# ============================================================
# GLOBAL UI PATCH — stable downloads
# Prevent download buttons from rerunning Streamlit and collapsing
# the currently open research tab. Falls back cleanly on older
# Streamlit versions that do not support on_click="ignore".
# ============================================================
_ST_DOWNLOAD_BUTTON_ORIGINAL = st.download_button

def _stable_download_button(*args, **kwargs):
    kwargs.setdefault("on_click", "ignore")
    try:
        return _ST_DOWNLOAD_BUTTON_ORIGINAL(*args, **kwargs)
    except TypeError as e:
        # Backward compatibility only. Current Streamlit should take
        # on_click="ignore"; older versions may not expose on_click.
        if "on_click" in kwargs:
            kwargs = dict(kwargs)
            kwargs.pop("on_click", None)
            return _ST_DOWNLOAD_BUTTON_ORIGINAL(*args, **kwargs)
        raise

st.download_button = _stable_download_button
