def get_full_history_monthly():
    """
    Heavy, shared full-history calculation.
    Yahoo adjusted prices + the app's own seven-model rules.
    No Portfolio Visualizer monthly-return data is used.
    Cached for 24 hours.
    """
    start = "2004-01-01"
    end = (
        pd.Timestamp.now(tz="Asia/Tokyo").normalize() + pd.Timedelta(days=1)
    ).strftime("%Y-%m-%d")

    px_full = get_close(FULL_HISTORY_TICKERS, start, end)
    rf_full = get_self_backtest_rf(start, end)

    bt_full, _ = run_backtest_detailed(
        px_full,
        rf_full,
        logic_version="v3.7-full-history-mom11-ex1-rfA",
    )

    periods = bt_full.index.to_period("M")
    monthly = (
        (1.0 + bt_full[["Frozen Core", "SPY"]])
        .groupby(periods)
        .prod()
        .sub(1.0)
    )

    # Benchmark TQQQ: actual adjusted-price monthly return, aligned to the
    # same daily backtest calendar. TQQQ begins later than SPY, so analyses
    # using TQQQ naturally start at the first complete available window.
    tqqq_daily = px_full["TQQQ"].pct_change(fill_method=None).reindex(bt_full.index)
    monthly["TQQQ"] = (
        (1.0 + tqqq_daily)
        .groupby(periods)
        .prod(min_count=1)
        .sub(1.0)
    )
    month_last = bt_full.groupby(periods).apply(lambda g: g.index[-1])
    monthly["Data through"] = pd.DatetimeIndex(month_last.values)
    monthly.index = monthly.index.astype(str)
    return monthly


def full_history_stats(monthly, asof):
    """Statistics use all completed months in the full self-calculated history."""
    x = monthly.copy()
    current_period = pd.Timestamp(asof).to_period("M")

    if len(x) and pd.Period(x.index[-1], freq="M") == current_period:
        completed = x.iloc[:-1].copy()
    else:
        completed = x.copy()

    if completed.empty:
        return None

    fc = completed["Frozen Core"].astype(float)
    best_month = fc.idxmax()
    worst_month = fc.idxmin()

    return {
        "first_month": completed.index[0],
        "last_month": completed.index[-1],
        "months": len(completed),
        "avg_month": fc.mean(),
        "pos_rate": (fc > 0).mean(),
        "best_month": best_month,
        "best_return": float(fc.loc[best_month]),
        "worst_month": worst_month,
        "worst_return": float(fc.loc[worst_month]),
    }


