def _max_consecutive_losses(r):
    best = cur = 0
    for x in r:
        if pd.notna(x) and x < 0:
            cur += 1; best = max(best, cur)
        else: cur = 0
    return best


def _risk_metrics(r, spy):
    import numpy as np
    df=pd.concat([r.rename('fc'),spy.rename('spy')],axis=1).dropna()
    fc,bm=df.fc.astype(float),df.spy.astype(float); n=len(fc); years=n/12
    cagr=(float((1+fc).prod())**(1/years)-1) if years>0 else float('nan')
    vol=float(fc.std(ddof=1)*np.sqrt(12))
    sharpe=float(fc.mean()/fc.std(ddof=1)*np.sqrt(12)) if fc.std(ddof=1)>0 else float('nan')
    downside=np.minimum(fc.to_numpy(),0); ddev=float(np.sqrt(np.mean(downside**2))*np.sqrt(12))
    sortino=float(fc.mean()*12/ddev) if ddev>0 else float('nan')
    wealth=(1+fc).cumprod(); peak=wealth.cummax(); dd=wealth/peak-1; maxdd=float(dd.min())
    calmar=cagr/abs(maxdd) if maxdd<0 else float('nan')
    uw=dd < -1e-12; cur=mx=0
    for z in uw:
        cur=cur+1 if z else 0; mx=max(mx,cur)
    nh=float((wealth>=peak*(1-1e-12)).mean())
    pidx=pd.PeriodIndex(fc.index,freq='M'); tmp=pd.DataFrame({'r':fc,'year':pidx.year})
    ann=tmp.groupby('year').r.apply(lambda x:(1+x).prod()-1); counts=tmp.groupby('year').size(); ann=ann[counts==12]
    worst_year=float(ann.min()) if len(ann) else float('nan')
    gains,losses=fc[fc>0],fc[fc<0]; gl=float(gains.mean()/abs(losses.mean())) if len(gains) and len(losses) else float('nan')
    corr=float(fc.corr(bm)); var=float(bm.var(ddof=1)); beta=float(fc.cov(bm)/var) if var>0 else float('nan')
    alpha_m=float(fc.mean()-beta*bm.mean()); alpha=(1+alpha_m)**12-1 if alpha_m>-1 else float('nan')
    active=fc-bm; te=float(active.std(ddof=1)*np.sqrt(12)); ir=float(active.mean()/active.std(ddof=1)*np.sqrt(12)) if active.std(ddof=1)>0 else float('nan')
    consec=0; run=0
    for x in fc:
        run=run+1 if x<0 else 0; consec=max(consec,run)
    return dict(cagr=cagr,vol=vol,sharpe=sharpe,sortino=sortino,maxdd=maxdd,calmar=calmar,worst_year=worst_year,
                positive=float((fc>0).mean()),gain_loss=gl,consecutive=consec,new_high=nh,underwater=mx,
                corr=corr,beta=beta,alpha=alpha,ir=ir,active=float(active.mean()*12),te=te,skew=float(fc.skew()))


def _market_regimes(monthly):
    import numpy as np
    d=monthly[['Frozen Core','SPY']].dropna().copy()
    d['Market']=np.where(d['SPY']>.02,'Up',np.where(d['SPY']<-.02,'Down','Sideways'))
    rows=[]
    for name in ['Up','Sideways','Down']:
        x=d[d.Market==name]; wins=int((x['Frozen Core']>x['SPY']).sum())
        rows.append([name,len(x),x['Frozen Core'].mean() if len(x) else np.nan,x['SPY'].mean() if len(x) else np.nan,wins,wins/len(x) if len(x) else np.nan])
    return pd.DataFrame(rows,columns=['Market','Months','Frozen Core avg','SPY avg','FC wins','Win rate'])



def _underwater_metrics(monthly_return):
    """
    Month-end drawdown episode statistics.

    Drawdown Length:
      peak month -> trough month
    Recovery Time:
      trough month -> first month that regains/exceeds the prior peak
    Underwater Period:
      peak month -> recovery month
    Avg Underwater Period:
      mean completed underwater episodes; ongoing episode excluded
    PTU:
      percentage of observed month-end points below the running high-water mark.
    """
    r = pd.Series(monthly_return).dropna().astype(float)
    if r.empty:
        return {
            "Max Drawdown Length": np.nan,
            "Max Recovery Time": np.nan,
            "Max Underwater Period": np.nan,
            "Avg Underwater Period": np.nan,
            "PTU": np.nan,
            "Completed Episodes": 0,
            "Ongoing": False,
        }

    wealth = (1.0 + r).cumprod()
    hwm = wealth.cummax()
    underwater = wealth < (hwm - 1e-12)
    ptu = float(underwater.mean())

    episodes = []
    ongoing = None
    i = 0
    n = len(wealth)

    while i < n:
        if not bool(underwater.iloc[i]):
            i += 1
            continue

        # Last high-water-mark observation immediately before this underwater run.
        peak_pos = max(i - 1, 0)

        # Continue until first recovered/new-high observation.
        j = i
        while j < n and bool(underwater.iloc[j]):
            j += 1

        end_underwater_pos = j - 1
        trough_slice = wealth.iloc[i:j]
        trough_pos = int(wealth.index.get_loc(trough_slice.idxmin()))

        if j < n:
            recovery_pos = j
            episodes.append({
                "peak_pos": peak_pos,
                "trough_pos": trough_pos,
                "recovery_pos": recovery_pos,
                "drawdown_length": trough_pos - peak_pos,
                "recovery_time": recovery_pos - trough_pos,
                "underwater_period": recovery_pos - peak_pos,
            })
        else:
            ongoing = {
                "peak_pos": peak_pos,
                "trough_pos": trough_pos,
                "last_pos": end_underwater_pos,
                "drawdown_length": trough_pos - peak_pos,
                "elapsed_underwater": end_underwater_pos - peak_pos,
            }
        i = j

    completed = len(episodes)
    dd_lengths = [e["drawdown_length"] for e in episodes]
    recovery_times = [e["recovery_time"] for e in episodes]
    uw_periods = [e["underwater_period"] for e in episodes]

    # Drawdown length can still be measured for an ongoing episode up to its trough.
    if ongoing is not None:
        dd_lengths_all = dd_lengths + [ongoing["drawdown_length"]]
    else:
        dd_lengths_all = dd_lengths

    return {
        "Max Drawdown Length": max(dd_lengths_all) if dd_lengths_all else 0,
        "Max Recovery Time": max(recovery_times) if recovery_times else 0,
        "Max Underwater Period": max(uw_periods) if uw_periods else (
            ongoing["elapsed_underwater"] if ongoing else 0
        ),
        "Avg Underwater Period": float(np.mean(uw_periods)) if uw_periods else np.nan,
        "PTU": ptu,
        "Completed Episodes": completed,
        "Ongoing": ongoing is not None,
        "Ongoing Underwater": ongoing["elapsed_underwater"] if ongoing else 0,
    }


def render_underwater_metrics(monthly):
    st.markdown("### Drawdown / Underwater")
    st.caption(
        "月末ベース。Drawdown Length＝直前高値→ボトム、Recovery Time＝ボトム→高値回復、"
        "Underwater Period＝直前高値→高値回復。Avg Underwaterは完了済みDDのみ（進行中は除外）。"
        "PTU＝月末時点で過去最高値を下回っていた割合。基本ベンチマークはSPY。"
    )

    fc = _underwater_metrics(monthly["Frozen Core"])
    spy = _underwater_metrics(monthly["SPY"])

    rows = [
        ("Max Drawdown Length", fc["Max Drawdown Length"], spy["Max Drawdown Length"], "months"),
        ("Max Recovery Time", fc["Max Recovery Time"], spy["Max Recovery Time"], "months"),
        ("Max Underwater Period", fc["Max Underwater Period"], spy["Max Underwater Period"], "months"),
        ("Avg Underwater Period", fc["Avg Underwater Period"], spy["Avg Underwater Period"], "months"),
        ("PTU", fc["PTU"], spy["PTU"], "pct"),
    ]

    for label, fcv, spyv, kind in rows:
        c1, c2 = st.columns(2)
        if kind == "pct":
            c1.metric(f"{label} · Frozen Core", f"{fcv*100:.1f}%")
            c2.metric(f"{label} · SPY", f"{spyv*100:.1f}%")
        else:
            fct = "—" if pd.isna(fcv) else f"{fcv:.1f} months" if label == "Avg Underwater Period" else f"{int(fcv)} months"
            spt = "—" if pd.isna(spyv) else f"{spyv:.1f} months" if label == "Avg Underwater Period" else f"{int(spyv)} months"
            c1.metric(f"{label} · Frozen Core", fct)
            c2.metric(f"{label} · SPY", spt)

    fc_note = f"{fc['Completed Episodes']} completed"
    spy_note = f"{spy['Completed Episodes']} completed"
    if fc["Ongoing"]:
        fc_note += f" + 1 ongoing ({fc['Ongoing Underwater']} months underwater)"
    if spy["Ongoing"]:
        spy_note += f" + 1 ongoing ({spy['Ongoing Underwater']} months underwater)"

    st.caption(
        f"Frozen Core: {fc_note} ｜ SPY: {spy_note} ｜ "
        "Avg Underwater Period は ongoing drawdown を平均から除外"
    )




def _normal_cdf(x):
    return 0.5 * (1.0 + math.erf(float(x) / math.sqrt(2.0)))

def _betacf(a, b, x, max_iter=200, eps=3e-14):
    fpmin = 1e-300
    qab, qap, qam = a+b, a+1.0, a-1.0
    c = 1.0
    d = 1.0 - qab*x/qap
    if abs(d) < fpmin: d = fpmin
    d = 1.0/d
    h = d
    for m in range(1, max_iter+1):
        m2 = 2*m
        aa = m*(b-m)*x/((qam+m2)*(a+m2))
        d = 1.0 + aa*d
        if abs(d) < fpmin: d = fpmin
        c = 1.0 + aa/c
        if abs(c) < fpmin: c = fpmin
        d = 1.0/d
        h *= d*c
        aa = -(a+m)*(qab+m)*x/((a+m2)*(qap+m2))
        d = 1.0 + aa*d
        if abs(d) < fpmin: d = fpmin
        c = 1.0 + aa/c
        if abs(c) < fpmin: c = fpmin
        d = 1.0/d
        delta = d*c
        h *= delta
        if abs(delta-1.0) < eps:
            break
    return h

def _regularized_beta(x, a, b):
    if x <= 0.0: return 0.0
    if x >= 1.0: return 1.0
    ln_bt = math.lgamma(a+b)-math.lgamma(a)-math.lgamma(b)+a*math.log(x)+b*math.log1p(-x)
    bt = math.exp(ln_bt)
    if x < (a+1.0)/(a+b+2.0):
        return bt*_betacf(a,b,x)/a
    return 1.0 - bt*_betacf(b,a,1.0-x)/b

def _student_t_sf(t_value, df):
    t_value, df = float(t_value), float(df)
    if not math.isfinite(t_value):
        return 0.0 if t_value > 0 else 1.0
    if df <= 0:
        return float("nan")
    x = df/(df+t_value*t_value)
    ib = _regularized_beta(x, df/2.0, 0.5)
    return 0.5*ib if t_value >= 0 else 1.0-0.5*ib

def _winsorize_series(x, q=0.01):
    x = pd.Series(x).dropna().astype(float)
    if len(x) < 3:
        return x
    lo, hi = x.quantile(q), x.quantile(1.0 - q)
    return x.clip(lower=lo, upper=hi)

def _nw_mean_variance(x, lag=None):
    x = np.asarray(pd.Series(x).dropna(), dtype=float)
    n = len(x)
    if n < 2:
        return np.nan
    if lag is None:
        lag = int(np.floor(4.0 * (n / 100.0) ** (2.0 / 9.0)))
    lag = max(0, min(int(lag), n - 1))
    u = x - x.mean()
    lrv = float(np.dot(u, u) / n)
    for k in range(1, lag + 1):
        gamma = float(np.dot(u[k:], u[:-k]) / n)
        lrv += 2.0 * (1.0 - k / (lag + 1.0)) * gamma
    return max(lrv, 0.0) / n

def _p_deterioration(monthly_return, recent_months, long_max=120, long_min=60, winsor_q=0.01, delta=0.0):
    r = pd.Series(monthly_return).dropna().astype(float)
    if len(r) < recent_months + long_min:
        return None
    recent = r.iloc[-recent_months:]
    long_end = len(r) - recent_months
    long = r.iloc[max(0, long_end-long_max):long_end]
    if len(long) < long_min:
        return None
    rw, lw = _winsorize_series(recent, winsor_q), _winsorize_series(long, winsor_q)
    vr, vl = _nw_mean_variance(rw), _nw_mean_variance(lw)
    se = math.sqrt(vr + vl)
    d = float(rw.mean() - lw.mean())
    z = (d + delta) / se if se > 0 else (np.inf if d + delta > 0 else -np.inf)
    return {"pdet": float(_normal_cdf(-z)), "recent_mean": float(rw.mean()), "long_mean": float(lw.mean())}

def _p_erosion(monthly_return, recent_months, warmup=12, anchor_months=84, long_max=120, long_min=60, winsor_q=0.01, gamma=0.25):
    r = pd.Series(monthly_return).dropna().astype(float)
    if len(r) < max(warmup+anchor_months, recent_months+long_min):
        return None
    anchor_s = r.iloc[warmup:warmup+anchor_months]
    long_end = len(r)-recent_months
    long_s = r.iloc[max(0,long_end-long_max):long_end]
    if len(anchor_s) < anchor_months or len(long_s) < long_min:
        return None
    aw, lw = _winsorize_series(anchor_s, winsor_q), _winsorize_series(long_s, winsor_q)
    tol = gamma * float(aw.std(ddof=1))
    se = math.sqrt(_nw_mean_variance(aw) + _nw_mean_variance(lw))
    deterioration = float(aw.mean() - lw.mean())
    z = (deterioration - tol) / se if se > 0 else (np.inf if deterioration > tol else -np.inf)
    return {"perosion": float(_normal_cdf(z)), "anchor_mean": float(aw.mean()), "current_long_mean": float(lw.mean())}

def _one_sided_mean_pvalue(x):
    x = pd.Series(x).dropna().astype(float)
    if len(x) < 2: return np.nan, np.nan, float(x.mean()) if len(x) else np.nan
    mu = float(x.mean())
    if mu < 0: return 1.0, np.nan, mu
    sd = float(x.std(ddof=1))
    if sd <= 0: return (0.0 if mu > 0 else 0.5), np.nan, mu
    tstat = mu / (sd / math.sqrt(len(x)))
    return float(_student_t_sf(tstat, len(x)-1)), float(tstat), mu

def _pbar_consistency(series, n_splits):
    r = pd.Series(series).dropna().astype(float)
    rows = []
    for i, idx in enumerate(np.array_split(np.arange(len(r)), int(n_splits)), 1):
        x = r.iloc[idx]
        p, ts, mu = _one_sided_mean_pvalue(x)
        rows.append({"Period":i,"Start":x.index[0],"End":x.index[-1],"Months":len(x),"Mean":mu,"t-stat":ts,"p":p})
    return float(np.mean([x["p"] for x in rows])), pd.DataFrame(rows)

def _pbar_label(p):
    if p <= .03: return "Strong"
    if p <= .10: return "Moderate"
    return "Not significant"

def _health_level(pdets, erosions):
    if not pdets or not erosions: return "⚪ INSUFFICIENT DATA"
    if sum(x >= .80 for x in pdets) >= 2 and max(erosions) >= .80: return "🔴 REVIEW"
    if sum(x >= .70 for x in pdets) >= 2 or max(erosions) >= .70: return "🟡 WATCH"
    return "🟢 HEALTHY"

def render_strategy_health_monitor(monthly):
    st.markdown("## Strategy Health Monitor")
    st.caption("診断専用。売買シグナル・配分は変更しません。P(det)=直近弱体化、p_erosion=長期侵食、p̄=期間横断的一貫性。")
    fc = pd.Series(monthly["Frozen Core"]).dropna().astype(float)
    spy = pd.Series(monthly["SPY"]).reindex(fc.index).astype(float)
    active = (fc-spy).dropna()
    windows=(6,12,24)
    ds=[_p_deterioration(fc,w) for w in windows]
    es=[_p_erosion(fc,w) for w in windows]
    st.markdown("### "+_health_level([d["pdet"] for d in ds if d],[e["perosion"] for e in es if e]))
    st.markdown("#### Current deterioration")
    for col,w,d in zip(st.columns(3),windows,ds):
        if d: col.metric(f"P(det) · {w}M",f"{d['pdet']*100:.1f}%",f"Recent {d['recent_mean']*100:+.2f}%/mo vs Long {d['long_mean']*100:+.2f}%/mo")
        else: col.metric(f"P(det) · {w}M","—")
    st.markdown("#### Long-term erosion")
    for col,w,e in zip(st.columns(3),windows,es):
        if e: col.metric(f"p_erosion · {w}M",f"{e['perosion']*100:.3f}%",f"Long {e['current_long_mean']*100:+.2f}%/mo vs Anchor {e['anchor_mean']*100:+.2f}%/mo")
        else: col.metric(f"p_erosion · {w}M","—")
    st.caption("Erosion: warm-up 12M / fixed anchor 84M / rolling long max 120M / 1% Winsorize / Newey-West HAC / γ=0.25×anchor σ。")
    rows=[]; details={}
    for n in (3,5,10):
        pa,da=_pbar_consistency(fc,n); pr,dr=_pbar_consistency(active,n)
        rows.append({"Split":f"{n}-split"+(" · Primary" if n==5 else ""),"FC > 0 p̄":f"{pa:.4f}","FC > 0":_pbar_label(pa),"FC > SPY p̄":f"{pr:.4f}","FC > SPY":_pbar_label(pr)})
        details[n]=(da,dr)
    st.markdown("#### Historical consistency · p̄")
    st.dataframe(pd.DataFrame(rows),use_container_width=True,hide_index=True)
    st.caption("記事の実務基準: p̄≤0.03 Strong / 0.03–0.10 Moderate / >0.10 Not significant。3/5/10分割を併記。")
    with st.expander("5-split の内訳"):
        a,r=details[5]
        d=a.copy()
        d=d.rename(columns={"Mean":"FC mean","t-stat":"FC t","p":"FC p"})
        d["FC-SPY mean"]=r["Mean"].values; d["FC-SPY t"]=r["t-stat"].values; d["FC-SPY p"]=r["p"].values
        st.dataframe(d,use_container_width=True,hide_index=True)
    st.info("Health Monitorは再検証の必要性を知らせる診断です。WATCH/REVIEWでも自動売却・自動配分変更はしません。")


