            missing = [x for x in needed if x not in closes.columns]
            if missing:
                extra = get_close(tuple(missing), start, end)
                closes = closes.join(extra, how="outer").sort_index().ffill()

            opens = get_open(tuple(needed), start, end)

            idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
            closes = closes.reindex(idx).ffill()
            opens = opens.reindex(idx).ffill()

            # Build heavy components once.
            core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)
            safe2, _, audit = _safe_haven_multi_selector(closes.assign(XLU=closes["GLD"]))
            safe2 = safe2.reindex(idx).ffill()
            asset_returns = opens.pct_change(fill_method=None)

            vix_h = _apply_safe_haven_to_models(
                core_h, safe2, ["Old VIX 15d", "Old VIX 20d", "New VIX 20d"]
            )
            all_h = _apply_safe_haven_to_models(
                core_h, safe2, list(MODEL_WEIGHTS.keys())
            )

            daily = pd.DataFrame({
                "Frozen Core": _portfolio_return_from_holdings_fast(core_h, asset_returns),
                "VIX-only": _portfolio_return_from_holdings_fast(vix_h, asset_returns),
                "ALL": _portfolio_return_from_holdings_fast(all_h, asset_returns),
            })

            dev_end = pd.Timestamp("2026-07-31")
