def _comparison_drawdown(r):
    eq = (1.0 + r.fillna(0.0)).cumprod()
    return eq / eq.cummax() - 1.0


def _annual_compound_returns(r):
    s = r.dropna().copy()
    if s.empty:
        return pd.Series(dtype=float)
    return (1.0 + s).groupby(s.index.year).prod() - 1.0


