# =============================================================================
# v3.25 — MOM leverage ladder on top of Frozen Adaptive ALL
# Pre-fixed ladder only:
#   Base: QQQ-MOM->QQQ,  QLD-MOM->QLD
#   L1:   QQQ-MOM->QLD,  QLD-MOM->QLD
#   L2:   QQQ-MOM->QLD,  QLD-MOM->TQQQ
#   L3:   QQQ-MOM->TQQQ, QLD-MOM->TQQQ
# IMPORTANT: only replace the RISK-ON QQQ/QLD holdings of the two MOM sleeves.
# Defensive LQD / GLD-TLT holdings and all MR/VIX sleeves are unchanged.
# =============================================================================

def _v325_annual_sortino(r):
    x = r.dropna()
    if len(x) < 2:
        return np.nan
    downside = x[x < 0]
    if len(downside) < 2:
        return np.nan
    dd = downside.std(ddof=1) * np.sqrt(252)
    return np.nan if dd == 0 else (x.mean() * 252) / dd


def _v325_metric_row(name, r):
    x = r.dropna()
    eq = (1.0 + x).cumprod()
    years = (x.index[-1] - x.index[0]).days / 365.2425
    cagr = eq.iloc[-1] ** (1.0 / years) - 1.0
    vol = x.std(ddof=1) * np.sqrt(252)
    sharpe = (x.mean() * 252) / vol if vol > 0 else np.nan
    sortino = _v325_annual_sortino(x)
    dmax = (eq / eq.cummax() - 1.0).min()
    m = (1.0 + x).resample("ME").prod() - 1.0
    meq = (1.0 + m).cumprod()
    mmax = (meq / meq.cummax() - 1.0).min()
    return {
        "Variant": name, "CAGR": cagr, "Vol": vol, "Daily MaxDD": dmax,
        "Monthly MaxDD": mmax, "Sharpe0": sharpe, "Sortino0": sortino
    }


def _v325_replace_mom_riskon(base_h, variant):
    h = base_h.copy()
    if variant == "L1 QLD+QLD":
        h.loc[h["QQQ-MOM"].eq("QQQ"), "QQQ-MOM"] = "QLD"
    elif variant == "L2 QLD+TQQQ":
        h.loc[h["QQQ-MOM"].eq("QQQ"), "QQQ-MOM"] = "QLD"
        h.loc[h["QLD-MOM"].eq("QLD"), "QLD-MOM"] = "TQQQ"
    elif variant == "L3 TQQQ+TQQQ":
        h.loc[h["QQQ-MOM"].eq("QQQ"), "QQQ-MOM"] = "TQQQ"
        h.loc[h["QLD-MOM"].eq("QLD"), "QLD-MOM"] = "TQQQ"
    return h



# =============================================================================
# v3.26 — Fixed bond-regime gated L2 challengers
#
# No parameter sweep. Three pre-fixed gates only:
#   A: TLT 3M total return > 0
#   B: LQD 3M total return > 0
#   C: BOTH TLT 3M > 0 AND LQD 3M > 0
#
# Base = Frozen Adaptive ALL.
# Upper-bound control = Always L2 (QQQ-MOM risk-on QQQ->QLD;
#                                 QLD-MOM risk-on QLD->TQQQ).
# The gate only decides whether the L2 MOM risk-on replacement is active.
# All defensive MOM holdings and every MR/VIX sleeve are unchanged.
# Signals are prior month-end adjusted-close total returns; effective next
# tradable day, matching the existing research calendar convention.
# =============================================================================

def _v326_effective_monthly_signal(signal_by_period, idx, name):
    idx = pd.DatetimeIndex(idx).sort_values()
    if len(idx) == 0:
        return pd.Series(dtype=bool, name=name)

    # Actual last tradable date for each calendar month.
    tmp = pd.Series(idx, index=idx.to_period("M"))
    last_trade = tmp.groupby(level=0).max()

    pairs = []
    for p, val in signal_by_period.dropna().items():
        if p not in last_trade.index:
            continue
        d = pd.Timestamp(last_trade.loc[p])
        pos = idx.searchsorted(d, side="right")
        if pos < len(idx):
            pairs.append((idx[pos], bool(val)))

    if not pairs:
        return pd.Series(False, index=idx, name=name)

    s = pd.Series(
        [v for _, v in pairs],
        index=pd.DatetimeIndex([d for d, _ in pairs]),
        dtype=bool,
        name=name,
    )
    return s[~s.index.duplicated(keep="last")].sort_index().reindex(idx).ffill().fillna(False)


@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def _v326_bond_regime_signals(closes, idx):
    m = closes[["TLT", "LQD"]].resample("ME").last()
    mom3 = m / m.shift(3) - 1.0
    mom3.index = mom3.index.to_period("M")

    raw = {
        "A TLT3M>0": mom3["TLT"] > 0,
        "B LQD3M>0": mom3["LQD"] > 0,
        "C BOTH>0": (mom3["TLT"] > 0) & (mom3["LQD"] > 0),
    }
    out = {
        k: _v326_effective_monthly_signal(v, idx, k)
        for k, v in raw.items()
    }
    audit = pd.DataFrame({
        "Month": mom3.index.astype(str),
        "TLT 3M": mom3["TLT"].values,
        "LQD 3M": mom3["LQD"].values,
        "A TLT3M>0": raw["A TLT3M>0"].values,
        "B LQD3M>0": raw["B LQD3M>0"].values,
        "C BOTH>0": raw["C BOTH>0"].values,
    })
    return out, audit


@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def _v326_apply_l2_gate(base_h, gate):
    h = base_h.copy()
    g = gate.reindex(h.index).fillna(False).astype(bool)

    m1 = g & h["QQQ-MOM"].eq("QQQ")
    m2 = g & h["QLD-MOM"].eq("QLD")
    h.loc[m1, "QQQ-MOM"] = "QLD"
    h.loc[m2, "QLD-MOM"] = "TQQQ"
    return h


def _v326_cpcv_summary(monthly, base_col, challenger_cols):
    from itertools import combinations
    m = monthly.dropna().copy()
    if len(m) < 32:
        return pd.DataFrame(), pd.DataFrame()

    pos_groups = np.array_split(np.arange(len(m)), 8)
    group_rows = []
    for i, pos in enumerate(pos_groups, start=1):
        group_rows.append({
            "Group": i,
            "Start": str(pd.Timestamp(m.index[pos[0]].start_time if isinstance(m.index[pos[0]], pd.Period) else m.index[pos[0]]).date()),
            "End": str(pd.Timestamp(m.index[pos[-1]].end_time if isinstance(m.index[pos[-1]], pd.Period) else m.index[pos[-1]]).date()),
            "Months": len(pos),
        })

    rows = []
    for g1, g2 in combinations(range(8), 2):
        pos = np.concatenate([pos_groups[g1], pos_groups[g2]])
        x = m.iloc[np.sort(pos)]
        base = x[base_col]
        for c in challenger_cols:
            ch = x[c]
            ds = _monthly_sortino0(ch) - _monthly_sortino0(base)
            dsh = _monthly_sharpe0(ch) - _monthly_sharpe0(base)
            active = (ch - base).mean() * 12.0
            rows.append({
                "Variant": c,
                "Group1": g1 + 1,
                "Group2": g2 + 1,
                "Months": len(x),
                "Delta Sortino0": ds,
                "Delta Sharpe0": dsh,
                "Active AnnArithmetic": active,
                "Positive Delta Sortino": ds > 0,
                "Positive Delta Sharpe": dsh > 0,
                "Positive Active": active > 0,
            })
    return pd.DataFrame(rows), pd.DataFrame(group_rows)


def _v326_rolling_p10_table(daily, variants):
    rows = []
    for h in ("1Y","2Y","3Y","5Y","7Y","10Y"):
        row = {"Horizon": h}
        for v in variants:
            row[v] = _rolling_p10_monthly(daily[v]).get(h, np.nan)
        rows.append(row)
    return pd.DataFrame(rows)


