def _v327_drawdown_episodes(r, top_n=10):
    r = r.dropna().copy()
    w = (1.0 + r).cumprod()
    peak = w.cummax()
    dd = w / peak - 1.0

    episodes = []
    in_dd = False
    peak_date = w.index[0]
    trough_date = w.index[0]
    trough_dd = 0.0

    for dt in w.index:
        if dd.loc[dt] < -1e-12:
            if not in_dd:
                in_dd = True
                pos = w.index.get_loc(dt)
                peak_date = w.index[max(0, pos - 1)]
                trough_date = dt
                trough_dd = dd.loc[dt]
            if dd.loc[dt] < trough_dd:
                trough_dd = dd.loc[dt]
                trough_date = dt
        else:
            if in_dd:
                episodes.append({
                    "Peak": peak_date,
                    "Trough": trough_date,
                    "Recovery": dt,
                    "MaxDD": trough_dd,
                    "Days Peak→Trough": (trough_date - peak_date).days,
                    "Days Trough→Recovery": (dt - trough_date).days,
                })
                in_dd = False

    if in_dd:
        episodes.append({
            "Peak": peak_date,
            "Trough": trough_date,
            "Recovery": pd.NaT,
            "MaxDD": trough_dd,
            "Days Peak→Trough": (trough_date - peak_date).days,
            "Days Trough→Recovery": np.nan,
        })

    return pd.DataFrame(episodes).sort_values("MaxDD").head(top_n).reset_index(drop=True)


