# =============================================================================
# v3.28 — Trend weakness vs correlation stress
# Diagnostic only. NO threshold optimization and NO trading rule yet.
#
# Fixed diagnostics:
#   Trend:
#     QQQ 20d return, SPY 20d return
#     QQQ/SPY distance from SMA200
#     VIX level and 20d change
#     LQD 20d return
#
#   Correlation:
#     20d mean pairwise correlation of risk basket [QQQ, SPY, XLU, LQD]
#     20d mean absolute pairwise correlation of cross-asset basket
#       [QQQ, LQD, TLT, GLD, XLU]
#
# Evaluated around A's Worst-10 DD episodes:
#   5 trading days before peak, peak, +5d, +10d, trough.
# =============================================================================

def _v328_mean_pair_corr(ret_df, window=20, absolute=False):
    cols = list(ret_df.columns)
    pair_series = []
    for i in range(len(cols)):
        for j in range(i+1, len(cols)):
            c = ret_df[cols[i]].rolling(window).corr(ret_df[cols[j]])
            if absolute:
                c = c.abs()
            pair_series.append(c)
    if not pair_series:
        return pd.Series(index=ret_df.index, dtype=float)
    return pd.concat(pair_series, axis=1).mean(axis=1)


def _v328_diag_features(closes):
    r = closes.pct_change(fill_method=None)
    d = pd.DataFrame(index=closes.index)

    d["QQQ_ret20"] = closes["QQQ"] / closes["QQQ"].shift(20) - 1.0
    d["SPY_ret20"] = closes["SPY"] / closes["SPY"].shift(20) - 1.0
    d["LQD_ret20"] = closes["LQD"] / closes["LQD"].shift(20) - 1.0

    d["QQQ_vs_SMA200"] = closes["QQQ"] / closes["QQQ"].rolling(200).mean() - 1.0
    d["SPY_vs_SMA200"] = closes["SPY"] / closes["SPY"].rolling(200).mean() - 1.0

    d["VIX_level"] = closes["^VIX"]
    d["VIX_chg20"] = closes["^VIX"] / closes["^VIX"].shift(20) - 1.0

    risk_cols = ["QQQ","SPY","XLU","LQD"]
    cross_cols = ["QQQ","LQD","TLT","GLD","XLU"]

    d["RiskCorr20"] = _v328_mean_pair_corr(r[risk_cols], 20, absolute=False)
    d["CrossAssetAbsCorr20"] = _v328_mean_pair_corr(r[cross_cols], 20, absolute=True)

    # A few transparent pairwise references; no rule fitting.
    d["Corr20_QQQ_LQD"] = r["QQQ"].rolling(20).corr(r["LQD"])
    d["Corr20_QQQ_TLT"] = r["QQQ"].rolling(20).corr(r["TLT"])
    d["Corr20_QQQ_GLD"] = r["QQQ"].rolling(20).corr(r["GLD"])

    return d


def _v328_shift_date(idx, dt, n):
    idx = pd.DatetimeIndex(idx)
    pos = idx.searchsorted(pd.Timestamp(dt))
    pos = min(max(pos + n, 0), len(idx)-1)
    return idx[pos]


