            cshow = covid.copy().astype(object)
            ccol = cshow.columns[0]
            cshow[ccol] = covid[ccol].map(lambda x: f"{x*100:+.2f}%").astype(object)
            st.markdown("#### 7) COVID Peak→Trough")
            st.dataframe(cshow, use_container_width=True)

            # Brake state around COVID
            ca = brake_audit.loc["2020-02-10":"2020-03-31"].copy()
