# v3.34 — Target TQQQ vs TECL Allocation Autopsy
#
# Diagnostic only. No trading rule, no threshold sweep, no allocation optimizer.
# Development target history frozen through 2026-07.
#
# Questions:
#   1) Within Aggressive months, what distinguishes TQQQ-heavy vs TECL-heavy?
#   2) Are relative-strength features visible at PRIOR month-end?
#   3) Is the direction stable across 2013-17 / 2018-21 / 2022-26?
#   4) Do pure TQQQ, pure TECL and mixed months show persistent structure?
#
# Fixed prior-month features:
#   XLK-QQQ relative momentum: 1M / 3M / 6M / 12M
#   XLK vs QQQ SMA200 distance spread
#   XLK 1M-3M inflection minus QQQ 1M-3M inflection
#   XLK 3M-12M inflection minus QQQ 3M-12M inflection
#   QQQ / XLK own momentum & SMA200 distance for context
# =============================================================================

def _v334_pairwise_auc(a, b):
    a = pd.Series(a).dropna().to_numpy()
    b = pd.Series(b).dropna().to_numpy()
    if len(a) < 2 or len(b) < 2:
        return np.nan
    return (
        np.greater.outer(a, b).sum()
        + 0.5 * np.equal.outer(a, b).sum()
    ) / (len(a) * len(b))


def _v334_target_alloc_features(target, feat):
    x = target.copy()
    x = x[x["Month"] <= pd.Period("2026-07", "M")].copy()

    # Aggressive allocation composition.
    ag = x["AggressiveWt"] > 0
    x = x[ag].copy()
    denom = x["TQQQ"].fillna(0) + x["TECL"].fillna(0)
    x["TQQQShareAgg"] = np.where(denom > 0, x["TQQQ"].fillna(0) / denom, np.nan)
    x["TECLShareAgg"] = np.where(denom > 0, x["TECL"].fillna(0) / denom, np.nan)

    def alloc_class(r):
        tq, te = float(r["TQQQ"]), float(r["TECL"])
        if tq >= 99.9 and te <= 0.1:
            return "Pure TQQQ"
        if te >= 99.9 and tq <= 0.1:
            return "Pure TECL"
        if tq > te:
            return "TQQQ-heavy Mix"
        if te > tq:
            return "TECL-heavy Mix"
        return "50/50 Mix"

    x["AttackAllocation"] = x.apply(alloc_class, axis=1)
    x = x.merge(feat.reset_index(names="Month"), on="Month", how="left")

    # Fixed relative-strength / relative-inflection features.
    for n in [1, 3, 6, 12]:
        q, k = f"QQQ_mom{n}", f"XLK_mom{n}"
        if q in x.columns and k in x.columns:
            x[f"XLK_minus_QQQ_{n}m"] = x[k] - x[q]

    if "XLK_vs_SMA200" in x and "QQQ_vs_SMA200" in x:
        x["XLK_minus_QQQ_SMA200"] = x["XLK_vs_SMA200"] - x["QQQ_vs_SMA200"]

    if all(c in x for c in ["XLK_mom1","XLK_mom3","QQQ_mom1","QQQ_mom3"]):
        x["RelInflect_1m3m"] = (
            (x["XLK_mom1"] - x["XLK_mom3"])
            - (x["QQQ_mom1"] - x["QQQ_mom3"])
        )

    if all(c in x for c in ["XLK_mom3","XLK_mom12","QQQ_mom3","QQQ_mom12"]):
        x["RelInflect_3m12m"] = (
            (x["XLK_mom3"] - x["XLK_mom12"])
            - (x["QQQ_mom3"] - x["QQQ_mom12"])
        )
    return x



# =============================================================================
# v3.35 — Attack Asset Challenger #1
#
# CONTROL
#   T2 from v3.33:
#   - A + VIX30
#   - same XLK inflection Turbo signal
#   - when Turbo active: 75% TQQQ + 25% proportional non-MOM portfolio
#
# CHALLENGER #1
#   Same Turbo signal. Same 75% attack weight. Same 25% non-MOM remainder.
#   ONLY attack asset changes:
#
#     if XLK 6M total return > QQQ 6M total return:
#         75% TECL
#     else:
#         75% TQQQ
#
# Natural zero boundary only. No threshold sweep. No allocation optimization.
# Prior month-end signal -> existing next-open execution convention.
# Development sample frozen through 2026-07.
# =============================================================================

@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def _v335_attack_selector_signal(closes, idx):
    me = closes[["XLK","QQQ"]].resample("ME").last()
    xlk6 = me["XLK"] / me["XLK"].shift(6) - 1.0
    qqq6 = me["QQQ"] / me["QQQ"].shift(6) - 1.0
    rel6 = xlk6 - qqq6
    choose_tecl = rel6 > 0

    raw = pd.DataFrame({
        "Month": rel6.index.to_period("M").astype(str),
        "XLK 6M": xlk6.values,
        "QQQ 6M": qqq6.values,
        "XLK-QQQ 6M": rel6.values,
        "Choose TECL": choose_tecl.values,
    })

    choose_tecl.index = choose_tecl.index.to_period("M")
    eff = _v326_effective_monthly_signal(
        choose_tecl, idx, "XLK 6M > QQQ 6M"
    )
    return eff, raw


@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def _v335_build_t2_and_attack_returns(control_ret, t1_ret, tqqq_ret, tecl_ret, turbo_active, choose_tecl):
    """
    T1 during Turbo = 50% TQQQ + 50% non-MOM.
    Therefore:
      non-MOM = 2*T1 - TQQQ

    T2 Control:
      75% TQQQ + 25% non-MOM
      = 0.5*TQQQ + 0.5*T1

    Attack Challenger:
      if TECL selected:
        75% TECL + 25% non-MOM
      else:
        same as T2 Control.
    """
    idx = control_ret.index
    turbo = turbo_active.reindex(idx).fillna(False).astype(bool)
    tecl_sel = choose_tecl.reindex(idx).fillna(False).astype(bool)

    tq = tqqq_ret.reindex(idx)
    te = tecl_ret.reindex(idx)
    t1 = t1_ret.reindex(idx)

    t2 = control_ret.copy()
    t2.loc[turbo] = 0.5 * tq.loc[turbo] + 0.5 * t1.loc[turbo]

    challenger = control_ret.copy()

    use_tqqq = turbo & ~tecl_sel
    use_tecl = turbo & tecl_sel

    challenger.loc[use_tqqq] = t2.loc[use_tqqq]

    # 25% non-MOM = 0.5*T1 - 0.25*TQQQ
    # 75% TECL + 25% non-MOM
    challenger.loc[use_tecl] = (
        0.75 * te.loc[use_tecl]
        + 0.5 * t1.loc[use_tecl]
        - 0.25 * tq.loc[use_tecl]
    )

    return t2, challenger



# =============================================================================
# v3.36b — Full Risk-Off Transition Autopsy
#
# TARGET ONLY / DIAGNOSTIC ONLY.
# No trading rule. No threshold sweep. No optimization.
# Target history frozen through 2026-07.
#
# Focus:
#   Aggressive -> Defensive transitions in the exact target history.
# Compare them with:
#   - Aggressive -> Aggressive continuation
#   - Defensive -> Aggressive recovery entries
#
# All features are observable at PRIOR month-end.
# Fixed feature families:
#   Equity trend / momentum
#   Momentum deterioration / inflection
#   Tech relative strength
#   Bonds / gold / utilities
#   VIX / correlation stress
# =============================================================================

def _v336_transition_autopsy(target, feat):
    x = target.copy()
    x = x[x["Month"] <= pd.Period("2026-07", "M")].copy()
    x = x.sort_values("Month").reset_index(drop=True)

    # v3.36b FIX:
    # _v330_normalize_target_table() does not guarantee a broad "State" column.
    # Reconstruct it deterministically from the exact target allocations.
    # This is the same broad-state definition used in the earlier target analysis:
    #   Aggressive = TQQQ/TECL 100%
    #   Defensive = XLU/GLD 100%
    #   Mixed      = anything between the two.
    if "State" not in x.columns:
        agg = x["AggressiveWt"].fillna(0.0)
        deff = x["DefensiveWt"].fillna(0.0)
        x["State"] = np.select(
            [
                (agg >= 0.999) & (deff <= 0.001),
                (deff >= 0.999) & (agg <= 0.001),
            ],
            ["Aggressive", "Defensive"],
            default="Mixed",
        )

    x["PrevState"] = x["State"].shift(1)
    x["Transition"] = x["PrevState"].astype(str) + " -> " + x["State"].astype(str)

    x = x.merge(feat.reset_index(names="Month"), on="Month", how="left")

    # Fixed deterioration / inflection features.
    pairs = [
        ("QQQ",1,3), ("QQQ",1,6), ("QQQ",3,6), ("QQQ",3,12),
        ("XLK",1,3), ("XLK",1,6), ("XLK",3,6), ("XLK",3,12),
    ]
    for a, s, l in pairs:
        cs, cl = f"{a}_mom{s}", f"{a}_mom{l}"
        if cs in x and cl in x:
            x[f"{a}_{s}m_minus_{l}m"] = x[cs] - x[cl]

    for n in [1,3,6,12]:
        q, k = f"QQQ_mom{n}", f"XLK_mom{n}"
        if q in x and k in x:
            x[f"XLK_minus_QQQ_{n}m"] = x[k] - x[q]

    if "XLK_vs_SMA200" in x and "QQQ_vs_SMA200" in x:
        x["XLK_minus_QQQ_SMA200"] = x["XLK_vs_SMA200"] - x["QQQ_vs_SMA200"]

    # Change in already prior-month-end observable features vs one month earlier.
    change_base = [c for c in [
        "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
        "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
        "QQQ_vs_SMA200","XLK_vs_SMA200",
        "TLT_mom3","TLT_mom6","LQD_mom3","LQD_mom6",
        "GLD_mom3","GLD_mom6","XLU_mom3","XLU_mom6",
        "VIX","RiskCorr20","RiskCorr60","CrossAssetAbsCorr20",
    ] if c in x.columns]
    for c in change_base:
        x[f"d1_{c}"] = x[c] - x[c].shift(1)

    return x


def _v336_compare_groups(data, mask_a, mask_b, label_a, label_b, features):
    rows = []
    for f in features:
        a = data.loc[mask_a, f].dropna()
        b = data.loc[mask_b, f].dropna()
        if len(a) < 3 or len(b) < 3:
            continue
        auc = _v334_pairwise_auc(a, b)
        pooled = np.sqrt((a.var(ddof=1) + b.var(ddof=1))/2)
        effect = (a.mean()-b.mean())/pooled if pooled and pd.notna(pooled) else np.nan
        rows.append({
            "Feature": f,
            f"{label_a} median": a.median(),
            f"{label_b} median": b.median(),
            f"AUC({label_a}>{label_b})": auc,
            "Directional AUC": max(auc, 1-auc),
            "Direction": f"{label_a}+" if auc >= .5 else f"{label_b}+",
            "Effect": effect,
            f"N {label_a}": len(a),
            f"N {label_b}": len(b),
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out = out.sort_values(["Directional AUC","Effect"], ascending=[False,False])
    return out



