# v3.37 — Defensive Asset Autopsy: XLU vs GLD
#
# TARGET ONLY / DIAGNOSTIC ONLY.
# No trading rule. No threshold sweep. No allocation optimization.
# Target history frozen through 2026-07.
#
# Goal:
#   Among target Defensive months, diagnose what distinguishes XLU from GLD.
#
# Fixed prior-month-end features:
#   Equity trend/momentum
#   Defensive relative strength (XLU vs GLD, XLU vs SPY, GLD vs SPY)
#   Bond momentum
#   VIX / correlation
#   Momentum inflection
#
# Comparisons:
#   1) Pure XLU vs Pure GLD
#   2) XLU-heavy vs GLD-heavy within Defensive months
#   3) Allocation shifts toward XLU vs toward GLD
#   4) Era stability
#   5) Defensive-entry months specifically
# =============================================================================

def _v337_prepare_defensive_allocations(target, feat):
    x = target.copy()
    x = x[x["Month"] <= pd.Period("2026-07", "M")].copy()
    x = x.sort_values("Month").reset_index(drop=True)

    # Reconstruct broad state if absent.
    if "State" not in x.columns:
        agg = x["AggressiveWt"].fillna(0.0)
        deff = x["DefensiveWt"].fillna(0.0)
        x["State"] = np.select(
            [
                (agg >= 0.999) & (deff <= 0.001),
                (deff >= 0.999) & (agg <= 0.001),
            ],
            ["Aggressive", "Defensive"],
            default="Mixed",
        )

    x["PrevState"] = x["State"].shift(1)
    x = x.merge(feat.reset_index(names="Month"), on="Month", how="left")

    # Defensive composition within XLU + GLD.
    denom = x["XLU"].fillna(0) + x["GLD"].fillna(0)
    x["XLUShareDef"] = np.where(denom > 0, x["XLU"].fillna(0) / denom, np.nan)
    x["GLDShareDef"] = np.where(denom > 0, x["GLD"].fillna(0) / denom, np.nan)

    def cls(r):
        xlu, gld = float(r["XLU"]), float(r["GLD"])
        if xlu >= 99.9 and gld <= 0.1:
            return "Pure XLU"
        if gld >= 99.9 and xlu <= 0.1:
            return "Pure GLD"
        if xlu > gld:
            return "XLU-heavy Mix"
        if gld > xlu:
            return "GLD-heavy Mix"
        return "50/50 Mix"

    x["DefensiveAllocation"] = x.apply(cls, axis=1)

    # Fixed relative-strength features.
    for n in [1,3,6,12]:
        if f"XLU_mom{n}" in x and f"GLD_mom{n}" in x:
            x[f"XLU_minus_GLD_{n}m"] = x[f"XLU_mom{n}"] - x[f"GLD_mom{n}"]
        if f"XLU_mom{n}" in x and f"SPY_mom{n}" in x:
            x[f"XLU_minus_SPY_{n}m"] = x[f"XLU_mom{n}"] - x[f"SPY_mom{n}"]
        if f"GLD_mom{n}" in x and f"SPY_mom{n}" in x:
            x[f"GLD_minus_SPY_{n}m"] = x[f"GLD_mom{n}"] - x[f"SPY_mom{n}"]

    if "XLU_vs_SMA200" in x and "GLD_vs_SMA200" in x:
        x["XLU_minus_GLD_SMA200"] = x["XLU_vs_SMA200"] - x["GLD_vs_SMA200"]

    # Fixed inflection differences.
    if all(c in x for c in ["XLU_mom1","XLU_mom3","GLD_mom1","GLD_mom3"]):
        x["DefRelInflect_1m3m"] = (
            (x["XLU_mom1"] - x["XLU_mom3"])
            - (x["GLD_mom1"] - x["GLD_mom3"])
        )
    if all(c in x for c in ["XLU_mom3","XLU_mom12","GLD_mom3","GLD_mom12"]):
        x["DefRelInflect_3m12m"] = (
            (x["XLU_mom3"] - x["XLU_mom12"])
            - (x["GLD_mom3"] - x["GLD_mom12"])
        )

    return x



