def _v338_monthly_total_return_signal(closes, asset, months, idx, label, condition):
    """
    v3.38b FIX:
    _v326_effective_monthly_signal() is a BOOLEAN signal execution helper.
    Build the economic condition at month-end first, then pass that boolean
    series through the existing next-open execution convention.

    condition:
      "lt0" -> monthly total return < 0
      "gt0" -> monthly total return > 0
    """
    me = closes[[asset]].resample("ME").last()
    s = me[asset] / me[asset].shift(months) - 1.0

    if condition == "lt0":
        raw_signal = s < 0
    elif condition == "gt0":
        raw_signal = s > 0
    else:
        raise ValueError(f"Unknown condition: {condition}")

    # Preserve missing warm-up values as False rather than accidentally truthy.
    raw_signal = raw_signal.where(s.notna(), False).astype(bool)

    eff = _v326_effective_monthly_signal(raw_signal, idx, label)

    raw = pd.DataFrame({
        "Month": s.index.to_period("M").astype(str),
        label: s.values,
        f"{label} raw condition": raw_signal.values,
    })
    return eff.astype(bool), raw



# =============================================================================
# v3.39 — Risk-Off Entry vs Exit Autopsy
#
# TARGET ONLY / DIAGNOSTIC ONLY.
# No trading rule. No threshold sweep. No portfolio change.
# Target history frozen through 2026-07.
#
# Goal:
#   Test whether target Risk-Off Entry (Agg->Def) and Risk-On Exit (Def->Agg)
#   are symmetric reversals of the same information, or use asymmetric
#   hysteresis / different information.
#
# Fixed prior-month-end feature families:
#   - QQQ / XLK momentum levels 1/3/6/12M
#   - QQQ / XLK momentum inflection
#   - QQQ / XLK SMA100 / SMA200 distance
#   - GLD / LQD / TLT / XLU momentum 1/3/6/12M
#   - relative-strength spreads
#   - VIX level / change
#   - RiskCorr20 / 60, CrossAssetAbsCorr20, correlation changes
#
# Comparisons:
#   A) Agg->Def vs Agg->Agg   : Risk-Off ENTRY information
#   B) Def->Agg vs Def->Def   : Risk-On EXIT information
#   C) Agg->Def vs Def->Agg   : direct transition asymmetry
#   D) Era stability
#   E) 3-month lead-up median path
#
# Important:
#   This app does NOT create a hysteresis rule. It only decides whether such a
#   rule is justified before any implementation.
# =============================================================================

def _v339_prepare_transition_dataset(target, closes):
    x = target.copy()
    x = x[x["Month"] <= pd.Period("2026-07", "M")].copy()
    x = x.sort_values("Month").reset_index(drop=True)

    # Broad state is reconstructed deterministically to prevent inherited-schema bugs.
    if "State" not in x.columns:
        agg = x["AggressiveWt"].fillna(0.0)
        deff = x["DefensiveWt"].fillna(0.0)
        x["State"] = np.select(
            [
                (agg >= 0.999) & (deff <= 0.001),
                (deff >= 0.999) & (agg <= 0.001),
            ],
            ["Aggressive", "Defensive"],
            default="Mixed",
        )

    x["PrevState"] = x["State"].shift(1)
    x["Transition"] = x["PrevState"].astype(str) + "→" + x["State"].astype(str)

    # Base fixed month-end features.
    feat = _v330_month_end_features(closes).copy()

    # Add SMA100 / SMA200 distances where available.
    me = closes.resample("ME").last()
    for a in ["QQQ","XLK","SPY","XLU","GLD","LQD","TLT"]:
        if a not in closes.columns:
            continue
        for w in [100, 200]:
            sma = closes[a].rolling(w).mean().resample("ME").last()
            s = me[a] / sma - 1.0
            s.index = s.index.to_period("M")
            feat[f"{a}_SMA{w}"] = s.reindex(feat.index)

    # Fixed momentum inflections and relative strength.
    for a in ["QQQ","XLK"]:
        if all(f"{a}_mom{n}" in feat.columns for n in [1,3,6,12]):
            feat[f"{a}_Inflect_1m3m"] = feat[f"{a}_mom1"] - feat[f"{a}_mom3"]
            feat[f"{a}_Inflect_1m6m"] = feat[f"{a}_mom1"] - feat[f"{a}_mom6"]
            feat[f"{a}_Inflect_3m12m"] = feat[f"{a}_mom3"] - feat[f"{a}_mom12"]

    for n in [1,3,6,12]:
        if f"XLK_mom{n}" in feat and f"QQQ_mom{n}" in feat:
            feat[f"XLK_minus_QQQ_{n}m"] = feat[f"XLK_mom{n}"] - feat[f"QQQ_mom{n}"]
        if f"QQQ_mom{n}" in feat and f"GLD_mom{n}" in feat:
            feat[f"QQQ_minus_GLD_{n}m"] = feat[f"QQQ_mom{n}"] - feat[f"GLD_mom{n}"]
        if f"QQQ_mom{n}" in feat and f"XLU_mom{n}" in feat:
            feat[f"QQQ_minus_XLU_{n}m"] = feat[f"QQQ_mom{n}"] - feat[f"XLU_mom{n}"]
        if f"TLT_mom{n}" in feat and f"GLD_mom{n}" in feat:
            feat[f"TLT_minus_GLD_{n}m"] = feat[f"TLT_mom{n}"] - feat[f"GLD_mom{n}"]

    # VIX / correlation diagnostics, all evaluated at month-end.
    ret = closes.pct_change(fill_method=None)

    def mean_pair_corr(frame, window, absolute=False):
        vals = []
        cols = list(frame.columns)
        for i in range(len(cols)):
            for j in range(i+1, len(cols)):
                c = frame[cols[i]].rolling(window).corr(frame[cols[j]])
                vals.append(c.abs() if absolute else c)
        if not vals:
            return pd.Series(index=frame.index, dtype=float)
        return pd.concat(vals, axis=1).mean(axis=1)

    risk_assets = [c for c in ["QQQ","SPY","XLU","LQD"] if c in ret.columns]
    cross_assets = [c for c in ["QQQ","LQD","TLT","GLD","XLU"] if c in ret.columns]

    corr_map = {
        "RiskCorr20": mean_pair_corr(ret[risk_assets], 20, False),
        "RiskCorr60": mean_pair_corr(ret[risk_assets], 60, False),
        "CrossAssetAbsCorr20": mean_pair_corr(ret[cross_assets], 20, True),
    }

    for name, s in corr_map.items():
        z = s.resample("ME").last()
        z.index = z.index.to_period("M")
        feat[name] = z.reindex(feat.index)
        feat[f"Delta_{name}_1m"] = feat[name] - feat[name].shift(1)

    # VIX one-month change if VIX exists in base feature table.
    if "VIX" in feat.columns:
        feat["Delta_VIX_1m"] = feat["VIX"] - feat["VIX"].shift(1)

    # Momentum one-month changes: level deterioration/improvement, not optimized.
    fixed_change_bases = [
        "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
        "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
        "GLD_mom3","LQD_mom3","TLT_mom3","XLU_mom3",
    ]
    for f in fixed_change_bases:
        if f in feat.columns:
            feat[f"Delta_{f}_1m"] = feat[f] - feat[f].shift(1)

    y = x.merge(feat.reset_index(names="Month"), on="Month", how="left")
    return y, feat


def _v339_transition_scoreboard(data, features):
    masks = {
        "Agg→Def": data["Transition"].eq("Aggressive→Defensive"),
        "Agg→Agg": data["Transition"].eq("Aggressive→Aggressive"),
        "Def→Agg": data["Transition"].eq("Defensive→Aggressive"),
        "Def→Def": data["Transition"].eq("Defensive→Defensive"),
    }

    rows = []
    for f in features:
        vals = {}
        for name, m in masks.items():
            vals[name] = data.loc[m, f].dropna()

        if min(len(vals["Agg→Def"]), len(vals["Agg→Agg"]),
               len(vals["Def→Agg"]), len(vals["Def→Def"])) < 1:
            continue

        e_auc_raw = _v334_pairwise_auc(vals["Agg→Def"], vals["Agg→Agg"])
        x_auc_raw = _v334_pairwise_auc(vals["Def→Agg"], vals["Def→Def"])
        direct_auc_raw = _v334_pairwise_auc(vals["Agg→Def"], vals["Def→Agg"])

        e_dir = 1 if e_auc_raw >= 0.5 else -1
        x_dir = 1 if x_auc_raw >= 0.5 else -1

        entry_med = vals["Agg→Def"].median()
        aggcont_med = vals["Agg→Agg"].median()
        exit_med = vals["Def→Agg"].median()
        defcont_med = vals["Def→Def"].median()

        rows.append({
            "Feature": f,
            "Agg→Def median": entry_med,
            "Agg→Agg median": aggcont_med,
            "Entry dAUC": max(e_auc_raw, 1-e_auc_raw),
            "Entry direction": "Higher at Risk-Off Entry" if e_dir > 0 else "Lower at Risk-Off Entry",
            "Def→Agg median": exit_med,
            "Def→Def median": defcont_med,
            "Exit dAUC": max(x_auc_raw, 1-x_auc_raw),
            "Exit direction": "Higher at Risk-On Exit" if x_dir > 0 else "Lower at Risk-On Exit",
            "Agg→Def vs Def→Agg dAUC": max(direct_auc_raw, 1-direct_auc_raw),
            "Opposite directions?": bool(e_dir != x_dir),
            "Entry median delta": entry_med - aggcont_med,
            "Exit median delta": exit_med - defcont_med,
        })
    out = pd.DataFrame(rows)
    if out.empty:
        return out
    # Holistic diagnostic ranking: strong on both sides first, no threshold optimization.
    out["Min(Entry,Exit) dAUC"] = out[["Entry dAUC","Exit dAUC"]].min(axis=1)
    out["Mean Entry/Exit dAUC"] = out[["Entry dAUC","Exit dAUC"]].mean(axis=1)
    return out.sort_values(
        ["Opposite directions?","Min(Entry,Exit) dAUC","Mean Entry/Exit dAUC"],
        ascending=[False,False,False]
    ).reset_index(drop=True)


def _v339_era_stability(data, features):
    eras = [
        ("2013-17", pd.Period("2013-01","M"), pd.Period("2017-12","M")),
        ("2018-21", pd.Period("2018-01","M"), pd.Period("2021-12","M")),
        ("2022-26", pd.Period("2022-01","M"), pd.Period("2026-07","M")),
    ]
    rows = []

    comparisons = [
        ("Entry", "Aggressive→Defensive", "Aggressive→Aggressive"),
        ("Exit", "Defensive→Aggressive", "Defensive→Defensive"),
    ]

    for comp, a_name, b_name in comparisons:
        for f in features:
            for era_name, lo, hi in eras:
                z = data[(data["Month"] >= lo) & (data["Month"] <= hi)]
                a = z.loc[z["Transition"].eq(a_name), f].dropna()
                b = z.loc[z["Transition"].eq(b_name), f].dropna()
                if len(a) < 2 or len(b) < 2:
                    continue
                auc = _v334_pairwise_auc(a, b)
                rows.append({
                    "Comparison": comp,
                    "Feature": f,
                    "Era": era_name,
                    "A median": a.median(),
                    "B median": b.median(),
                    "Median delta": a.median() - b.median(),
                    "Directional AUC": max(auc, 1-auc),
                    "Raw AUC(A>B)": auc,
                    "Direction": "Higher" if auc >= .5 else "Lower",
                    "N A": len(a),
                    "N B": len(b),
                })
    return pd.DataFrame(rows)


def _v339_leadup_table(data, features):
    transition_months = {
        "Risk-Off Entry": data.loc[
            data["Transition"].eq("Aggressive→Defensive"), "Month"
        ].tolist(),
        "Risk-On Exit": data.loc[
            data["Transition"].eq("Defensive→Aggressive"), "Month"
        ].tolist(),
    }

    by_month = data.set_index("Month")
    rows = []
    for transition_type, months in transition_months.items():
        for lag in [-3,-2,-1,0]:
            vals_by_feature = {f: [] for f in features}
            for m in months:
                mm = m + lag
                if mm not in by_month.index:
                    continue
                row = by_month.loc[mm]
                if isinstance(row, pd.DataFrame):
                    row = row.iloc[-1]
                for f in features:
                    v = row.get(f, np.nan)
                    if pd.notna(v):
                        vals_by_feature[f].append(float(v))
            for f, vals in vals_by_feature.items():
                if vals:
                    rows.append({
                        "TransitionType": transition_type,
                        "LagMonths": lag,
                        "Feature": f,
                        "Median": float(np.median(vals)),
                        "N": len(vals),
                    })
    return pd.DataFrame(rows)



# =============================================================================
# v3.40 — TLT3M State-Machine Challenger #1
#
# CONTROL
#   v3.35 Attack #1:
#   - Adaptive ALL safe haven
#   - A Accelerator: TLT 3M > 0
#   - VIX30 brake
#   - XLK momentum-inflection Turbo
#   - T2 = 75% attack allocation during Turbo
#   - Attack asset: TECL iff prior month-end XLK 6M > QQQ 6M, else TQQQ
#
# CHALLENGER
#   Risk-Off destination fixed ex ante to 100% XLU.
#
#   Monthly TLT 3M state machine:
#     Risk-On  -> Risk-Off only when TLT3M crosses from >=0 to <0
#     Risk-Off -> Risk-On  only when TLT3M crosses from <=0 to >0
#     Otherwise preserve previous state.
#
#   Month-end signal -> existing next-open execution convention.
#
# IMPORTANT:
#   This is a one-shot state-machine test.
#   No threshold sweep. No 6M comparison. No GLD/XLU selector.
#   Development sample through 2026-07.
# =============================================================================

def _v340_tlt3m_state_machine(closes, idx):
    me = closes[["TLT"]].resample("ME").last()
    tlt3 = me["TLT"] / me["TLT"].shift(3) - 1.0

    vals = tlt3.copy()
    state = pd.Series(False, index=vals.index, dtype=bool)  # False=Risk-On, True=Risk-Off

    current_riskoff = False
    prev = np.nan

    for dt, v in vals.items():
        if pd.isna(v):
            state.loc[dt] = current_riskoff
            continue

        if pd.notna(prev):
            if (prev >= 0) and (v < 0):
                current_riskoff = True
            elif (prev <= 0) and (v > 0):
                current_riskoff = False

        state.loc[dt] = current_riskoff
        prev = v

    # Existing month-end -> next-open execution helper expects booleans.
    eff = _v326_effective_monthly_signal(
        state.astype(bool), idx, "TLT3M Risk-Off State"
    ).astype(bool)

    audit = pd.DataFrame({
        "Month": vals.index.to_period("M").astype(str),
        "TLT 3M": vals.values,
        "Raw Risk-Off State": state.values,
    })
    audit["Prev TLT 3M"] = audit["TLT 3M"].shift(1)
    audit["Down Cross"] = (
        audit["Prev TLT 3M"].ge(0) & audit["TLT 3M"].lt(0)
    )
    audit["Up Cross"] = (
        audit["Prev TLT 3M"].le(0) & audit["TLT 3M"].gt(0)
    )

    return eff, audit



# =============================================================================
# v3.41 — TLT Down-Cross True-vs-False Entry Autopsy
#
# DIAGNOSTIC ONLY. NO TRADING RULE.
#
# Fixed event universe:
#   Every prior-month-end TLT3M >=0 -> <0 down-cross through 2026-07.
#
# Question:
#   Which down-crosses coincide with the TARGET actually moving
#   Aggressive -> Defensive ("True Entry"), versus down-crosses where
#   the target remains Aggressive ("False Entry")?
#
# To avoid post-hoc fishing:
#   - no new lookbacks
#   - no threshold sweep
#   - no AND/OR combinations
#   - only previously discovered fixed feature families
#   - report era stability and lead-up paths
# =============================================================================

def _v341_prepare_downcross_autopsy(target, closes):
    x = target.copy()
    x = x[x["Month"] <= pd.Period("2026-07", "M")].copy()
    x = x.sort_values("Month").reset_index(drop=True)

    if "State" not in x.columns:
        agg = x["AggressiveWt"].fillna(0.0)
        deff = x["DefensiveWt"].fillna(0.0)
        x["State"] = np.select(
            [
                (agg >= 0.999) & (deff <= 0.001),
                (deff >= 0.999) & (agg <= 0.001),
            ],
            ["Aggressive", "Defensive"],
            default="Mixed",
        )

    x["PrevState"] = x["State"].shift(1)
    x["Transition"] = x["PrevState"].astype(str) + "→" + x["State"].astype(str)

    feat = _v330_month_end_features(closes).copy()

    # TLT3M is the fixed event trigger.
    me = closes.resample("ME").last()
    tlt3 = me["TLT"] / me["TLT"].shift(3) - 1.0
    tlt3.index = tlt3.index.to_period("M")
    feat["TLT_mom3"] = tlt3.reindex(feat.index)
    feat["Prev_TLT_mom3"] = feat["TLT_mom3"].shift(1)
    feat["TLT3M_DownCross"] = (
        feat["Prev_TLT_mom3"].ge(0) & feat["TLT_mom3"].lt(0)
    )

    # Previously discovered fixed trend features.
    for a in ["QQQ","XLK"]:
        if a in closes.columns:
            for w in [100, 200]:
                sma = closes[a].rolling(w).mean().resample("ME").last()
                s = me[a] / sma - 1.0
                s.index = s.index.to_period("M")
                feat[f"{a}_SMA{w}"] = s.reindex(feat.index)

    # Previously discovered momentum inflection.
    for a in ["QQQ","XLK"]:
        if f"{a}_mom1" in feat.columns and f"{a}_mom3" in feat.columns:
            feat[f"{a}_Inflect_1m3m"] = feat[f"{a}_mom1"] - feat[f"{a}_mom3"]

    # Stress / correlation features used in earlier autopsies.
    ret = closes.pct_change(fill_method=None)

    def _pair_corr(frame, window, absolute=False):
        vals = []
        cols = list(frame.columns)
        for i in range(len(cols)):
            for j in range(i + 1, len(cols)):
                c = frame[cols[i]].rolling(window).corr(frame[cols[j]])
                vals.append(c.abs() if absolute else c)
        if not vals:
            return pd.Series(index=frame.index, dtype=float)
        return pd.concat(vals, axis=1).mean(axis=1)

    risk_cols = [c for c in ["QQQ","SPY","XLU","LQD"] if c in ret.columns]
    cross_cols = [c for c in ["QQQ","LQD","TLT","GLD","XLU"] if c in ret.columns]

    corr_series = {
        "RiskCorr20": _pair_corr(ret[risk_cols], 20, False),
        "CrossAssetAbsCorr20": _pair_corr(ret[cross_cols], 20, True),
    }
    for name, s in corr_series.items():
        z = s.resample("ME").last()
        z.index = z.index.to_period("M")
        feat[name] = z.reindex(feat.index)
        feat[f"Delta_{name}_1m"] = feat[name] - feat[name].shift(1)

    if "VIX" in feat.columns:
        feat["Delta_VIX_1m"] = feat["VIX"] - feat["VIX"].shift(1)

    # One-month change only for already established features.
    for f in [
        "QQQ_mom3","GLD_mom3","LQD_mom3","TLT_mom3",
        "QQQ_Inflect_1m3m","XLK_Inflect_1m3m",
    ]:
        if f in feat.columns:
            feat[f"Delta_{f}_1m"] = feat[f] - feat[f].shift(1)

    data = x.merge(feat.reset_index(names="Month"), on="Month", how="left")

    # Classification is intentionally strict:
    # True = target was Aggressive and becomes Defensive exactly on the down-cross month.
    # False = target was Aggressive and remains Aggressive on the down-cross month.
    # Other down-crosses (target already Defensive / Mixed) are retained in event audit
    # but excluded from True-vs-False discrimination.
    data["DownCrossClass"] = np.select(
        [
            data["TLT3M_DownCross"].fillna(False)
            & data["PrevState"].eq("Aggressive")
            & data["State"].eq("Defensive"),

            data["TLT3M_DownCross"].fillna(False)
            & data["PrevState"].eq("Aggressive")
            & data["State"].eq("Aggressive"),
        ],
        ["True Entry","False Entry"],
        default="Other / not eligible",
    )

    return data, feat


def _v341_compare_true_false(data, features):
    true_mask = data["DownCrossClass"].eq("True Entry")
    false_mask = data["DownCrossClass"].eq("False Entry")

    rows = []
    for f in features:
        a = data.loc[true_mask, f].dropna()
        b = data.loc[false_mask, f].dropna()
        if len(a) < 1 or len(b) < 1:
            continue
        auc = _v334_pairwise_auc(a, b)
        rows.append({
            "Feature": f,
            "True Entry median": a.median(),
            "False Entry median": b.median(),
            "Median delta": a.median() - b.median(),
            "Raw AUC(True>False)": auc,
            "Directional AUC": max(auc, 1-auc),
            "True Entry direction": "Higher" if auc >= .5 else "Lower",
            "N True": len(a),
            "N False": len(b),
        })
    out = pd.DataFrame(rows)
    if out.empty:
        return out
    return out.sort_values("Directional AUC", ascending=False).reset_index(drop=True)


def _v341_era_stability(data, features):
    eras = [
        ("2013-17", pd.Period("2013-01","M"), pd.Period("2017-12","M")),
        ("2018-21", pd.Period("2018-01","M"), pd.Period("2021-12","M")),
        ("2022-26", pd.Period("2022-01","M"), pd.Period("2026-07","M")),
    ]
    rows = []
    for f in features:
        for era_name, lo, hi in eras:
            z = data[(data["Month"] >= lo) & (data["Month"] <= hi)]
            a = z.loc[z["DownCrossClass"].eq("True Entry"), f].dropna()
            b = z.loc[z["DownCrossClass"].eq("False Entry"), f].dropna()
            if len(a) < 1 or len(b) < 1:
                continue
            auc = _v334_pairwise_auc(a, b)
            rows.append({
                "Feature": f,
                "Era": era_name,
                "True median": a.median(),
                "False median": b.median(),
                "Median delta": a.median() - b.median(),
                "Raw AUC(True>False)": auc,
                "Directional AUC": max(auc, 1-auc),
                "Direction": "Higher" if auc >= .5 else "Lower",
                "N True": len(a),
                "N False": len(b),
            })
    return pd.DataFrame(rows)


def _v341_leadup(data, features):
    by_month = data.set_index("Month")
    rows = []
    for klass in ["True Entry","False Entry"]:
        months = data.loc[data["DownCrossClass"].eq(klass), "Month"].tolist()
        for lag in [-3,-2,-1,0]:
            for f in features:
                vals = []
                for m in months:
                    mm = m + lag
                    if mm not in by_month.index:
                        continue
                    row = by_month.loc[mm]
                    if isinstance(row, pd.DataFrame):
                        row = row.iloc[-1]
                    v = row.get(f, np.nan)
                    if pd.notna(v):
                        vals.append(float(v))
                if vals:
                    rows.append({
                        "Class": klass,
                        "LagMonths": lag,
                        "Feature": f,
                        "Median": float(np.median(vals)),
                        "N": len(vals),
                    })
    return pd.DataFrame(rows)



# =============================================================================
# v3.42 — Risk-Off Momentum Exhaustion Autopsy
#
# DIAGNOSTIC ONLY. NO TRADING RULE.
#
# Fixed event universe:
#   TARGET Aggressive -> Defensive entries through 2026-07
#   versus TARGET Aggressive -> Aggressive continuations.
#
# Main question:
#   Is Risk-Off entry characterized by the *joint structure*:
#     (1) medium-term equity momentum remains strong, while
#     (2) short-term momentum has sharply deteriorated?
#
# This tests the previously observed "late-cycle / momentum exhaustion" idea
# without creating an AND rule or optimizing thresholds.
#
# Predeclared structure diagnostics:
#   - QQQ 3M level
#   - QQQ 1M-3M inflection
#   - XLK analogues
#   - rank/quadrant occupancy using natural sample medians only for description,
#     not for trading
#   - interaction-style continuous diagnostics:
#       strong-medium * negative-inflection magnitude
#       z(QQQ3M) - z(QQQ 1M-3M)
#   - lead-up path and era stability
#
# IMPORTANT:
#   No threshold sweep. No lookback sweep. No AND/OR trading rule.
#   Median-based quadrants are descriptive only.
# =============================================================================

def _v342_prepare_momentum_exhaustion(target, closes):
    x = target.copy()
    x = x[x["Month"] <= pd.Period("2026-07", "M")].copy()
    x = x.sort_values("Month").reset_index(drop=True)

    if "State" not in x.columns:
        agg = x["AggressiveWt"].fillna(0.0)
        deff = x["DefensiveWt"].fillna(0.0)
        x["State"] = np.select(
            [
                (agg >= 0.999) & (deff <= 0.001),
                (deff >= 0.999) & (agg <= 0.001),
            ],
            ["Aggressive", "Defensive"],
            default="Mixed",
        )

    x["PrevState"] = x["State"].shift(1)
    x["Transition"] = x["PrevState"].astype(str) + "→" + x["State"].astype(str)

    feat = _v330_month_end_features(closes).copy()

    # Previously established equity trend features.
    me = closes.resample("ME").last()
    for a in ["QQQ","XLK"]:
        if a in closes.columns:
            for w in [100, 200]:
                sma = closes[a].rolling(w).mean().resample("ME").last()
                s = me[a] / sma - 1.0
                s.index = s.index.to_period("M")
                feat[f"{a}_SMA{w}"] = s.reindex(feat.index)

    # Fixed inflection definitions from prior work.
    for a in ["QQQ","XLK"]:
        if f"{a}_mom1" in feat.columns and f"{a}_mom3" in feat.columns:
            feat[f"{a}_Inflect_1m3m"] = feat[f"{a}_mom1"] - feat[f"{a}_mom3"]
        if f"{a}_mom1" in feat.columns and f"{a}_mom6" in feat.columns:
            feat[f"{a}_Inflect_1m6m"] = feat[f"{a}_mom1"] - feat[f"{a}_mom6"]

    # One-month changes in already established features.
    for f in [
        "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m",
        "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m",
        "GLD_mom3","LQD_mom3","TLT_mom3",
    ]:
        if f in feat.columns:
            feat[f"Delta_{f}_1m"] = feat[f] - feat[f].shift(1)

    # Stress / correlation diagnostics used before.
    ret = closes.pct_change(fill_method=None)

    def _pair_corr(frame, window, absolute=False):
        vals = []
        cols = list(frame.columns)
        for i in range(len(cols)):
            for j in range(i + 1, len(cols)):
                c = frame[cols[i]].rolling(window).corr(frame[cols[j]])
                vals.append(c.abs() if absolute else c)
        if not vals:
            return pd.Series(index=frame.index, dtype=float)
        return pd.concat(vals, axis=1).mean(axis=1)

    risk_cols = [c for c in ["QQQ","SPY","XLU","LQD"] if c in ret.columns]
    cross_cols = [c for c in ["QQQ","LQD","TLT","GLD","XLU"] if c in ret.columns]

    corr_series = {
        "RiskCorr20": _pair_corr(ret[risk_cols], 20, False),
        "CrossAssetAbsCorr20": _pair_corr(ret[cross_cols], 20, True),
    }
    for name, s in corr_series.items():
        z = s.resample("ME").last()
        z.index = z.index.to_period("M")
        feat[name] = z.reindex(feat.index)
        feat[f"Delta_{name}_1m"] = feat[name] - feat[name].shift(1)

    if "VIX" in feat.columns:
        feat["Delta_VIX_1m"] = feat["VIX"] - feat["VIX"].shift(1)

    data = x.merge(feat.reset_index(names="Month"), on="Month", how="left")

    # Eligible universe only: prior state Aggressive.
    eligible = data["PrevState"].eq("Aggressive") & data["State"].isin(["Aggressive","Defensive"])
    data["EntryClass"] = np.select(
        [
            eligible & data["State"].eq("Defensive"),
            eligible & data["State"].eq("Aggressive"),
        ],
        ["Risk-Off Entry","Aggressive Continue"],
        default="Other / not eligible",
    )

    # Continuous exhaustion diagnostics. These are descriptive transforms,
    # not thresholds and not trading rules.
    for a in ["QQQ","XLK"]:
        m3 = f"{a}_mom3"
        inf = f"{a}_Inflect_1m3m"
        if m3 in data.columns and inf in data.columns:
            # Positive only when medium momentum is strong and inflection is negative.
            data[f"{a}_ExhaustionProduct"] = (
                data[m3].clip(lower=0) * (-data[inf]).clip(lower=0)
            )

            # Standardized contrast across eligible observations only.
            em = data.loc[eligible, m3]
            ei = data.loc[eligible, inf]
            m_mu, m_sd = em.mean(), em.std(ddof=0)
            i_mu, i_sd = ei.mean(), ei.std(ddof=0)
            z_m = (data[m3] - m_mu) / m_sd if pd.notna(m_sd) and m_sd > 0 else np.nan
            z_i = (data[inf] - i_mu) / i_sd if pd.notna(i_sd) and i_sd > 0 else np.nan
            data[f"{a}_ExhaustionZ"] = z_m - z_i

    return data


def _v342_compare_groups(data, features):
    a_mask = data["EntryClass"].eq("Risk-Off Entry")
    b_mask = data["EntryClass"].eq("Aggressive Continue")

    rows = []
    for f in features:
        a = data.loc[a_mask, f].dropna()
        b = data.loc[b_mask, f].dropna()
        if len(a) < 1 or len(b) < 1:
            continue
        auc = _v334_pairwise_auc(a, b)
        rows.append({
            "Feature": f,
            "Risk-Off Entry median": a.median(),
            "Aggressive Continue median": b.median(),
            "Median delta": a.median() - b.median(),
            "Raw AUC(Entry>Continue)": auc,
            "Directional AUC": max(auc, 1-auc),
            "Entry direction": "Higher" if auc >= .5 else "Lower",
            "N Entry": len(a),
            "N Continue": len(b),
        })
    out = pd.DataFrame(rows)
    if out.empty:
        return out
    return out.sort_values("Directional AUC", ascending=False).reset_index(drop=True)


def _v342_era_stability(data, features):
    eras = [
        ("2013-17", pd.Period("2013-01","M"), pd.Period("2017-12","M")),
        ("2018-21", pd.Period("2018-01","M"), pd.Period("2021-12","M")),
        ("2022-26", pd.Period("2022-01","M"), pd.Period("2026-07","M")),
    ]
    rows = []
    for f in features:
        for era_name, lo, hi in eras:
            z = data[(data["Month"] >= lo) & (data["Month"] <= hi)]
            a = z.loc[z["EntryClass"].eq("Risk-Off Entry"), f].dropna()
            b = z.loc[z["EntryClass"].eq("Aggressive Continue"), f].dropna()
            if len(a) < 2 or len(b) < 2:
                continue
            auc = _v334_pairwise_auc(a, b)
            rows.append({
                "Feature": f,
                "Era": era_name,
                "Entry median": a.median(),
                "Continue median": b.median(),
                "Median delta": a.median() - b.median(),
                "Raw AUC(Entry>Continue)": auc,
                "Directional AUC": max(auc, 1-auc),
                "Direction": "Higher" if auc >= .5 else "Lower",
                "N Entry": len(a),
                "N Continue": len(b),
            })
    return pd.DataFrame(rows)


def _v342_leadup(data, features):
    by_month = data.set_index("Month")
    rows = []
    for klass in ["Risk-Off Entry","Aggressive Continue"]:
        months = data.loc[data["EntryClass"].eq(klass), "Month"].tolist()
        for lag in [-3,-2,-1,0]:
            for f in features:
                vals = []
                for m in months:
                    mm = m + lag
                    if mm not in by_month.index:
                        continue
                    row = by_month.loc[mm]
                    if isinstance(row, pd.DataFrame):
                        row = row.iloc[-1]
                    v = row.get(f, np.nan)
                    if pd.notna(v):
                        vals.append(float(v))
                if vals:
                    rows.append({
                        "Class": klass,
                        "LagMonths": lag,
                        "Feature": f,
                        "Median": float(np.median(vals)),
                        "N": len(vals),
                    })
    return pd.DataFrame(rows)


def _v342_quadrant_table(data, asset="QQQ"):
    m3 = f"{asset}_mom3"
    inf = f"{asset}_Inflect_1m3m"
    z = data[data["EntryClass"].isin(["Risk-Off Entry","Aggressive Continue"])].copy()
    z = z.dropna(subset=[m3, inf])

    if z.empty:
        return pd.DataFrame(), pd.DataFrame()

    # Descriptive natural sample medians only; never used as a strategy rule.
    m3_med = z[m3].median()
    inf_med = z[inf].median()

    z["MediumMomentum"] = np.where(z[m3] >= m3_med, "High 3M", "Low 3M")
    z["Inflection"] = np.where(z[inf] < inf_med, "Weak 1M−3M", "Strong 1M−3M")
    z["Quadrant"] = z["MediumMomentum"] + " / " + z["Inflection"]

    count = pd.crosstab(z["Quadrant"], z["EntryClass"])
    count["Total"] = count.sum(axis=1)
    if "Risk-Off Entry" in count.columns:
        count["Risk-Off Entry share"] = count["Risk-Off Entry"] / count["Total"]
    count = count.reset_index()

    meta = pd.DataFrame({
        "Asset": [asset],
        "3M sample median": [m3_med],
        "1M−3M sample median": [inf_med],
        "Note": ["Descriptive median split only; not a trading threshold"],
    })
    return count, meta



# =============================================================================
# v3.43 — QQQ Exhaustion One-Month Brake Challenger #1
#
# CONTROL = v3.35 Attack #1, unchanged.
#
# CHALLENGER:
#   Build the same continuous QQQ Exhaustion Z diagnostic frozen in v3.42:
#       z(QQQ 3M) - z(QQQ 1M-3M)
#
#   Event trigger:
#       Exhaustion Z crosses from <= 0 to > 0 at month-end.
#
#   Action:
#       ONLY the following execution month is 100% XLU.
#       Then automatically return to Attack #1 unless a new independent
#       up-cross event occurs later.
#
#   Existing month-end -> next-open execution convention.
#
# IMPORTANT:
#   - One-shot test.
#   - No threshold sweep; zero is the fixed natural standardized boundary.
#   - No lookback sweep.
#   - No AND/OR filters.
#   - No persistent Risk-Off state.
#   - Development sample through 2026-07.
# =============================================================================

def _v343_exhaustion_z_monthly(closes):
    me = closes[["QQQ"]].resample("ME").last()
    q3 = me["QQQ"] / me["QQQ"].shift(3) - 1.0
    q1 = me["QQQ"] / me["QQQ"].shift(1) - 1.0
    inf = q1 - q3

    # Frozen v3.42 definition: standardized across the development observations.
    # This is diagnostic-standardization, not an optimized threshold.
    valid = pd.concat([q3.rename("q3"), inf.rename("inf")], axis=1).dropna()
    valid = valid.loc[valid.index <= pd.Timestamp("2026-07-31")]

    q3_mu, q3_sd = valid["q3"].mean(), valid["q3"].std(ddof=0)
    inf_mu, inf_sd = valid["inf"].mean(), valid["inf"].std(ddof=0)

    z3 = (q3 - q3_mu) / q3_sd
    zi = (inf - inf_mu) / inf_sd
    ez = z3 - zi

    upcross = ez.gt(0) & ez.shift(1).le(0)

    audit = pd.DataFrame({
        "Month": ez.index.to_period("M").astype(str),
        "QQQ 3M": q3.values,
        "QQQ 1M": q1.values,
        "QQQ 1M-3M": inf.values,
        "QQQ Exhaustion Z": ez.values,
        "Prev Exhaustion Z": ez.shift(1).values,
        "Up-Cross Event": upcross.values,
    })
    return ez, upcross.astype(bool), audit


def _v343_one_month_effective_signal(monthly_event, idx):
    # Reuse the established month-end -> next-open boolean execution helper.
    # The source signal is TRUE for the event month only, so it does not create
    # a persistent state.
    return _v326_effective_monthly_signal(
        monthly_event.astype(bool), idx, "QQQ Exhaustion Z Up-Cross"
    ).astype(bool)



# =============================================================================
# v3.44 — Turbo 75% -> 100% Promotion Autopsy
#
# DIAGNOSTIC ONLY. NO TRADING RULE.
#
# Fixed universe:
#   Months where v3.35 Attack #1 Turbo is active.
#
# Question:
#   Which Turbo months appear suitable for promotion from the frozen
#   75% attack allocation to 100% attack?
#
# Labels are outcome diagnostics only:
#   Compare the realized next-open execution-month return of:
#     - frozen Attack #1 (75% attack + 25% proportional non-MOM)
#     - hypothetical 100% same selected attack asset
#
# "Promotion Winner" means 100% attack outperformed the frozen 75% allocation
# during that Turbo month. This label is NOT a deployable signal.
#
# Features are frozen/prior-discovered only:
#   - QQQ/XLK momentum and 1M-3M inflection
#   - QQQ/XLK SMA100/200 distance
#   - XLK-QQQ 6M relative strength (already frozen attack-asset selector)
#   - TLT/LQD/GLD 3M
#   - VIX / changes
#   - cross-asset correlation / changes
#
# No threshold sweep. No lookback sweep. No AND/OR search.
# Development cutoff 2026-07.
# =============================================================================

def _v344_prepare_promotion_features(closes):
    feat = _v330_month_end_features(closes).copy()
    me = closes.resample("ME").last()

    for a in ["QQQ","XLK"]:
        if a in closes.columns:
            for w in [100, 200]:
                sma = closes[a].rolling(w).mean().resample("ME").last()
                s = me[a] / sma - 1.0
                s.index = s.index.to_period("M")
                feat[f"{a}_SMA{w}"] = s.reindex(feat.index)

    for a in ["QQQ","XLK"]:
        if f"{a}_mom1" in feat.columns and f"{a}_mom3" in feat.columns:
            feat[f"{a}_Inflect_1m3m"] = feat[f"{a}_mom1"] - feat[f"{a}_mom3"]

    if "XLK_mom6" in feat.columns and "QQQ_mom6" in feat.columns:
        feat["XLK_minus_QQQ_6M"] = feat["XLK_mom6"] - feat["QQQ_mom6"]

    for f in [
        "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m",
        "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m",
        "GLD_mom3","LQD_mom3","TLT_mom3","XLK_minus_QQQ_6M"
    ]:
        if f in feat.columns:
            feat[f"Delta_{f}_1m"] = feat[f] - feat[f].shift(1)

    ret = closes.pct_change(fill_method=None)

    def _pair_corr(frame, window, absolute=False):
        vals = []
        cols = list(frame.columns)
        for i in range(len(cols)):
            for j in range(i + 1, len(cols)):
                c = frame[cols[i]].rolling(window).corr(frame[cols[j]])
                vals.append(c.abs() if absolute else c)
        if not vals:
            return pd.Series(index=frame.index, dtype=float)
        return pd.concat(vals, axis=1).mean(axis=1)

    risk_cols = [c for c in ["QQQ","SPY","XLU","LQD"] if c in ret.columns]
    cross_cols = [c for c in ["QQQ","LQD","TLT","GLD","XLU"] if c in ret.columns]

    for name, s in {
        "RiskCorr20": _pair_corr(ret[risk_cols], 20, False),
        "CrossAssetAbsCorr20": _pair_corr(ret[cross_cols], 20, True),
    }.items():
        z = s.resample("ME").last()
        z.index = z.index.to_period("M")
        feat[name] = z.reindex(feat.index)
        feat[f"Delta_{name}_1m"] = feat[name] - feat[name].shift(1)

    if "VIX" in feat.columns:
        feat["Delta_VIX_1m"] = feat["VIX"] - feat["VIX"].shift(1)

    return feat


def _v344_era_compare(df, features):
    eras = [
        ("2011-17", pd.Period("2011-01","M"), pd.Period("2017-12","M")),
        ("2018-21", pd.Period("2018-01","M"), pd.Period("2021-12","M")),
        ("2022-26", pd.Period("2022-01","M"), pd.Period("2026-07","M")),
    ]
    rows = []
    for f in features:
        for era, lo, hi in eras:
            z = df[(df["SignalMonth"] >= lo) & (df["SignalMonth"] <= hi)]
            a = z.loc[z["PromotionLabel"].eq("100% Winner"), f].dropna()
            b = z.loc[z["PromotionLabel"].eq("75% Winner"), f].dropna()
            if len(a) < 2 or len(b) < 2:
                continue
            auc = _v334_pairwise_auc(a, b)
            rows.append({
                "Feature": f, "Era": era,
                "100% Winner median": a.median(),
                "75% Winner median": b.median(),
                "Median delta": a.median() - b.median(),
                "Raw AUC(100%>75%)": auc,
                "Directional AUC": max(auc, 1-auc),
                "100% Winner direction": "Higher" if auc >= .5 else "Lower",
                "N 100%": len(a), "N 75%": len(b),
            })
    return pd.DataFrame(rows)



