# =============================================================================
# v3.46b — Target vs v3.45 Aggression Gap Attribution FIX
#
# DIAGNOSTIC ONLY. NO NEW TRADING RULE.
#
# Goal:
#   Explain the remaining gap between the target strategy and v3.45.
#
# Main attribution questions:
#   1) Frequency gap:
#      Target is 100% Aggressive while v3.45 is not fully aggressive.
#
#   2) Asset gap:
#      Both are aggressive, but target uses a different attack asset
#      (TQQQ vs TECL / mix) than v3.45.
#
#   3) Timing gap:
#      Target enters/exits Aggressive earlier or later than v3.45.
#
#   4) Outcome attribution:
#      Which mismatch categories contribute the most realized monthly return
#      difference?
#
# Important:
#   - Diagnostic only.
#   - No threshold/lookback/filter search.
#   - Target data cutoff 2026-07 for development analysis.
#   - Existing next-open execution convention for v3.45.
# =============================================================================

def _v346_classify_target(row):
    aw = float(row.get("AggressiveWt", 0.0) or 0.0)
    dw = float(row.get("DefensiveWt", 0.0) or 0.0)

    if aw >= 0.999 and dw <= 0.001:
        return "Target 100% Aggressive"
    if dw >= 0.999 and aw <= 0.001:
        return "Target 100% Defensive"
    return "Target Mixed"


def _v346_target_primary_asset(row):
    vals = {
        "TQQQ": float(row.get("TQQQ", 0.0) or 0.0),
        "TECL": float(row.get("TECL", 0.0) or 0.0),
        "XLU": float(row.get("XLU", 0.0) or 0.0),
        "GLD": float(row.get("GLD", 0.0) or 0.0),
    }
    if not vals:
        return "Unknown"
    k = max(vals, key=vals.get)
    mx = vals[k]
    if mx <= 0:
        return "Unknown"
    # Preserve mix information where relevant.
    positive = [a for a, v in vals.items() if v > 0.001]
    if len(positive) > 1:
        return "Mixed: " + "+".join(positive)
    return k


def _v346_v345_monthly_state(
    idx, turbo_active, choose_tecl, promote, attack75, challenger, asset_ret
):
    # Build monthly exposure/state diagnostics from the actual v3.45 execution logic.
    # v3.45:
    # - Turbo + TECL leadership -> 100% TECL
    # - Turbo + no TECL leadership -> 75% TQQQ + 25% non-MOM
    # - otherwise Attack #1 baseline
    d = pd.DataFrame({
        "Turbo": turbo_active.reindex(idx).fillna(False).astype(bool),
        "ChooseTECL": choose_tecl.reindex(idx).fillna(False).astype(bool),
        "Promote100TECL": promote.reindex(idx).fillna(False).astype(bool),
        "V345Ret": challenger.reindex(idx),
        "Attack75Ret": attack75.reindex(idx),
    })

    # Approximate attack intensity state from frozen rules, not inferred from realized P&L.
    d["V345AttackWt"] = np.select(
        [
            d["Promote100TECL"],
            d["Turbo"] & ~d["Promote100TECL"],
        ],
        [1.00, 0.75],
        default=0.50,  # baseline stack keeps MOM sleeve at 50%; diagnostic label only
    )

    d["V345AttackAsset"] = np.select(
        [
            d["Promote100TECL"],
            d["Turbo"] & ~d["Promote100TECL"],
        ],
        ["TECL", "TQQQ"],
        default="Baseline Mix",
    )

    rows = []
    for p, g in d.groupby(d.index.to_period("M")):
        # Majority/maximum execution state for the month.
        promo = bool(g["Promote100TECL"].max())
        turbo = bool(g["Turbo"].max())
        if promo:
            state = "100% TECL"
            aw = 1.00
            asset = "TECL"
        elif turbo:
            state = "75% TQQQ"
            aw = 0.75
            asset = "TQQQ"
        else:
            state = "Baseline / non-Turbo"
            aw = float(g["V345AttackWt"].median())
            asset = "Baseline Mix"

        r = (1.0 + g["V345Ret"].dropna()).prod() - 1.0
        rows.append({
            "Month": p,
            "V345State": state,
            "V345AttackWt": aw,
            "V345AttackAsset": asset,
            "V345Return": r,
            "Turbo": turbo,
            "Promote100TECL": promo,
        })
    return pd.DataFrame(rows)


def _v346_transition_flags(df):
    z = df.sort_values("Month").copy()

    z["TargetAggFlag"] = z["TargetClass"].eq("Target 100% Aggressive")
    z["V345FullAggFlag"] = z["V345AttackWt"].ge(0.999)

    z["TargetAggEntry"] = z["TargetAggFlag"] & ~z["TargetAggFlag"].shift(1, fill_value=False)
    z["TargetAggExit"] = ~z["TargetAggFlag"] & z["TargetAggFlag"].shift(1, fill_value=False)

    z["V345FullAggEntry"] = z["V345FullAggFlag"] & ~z["V345FullAggFlag"].shift(1, fill_value=False)
    z["V345FullAggExit"] = ~z["V345FullAggFlag"] & z["V345FullAggFlag"].shift(1, fill_value=False)

    return z



