def _v349_pairwise_auc(a, b):
    a = pd.Series(a).dropna().astype(float).to_numpy()
    b = pd.Series(b).dropna().astype(float).to_numpy()
    if len(a) == 0 or len(b) == 0:
        return np.nan
    wins = 0.0
    total = 0
    for x in a:
        gt = np.sum(x > b)
        eq = np.sum(x == b)
        wins += gt + 0.5 * eq
        total += len(b)
    return wins / total if total else np.nan


def _v349_feature_table(events, features):
    rows = []
    for f in features:
        w = events.loc[events["OutcomeLabel"].eq("Winner"), f].dropna()
        l = events.loc[events["OutcomeLabel"].eq("Loser"), f].dropna()
        if len(w) == 0 or len(l) == 0:
            continue
        auc = _v349_pairwise_auc(w, l)
        rows.append({
            "Feature": f,
            "Winner median": w.median(),
            "Loser median": l.median(),
            "Median delta": w.median() - l.median(),
            "Raw AUC(Winner>Loser)": auc,
            "Directional AUC": max(auc, 1.0 - auc),
            "Winner direction": "Higher" if auc >= .5 else "Lower",
            "N Winner": len(w),
            "N Loser": len(l),
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out = out.sort_values("Directional AUC", ascending=False).reset_index(drop=True)
    return out


