def render_v355_final_freeze_validation(px_close, rf_bt, start, end):
    st.markdown("### 🧊 v3.55 — v3.45 Final Freeze Validation")
    st.caption(
        "新しいシグナル探索は行いません。v3.45 TECL Leadership 100% Promotionを、"
        "正式Freeze候補として実装・時間方向・rolling・CPCV・stressまで最終確認します。"
    )
    st.info(
        "Development cutoff = 2026-07-31。2026-09以降をForward OOSとして明示します。"
        "Frozen Core自体はControlとして変更せず保存します。"
    )

    if st.button("Final Freeze Validationを実行", type="primary", key="run_v355"):
        progress = st.progress(0, text="価格・Frozen stateを再構築中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(columns=[c for c in needed if c in px_close.columns]).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            closes = closes.join(get_close(tuple(missing), start, end), how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()

        ret_open = opens.pct_change(fill_method=None)
        ret_close = closes.pct_change(fill_method=None)

        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        adaptive_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = adaptive_h[model].eq("GLD")
            adaptive_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)
        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(adaptive_h, allow_l2)
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        inflect_eff = inflect_eff.reindex(idx).fillna(False).astype(bool)
        turbo = (allow_l2 & inflect_eff).reindex(idx).fillna(False).astype(bool)
        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        t1_h = _v332_apply_turbo_l3(avix_h, turbo)

        def build_returns(asset_ret):
            adaptive_ret = _portfolio_return_from_holdings_fast(adaptive_h, asset_ret)
            avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
            t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)
            _, attack = _v335_build_t2_and_attack_returns(
                avix_ret, t1_ret,
                asset_ret["TQQQ"], asset_ret["TECL"],
                turbo, choose_tecl
            )
            promo = (turbo & choose_tecl).reindex(idx).fillna(False)
            v345 = attack.copy()
            v345.loc[promo] = asset_ret["TECL"].reindex(idx).loc[promo]
            return adaptive_ret, attack, v345

        open_adaptive, open_attack, open_v345 = build_returns(ret_open)
        close_adaptive, close_attack, close_v345 = build_returns(ret_close)

        cutoff = pd.Timestamp("2026-07-31")
        primary = pd.DataFrame({
            "Adaptive ALL": open_adaptive,
            "Attack #1": open_attack,
            "v3.45": open_v345,
        }).loc[:cutoff].dropna()

        timing = pd.DataFrame({
            "Open Adaptive": open_adaptive,
            "Open Attack #1": open_attack,
            "Open v3.45": open_v345,
            "Close Adaptive": close_adaptive,
            "Close Attack #1": close_attack,
            "Close v3.45": close_v345,
        }).loc[:cutoff].dropna()

        progress.progress(24, text="Full metrics / timing sensitivityを計算中…")

        metric_rows = []
        for v in primary.columns:
            metric_rows.append(_v325_metric_row(v, primary[v]))
        metrics = pd.DataFrame(metric_rows).set_index("Variant")

        timing_rows = []
        for v in timing.columns:
            timing_rows.append(_v325_metric_row(v, timing[v]))
        timing_metrics = pd.DataFrame(timing_rows).set_index("Variant")

        exec_sens = pd.DataFrame({
            "Metric": ["CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD"],
            "Open v3.45": [timing_metrics.loc["Open v3.45", c] for c in
                           ["CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD"]],
            "Close v3.45": [timing_metrics.loc["Close v3.45", c] for c in
                            ["CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD"]],
        })
        exec_sens["Open minus Close"] = exec_sens["Open v3.45"] - exec_sens["Close v3.45"]

        progress.progress(38, text="Rolling / calendar / stressを計算中…")
        roll = _v326_rolling_p10_table(primary, list(primary.columns))
        monthly = (1.0 + primary).resample("ME").prod() - 1.0
        monthly.index = monthly.index.to_period("M")
        annual = (1.0 + primary).resample("YE").prod() - 1.0
        annual.index = annual.index.year
        annual.index.name = "Year"

        stress_windows = [
            ("2011 Jul-Oct", "2011-07-26", "2011-10-04"),
            ("2015 Jul-Aug", "2015-07-21", "2015-08-24"),
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2023 Jul-Oct", "2023-07-19", "2023-10-27"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = primary.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in primary.columns:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        progress.progress(52, text="CPCV / WF-style robustnessを計算中…")
        cpcv_attack, _ = _v326_cpcv_summary(monthly, "Attack #1", ["v3.45"])
        cpcv_base, _ = _v326_cpcv_summary(monthly, "Adaptive ALL", ["Attack #1","v3.45"])
        wf_attack = _v355_wf_blocks(monthly, "Attack #1", "v3.45", 13)
        wf_base = _v355_wf_blocks(monthly, "Adaptive ALL", "v3.45", 13)

        progress.progress(64, text="Signal / exposure auditを作成中…")
        states = pd.DataFrame({
            "GateA": gate_a,
            "VIXBrake": vix_brake,
            "AllowL2": allow_l2,
            "XLKInflect": inflect_eff,
            "Turbo": turbo,
            "ChooseTECL": choose_tecl,
            "Promotion100": turbo & choose_tecl,
        }, index=idx).loc[:cutoff]

        state_m = states.groupby(states.index.to_period("M")).max()
        signal_summary = pd.DataFrame({
            "State": ["GateA","VIXBrake","AllowL2","XLKInflect","Turbo","Promotion100"],
            "Months ON": [int(state_m[c].sum()) for c in
                          ["GateA","VIXBrake","AllowL2","XLKInflect","Turbo","Promotion100"]],
            "Share": [state_m[c].mean() for c in
                      ["GateA","VIXBrake","AllowL2","XLKInflect","Turbo","Promotion100"]],
        })

        # Effective attack state by month.
        attack_state = pd.DataFrame(index=state_m.index)
        attack_state["Intensity"] = 0.50
        attack_state["Asset"] = "Baseline"
        attack_state.loc[state_m["Turbo"], "Intensity"] = 0.75
        attack_state.loc[state_m["Turbo"], "Asset"] = np.where(
            state_m.loc[state_m["Turbo"], "ChooseTECL"], "TECL", "TQQQ"
        )
        attack_state.loc[state_m["Promotion100"], "Intensity"] = 1.00
        attack_state.loc[state_m["Promotion100"], "Asset"] = "TECL"

        exposure_summary = (
            attack_state.groupby(["Intensity","Asset"])
            .size().reset_index(name="Months")
        )
        exposure_summary["Share"] = exposure_summary["Months"] / len(attack_state)

        progress.progress(74, text="Drawdown / risk contribution proxyを確認中…")
        drawdowns = _v355_drawdown_episodes(primary["v3.45"], 12)

        # Simple realized variance contribution proxy by state.
        state_daily = states.reindex(primary.index).fillna(False)
        risk_rows = []
        for label, mask in [
            ("Turbo OFF", ~state_daily["Turbo"]),
            ("Turbo 75% TQQQ", state_daily["Turbo"] & ~state_daily["ChooseTECL"]),
            ("Promotion 100% TECL", state_daily["Promotion100"]),
        ]:
            rr = primary.loc[mask, "v3.45"].dropna()
            if len(rr):
                risk_rows.append({
                    "State": label,
                    "TradingDays": len(rr),
                    "ShareDays": len(rr)/len(primary),
                    "AnnVol": rr.std(ddof=1)*np.sqrt(252),
                    "MeanDaily": rr.mean(),
                    "VarianceShareProxy": (
                        (rr.pow(2).sum()) /
                        (primary["v3.45"].dropna().pow(2).sum())
                    ),
                })
        risk_proxy = pd.DataFrame(risk_rows)

        progress.progress(84, text="Freeze decision sheetを作成中…")
        # Compact CPCV summary.
        def compact_cpcv(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                row = {
                    "Variant": v,
                    "Folds": len(g),
                    "SortinoWins": int(g["Positive Delta Sortino"].sum()),
                    "SortinoWinRate": g["Positive Delta Sortino"].mean(),
                    "PositiveActive": int(g["Positive Active"].sum()),
                    "PositiveActiveRate": g["Positive Active"].mean(),
                    "MedianDeltaSortino": g["Delta Sortino0"].median(),
                    "P10DeltaSortino": g["Delta Sortino0"].quantile(.10),
                    "MedianActiveAnn": g["Active AnnArithmetic"].median(),
                    "P10ActiveAnn": g["Active AnnArithmetic"].quantile(.10),
                }
                if "Delta Sharpe0" in g.columns:
                    row["SharpeWins"] = int((g["Delta Sharpe0"] > 0).sum())
                    row["SharpeWinRate"] = (g["Delta Sharpe0"] > 0).mean()
                    row["MedianDeltaSharpe"] = g["Delta Sharpe0"].median()
                    row["P10DeltaSharpe"] = g["Delta Sharpe0"].quantile(.10)
                rows.append(row)
            return pd.DataFrame(rows)

        cpcv_attack_summary = compact_cpcv(cpcv_attack)
        cpcv_base_summary = compact_cpcv(cpcv_base)

        freeze_sheet = pd.DataFrame({
            "Item": [
                "Strategy",
                "Development cutoff",
                "Forward OOS start",
                "Primary execution",
                "Frozen Core status",
                "Signal tuning in v3.55",
                "v3.45 CAGR",
                "v3.45 Sortino",
                "v3.45 Sharpe",
                "v3.45 Daily MaxDD",
                "v3.45 Monthly MaxDD",
                "CPCV vs Attack #1 Sortino wins",
                "CPCV vs Attack #1 Positive Active",
                "WF vs Attack #1 wins",
            ],
            "Value": [
                "v3.45 TECL Leadership 100% Promotion",
                "2026-07-31",
                "2026-09",
                "Open -> Open",
                "Unchanged formal control",
                "None",
                metrics.loc["v3.45","CAGR"],
                metrics.loc["v3.45","Sortino0"],
                metrics.loc["v3.45","Sharpe0"],
                metrics.loc["v3.45","Daily MaxDD"],
                metrics.loc["v3.45","Monthly MaxDD"],
                (
                    f"{int(cpcv_attack['Positive Delta Sortino'].sum())}/{len(cpcv_attack)}"
                    if len(cpcv_attack) else "N/A"
                ),
                (
                    f"{int(cpcv_attack['Positive Active'].sum())}/{len(cpcv_attack)}"
                    if len(cpcv_attack) else "N/A"
                ),
                (
                    f"{int(wf_attack['v3.45 Win'].sum())}/{len(wf_attack)}"
                    if len(wf_attack) else "N/A"
                ),
            ]
        })

        progress.progress(92, text="結果を表示中…")
        st.markdown("#### 1) Freeze decision sheet")
        st.dataframe(freeze_sheet, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Open→Open full metrics")
        st.dataframe(metrics.round(6), use_container_width=True)

        st.markdown("#### 3) Open vs Close execution sensitivity")
        st.dataframe(exec_sens.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 4) Rolling CAGR P10")
        st.dataframe(roll.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 5) CPCV — v3.45 vs Attack #1")
        st.dataframe(cpcv_attack_summary.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 6) CPCV — Attack / v3.45 vs Adaptive ALL")
        st.dataframe(cpcv_base_summary.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 7) WF-style chronological blocks — v3.45 vs Attack #1")
        st.dataframe(wf_attack.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 8) Fixed stress windows")
        st.dataframe(stress.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 9) Calendar-year returns")
        st.dataframe(annual.round(6), use_container_width=True)

        st.markdown("#### 10) Signal frequency")
        st.dataframe(signal_summary.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 11) Effective attack exposure")
        st.dataframe(exposure_summary.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 12) Risk contribution proxy by state")
        st.dataframe(risk_proxy.round(6), hide_index=True, use_container_width=True)

        st.markdown("#### 13) Largest drawdown episodes")
        st.dataframe(drawdowns.round(6), hide_index=True, use_container_width=True)

        st.success(
            "v3.55はValidation専用です。数値を確認後、v3.45をFreezeするか判断します。"
            "2026-09以降のデータは開発・再最適化に戻さずForward OOSとして扱います。"
        )

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            files = {
                "00_freeze_decision_sheet.csv": freeze_sheet,
                "01_open_full_metrics.csv": metrics.reset_index(),
                "02_timing_all_metrics.csv": timing_metrics.reset_index(),
                "03_execution_sensitivity.csv": exec_sens,
                "04_rolling_p10.csv": roll,
                "05_cpcv_v345_vs_attack_detail.csv": cpcv_attack,
                "06_cpcv_v345_vs_attack_summary.csv": cpcv_attack_summary,
                "07_cpcv_vs_adaptive_detail.csv": cpcv_base,
                "08_cpcv_vs_adaptive_summary.csv": cpcv_base_summary,
                "09_wf_v345_vs_attack.csv": wf_attack,
                "10_wf_v345_vs_adaptive.csv": wf_base,
                "11_stress_windows.csv": stress,
                "12_calendar_year_returns.csv": annual.reset_index(),
                "13_signal_frequency.csv": signal_summary,
                "14_attack_exposure.csv": exposure_summary,
                "15_risk_proxy.csv": risk_proxy,
                "16_drawdown_episodes.csv": drawdowns,
                "17_monthly_returns.csv": monthly.reset_index(),
                "18_attack_state_monthly.csv": attack_state.reset_index(),
            }
            for name, df in files.items():
                z.writestr(name, df.to_csv(index=False).encode("utf-8-sig"))

            z.writestr(
                "README_FREEZE.txt",
                (
                    "v3.55 FINAL FREEZE VALIDATION\n"
                    "Strategy: v3.45 TECL Leadership 100% Promotion\n"
                    "Development cutoff: 2026-07-31\n"
                    "Forward OOS start: 2026-09\n"
                    "Primary execution: Open -> Open\n"
                    "Frozen Core remains unchanged formal control.\n"
                    "No signal optimization or new rule was performed in v3.55.\n"
                ).encode("utf-8")
            )

        st.markdown("#### 14) 保存")
        st.download_button(
            "📦 v3.55 Final Freeze Validation（ZIP）",
            data=buf.getvalue(),
            file_name="v345_final_freeze_validation_v355.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v355",
        )


def render_v354_turbo_off_attack_opportunity_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🔬 v3.54 — Turbo-OFF Attack Opportunity Autopsy")
    st.caption(
        "Target戦略は使わず、v3.45のTurbo OFF月すべてを母集団にして、"
        "実際に攻撃を追加したら翌月リターンが改善したかを直接調べます。"
    )
    st.info(
        "診断専用です。Outcomeは実現リターンから作るpost-hocラベルで、"
        "そのまま売買ルールにはしません。閾値・lookback・AND/OR探索も行いません。"
    )

    if st.button("Turbo-OFF Attack Opportunityを解析", type="primary", key="run_v354"):
        progress = st.progress(0, text="Frozen v3.45 / price seriesを再構築中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            closes = closes.join(
                get_close(tuple(missing), start, end),
                how="outer"
            ).sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)

        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(base_h, allow_l2)

        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        inflect_eff = inflect_eff.reindex(idx).fillna(False).astype(bool)
        turbo = (allow_l2 & inflect_eff).reindex(idx).fillna(False).astype(bool)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        # Frozen v3.45 returns.
        t1_h = _v332_apply_turbo_l3(avix_h, turbo)
        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)
        _, attack75 = _v335_build_t2_and_attack_returns(
            avix_ret, t1_ret,
            asset_ret["TQQQ"], asset_ret["TECL"],
            turbo, choose_tecl,
        )
        promote100 = (turbo & choose_tecl).reindex(idx).fillna(False)
        v345 = attack75.copy()
        v345.loc[promote100] = asset_ret["TECL"].reindex(idx).loc[promote100]

        nonmom = _v348_nonmom_normalized_return(avix_h, asset_ret).reindex(idx)
        tq = asset_ret["TQQQ"].reindex(idx)
        te = asset_ret["TECL"].reindex(idx)

        # Hypothetical attack actions, daily return series.
        hyp75_tqqq = .75*tq + .25*nonmom
        hyp75_tecl = .75*te + .25*nonmom
        hyp100_tqqq = tq.copy()
        hyp100_tecl = te.copy()

        progress.progress(30, text="Turbo-OFF execution monthsを作成中…")

        # Collapse by execution month. Require Turbo OFF for the month.
        state_d = pd.DataFrame({
            "Turbo": turbo,
            "GateA": gate_a,
            "VIXBrake": vix_brake,
            "AllowL2": allow_l2,
            "XLKInflect": inflect_eff,
            "ChooseTECL": choose_tecl,
        }, index=idx)

        month_state = state_d.groupby(state_d.index.to_period("M")).agg({
            "Turbo":"max",
            "GateA":"max",
            "VIXBrake":"max",
            "AllowL2":"max",
            "XLKInflect":"max",
            "ChooseTECL":"max",
        })

        ret_frame = pd.DataFrame({
            "Control": v345,
            "75% TQQQ": hyp75_tqqq,
            "75% TECL": hyp75_tecl,
            "100% TQQQ": hyp100_tqqq,
            "100% TECL": hyp100_tecl,
        }, index=idx)

        monthly_ret = (1.0 + ret_frame).resample("ME").prod() - 1.0
        monthly_ret.index = monthly_ret.index.to_period("M")

        # Dev cutoff and common months.
        dev_months = monthly_ret.index[
            monthly_ret.index <= pd.Period("2026-07","M")
        ]
        monthly_ret = monthly_ret.reindex(dev_months)
        month_state = month_state.reindex(dev_months)

        events = monthly_ret.join(month_state, how="inner")
        events = events[~events["Turbo"].fillna(False).astype(bool)].copy()
        events["SignalMonth"] = events.index - 1

        for c in ["75% TQQQ","75% TECL","100% TQQQ","100% TECL"]:
            events[f"Active {c}"] = events[c] - events["Control"]

        action_cols = ["75% TQQQ","75% TECL","100% TQQQ","100% TECL"]
        active_cols = [f"Active {c}" for c in action_cols]
        active_matrix = events[active_cols]
        best_active_col = active_matrix.idxmax(axis=1)
        events["BestAction"] = best_active_col.str.replace("Active ","", regex=False)
        events["BestActive"] = active_matrix.max(axis=1)
        events["AttackOpportunity"] = events["BestActive"] > 0
        events["OpportunityLabel"] = np.where(
            events["AttackOpportunity"], "Opportunity", "No Opportunity"
        )

        # Also label preferred intensity/asset family post-hoc.
        events["BestIntensity"] = np.where(
            events["BestAction"].str.startswith("100%"), "100%", "75%"
        )
        events["BestAsset"] = np.where(
            events["BestAction"].str.contains("TECL"), "TECL", "TQQQ"
        )

        progress.progress(46, text="Frozen featuresを付与中…")
        feat = _v347_prepare_features(closes)

        for i, r in events.iterrows():
            sm = r["SignalMonth"]
            if sm in feat.index:
                fr = feat.loc[sm]
                for c in feat.columns:
                    events.loc[i, c] = fr.get(c, np.nan)

        features = [c for c in [
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "XLK_Inflect_1m3m","XLK_SMA100","XLK_SMA200",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
            "Delta_QQQ_mom3_1m","Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_mom3_1m","Delta_XLK_Inflect_1m3m_1m",
            "Delta_TLT_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_GLD_mom3_1m","Delta_XLK_minus_QQQ_6M_1m",
        ] if c in events.columns]

        cmp = _v354_compare_groups(
            events, "OpportunityLabel",
            "Opportunity", "No Opportunity",
            features
        )
        era = _v354_era_stability(
            events, "OpportunityLabel",
            "Opportunity", "No Opportunity",
            features
        )

        if not cmp.empty:
            stability = []
            for _, r in cmp.iterrows():
                g = era[era["Feature"].eq(r["Feature"])]
                full_dir = r["Opportunity direction"]
                stability.append(
                    f"{int(g['Opportunity direction'].eq(full_dir).sum())}/{len(g)}"
                    if len(g) else "0/0"
                )
            cmp["Era same direction"] = stability

        progress.progress(60, text="Outcome / intensity / assetを集計中…")

        summary = pd.DataFrame({
            "Measure": [
                "Turbo-OFF months",
                "Attack Opportunity months",
                "Opportunity rate",
                "Median best active",
                "Mean best active",
                "P10 best active",
                "100% best-action share",
                "TECL best-action share",
            ],
            "Value": [
                len(events),
                int(events["AttackOpportunity"].sum()),
                f"{events['AttackOpportunity'].mean()*100:.1f}%",
                f"{events['BestActive'].median()*100:+.2f}%",
                f"{events['BestActive'].mean()*100:+.2f}%",
                f"{events['BestActive'].quantile(.10)*100:+.2f}%",
                f"{events['BestIntensity'].eq('100%').mean()*100:.1f}%",
                f"{events['BestAsset'].eq('TECL').mean()*100:.1f}%",
            ]
        })

        action_summary_rows = []
        for a in action_cols:
            s = events[f"Active {a}"].dropna()
            action_summary_rows.append({
                "Action": a,
                "Months": len(s),
                "PositiveActive": int((s>0).sum()),
                "PositiveRate": (s>0).mean(),
                "MedianActive": s.median(),
                "MeanActive": s.mean(),
                "P10Active": s.quantile(.10),
                "P90Active": s.quantile(.90),
            })
        action_summary = pd.DataFrame(action_summary_rows)

        best_action_summary = (
            events.groupby("BestAction")
            .agg(
                Months=("BestAction","size"),
                MedianBestActive=("BestActive","median"),
                MeanBestActive=("BestActive","mean"),
            )
            .reset_index()
            .sort_values("Months", ascending=False)
        )

        # Separate opportunity diagnostics for intensity and asset preference.
        opp = events[events["AttackOpportunity"]].copy()
        intensity_cmp = pd.DataFrame()
        asset_cmp = pd.DataFrame()
        if len(opp) >= 6 and opp["BestIntensity"].nunique() == 2:
            intensity_cmp = _v354_compare_groups(
                opp, "BestIntensity", "100%", "75%", features
            )
        if len(opp) >= 6 and opp["BestAsset"].nunique() == 2:
            asset_cmp = _v354_compare_groups(
                opp, "BestAsset", "TECL", "TQQQ", features
            )

        # Lead-up paths for opportunity vs no-opportunity.
        lead_features = [c for c in [
            "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100",
            "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in feat.columns]

        lead_rows = []
        for klass in ["Opportunity","No Opportunity"]:
            months = events.loc[events["OpportunityLabel"].eq(klass), "SignalMonth"].tolist()
            for lag in [-2,-1,0]:
                for f in lead_features:
                    vals = []
                    for m in months:
                        mm = m + lag
                        if mm in feat.index and pd.notna(feat.loc[mm, f]):
                            vals.append(float(feat.loc[mm, f]))
                    if vals:
                        lead_rows.append({
                            "Class": klass,
                            "LagMonths": lag,
                            "Feature": f,
                            "Median": float(np.median(vals)),
                            "N": len(vals),
                        })
        leadup = pd.DataFrame(lead_rows)

        # Biggest positive/negative opportunity months.
        best_months = events.nlargest(20, "BestActive").copy()
        worst_months = events.nsmallest(20, "BestActive").copy()

        progress.progress(80, text="結果を表示中…")

        st.markdown("#### 1) Turbo-OFF opportunity summary")
        st.dataframe(summary, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Each hypothetical attack action")
        ash = action_summary.copy()
        for c in ["PositiveRate","MedianActive","MeanActive","P10Active","P90Active"]:
            if c == "PositiveRate":
                ash[c] = ash[c].map(lambda x: f"{x*100:.1f}%")
            else:
                ash[c] = ash[c].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(ash, hide_index=True, use_container_width=True)

        st.markdown("#### 3) Post-hoc best action frequency")
        bsh = best_action_summary.copy()
        for c in ["MedianBestActive","MeanBestActive"]:
            bsh[c] = bsh[c].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(bsh, hide_index=True, use_container_width=True)

        st.markdown("#### 4) Opportunity vs No Opportunity — fixed features")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 6) Lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 7) Within Opportunity: 100% vs 75%")
        st.dataframe(intensity_cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 8) Within Opportunity: TECL vs TQQQ")
        st.dataframe(asset_cmp.round(4), hide_index=True, use_container_width=True)

        display_cols = [c for c in [
            "Control","75% TQQQ","75% TECL","100% TQQQ","100% TECL",
            "BestAction","BestActive","OpportunityLabel",
            "GateA","VIXBrake","AllowL2","XLKInflect","ChooseTECL",
            "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3","VIX",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in events.columns]

        st.markdown("#### 9) Strongest missed attack opportunities")
        st.dataframe(
            best_months[display_cols].round(4),
            use_container_width=True
        )

        st.markdown("#### 10) Worst months for adding attack")
        st.dataframe(
            worst_months[display_cols].round(4),
            use_container_width=True
        )

        audit = events.copy()
        audit.index = audit.index.astype(str)
        audit.index.name = "Month"

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_turbo_off_opportunity_summary.csv",
                summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_action_summary.csv",
                action_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_best_action_frequency.csv",
                best_action_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_opportunity_feature_discrimination.csv",
                cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_opportunity_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_opportunity_leadup_path.csv",
                leadup.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_intensity_100_vs_75.csv",
                intensity_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_asset_tecl_vs_tqqq.csv",
                asset_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_best_opportunity_months.csv",
                best_months.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "10_worst_attack_months.csv",
                worst_months.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "11_event_audit.csv",
                audit.to_csv().encode("utf-8-sig")
            )

        st.markdown("#### 11) 保存")
        st.download_button(
            "📦 v3.54 Turbo-OFF Attack Opportunity Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="turbo_off_attack_opportunity_autopsy_v354.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v354",
        )
        st.caption(
            "Targetを使わず、実現リターンだけでSecond Attack候補の市場状態を診断します。"
            "ここでも安定構造が弱ければ、v3.45 Freezeを強く支持します。"
        )


def render_v353_second_attack_entry_trigger_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🚦 v3.53 — Second Attack Entry Trigger Autopsy")
    st.caption(
        "v3.52で見つかったMissed Entryだけを対象に、"
        "既存シグナル・自然境界の『状態遷移』で説明できるかを調べます。"
    )
    st.info(
        "診断専用です。VIX>19やSMA距離<7%のような後付け閾値は作りません。"
        "0クロス、ON→OFF、OFF→ON、SMA跨ぎなど既存/自然な遷移だけを使います。"
    )

    if st.button("Second Attack Entry Triggerを解析", type="primary", key="run_v353"):
        progress = st.progress(0, text="Target / v3.45 / feature stateを再構築中…")

        # ---------------------------------------------------------------------
        # Rebuild exact v3.52 Missed Entry mother set
        # ---------------------------------------------------------------------
        target = _v330_normalize_target_table(_v330_find_target_monthly_table())
        target = target[target["Month"] <= pd.Period("2026-07","M")].copy()
        target = target.sort_values("Month").reset_index(drop=True)
        target["TargetAggressive"] = (
            pd.to_numeric(target["AggressiveWt"], errors="coerce").fillna(0) >= 99.9
        ) & (
            pd.to_numeric(target["DefensiveWt"], errors="coerce").fillna(0) <= .1
        )
        target["PriorTargetAggressive"] = target["TargetAggressive"].shift(1, fill_value=False)

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(columns=[c for c in needed if c in px_close.columns]).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            closes = closes.join(
                get_close(tuple(missing), start, end),
                how="outer"
            ).sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()

        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)

        allow_l2 = gate_a & ~vix_brake

        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        inflect_eff = inflect_eff.reindex(idx).fillna(False).astype(bool)

        turbo = (allow_l2 & inflect_eff).reindex(idx).fillna(False).astype(bool)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        # execution-month state
        state_d = pd.DataFrame({
            "GateA": gate_a.astype(bool),
            "VIXBrake": vix_brake.astype(bool),
            "AllowL2": allow_l2.astype(bool),
            "XLKInflect": inflect_eff.astype(bool),
            "Turbo": turbo.astype(bool),
            "ChooseTECL": choose_tecl.astype(bool),
        }, index=idx)

        state_m = state_d.groupby(state_d.index.to_period("M")).agg({
            "GateA":"max",
            "VIXBrake":"max",
            "AllowL2":"max",
            "XLKInflect":"max",
            "Turbo":"max",
            "ChooseTECL":"max",
        })
        state_m["V345AttackWt"] = .50
        state_m.loc[state_m["Turbo"], "V345AttackWt"] = .75
        state_m.loc[state_m["Turbo"] & state_m["ChooseTECL"], "V345AttackWt"] = 1.00
        state_m = state_m.reset_index(names="Month")

        x = target.merge(
            state_m[[
                "Month","GateA","VIXBrake","AllowL2",
                "XLKInflect","Turbo","ChooseTECL","V345AttackWt"
            ]],
            on="Month", how="inner"
        )
        x["Captured"] = x["V345AttackWt"] >= .75

        missed_entry = x[
            x["TargetAggressive"] &
            ~x["PriorTargetAggressive"] &
            ~x["Captured"]
        ].copy()
        missed_entry["SignalMonth"] = missed_entry["Month"] - 1

        if len(missed_entry) == 0:
            raise RuntimeError("v3.53 sanity check failed: no Missed Entry events.")

        progress.progress(22, text="自然境界・既存遷移を構築中…")

        # ---------------------------------------------------------------------
        # Monthly features aligned to signal month
        # ---------------------------------------------------------------------
        feat = _v347_prepare_features(closes).copy()

        # Add monthly close / SMA state directly from prices where possible.
        me = closes.resample("ME").last()
        me.index = me.index.to_period("M")

        for a in ["QQQ","XLK"]:
            if a in me.columns:
                px = me[a]
                sma100 = closes[a].rolling(100, min_periods=100).mean().resample("ME").last()
                sma200 = closes[a].rolling(200, min_periods=200).mean().resample("ME").last()
                sma100.index = sma100.index.to_period("M")
                sma200.index = sma200.index.to_period("M")
                feat[f"{a}_AboveSMA100"] = (px.reindex(feat.index) > sma100.reindex(feat.index))
                feat[f"{a}_AboveSMA200"] = (px.reindex(feat.index) > sma200.reindex(feat.index))

        # Existing numeric series from frozen feature builder
        transitions = pd.DataFrame(index=feat.index)

        if "TLT_mom3" in feat.columns:
            transitions["TLT3M <=0 -> >0"] = _v353_num_cross_up_zero(feat["TLT_mom3"])
            transitions["TLT3M >=0 -> <0"] = _v353_num_cross_down_zero(feat["TLT_mom3"])

        if "LQD_mom3" in feat.columns:
            transitions["LQD3M <=0 -> >0"] = _v353_num_cross_up_zero(feat["LQD_mom3"])
            transitions["LQD3M >=0 -> <0"] = _v353_num_cross_down_zero(feat["LQD_mom3"])

        if "GLD_mom3" in feat.columns:
            transitions["GLD3M <=0 -> >0"] = _v353_num_cross_up_zero(feat["GLD_mom3"])
            transitions["GLD3M >=0 -> <0"] = _v353_num_cross_down_zero(feat["GLD_mom3"])

        # Map monthly states from execution month back to prior signal month.
        state_sig = state_m.copy()
        state_sig["SignalMonth"] = state_sig["Month"] - 1
        state_sig = state_sig.set_index("SignalMonth")

        for c, label in [
            ("GateA","A gate OFF -> ON"),
            ("AllowL2","AllowL2 OFF -> ON"),
            ("XLKInflect","XLK inflection False -> True"),
            ("Turbo","Turbo OFF -> ON"),
            ("ChooseTECL","TECL selector OFF -> ON"),
        ]:
            s = state_sig[c].reindex(feat.index).fillna(False).astype(bool)
            transitions[label] = _v353_bool_cross_up(s)

        sbr = state_sig["VIXBrake"].reindex(feat.index).fillna(False).astype(bool)
        transitions["VIX30 Brake ON -> OFF"] = _v353_bool_cross_down(sbr)
        transitions["VIX30 Brake OFF -> ON"] = _v353_bool_cross_up(sbr)

        for a in ["QQQ","XLK"]:
            for n in [100,200]:
                c = f"{a}_AboveSMA{n}"
                if c in feat.columns:
                    s = feat[c].fillna(False).astype(bool)
                    transitions[f"{a} below -> above SMA{n}"] = _v353_bool_cross_up(s)
                    transitions[f"{a} above -> below SMA{n}"] = _v353_bool_cross_down(s)

        if "CrossAssetAbsCorr20" in feat.columns:
            transitions["CrossAssetCorr turn up"] = _v353_direction_turn_up(feat["CrossAssetAbsCorr20"])
            transitions["CrossAssetCorr turn down"] = _v353_direction_turn_down(feat["CrossAssetAbsCorr20"])

        if "RiskCorr20" in feat.columns:
            transitions["RiskCorr turn up"] = _v353_direction_turn_up(feat["RiskCorr20"])
            transitions["RiskCorr turn down"] = _v353_direction_turn_down(feat["RiskCorr20"])

        # ---------------------------------------------------------------------
        # Event coverage within signal month / prior 1 / prior 2 months
        # ---------------------------------------------------------------------
        event_rows = []
        for _, r in missed_entry.iterrows():
            sm = r["SignalMonth"]
            row = {
                "TargetMonth": str(r["Month"]),
                "SignalMonth": str(sm),
                "TargetReturn": r.get("TargetReturn", np.nan),
            }
            for tname in transitions.columns:
                vals = []
                hits = []
                for lag in [0,-1,-2]:
                    mm = sm + lag
                    hit = bool(transitions.loc[mm, tname]) if mm in transitions.index and pd.notna(transitions.loc[mm, tname]) else False
                    vals.append(hit)
                    if hit:
                        hits.append(lag)
                row[f"{tname} | M0"] = vals[0]
                row[f"{tname} | M-1"] = vals[1]
                row[f"{tname} | M-2"] = vals[2]
                row[f"{tname} | Any0to2"] = any(vals)
                row[f"{tname} | NearestLag"] = (
                    max(hits) if hits else np.nan
                )
            event_rows.append(row)

        event_audit = pd.DataFrame(event_rows)

        # ---------------------------------------------------------------------
        # Summary: coverage + descriptive event frequency / precision
        # ---------------------------------------------------------------------
        summary_rows = []
        dev_months = transitions.index[
            (transitions.index >= pd.Period("2013-01","M")) &
            (transitions.index <= pd.Period("2026-06","M"))
        ]

        event_signal_months = set(missed_entry["SignalMonth"].tolist())
        for tname in transitions.columns:
            hit_months = set(transitions.index[transitions[tname].fillna(False)].tolist())
            covered0 = sum(sm in hit_months for sm in event_signal_months)

            covered_any = 0
            nearest = []
            for sm in event_signal_months:
                h = []
                for lag in [0,-1,-2]:
                    mm = sm + lag
                    if mm in hit_months:
                        h.append(lag)
                if h:
                    covered_any += 1
                    nearest.append(max(h))

            all_hits = [m for m in dev_months if bool(transitions.loc[m, tname])]
            entry_related_hit_months = 0
            for hm in all_hits:
                # A hit is considered associated if a Missed Entry signal month occurs
                # at hm, hm+1, or hm+2 (same 0-2 month window).
                if any((hm + k) in event_signal_months for k in [0,1,2]):
                    entry_related_hit_months += 1

            summary_rows.append({
                "Transition": tname,
                "Missed Entry events": len(event_signal_months),
                "Covered M0": covered0,
                "Coverage M0": covered0 / len(event_signal_months),
                "Covered Any M0..M-2": covered_any,
                "Coverage Any M0..M-2": covered_any / len(event_signal_months),
                "Median nearest lag": (
                    float(np.median(nearest)) if len(nearest) else np.nan
                ),
                "All transition hits": len(all_hits),
                "Entry-related transition hits": entry_related_hit_months,
                "Descriptive hit precision": (
                    entry_related_hit_months / len(all_hits)
                    if len(all_hits) else np.nan
                ),
            })

        summary = pd.DataFrame(summary_rows).sort_values(
            ["Coverage Any M0..M-2","Descriptive hit precision","All transition hits"],
            ascending=[False,False,True]
        ).reset_index(drop=True)

        # ---------------------------------------------------------------------
        # Event-level state path of key raw features
        # ---------------------------------------------------------------------
        key_raw = [c for c in [
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","QQQ_mom3","QQQ_mom6","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom3","XLK_mom6","XLK_SMA100","XLK_SMA200",
            "XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "CrossAssetAbsCorr20","RiskCorr20"
        ] if c in feat.columns]

        path_rows = []
        for _, r in missed_entry.iterrows():
            sm = r["SignalMonth"]
            for lag in [-2,-1,0]:
                mm = sm + lag
                row = {
                    "TargetMonth": str(r["Month"]),
                    "SignalMonth": str(sm),
                    "LagMonths": lag,
                    "FeatureMonth": str(mm),
                    "TargetReturn": r.get("TargetReturn", np.nan),
                }
                if mm in feat.index:
                    for c in key_raw:
                        row[c] = feat.loc[mm, c]
                path_rows.append(row)
        raw_path = pd.DataFrame(path_rows)

        # ---------------------------------------------------------------------
        # Month-by-month compact trigger matrix
        # ---------------------------------------------------------------------
        compact_cols = []
        preferred = [
            "TLT3M <=0 -> >0",
            "LQD3M <=0 -> >0",
            "VIX30 Brake ON -> OFF",
            "A gate OFF -> ON",
            "AllowL2 OFF -> ON",
            "XLK inflection False -> True",
            "Turbo OFF -> ON",
            "QQQ below -> above SMA100",
            "QQQ below -> above SMA200",
            "XLK below -> above SMA100",
            "XLK below -> above SMA200",
            "CrossAssetCorr turn down",
            "RiskCorr turn down",
        ]
        for p in preferred:
            c = f"{p} | Any0to2"
            if c in event_audit.columns:
                compact_cols.append(c)

        compact = event_audit[[
            "TargetMonth","SignalMonth","TargetReturn"
        ] + compact_cols].copy()

        # ---------------------------------------------------------------------
        # Also show exact current/prior frozen state for each event
        # ---------------------------------------------------------------------
        state_rows = []
        state_sig_full = state_sig.reindex(feat.index)
        for _, r in missed_entry.iterrows():
            sm = r["SignalMonth"]
            for lag in [-2,-1,0]:
                mm = sm + lag
                row = {
                    "TargetMonth": str(r["Month"]),
                    "SignalMonth": str(sm),
                    "LagMonths": lag,
                    "FeatureMonth": str(mm),
                }
                if mm in state_sig_full.index:
                    for c in ["GateA","VIXBrake","AllowL2","XLKInflect","Turbo","ChooseTECL"]:
                        row[c] = state_sig_full.loc[mm, c]
                state_rows.append(row)
        state_path = pd.DataFrame(state_rows)

        progress.progress(76, text="結果を表示中…")

        st.markdown("#### 1) Natural transition coverage")
        sshow = summary.copy()
        for c in ["Coverage M0","Coverage Any M0..M-2","Descriptive hit precision"]:
            if c in sshow.columns:
                sshow[c] = sshow[c].map(
                    lambda x: "—" if pd.isna(x) else f"{x*100:.1f}%"
                )
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Missed Entry × natural trigger matrix")
        st.dataframe(compact, hide_index=True, use_container_width=True)

        st.markdown("#### 3) Exact event audit")
        st.dataframe(event_audit, hide_index=True, use_container_width=True)

        st.markdown("#### 4) Raw feature path (-2M → signal month)")
        st.dataframe(raw_path.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Frozen state path")
        st.dataframe(state_path, hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_natural_transition_coverage.csv",
                summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_missed_entry_trigger_matrix.csv",
                compact.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_event_audit_full.csv",
                event_audit.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_raw_feature_path.csv",
                raw_path.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_frozen_state_path.csv",
                state_path.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_transition_monthly_series.csv",
                transitions.astype(int).to_csv().encode("utf-8-sig")
            )

        st.markdown("#### 6) 保存")
        st.download_button(
            "📦 v3.53 Second Attack Entry Trigger Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="second_attack_entry_trigger_autopsy_v353.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v353",
        )
        st.caption(
            "自然な既存遷移だけでMissed Entryを十分説明できる場合のみ、"
            "次に一発のSecond Attack Entry Challengerを検討します。"
        )


def render_v352_missed_entry_vs_continuation(px_close, rf_bt, start, end):
    st.markdown("### 🧭 v3.52 — Missed Aggressive Entry vs Continuation Autopsy")
    st.caption(
        "v3.51のMissed Aggressive月だけを、Target Aggressive runの"
        "『Entryを丸ごと逃した月』と『run途中のContinuationを逃した月』に分解します。"
    )
    st.info(
        "診断専用です。Targetはラベルにしか使いません。"
        "新しい売買ルール・閾値・lookback・AND/OR探索はありません。"
    )

    if st.button("Entry vs Continuationを解析", type="primary", key="run_v352"):
        progress = st.progress(0, text="Target / v3.45 stateを再構築中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())
        target = target[target["Month"] <= pd.Period("2026-07","M")].copy()
        target = target.sort_values("Month").reset_index(drop=True)
        target["TargetAggressive"] = (
            pd.to_numeric(target["AggressiveWt"], errors="coerce").fillna(0) >= 99.9
        ) & (
            pd.to_numeric(target["DefensiveWt"], errors="coerce").fillna(0) <= .1
        )
        target["PriorTargetAggressive"] = target["TargetAggressive"].shift(1, fill_value=False)

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(columns=[c for c in needed if c in px_close.columns]).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            closes = closes.join(get_close(tuple(missing), start, end), how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()

        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)
        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)
        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo = (allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)).fillna(False)
        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        sm = pd.DataFrame({"Turbo":turbo, "ChooseTECL":choose_tecl}, index=idx)
        sm = sm.groupby(sm.index.to_period("M")).agg({"Turbo":"max","ChooseTECL":"max"})
        sm["V345AttackWt"] = .50
        sm.loc[sm["Turbo"], "V345AttackWt"] = .75
        sm.loc[sm["Turbo"] & sm["ChooseTECL"], "V345AttackWt"] = 1.00
        sm = sm.reset_index(names="Month")

        x = target.merge(sm[["Month","V345AttackWt","Turbo","ChooseTECL"]], on="Month", how="inner")
        x["Captured"] = x["V345AttackWt"] >= .75

        # Target aggressive run IDs and run age.
        run_id = 0
        age = 0
        run_ids, ages = [], []
        for flag in x["TargetAggressive"].tolist():
            if flag:
                if age == 0:
                    run_id += 1
                age += 1
                run_ids.append(run_id)
                ages.append(age)
            else:
                age = 0
                run_ids.append(np.nan)
                ages.append(np.nan)
        x["TargetAggRun"] = run_ids
        x["RunAgeMonth"] = ages

        # Track whether v3.45 had already captured earlier in same Target run.
        prior_capture_flags = []
        months_since_capture = []
        for _, r in x.iterrows():
            if not bool(r["TargetAggressive"]):
                prior_capture_flags.append(False)
                months_since_capture.append(np.nan)
                continue
            rid = r["TargetAggRun"]
            m = r["Month"]
            prior = x[
                (x["TargetAggRun"].eq(rid)) &
                (x["Month"] < m) &
                (x["Captured"])
            ]
            prior_capture_flags.append(len(prior) > 0)
            if len(prior):
                lastm = prior["Month"].max()
                months_since_capture.append(m.ordinal - lastm.ordinal)
            else:
                months_since_capture.append(np.nan)

        x["PreviouslyCapturedInRun"] = prior_capture_flags
        x["MonthsSinceLastCapture"] = months_since_capture

        events = x[x["TargetAggressive"] & ~x["Captured"]].copy()
        events["MissType"] = np.where(
            ~events["PriorTargetAggressive"],
            "Missed Entry",
            "Missed Continuation"
        )
        events["SignalMonth"] = events["Month"] - 1

        if events["MissType"].nunique() < 2:
            raise RuntimeError("v3.52 sanity check failed: both miss types not available.")

        progress.progress(32, text="Frozen特徴を付与中…")
        feat = _v347_prepare_features(closes)
        for i, r in events.iterrows():
            smonth = r["SignalMonth"]
            if smonth in feat.index:
                fr = feat.loc[smonth]
                for c in feat.columns:
                    events.loc[i, c] = fr.get(c, np.nan)

        features = [c for c in [
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "XLK_Inflect_1m3m","XLK_SMA100","XLK_SMA200",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
            "Delta_QQQ_mom3_1m","Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_mom3_1m","Delta_XLK_Inflect_1m3m_1m",
            "Delta_TLT_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_GLD_mom3_1m","Delta_XLK_minus_QQQ_6M_1m",
        ] if c in events.columns]

        cmp = _v352_compare(events, features)
        era = _v352_era(events, features)
        if not cmp.empty:
            ss = []
            for _, r in cmp.iterrows():
                g = era[era["Feature"].eq(r["Feature"])]
                ss.append(
                    f"{int(g['Entry direction'].eq(r['Entry direction']).sum())}/{len(g)}"
                    if len(g) else "0/0"
                )
            cmp["Era same direction"] = ss

        progress.progress(52, text="Entry / Continuation構造を集計中…")
        summary = (
            events.groupby("MissType")
            .agg(
                Months=("Month","size"),
                AvgTargetReturn=("TargetReturn","mean"),
                MedianTargetReturn=("TargetReturn","median"),
                PositiveMonths=("TargetReturn", lambda s: int((s>0).sum())),
                MedianRunAge=("RunAgeMonth","median"),
                PreviouslyCaptured=("PreviouslyCapturedInRun", lambda s: int(s.sum())),
            )
            .reset_index()
        )
        summary["PositiveRate"] = summary["PositiveMonths"] / summary["Months"]

        # Continuation substructure: never captured in run vs dropped after capture.
        cont = events[events["MissType"].eq("Missed Continuation")].copy()
        cont["ContinuationSubtype"] = np.where(
            cont["PreviouslyCapturedInRun"],
            "Dropped after earlier v3.45 capture",
            "Never captured earlier in Target run"
        )
        cont_summary = (
            cont.groupby("ContinuationSubtype")
            .agg(
                Months=("Month","size"),
                AvgTargetReturn=("TargetReturn","mean"),
                MedianTargetReturn=("TargetReturn","median"),
                PositiveMonths=("TargetReturn", lambda s: int((s>0).sum())),
                MedianRunAge=("RunAgeMonth","median"),
                MedianMonthsSinceCapture=("MonthsSinceLastCapture","median"),
            )
            .reset_index()
        )
        if len(cont_summary):
            cont_summary["PositiveRate"] = cont_summary["PositiveMonths"] / cont_summary["Months"]

        # Lead-up paths.
        lead_features = [c for c in [
            "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100",
            "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in feat.columns]

        lead_rows = []
        for klass in ["Missed Entry","Missed Continuation"]:
            months = events.loc[events["MissType"].eq(klass), "SignalMonth"].tolist()
            for lag in [-2,-1,0]:
                for f in lead_features:
                    vals = []
                    for m in months:
                        mm = m + lag
                        if mm in feat.index and pd.notna(feat.loc[mm, f]):
                            vals.append(float(feat.loc[mm, f]))
                    if vals:
                        lead_rows.append({
                            "Class":klass, "LagMonths":lag, "Feature":f,
                            "Median":float(np.median(vals)), "N":len(vals)
                        })
        leadup = pd.DataFrame(lead_rows)

        # Run-level missed entry / continuation coverage.
        run_summary = (
            events.groupby("TargetAggRun")
            .agg(
                FirstMissMonth=("Month","min"),
                LastMissMonth=("Month","max"),
                MissedMonths=("Month","size"),
                EntryMisses=("MissType", lambda s: int((s=="Missed Entry").sum())),
                ContinuationMisses=("MissType", lambda s: int((s=="Missed Continuation").sum())),
                AvgTargetReturn=("TargetReturn","mean"),
                MaxRunAgeObserved=("RunAgeMonth","max"),
            )
            .reset_index()
        )
        run_summary["FirstMissMonth"] = run_summary["FirstMissMonth"].astype(str)
        run_summary["LastMissMonth"] = run_summary["LastMissMonth"].astype(str)

        # Best/worst for each class.
        extremes = []
        for klass in ["Missed Entry","Missed Continuation"]:
            g = events[events["MissType"].eq(klass)]
            for side, gg in [
                ("Best", g.nlargest(min(10,len(g)), "TargetReturn")),
                ("Worst", g.nsmallest(min(10,len(g)), "TargetReturn"))
            ]:
                z = gg.copy()
                z["Extreme"] = side
                extremes.append(z)
        extremes = pd.concat(extremes, ignore_index=True) if extremes else pd.DataFrame()

        progress.progress(78, text="結果を表示中…")
        st.markdown("#### 1) Missed Entry vs Continuation")
        st.dataframe(summary.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 2) Continuation substructure")
        st.dataframe(cont_summary.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Fixed feature discrimination")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 6) Target run audit")
        st.dataframe(run_summary.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 7) Best / Worst misses")
        cols = [c for c in [
            "Month","MissType","Extreme","TargetReturn","RunAgeMonth",
            "PreviouslyCapturedInRun","MonthsSinceLastCapture",
            "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100",
            "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3","VIX",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in extremes.columns]
        st.dataframe(extremes[cols].round(4), hide_index=True, use_container_width=True)

        audit = events.copy()
        audit["Month"] = audit["Month"].astype(str)
        audit["SignalMonth"] = audit["SignalMonth"].astype(str)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr("01_entry_vs_continuation_summary.csv",
                       summary.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("02_continuation_substructure.csv",
                       cont_summary.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("03_feature_discrimination.csv",
                       cmp.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("04_era_stability.csv",
                       era.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("05_leadup_path.csv",
                       leadup.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("06_target_run_audit.csv",
                       run_summary.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("07_best_worst_misses.csv",
                       extremes.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("08_event_audit.csv",
                       audit.to_csv(index=False).encode("utf-8-sig"))

        st.markdown("#### 8) 保存")
        st.download_button(
            "📦 v3.52 Missed Entry vs Continuation Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_missed_entry_vs_continuation_autopsy_v352.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v352",
        )
        st.caption(
            "Entry側に安定構造があればSecond Attack Entry、"
            "Continuation側ならRegime Holdの診断へ進みます。"
        )


def render_v351_missed_aggressive_months_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🎯 v3.51 — Missed Aggressive Months Autopsy")
    st.caption(
        "Targetが100% Aggressiveだった月だけを母集団にして、"
        "v3.45が75%以上の攻撃を捕捉できた月と、Baselineのまま逃した月を比較します。"
    )
    st.info(
        "診断専用です。Target状態はラベルとしてのみ使用し、売買ルールには使いません。"
        "閾値・lookback・AND/OR条件の探索もしません。"
    )

    if st.button("Missed Aggressiveを解析", type="primary", key="run_v351"):
        progress = st.progress(0, text="Targetと価格系列を準備中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())
        target = target[target["Month"] <= pd.Period("2026-07","M")].copy()
        target["TargetAggressive"] = (
            pd.to_numeric(target["AggressiveWt"], errors="coerce").fillna(0) >= 99.9
        ) & (
            pd.to_numeric(target["DefensiveWt"], errors="coerce").fillna(0) <= .1
        )
        target = target[target["TargetAggressive"]].copy()

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()

        progress.progress(18, text="Frozen v3.45 stateを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = (
            allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        ).reindex(idx).fillna(False).astype(bool)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        # Collapse effective v3.45 state to execution month.
        state_daily = pd.DataFrame({
            "Turbo": turbo_active,
            "ChooseTECL": choose_tecl,
        }, index=idx)
        state_m = state_daily.groupby(state_daily.index.to_period("M")).agg({
            "Turbo":"max",
            "ChooseTECL":"max",
        })
        state_m["V345AttackWt"] = 0.50
        state_m.loc[state_m["Turbo"], "V345AttackWt"] = 0.75
        state_m.loc[state_m["Turbo"] & state_m["ChooseTECL"], "V345AttackWt"] = 1.00
        state_m["V345AttackAsset"] = "Baseline Mix"
        state_m.loc[state_m["Turbo"] & ~state_m["ChooseTECL"], "V345AttackAsset"] = "TQQQ"
        state_m.loc[state_m["Turbo"] & state_m["ChooseTECL"], "V345AttackAsset"] = "TECL"
        state_m = state_m.reset_index(names="Month")

        events = target.merge(
            state_m[["Month","V345AttackWt","V345AttackAsset","Turbo","ChooseTECL"]],
            on="Month",
            how="inner"
        )
        events["CaptureLabel"] = np.where(
            events["V345AttackWt"] >= .75,
            "Captured",
            "Missed"
        )
        events["SignalMonth"] = events["Month"] - 1

        if events["CaptureLabel"].nunique() < 2:
            raise RuntimeError("v3.51 sanity check failed: Captured/Missed classes unavailable.")

        progress.progress(34, text="Frozen特徴を付与中…")
        feat = _v347_prepare_features(closes)

        for i, r in events.iterrows():
            sm = r["SignalMonth"]
            if sm in feat.index:
                fr = feat.loc[sm]
                for c in feat.columns:
                    events.loc[i, c] = fr.get(c, np.nan)

        features = [c for c in [
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "XLK_Inflect_1m3m","XLK_SMA100","XLK_SMA200",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
            "Delta_QQQ_mom3_1m","Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_mom3_1m","Delta_XLK_Inflect_1m3m_1m",
            "Delta_TLT_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_GLD_mom3_1m","Delta_XLK_minus_QQQ_6M_1m",
        ] if c in events.columns]

        cmp = _v351_feature_compare(events, features)
        era = _v351_era_stability(events, features)

        if not cmp.empty:
            stability = []
            for _, r in cmp.iterrows():
                g = era[era["Feature"].eq(r["Feature"])]
                full_dir = r["Captured direction"]
                if len(g):
                    same = int(g["Captured direction"].eq(full_dir).sum())
                    stability.append(f"{same}/{len(g)}")
                else:
                    stability.append("0/0")
            cmp["Era same direction"] = stability

        progress.progress(50, text="Run構造を集計中…")

        # Target Aggressive run IDs, then coverage within each run.
        t_all = _v330_normalize_target_table(_v330_find_target_monthly_table())
        t_all = t_all[t_all["Month"] <= pd.Period("2026-07","M")].copy()
        t_all["TargetAggressive"] = (
            pd.to_numeric(t_all["AggressiveWt"], errors="coerce").fillna(0) >= 99.9
        ) & (
            pd.to_numeric(t_all["DefensiveWt"], errors="coerce").fillna(0) <= .1
        )
        run_id = 0
        in_run = False
        run_map = {}
        for _, rr in t_all.sort_values("Month").iterrows():
            m = rr["Month"]
            flag = bool(rr["TargetAggressive"])
            if flag and not in_run:
                run_id += 1
                in_run = True
            if flag:
                run_map[m] = run_id
            else:
                in_run = False

        events["TargetAggRun"] = events["Month"].map(run_map)

        run_summary = (
            events.groupby("TargetAggRun")
            .agg(
                Start=("Month","min"),
                End=("Month","max"),
                Months=("Month","size"),
                CapturedMonths=("CaptureLabel", lambda s: int((s=="Captured").sum())),
                MissedMonths=("CaptureLabel", lambda s: int((s=="Missed").sum())),
                AvgTargetReturn=("TargetReturn","mean"),
            )
            .reset_index()
        )
        run_summary["CapturedCoverage"] = (
            run_summary["CapturedMonths"] / run_summary["Months"]
        )
        run_summary["Start"] = run_summary["Start"].astype(str)
        run_summary["End"] = run_summary["End"].astype(str)

        progress.progress(62, text="Lead-up / transition structureを計算中…")
        lead_features = [c for c in [
            "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100",
            "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in feat.columns]

        lead_rows = []
        for klass in ["Captured","Missed"]:
            sig_months = events.loc[
                events["CaptureLabel"].eq(klass), "SignalMonth"
            ].tolist()
            for lag in [-2,-1,0]:
                for f in lead_features:
                    vals = []
                    for m in sig_months:
                        mm = m + lag
                        if mm in feat.index:
                            v = feat.loc[mm, f]
                            if pd.notna(v):
                                vals.append(float(v))
                    if vals:
                        lead_rows.append({
                            "Class": klass,
                            "LagMonths": lag,
                            "Feature": f,
                            "Median": float(np.median(vals)),
                            "N": len(vals),
                        })
        leadup = pd.DataFrame(lead_rows)

        # Target asset mix by capture class.
        def _asset_label(r):
            vals = {
                "TQQQ": float(pd.to_numeric(r.get("TQQQ",0), errors="coerce") or 0),
                "TECL": float(pd.to_numeric(r.get("TECL",0), errors="coerce") or 0),
                "XLU": float(pd.to_numeric(r.get("XLU",0), errors="coerce") or 0),
                "GLD": float(pd.to_numeric(r.get("GLD",0), errors="coerce") or 0),
            }
            pos = [k for k,v in vals.items() if pd.notna(v) and v > .1]
            if len(pos) == 1:
                return pos[0]
            if len(pos) > 1:
                return "Mixed: " + "+".join(pos)
            return "Unknown"

        events["TargetAssetLabel"] = events.apply(_asset_label, axis=1)

        asset_summary = (
            events.groupby(["CaptureLabel","TargetAssetLabel"], dropna=False)
            .agg(
                Months=("Month","size"),
                AvgTargetReturn=("TargetReturn","mean"),
                MedianTargetReturn=("TargetReturn","median"),
            )
            .reset_index()
            .sort_values(["CaptureLabel","Months"], ascending=[True,False])
        )

        # Outcome summary.
        summary = (
            events.groupby("CaptureLabel")
            .agg(
                Months=("Month","size"),
                AvgTargetReturn=("TargetReturn","mean"),
                MedianTargetReturn=("TargetReturn","median"),
                PositiveTargetMonths=("TargetReturn", lambda s: int((s>0).sum())),
            )
            .reset_index()
        )
        summary["PositiveRate"] = summary["PositiveTargetMonths"] / summary["Months"]

        # Largest missed months by target return.
        missed_best = (
            events[events["CaptureLabel"].eq("Missed")]
            .sort_values("TargetReturn", ascending=False)
            .head(15)
            .copy()
        )
        missed_worst = (
            events[events["CaptureLabel"].eq("Missed")]
            .sort_values("TargetReturn", ascending=True)
            .head(15)
            .copy()
        )

        progress.progress(78, text="結果を表示中…")
        st.markdown("#### 1) Captured vs Missed summary")
        st.dataframe(summary.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 2) Fixed feature discrimination")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) Lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Target Aggressive run coverage")
        st.dataframe(run_summary.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 6) Target asset mix")
        st.dataframe(asset_summary.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 7) Best missed Aggressive months")
        st.dataframe(
            missed_best[[
                c for c in [
                    "Month","TargetReturn","TargetAssetLabel","TargetAggRun",
                    "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100",
                    "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
                    "TLT_mom3","LQD_mom3","GLD_mom3","VIX",
                    "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
                ] if c in missed_best.columns
            ]].round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 8) Worst missed Aggressive months")
        st.dataframe(
            missed_worst[[
                c for c in [
                    "Month","TargetReturn","TargetAssetLabel","TargetAggRun",
                    "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100",
                    "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
                    "TLT_mom3","LQD_mom3","GLD_mom3","VIX",
                    "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
                ] if c in missed_worst.columns
            ]].round(4),
            hide_index=True, use_container_width=True
        )

        audit = events.copy()
        audit["Month"] = audit["Month"].astype(str)
        audit["SignalMonth"] = audit["SignalMonth"].astype(str)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile

        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_captured_vs_missed_summary.csv",
                summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_feature_discrimination.csv",
                cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_leadup_path.csv",
                leadup.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_target_aggressive_run_coverage.csv",
                run_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_target_asset_mix.csv",
                asset_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_best_missed_aggressive_months.csv",
                missed_best.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_worst_missed_aggressive_months.csv",
                missed_worst.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_missed_aggressive_event_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.51 Missed Aggressive Months Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_missed_aggressive_months_autopsy_v351.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v351",
        )
        st.caption(
            "ここでMissed群にfull sample・Era・lead-upで一貫した構造があれば、"
            "次はその構造だけを一発Challenger化します。"
        )


def render_v350_capped_one_month_persistence(px_close, rf_bt, start, end):
    st.markdown("### 🧯 v3.50 — Capped One-Month Turbo Persistence Challenger")
    st.caption(
        "Controlはv3.45。TurboがON→OFFになった最初の1か月だけPersistenceしますが、"
        "攻撃強度は必ず最大75%に制限します。"
        "前月が100% TECL Promotionでも、Persistence月は75%へ落とします。"
    )
    st.info(
        "攻撃資産は既存のXLK6M > QQQ6M selectorで毎月選び直します。"
        "新indicator・新threshold・新lookback・Target状態は使いません。"
    )
    st.warning(
        "これがPersistenceルート最後の一発テストです。"
        "CAGRだけでなく、SortinoをSharpeより重く見つつ、Rolling P10、"
        "Daily/Monthly DD、CPCV、stressを総合評価します。"
    )

    if st.button("Capped Persistenceを検証", type="primary", key="run_v350"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        progress.progress(18, text="Frozen v3.45 Controlを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(base_h, allow_l2)
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = (
            allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        ).reindex(idx).fillna(False).astype(bool)

        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)
        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        _, attack75 = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        # Frozen v3.45 control.
        promote100 = (turbo_active & choose_tecl).reindex(idx).fillna(False)
        v345 = attack75.copy()
        v345.loc[promote100] = asset_ret["TECL"].reindex(idx).loc[promote100]

        progress.progress(34, text="Capped one-month persistence stateを構築中…")

        # Reuse the exact v3.48 persistence-month identification.
        persist, _, persist_asset, persistence_audit = (
            _v348_monthly_persistence_state(idx, turbo_active, choose_tecl)
        )

        # Cap persistence at 75% regardless of previous Turbo intensity.
        capped_intensity = pd.Series(
            np.where(persist, 0.75, 0.0),
            index=idx, dtype=float
        )

        nonmom = _v348_nonmom_normalized_return(avix_h, asset_ret).reindex(idx)
        tq = asset_ret["TQQQ"].reindex(idx)
        te = asset_ret["TECL"].reindex(idx)

        selected_attack = pd.Series(
            np.where(persist_asset.eq("TECL"), te, tq),
            index=idx, dtype=float
        )

        persistence_ret = pd.Series(np.nan, index=idx, dtype=float)
        pmask = persist & capped_intensity.eq(.75)
        persistence_ret.loc[pmask] = (
            .75 * selected_attack.loc[pmask]
            + .25 * nonmom.loc[pmask]
        )

        challenger = v345.copy()
        challenger.loc[persist] = persistence_ret.loc[persist]

        cutoff = pd.Timestamp("2026-07-31")
        daily = pd.DataFrame({
            "Base Adaptive ALL": base_ret,
            "v3.45 Control": v345,
            "v3.50 Capped Persistence": challenger,
        }).loc[:cutoff].dropna()

        variants = list(daily.columns)
        ctrl_name = "v3.45 Control"
        chal_name = "v3.50 Capped Persistence"

        changed = (
            (challenger.reindex(daily.index) - v345.reindex(daily.index))
            .abs().fillna(0.0) > 1e-12
        )
        if int(persist.reindex(daily.index).fillna(False).sum()) == 0:
            raise RuntimeError("v3.50 sanity check failed: no persistence days.")
        if int(changed.sum()) == 0:
            raise RuntimeError(
                "v3.50 sanity check failed: capped persistence never changed returns."
            )

        progress.progress(48, text="Full metricsを計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl = metrics.loc[ctrl_name]
        metrics["ΔCAGR vs Control"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs Control"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs Control"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["Daily DD change vs Control"] = (
            metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]
        )
        metrics["Monthly DD change vs Control"] = (
            metrics["Monthly MaxDD"] - ctrl["Monthly MaxDD"]
        )

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","ΔSortino vs Control","ΔSharpe vs Control",
            "Daily DD change vs Control","Monthly DD change vs Control"
        ]
        show = metrics[show_cols].copy().astype(object)

        for c in [
            "CAGR","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","Daily DD change vs Control",
            "Monthly DD change vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in [
            "Sortino0","Sharpe0","ΔSortino vs Control","ΔSharpe vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        progress.progress(58, text="Activity / Rolling P10を集計中…")
        p_daily = pd.DataFrame({
            "Persistence": persist.reindex(daily.index).fillna(False),
            "Asset": persist_asset.reindex(daily.index),
            "Changed": changed.reindex(daily.index).fillna(False),
        })
        activity = pd.DataFrame({
            "Measure": [
                "Persistence trading days",
                "Persistence share of trading days",
                "Persistence months",
                "TECL persistence months",
                "TQQQ persistence months",
                "Days returns actually changed",
            ],
            "Value": [
                int(p_daily["Persistence"].sum()),
                f"{p_daily['Persistence'].mean()*100:.1f}%",
                int(
                    p_daily[p_daily["Persistence"]]
                    .index.to_period("M").nunique()
                ),
                int(
                    p_daily[
                        p_daily["Persistence"] & p_daily["Asset"].eq("TECL")
                    ].index.to_period("M").nunique()
                ),
                int(
                    p_daily[
                        p_daily["Persistence"] & p_daily["Asset"].eq("TQQQ")
                    ].index.to_period("M").nunique()
                ),
                int(p_daily["Changed"].sum()),
            ],
        })

        st.markdown("#### 2) Persistence activity")
        st.dataframe(activity, hide_index=True, use_container_width=True)

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(70, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        cpcv_vs_ctrl, _ = _v326_cpcv_summary(
            monthly, ctrl_name, [chal_name]
        )
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL", [ctrl_name, chal_name]
        )

        def _compact_cpcv_v350(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                row = {
                    "Variant": v,
                    "Sortino wins": (
                        f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}"
                    ),
                    "Positive Active": (
                        f"{int(g['Positive Active'].sum())}/{len(g)}"
                    ),
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                }
                if "Delta Sharpe0" in g.columns:
                    row["Sharpe wins"] = (
                        f"{int((g['Delta Sharpe0'] > 0).sum())}/{len(g)}"
                    )
                    row["Median ΔSharpe"] = g["Delta Sharpe0"].median()
                    row["P10 ΔSharpe"] = g["Delta Sharpe0"].quantile(.10)
                rows.append(row)
            return pd.DataFrame(rows)

        st.markdown("#### 4) CPCV — Capped Persistence vs v3.45")
        st.dataframe(
            _compact_cpcv_v350(cpcv_vs_ctrl).round(4),
            hide_index=True,
            use_container_width=True
        )

        st.markdown("#### 5) CPCV — Control / Challenger vs Base")
        st.dataframe(
            _compact_cpcv_v350(cpcv_vs_base).round(4),
            hide_index=True,
            use_container_width=True
        )

        progress.progress(80, text="Stress / annual robustnessを確認中…")
        stress_windows = [
            ("2011 Jul-Oct", "2011-07-26", "2011-10-04"),
            ("2015 Jul-Aug", "2015-07-21", "2015-08-24"),
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2023 Jul-Oct", "2023-07-19", "2023-10-27"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress.columns:
                sshow[v] = stress[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        annual = (1.0 + daily).resample("YE").prod() - 1.0
        annual.index = annual.index.year
        annual.index.name = "Year"

        st.markdown("#### 7) Calendar-year returns")
        ashow = annual.copy().astype(object)
        for v in variants:
            ashow[v] = annual[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(ashow, use_container_width=True)

        # Direct month-level attribution.
        attr = pd.DataFrame({
            "Control": v345.reindex(daily.index),
            "Capped": challenger.reindex(daily.index),
            "Persist": persist.reindex(daily.index).fillna(False),
            "Asset": persist_asset.reindex(daily.index),
        })
        ponly = attr[attr["Persist"]].copy()
        ponly["Month"] = ponly.index.to_period("M").astype(str)

        rows = []
        for m, g in ponly.groupby("Month"):
            c = (1.0 + g["Control"].dropna()).prod() - 1.0
            p = (1.0 + g["Capped"].dropna()).prod() - 1.0
            rows.append({
                "Month": m,
                "PersistIntensity": 0.75,
                "PersistAsset": (
                    "TECL" if (g["Asset"] == "TECL").mean() >= .5 else "TQQQ"
                ),
                "v3.45 Control": c,
                "v3.50 Capped": p,
                "Active": p - c,
                "TradingDays": len(g),
            })
        monthly_attr = pd.DataFrame(rows)

        st.markdown("#### 8) Persistence-month attribution")
        st.dataframe(
            monthly_attr.round(4),
            hide_index=True,
            use_container_width=True
        )

        # Audit persistence months.
        pa = persistence_audit[
            persistence_audit["PersistenceMonth"]
        ].copy()
        pa["CappedIntensity"] = 0.75

        st.markdown("#### 9) Persistence state audit")
        st.dataframe(pa, hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile

        buf = _io.BytesIO()
        with _zipfile.ZipFile(
            buf, "w", compression=_zipfile.ZIP_DEFLATED
        ) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_persistence_activity.csv",
                activity.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_capped_vs_control.csv",
                cpcv_vs_ctrl.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_annual_returns.csv",
                annual.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "08_persistence_month_attribution.csv",
                monthly_attr.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_persistence_state_audit.csv",
                pa.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "10_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )

        st.markdown("#### 10) 保存")
        st.download_button(
            "📦 v3.50 Capped One-Month Persistence（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v350_capped_one_month_persistence.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v350",
        )
        st.caption(
            "これでもv3.45を総合的に上回らなければ、"
            "Persistenceルートはここで終了します。"
        )


def render_v349_persistence_winner_loser_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🧪 v3.49b — Persistence Winner vs Loser Autopsy FIX")
    st.caption(
        "棄却したv3.48のPersistence月だけを固定母集団にして、"
        "v3.45より改善した月（Winner）と悪化した月（Loser）を比較します。"
    )
    st.info(
        "診断専用です。新しい売買ルールは作りません。"
        "既存特徴だけを使い、閾値・lookback・AND/OR条件は探索しません。"
    )

    if st.button("Winner vs Loserを解析", type="primary", key="run_v349"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        progress.progress(16, text="Frozen v3.45 / rejected v3.48を再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(base_h, allow_l2)
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = (
            allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        ).reindex(idx).fillna(False).astype(bool)

        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)
        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        _, attack75 = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        promote100 = (turbo_active & choose_tecl).reindex(idx).fillna(False)
        v345 = attack75.copy()
        v345.loc[promote100] = asset_ret["TECL"].reindex(idx).loc[promote100]

        persist, intensity, persist_asset, persistence_audit = (
            _v348_monthly_persistence_state(idx, turbo_active, choose_tecl)
        )

        nonmom = _v348_nonmom_normalized_return(avix_h, asset_ret).reindex(idx)
        tq = asset_ret["TQQQ"].reindex(idx)
        te = asset_ret["TECL"].reindex(idx)

        selected_attack = pd.Series(
            np.where(persist_asset.eq("TECL"), te, tq),
            index=idx, dtype=float
        )

        persistence_ret = pd.Series(np.nan, index=idx, dtype=float)
        p75 = persist & intensity.eq(.75)
        p100 = persist & intensity.eq(1.0)

        persistence_ret.loc[p75] = (
            .75 * selected_attack.loc[p75]
            + .25 * nonmom.loc[p75]
        )
        persistence_ret.loc[p100] = selected_attack.loc[p100]

        v348 = v345.copy()
        v348.loc[persist] = persistence_ret.loc[persist]

        cutoff = pd.Timestamp("2026-07-31")
        v345 = v345.loc[v345.index <= cutoff]
        v348 = v348.loc[v348.index <= cutoff]
        persist = persist.reindex(v345.index).fillna(False)
        intensity = intensity.reindex(v345.index).fillna(0.0)
        persist_asset = persist_asset.reindex(v345.index)

        progress.progress(32, text="Persistence月の実現アウトカムを作成中…")
        month_rows = []
        pmonths = sorted(v345.index[persist].to_period("M").unique())

        for m in pmonths:
            sel = (v345.index.to_period("M") == m)
            c = v345.loc[sel].dropna()
            p = v348.loc[sel].dropna()
            if len(c) == 0 or len(p) == 0:
                continue
            cr = (1.0 + c).prod() - 1.0
            pr = (1.0 + p).prod() - 1.0
            active = pr - cr

            gidx = v345.index[sel]
            inten = float(intensity.reindex(gidx).median())
            asset = (
                "TECL"
                if (persist_asset.reindex(gidx) == "TECL").mean() >= .5
                else "TQQQ"
            )

            month_rows.append({
                "ExecutionMonth": m,
                "SignalMonth": m - 1,
                "OutcomeLabel": "Winner" if active > 0 else "Loser",
                "v3.45Return": cr,
                "PersistenceReturn": pr,
                "Active": active,
                "PersistIntensity": inten,
                "PersistAsset": asset,
                "TradingDays": len(gidx),
            })

        events = pd.DataFrame(month_rows)
        if events.empty or events["OutcomeLabel"].nunique() < 2:
            raise RuntimeError(
                "v3.49 sanity check failed: Winner/Loser events unavailable."
            )

        progress.progress(46, text="Frozen特徴を付与中…")
        feat = _v347_prepare_features(closes)

        for i, r in events.iterrows():
            sm = r["SignalMonth"]
            if sm in feat.index:
                fr = feat.loc[sm]
                for c in feat.columns:
                    events.loc[i, c] = fr.get(c, np.nan)

        features = [c for c in [
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "XLK_Inflect_1m3m","XLK_SMA100","XLK_SMA200",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
            "Delta_QQQ_mom3_1m","Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_mom3_1m","Delta_XLK_Inflect_1m3m_1m",
            "Delta_TLT_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_GLD_mom3_1m","Delta_XLK_minus_QQQ_6M_1m",
        ] if c in events.columns]

        cmp = _v349_feature_table(events, features)
        era = _v349_era_stability(events, features)

        if not cmp.empty:
            stability = []
            for _, r in cmp.iterrows():
                g = era[era["Feature"].eq(r["Feature"])]
                full_dir = r["Winner direction"]
                if len(g):
                    same = int(g["Winner direction"].eq(full_dir).sum())
                    stability.append(f"{same}/{len(g)}")
                else:
                    stability.append("0/0")
            cmp["Era same direction"] = stability

        progress.progress(60, text="Lead-up / failure autopsyを計算中…")
        lead_features = [c for c in [
            "QQQ_mom3","QQQ_mom6","QQQ_Inflect_1m3m","QQQ_SMA100",
            "XLK_mom3","XLK_mom6","XLK_Inflect_1m3m",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in feat.columns]

        lead_rows = []
        for klass in ["Winner","Loser"]:
            sig_months = events.loc[
                events["OutcomeLabel"].eq(klass), "SignalMonth"
            ].tolist()
            for lag in [-2,-1,0]:
                for f in lead_features:
                    vals = []
                    for m in sig_months:
                        mm = m + lag
                        if mm in feat.index:
                            v = feat.loc[mm, f]
                            if pd.notna(v):
                                vals.append(float(v))
                    if vals:
                        lead_rows.append({
                            "Class": klass,
                            "LagMonths": lag,
                            "Feature": f,
                            "Median": float(np.median(vals)),
                            "N": len(vals),
                        })
        leadup = pd.DataFrame(lead_rows)

        outcome_summary = pd.DataFrame({
            "Measure": [
                "Persistence months",
                "Winner months",
                "Loser months",
                "Winner rate",
                "Median active return",
                "Mean active return",
                "Sum active return",
                "Median Winner active",
                "Median Loser active",
            ],
            "Value": [
                len(events),
                int(events["OutcomeLabel"].eq("Winner").sum()),
                int(events["OutcomeLabel"].eq("Loser").sum()),
                events["OutcomeLabel"].eq("Winner").mean(),
                events["Active"].median(),
                events["Active"].mean(),
                events["Active"].sum(),
                events.loc[events["OutcomeLabel"].eq("Winner"), "Active"].median(),
                events.loc[events["OutcomeLabel"].eq("Loser"), "Active"].median(),
            ],
        })

        asset_intensity = (
            events.groupby(["PersistIntensity","PersistAsset","OutcomeLabel"])
            .agg(
                Events=("ExecutionMonth","size"),
                MedianActive=("Active","median"),
                MeanActive=("Active","mean"),
            )
            .reset_index()
        )

        worst = events.sort_values("Active").head(10).copy()
        best = events.sort_values("Active", ascending=False).head(10).copy()

        progress.progress(74, text="Target診断クロスチェック中…")
        target_x = pd.DataFrame()
        try:
            target = _v330_normalize_target_table(_v330_find_target_monthly_table())
            target = target[target["Month"] <= pd.Period("2026-07","M")].copy()
            target["TargetAggressive"] = (
                pd.to_numeric(target["AggressiveWt"], errors="coerce").fillna(0) >= 99.9
            ) & (
                pd.to_numeric(target["DefensiveWt"], errors="coerce").fillna(0) <= .1
            )
            tx = events[["ExecutionMonth","OutcomeLabel","Active"]].merge(
                target[["Month","TargetAggressive","AggressiveWt","DefensiveWt"]],
                left_on="ExecutionMonth",
                right_on="Month",
                how="left",
            )
            target_x = (
                tx.groupby(["OutcomeLabel","TargetAggressive"], dropna=False)
                .agg(
                    Events=("ExecutionMonth","size"),
                    MedianActive=("Active","median")
                )
                .reset_index()
            )
        except Exception:
            pass

        progress.progress(84, text="結果を表示中…")
        st.markdown("#### 1) Persistence outcome")
        os_show = outcome_summary.copy()
        for i in os_show.index:
            m = os_show.loc[i, "Measure"]
            v = os_show.loc[i, "Value"]
            if "rate" in m.lower() or "return" in m.lower():
                try:
                    os_show.loc[i, "Value"] = f"{float(v)*100:+.2f}%"
                except Exception:
                    pass
        st.dataframe(os_show, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Fixed feature discrimination")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) Lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Asset / intensity outcome")
        st.dataframe(asset_intensity.round(4), hide_index=True, use_container_width=True)

        if not target_x.empty:
            st.markdown("#### 6) Target-state cross-check（diagnostic only）")
            st.dataframe(target_x.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 7) Worst persistence months")
        st.dataframe(
            worst[[
                c for c in [
                    "ExecutionMonth","OutcomeLabel","Active",
                    "v3.45Return","PersistenceReturn",
                    "PersistIntensity","PersistAsset",
                    "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
                    "XLK_minus_QQQ_6M","XLK_mom6",
                    "TLT_mom3","LQD_mom3","GLD_mom3","VIX"
                ] if c in worst.columns
            ]].round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 8) Best persistence months")
        st.dataframe(
            best[[
                c for c in [
                    "ExecutionMonth","OutcomeLabel","Active",
                    "v3.45Return","PersistenceReturn",
                    "PersistIntensity","PersistAsset",
                    "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
                    "XLK_minus_QQQ_6M","XLK_mom6",
                    "TLT_mom3","LQD_mom3","GLD_mom3","VIX"
                ] if c in best.columns
            ]].round(4),
            hide_index=True, use_container_width=True
        )

        audit = events.copy()
        audit["ExecutionMonth"] = audit["ExecutionMonth"].astype(str)
        audit["SignalMonth"] = audit["SignalMonth"].astype(str)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile

        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_outcome_summary.csv",
                outcome_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_feature_discrimination.csv",
                cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_leadup_path.csv",
                leadup.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_asset_intensity_outcome.csv",
                asset_intensity.to_csv(index=False).encode("utf-8-sig")
            )
            if not target_x.empty:
                z.writestr(
                    "06_target_state_crosscheck.csv",
                    target_x.to_csv(index=False).encode("utf-8-sig")
                )
            z.writestr(
                "07_worst_persistence_months.csv",
                worst.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_best_persistence_months.csv",
                best.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_persistence_event_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.49b Persistence Winner vs Loser Autopsy FIX（ZIP）",
            data=buf.getvalue(),
            file_name="target_persistence_winner_loser_autopsy_v349b.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v349",
        )
        st.caption(
            "full sample・Era・lead-up・大失敗月で同じ特徴が一貫した場合だけ、"
            "次のthreshold-free Persistence Challengerを検討します。"
        )


def render_v348_one_month_turbo_persistence(px_close, rf_bt, start, end):
    st.markdown("### 🔁 v3.48 — One-Month Turbo Persistence Challenger #1")
    st.caption(
        "Controlはv3.45。TurboがON→OFFになった最初の1か月だけ、"
        "前月の攻撃強度（75%または100%）を維持します。"
        "攻撃資産はその月の既存XLK6M vs QQQ6M selectorでTQQQ/TECLを選び直します。"
    )
    st.info(
        "新indicator・新lookback・新thresholdはありません。"
        "Target状態は売買ルールに一切使いません。1か月後は自動的に通常v3.45へ戻ります。"
    )
    st.warning(
        "一発検証です。CAGRだけでなく、SortinoをSharpeより重く見つつ、"
        "Rolling P10、Daily/Monthly DD、CPCV、stress、年次を総合評価します。"
    )

    if st.button("One-Month Persistenceを検証", type="primary", key="run_v348"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        progress.progress(18, text="Frozen v3.45 Controlを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(base_h, allow_l2)
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = (
            allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        ).reindex(idx).fillna(False).astype(bool)

        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        _, attack75 = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        # v3.45 control: frozen TECL leadership promotion to 100%.
        promote100 = (turbo_active & choose_tecl).reindex(idx).fillna(False)
        v345 = attack75.copy()
        v345.loc[promote100] = asset_ret["TECL"].reindex(idx).loc[promote100]

        progress.progress(36, text="One-month persistence stateを構築中…")
        persist, intensity, persist_asset, persistence_audit = (
            _v348_monthly_persistence_state(
                idx, turbo_active, choose_tecl
            )
        )

        nonmom = _v348_nonmom_normalized_return(avix_h, asset_ret).reindex(idx)
        tq = asset_ret["TQQQ"].reindex(idx)
        te = asset_ret["TECL"].reindex(idx)

        selected_attack = pd.Series(
            np.where(persist_asset.eq("TECL"), te, tq),
            index=idx, dtype=float
        )

        persistence_ret = pd.Series(np.nan, index=idx, dtype=float)
        p75 = persist & intensity.eq(0.75)
        p100 = persist & intensity.eq(1.00)

        persistence_ret.loc[p75] = (
            0.75 * selected_attack.loc[p75]
            + 0.25 * nonmom.loc[p75]
        )
        persistence_ret.loc[p100] = selected_attack.loc[p100]

        challenger = v345.copy()
        challenger.loc[persist] = persistence_ret.loc[persist]

        changed = (
            (challenger - v345).abs().fillna(0.0) > 1e-12
        )

        if int(persist.sum()) == 0:
            raise RuntimeError("v3.48 sanity check failed: no persistence days.")
        if int(changed.sum()) == 0:
            raise RuntimeError(
                "v3.48 sanity check failed: persistence activated but returns never changed."
            )

        daily = pd.DataFrame({
            "Base Adaptive ALL": base_ret,
            "v3.45 Control": v345,
            "1M Turbo Persistence": challenger,
        })
        daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
        variants = list(daily.columns)

        progress.progress(50, text="Full metricsを計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl_name = "v3.45 Control"
        chal_name = "1M Turbo Persistence"
        ctrl = metrics.loc[ctrl_name]

        metrics["ΔCAGR vs Control"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs Control"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs Control"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["Daily DD change vs Control"] = (
            metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]
        )
        metrics["Monthly DD change vs Control"] = (
            metrics["Monthly MaxDD"] - ctrl["Monthly MaxDD"]
        )

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","ΔSortino vs Control","ΔSharpe vs Control",
            "Daily DD change vs Control","Monthly DD change vs Control"
        ]
        show = metrics[show_cols].copy().astype(object)

        for c in [
            "CAGR","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","Daily DD change vs Control",
            "Monthly DD change vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in [
            "Sortino0","Sharpe0","ΔSortino vs Control","ΔSharpe vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        progress.progress(60, text="Activity / Rolling P10を集計中…")
        p_daily = pd.DataFrame({
            "Persistence": persist.reindex(daily.index).fillna(False),
            "Intensity": intensity.reindex(daily.index).fillna(0.0),
            "Asset": persist_asset.reindex(daily.index),
            "Changed": changed.reindex(daily.index).fillna(False),
        })

        activity = pd.DataFrame({
            "Measure": [
                "Persistence trading days",
                "Persistence share of trading days",
                "Persistence months",
                "75% persistence months",
                "100% persistence months",
                "Days returns actually changed",
            ],
            "Value": [
                int(p_daily["Persistence"].sum()),
                f"{p_daily['Persistence'].mean()*100:.1f}%",
                int(
                    p_daily[p_daily["Persistence"]]
                    .index.to_period("M").nunique()
                ),
                int(
                    p_daily[
                        p_daily["Persistence"] & p_daily["Intensity"].eq(.75)
                    ].index.to_period("M").nunique()
                ),
                int(
                    p_daily[
                        p_daily["Persistence"] & p_daily["Intensity"].eq(1.0)
                    ].index.to_period("M").nunique()
                ),
                int(p_daily["Changed"].sum()),
            ],
        })

        st.markdown("#### 2) Persistence activity")
        st.dataframe(activity, hide_index=True, use_container_width=True)

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(70, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        cpcv_vs_ctrl, _ = _v326_cpcv_summary(
            monthly, ctrl_name, [chal_name]
        )
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL", [ctrl_name, chal_name]
        )

        def _compact_cpcv_v348(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                row = {
                    "Variant": v,
                    "Sortino wins": (
                        f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}"
                    ),
                    "Positive Active": (
                        f"{int(g['Positive Active'].sum())}/{len(g)}"
                    ),
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                }
                if "Delta Sharpe0" in g.columns:
                    row["Sharpe wins"] = (
                        f"{int((g['Delta Sharpe0'] > 0).sum())}/{len(g)}"
                    )
                    row["Median ΔSharpe"] = g["Delta Sharpe0"].median()
                    row["P10 ΔSharpe"] = g["Delta Sharpe0"].quantile(.10)
                rows.append(row)
            return pd.DataFrame(rows)

        st.markdown("#### 4) CPCV — Persistence vs v3.45")
        st.dataframe(
            _compact_cpcv_v348(cpcv_vs_ctrl).round(4),
            hide_index=True,
            use_container_width=True
        )

        st.markdown("#### 5) CPCV — Control / Persistence vs Base")
        st.dataframe(
            _compact_cpcv_v348(cpcv_vs_base).round(4),
            hide_index=True,
            use_container_width=True
        )

        progress.progress(80, text="Stress / annual robustnessを確認中…")
        stress_windows = [
            ("2011 Jul-Oct", "2011-07-26", "2011-10-04"),
            ("2015 Jul-Aug", "2015-07-21", "2015-08-24"),
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2023 Jul-Oct", "2023-07-19", "2023-10-27"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress.columns:
                sshow[v] = stress[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        annual = (1.0 + daily).resample("YE").prod() - 1.0
        annual.index = annual.index.year
        annual.index.name = "Year"

        st.markdown("#### 7) Calendar-year returns")
        ashow = annual.copy().astype(object)
        for v in variants:
            ashow[v] = annual[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(ashow, use_container_width=True)

        # Month-level direct attribution.
        attr = pd.DataFrame({
            "Control": v345.reindex(daily.index),
            "Persistence": challenger.reindex(daily.index),
            "Persist": persist.reindex(daily.index).fillna(False),
            "Intensity": intensity.reindex(daily.index).fillna(0.0),
            "Asset": persist_asset.reindex(daily.index),
        })
        ponly = attr[attr["Persist"]].copy()
        ponly["Month"] = ponly.index.to_period("M").astype(str)

        rows = []
        for m, g in ponly.groupby("Month"):
            c = (1.0 + g["Control"].dropna()).prod() - 1.0
            p = (1.0 + g["Persistence"].dropna()).prod() - 1.0
            rows.append({
                "Month": m,
                "PersistIntensity": float(g["Intensity"].median()),
                "PersistAsset": (
                    "TECL" if (g["Asset"] == "TECL").mean() >= .5 else "TQQQ"
                ),
                "v3.45 Control": c,
                "1M Persistence": p,
                "Active": p - c,
                "TradingDays": len(g),
            })
        monthly_attr = pd.DataFrame(rows)

        st.markdown("#### 8) Persistence-month attribution")
        st.dataframe(
            monthly_attr.round(4),
            hide_index=True,
            use_container_width=True
        )

        # Restrict raw audit to actual persistence months.
        pa = persistence_audit[
            persistence_audit["PersistenceMonth"]
        ].copy()

        st.markdown("#### 9) Persistence state audit")
        st.dataframe(pa, hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile

        buf = _io.BytesIO()
        with _zipfile.ZipFile(
            buf, "w", compression=_zipfile.ZIP_DEFLATED
        ) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_persistence_activity.csv",
                activity.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_persistence_vs_control.csv",
                cpcv_vs_ctrl.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_annual_returns.csv",
                annual.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "08_persistence_month_attribution.csv",
                monthly_attr.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_persistence_state_audit.csv",
                pa.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "10_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )

        st.markdown("#### 10) 保存")
        st.download_button(
            "📦 v3.48 One-Month Turbo Persistence（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v348_one_month_turbo_persistence.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v348",
        )
        st.caption(
            "v3.45を置き換えるのは、CAGRだけでなくSortino/Sharpe、Rolling P10、"
            "DD、CPCV、stressを総合して十分に改善・維持した場合だけです。"
        )


def render_v347_turbo_exit_persistence_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🔄 v3.47 — Turbo Exit / Persistence Autopsy")
    st.caption(
        "v3.45のTurboがON→OFFになる地点だけを固定母集団にして、"
        "Targetがその後も100% Aggressiveを維持するケースと、"
        "Defensive/Mixedへ落ちるケースを比較します。"
    )
    st.info(
        "診断専用です。Turboを延長する売買ルールはまだ作りません。"
        "閾値・lookback・AND/OR条件の探索もしません。"
    )

    if st.button("Turbo Persistenceを解析", type="primary", key="run_v347"):
        progress = st.progress(0, text="Targetと価格系列を準備中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())
        target = target[target["Month"] <= pd.Period("2026-07","M")].copy()
        target = _v347_target_is_full_aggressive(target)
        target_map = dict(zip(target["Month"], target["TargetAggressive"]))

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        progress.progress(18, text="Frozen v3.45 Turbo stateを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(base_h, allow_l2)
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = (
            allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        ).reindex(idx).fillna(False).astype(bool)

        # Collapse daily effective state to execution-month state.
        turbo_month = turbo_active.groupby(turbo_active.index.to_period("M")).max()
        turbo_month = turbo_month.loc[
            (turbo_month.index >= pd.Period("2013-01","M")) &
            (turbo_month.index <= pd.Period("2026-07","M"))
        ]

        # OFF event = previous execution month Turbo ON, current execution month OFF.
        off_event = (~turbo_month) & turbo_month.shift(1, fill_value=False)
        off_months = off_event[off_event].index.tolist()

        progress.progress(34, text="Turbo OFFイベントをTarget状態と突合中…")
        feat = _v347_prepare_features(closes)

        rows = []
        for exec_month in off_months:
            # Existing execution convention:
            # current execution month reflects previous month-end signal.
            signal_month = exec_month - 1

            # Primary label uses target state in current execution month.
            persist_now = bool(target_map.get(exec_month, False))
            run_len = _v347_count_forward_aggressive_run(
                target_map, exec_month, max_months=24
            )

            target_row = target[target["Month"].eq(exec_month)]
            if target_row.empty:
                continue

            tr = target_row.iloc[0]

            row = {
                "ExecutionMonth": exec_month,
                "SignalMonth": signal_month,
                "PersistenceLabel": (
                    "Persist Aggressive" if persist_now else "De-risk / Other"
                ),
                "TargetAggressiveNow": persist_now,
                "TargetAggressiveNext2M": (
                    run_len >= 2
                ),
                "TargetAggressiveNext3M": (
                    run_len >= 3
                ),
                "ForwardAggressiveRunMonths": run_len,
                "TargetAggressiveWt": tr.get("AggressiveWt", np.nan),
                "TargetDefensiveWt": tr.get("DefensiveWt", np.nan),
                "TargetTQQQ": tr.get("TQQQ", np.nan),
                "TargetTECL": tr.get("TECL", np.nan),
                "TargetXLU": tr.get("XLU", np.nan),
                "TargetGLD": tr.get("GLD", np.nan),
                "TargetReturn": tr.get("TargetReturn", np.nan),
            }

            if signal_month in feat.index:
                fr = feat.loc[signal_month]
                for c in feat.columns:
                    row[c] = fr.get(c, np.nan)

            rows.append(row)

        events = pd.DataFrame(rows)
        if events.empty:
            raise RuntimeError("v3.47 sanity check failed: no eligible Turbo OFF events.")
        if events["PersistenceLabel"].nunique() < 2:
            raise RuntimeError(
                "v3.47 sanity check failed: only one target outcome class found."
            )

        features = [c for c in [
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "XLK_Inflect_1m3m","XLK_SMA100","XLK_SMA200",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
            "Delta_QQQ_mom3_1m","Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_mom3_1m","Delta_XLK_Inflect_1m3m_1m",
            "Delta_TLT_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_GLD_mom3_1m","Delta_XLK_minus_QQQ_6M_1m",
        ] if c in events.columns]

        progress.progress(52, text="Persist vs De-riskを比較中…")
        cmp_rows = []
        for f in features:
            a = events.loc[
                events["PersistenceLabel"].eq("Persist Aggressive"), f
            ].dropna()
            b = events.loc[
                events["PersistenceLabel"].eq("De-risk / Other"), f
            ].dropna()

            if len(a) < 1 or len(b) < 1:
                continue

            auc = _v334_pairwise_auc(a, b)
            cmp_rows.append({
                "Feature": f,
                "Persist median": a.median(),
                "De-risk median": b.median(),
                "Median delta": a.median() - b.median(),
                "Raw AUC(Persist>De-risk)": auc,
                "Directional AUC": max(auc, 1-auc),
                "Persist direction": "Higher" if auc >= .5 else "Lower",
                "N Persist": len(a),
                "N De-risk": len(b),
            })

        cmp = pd.DataFrame(cmp_rows)
        if not cmp.empty:
            cmp = cmp.sort_values(
                "Directional AUC", ascending=False
            ).reset_index(drop=True)

        progress.progress(64, text="Era stabilityを確認中…")
        era = _v347_era_compare(events, features)

        if not cmp.empty:
            same_labels = []
            for _, r in cmp.iterrows():
                g = era[era["Feature"].eq(r["Feature"])]
                full_high = r["Persist direction"] == "Higher"
                if len(g):
                    same = int(
                        ((g["Persist direction"].eq("Higher")) == full_high).sum()
                    )
                    same_labels.append(f"{same}/{len(g)}")
                else:
                    same_labels.append("0/0")
            cmp["Era same direction"] = same_labels

        progress.progress(74, text="Lead-up pathを作成中…")
        lead_features = [c for c in [
            "QQQ_mom3","QQQ_Inflect_1m3m","QQQ_SMA100",
            "XLK_mom3","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in feat.columns]

        lead_rows = []
        for klass in ["Persist Aggressive","De-risk / Other"]:
            sig_months = events.loc[
                events["PersistenceLabel"].eq(klass), "SignalMonth"
            ].tolist()

            for lag in [-2,-1,0]:
                for f in lead_features:
                    vals = []
                    for m in sig_months:
                        mm = m + lag
                        if mm in feat.index:
                            v = feat.loc[mm, f]
                            if pd.notna(v):
                                vals.append(float(v))
                    if vals:
                        lead_rows.append({
                            "Class": klass,
                            "LagMonths": lag,
                            "Feature": f,
                            "Median": float(np.median(vals)),
                            "N": len(vals),
                        })

        leadup = pd.DataFrame(lead_rows)

        # Persistence horizon summary.
        horizon = pd.DataFrame({
            "Measure": [
                "Eligible Turbo OFF events",
                "Persist Aggressive this month",
                "De-risk / Other this month",
                "Target aggressive >=2 months after OFF",
                "Target aggressive >=3 months after OFF",
                "Median forward aggressive run (all OFF events)",
                "Median forward aggressive run (Persist only)",
            ],
            "Value": [
                len(events),
                int(events["TargetAggressiveNow"].sum()),
                int((~events["TargetAggressiveNow"]).sum()),
                int(events["TargetAggressiveNext2M"].sum()),
                int(events["TargetAggressiveNext3M"].sum()),
                float(events["ForwardAggressiveRunMonths"].median()),
                float(
                    events.loc[
                        events["TargetAggressiveNow"],
                        "ForwardAggressiveRunMonths"
                    ].median()
                ),
            ],
        })

        # Target asset split within Persist cases.
        def target_asset_label(r):
            vals = {
                "TQQQ": float(r.get("TargetTQQQ", 0) or 0),
                "TECL": float(r.get("TargetTECL", 0) or 0),
                "XLU": float(r.get("TargetXLU", 0) or 0),
                "GLD": float(r.get("TargetGLD", 0) or 0),
            }
            pos = [k for k, v in vals.items() if v > 0.1]
            if len(pos) == 1:
                return pos[0]
            if len(pos) > 1:
                return "Mixed: " + "+".join(pos)
            return "Unknown"

        events["TargetAssetLabel"] = events.apply(target_asset_label, axis=1)
        asset_summary = (
            events.groupby(
                ["PersistenceLabel","TargetAssetLabel"], dropna=False
            )
            .size()
            .reset_index(name="Events")
            .sort_values(["PersistenceLabel","Events"], ascending=[True,False])
        )

        progress.progress(88, text="結果を表示中…")

        st.markdown("#### 1) Turbo OFF outcome")
        st.dataframe(horizon, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Fixed feature discrimination")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) Lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Target asset after Turbo OFF")
        st.dataframe(asset_summary, hide_index=True, use_container_width=True)

        st.markdown("#### 6) Exact event audit")
        audit = events.copy()
        audit["ExecutionMonth"] = audit["ExecutionMonth"].astype(str)
        audit["SignalMonth"] = audit["SignalMonth"].astype(str)

        audit_cols = [c for c in [
            "ExecutionMonth","SignalMonth","PersistenceLabel",
            "ForwardAggressiveRunMonths","TargetAssetLabel",
            "TargetAggressiveWt","TargetDefensiveWt",
            "TargetTQQQ","TargetTECL","TargetXLU","TargetGLD","TargetReturn",
            "QQQ_mom3","QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom3","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3","VIX",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in audit.columns]

        st.dataframe(
            audit[audit_cols].round(4),
            hide_index=True,
            use_container_width=True
        )

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile

        buf = _io.BytesIO()
        with _zipfile.ZipFile(
            buf, "w", compression=_zipfile.ZIP_DEFLATED
        ) as z:
            z.writestr(
                "01_turbo_off_outcome.csv",
                horizon.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_feature_discrimination.csv",
                cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_leadup_path.csv",
                leadup.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_target_asset_after_turbo_off.csv",
                asset_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_turbo_off_event_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 7) 保存")
        st.download_button(
            "📦 v3.47 Turbo Exit / Persistence Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_turbo_exit_persistence_autopsy_v347.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v347",
        )
        st.caption(
            "単一特徴がfull sample・Era・lead-upで一貫した場合だけ、"
            "次に固定Persistence Challengerを一発テストします。"
        )


def render_v346b_target_vs_v345_gap(px_close, rf_bt, start, end):
    st.markdown("### 🧩 v3.46b — Target vs v3.45 Aggression Gap Attribution FIX")
    st.caption(
        "目標戦略とv3.45を月次で直接突き合わせ、残りのCAGR差が"
        "『攻撃頻度』『攻撃資産』『Entry/Exit timing』のどこにあるかを分解します。"
    )
    st.info(
        "診断専用です。新しい売買ルールや閾値は作りません。"
        "開発比較は2026-07までに固定します。"
    )

    if st.button("Aggression Gapを解析", type="primary", key="run_v346"):
        progress = st.progress(0, text="Targetと価格系列を準備中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())
        target = target[target["Month"] <= pd.Period("2026-07", "M")].copy()

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        progress.progress(18, text="v3.45を再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(base_h, allow_l2)
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)
        _, attack75 = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        promote = (turbo_active & choose_tecl).reindex(idx).fillna(False).astype(bool)
        v345 = attack75.copy()
        v345.loc[promote] = asset_ret["TECL"].reindex(idx).loc[promote]

        progress.progress(36, text="月次状態を整列中…")
        v345m = _v346_v345_monthly_state(
            idx, turbo_active, choose_tecl, promote, attack75, v345, asset_ret
        )
        v345m = v345m[v345m["Month"] <= pd.Period("2026-07","M")].copy()

        t = target.copy()
        t["TargetClass"] = t.apply(_v346_classify_target, axis=1)
        t["TargetPrimaryAsset"] = t.apply(_v346_target_primary_asset, axis=1)

        keep = [c for c in [
            "Month","TargetReturn","AggressiveWt","DefensiveWt",
            "TQQQ","TECL","XLU","GLD","State","Position",
            "TargetClass","TargetPrimaryAsset"
        ] if c in t.columns]
        t = t[keep].copy()

        # _v330_normalize_target_table already creates decimal TargetReturn.
        if "TargetReturn" not in t.columns:
            raise RuntimeError("v3.46b sanity check failed: normalized target return missing.")
        t["TargetReturn"] = pd.to_numeric(t["TargetReturn"], errors="coerce")
        if t["TargetReturn"].notna().sum() == 0:
            raise RuntimeError("v3.46b sanity check failed: all normalized target returns are NaN.")

        merged = t.merge(v345m, on="Month", how="inner").sort_values("Month").reset_index(drop=True)
        if merged["TargetReturn"].notna().sum() == 0:
            raise RuntimeError("v3.46b sanity check failed: TargetReturn lost after merge.")

        # Core mismatch categories.
        def mismatch_category(r):
            tc = r["TargetClass"]
            vw = float(r["V345AttackWt"])
            va = r["V345AttackAsset"]
            ta = r["TargetPrimaryAsset"]

            if tc == "Target 100% Aggressive":
                if vw < 0.999:
                    return "Frequency gap: Target 100% Agg / v3.45 <100%"
                if ta in ["TQQQ","TECL"] and va in ["TQQQ","TECL"] and ta != va:
                    return "Asset gap: both aggressive / different asset"
                return "Aligned: both full aggressive"

            if tc == "Target 100% Defensive":
                if vw >= 0.999:
                    return "Over-aggressive: v3.45 100% / Target Defensive"
                return "Target Defensive / v3.45 not full aggressive"

            return "Target Mixed / other"

        merged["GapCategory"] = merged.apply(mismatch_category, axis=1)
        merged["ReturnGap_TargetMinusV345"] = merged["TargetReturn"] - merged["V345Return"]

        progress.progress(52, text="攻撃頻度・資産差を集計中…")
        category_summary = (
            merged.groupby("GapCategory", dropna=False)
            .agg(
                Months=("Month","count"),
                AvgTargetReturn=("TargetReturn","mean"),
                AvgV345Return=("V345Return","mean"),
                AvgMonthlyGap=("ReturnGap_TargetMinusV345","mean"),
                MedianMonthlyGap=("ReturnGap_TargetMinusV345","median"),
                SumMonthlyGap=("ReturnGap_TargetMinusV345","sum"),
            )
            .reset_index()
            .sort_values("SumMonthlyGap", ascending=False)
        )

        target_agg = merged[merged["TargetClass"].eq("Target 100% Aggressive")].copy()
        freq_summary = pd.DataFrame({
            "Measure": [
                "Target 100% Aggressive months",
                "…of which v3.45 also 100%",
                "…of which v3.45 only 75%",
                "…of which v3.45 baseline/non-Turbo",
                "Target full-aggressive coverage by v3.45",
            ],
            "Value": [
                len(target_agg),
                int((target_agg["V345AttackWt"] >= .999).sum()),
                int(np.isclose(target_agg["V345AttackWt"], .75).sum()),
                int((target_agg["V345AttackWt"] < .75).sum()),
                (
                    f"{(target_agg['V345AttackWt'] >= .999).mean()*100:.1f}%"
                    if len(target_agg) else "—"
                ),
            ],
        })

        asset_cross = pd.crosstab(
            target_agg["TargetPrimaryAsset"],
            target_agg["V345AttackAsset"],
            margins=True
        ).reset_index()

        progress.progress(66, text="Entry / Exit timing gapを計算中…")
        trans = _v346_transition_flags(merged)

        # Run-level timing attribution:
        # For each contiguous Target 100% Aggressive run, inspect whether/when v3.45
        # reaches 75% Turbo or 100% promotion inside the SAME target run.
        run_rows = []
        run_id = 0
        in_run = False
        run_start_i = None

        for i, flag in enumerate(trans["TargetAggFlag"].tolist()):
            if flag and not in_run:
                run_id += 1
                in_run = True
                run_start_i = i
            if in_run and (not flag or i == len(trans)-1):
                run_end_i = i - 1 if not flag else i
                g = trans.iloc[run_start_i:run_end_i+1].copy()
                start_m = g["Month"].iloc[0]
                end_m = g["Month"].iloc[-1]

                g75 = g[g["V345AttackWt"] >= .75]
                g100 = g[g["V345AttackWt"] >= .999]

                first75 = g75["Month"].iloc[0] if len(g75) else None
                first100 = g100["Month"].iloc[0] if len(g100) else None
                last75 = g75["Month"].iloc[-1] if len(g75) else None
                last100 = g100["Month"].iloc[-1] if len(g100) else None

                run_rows.append({
                    "Run": run_id,
                    "TargetRunStart": str(start_m),
                    "TargetRunEnd": str(end_m),
                    "TargetRunMonths": len(g),
                    "V345 >=75% months in run": int((g["V345AttackWt"] >= .75).sum()),
                    "V345 100% months in run": int((g["V345AttackWt"] >= .999).sum()),
                    "First >=75% month": str(first75) if first75 is not None else "",
                    "First 100% month": str(first100) if first100 is not None else "",
                    "Lag to first >=75% (months)": (
                        first75.ordinal - start_m.ordinal if first75 is not None else np.nan
                    ),
                    "Lag to first 100% (months)": (
                        first100.ordinal - start_m.ordinal if first100 is not None else np.nan
                    ),
                    "Last >=75% month": str(last75) if last75 is not None else "",
                    "Last 100% month": str(last100) if last100 is not None else "",
                    "Coverage >=75%": float((g["V345AttackWt"] >= .75).mean()),
                    "Coverage 100%": float((g["V345AttackWt"] >= .999).mean()),
                    "TargetRunReturn": float((1.0 + g["TargetReturn"].dropna()).prod() - 1.0),
                    "V345RunReturn": float((1.0 + g["V345Return"].dropna()).prod() - 1.0),
                })
                in_run = False
                run_start_i = None

        timing = pd.DataFrame(run_rows)

        timing_summary = pd.DataFrame()
        if not timing.empty:
            timing_summary = pd.DataFrame({
                "Measure": [
                    "Target Aggressive runs",
                    "Runs with any v3.45 >=75%",
                    "Runs with any v3.45 100%",
                    "Median lag to first >=75% (months)",
                    "Median lag to first 100% (months)",
                    "Median >=75% coverage inside Target run",
                    "Median 100% coverage inside Target run",
                ],
                "Value": [
                    len(timing),
                    int(timing["First >=75% month"].ne("").sum()),
                    int(timing["First 100% month"].ne("").sum()),
                    timing["Lag to first >=75% (months)"].median(),
                    timing["Lag to first 100% (months)"].median(),
                    timing["Coverage >=75%"].median(),
                    timing["Coverage 100%"].median(),
                ]
            })

        progress.progress(76, text="Return gap contributionをランキング中…")
        gap_rank = merged[[
            "Month","TargetClass","TargetPrimaryAsset",
            "V345State","V345AttackWt","V345AttackAsset",
            "TargetReturn","V345Return","ReturnGap_TargetMinusV345",
            "GapCategory"
        ]].copy()
        gap_rank["AbsGap"] = gap_rank["ReturnGap_TargetMinusV345"].abs()
        gap_rank = gap_rank.sort_values("AbsGap", ascending=False).drop(columns="AbsGap")
        gap_rank["Month"] = gap_rank["Month"].astype(str)

        # Positive gap months explain where target beat v3.45.
        positive_gap = merged[merged["ReturnGap_TargetMinusV345"] > 0].copy()
        positive_by_cat = (
            positive_gap.groupby("GapCategory")
            .agg(
                Months=("Month","count"),
                SumPositiveGap=("ReturnGap_TargetMinusV345","sum"),
                AvgPositiveGap=("ReturnGap_TargetMinusV345","mean"),
            )
            .reset_index()
            .sort_values("SumPositiveGap", ascending=False)
        )

        # Negative gap months show where v3.45 beat target.
        negative_gap = merged[merged["ReturnGap_TargetMinusV345"] < 0].copy()
        negative_by_cat = (
            negative_gap.groupby("GapCategory")
            .agg(
                Months=("Month","count"),
                SumNegativeGap=("ReturnGap_TargetMinusV345","sum"),
                AvgNegativeGap=("ReturnGap_TargetMinusV345","mean"),
            )
            .reset_index()
            .sort_values("SumNegativeGap")
        )

        progress.progress(88, text="結果を表示中…")

        st.markdown("#### 1) Target full-aggressive coverage")
        st.dataframe(freq_summary, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Gap category attribution")
        cat_show = category_summary.copy()
        for c in [
            "AvgTargetReturn","AvgV345Return","AvgMonthlyGap",
            "MedianMonthlyGap","SumMonthlyGap"
        ]:
            cat_show[c] = cat_show[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(cat_show, hide_index=True, use_container_width=True)

        st.markdown("#### 3) Target aggressive asset × v3.45 attack asset")
        st.dataframe(asset_cross, hide_index=True, use_container_width=True)

        st.markdown("#### 4) Entry / Exit timing")
        if timing_summary.empty:
            st.caption("Timing summary unavailable.")
        else:
            st.dataframe(timing_summary.round(2), hide_index=True, use_container_width=True)
            st.dataframe(timing, hide_index=True, use_container_width=True)

        st.markdown("#### 5) Where Target beats v3.45")
        pos_show = positive_by_cat.copy()
        for c in ["SumPositiveGap","AvgPositiveGap"]:
            if c in pos_show.columns:
                pos_show[c] = pos_show[c].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(pos_show, hide_index=True, use_container_width=True)

        st.markdown("#### 6) Where v3.45 beats Target")
        neg_show = negative_by_cat.copy()
        for c in ["SumNegativeGap","AvgNegativeGap"]:
            if c in neg_show.columns:
                neg_show[c] = neg_show[c].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(neg_show, hide_index=True, use_container_width=True)

        st.markdown("#### 7) Largest monthly gaps")
        gr = gap_rank.head(40).copy()
        for c in ["TargetReturn","V345Return","ReturnGap_TargetMinusV345"]:
            gr[c] = gr[c].map(lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%")
        st.dataframe(gr, hide_index=True, use_container_width=True)

        audit = merged.copy()
        audit["Month"] = audit["Month"].astype(str)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile

        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_full_aggressive_coverage.csv",
                freq_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_gap_category_attribution.csv",
                category_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_target_asset_vs_v345_asset.csv",
                asset_cross.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_target_aggressive_run_summary.csv",
                timing_summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_target_aggressive_run_audit.csv",
                timing.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_target_beats_v345_by_category.csv",
                positive_by_cat.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_v345_beats_target_by_category.csv",
                negative_by_cat.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_largest_monthly_gaps.csv",
                gap_rank.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_monthly_alignment_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 8) 保存")
        st.download_button(
            "📦 v3.46b Target-vs-v3.45 Gap Attribution FIX（ZIP）",
            data=buf.getvalue(),
            file_name="target_vs_v345_aggression_gap_attribution_v346b.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v346",
        )
        st.caption(
            "次のルール探索は、このAttributionで残差の主因が明確になった場合だけ行います。"
        )


def render_v345_tecl_leadership_promotion(px_close, rf_bt, start, end):
    st.markdown("### 🚀 v3.45 — TECL Leadership 100% Promotion Challenger #1")
    st.caption(
        "Controlはv3.35 Attack #1。Turbo中にXLK 6M > QQQ 6Mとなる既存のTECL選択局面だけ、"
        "75% TECLから100% TECLへ昇格します。"
    )
    st.info(
        "既存のAttack Asset selectorをattack intensityにも使うだけです。"
        "新しいindicator・lookback・thresholdは追加しません。"
    )
    st.warning(
        "一発検証です。開発期間は2026-07まで固定。"
        "採否はCAGRだけでなく、SortinoをSharpeより重く見つつ、"
        "Rolling P10、Daily/Monthly DD、CPCV、stress、年次で総合評価します。"
    )

    if st.button("TECL 100% Promotionを検証", type="primary", key="run_v345"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(10, text="Open価格を準備中…")
        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        progress.progress(22, text="Frozen Attack #1を再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)

        allow_l2 = gate_a & ~vix_brake
        avix_h = _v326_apply_l2_gate(base_h, allow_l2)

        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)

        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)

        # Frozen v3.35 selector:
        # XLK6M > QQQ6M -> TECL, otherwise TQQQ.
        choose_tecl, selector_audit = _v335_attack_selector_signal(closes, idx)
        choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

        progress.progress(38, text="Attack #1 Control returnを計算中…")
        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        _, attack75 = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        # Promotion condition:
        # frozen Turbo AND frozen TECL leadership selector.
        promote = (
            turbo_active
            & choose_tecl
        ).reindex(idx).fillna(False).astype(bool)

        challenger = attack75.copy()
        challenger.loc[promote] = asset_ret["TECL"].reindex(idx).loc[promote]

        changed = (
            (challenger - attack75)
            .abs()
            .fillna(0.0)
            .gt(1e-12)
        )

        if int(promote.sum()) == 0:
            raise RuntimeError("v3.45 sanity check failed: no TECL promotion days.")
        if int(changed.sum()) == 0:
            raise RuntimeError(
                "v3.45 sanity check failed: promotion activated but returns never changed."
            )

        daily = pd.DataFrame({
            "Base Adaptive ALL": base_ret,
            "Attack #1 Control": attack75,
            "TECL 100% Promotion": challenger,
        })
        daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
        variants = list(daily.columns)

        # Release large objects before robustness calculations.
        del core_h, base_h, avix_h, t1_h, opens

        progress.progress(52, text="Full metricsを計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl_name = "Attack #1 Control"
        chal_name = "TECL 100% Promotion"
        ctrl = metrics.loc[ctrl_name]

        metrics["ΔCAGR vs Control"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs Control"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs Control"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["DD change vs Control"] = metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]
        metrics["Monthly DD change vs Control"] = (
            metrics["Monthly MaxDD"] - ctrl["Monthly MaxDD"]
        )

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","ΔSortino vs Control","ΔSharpe vs Control",
            "DD change vs Control","Monthly DD change vs Control"
        ]
        show = metrics[show_cols].copy().astype(object)

        for c in [
            "CAGR","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","DD change vs Control",
            "Monthly DD change vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in [
            "Sortino0","Sharpe0","ΔSortino vs Control","ΔSharpe vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        progress.progress(62, text="Promotion activity / Rolling P10を集計中…")

        # Month-level promotion audit.
        promo_daily = pd.DataFrame({
            "Promotion": promote,
            "Changed": changed,
            "ChooseTECL": choose_tecl,
            "Turbo": turbo_active,
        }).loc[daily.index]

        promo_month = promo_daily.resample("ME").agg({
            "Promotion":"max",
            "Changed":"sum",
            "ChooseTECL":"mean",
            "Turbo":"max",
        })
        promo_month["Month"] = promo_month.index.to_period("M").astype(str)

        # Add frozen selector's raw monthly diagnostics if available.
        audit = promo_month.reset_index(drop=True)
        if isinstance(selector_audit, pd.DataFrame) and not selector_audit.empty:
            sa = selector_audit.copy()
            if "Month" in sa.columns:
                sa["Month"] = sa["Month"].astype(str)
                audit = audit.merge(sa, on="Month", how="left")

        activity = pd.DataFrame({
            "Measure": [
                "Turbo trading days",
                "TECL-selected Turbo trading days",
                "Promotion trading days",
                "Promotion share of trading days",
                "Promotion months",
                "Days returns actually changed",
            ],
            "Value": [
                int(turbo_active.reindex(daily.index).fillna(False).sum()),
                int((turbo_active & choose_tecl).reindex(daily.index).fillna(False).sum()),
                int(promote.reindex(daily.index).fillna(False).sum()),
                f"{promote.reindex(daily.index).fillna(False).mean()*100:.1f}%",
                int(audit["Promotion"].fillna(False).sum()),
                int(changed.reindex(daily.index).fillna(False).sum()),
            ],
        })

        st.markdown("#### 2) Promotion activity")
        st.dataframe(activity, hide_index=True, use_container_width=True)

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(72, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        cpcv_vs_ctrl, _ = _v326_cpcv_summary(
            monthly, ctrl_name, [chal_name]
        )
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL", [ctrl_name, chal_name]
        )

        def compact_cpcv(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                row = {
                    "Variant": v,
                    "Sortino wins": f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}",
                    "Sharpe wins": (
                        f"{int((g['Delta Sharpe0'] > 0).sum())}/{len(g)}"
                        if "Delta Sharpe0" in g.columns else "—"
                    ),
                    "Positive Active": f"{int(g['Positive Active'].sum())}/{len(g)}",
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                }
                if "Delta Sharpe0" in g.columns:
                    row["Median ΔSharpe"] = g["Delta Sharpe0"].median()
                    row["P10 ΔSharpe"] = g["Delta Sharpe0"].quantile(.10)
                rows.append(row)
            return pd.DataFrame(rows)

        st.markdown("#### 4) CPCV — Promotion vs Attack #1")
        st.dataframe(
            compact_cpcv(cpcv_vs_ctrl).round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 5) CPCV — Control / Promotion vs Base")
        st.dataframe(
            compact_cpcv(cpcv_vs_base).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(82, text="Stress / annual robustnessを確認中…")
        stress_windows = [
            ("2011 Jul-Oct", "2011-07-26", "2011-10-04"),
            ("2015 Jul-Aug", "2015-07-21", "2015-08-24"),
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2023 Jul-Oct", "2023-07-19", "2023-10-27"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress:
                sshow[v] = stress[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        annual = (1.0 + daily).resample("YE").prod() - 1.0
        annual.index = annual.index.year
        annual.index.name = "Year"

        st.markdown("#### 7) Calendar-year returns")
        ashow = annual.copy().astype(object)
        for v in variants:
            ashow[v] = annual[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(ashow, use_container_width=True)

        # Direct attribution only on promotion periods.
        attr = pd.DataFrame({
            "Control": attack75.reindex(daily.index),
            "Promotion": challenger.reindex(daily.index),
            "Active": challenger.reindex(daily.index) - attack75.reindex(daily.index),
            "Promote": promote.reindex(daily.index).fillna(False),
        })
        promo_only = attr[attr["Promote"]].copy()
        promo_only["Month"] = promo_only.index.to_period("M").astype(str)

        monthly_attr = []
        for m, g in promo_only.groupby("Month"):
            c = (1.0 + g["Control"].dropna()).prod() - 1.0
            p = (1.0 + g["Promotion"].dropna()).prod() - 1.0
            monthly_attr.append({
                "Month": m,
                "Attack #1": c,
                "TECL 100% Promotion": p,
                "Active": p - c,
                "TradingDays": len(g),
            })
        monthly_attr = pd.DataFrame(monthly_attr)

        st.markdown("#### 8) Promotion-month attribution")
        st.dataframe(
            monthly_attr.round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile

        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_promotion_activity.csv",
                activity.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_promotion_vs_control.csv",
                cpcv_vs_ctrl.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_annual_returns.csv",
                annual.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "08_promotion_month_attribution.csv",
                monthly_attr.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_selector_promotion_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "10_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.45 TECL Leadership 100% Promotion（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v345_tecl_leadership_100pct_promotion.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v345",
        )
        st.caption(
            "Attack #1を正式に置き換えるのは、CAGR上昇だけでなく、"
            "Sortino/Sharpe、Rolling P10、DD、CPCV、stressの総合結果が"
            "十分に維持・改善した場合だけです。"
        )


def render_v344_turbo_promotion_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🚀 v3.44 — Turbo 75% → 100% Promotion Autopsy")
    st.caption(
        "v3.35 Attack #1のTurbo月だけを固定母集団にして、"
        "75%攻撃のままが良かった月と、同じTQQQ/TECLを100%まで上げた方が"
        "良かった月を比較します。"
    )
    st.info(
        "診断専用です。100% Winnerは事後ラベルであり売買シグナルではありません。"
        "新しい閾値・lookback・AND/OR条件は探索しません。"
    )

    if st.button("Turbo Promotionを解析", type="primary", key="run_v344"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()
        asset_ret = opens.pct_change(fill_method=None)

        progress.progress(20, text="Frozen Attack #1を再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        avix_h = _v326_apply_l2_gate(base_h, allow_l2)
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)

        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)
        _, attack75 = _v335_build_t2_and_attack_returns(
            avix_ret, t1_ret,
            asset_ret["TQQQ"], asset_ret["TECL"],
            turbo_active, choose_tecl
        )

        attack_asset_ret = pd.Series(
            np.where(
                choose_tecl.reindex(idx).fillna(False).to_numpy(),
                asset_ret["TECL"].reindex(idx).to_numpy(),
                asset_ret["TQQQ"].reindex(idx).to_numpy(),
            ),
            index=idx, dtype=float
        )

        # Hypothetical 100% only during frozen Turbo; otherwise identical to Attack #1.
        attack100 = attack75.copy()
        attack100.loc[turbo_active] = attack_asset_ret.loc[turbo_active]

        progress.progress(42, text="Turbo月ごとの75% vs 100%を集計中…")

        daily_tmp = pd.DataFrame({
            "Attack75": attack75,
            "Attack100": attack100,
            "Turbo": turbo_active.astype(bool),
            "ChooseTECL": choose_tecl.reindex(idx).fillna(False).astype(bool),
        }).loc[:pd.Timestamp("2026-07-31")]

        # Each execution month is mapped to the immediately preceding signal month.
        # Compare compounded Open->Open return within Turbo execution months.
        monthly_rows = []
        for p, g in daily_tmp.groupby(daily_tmp.index.to_period("M")):
            tg = g[g["Turbo"]]
            if tg.empty:
                continue
            r75 = (1.0 + tg["Attack75"].dropna()).prod() - 1.0
            r100 = (1.0 + tg["Attack100"].dropna()).prod() - 1.0
            selected = "TECL" if tg["ChooseTECL"].mean() >= .5 else "TQQQ"
            monthly_rows.append({
                "ExecutionMonth": p,
                "SignalMonth": p - 1,
                "SelectedAttackAsset": selected,
                "Attack75Return": r75,
                "Attack100Return": r100,
                "PromotionActiveReturn": r100 - r75,
                "PromotionLabel": "100% Winner" if r100 > r75 else "75% Winner",
                "TurboTradingDays": int(len(tg)),
            })
        events = pd.DataFrame(monthly_rows)

        if events.empty:
            raise RuntimeError("v3.44 sanity check failed: no Turbo months.")

        feat = _v344_prepare_promotion_features(closes)
        events = events.merge(
            feat.reset_index(names="SignalMonth"),
            on="SignalMonth", how="left"
        )

        features = [c for c in [
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "XLK_Inflect_1m3m","XLK_SMA100","XLK_SMA200",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
            "Delta_QQQ_mom3_1m","Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_mom3_1m","Delta_XLK_Inflect_1m3m_1m",
            "Delta_TLT_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_GLD_mom3_1m","Delta_XLK_minus_QQQ_6M_1m",
        ] if c in events.columns]

        progress.progress(60, text="100% Winner vs 75% Winnerを比較中…")
        rows = []
        for f in features:
            a = events.loc[events["PromotionLabel"].eq("100% Winner"), f].dropna()
            b = events.loc[events["PromotionLabel"].eq("75% Winner"), f].dropna()
            if len(a) < 1 or len(b) < 1:
                continue
            auc = _v334_pairwise_auc(a, b)
            rows.append({
                "Feature": f,
                "100% Winner median": a.median(),
                "75% Winner median": b.median(),
                "Median delta": a.median() - b.median(),
                "Raw AUC(100%>75%)": auc,
                "Directional AUC": max(auc, 1-auc),
                "100% Winner direction": "Higher" if auc >= .5 else "Lower",
                "N 100%": len(a), "N 75%": len(b),
            })
        cmp = pd.DataFrame(rows)
        if not cmp.empty:
            cmp = cmp.sort_values("Directional AUC", ascending=False).reset_index(drop=True)

        progress.progress(72, text="Era stabilityを確認中…")
        era = _v344_era_compare(events, features)

        if not cmp.empty:
            labels = []
            for _, row in cmp.iterrows():
                g = era[era["Feature"].eq(row["Feature"])]
                full_higher = row["100% Winner direction"] == "Higher"
                if len(g):
                    same = int(((g["100% Winner direction"] == "Higher") == full_higher).sum())
                    labels.append(f"{same}/{len(g)}")
                else:
                    labels.append("0/0")
            cmp["Era same direction"] = labels

        counts = (
            events["PromotionLabel"].value_counts()
            .rename_axis("Label").reset_index(name="Turbo months")
        )

        asset_counts = pd.crosstab(
            events["SelectedAttackAsset"], events["PromotionLabel"]
        ).reset_index()

        progress.progress(84, text="Lead-up pathを作成中…")
        lead_features = [c for c in [
            "QQQ_mom3","QQQ_Inflect_1m3m",
            "XLK_mom3","XLK_Inflect_1m3m",
            "XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3",
            "VIX","CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in feat.columns]

        lead_rows = []
        feat_by_month = feat.copy()
        for klass in ["100% Winner","75% Winner"]:
            months = events.loc[events["PromotionLabel"].eq(klass), "SignalMonth"].tolist()
            for lag in [-2,-1,0]:
                for f in lead_features:
                    vals = []
                    for m in months:
                        mm = m + lag
                        if mm in feat_by_month.index:
                            v = feat_by_month.loc[mm, f]
                            if pd.notna(v):
                                vals.append(float(v))
                    if vals:
                        lead_rows.append({
                            "Class": klass, "LagMonths": lag, "Feature": f,
                            "Median": float(np.median(vals)), "N": len(vals)
                        })
        leadup = pd.DataFrame(lead_rows)

        # Audit-friendly month strings.
        audit = events.copy()
        audit["ExecutionMonth"] = audit["ExecutionMonth"].astype(str)
        audit["SignalMonth"] = audit["SignalMonth"].astype(str)

        progress.progress(94, text="結果を表示中…")

        st.markdown("#### 1) Turbo promotion outcome")
        st.dataframe(counts, hide_index=True, use_container_width=True)
        st.dataframe(asset_counts, hide_index=True, use_container_width=True)
        st.caption(
            "100% Winner / 75% Winnerは事後的な実現リターン比較です。"
            "このラベル自体をシグナルとして使用してはいけません。"
        )

        st.markdown("#### 2) Fixed feature discrimination")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) Lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Exact Turbo-month audit")
        audit_cols = [c for c in [
            "ExecutionMonth","SignalMonth","SelectedAttackAsset",
            "Attack75Return","Attack100Return","PromotionActiveReturn",
            "PromotionLabel","TurboTradingDays",
            "QQQ_mom3","QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom3","XLK_Inflect_1m3m","XLK_minus_QQQ_6M",
            "TLT_mom3","LQD_mom3","GLD_mom3","VIX",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in audit.columns]
        st.dataframe(audit[audit_cols].round(4), hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr("01_promotion_counts.csv",
                       counts.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("02_asset_by_outcome.csv",
                       asset_counts.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("03_feature_discrimination.csv",
                       cmp.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("04_era_stability.csv",
                       era.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("05_leadup_path.csv",
                       leadup.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("06_turbo_month_audit.csv",
                       audit.to_csv(index=False).encode("utf-8-sig"))

        st.markdown("#### 6) 保存")
        st.download_button(
            "📦 v3.44 Turbo Promotion Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_turbo_75_to_100_promotion_autopsy_v344.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v344",
        )
        st.caption(
            "ここでは75→100%昇格ルールを作りません。"
            "単一特徴が全期間・Era・lead-upで安定している場合だけ、"
            "次の固定Promotion Challengerを一発テストします。"
        )


def render_v343_exhaustion_one_month_brake(px_close, rf_bt, start, end):
    st.markdown("### 🛑 v3.43 — QQQ Exhaustion One-Month Brake Challenger #1")
    st.caption(
        "Attack #1をControlとして固定。QQQ Exhaustion Zが0を下→上にクロスした"
        "イベント月だけ、次の実行月を100% XLUにします。"
    )
    st.info(
        "Persistent Risk-Offではありません。Brakeは1か月だけで自動解除し、"
        "その後はAttack #1へ戻ります。"
    )
    st.warning(
        "閾値探索なし・lookback探索なし・AND/OR条件なし。"
        "Exhaustion Z=0のup-crossを一発だけ検証します。開発期間は2026-07まで固定。"
    )

    if st.button("One-Month Brakeを検証", type="primary", key="run_v343"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(10, text="Open価格を準備中…")
        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()

        progress.progress(22, text="Attack #1 Controlを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)

        allow_l2 = gate_a & ~vix_brake
        avix_h = _v326_apply_l2_gate(base_h, allow_l2)

        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)

        progress.progress(40, text="Control Open→Open returnを計算中…")
        asset_ret = opens.pct_change(fill_method=None)
        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        _, attack_ret = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        progress.progress(52, text="QQQ Exhaustion Z eventを構築中…")
        ez, event_monthly, event_audit = _v343_exhaustion_z_monthly(closes)
        brake_eff = _v343_one_month_effective_signal(event_monthly, idx)
        brake = brake_eff.reindex(idx).fillna(False).astype(bool)

        challenger_ret = attack_ret.copy()
        challenger_ret.loc[brake] = asset_ret["XLU"].reindex(idx).loc[brake]

        changed = (
            (challenger_ret - attack_ret).abs()
            .fillna(0.0)
            .gt(1e-12)
        )

        if int(event_monthly.sum()) == 0:
            raise RuntimeError("v3.43 sanity check failed: no Exhaustion Z up-cross events.")
        if int(brake.sum()) == 0:
            raise RuntimeError("v3.43 sanity check failed: no effective Brake days.")
        if int(changed.sum()) == 0:
            raise RuntimeError(
                "v3.43 sanity check failed: Brake activated but returns never changed."
            )

        daily = pd.DataFrame({
            "Base Adaptive ALL": base_ret,
            "Attack #1 Control": attack_ret,
            "Exhaustion 1M Brake": challenger_ret,
        })
        daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
        variants = list(daily.columns)

        # Free large holding matrices before robustness tests.
        del core_h, base_h, avix_h, t1_h, opens

        progress.progress(64, text="Full metrics / Rolling P10を計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl_name = "Attack #1 Control"
        chal_name = "Exhaustion 1M Brake"
        ctrl = metrics.loc[ctrl_name]

        metrics["ΔCAGR vs Control"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs Control"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs Control"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["DD change vs Control"] = metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","ΔSortino vs Control",
            "ΔSharpe vs Control","DD change vs Control"
        ]
        show = metrics[show_cols].copy().astype(object)
        for c in [
            "CAGR","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","DD change vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in [
            "Sortino0","Sharpe0","ΔSortino vs Control","ΔSharpe vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        # Monthly event / effective activity audit.
        eff_month = pd.DataFrame({"Effective Brake": brake}).resample("ME").max()
        eff_month["Month"] = eff_month.index.to_period("M").astype(str)
        audit = event_audit.merge(
            eff_month[["Month","Effective Brake"]],
            on="Month", how="left"
        )
        audit = audit[
            pd.PeriodIndex(audit["Month"], freq="M")
            <= pd.Period("2026-07","M")
        ].copy()

        activity = pd.DataFrame({
            "Measure": [
                "Raw Exhaustion Z up-cross events",
                "Effective Brake months",
                "Effective Brake trading days",
                "Brake share of trading days",
                "Days returns actually changed",
            ],
            "Value": [
                int(event_monthly.loc[
                    event_monthly.index <= pd.Timestamp("2026-07-31")
                ].sum()),
                int(audit["Effective Brake"].fillna(False).sum()),
                int(brake.reindex(daily.index).fillna(False).sum()),
                f"{brake.reindex(daily.index).fillna(False).mean()*100:.1f}%",
                int(changed.reindex(daily.index).fillna(False).sum()),
            ],
        })
        st.markdown("#### 2) Brake activity")
        st.dataframe(activity, hide_index=True, use_container_width=True)

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(76, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        cpcv_vs_ctrl, _ = _v326_cpcv_summary(
            monthly, ctrl_name, [chal_name]
        )
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL", [ctrl_name, chal_name]
        )

        def compact_cpcv(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                row = {
                    "Variant": v,
                    "Sortino wins": f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}",
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Positive Active": f"{int(g['Positive Active'].sum())}/{len(g)}",
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                }
                if "Delta Sharpe0" in g.columns:
                    row["Median ΔSharpe"] = g["Delta Sharpe0"].median()
                    row["P10 ΔSharpe"] = g["Delta Sharpe0"].quantile(.10)
                rows.append(row)
            return pd.DataFrame(rows)

        st.markdown("#### 4) CPCV — Brake vs Attack #1")
        st.dataframe(
            compact_cpcv(cpcv_vs_ctrl).round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 5) CPCV — Control / Brake vs Base")
        st.dataframe(
            compact_cpcv(cpcv_vs_base).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(86, text="Stress / annual robustnessを確認中…")
        stress_windows = [
            ("2011 Jul-Oct", "2011-07-26", "2011-10-04"),
            ("2015 Jul-Aug", "2015-07-21", "2015-08-24"),
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2023 Jul-Oct", "2023-07-19", "2023-10-27"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress:
                sshow[v] = stress[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        annual = (1.0 + daily).resample("YE").prod() - 1.0
        annual.index = annual.index.year
        annual.index.name = "Year"

        st.markdown("#### 7) Calendar-year returns")
        ashow = annual.copy().astype(object)
        for v in variants:
            ashow[v] = annual[v].map(lambda x: f"{x*100:+.2f}%")
        st.dataframe(ashow, use_container_width=True)

        st.markdown("#### 8) Exhaustion event audit")
        st.dataframe(
            audit[audit["Up-Cross Event"].fillna(False) | audit["Effective Brake"].fillna(False)]
            .round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_brake_vs_control.csv",
                cpcv_vs_ctrl.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_annual_returns.csv",
                annual.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "08_exhaustion_event_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_brake_activity.csv",
                activity.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.43 Exhaustion One-Month Brake（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v343_qqq_exhaustion_one_month_brake.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v343",
        )
        st.caption(
            "採否はCAGRだけで決めません。SortinoをSharpeより重く見つつ、"
            "Rolling P10、Daily/Monthly DD、CPCV、stress、年次を総合評価します。"
        )


def render_v342_momentum_exhaustion_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🧭 v3.42 — Risk-Off Momentum Exhaustion Autopsy")
    st.caption(
        "目標戦略のAggressive→Defensive 13回をすべて使い、"
        "『中期momentumは強いまま、短期momentumだけ急失速する』構造を診断します。"
    )
    st.info(
        "診断専用です。AND条件や売買ルールは作りません。"
        "新しいlookback・閾値・組み合わせ探索も行いません。"
    )

    if st.button("Momentum Exhaustionを解析", type="primary", key="run_v342"):
        progress = st.progress(0, text="目標履歴と価格系列を準備中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())

        needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(24, text="固定特徴量とExhaustion構造を計算中…")
        data = _v342_prepare_momentum_exhaustion(target, closes)

        counts = (
            data["EntryClass"]
            .value_counts()
            .rename_axis("Class")
            .reset_index(name="Months")
        )

        features = [c for c in [
            # Core momentum structure
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_Inflect_1m6m",
            "QQQ_SMA100","QQQ_SMA200",
            "QQQ_ExhaustionProduct","QQQ_ExhaustionZ",

            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "XLK_Inflect_1m3m","XLK_Inflect_1m6m",
            "XLK_SMA100","XLK_SMA200",
            "XLK_ExhaustionProduct","XLK_ExhaustionZ",

            # Previously discovered contextual features
            "GLD_mom3","LQD_mom3","TLT_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",

            # Change terms already predeclared above
            "Delta_QQQ_mom3_1m","Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_mom3_1m","Delta_XLK_Inflect_1m3m_1m",
            "Delta_GLD_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_TLT_mom3_1m",
        ] if c in data.columns]

        progress.progress(44, text="Entry vs continuationを比較中…")
        cmp = _v342_compare_groups(data, features)

        progress.progress(58, text="Era stabilityを確認中…")
        era = _v342_era_stability(data, features)

        if not cmp.empty:
            era_labels = []
            for _, row in cmp.iterrows():
                f = row["Feature"]
                g = era[era["Feature"].eq(f)]
                full_higher = row["Entry direction"] == "Higher"
                if len(g):
                    same = int(((g["Direction"] == "Higher") == full_higher).sum())
                    era_labels.append(f"{same}/{len(g)}")
                else:
                    era_labels.append("0/0")
            cmp["Era same direction"] = era_labels

        progress.progress(70, text="Lead-up pathを作成中…")
        lead_features = [c for c in [
            "QQQ_mom3","QQQ_Inflect_1m3m","QQQ_ExhaustionZ",
            "XLK_mom3","XLK_Inflect_1m3m","XLK_ExhaustionZ",
            "QQQ_SMA100","QQQ_SMA200",
            "GLD_mom3","LQD_mom3","TLT_mom3",
            "VIX","Delta_VIX_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in data.columns]
        leadup = _v342_leadup(data, lead_features)

        progress.progress(80, text="2D quadrantを作成中…")
        qqq_quad, qqq_meta = _v342_quadrant_table(data, "QQQ")
        xlk_quad, xlk_meta = _v342_quadrant_table(data, "XLK")

        event_cols = [c for c in [
            "Month","PrevState","State","Transition","Position","EntryClass",
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "QQQ_ExhaustionProduct","QQQ_ExhaustionZ",
            "XLK_mom3","XLK_Inflect_1m3m",
            "XLK_ExhaustionProduct","XLK_ExhaustionZ",
            "GLD_mom3","LQD_mom3","TLT_mom3",
            "VIX","Delta_VIX_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in data.columns]
        events = data[
            data["EntryClass"].isin(["Risk-Off Entry","Aggressive Continue"])
        ][event_cols].copy()
        events["Month"] = events["Month"].astype(str)

        progress.progress(92, text="結果を表示中…")

        st.markdown("#### 1) Event counts")
        st.dataframe(counts, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Risk-Off Entry vs Aggressive Continue")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) 3-month lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) QQQ descriptive 2D quadrant")
        st.caption(
            "3M momentumと1M−3M inflectionをeligible sample中央値で4象限化。"
            "これは構造確認専用で、閾値や売買ルールには使用しません。"
        )
        st.dataframe(qqq_meta.round(4), hide_index=True, use_container_width=True)
        st.dataframe(qqq_quad.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 6) XLK descriptive 2D quadrant")
        st.dataframe(xlk_meta.round(4), hide_index=True, use_container_width=True)
        st.dataframe(xlk_quad.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 7) Exact eligible events")
        st.dataframe(events.round(4), hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_event_counts.csv",
                counts.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_entry_vs_continue.csv",
                cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_leadup_median_path.csv",
                leadup.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_qqq_quadrant.csv",
                qqq_quad.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_qqq_quadrant_meta.csv",
                qqq_meta.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_xlk_quadrant.csv",
                xlk_quad.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_xlk_quadrant_meta.csv",
                xlk_meta.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_eligible_event_audit.csv",
                events.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 8) 保存")
        st.download_button(
            "📦 v3.42 Momentum Exhaustion Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_riskoff_momentum_exhaustion_autopsy_v342.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v342",
        )
        st.caption(
            "次のChallengerへ進むのは、単なる高dAUCだけでなく、"
            "13 Entry全体・Era方向・lead-up・2D構造が整合した場合だけです。"
        )


def render_v341_tlt_downcross_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🔬 v3.41 — TLT Down-Cross True-vs-False Entry Autopsy")
    st.caption(
        "TLT3Mの +→− down-crossを固定母集団にし、目標戦略が本当にAggressive→Defensiveへ"
        "遷移したcrossと、Aggressiveを継続したcrossの違いだけを診断します。"
    )
    st.info(
        "診断専用です。新しい売買ルールは作りません。"
        "閾値探索・lookback探索・AND/OR条件探索はありません。"
    )

    if st.button("True vs False Entryを解析", type="primary", key="run_v341"):
        progress = st.progress(0, text="目標戦略と価格系列を準備中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())

        needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(25, text="TLT3M down-cross eventsを分類中…")
        data, feat = _v341_prepare_downcross_autopsy(target, closes)

        # Fixed, predeclared feature set from prior autopsies.
        features = [c for c in [
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "XLK_mom1","XLK_mom3","XLK_mom6",
            "XLK_Inflect_1m3m","XLK_SMA100","XLK_SMA200",
            "GLD_mom3","GLD_mom6",
            "LQD_mom3","LQD_mom6",
            "TLT_mom3","TLT_mom6",
            "XLU_mom3","XLU_mom6",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
            "Delta_QQQ_mom3_1m","Delta_GLD_mom3_1m",
            "Delta_LQD_mom3_1m","Delta_TLT_mom3_1m",
            "Delta_QQQ_Inflect_1m3m_1m",
            "Delta_XLK_Inflect_1m3m_1m",
        ] if c in data.columns]

        events = data[data["TLT3M_DownCross"].fillna(False)].copy()
        class_counts = (
            events["DownCrossClass"]
            .value_counts()
            .rename_axis("Class")
            .reset_index(name="Events")
        )

        progress.progress(45, text="True Entry vs False Entryを比較中…")
        cmp = _v341_compare_true_false(data, features)

        progress.progress(60, text="Era stabilityを確認中…")
        era = _v341_era_stability(data, features)

        # Add era same-direction summary to main comparison.
        if not cmp.empty and not era.empty:
            summaries = []
            for _, row in cmp.iterrows():
                f = row["Feature"]
                g = era[era["Feature"].eq(f)]
                full_higher = row["True Entry direction"] == "Higher"
                if len(g):
                    same = int(((g["Direction"] == "Higher") == full_higher).sum())
                    label = f"{same}/{len(g)}"
                else:
                    label = "0/0"
                summaries.append(label)
            cmp["Era same direction"] = summaries

        progress.progress(74, text="Lead-up pathを作成中…")
        lead_features = [c for c in [
            "QQQ_Inflect_1m3m","QQQ_mom3","QQQ_SMA100",
            "GLD_mom3","LQD_mom3","TLT_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in data.columns]
        leadup = _v341_leadup(data, lead_features)

        event_cols = [c for c in [
            "Month","PrevState","State","Transition","Position",
            "TLT_mom3","Prev_TLT_mom3","TLT3M_DownCross","DownCrossClass",
            "QQQ_mom3","QQQ_Inflect_1m3m","QQQ_SMA100","QQQ_SMA200",
            "GLD_mom3","LQD_mom3","XLU_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in events.columns]
        event_audit = events[event_cols].copy()
        event_audit["Month"] = event_audit["Month"].astype(str)

        progress.progress(90, text="結果を表示中…")

        st.markdown("#### 1) Down-cross classification")
        st.dataframe(class_counts, hide_index=True, use_container_width=True)
        st.caption(
            "True Entry = TLT3M down-crossと同じ月に目標がAgg→Def。"
            "False Entry = down-crossと同じ月でも目標はAgg→Agg。"
            "Otherは既にDefensive/Mixed等で、識別比較から除外します。"
        )

        st.markdown("#### 2) True Entry vs False Entry")
        st.dataframe(cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) 3-month lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Exact TLT3M down-cross events")
        st.dataframe(event_audit.round(4), hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_downcross_class_counts.csv",
                class_counts.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_true_vs_false_entry.csv",
                cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_leadup_median_path.csv",
                leadup.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_downcross_event_audit.csv",
                event_audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 6) 保存")
        st.download_button(
            "📦 v3.41 TLT Down-Cross Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_tlt_downcross_true_false_autopsy_v341.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v341",
        )
        st.caption(
            "ここではconfirmation ruleを作りません。"
            "単一特徴が方向・Era・lead-upまで揃う場合だけ次の固定Challengerへ進みます。"
        )


def render_v340_tlt3m_state_machine(px_close, rf_bt, start, end):
    st.markdown("### 🔁 v3.40 — TLT3M State-Machine Challenger #1")
    st.caption(
        "Attack #1をControlとして固定し、TLT3Mの0クロスだけでRisk-On/Risk-Off状態を遷移させます。"
    )
    st.info(
        "Risk-On→Risk-Off：TLT3Mが +→− クロス。"
        "Risk-Off→Risk-On：TLT3Mが −→+ クロス。"
        "Risk-Off先は100% XLU固定です。"
    )
    st.warning(
        "閾値探索なし・6M比較なし・XLU/GLD selectorなし。"
        "状態機械そのものの価値だけを一発検証します。開発期間は2026-07まで固定。"
    )

    if st.button("TLT3M State-Machineを検証", type="primary", key="run_v340"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(10, text="Open価格を準備中…")
        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()

        progress.progress(22, text="Attack #1 Controlを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)

        allow_l2 = gate_a & ~vix_brake
        avix_h = _v326_apply_l2_gate(base_h, allow_l2)

        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)

        choose_tecl, _ = _v335_attack_selector_signal(closes, idx)

        progress.progress(40, text="Control Open→Open returnを計算中…")
        asset_ret = opens.pct_change(fill_method=None)
        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        _, attack_ret = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        progress.progress(52, text="TLT3M State-Machineを構築中…")
        riskoff_eff, state_audit = _v340_tlt3m_state_machine(closes, idx)
        riskoff = riskoff_eff.reindex(idx).fillna(False).astype(bool)

        challenger_ret = attack_ret.copy()
        challenger_ret.loc[riskoff] = asset_ret["XLU"].reindex(idx).loc[riskoff]

        changed = (
            (challenger_ret - attack_ret).abs()
            .fillna(0.0)
            .gt(1e-12)
        )

        # Hard checks against another silent no-op.
        if int(riskoff.sum()) == 0:
            raise RuntimeError(
                "v3.40 sanity check failed: Risk-Off state never activated."
            )
        if int(changed.sum()) == 0:
            raise RuntimeError(
                "v3.40 sanity check failed: Risk-Off activated but returns never changed."
            )

        daily = pd.DataFrame({
            "Base Adaptive ALL": base_ret,
            "Attack #1 Control": attack_ret,
            "TLT3M State-Machine": challenger_ret,
        })
        daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
        variants = list(daily.columns)

        # Free memory before CPCV.
        del core_h, base_h, avix_h, t1_h, opens

        progress.progress(64, text="Full metrics / Rolling P10を計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl_name = "Attack #1 Control"
        chal_name = "TLT3M State-Machine"
        ctrl = metrics.loc[ctrl_name]

        metrics["ΔCAGR vs Control"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs Control"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs Control"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["DD change vs Control"] = metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","ΔSortino vs Control",
            "ΔSharpe vs Control","DD change vs Control"
        ]
        show = metrics[show_cols].copy().astype(object)
        for c in [
            "CAGR","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","DD change vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in [
            "Sortino0","Sharpe0","ΔSortino vs Control","ΔSharpe vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        r = riskoff.reindex(daily.index).fillna(False)
        # Count raw monthly state transitions.
        raw_state = state_audit["Raw Risk-Off State"].fillna(False).astype(bool)
        raw_switches = int(raw_state.ne(raw_state.shift(1)).sum() - 1) if len(raw_state) else 0

        activity = pd.DataFrame({
            "Measure": [
                "Risk-Off trading days",
                "Risk-Off share of sample",
                "Raw monthly state switches",
                "Down-cross entries",
                "Up-cross exits",
                "Days returns actually changed",
            ],
            "Value": [
                int(r.sum()),
                f"{r.mean()*100:.1f}%",
                raw_switches,
                int(state_audit["Down Cross"].sum()),
                int(state_audit["Up Cross"].sum()),
                int(changed.reindex(daily.index).fillna(False).sum()),
            ],
        })
        st.markdown("#### 2) State activity")
        st.dataframe(activity, hide_index=True, use_container_width=True)

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(76, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        cpcv_vs_ctrl, _ = _v326_cpcv_summary(
            monthly, ctrl_name, [chal_name]
        )
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL", [ctrl_name, chal_name]
        )

        def compact_cpcv(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                row = {
                    "Variant": v,
                    "Sortino wins": f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}",
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Positive Active": f"{int(g['Positive Active'].sum())}/{len(g)}",
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                }
                if "Delta Sharpe0" in g.columns:
                    row["Median ΔSharpe"] = g["Delta Sharpe0"].median()
                    row["P10 ΔSharpe"] = g["Delta Sharpe0"].quantile(.10)
                rows.append(row)
            return pd.DataFrame(rows)

        st.markdown("#### 4) CPCV — State-Machine vs Attack #1")
        st.dataframe(
            compact_cpcv(cpcv_vs_ctrl).round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 5) CPCV — Control / Challenger vs Base")
        st.dataframe(
            compact_cpcv(cpcv_vs_base).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(86, text="Stress / annual robustnessを確認中…")
        stress_windows = [
            ("2011 Jul-Oct", "2011-07-26", "2011-10-04"),
            ("2015 Jul-Aug", "2015-07-21", "2015-08-24"),
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2023 Jul-Oct", "2023-07-19", "2023-10-27"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress:
                sshow[v] = stress[v].map(lambda x:f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        annual = (1.0 + daily).resample("YE").prod() - 1.0
        annual.index = annual.index.year
        annual.index.name = "Year"

        st.markdown("#### 7) Calendar-year returns")
        ashow = annual.copy().astype(object)
        for v in variants:
            ashow[v] = annual[v].map(lambda x:f"{x*100:+.2f}%")
        st.dataframe(ashow, use_container_width=True)

        # Monthly audit: raw state plus effective month-end trading state.
        eff_month = pd.DataFrame({"Effective Risk-Off": riskoff}).resample("ME").last()
        eff_month["Month"] = eff_month.index.to_period("M").astype(str)
        audit = state_audit.merge(
            eff_month[["Month","Effective Risk-Off"]],
            on="Month", how="left"
        )
        audit = audit[
            pd.PeriodIndex(audit["Month"], freq="M")
            <= pd.Period("2026-07","M")
        ]

        st.markdown("#### 8) Recent State-Machine audit")
        st.dataframe(
            audit.tail(36).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_state_machine_vs_control.csv",
                cpcv_vs_ctrl.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_annual_returns.csv",
                annual.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "08_state_machine_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "09_state_activity.csv",
                activity.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.40 TLT3M State-Machine（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v340_tlt3m_state_machine_challenger_1.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v340",
        )
        st.caption(
            "評価はCAGRだけでなく、Rolling P10、SortinoをSharpeより重く見つつ、"
            "Daily/Monthly DD、CPCV、stress windows、年次安定性を総合します。"
        )


def render_v339_riskoff_entry_exit_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🔁 v3.39 — Risk-Off Entry vs Exit Autopsy")
    st.caption(
        "目標戦略のAggressive→DefensiveとDefensive→Aggressiveを同じ固定特徴量で比較し、"
        "Entry/Exitが対称か、ヒステリシス型かを診断します。"
    )
    st.info(
        "診断のみ。新しいRisk-Off売買ルールは作りません。"
        "閾値探索・lookback探索・AND条件探索なし。目標履歴は2026-07まで固定。"
    )

    if st.button("Entry vs Exit を解析", type="primary", key="run_v339"):
        progress = st.progress(0, text="目標戦略履歴を復元中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())

        needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(20, text="固定特徴量を計算中…")
        data, feat = _v339_prepare_transition_dataset(target, closes)

        # Fixed feature set. No post-result feature generation.
        features = [c for c in [
            # Equity momentum / trend
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "QQQ_SMA100","QQQ_SMA200","XLK_SMA100","XLK_SMA200",

            # Equity inflection
            "QQQ_Inflect_1m3m","QQQ_Inflect_1m6m","QQQ_Inflect_3m12m",
            "XLK_Inflect_1m3m","XLK_Inflect_1m6m","XLK_Inflect_3m12m",

            # Defensive / bond momentum
            "GLD_mom1","GLD_mom3","GLD_mom6","GLD_mom12",
            "LQD_mom1","LQD_mom3","LQD_mom6","LQD_mom12",
            "TLT_mom1","TLT_mom3","TLT_mom6","TLT_mom12",
            "XLU_mom1","XLU_mom3","XLU_mom6","XLU_mom12",

            # Relative strength
            "XLK_minus_QQQ_1m","XLK_minus_QQQ_3m",
            "XLK_minus_QQQ_6m","XLK_minus_QQQ_12m",
            "QQQ_minus_GLD_3m","QQQ_minus_GLD_6m",
            "QQQ_minus_XLU_3m","QQQ_minus_XLU_6m",
            "TLT_minus_GLD_3m","TLT_minus_GLD_6m",

            # Stress / correlation
            "VIX","Delta_VIX_1m",
            "RiskCorr20","RiskCorr60","CrossAssetAbsCorr20",
            "Delta_RiskCorr20_1m","Delta_RiskCorr60_1m",
            "Delta_CrossAssetAbsCorr20_1m",

            # One-month changes in fixed momentum levels
            "Delta_QQQ_mom1_1m","Delta_QQQ_mom3_1m",
            "Delta_QQQ_mom6_1m","Delta_QQQ_mom12_1m",
            "Delta_XLK_mom1_1m","Delta_XLK_mom3_1m",
            "Delta_XLK_mom6_1m","Delta_XLK_mom12_1m",
            "Delta_GLD_mom3_1m","Delta_LQD_mom3_1m",
            "Delta_TLT_mom3_1m","Delta_XLU_mom3_1m",
        ] if c in data.columns]

        progress.progress(38, text="Transition counts / direct comparisonsを集計中…")
        counts = (
            data["Transition"]
            .value_counts(dropna=False)
            .rename_axis("Transition")
            .reset_index(name="Months")
        )

        entry_cmp = _v336_compare_groups(
            data,
            data["Transition"].eq("Aggressive→Defensive"),
            data["Transition"].eq("Aggressive→Aggressive"),
            "Agg→Def",
            "Agg→Agg",
            features,
        )
        exit_cmp = _v336_compare_groups(
            data,
            data["Transition"].eq("Defensive→Aggressive"),
            data["Transition"].eq("Defensive→Defensive"),
            "Def→Agg",
            "Def→Def",
            features,
        )
        direct_cmp = _v336_compare_groups(
            data,
            data["Transition"].eq("Aggressive→Defensive"),
            data["Transition"].eq("Defensive→Aggressive"),
            "Agg→Def",
            "Def→Agg",
            features,
        )

        scoreboard = _v339_transition_scoreboard(data, features)

        progress.progress(58, text="Era stabilityを確認中…")
        era = _v339_era_stability(data, features)

        # Add compact era-direction summary to scoreboard.
        era_summary_rows = []
        if not era.empty:
            for f in features:
                row = {"Feature": f}
                for comp in ["Entry","Exit"]:
                    g = era[(era["Feature"].eq(f)) & (era["Comparison"].eq(comp))]
                    if g.empty:
                        row[f"{comp} era same direction"] = "0/0"
                        continue
                    # Full-sample direction from scoreboard.
                    s = scoreboard[scoreboard["Feature"].eq(f)]
                    if s.empty:
                        continue
                    col = "Entry direction" if comp == "Entry" else "Exit direction"
                    full_higher = "Higher" in str(s.iloc[0][col])
                    same = sum((g["Direction"].eq("Higher")) == full_higher)
                    row[f"{comp} era same direction"] = f"{same}/{len(g)}"
                era_summary_rows.append(row)
            scoreboard = scoreboard.merge(
                pd.DataFrame(era_summary_rows), on="Feature", how="left"
            )

        progress.progress(72, text="3か月lead-up pathを作成中…")
        # Keep lead-up focused on predeclared key features to stay lightweight.
        lead_features = [c for c in [
            "QQQ_Inflect_1m3m","QQQ_mom3","QQQ_mom6",
            "GLD_mom3","LQD_mom3","TLT_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m"
        ] if c in data.columns]
        leadup = _v339_leadup_table(data, lead_features)

        # Exact transition event rows.
        event_cols = [c for c in [
            "Month","PrevState","State","Transition","Position","TargetReturn",
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_Inflect_1m3m","QQQ_SMA200",
            "GLD_mom3","LQD_mom3","TLT_mom3","XLU_mom3",
            "VIX","Delta_VIX_1m",
            "RiskCorr20","Delta_RiskCorr20_1m",
            "CrossAssetAbsCorr20","Delta_CrossAssetAbsCorr20_1m",
        ] if c in data.columns]
        events = data[
            data["Transition"].isin(
                ["Aggressive→Defensive","Defensive→Aggressive"]
            )
        ][event_cols].copy()
        events["Month"] = events["Month"].astype(str)

        progress.progress(84, text="結果を表示中…")

        st.markdown("#### 1) Transition counts")
        st.dataframe(counts, hide_index=True, use_container_width=True)

        st.markdown("#### 2) Risk-Off Entry: Agg→Def vs Agg→Agg")
        st.dataframe(entry_cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 3) Risk-On Exit: Def→Agg vs Def→Def")
        st.dataframe(exit_cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 4) Direct transition asymmetry: Agg→Def vs Def→Agg")
        st.dataframe(direct_cmp.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 5) Hysteresis scoreboard")
        st.caption(
            "Entry/Exitの両方で識別力があり、かつ方向が反対なら、"
            "同じ特徴量の単純な逆符号よりヒステリシス候補として興味深いです。"
        )
        st.dataframe(scoreboard.head(35).round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 6) Era stability")
        st.dataframe(era.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 7) 3-month lead-up median path")
        st.dataframe(leadup.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 8) Exact Entry / Exit events")
        st.dataframe(events.round(4), hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_transition_counts.csv",
                counts.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_riskoff_entry_aggdef_vs_aggagg.csv",
                entry_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_riskon_exit_defagg_vs_defdef.csv",
                exit_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_direct_aggdef_vs_defagg.csv",
                direct_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_hysteresis_scoreboard.csv",
                scoreboard.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_leadup_median_path.csv",
                leadup.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_transition_events.csv",
                events.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.39 Risk-Off Entry vs Exit Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_riskoff_entry_exit_autopsy_v339.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v339",
        )
        st.caption(
            "ここではルール化しません。Entry/Exitの方向・Era安定性・lead-upが揃った場合だけ、"
            "次の固定Hysteresis Challengerへ進みます。"
        )


def render_v338_full_riskoff_challenger(px_close, rf_bt, start, end):
    st.markdown("### 🛡️ v3.38b — Full Risk-Off Challenger #1")
    st.caption(
        "Attack #1をControlとして固定し、GLD3M<0の時だけポートフォリオ全体をRisk-Offします。"
    )
    st.info(
        "固定ルール：前月末 GLD 3M < 0 → Full Risk-Off。"
        "その時 LQD 3M > 0 → 100% GLD、LQD 3M ≤ 0 → 100% XLU。"
    )
    st.warning(
        "自然な0境界のみ。閾値探索なし・3M/6M比較なし・配分最適化なし。"
        "開発期間は2026-07まで固定。"
    )

    if st.button("Full Risk-Off Challenger #1 を検証", type="primary", key="run_v338"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(10, text="Open価格を準備中…")
        opens = get_open(tuple(needed), start, end)
        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()

        progress.progress(22, text="Adaptive ALL / A+VIX30を再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake
        avix_h = _v326_apply_l2_gate(base_h, allow_l2)

        progress.progress(36, text="Turbo / Attack #1を再構築中…")
        inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        t1_h = _v332_apply_turbo_l3(avix_h, turbo_active)

        choose_tecl, attack_audit = _v335_attack_selector_signal(closes, idx)

        progress.progress(48, text="Open→Open Control returnを計算中…")
        asset_ret = opens.pct_change(fill_method=None)

        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        t2_ret, attack_ret = _v335_build_t2_and_attack_returns(
            avix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl,
        )

        progress.progress(58, text="GLD3M / LQD3M Risk-Off signalを計算中…")
        gld3_neg_eff, gld_audit = _v338_monthly_total_return_signal(
            closes, "GLD", 3, idx, "GLD 3M", "lt0"
        )
        lqd3_pos_eff, lqd_audit = _v338_monthly_total_return_signal(
            closes, "LQD", 3, idx, "LQD 3M", "gt0"
        )

        # Effective booleans already include the existing month-end -> next-open lag.
        riskoff = gld3_neg_eff.reindex(idx).fillna(False).astype(bool)
        riskoff_gld = (
            riskoff
            & lqd3_pos_eff.reindex(idx).fillna(False).astype(bool)
        )
        riskoff_xlu = riskoff & ~riskoff_gld

        # Hard sanity checks: v3.38b must actually activate and alter returns.
        if int(riskoff.sum()) == 0:
            raise RuntimeError(
                "v3.38b sanity check failed: Full Risk-Off never activated."
            )

        challenger_ret = attack_ret.copy()
        challenger_ret.loc[riskoff_gld] = asset_ret["GLD"].reindex(idx).loc[riskoff_gld]
        challenger_ret.loc[riskoff_xlu] = asset_ret["XLU"].reindex(idx).loc[riskoff_xlu]

        changed = (
            (challenger_ret - attack_ret).abs()
            .reindex(idx)
            .fillna(0.0)
            .gt(1e-12)
        )
        if int(changed.sum()) == 0:
            raise RuntimeError(
                "v3.38b sanity check failed: Risk-Off activated but returns never changed."
            )

        daily = pd.DataFrame({
            "Base Adaptive ALL": base_ret,
            "Attack #1 Control": attack_ret,
            "Full Risk-Off #1": challenger_ret,
        })
        daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
        variants = list(daily.columns)

        # Free large intermediates before CPCV.
        del core_h, base_h, avix_h, t1_h, opens

        progress.progress(68, text="Full metrics / Rolling P10を計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl_name = "Attack #1 Control"
        chal_name = "Full Risk-Off #1"
        ctrl = metrics.loc[ctrl_name]

        metrics["ΔCAGR vs Control"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs Control"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs Control"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["DD change vs Control"] = metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","ΔSortino vs Control",
            "ΔSharpe vs Control","DD change vs Control"
        ]
        show = metrics[show_cols].copy().astype(object)
        for c in [
            "CAGR","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs Control","DD change vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in [
            "Sortino0","Sharpe0","ΔSortino vs Control","ΔSharpe vs Control"
        ]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        r = riskoff.reindex(daily.index).fillna(False)
        rg = riskoff_gld.reindex(daily.index).fillna(False)
        rx = riskoff_xlu.reindex(daily.index).fillna(False)

        activity = pd.DataFrame({
            "Measure": [
                "Full Risk-Off days",
                "Risk-Off → GLD days",
                "Risk-Off → XLU days",
                "Risk-Off share of sample",
                "Days returns actually changed",
            ],
            "Value": [
                int(r.sum()),
                int(rg.sum()),
                int(rx.sum()),
                f"{r.mean()*100:.1f}%",
                int(changed.reindex(daily.index).fillna(False).sum()),
            ],
        })
        st.markdown("#### 2) Full Risk-Off activity")
        st.dataframe(activity, hide_index=True, use_container_width=True)

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(78, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        cpcv_vs_ctrl, _ = _v326_cpcv_summary(
            monthly, ctrl_name, [chal_name]
        )
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL", [ctrl_name, chal_name]
        )

        def compact_cpcv(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                rows.append({
                    "Variant": v,
                    "Sortino wins": f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}",
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Positive Active": f"{int(g['Positive Active'].sum())}/{len(g)}",
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                })
            return pd.DataFrame(rows)

        st.markdown("#### 4) CPCV — Full Risk-Off #1 vs Attack #1")
        st.dataframe(
            compact_cpcv(cpcv_vs_ctrl).round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 5) CPCV — Control / Challenger vs Base")
        st.dataframe(
            compact_cpcv(cpcv_vs_base).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(88, text="Stress / year robustnessを確認中…")
        stress_windows = [
            ("2011 Jul-Oct", "2011-07-26", "2011-10-04"),
            ("2015 Jul-Aug", "2015-07-21", "2015-08-24"),
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2023 Jul-Oct", "2023-07-19", "2023-10-27"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress:
                sshow[v] = stress[v].map(lambda x:f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        annual = (1.0 + daily).resample("YE").prod() - 1.0
        annual.index = annual.index.year
        annual.index.name = "Year"

        st.markdown("#### 7) Calendar-year returns")
        ashow = annual.copy().astype(object)
        for v in variants:
            ashow[v] = annual[v].map(lambda x:f"{x*100:+.2f}%")
        st.dataframe(ashow, use_container_width=True)

        # Monthly audit, compact.
        audit = gld_audit.merge(lqd_audit, on="Month", how="outer")
        eff = pd.DataFrame({
            "Risk-Off": riskoff,
            "Risk-Off GLD": riskoff_gld,
            "Risk-Off XLU": riskoff_xlu,
        }).resample("ME").last()
        eff["Month"] = eff.index.to_period("M").astype(str)
        audit = audit.merge(
            eff[["Month","Risk-Off","Risk-Off GLD","Risk-Off XLU"]],
            on="Month", how="left"
        )
        audit = audit[
            pd.PeriodIndex(audit["Month"], freq="M")
            <= pd.Period("2026-07","M")
        ]

        st.markdown("#### 8) Recent Full Risk-Off signal audit")
        st.dataframe(
            audit.tail(30).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_riskoff_vs_control.csv",
                cpcv_vs_ctrl.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_annual_returns.csv",
                annual.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "08_riskoff_signal_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.38b Full Risk-Off Challenger #1（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v338b_full_riskoff_challenger_1.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v338",
        )

        st.caption(
            "勝敗はCAGRだけでは決めません。Rolling P10、SortinoをSharpeより重く見つつ、"
            "Daily/Monthly DD、CPCV、stress windows、年次安定性を総合評価します。"
        )


def render_v337_defensive_asset_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🛟 v3.37 — Defensive Asset Autopsy: XLU vs GLD")
    st.caption(
        "目標戦略がDefensive時にXLUとGLDをどう使い分けていたかだけを診断します。"
    )
    st.info(
        "診断のみ。Full Risk-Offルールはまだ作りません。"
        "閾値探索・配分最適化なし。目標履歴は2026-07まで固定。"
    )

    if st.button("XLU vs GLD を解析", type="primary", key="run_v337"):
        progress = st.progress(0, text="目標戦略履歴を復元中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())

        progress.progress(18, text="前月末特徴量を計算中…")
        needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        feat = _v330_month_end_features(closes)

        # Add SMA200 distances for XLU/GLD if not already present.
        me = closes.resample("ME").last()
        for a in ["XLU","GLD","SPY"]:
            if a in closes.columns:
                sma200 = closes[a].rolling(200).mean().resample("ME").last()
                s = me[a] / sma200 - 1.0
                s.index = s.index.to_period("M")
                feat[f"{a}_vs_SMA200"] = s.reindex(feat.index)

        # Add fixed correlation diagnostics.
        ret = closes.pct_change(fill_method=None)
        risk_assets = [c for c in ["QQQ","SPY","XLU","LQD"] if c in ret.columns]
        cross_assets = [c for c in ["QQQ","LQD","TLT","GLD","XLU"] if c in ret.columns]

        def mean_pair_corr(frame, window, absolute=False):
            vals = []
            cols = list(frame.columns)
            for i in range(len(cols)):
                for j in range(i+1, len(cols)):
                    c = frame[cols[i]].rolling(window).corr(frame[cols[j]])
                    vals.append(c.abs() if absolute else c)
            if not vals:
                return pd.Series(index=frame.index, dtype=float)
            return pd.concat(vals, axis=1).mean(axis=1)

        rc20 = mean_pair_corr(ret[risk_assets], 20, False).resample("ME").last()
        rc60 = mean_pair_corr(ret[risk_assets], 60, False).resample("ME").last()
        ca20 = mean_pair_corr(ret[cross_assets], 20, True).resample("ME").last()

        for name, s in {
            "RiskCorr20": rc20,
            "RiskCorr60": rc60,
            "CrossAssetAbsCorr20": ca20,
        }.items():
            z = s.copy()
            z.index = z.index.to_period("M")
            feat[name] = z.reindex(feat.index)

        data = _v337_prepare_defensive_allocations(target, feat)
        d = data[data["State"].eq("Defensive")].copy()

        progress.progress(38, text="Defensive allocation statesを集計中…")
        summary = (
            d.groupby("DefensiveAllocation", dropna=False)
            .agg(
                Months=("Month","size"),
                AvgTargetReturn=("TargetReturn","mean"),
                MedianTargetReturn=("TargetReturn","median"),
                AvgXLUShare=("XLUShareDef","mean"),
                AvgGLDShare=("GLDShareDef","mean"),
            )
            .reset_index()
            .sort_values("Months", ascending=False)
        )

        st.markdown("#### 1) Defensive allocation states")
        ss = summary.copy()
        for c in ["AvgTargetReturn","MedianTargetReturn"]:
            ss[c] = ss[c].map(lambda x:f"{x*100:+.2f}%")
        for c in ["AvgXLUShare","AvgGLDShare"]:
            ss[c] = ss[c].map(lambda x:f"{x*100:.1f}%")
        st.dataframe(ss, hide_index=True, use_container_width=True)

        fixed_features = [c for c in [
            # Relative strength XLU vs GLD
            "XLU_minus_GLD_1m","XLU_minus_GLD_3m",
            "XLU_minus_GLD_6m","XLU_minus_GLD_12m",
            "XLU_minus_GLD_SMA200",
            "DefRelInflect_1m3m","DefRelInflect_3m12m",
            # Absolute defensive momentum
            "XLU_mom1","XLU_mom3","XLU_mom6","XLU_mom12",
            "GLD_mom1","GLD_mom3","GLD_mom6","GLD_mom12",
            "TLT_mom1","TLT_mom3","TLT_mom6","TLT_mom12",
            "LQD_mom1","LQD_mom3","LQD_mom6","LQD_mom12",
            # Relative to SPY
            "XLU_minus_SPY_1m","XLU_minus_SPY_3m",
            "XLU_minus_SPY_6m","XLU_minus_SPY_12m",
            "GLD_minus_SPY_1m","GLD_minus_SPY_3m",
            "GLD_minus_SPY_6m","GLD_minus_SPY_12m",
            # Equity/stress context
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_vs_SMA200","VIX",
            "RiskCorr20","RiskCorr60","CrossAssetAbsCorr20",
        ] if c in d.columns]

        pure_xlu = d["DefensiveAllocation"].eq("Pure XLU")
        pure_gld = d["DefensiveAllocation"].eq("Pure GLD")

        progress.progress(52, text="Pure XLU vs Pure GLDを比較中…")
        pure_cmp = _v336_compare_groups(
            d, pure_xlu, pure_gld, "Pure XLU", "Pure GLD", fixed_features
        )
        st.markdown("#### 2) Pure XLU vs Pure GLD — prior month-end")
        st.dataframe(pure_cmp.round(4), hide_index=True, use_container_width=True)

        xlu_heavy = d["XLUShareDef"] > 0.5
        gld_heavy = d["GLDShareDef"] > 0.5
        heavy_cmp = _v336_compare_groups(
            d, xlu_heavy, gld_heavy, "XLU-heavy", "GLD-heavy", fixed_features
        )
        st.markdown("#### 3) XLU-heavy vs GLD-heavy")
        st.dataframe(heavy_cmp.round(4), hide_index=True, use_container_width=True)

        progress.progress(64, text="Allocation shiftを解析中…")
        d = d.sort_values("Month").reset_index(drop=True)
        d["PrevXLUShare"] = d["XLUShareDef"].shift(1)
        d["ΔXLUShare"] = d["XLUShareDef"] - d["PrevXLUShare"]
        toward_xlu = d["ΔXLUShare"] > 0
        toward_gld = d["ΔXLUShare"] < 0

        shift_cmp = _v336_compare_groups(
            d, toward_xlu, toward_gld, "Toward XLU", "Toward GLD", fixed_features
        )
        st.markdown("#### 4) Allocation shifts — toward XLU vs toward GLD")
        st.dataframe(shift_cmp.round(4), hide_index=True, use_container_width=True)

        progress.progress(74, text="Era stabilityを確認中…")
        eras = [
            ("2013-17", pd.Period("2013-01","M"), pd.Period("2017-12","M")),
            ("2018-21", pd.Period("2018-01","M"), pd.Period("2021-12","M")),
            ("2022-26", pd.Period("2022-01","M"), pd.Period("2026-07","M")),
        ]
        era_rows = []
        for f in fixed_features:
            for era_name, lo, hi in eras:
                z = d[(d["Month"] >= lo) & (d["Month"] <= hi)]
                mx = z["DefensiveAllocation"].eq("Pure XLU")
                mg = z["DefensiveAllocation"].eq("Pure GLD")
                a = z.loc[mx, f].dropna()
                b = z.loc[mg, f].dropna()
                if len(a) < 2 or len(b) < 2:
                    continue
                auc = _v334_pairwise_auc(a, b)
                era_rows.append({
                    "Feature": f,
                    "Era": era_name,
                    "Pure XLU median": a.median(),
                    "Pure GLD median": b.median(),
                    "Median diff": a.median() - b.median(),
                    "AUC(XLU>GLD)": auc,
                    "N XLU": len(a),
                    "N GLD": len(b),
                })
        era = pd.DataFrame(era_rows)

        st.markdown("#### 5) Era stability — Pure XLU vs Pure GLD")
        if not era.empty:
            ep = era.pivot(index="Feature", columns="Era", values="Median diff")
            st.dataframe(ep.round(4), use_container_width=True)

        # Defensive entry months only.
        progress.progress(84, text="Defensive entry monthsを解析中…")
        entry = data["State"].eq("Defensive") & ~data["PrevState"].eq("Defensive")
        entry_d = data[entry].copy()

        entry_xlu = entry_d["XLUShareDef"] > 0.5
        entry_gld = entry_d["GLDShareDef"] > 0.5
        entry_cmp = _v336_compare_groups(
            entry_d, entry_xlu, entry_gld, "Entry XLU", "Entry GLD", fixed_features
        )

        st.markdown("#### 6) Defensive-entry months — XLU vs GLD")
        st.dataframe(entry_cmp.round(4), hide_index=True, use_container_width=True)

        # Scoreboard centered on pure comparison + era stability.
        score = pure_cmp[["Feature","Directional AUC","Direction","Effect"]].copy() \
            if not pure_cmp.empty else pd.DataFrame()

        if not score.empty and not era.empty:
            auc_col = "AUC(XLU>GLD)"
            full_auc_col = "AUC(Pure XLU>Pure GLD)"
            if full_auc_col in pure_cmp.columns:
                full_auc = pure_cmp.set_index("Feature")[full_auc_col]
            else:
                # Column name generated by helper:
                full_auc = pure_cmp.set_index("Feature")[
                    [c for c in pure_cmp.columns if c.startswith("AUC(")][0]
                ]
            stable = []
            for f, g in era.groupby("Feature"):
                if f not in full_auc:
                    continue
                sign_full = 1 if full_auc.loc[f] >= .5 else -1
                vals = g[auc_col].dropna()
                signs = [(1 if a >= .5 else -1) for a in vals]
                stable.append({
                    "Feature": f,
                    "Era same direction": f"{sum(s == sign_full for s in signs)}/{len(signs)}",
                    "Era median dAUC": np.median([max(a,1-a) for a in vals])
                        if len(vals) else np.nan,
                })
            score = score.merge(pd.DataFrame(stable), on="Feature", how="left")

        st.markdown("#### 7) Diagnostic scoreboard")
        st.dataframe(score.head(30).round(4), hide_index=True, use_container_width=True)

        recent_cols = [c for c in [
            "Month","Position","TargetReturn","PrevState","State",
            "DefensiveAllocation","XLU","GLD","XLUShareDef","GLDShareDef",
            "XLU_minus_GLD_1m","XLU_minus_GLD_3m",
            "XLU_minus_GLD_6m","XLU_minus_GLD_12m",
            "XLU_mom3","GLD_mom3","TLT_mom3","LQD_mom3",
            "QQQ_mom3","VIX"
        ] if c in d.columns]
        recent = d[recent_cols].tail(30).copy()
        recent["Month"] = recent["Month"].astype(str)

        st.markdown("#### 8) Recent Defensive months")
        st.dataframe(recent.round(4), hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_defensive_state_summary.csv",
                summary.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_pure_xlu_vs_gld.csv",
                pure_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_xluheavy_vs_gldheavy.csv",
                heavy_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_allocation_shifts.csv",
                shift_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_defensive_entries.csv",
                entry_cmp.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_scoreboard.csv",
                score.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_defensive_months_labeled.csv",
                d.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.37 Defensive Asset Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_defensive_asset_autopsy_v337.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v337",
        )
        st.caption(
            "ここではXLU/GLD選択ルールを作りません。"
            "Pure比較・Entry比較・Era安定性が揃った特徴だけを次のChallenger候補に残します。"
        )


def render_v336_full_riskoff_transition_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🛡️ v3.36b — Full Risk-Off Transition Autopsy")
    st.caption(
        "目標戦略のAggressive→Defensive切替を、前月末に観測可能だった情報だけで再解析します。"
    )
    st.info(
        "診断のみ。Full Risk-Off売買ルールはまだ作りません。"
        "閾値探索・特徴量最適化なし。目標履歴は2026-07まで固定。"
    )

    if st.button("Full Risk-Off transitionを解析", type="primary", key="run_v336"):
        progress = st.progress(0, text="目標戦略履歴を復元中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())

        progress.progress(18, text="前月末特徴量を計算中…")
        needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        feat = _v330_month_end_features(closes)

        # Add fixed 20/60d correlation diagnostics, aligned to month-end.
        ret = closes.pct_change(fill_method=None)
        risk_assets = [c for c in ["QQQ","SPY","XLU","LQD"] if c in ret.columns]
        cross_assets = [c for c in ["QQQ","LQD","TLT","GLD","XLU"] if c in ret.columns]

        def mean_pair_corr(frame, window, absolute=False):
            vals = []
            cols = list(frame.columns)
            for i in range(len(cols)):
                for j in range(i+1, len(cols)):
                    c = frame[cols[i]].rolling(window).corr(frame[cols[j]])
                    vals.append(c.abs() if absolute else c)
            if not vals:
                return pd.Series(index=frame.index, dtype=float)
            return pd.concat(vals, axis=1).mean(axis=1)

        rc20 = mean_pair_corr(ret[risk_assets], 20, False).resample("ME").last()
        rc60 = mean_pair_corr(ret[risk_assets], 60, False).resample("ME").last()
        ca20 = mean_pair_corr(ret[cross_assets], 20, True).resample("ME").last()

        # Feature table index is PeriodIndex in the prior autopsy helpers.
        def add_monthly_series(name, s):
            z = s.copy()
            z.index = z.index.to_period("M")
            feat[name] = z.reindex(feat.index)

        add_monthly_series("RiskCorr20", rc20)
        add_monthly_series("RiskCorr60", rc60)
        add_monthly_series("CrossAssetAbsCorr20", ca20)

        data = _v336_transition_autopsy(target, feat)

        progress.progress(38, text="Transition eventsを分類中…")
        ad = data["PrevState"].eq("Aggressive") & data["State"].eq("Defensive")
        aa = data["PrevState"].eq("Aggressive") & data["State"].eq("Aggressive")
        da = data["PrevState"].eq("Defensive") & data["State"].eq("Aggressive")
        dd = data["PrevState"].eq("Defensive") & data["State"].eq("Defensive")

        counts = pd.DataFrame({
            "Transition": [
                "Aggressive → Defensive",
                "Aggressive → Aggressive",
                "Defensive → Aggressive",
                "Defensive → Defensive",
            ],
            "Months": [int(ad.sum()), int(aa.sum()), int(da.sum()), int(dd.sum())]
        })
        st.markdown("#### 1) Transition counts")
        st.dataframe(counts, hide_index=True, use_container_width=True)

        fixed_features = [c for c in [
            # Equity trend / momentum
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "QQQ_vs_SMA100","QQQ_vs_SMA200",
            "XLK_vs_SMA100","XLK_vs_SMA200",
            # Inflection / deterioration
            "QQQ_1m_minus_3m","QQQ_1m_minus_6m","QQQ_3m_minus_6m","QQQ_3m_minus_12m",
            "XLK_1m_minus_3m","XLK_1m_minus_6m","XLK_3m_minus_6m","XLK_3m_minus_12m",
            # Tech relative strength
            "XLK_minus_QQQ_1m","XLK_minus_QQQ_3m","XLK_minus_QQQ_6m","XLK_minus_QQQ_12m",
            "XLK_minus_QQQ_SMA200",
            # Defensive assets
            "TLT_mom1","TLT_mom3","TLT_mom6","TLT_mom12",
            "LQD_mom1","LQD_mom3","LQD_mom6","LQD_mom12",
            "GLD_mom1","GLD_mom3","GLD_mom6","GLD_mom12",
            "XLU_mom1","XLU_mom3","XLU_mom6","XLU_mom12",
            # Stress
            "VIX","RiskCorr20","RiskCorr60","CrossAssetAbsCorr20",
            # One-month changes in fixed features
            "d1_QQQ_mom1","d1_QQQ_mom3","d1_QQQ_mom6",
            "d1_XLK_mom1","d1_XLK_mom3","d1_XLK_mom6",
            "d1_QQQ_vs_SMA200","d1_XLK_vs_SMA200",
            "d1_TLT_mom3","d1_LQD_mom3","d1_GLD_mom3","d1_XLU_mom3",
            "d1_VIX","d1_RiskCorr20","d1_RiskCorr60","d1_CrossAssetAbsCorr20",
        ] if c in data.columns]

        progress.progress(52, text="Agg→Def vs Agg continuationを比較中…")
        ad_vs_aa = _v336_compare_groups(
            data, ad, aa, "Agg→Def", "Agg→Agg", fixed_features
        )

        st.markdown("#### 2) Aggressive → Defensive vs Aggressive continuation")
        st.dataframe(ad_vs_aa.round(4), hide_index=True, use_container_width=True)

        progress.progress(64, text="Agg→Def vs recovery entryを比較中…")
        ad_vs_da = _v336_compare_groups(
            data, ad, da, "Agg→Def", "Def→Agg", fixed_features
        )
        st.markdown("#### 3) Aggressive → Defensive vs Defensive → Aggressive")
        st.dataframe(ad_vs_da.round(4), hide_index=True, use_container_width=True)

        # Era stability of the primary comparison.
        progress.progress(74, text="Era stabilityを確認中…")
        eras = [
            ("2013-17", pd.Period("2013-01","M"), pd.Period("2017-12","M")),
            ("2018-21", pd.Period("2018-01","M"), pd.Period("2021-12","M")),
            ("2022-26", pd.Period("2022-01","M"), pd.Period("2026-07","M")),
        ]
        era_rows = []
        for f in fixed_features:
            for era_name, lo, hi in eras:
                z = data[(data["Month"] >= lo) & (data["Month"] <= hi)]
                ma = z["PrevState"].eq("Aggressive") & z["State"].eq("Defensive")
                mb = z["PrevState"].eq("Aggressive") & z["State"].eq("Aggressive")
                a = z.loc[ma, f].dropna()
                b = z.loc[mb, f].dropna()
                if len(a) < 2 or len(b) < 2:
                    continue
                auc = _v334_pairwise_auc(a, b)
                era_rows.append({
                    "Feature": f,
                    "Era": era_name,
                    "Agg→Def median": a.median(),
                    "Agg→Agg median": b.median(),
                    "Median diff": a.median() - b.median(),
                    "AUC(Agg→Def>Agg→Agg)": auc,
                    "N Agg→Def": len(a),
                    "N Agg→Agg": len(b),
                })
        era = pd.DataFrame(era_rows)

        st.markdown("#### 4) Era stability — Agg→Def vs Agg→Agg")
        if not era.empty:
            ep = era.pivot(index="Feature", columns="Era", values="Median diff")
            st.dataframe(ep.round(4), use_container_width=True)

        # Scoreboard: full comparison + era direction consistency.
        score = ad_vs_aa[[
            "Feature","Directional AUC","Direction","Effect"
        ]].copy() if not ad_vs_aa.empty else pd.DataFrame()

        if not score.empty and not era.empty:
            full_auc_col = "AUC(Agg→Def>Agg→Agg)"
            full_auc = ad_vs_aa.set_index("Feature")[full_auc_col]
            stable = []
            for f, g in era.groupby("Feature"):
                if f not in full_auc:
                    continue
                sign_full = 1 if full_auc.loc[f] >= .5 else -1
                signs = [(1 if a >= .5 else -1) for a in g[full_auc_col].dropna()]
                same = sum(s == sign_full for s in signs)
                stable.append({
                    "Feature": f,
                    "Era same direction": f"{same}/{len(signs)}",
                    "Era median dAUC": np.median([max(a,1-a) for a in g[full_auc_col].dropna()])
                        if len(g[full_auc_col].dropna()) else np.nan,
                })
            score = score.merge(pd.DataFrame(stable), on="Feature", how="left")

        st.markdown("#### 5) Diagnostic scoreboard")
        st.dataframe(score.head(30).round(4), hide_index=True, use_container_width=True)

        # Exact transition event audit.
        event_cols = [c for c in [
            "Month","Position","TargetReturn","PrevState","State","Transition",
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "QQQ_vs_SMA200","XLK_vs_SMA200",
            "QQQ_1m_minus_3m","XLK_1m_minus_3m",
            "XLK_minus_QQQ_6m",
            "TLT_mom3","LQD_mom3","GLD_mom3","XLU_mom3",
            "VIX","RiskCorr20","RiskCorr60","CrossAssetAbsCorr20",
            "d1_QQQ_mom3","d1_QQQ_vs_SMA200","d1_VIX","d1_RiskCorr20",
        ] if c in data.columns]

        events = data.loc[ad | da, event_cols].copy()
        st.markdown("#### 6) Exact risk-off / recovery transition events")
        eshow = events.copy()
        eshow["Month"] = eshow["Month"].astype(str)
        st.dataframe(eshow.round(4), hide_index=True, use_container_width=True)

        progress.progress(88, text="Lead-up pathを作成中…")
        # 3-month lead-up around each Agg->Def event, diagnostic only.
        lead_rows = []
        for i in data.index[ad]:
            for lag in [3,2,1,0]:
                j = i - lag
                if j < 0:
                    continue
                r = data.loc[j]
                lead_rows.append({
                    "RiskOffMonth": str(data.loc[i,"Month"]),
                    "Lead": f"-{lag}m" if lag else "0m",
                    "ObservedMonth": str(r["Month"]),
                    **{f: r.get(f, np.nan) for f in fixed_features}
                })
        lead = pd.DataFrame(lead_rows)

        st.markdown("#### 7) Median lead-up path before Agg→Def")
        if not lead.empty:
            lead_med = (
                lead.groupby("Lead")[fixed_features]
                .median(numeric_only=True)
                .reindex(["-3m","-2m","-1m","0m"])
            )
            # Show a compact, fixed subset on mobile.
            compact_cols = [c for c in [
                "QQQ_mom3","QQQ_mom6","QQQ_vs_SMA200",
                "QQQ_1m_minus_3m","XLK_minus_QQQ_6m",
                "TLT_mom3","LQD_mom3","GLD_mom3","XLU_mom3",
                "VIX","RiskCorr20","RiskCorr60"
            ] if c in lead_med.columns]
            st.dataframe(lead_med[compact_cols].round(4), use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr(
                "01_transition_counts.csv",
                counts.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "02_aggdef_vs_aggagg.csv",
                ad_vs_aa.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "03_aggdef_vs_defagg.csv",
                ad_vs_da.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_era_stability.csv",
                era.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_scoreboard.csv",
                score.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_transition_events.csv",
                events.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_riskoff_leadup.csv",
                lead.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 8) 保存")
        st.download_button(
            "📦 v3.36 Full Risk-Off Transition Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_full_riskoff_transition_autopsy_v336b.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v336",
        )
        st.caption(
            "ここではFull Risk-Offルールを作りません。"
            "Agg→DefをAgg continuationと分ける特徴がEraを跨いで残るかだけを判定します。"
        )


def render_v335_attack_asset_challenger(px_close, rf_bt, start, end):
    st.markdown("### ⚔️ v3.35 — Attack Asset Challenger #1")
    st.caption(
        "T2の75%火力とTurboシグナルは完全固定。攻撃先だけTQQQ/TECLで切り替えます。"
    )
    st.info(
        "固定ルール：前月末 XLK 6M > QQQ 6M ならTurbo攻撃枠75%をTECL、"
        "それ以外はTQQQ。自然な0境界のみ。"
    )
    st.warning(
        "閾値探索なし・75%配分は変更なし・Turbo条件も変更なし。"
        "開発期間は2026-07まで固定。"
    )

    if st.button("Attack Asset Challenger #1 を検証", type="primary", key="run_v335"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(12, text="Open価格を準備中…")
        opens = get_open(tuple(needed), start, end)

        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()

        progress.progress(26, text="Adaptive ALLを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        progress.progress(40, text="A Accelerator / VIX30 Brakeを計算中…")
        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        control_h = _v326_apply_l2_gate(base_h, allow_l2)

        progress.progress(52, text="Turbo / Attack selectorを計算中…")
        inflect_eff, inflect_audit = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        t1_h = _v332_apply_turbo_l3(control_h, turbo_active)

        choose_tecl, attack_audit = _v335_attack_selector_signal(closes, idx)

        progress.progress(64, text="Open→Openリターンを計算中…")
        asset_ret = opens.pct_change(fill_method=None)

        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        a_vix_ret = _portfolio_return_from_holdings_fast(control_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

        t2_ret, attack_ret = _v335_build_t2_and_attack_returns(
            a_vix_ret,
            t1_ret,
            asset_ret["TQQQ"],
            asset_ret["TECL"],
            turbo_active,
            choose_tecl
        )

        daily = pd.DataFrame({
            "Base Adaptive ALL": base_ret,
            "A+VIX30": a_vix_ret,
            "T2 75% TQQQ Control": t2_ret,
            "Attack #1 75% TQQQ/TECL": attack_ret,
        })
        daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
        variants = list(daily.columns)

        del core_h, base_h, control_h, t1_h, asset_ret, opens

        progress.progress(74, text="Full metrics / Rolling P10を計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl_name = "T2 75% TQQQ Control"
        chal_name = "Attack #1 75% TQQQ/TECL"
        ctrl = metrics.loc[ctrl_name]

        metrics["ΔCAGR vs T2"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs T2"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs T2"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["DD change vs T2"] = metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs T2","ΔSortino vs T2","ΔSharpe vs T2","DD change vs T2"
        ]
        show = metrics[show_cols].copy().astype(object)
        for c in ["CAGR","Daily MaxDD","Monthly MaxDD","ΔCAGR vs T2","DD change vs T2"]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in ["Sortino0","Sharpe0","ΔSortino vs T2","ΔSharpe vs T2"]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        turbo = turbo_active.reindex(daily.index).fillna(False)
        tecl_sel = choose_tecl.reindex(daily.index).fillna(False)
        use_tecl = turbo & tecl_sel
        use_tqqq = turbo & ~tecl_sel

        st.markdown("#### 2) Attack selector activity")
        activity = pd.DataFrame({
            "Measure": [
                "Turbo active days",
                "TECL attack days",
                "TQQQ attack days",
                "TECL share of Turbo days",
            ],
            "Value": [
                int(turbo.sum()),
                int(use_tecl.sum()),
                int(use_tqqq.sum()),
                f"{(use_tecl.sum()/turbo.sum()*100 if turbo.sum() else np.nan):.1f}%",
            ]
        })
        st.dataframe(activity, hide_index=True, use_container_width=True)

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(84, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        cpcv_vs_t2, _ = _v326_cpcv_summary(
            monthly, ctrl_name, [chal_name]
        )
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL", [ctrl_name, chal_name]
        )

        def compact_cpcv(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                rows.append({
                    "Variant": v,
                    "Sortino wins": f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}",
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Positive Active": f"{int(g['Positive Active'].sum())}/{len(g)}",
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                })
            return pd.DataFrame(rows)

        st.markdown("#### 4) CPCV — Attack #1 vs T2")
        st.dataframe(
            compact_cpcv(cpcv_vs_t2).round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 5) CPCV — T2 / Attack #1 vs Base")
        st.dataframe(
            compact_cpcv(cpcv_vs_base).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(92, text="ストレス期間を確認中…")
        stress_windows = [
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress:
                sshow[v] = stress[v].map(lambda x:f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        # Monthly attack audit.
        tmp = pd.DataFrame({
            "Turbo active": turbo_active,
            "Choose TECL": choose_tecl,
            "VIX30 brake": vix_brake,
            "L2 allowed": allow_l2,
        }).resample("ME").last()
        tmp["Month"] = tmp.index.to_period("M").astype(str)

        audit = attack_audit.merge(
            tmp[["Month","Turbo active","Choose TECL","VIX30 brake","L2 allowed"]],
            on="Month", how="left",
            suffixes=("", "_effective")
        )
        audit = audit[
            pd.PeriodIndex(audit["Month"], freq="M")
            <= pd.Period("2026-07","M")
        ]

        st.markdown("#### 7) Recent attack selector audit")
        st.dataframe(
            audit.tail(24).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(
            buf, "w", compression=_zipfile.ZIP_DEFLATED
        ) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_attack_vs_t2.csv",
                cpcv_vs_t2.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_attack_selector_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 8) 保存")
        st.download_button(
            "📦 v3.35 Attack Asset Challenger #1（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v335_attack_asset_challenger_1.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v335",
        )

        st.caption(
            "勝敗はCAGRだけでなく、Rolling P10、SortinoをSharpeより重く見つつ、"
            "Daily/Monthly DD、CPCV、stress windowを総合評価します。"
        )


def render_v334_tqqq_tecl_allocation_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🧭 v3.34 — Target TQQQ vs TECL Allocation Autopsy")
    st.caption(
        "T2の火力は固定したまま、目標戦略がTQQQとTECLをどう使い分けていたかだけを診断します。"
    )
    st.info(
        "前月末情報のみ。閾値探索なし・配分最適化なし・売買ルールなし。"
        "目標履歴は2026-07まで固定。"
    )

    if st.button("TQQQ vs TECL 配分を解析", type="primary", key="run_v334"):
        progress = st.progress(0, text="目標戦略履歴を復元中…")

        target = _v330_normalize_target_table(_v330_find_target_monthly_table())

        progress.progress(20, text="QQQ / XLK 前月末特徴量を計算中…")
        needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        feat = _v330_month_end_features(closes)
        data = _v334_target_alloc_features(target, feat)

        progress.progress(40, text="配分状態を集計中…")
        state_summary = (
            data.groupby("AttackAllocation", dropna=False)
            .agg(
                Months=("Month","size"),
                AvgTargetReturn=("TargetReturn","mean"),
                MedianTargetReturn=("TargetReturn","median"),
                AvgTQQQShare=("TQQQShareAgg","mean"),
                AvgTECLShare=("TECLShareAgg","mean"),
            )
            .reset_index()
            .sort_values("Months", ascending=False)
        )

        st.markdown("#### 1) Target aggressive allocation states")
        ss = state_summary.copy()
        for c in ["AvgTargetReturn","MedianTargetReturn"]:
            ss[c] = ss[c].map(lambda x:f"{x*100:+.2f}%")
        for c in ["AvgTQQQShare","AvgTECLShare"]:
            ss[c] = ss[c].map(lambda x:f"{x*100:.1f}%")
        st.dataframe(ss, hide_index=True, use_container_width=True)

        # Continuous target: TECL-heavy (>50%) vs TQQQ-heavy (>50%).
        tecl_heavy = data["TECLShareAgg"] > 0.5
        tqqq_heavy = data["TQQQShareAgg"] > 0.5

        fixed_features = [c for c in [
            "XLK_minus_QQQ_1m",
            "XLK_minus_QQQ_3m",
            "XLK_minus_QQQ_6m",
            "XLK_minus_QQQ_12m",
            "XLK_minus_QQQ_SMA200",
            "RelInflect_1m3m",
            "RelInflect_3m12m",
            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
            "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
            "QQQ_vs_SMA200","XLK_vs_SMA200",
            "VIX",
        ] if c in data.columns]

        rows = []
        for f in fixed_features:
            te = data.loc[tecl_heavy, f].dropna()
            tq = data.loc[tqqq_heavy, f].dropna()
            if len(te) < 3 or len(tq) < 3:
                continue
            auc = _v334_pairwise_auc(te, tq)
            pooled = np.sqrt((te.var(ddof=1) + tq.var(ddof=1))/2)
            effect = (te.mean()-tq.mean())/pooled if pooled and pd.notna(pooled) else np.nan
            rows.append({
                "Feature": f,
                "TECL-heavy median": te.median(),
                "TQQQ-heavy median": tq.median(),
                "AUC(TECL>TQQQ)": auc,
                "Directional AUC": max(auc, 1-auc),
                "Direction": "TECL+" if auc >= .5 else "TQQQ+",
                "Effect": effect,
                "N TECL-heavy": len(te),
                "N TQQQ-heavy": len(tq),
            })
        compare = pd.DataFrame(rows)
        if not compare.empty:
            compare = compare.sort_values(
                ["Directional AUC","Effect"], ascending=[False,False]
            )

        st.markdown("#### 2) TECL-heavy vs TQQQ-heavy — prior month-end")
        st.dataframe(compare.round(4), hide_index=True, use_container_width=True)

        progress.progress(58, text="Era stabilityを確認中…")
        eras = [
            ("2013-17", pd.Period("2013-01","M"), pd.Period("2017-12","M")),
            ("2018-21", pd.Period("2018-01","M"), pd.Period("2021-12","M")),
            ("2022-26", pd.Period("2022-01","M"), pd.Period("2026-07","M")),
        ]
        era_rows = []
        for f in fixed_features:
            for era, lo, hi in eras:
                z = data[(data["Month"]>=lo)&(data["Month"]<=hi)]
                te = z.loc[z["TECLShareAgg"] > .5, f].dropna()
                tq = z.loc[z["TQQQShareAgg"] > .5, f].dropna()
                if len(te) < 2 or len(tq) < 2:
                    continue
                auc = _v334_pairwise_auc(te, tq)
                era_rows.append({
                    "Feature": f,
                    "Era": era,
                    "TECL-heavy median": te.median(),
                    "TQQQ-heavy median": tq.median(),
                    "Median diff": te.median()-tq.median(),
                    "AUC(TECL>TQQQ)": auc,
                    "N TECL-heavy": len(te),
                    "N TQQQ-heavy": len(tq),
                })
        era = pd.DataFrame(era_rows)

        st.markdown("#### 3) Era stability — median difference")
        if not era.empty:
            ep = era.pivot(index="Feature", columns="Era", values="Median diff")
            st.dataframe(ep.round(4), use_container_width=True)

        # Pure allocations only: cleaner, smaller subset.
        pure = data[data["AttackAllocation"].isin(["Pure TQQQ","Pure TECL"])].copy()
        pure_rows = []
        for f in fixed_features:
            te = pure.loc[pure["AttackAllocation"].eq("Pure TECL"), f].dropna()
            tq = pure.loc[pure["AttackAllocation"].eq("Pure TQQQ"), f].dropna()
            if len(te) < 3 or len(tq) < 3:
                continue
            auc = _v334_pairwise_auc(te, tq)
            pure_rows.append({
                "Feature": f,
                "Pure TECL median": te.median(),
                "Pure TQQQ median": tq.median(),
                "AUC(TECL>TQQQ)": auc,
                "Directional AUC": max(auc,1-auc),
                "Direction": "TECL+" if auc >= .5 else "TQQQ+",
                "N TECL": len(te),
                "N TQQQ": len(tq),
            })
        pure_compare = pd.DataFrame(pure_rows)
        if not pure_compare.empty:
            pure_compare = pure_compare.sort_values("Directional AUC", ascending=False)

        st.markdown("#### 4) Pure TECL vs Pure TQQQ")
        st.dataframe(pure_compare.round(4), hide_index=True, use_container_width=True)

        progress.progress(72, text="配分変更イベントを解析中…")
        data = data.sort_values("Month").reset_index(drop=True)
        data["PrevTQQQShare"] = data["TQQQShareAgg"].shift(1)
        data["PrevTECLShare"] = data["TECLShareAgg"].shift(1)
        data["ΔTECLShare"] = data["TECLShareAgg"] - data["PrevTECLShare"]
        data["ShiftTowardTECL"] = data["ΔTECLShare"] > 0
        data["ShiftTowardTQQQ"] = data["ΔTECLShare"] < 0

        shift_rows = []
        for f in fixed_features:
            te = data.loc[data["ShiftTowardTECL"], f].dropna()
            tq = data.loc[data["ShiftTowardTQQQ"], f].dropna()
            if len(te) < 3 or len(tq) < 3:
                continue
            auc = _v334_pairwise_auc(te, tq)
            shift_rows.append({
                "Feature": f,
                "Toward TECL median": te.median(),
                "Toward TQQQ median": tq.median(),
                "AUC(TECLshift>TQQQshift)": auc,
                "Directional AUC": max(auc,1-auc),
                "Direction": "TECL+" if auc >= .5 else "TQQQ+",
                "N toward TECL": len(te),
                "N toward TQQQ": len(tq),
            })
        shifts = pd.DataFrame(shift_rows)
        if not shifts.empty:
            shifts = shifts.sort_values("Directional AUC", ascending=False)

        st.markdown("#### 5) Allocation shifts — toward TECL vs toward TQQQ")
        st.dataframe(shifts.round(4), hide_index=True, use_container_width=True)

        # Fixed descriptive scoreboard. No selection rule is generated.
        progress.progress(84, text="Diagnostic scoreboardを作成中…")
        score = pd.DataFrame({"Feature": fixed_features})
        if not compare.empty:
            score = score.merge(
                compare[["Feature","Directional AUC","Direction"]].rename(
                    columns={
                        "Directional AUC":"Heavy dAUC",
                        "Direction":"Heavy dir"
                    }
                ), on="Feature", how="left"
            )
        if not pure_compare.empty:
            score = score.merge(
                pure_compare[["Feature","Directional AUC","Direction"]].rename(
                    columns={
                        "Directional AUC":"Pure dAUC",
                        "Direction":"Pure dir"
                    }
                ), on="Feature", how="left"
            )
        if not shifts.empty:
            score = score.merge(
                shifts[["Feature","Directional AUC","Direction"]].rename(
                    columns={
                        "Directional AUC":"Shift dAUC",
                        "Direction":"Shift dir"
                    }
                ), on="Feature", how="left"
            )

        # Era directional stability relative to full-sample direction.
        if not era.empty and not compare.empty:
            full_dir = compare.set_index("Feature")["AUC(TECL>TQQQ)"]
            stable_rows = []
            for f, g in era.groupby("Feature"):
                if f not in full_dir:
                    continue
                sign_full = 1 if full_dir.loc[f] >= .5 else -1
                same = sum(
                    (1 if a >= .5 else -1) == sign_full
                    for a in g["AUC(TECL>TQQQ)"].dropna()
                )
                stable_rows.append({
                    "Feature": f,
                    "Era same direction": f"{same}/{len(g)}"
                })
            score = score.merge(pd.DataFrame(stable_rows), on="Feature", how="left")

        st.markdown("#### 6) Diagnostic scoreboard")
        st.dataframe(score.round(4), hide_index=True, use_container_width=True)

        st.markdown("#### 7) Recent target aggressive allocations")
        recent_cols = [
            "Month","Position","TargetReturn","TQQQ","TECL",
            "AttackAllocation","TQQQShareAgg","TECLShareAgg",
            "XLK_minus_QQQ_1m","XLK_minus_QQQ_3m",
            "XLK_minus_QQQ_6m","XLK_minus_QQQ_12m",
            "RelInflect_1m3m","RelInflect_3m12m"
        ]
        recent = data[[c for c in recent_cols if c in data.columns]].tail(30).copy()
        recent["Month"] = recent["Month"].astype(str)
        st.dataframe(recent.round(4), hide_index=True, use_container_width=True)

        progress.progress(100, text="完了")
        progress.empty()

        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
            z.writestr("01_aggressive_months_labeled.csv",
                       data.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("02_allocation_state_summary.csv",
                       state_summary.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("03_tecl_vs_tqqq_heavy.csv",
                       compare.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("04_era_stability.csv",
                       era.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("05_pure_tecl_vs_tqqq.csv",
                       pure_compare.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("06_allocation_shifts.csv",
                       shifts.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("07_scoreboard.csv",
                       score.to_csv(index=False).encode("utf-8-sig"))

        st.markdown("#### 8) 保存")
        st.download_button(
            "📦 TQQQ vs TECL Allocation Autopsy（ZIP）",
            data=buf.getvalue(),
            file_name="target_tqqq_tecl_allocation_autopsy_v334.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v334",
        )

        st.caption(
            "ここではTQQQ/TECL選択ルールを作りません。全期間だけでなくEra安定性と"
            "配分変更イベントでも同方向の特徴だけを次段階候補に残します。"
        )


def render_v333_turbo_intensity_ladder(px_close, rf_bt, start, end):
    st.markdown("### 🔥 v3.33 — Turbo Intensity Ladder")
    st.caption(
        "Turboシグナルはv3.32から一切変更せず、発動時の集中度だけを固定4段階で比較します。"
    )
    st.info(
        "T0=Control / T1=現在のTurbo / T2=75% TQQQ / T3=100% TQQQ。"
        "Turbo非発動時は全てA+VIX30 Controlです。"
    )
    st.warning(
        "これは閾値最適化ではなく、同一シグナルにどこまで資本を載せられるかの"
        "risk-budget / concentration testです。開発期間は2026-07まで固定。"
    )

    if st.button("Turbo Intensity Ladder を検証", type="primary", key="run_v333"):
        progress = st.progress(0, text="価格系列を準備中…")

        needed = [
            "QQQ","QLD","TQQQ","LQD","GLD","TLT",
            "SPXL","TECL","XLU","^VIX","SPY","XLK"
        ]

        closes = px_close.reindex(
            columns=[c for c in needed if c in px_close.columns]
        ).copy()
        missing = [x for x in needed if x not in closes.columns]
        if missing:
            extra = get_close(tuple(missing), start, end)
            closes = closes.join(extra, how="outer").sort_index().ffill()

        progress.progress(12, text="Open価格を準備中…")
        opens = get_open(tuple(needed), start, end)

        idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
        closes = closes.reindex(idx).ffill()
        opens = opens.reindex(idx).ffill()

        progress.progress(25, text="Adaptive ALLを再構築中…")
        core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

        safe_input = closes.copy()
        if "XLU" not in safe_input.columns:
            safe_input["XLU"] = safe_input["GLD"]
        safe2, _, _ = _safe_haven_multi_selector(safe_input)
        safe2 = safe2.reindex(idx).ffill()

        base_h = core_h.copy()
        for model in MODEL_WEIGHTS:
            mask = base_h[model].eq("GLD")
            base_h.loc[mask, model] = safe2.loc[mask]

        progress.progress(40, text="A Accelerator / VIX30 Brake を計算中…")
        gates, _ = _v326_bond_regime_signals(closes, idx)
        gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

        brakes, _ = _v329_brake_signals(closes, idx)
        vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
        allow_l2 = gate_a & ~vix_brake

        control_h = _v326_apply_l2_gate(base_h, allow_l2)

        progress.progress(52, text="XLK Inflection Turboを計算中…")
        inflect_eff, inflect_audit = _v332_xlk_inflection_signal(closes, idx)
        turbo_active = allow_l2 & inflect_eff.reindex(idx).fillna(False).astype(bool)
        t1_h = _v332_apply_turbo_l3(control_h, turbo_active)

        progress.progress(63, text="Open→Openリターンを計算中…")
        asset_ret = opens.pct_change(fill_method=None)

        base_ret = _portfolio_return_from_holdings_fast(base_h, asset_ret)
        control_ret = _portfolio_return_from_holdings_fast(control_h, asset_ret)
        t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)
        tqqq_ret = asset_ret["TQQQ"]

        ladder = _v333_intensity_returns(
            control_ret, t1_ret, tqqq_ret, turbo_active
        )

        daily = pd.concat(
            [base_ret.rename("Base Adaptive ALL"), ladder], axis=1
        )
        daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
        variants = list(daily.columns)

        # Release large objects before robustness work.
        del core_h, base_h, control_h, t1_h, asset_ret, opens

        progress.progress(74, text="Full metrics / Rolling P10を計算中…")
        metrics = pd.DataFrame(
            [_v325_metric_row(v, daily[v]) for v in variants]
        ).set_index("Variant")

        ctrl_name = "T0 A+VIX30 Control"
        ctrl = metrics.loc[ctrl_name]
        metrics["ΔCAGR vs T0"] = metrics["CAGR"] - ctrl["CAGR"]
        metrics["ΔSortino vs T0"] = metrics["Sortino0"] - ctrl["Sortino0"]
        metrics["ΔSharpe vs T0"] = metrics["Sharpe0"] - ctrl["Sharpe0"]
        metrics["DD change vs T0"] = metrics["Daily MaxDD"] - ctrl["Daily MaxDD"]

        st.markdown("#### 1) Full-sample metrics")
        show_cols = [
            "CAGR","Sortino0","Sharpe0","Daily MaxDD","Monthly MaxDD",
            "ΔCAGR vs T0","ΔSortino vs T0","ΔSharpe vs T0","DD change vs T0"
        ]
        show = metrics[show_cols].copy().astype(object)

        for c in ["CAGR","Daily MaxDD","Monthly MaxDD","ΔCAGR vs T0","DD change vs T0"]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        for c in ["Sortino0","Sharpe0","ΔSortino vs T0","ΔSharpe vs T0"]:
            show[c] = metrics[c].map(
                lambda x: "—" if pd.isna(x) else f"{x:+.3f}"
            )
        st.dataframe(show, use_container_width=True)

        active = turbo_active.reindex(daily.index).fillna(False)
        allow = allow_l2.reindex(daily.index).fillna(False)

        st.markdown("#### 2) Turbo activity")
        st.write(
            f"Turbo active: **{int(active.sum()):,}日 / {len(active):,}日 "
            f"({active.mean()*100:.1f}%)** — "
            f"L2許可日の **{(active.sum()/allow.sum()*100 if allow.sum() else float('nan')):.1f}%**"
        )

        roll = _v326_rolling_p10_table(daily, variants)
        st.markdown("#### 3) Rolling CAGR P10")
        rshow = roll.copy().astype(object)
        for c in variants:
            rshow[c] = roll[c].map(
                lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%"
            )
        st.dataframe(rshow, hide_index=True, use_container_width=True)

        progress.progress(84, text="CPCVを計算中…")
        monthly = (1.0 + daily).resample("ME").prod() - 1.0

        ladder_names = [
            "T1 MOM50 TQQQ",
            "T2 75% TQQQ",
            "T3 100% TQQQ",
        ]

        # Direct robustness vs the chosen Control.
        cpcv_vs_t0, _ = _v326_cpcv_summary(
            monthly, ctrl_name, ladder_names
        )

        # Whole architecture vs Base as secondary check.
        cpcv_vs_base, _ = _v326_cpcv_summary(
            monthly, "Base Adaptive ALL",
            [ctrl_name] + ladder_names
        )

        def compact_cpcv(detail):
            if detail.empty:
                return pd.DataFrame()
            rows = []
            for v, g in detail.groupby("Variant"):
                rows.append({
                    "Variant": v,
                    "Sortino wins": f"{int(g['Positive Delta Sortino'].sum())}/{len(g)}",
                    "Median ΔSortino": g["Delta Sortino0"].median(),
                    "P10 ΔSortino": g["Delta Sortino0"].quantile(.10),
                    "Positive Active": f"{int(g['Positive Active'].sum())}/{len(g)}",
                    "Median Active/yr": g["Active AnnArithmetic"].median(),
                    "P10 Active/yr": g["Active AnnArithmetic"].quantile(.10),
                })
            return pd.DataFrame(rows)

        cpcv_t0_summary = compact_cpcv(cpcv_vs_t0)
        cpcv_base_summary = compact_cpcv(cpcv_vs_base)

        st.markdown("#### 4) CPCV — each Turbo intensity vs T0")
        st.dataframe(
            cpcv_t0_summary.round(4),
            hide_index=True, use_container_width=True
        )

        st.markdown("#### 5) CPCV — whole ladder vs Base")
        st.dataframe(
            cpcv_base_summary.round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(92, text="ストレス期間を確認中…")
        stress_windows = [
            ("COVID", "2020-02-20", "2020-03-23"),
            ("2020 Sep", "2020-09-02", "2020-09-24"),
            ("2022 Aug-Oct", "2022-08-16", "2022-10-13"),
            ("2025 Feb-Apr", "2025-02-21", "2025-04-07"),
        ]
        stress_rows = []
        for label, a, b in stress_windows:
            sub = daily.loc[pd.Timestamp(a):pd.Timestamp(b)]
            if len(sub):
                row = {"Window": label}
                for v in variants:
                    row[v] = (1.0 + sub[v]).prod() - 1.0
                stress_rows.append(row)
        stress = pd.DataFrame(stress_rows)

        st.markdown("#### 6) Fixed stress windows")
        sshow = stress.copy().astype(object)
        for v in variants:
            if v in stress:
                sshow[v] = stress[v].map(lambda x:f"{x*100:+.2f}%")
        st.dataframe(sshow, hide_index=True, use_container_width=True)

        # Simple DD budget readout.
        st.markdown("#### 7) DD budget check")
        budget_rows = []
        for v in [ctrl_name] + ladder_names:
            mdd = metrics.loc[v, "Daily MaxDD"]
            budget_rows.append({
                "Variant": v,
                "Daily MaxDD": mdd,
                "Distance from -35%": mdd - (-0.35),
                "Within -35%": bool(mdd >= -0.35),
            })
        budget = pd.DataFrame(budget_rows)
        bshow = budget.copy().astype(object)
        bshow["Daily MaxDD"] = budget["Daily MaxDD"].map(lambda x:f"{x*100:.2f}%")
        bshow["Distance from -35%"] = budget["Distance from -35%"].map(
            lambda x:f"{x*100:+.2f}pt"
        )
        st.dataframe(bshow, hide_index=True, use_container_width=True)

        # Monthly audit, last 24 months only on screen.
        tmp = pd.DataFrame({
            "Turbo active": turbo_active,
            "L2 allowed": allow_l2,
            "VIX30 brake": vix_brake,
        }).resample("ME").last()
        tmp["Month"] = tmp.index.to_period("M").astype(str)

        audit = inflect_audit.copy().merge(
            tmp[["Month","Turbo active","L2 allowed","VIX30 brake"]],
            on="Month", how="left"
        )
        audit = audit[
            pd.PeriodIndex(audit["Month"], freq="M")
            <= pd.Period("2026-07","M")
        ]

        st.markdown("#### 8) Recent Turbo signal audit")
        st.dataframe(
            audit.tail(24).round(4),
            hide_index=True, use_container_width=True
        )

        progress.progress(100, text="完了")
        progress.empty()

        # One compact ZIP only.
        import io as _io
        import zipfile as _zipfile
        buf = _io.BytesIO()
        with _zipfile.ZipFile(
            buf, "w", compression=_zipfile.ZIP_DEFLATED
        ) as z:
            z.writestr(
                "01_full_metrics.csv",
                metrics.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "02_monthly_returns.csv",
                monthly.to_csv().encode("utf-8-sig")
            )
            z.writestr(
                "03_rolling_p10.csv",
                roll.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "04_cpcv_vs_t0.csv",
                cpcv_vs_t0.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "05_cpcv_vs_base.csv",
                cpcv_vs_base.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "06_stress_windows.csv",
                stress.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "07_dd_budget.csv",
                budget.to_csv(index=False).encode("utf-8-sig")
            )
            z.writestr(
                "08_turbo_signal_audit.csv",
                audit.to_csv(index=False).encode("utf-8-sig")
            )

        st.markdown("#### 9) 保存")
        st.download_button(
            "📦 v3.33 Turbo Intensity Ladder（ZIP）",
            data=buf.getvalue(),
            file_name="frozen_core_v333_turbo_intensity_ladder.zip",
            mime="application/zip",
            use_container_width=True,
            on_click="ignore",
            key="dl_v333",
        )

        st.caption(
            "採用判断はCAGRだけではなく、Rolling P10、SortinoをSharpeより重く見つつ、"
            "Daily/Monthly DD、CPCV、stress windowを総合評価します。"
        )


