def render_v331_momentum_inflection_autopsy(px_close, rf_bt, start, end):
    st.markdown("### ⚡ v3.31 — Momentum Inflection Autopsy")
    st.caption(
        "目標戦略が『まだ弱いが、回復し始めた局面』を早く拾っているかを検証します。"
        "Turbo売買ルールはまだ作りません。"
    )
    st.info("開発データは2026-07まで固定。閾値探索・最適化なし。")
    st.warning(
        "今回の主役は momentum の水準ではなく『短期−中長期』の速度差です。"
        "2020-04や2023-03だけに合うルールは採用しません。"
    )

    if st.button("Momentum Inflection を解析", type="primary", key="run_v331"):
        with st.spinner("Target月次履歴と前月末Inflection特徴量を照合中…"):
            target = _v330_normalize_target_table(_v330_find_target_monthly_table())
            target["BroadState"] = target.get(
                "BroadStateExact",
                target["AllocationText"].map(_v330_classify_broad_state)
            )

            needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
            closes = px_close.reindex(columns=[c for c in needed if c in px_close.columns]).copy()
            missing = [x for x in needed if x not in closes.columns]
            if missing:
                extra = get_close(tuple(missing), start, end)
                closes = closes.join(extra, how="outer").sort_index().ffill()

            feat = _v330_month_end_features(closes)
            feat = _v331_add_inflection_features(feat)
            data = target.merge(feat.reset_index(names="Month"), on="Month", how="left")
            data = data.sort_values("Month").reset_index(drop=True)

            # Same descriptive Super/Normal label as v3.30.
            ag = data["BroadState"].eq("Aggressive")
            ag_median = data.loc[ag,"TargetReturn"].median()
            data["SuperAggressive"] = ag & (data["TargetReturn"] >= ag_median)
            data["NormalAggressive"] = ag & (data["TargetReturn"] < ag_median)

            data["PrevState"] = data["BroadState"].shift(1)
            data["AggressiveEntry"] = ag & ~data["PrevState"].eq("Aggressive")
            data["AggressiveContinuation"] = ag & data["PrevState"].eq("Aggressive")
            data["NonAggressive"] = ~ag

            inflect_features = [c for c in [
                "QQQ_inflect_1m_minus_6m",
                "QQQ_inflect_3m_minus_12m",
                "XLK_inflect_1m_minus_6m",
                "XLK_inflect_3m_minus_12m",
                "QQQ_inflect_1m_minus_3m",
                "XLK_inflect_1m_minus_3m",
                "QQQ_minus_TLT_3m",
                "QQQ_minus_GLD_3m",
                "XLK_minus_XLU_3m",
            ] if c in data.columns]

            st.markdown("#### 1) Fixed Inflection features")
            st.caption(
                "正なら『短期の勢いが中長期より強い』、負なら『短期の方が弱い』を意味します。"
            )
            st.dataframe(
                pd.DataFrame({
                    "Feature": inflect_features,
                    "Meaning": [
                        {
                            "QQQ_inflect_1m_minus_6m":"QQQ 1M − 6M",
                            "QQQ_inflect_3m_minus_12m":"QQQ 3M − 12M",
                            "XLK_inflect_1m_minus_6m":"XLK 1M − 6M",
                            "XLK_inflect_3m_minus_12m":"XLK 3M − 12M",
                            "QQQ_inflect_1m_minus_3m":"QQQ 1M − 3M",
                            "XLK_inflect_1m_minus_3m":"XLK 1M − 3M",
                            "QQQ_minus_TLT_3m":"QQQ 3M − TLT 3M",
                            "QQQ_minus_GLD_3m":"QQQ 3M − GLD 3M",
                            "XLK_minus_XLU_3m":"XLK 3M − XLU 3M",
                        }.get(f, f)
                        for f in inflect_features
                    ]
                }),
                hide_index=True, use_container_width=True
            )

            # A: Super vs Normal Aggressive
            sn = _v331_binary_feature_table(
                data, data["SuperAggressive"], data["NormalAggressive"],
                "Super", "Normal", inflect_features
            )
            st.markdown("#### 2) Super vs Normal Aggressive")
            st.dataframe(sn.round(3), hide_index=True, use_container_width=True)

            # B: Entry vs Continuation
            ec = _v331_binary_feature_table(
                data, data["AggressiveEntry"], data["AggressiveContinuation"],
                "Entry", "Continuation", inflect_features
            )
            st.markdown("#### 3) Aggressive Entry vs Continuation")
            st.caption("目標がAggressiveへ入り直す直前に、Inflectionが特に強いかを確認。")
            st.dataframe(ec.round(3), hide_index=True, use_container_width=True)

            # C: Entry vs NonAggressive
            en = _v331_binary_feature_table(
                data, data["AggressiveEntry"], data["NonAggressive"],
                "Entry", "NonAgg", inflect_features
            )
            st.markdown("#### 4) Aggressive Entry vs Non-Aggressive")
            st.caption("単に相場が弱いだけの月と、実際にAggressiveへ転じた月を分けられるか。")
            st.dataframe(en.round(3), hide_index=True, use_container_width=True)

            # Era stability for Entry vs Continuation and Super vs Normal
            era_ec = _v331_era_compare(
                data, "AggressiveEntry", "AggressiveContinuation", inflect_features
            )
            era_sn = _v331_era_compare(
                data, "SuperAggressive", "NormalAggressive", inflect_features
            )

            st.markdown("#### 5) Era stability — Entry vs Continuation")
            if not era_ec.empty:
                p = era_ec.pivot(index="Feature", columns="Era", values="Median diff")
                st.dataframe(p.round(3), use_container_width=True)

            st.markdown("#### 6) Era stability — Super vs Normal")
            if not era_sn.empty:
                p2 = era_sn.pivot(index="Feature", columns="Era", values="Median diff")
                st.dataframe(p2.round(3), use_container_width=True)

            # Explicit recovery cases.
            focus_months = [pd.Period("2020-04","M"), pd.Period("2023-03","M")]
            focus_cols = [
                "Month","PrevState","BroadState","TargetReturn",
                "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
                "XLK_mom1","XLK_mom3","XLK_mom6","XLK_mom12",
                "QQQ_inflect_1m_minus_6m","QQQ_inflect_3m_minus_12m",
                "XLK_inflect_1m_minus_6m","XLK_inflect_3m_minus_12m",
                "TLT_mom3","LQD_mom3","GLD_mom3","VIX","RiskCorr20"
            ]
            focus = data[data["Month"].isin(focus_months)][
                [c for c in focus_cols if c in data.columns]
            ].copy()

            st.markdown("#### 7) Recovery focus — 2020-04 / 2023-03")
            if not focus.empty:
                focus["Month"] = focus["Month"].astype(str)
                focus["TargetReturn"] = focus["TargetReturn"].map(lambda x:f"{x*100:+.2f}%")
                st.dataframe(focus.round(3), hide_index=True, use_container_width=True)

            # Entry events table for context.
            entry_cols = [
                "Month","PrevState","TargetReturn",
                "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
                "QQQ_inflect_1m_minus_6m","QQQ_inflect_3m_minus_12m",
                "XLK_inflect_1m_minus_6m","XLK_inflect_3m_minus_12m",
                "TLT_mom3","LQD_mom3","VIX"
            ]
            entries = data[data["AggressiveEntry"]][
                [c for c in entry_cols if c in data.columns]
            ].copy()
            entries["Month"] = entries["Month"].astype(str)

            st.markdown("#### 8) All Aggressive entry events")
            st.dataframe(entries.round(3), hide_index=True, use_container_width=True)

            # Compact fixed scoreboard.
            score = pd.DataFrame({"Feature": inflect_features})
            if not sn.empty:
                score = score.merge(
                    sn[["Feature","Directional AUC","Direction"]].rename(
                        columns={"Directional AUC":"Super-vs-Normal dAUC",
                                 "Direction":"Super-vs-Normal dir"}
                    ), on="Feature", how="left"
                )
            if not ec.empty:
                score = score.merge(
                    ec[["Feature","Directional AUC","Direction"]].rename(
                        columns={"Directional AUC":"Entry-vs-Cont dAUC",
                                 "Direction":"Entry-vs-Cont dir"}
                    ), on="Feature", how="left"
                )
            if not en.empty:
                score = score.merge(
                    en[["Feature","Directional AUC","Direction"]].rename(
                        columns={"Directional AUC":"Entry-vs-NonAgg dAUC",
                                 "Direction":"Entry-vs-NonAgg dir"}
                    ), on="Feature", how="left"
                )

            st.markdown("#### 9) Diagnostic scoreboard")
            st.dataframe(score.round(3), hide_index=True, use_container_width=True)
            st.caption(
                "Turbo候補に進めるのは、Entry判別とSuper判別の両方で情報量があり、"
                "era方向も大きく崩れない特徴だけです。2020/2023だけ強いものは採用しません。"
            )

            # One compact ZIP only.
            import io as _io
            import zipfile as _zipfile
            buf = _io.BytesIO()
            with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
                z.writestr("01_monthly_inflection_labeled.csv",
                           data.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("02_super_vs_normal.csv",
                           sn.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("03_entry_vs_continuation.csv",
                           ec.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("04_entry_vs_nonaggressive.csv",
                           en.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("05_era_entry_vs_continuation.csv",
                           era_ec.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("06_era_super_vs_normal.csv",
                           era_sn.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("07_recovery_focus.csv",
                           focus.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("08_aggressive_entries.csv",
                           entries.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("09_scoreboard.csv",
                           score.to_csv(index=False).encode("utf-8-sig"))

            st.markdown("#### 10) 保存")
            st.download_button(
                "📦 Momentum Inflection診断を保存（ZIP）",
                data=buf.getvalue(),
                file_name="target_momentum_inflection_autopsy_v331.zip",
                mime="application/zip",
                use_container_width=True,
                on_click="ignore",
                key="dl_v331",
            )

def render_v330_super_aggressive_autopsy(px_close, rf_bt, start, end):
    st.markdown("### 🚀 v3.30 — Target Super-Aggressive Regime Autopsy")
    st.caption(
        "70% CAGRの『源泉側』を解析します。売買ルールはまだ作りません。"
        "TargetのAggressive月をNormal / Superに分け、前月末情報だけで違いを探します。"
    )
    st.info("開発データは2026-07までに固定。2026-08 / 09 MTDはTurbo設計に使用しません。")
    st.warning(
        "Super/Normalの分割に当月Target returnを使いますが、これは説明用ラベルだけです."
        "特徴量はすべて前月末まで。閾値探索・Turboルール最適化はしません。"
    )

    if st.button("Super-Aggressive regime を解析", type="primary", key="run_v330"):
        with st.spinner("Target履歴と前月末特徴量を照合中…"):
            target_raw = _v330_find_target_monthly_table()
            if target_raw is None:
                st.error(
                    "このapp内からTarget月次取引テーブルを自動検出できませんでした。"
                    "v3 reverse-engineering版の埋め込みTarget履歴が必要です。"
                )
                return

            try:
                target = _v330_normalize_target_table(target_raw)
            except Exception as e:
                st.error(f"Target table normalization failed: {e}")
                return

            target["BroadState"] = target.get("BroadStateExact", target["AllocationText"].map(_v330_classify_broad_state))

            state_counts_check = target["BroadState"].value_counts()
            if int(state_counts_check.get("Aggressive", 0)) == 0:
                st.error(
                    "Target履歴は読み込めましたがAggressive月を認識できませんでした。"
                    "誤ったテーブルを解析しないため停止します。"
                )
                st.dataframe(
                    target[["Month","TargetReturn","AllocationText","BroadState"]].head(20),
                    hide_index=True, use_container_width=True
                )
                return

            # Need XLK in addition to the execution universe.
            needed = ["QQQ","XLK","SPY","XLU","LQD","TLT","GLD","^VIX"]
            closes = px_close.reindex(columns=[c for c in needed if c in px_close.columns]).copy()
            missing = [x for x in needed if x not in closes.columns]
            if missing:
                extra = get_close(tuple(missing), start, end)
                closes = closes.join(extra, how="outer").sort_index().ffill()

            feat = _v330_month_end_features(closes)
            data = target.merge(feat.reset_index(names="Month"), on="Month", how="left")

            # Aggressive median return is descriptive split only.
            ag_mask = data["BroadState"].eq("Aggressive")
            ag_median = data.loc[ag_mask,"TargetReturn"].median()
            data["AggressiveClass"] = "Not Aggressive"
            data.loc[ag_mask & (data["TargetReturn"] < ag_median), "AggressiveClass"] = "Normal Aggressive"
            data.loc[ag_mask & (data["TargetReturn"] >= ag_median), "AggressiveClass"] = "Super Aggressive"

            # Previous broad state for entry-event analysis.
            data = data.sort_values("Month").reset_index(drop=True)
            data["PrevState"] = data["BroadState"].shift(1)
            data["AggressiveEntry"] = (
                data["BroadState"].eq("Aggressive")
                & ~data["PrevState"].eq("Aggressive")
            )

            feature_cols = [c for c in feat.columns if c in data.columns]

            st.markdown("#### 1) Target state reconstruction")
            state_summary = data.groupby("BroadState").agg(
                Months=("Month","count"),
                Avg_Return=("TargetReturn","mean"),
                Median_Return=("TargetReturn","median"),
            ).sort_values("Months",ascending=False)
            ss = state_summary.copy()
            for c in ["Avg_Return","Median_Return"]:
                ss[c] = ss[c].map(lambda x:f"{x*100:+.2f}%")
            st.dataframe(ss, use_container_width=True)

            ag_summary = data[ag_mask].groupby("AggressiveClass").agg(
                Months=("Month","count"),
                Avg_Return=("TargetReturn","mean"),
                Median_Return=("TargetReturn","median"),
                Worst=("TargetReturn","min"),
                Best=("TargetReturn","max"),
            )
            st.markdown("#### 2) Aggressive → Normal / Super")
            st.caption(f"Aggressive median monthly return = {ag_median*100:+.2f}%（ラベル分割のみ）")
            ash = ag_summary.copy()
            for c in ["Avg_Return","Median_Return","Worst","Best"]:
                ash[c] = ash[c].map(lambda x:f"{x*100:+.2f}%")
            st.dataframe(ash, use_container_width=True)

            # Main feature separation.
            fs = _v330_feature_summary(data, feature_cols)
            st.markdown("#### 3) 前月末特徴量 — Super vs Normal Aggressive")
            top = fs.head(15).copy()
            for c in ["Super median","Normal median"]:
                top[c] = top[c].map(lambda x:"—" if pd.isna(x) else f"{x:+.3f}")
            for c in ["AUC","Directional AUC","Effect"]:
                top[c] = top[c].map(lambda x:"—" if pd.isna(x) else f"{x:.3f}")
            st.dataframe(top, hide_index=True, use_container_width=True)

            # Era stability for top features only, fixed display count not selection rule.
            top_features = fs.head(10)["Feature"].tolist()
            era = _v330_era_stability(data, top_features)
            st.markdown("#### 4) Era stability")
            if not era.empty:
                ep = era.pivot(index="Feature", columns="Era", values="Median diff")
                st.caption("値 = Super median − Normal median。同じ符号が3 eraで続くかを見る。")
                st.dataframe(ep.round(3), use_container_width=True)

                est = []
                for feat_name, g in era.groupby("Feature"):
                    signs = np.sign(g["Median diff"].dropna())
                    est.append({
                        "Feature":feat_name,
                        "Eras available":len(signs),
                        "Positive eras":int((signs>0).sum()),
                        "Negative eras":int((signs<0).sum()),
                        "Same direction all eras": bool(len(signs)>=2 and (np.all(signs>0) or np.all(signs<0))),
                        "Median AUC":g["AUC"].median(),
                    })
                era_score = pd.DataFrame(est).sort_values(
                    ["Same direction all eras","Eras available","Median AUC"],
                    ascending=[False,False,False]
                )
                st.dataframe(era_score, hide_index=True, use_container_width=True)
            else:
                era_score = pd.DataFrame()

            # Entry-event autopsy.
            entries = data[data["AggressiveEntry"]].copy()
            entry_cols = [
                "Month","PrevState","TargetReturn","AggressiveClass","AllocationText"
            ] + feature_cols
            entries = entries[entry_cols]

            st.markdown("#### 5) Aggressive entry events")
            st.caption("Defensive/Mixed → Aggressive の切替月。特徴量はその前月末。")
            entry_show = entries[[
                c for c in ["Month","PrevState","TargetReturn","AggressiveClass",
                            "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12",
                            "QQQ_SMA200","TLT_mom3","LQD_mom3","LQD_minus_TLT_3m",
                            "VIX","VIX_chg1","RiskCorr20_minus_60"]
                if c in entries.columns
            ]].copy()
            entry_show["Month"] = entry_show["Month"].astype(str)
            entry_show["TargetReturn"] = entry_show["TargetReturn"].map(lambda x:f"{x*100:+.2f}%")
            st.dataframe(entry_show, hide_index=True, use_container_width=True)

            # Explicit recovery cases requested.
            focus_months = [pd.Period("2020-04","M"), pd.Period("2023-03","M")]
            focus = data[data["Month"].isin(focus_months)].copy()
            st.markdown("#### 6) Recovery focus — 2020-04 / 2023-03")
            if not focus.empty:
                focus_cols = [
                    "Month","PrevState","BroadState","TargetReturn","AggressiveClass",
                    "QQQ_mom1","QQQ_mom3","QQQ_mom6","QQQ_mom12","QQQ_SMA200",
                    "XLK_mom1","XLK_mom3","XLK_mom6","XLK_SMA200",
                    "TLT_mom3","TLT_mom6","LQD_mom3","LQD_mom6",
                    "LQD_minus_TLT_3m","LQD_minus_TLT_6m",
                    "VIX","VIX_chg1","RiskCorr20","RiskCorr60","RiskCorr20_minus_60"
                ]
                focus_show = focus[[c for c in focus_cols if c in focus.columns]].copy()
                focus_show["Month"] = focus_show["Month"].astype(str)
                focus_show["TargetReturn"] = focus_show["TargetReturn"].map(lambda x:f"{x*100:+.2f}%")
                st.dataframe(focus_show, hide_index=True, use_container_width=True)

            # Compare entries with continuing aggressive months.
            data["AggressiveContinuation"] = (
                data["BroadState"].eq("Aggressive") & data["PrevState"].eq("Aggressive")
            )
            transition_rows = []
            for feat_name in feature_cols:
                en = data.loc[data["AggressiveEntry"], feat_name].dropna()
                co = data.loc[data["AggressiveContinuation"], feat_name].dropna()
                if len(en)>=3 and len(co)>=3:
                    transition_rows.append({
                        "Feature":feat_name,
                        "Entry median":en.median(),
                        "Continuation median":co.median(),
                        "Entry-Continuation":en.median()-co.median(),
                        "N Entry":len(en),"N Continuation":len(co)
                    })
            transition = pd.DataFrame(transition_rows)
            if not transition.empty:
                transition["AbsDiff"] = transition["Entry-Continuation"].abs()
                transition = transition.sort_values("AbsDiff",ascending=False).drop(columns="AbsDiff")
            st.markdown("#### 7) Aggressive Entry vs Continuation")
            st.dataframe(transition.head(15).round(3), hide_index=True, use_container_width=True)

            # Compact conclusion aid: not a fitted rule.
            st.markdown("#### 8) Diagnostic scoreboard")
            score = fs[["Feature","Directional AUC","Direction","Effect"]].copy()
            if not era_score.empty:
                score = score.merge(
                    era_score[["Feature","Eras available","Same direction all eras"]],
                    on="Feature", how="left"
                )
            score = score.sort_values("Directional AUC",ascending=False)
            st.dataframe(score.head(15).round(3), hide_index=True, use_container_width=True)

            st.caption(
                "ここで上位特徴が複数eraで同方向、かつ2020-04/2023-03の回復初期にも整合する場合だけ、"
                "次にTurbo Challengerを1本固定します。単一eraだけ強い特徴は採用しません。"
            )

            # Single ZIP.
            st.markdown("#### 9) 保存")
            import io as _io
            import zipfile as _zipfile
            buf = _io.BytesIO()
            with _zipfile.ZipFile(buf, "w", compression=_zipfile.ZIP_DEFLATED) as z:
                z.writestr("01_target_monthly_labeled.csv", data.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("02_state_summary.csv", state_summary.to_csv().encode("utf-8-sig"))
                z.writestr("03_aggressive_class_summary.csv", ag_summary.to_csv().encode("utf-8-sig"))
                z.writestr("04_super_vs_normal_features.csv", fs.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("05_era_stability.csv", era.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("06_era_score.csv", era_score.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("07_aggressive_entries.csv", entries.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("08_recovery_focus.csv", focus.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("09_entry_vs_continuation.csv", transition.to_csv(index=False).encode("utf-8-sig"))
                z.writestr("10_scoreboard.csv", score.to_csv(index=False).encode("utf-8-sig"))

            st.download_button(
                "📦 Super-Aggressive診断を保存（ZIP）",
                data=buf.getvalue(),
                file_name="target_super_aggressive_autopsy_v330.zip",
                mime="application/zip",
                use_container_width=True,
                on_click="ignore",
                key="dl_v330",
            )


def render_mom_leverage_challenger_light(px_close, rf_bt, start, end):
    st.markdown("### 🚀 MOM Leverage Ladder — Adaptive ALL base")
    st.caption(
        "後付け最適化を避けるため4本だけ固定比較。"
        "MOMのRisk-on保有だけをQQQ/QLD/TQQQへ置換し、"
        "LQD・GLD/TLT・MR・VIXロジックは一切変更しません。"
    )

    if st.button("MOMレバレッジ4本を比較", type="primary", key="run_v325_mom_leverage"):
        with st.spinner("4 variantsを1回の価格行列で計算中…"):
            # Minimal execution universe; TQQQ is the only new asset.
            needed = ["QQQ","QLD","TQQQ","LQD","GLD","TLT","SPXL","TECL","XLU","^VIX","SPY"]
            closes = px_close.reindex(columns=[c for c in needed if c in px_close.columns]).copy()
            missing = [x for x in needed if x not in closes.columns]
            if missing:
                extra = get_close(tuple(missing), start, end)
                closes = closes.join(extra, how="outer").sort_index().ffill()

            opens = get_open(tuple(needed), start, end)
            idx = pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
            closes = closes.reindex(idx).ffill()
            opens = opens.reindex(idx).ffill()

            core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

            # Frozen 12M GLD/TLT selector, applied to ALL sleeves first.
            safe2, _, _ = _safe_haven_multi_selector(closes.assign(XLU=closes["GLD"]))
            safe2 = safe2.reindex(idx).ffill()
            base_h = core_h.copy()
            for model in MODEL_WEIGHTS:
                mask = base_h[model].eq("GLD")
                base_h.loc[mask, model] = safe2.loc[mask]

            asset_ret = opens.pct_change(fill_method=None)
            variants = ["Base Adaptive ALL", "L1 QLD+QLD", "L2 QLD+TQQQ", "L3 TQQQ+TQQQ"]
            daily = {}

            # Base
            daily[variants[0]] = _portfolio_return_from_holdings_fast(base_h, asset_ret)
            # Fixed leverage ladder
            for v in variants[1:]:
                hv = _v325_replace_mom_riskon(base_h, v)
                daily[v] = _portfolio_return_from_holdings_fast(hv, asset_ret)
                del hv

            daily = pd.DataFrame(daily)
            daily = daily.loc[daily.index <= pd.Timestamp("2026-07-31")].dropna()
            if daily.empty:
                raise RuntimeError("Common 4-variant history is empty.")

            st.info(
                f"Strict Open→Open: {daily.index.min().date()} ～ {daily.index.max().date()} "
                f"({len(daily):,} trading days)"
            )

            # Summary
            metrics = pd.DataFrame([_v325_metric_row(v, daily[v]) for v in variants]).set_index("Variant")
            st.markdown("#### 1) Full-sample metrics")
            show = metrics.copy()
            for c in ("CAGR","Vol","Daily MaxDD","Monthly MaxDD"):
                show[c] = show[c].map(lambda x: "—" if pd.isna(x) else f"{x*100:+.2f}%")
            for c in ("Sharpe0","Sortino0"):
                show[c] = show[c].map(lambda x: "—" if pd.isna(x) else f"{x:+.3f}")
            st.dataframe(show, use_container_width=True)

            # Mobile-safe charts: monthly only, no wide multi-column custom layout.
            wealth = (1.0 + daily).cumprod() * 100.0
            wealth_m = wealth.resample("ME").last()
            st.markdown("#### 2) Growth of 100")
            st.line_chart(wealth_m, use_container_width=True)

            dd = wealth / wealth.cummax() - 1.0
            dd_w = dd.resample("W-FRI").min() * 100.0
            st.markdown("#### 3) Drawdown (%)")
