    if st.button("Open→Open 実行差を計算",key="run_execution_reality"):
        with st.spinner("Adjusted Openを取得して計算中…"):
            opens=get_open(tuple(px_close.columns),start,end)
            ex=run_execution_backtest(px_close,opens,rf_bt)
            cl=run_backtest(px_close,rf_bt)
            common=cl.index.intersection(ex.index)
            rows=[]
            for name in ("Frozen Core","SPY"):
                cd=cl.loc[common,name].dropna(); od=ex.loc[common,name].dropna()
                ci=cd.index.intersection(od.index); cd=cd.loc[ci]; od=od.loc[ci]
                mc=performance_metrics(cd); mo=performance_metrics(od)
                cm=(1+cd).groupby(cd.index.to_period("M")).prod().sub(1)
                om=(1+od).groupby(od.index.to_period("M")).prod().sub(1)
                rows.append({"Series":name,"Close CAGR":mc["CAGR"],"Open CAGR":mo["CAGR"],
                    "CAGR gap":mo["CAGR"]-mc["CAGR"],
                    "Close Daily MaxDD":mc["MaxDD"],"Open Daily MaxDD":mo["MaxDD"],
                    "Close Monthly MaxDD":monthly_metrics_0rf(cm)["MaxDD"],"Open Monthly MaxDD":monthly_metrics_0rf(om)["MaxDD"],
                    "Close Sharpe":mc["Sharpe"],"Open Sharpe":mo["Sharpe"]})
            df=pd.DataFrame(rows); show=df.copy()
            for c in ["Close CAGR","Open CAGR","CAGR gap","Close Daily MaxDD","Open Daily MaxDD","Close Monthly MaxDD","Open Monthly MaxDD"]:
                show[c]=show[c].map(lambda x:f"{x*100:+.2f}%")
            for c in ["Close Sharpe","Open Sharpe"]: show[c]=show[c].map(lambda x:f"{x:.2f}")
            st.dataframe(show,hide_index=True,use_container_width=True)
            d=ex.loc[common,"Frozen Core"]-cl.loc[common,"Frozen Core"]
            st.caption(f"Common period: {common.min().date()} ～ {common.max().date()} / Return-gap TE {d.std(ddof=1)*np.sqrt(252)*100:.2f}%")
            r=df[df["Series"].eq("Frozen Core")].iloc[0]
            st.info(f"Frozen Core MaxDD：Close→Close Daily {r['Close Daily MaxDD']*100:.2f}% / Monthly {r['Close Monthly MaxDD']*100:.2f}% ｜ Open→Open Daily {r['Open Daily MaxDD']*100:.2f}% / Monthly {r['Open Monthly MaxDD']*100:.2f}%")
            st.caption("Golden Referenceと比較するときはMonthly MaxDD同士。Daily MaxDDは月中の下落も拾う実運用リスク指標です。")
