@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def run_backtest(px, rf_rates, logic_version="v3.0-final-mom11-ex1-rfA"):
    bt, _ = run_backtest_detailed(px, rf_rates, logic_version=logic_version)
    return bt[["Frozen Core", "SPY"]]


def daily_rf_series(rf_rates, index):
    s = rf_rates.reindex(index, method="ffill").fillna(0.0) / 100.0
    return (1.0 + s).pow(1.0 / 252.0) - 1.0


def performance_metrics(r, rf_daily=None):
    r = r.dropna()
    if len(r) < 2:
        return {}
    years = len(r) / 252.0
    growth = (1 + r).cumprod()
    cagr = growth.iloc[-1] ** (1 / years) - 1
    vol = r.std(ddof=1) * np.sqrt(252)
    peak = growth.cummax()
    dd = growth / peak - 1
    maxdd = dd.min()

    if rf_daily is None:
        excess = r
    else:
        excess = r - rf_daily.reindex(r.index).fillna(0.0)
    sharpe = np.sqrt(252) * excess.mean() / excess.std(ddof=1) if excess.std(ddof=1) > 0 else np.nan
    downside = excess[excess < 0].std(ddof=1)
    sortino = np.sqrt(252) * excess.mean() / downside if pd.notna(downside) and downside > 0 else np.nan
    calmar = cagr / abs(maxdd) if maxdd < 0 else np.nan
    return {
        "CAGR": cagr,
        "MaxDD": maxdd,
        "Volatility": vol,
        "Sharpe": sharpe,
        "Sortino": sortino,
        "Calmar": calmar,
    }


def rolling_cagr(r, window=756):
    wealth = (1 + r).cumprod()
    out = wealth / wealth.shift(window)
    return out.pow(252 / window) - 1


def rolling_sharpe(r, rf_daily, window=252):
    ex = r - rf_daily.reindex(r.index).fillna(0.0)
    mean = ex.rolling(window).mean()
    std = ex.rolling(window).std(ddof=1)
    return np.sqrt(252) * mean / std


# =============================================================================
# v3.76 — DM Multi-Lookback Challenger #1
# Research-only. Frozen v3.45 is NOT modified.
# Pre-registered hypothesis from the supplied DM2 comment:
#   10 trading days / 4 calendar months / 12 calendar months.
# Only the two MOM sleeves' absolute-momentum gate is changed.
# Each horizon is converted to a scalar sign (+1 risk-on / -1 risk-off)
# after comparing LQD total return with the matched risk-free return.
# Equal-weight scalar score = mean(signs); 2-of-3 majority => risk-on.
# No lookback sweep, no weights sweep, no threshold sweep.
# Development cutoff remains 2026-07-31.
# =============================================================================

def _v376_dmml_mom_holding_matrix(core_h, signal_px, rf_rates):
    idx = pd.DatetimeIndex(signal_px.index).sort_values()
    h = core_h.copy().reindex(idx)
    audits = []
    signal_map = {}
    for d in _model_trade_dates(idx, "QQQ-MOM"):
        try:
            prev_me = last_trading_day_before(idx, pd.Timestamp(d.year, d.month, 1))
            r10, s10, e10 = trading_return(signal_px["LQD"], prev_me, 10)
            rf10 = rf_return(rf_rates, s10, e10)
            r4, s4, e4 = calendar_return(signal_px["LQD"], prev_me, 4, exclude_recent=0)
            rf4 = rf_return(rf_rates, s4, e4)
            r12, s12, e12 = calendar_return(signal_px["LQD"], prev_me, 12, exclude_recent=0)
            rf12 = rf_return(rf_rates, s12, e12)
            signs = [1 if r10 >= rf10 else -1, 1 if r4 >= rf4 else -1, 1 if r12 >= rf12 else -1]
            score = float(np.mean(signs))
            risk_on = score > 0.0  # exactly 2-of-3 or 3-of-3
            signal_map[pd.Timestamp(d)] = risk_on
            audits.append({
                "TradeDate": pd.Timestamp(d), "SignalEnd": prev_me,
                "LQD10D": r10, "RF10D": rf10, "S10D": signs[0],
                "LQD4M": r4, "RF4M": rf4, "S4M": signs[1],
                "LQD12M": r12, "RF12M": rf12, "S12M": signs[2],
                "Score": score, "RiskOn": risk_on,
            })
        except (ValueError, IndexError, KeyError):
            continue

    pairs=[]
    for sd, risk_on in signal_map.items():
        loc=idx.get_loc(sd)
        if loc+1 < len(idx):
            pairs.append((idx[loc+1], risk_on))
    if not pairs:
        raise RuntimeError("DM Multi-Lookback signal could not initialize.")
    eff=pd.Series([v for _,v in pairs], index=pd.DatetimeIndex([d for d,_ in pairs]), dtype=bool)
    eff=eff[~eff.index.duplicated(keep="last")].sort_index().reindex(idx).ffill()
    valid=eff.notna()
    h.loc[valid, "QQQ-MOM"] = np.where(eff.loc[valid], "QQQ", "GLD")
    h.loc[valid, "QLD-MOM"] = np.where(eff.loc[valid], "QLD", "GLD")
    return h, pd.DataFrame(audits)


def _v376_build_v345_from_core(core_h, closes, opens, idx):
    safe_input=closes.copy()
    if "XLU" not in safe_input.columns:
        safe_input["XLU"] = safe_input["GLD"]
    safe2,_,_=_safe_haven_multi_selector(safe_input)
    safe2=safe2.reindex(idx).ffill()
    adaptive_h=core_h.copy()
    for model in MODEL_WEIGHTS:
        mask=adaptive_h[model].eq("GLD")
        adaptive_h.loc[mask,model]=safe2.loc[mask]
    gates,_=_v326_bond_regime_signals(closes,idx)
    gate_a=gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)
    brakes,_=_v329_brake_signals(closes,idx)
    vix_brake=brakes["V VIX30"].reindex(idx).fillna(False)
    allow_l2=gate_a & ~vix_brake
    avix_h=_v326_apply_l2_gate(adaptive_h,allow_l2)
    inflect,_=_v332_xlk_inflection_signal(closes,idx)
    inflect=inflect.reindex(idx).fillna(False).astype(bool)
    turbo=(allow_l2 & inflect).reindex(idx).fillna(False).astype(bool)
    choose_tecl,_=_v335_attack_selector_signal(closes,idx)
    choose_tecl=choose_tecl.reindex(idx).fillna(False).astype(bool)
    t1_h=_v332_apply_turbo_l3(avix_h,turbo)
    asset_ret=opens.pct_change(fill_method=None)
    avix_ret=_portfolio_return_from_holdings_fast(avix_h,asset_ret)
    t1_ret=_portfolio_return_from_holdings_fast(t1_h,asset_ret)
    _,attack=_v335_build_t2_and_attack_returns(avix_ret,t1_ret,asset_ret["TQQQ"],asset_ret["TECL"],turbo,choose_tecl)
    promo=(turbo & choose_tecl).reindex(idx).fillna(False)
    v345=attack.copy(); v345.loc[promo]=asset_ret["TECL"].reindex(idx).loc[promo]
    return v345


