# =============================================================================
# v3.77 — DD-HMM Promotion100 Tail-Risk Challenger #1
# Research-only. Frozen v3.45 is NOT modified.
# Pre-registered one-shot rule:
#   - Reuse the fixed v3.74R14 weekly expanding ex-ante 3-state PCA/HMM.
#   - Only when Frozen v3.45 Promotion100 is ON, inspect the last HMM state
#     strictly before the execution month.
#   - If MostLikelyRiskState == "High-Risk", cancel ONLY the 100% TECL
#     promotion and fall back to the already-frozen Attack #1 75% allocation.
#   - Otherwise keep Frozen v3.45 exactly.
# No probability threshold, no state-count sweep, no feature/lookback sweep,
# no sizing sweep. Development cutoff remains 2026-07-31.
# =============================================================================

def _v377_promo_state_map(weekly_hmm, promo_mask, cutoff=pd.Timestamp("2026-07-31")):
    w=weekly_hmm.copy()
    w["SignalDate"]=pd.to_datetime(w["SignalDate"],errors="coerce")
    w=w.dropna(subset=["SignalDate","MostLikelyRiskState"]).sort_values("SignalDate")
    w=w[w["SignalDate"]<=cutoff]
    pm=promo_mask.loc[:cutoff].fillna(False).astype(bool)
    months=pd.PeriodIndex(pm.index[pm].to_period("M").unique(),freq="M")
    rows=[]
    for per in months:
        lookup=per.start_time-pd.Timedelta(nanoseconds=1)
        z=w[w["SignalDate"]<=lookup]
        if z.empty: continue
        r=z.iloc[-1]
        rows.append({"Month":per,"MonthStart":per.start_time,"RiskSignalDate":r["SignalDate"],
                     "MostLikelyRiskState":r["MostLikelyRiskState"],
                     "HighRiskProb":r.get("HighRiskProb",np.nan),"LowRiskProb":r.get("LowRiskProb",np.nan),
                     "TransitionProb":r.get("TransitionProb",np.nan),"Confidence":r.get("Confidence",np.nan),
                     "CancelPromotion":bool(r["MostLikelyRiskState"]=="High-Risk")})
    return pd.DataFrame(rows)


def render_v377_ddhmm_promotion_challenger(px_close, rf_bt, start, end):
    st.markdown("### 🧠 v3.77 — DD-HMM Promotion100 Tail-Risk Challenger #1")
    st.caption("Frozen v3.45は変更しません。既存Promotion100だけに、既存DD-HMMのHigh-Risk stateをtail-risk vetoとして1回だけ適用します。")
    st.info("事前固定ルール：Promotion100 ON ＋ 月初前の最新HMM MostLikelyRiskState=High-Risk → 100% TECL昇格だけ取消し、Frozen Attack #1（75% attack）へ戻す。それ以外はv3.45そのまま。")
    st.warning("確率閾値・state数・特徴量・lookback・サイズは探索しません。Development cutoff=2026-07-31。結果が良くてもFrozen v3.45は上書きしません。")
    if not st.button("DD-HMM Promotion Challengerを検証",type="primary",use_container_width=True,key="run_v377"):
        return
    with st.spinner("Frozen v3.45 / Attack75 / ex-ante weekly HMMを再構築中…"):
        closes,v345,attack75,promo=_v374r10_build_dd_inputs(px_close,rf_bt,start,end)
        hmm=_v374r12_run(closes,v345)
        weekly=hmm["weekly"]
        cutoff=pd.Timestamp("2026-07-31")
        state_map=_v377_promo_state_map(weekly,promo,cutoff)
        challenger=v345.loc[:cutoff].copy()
        cancel_days=pd.Series(False,index=challenger.index)
        if not state_map.empty:
            cancel_months=set(state_map.loc[state_map["CancelPromotion"],"Month"].tolist())
            cancel_days=pd.Series(challenger.index.to_period("M").isin(cancel_months),index=challenger.index) & promo.reindex(challenger.index).fillna(False).astype(bool)
            challenger.loc[cancel_days]=attack75.reindex(challenger.index).loc[cancel_days]
        daily=pd.DataFrame({"Frozen v3.45":v345.loc[:cutoff],"DD-HMM Challenger":challenger}).dropna()
        monthly=(1+daily).groupby(daily.index.to_period("M")).prod()-1
        metrics=pd.DataFrame([_v325_metric_row(c,daily[c]) for c in daily.columns]).set_index("Variant")
        roll=_v326_rolling_p10_table(daily,list(daily.columns))
        cpcv,_=_v326_cpcv_summary(monthly,"Frozen v3.45",["DD-HMM Challenger"])
        wf=_v355_wf_blocks(monthly,"Frozen v3.45","DD-HMM Challenger",13)
        # Promotion-tail audit, using realized monthly control vs counterfactual/challenger.
        pe=[]
        for _,r in state_map.iterrows():
            per=r["Month"]; mask=daily.index.to_period("M")==per
            if not mask.any(): continue
            ctl=float((1+daily.loc[mask,"Frozen v3.45"]).prod()-1)
            ch=float((1+daily.loc[mask,"DD-HMM Challenger"]).prod()-1)
            a75=float((1+attack75.reindex(daily.index).loc[mask]).prod()-1)
            pe.append({**r.to_dict(),"Frozen_v345_Return":ctl,"Attack75_Return":a75,"Challenger_Return":ch,
                       "Challenger_Active":ch-ctl,"Promotion100_Active_vs75":ctl-a75})
        promo_events=pd.DataFrame(pe)
        def _tail_row(name,x):
            x=pd.Series(x).dropna().astype(float)
            if x.empty:return {"Series":name}
            q05=x.quantile(.05); q10=x.quantile(.10)
            return {"Series":name,"N":len(x),"Mean":x.mean(),"P10":q10,"P05":q05,
                    "ExpectedShortfall10":x[x<=q10].mean(),"Worst":x.min(),"NegativeRate":(x<0).mean()}
        promo_tail=pd.DataFrame([
            _tail_row("Frozen v3.45 Promotion100",promo_events.get("Frozen_v345_Return",pd.Series(dtype=float))),
            _tail_row("DD-HMM Challenger Promotion months",promo_events.get("Challenger_Return",pd.Series(dtype=float))),
        ])

    st.markdown("#### Full-sample metrics（開発期間のみ）")
    show=metrics[[c for c in ["CAGR","Volatility","Daily MaxDD","Monthly MaxDD","Sharpe0","Sortino0","Calmar"] if c in metrics.columns]].copy()
    st.dataframe(show.round(6),use_container_width=True)
    st.markdown("#### Rolling CAGR P10")
    st.dataframe(roll.round(6),hide_index=True,use_container_width=True)
    st.markdown("#### CPCV / WF")
    if not cpcv.empty:
        st.write({"CPCV Sortino wins":f"{int(cpcv['Positive Delta Sortino'].sum())}/{len(cpcv)}",
                  "CPCV Sharpe wins":f"{int(cpcv['Positive Delta Sharpe'].sum())}/{len(cpcv)}",
                  "CPCV Positive Active":f"{int(cpcv['Positive Active'].sum())}/{len(cpcv)}",
                  "Median ΔSortino":float(cpcv['Delta Sortino0'].median()),
                  "P10 ΔSortino":float(cpcv['Delta Sortino0'].quantile(.10)),
                  "Median Active/yr":float(cpcv['Active AnnArithmetic'].median()),
                  "P10 Active/yr":float(cpcv['Active AnnArithmetic'].quantile(.10))})
    if not wf.empty:
        act=wf["Active CAGR"].astype(float)
        st.write({"WF wins":int((act>1e-12).sum()),"WF ties":int((act.abs()<=1e-12).sum()),"WF losses":int((act< -1e-12).sum()),"WF blocks":len(act)})
        st.dataframe(wf.round(6),hide_index=True,use_container_width=True)
    st.markdown("#### Promotion100 tail audit")
    st.caption(f"Promotion months={len(promo_events)} ｜ High-Risk veto={int(state_map['CancelPromotion'].sum()) if len(state_map) else 0}")
    st.dataframe(promo_tail.round(6),hide_index=True,use_container_width=True)
    if len(promo_events): st.dataframe(promo_events,use_container_width=True,hide_index=True)

    # One compact ZIP for mobile reliability.
    import zipfile as _zip377
    _buf377=io.BytesIO()
    with _zip377.ZipFile(_buf377,"w",compression=_zip377.ZIP_DEFLATED) as z:
        files={"01_full_metrics.csv":metrics.reset_index(),"02_rolling_p10.csv":roll,
               "03_cpcv_detail.csv":cpcv,"04_wf_blocks.csv":wf,"05_promotion_state_map.csv":state_map,
               "06_promotion_tail.csv":promo_tail,"07_promotion_events.csv":promo_events,
               "08_monthly_returns.csv":monthly.reset_index(),"09_daily_returns.csv":daily.reset_index(),
               "10_weekly_hmm.csv":weekly}
        for name,df in files.items(): z.writestr(name,df.to_csv(index=False).encode("utf-8-sig"))
        z.writestr("README.txt",("v3.77 DD-HMM Promotion100 Tail-Risk Challenger #1\nFrozen v3.45 unchanged.\nRule: only Promotion100 + last pre-month MostLikelyRiskState=High-Risk => revert to frozen Attack #1 75% allocation.\nNo probability threshold or parameter sweep.\nDevelopment cutoff: 2026-07-31.\nForward OOS remains untouched.\n").encode("utf-8"))
    st.download_button("📦 v3.77 検証データZIP",data=_buf377.getvalue(),file_name="v377_ddhmm_promotion_challenger.zip",mime="application/zip",use_container_width=True,on_click="ignore",key="dl_v377")
