# ============================================================
# v3.78 — Distribution Health LIGHT
# Source-inspired diagnostic: skew / excess kurtosis / JB p<0.10.
# IMPORTANT: monitoring only. It never changes Frozen v3.45 positions.
# The source uses intraday→weekly bars; this dashboard only has a reliable
# daily strategy-return stream, so we use a predeclared daily analogue:
# 1D / 2D / 5D / 10D / 21D horizon returns, all observed inside the same
# trailing 252-trading-day window. No horizon/window/threshold optimization.
# ============================================================

def _v378_moments_jb(x):
    x = np.asarray(pd.Series(x).dropna(), dtype=float)
    n = int(x.size)
    if n < 20:
        return np.nan, np.nan, np.nan, np.nan, n
    mu = float(np.mean(x))
    d = x - mu
    m2 = float(np.mean(d*d))
    if (not np.isfinite(m2)) or m2 <= 0:
        return np.nan, np.nan, np.nan, np.nan, n
    m3 = float(np.mean(d**3)); m4 = float(np.mean(d**4))
    skew = m3 / (m2 ** 1.5)
    exk = m4 / (m2 * m2) - 3.0
    jb = n / 6.0 * (skew*skew + 0.25*exk*exk)
    # Chi-square(df=2) survival function is exactly exp(-x/2).
    p = float(np.exp(-0.5 * jb))
    return skew, exk, jb, p, n


def _v378_distribution_timeline(daily_ret, window=252):
    r = pd.Series(daily_ret).dropna().astype(float).sort_index()
    r = r[r.index >= pd.Timestamp("2011-04-01")]
    horizons = [("1D",1),("2D",2),("5D",5),("10D",10),("21D",21)]
    # Build horizon returns once; rolling diagnostics are evaluated monthly
    # rather than every day to keep Streamlit/iPhone CPU and payload small.
    hret = {name: (1.0+r).rolling(h).apply(np.prod, raw=True)-1.0 for name,h in horizons}
    month_ends = r.groupby(r.index.to_period("M")).apply(lambda z: z.index.max())
    rows=[]
    for dt in pd.DatetimeIndex(month_ends.values):
        loc = r.index.get_indexer([dt])[0]
        if loc < window-1:
            continue
        start_dt = r.index[loc-window+1]
        row={"Date":dt}
        breaches=0
        for name,_h in horizons:
            x=hret[name].loc[start_dt:dt]
            sk,ku,jb,p,n=_v378_moments_jb(x)
            br=bool(np.isfinite(p) and p < 0.10)
            breaches += int(br)
            row[f"{name}_Skew"]=sk; row[f"{name}_ExKurt"]=ku
            row[f"{name}_JB"]=jb; row[f"{name}_P"]=p; row[f"{name}_Breach"]=br
            row[f"{name}_N"]=n
        row["DefenseLinesBreached"]=breaches
        rows.append(row)
    return pd.DataFrame(rows), r


