# ============================================================
# v3.79 — Relative Distribution Health LIGHT
# Frozen v3.45 is unchanged. Monitoring only.
# Purpose: detect deterioration relative to v3.45's OWN historical
# distribution rather than testing normality.  No parameter sweep.
#
# Predeclared daily-data analogue:
#   horizons: 1D / 2D / 5D / 10D / 21D
#   local-moment window: trailing 252 trading days
#   relative baseline: expanding PRIOR monthly observations only
#   minimum prior baseline: 36 months
#   three tail-risk components per horizon:
#       low skewness, high excess kurtosis, low empirical ES5
#   component "extreme": historical risk percentile >= 90%
#   horizon breach: >= 2 of 3 components extreme
# Diagnostics are monthly only for mobile/Streamlit efficiency.
# ============================================================

def _v379_dist_stats(x):
    x=np.asarray(pd.Series(x).dropna(),dtype=float)
    n=int(x.size)
    if n<20:
        return np.nan,np.nan,np.nan,n
    mu=float(np.mean(x)); d=x-mu
    m2=float(np.mean(d*d))
    if (not np.isfinite(m2)) or m2<=0:
        return np.nan,np.nan,np.nan,n
    m3=float(np.mean(d**3)); m4=float(np.mean(d**4))
    skew=m3/(m2**1.5)
    exk=m4/(m2*m2)-3.0
    q05=float(np.quantile(x,0.05))
    tail=x[x<=q05]
    es05=float(np.mean(tail)) if tail.size else q05
    return skew,exk,es05,n


def _v379_percentile_le(prior, value):
    p=np.asarray(pd.Series(prior).dropna(),dtype=float)
    if p.size==0 or not np.isfinite(value):
        return np.nan
    # Mid-rank empirical percentile; deterministic and no scipy dependency.
    lt=float(np.sum(p<value)); eq=float(np.sum(p==value))
    return (lt+0.5*eq)/float(p.size)


def _v379_relative_distribution_timeline(daily_ret,window=252,min_baseline_months=36):
    r=pd.Series(daily_ret).dropna().astype(float).sort_index()
    r=r[r.index>=pd.Timestamp('2011-04-01')]
    horizons=[('1D',1),('2D',2),('5D',5),('10D',10),('21D',21)]
    hret={name:(1.0+r).rolling(h).apply(np.prod,raw=True)-1.0 for name,h in horizons}
    month_ends=r.groupby(r.index.to_period('M')).apply(lambda z:z.index.max())

    raw=[]
    for dt in pd.DatetimeIndex(month_ends.values):
        loc=r.index.get_indexer([dt])[0]
        if loc<window-1:
            continue
        start_dt=r.index[loc-window+1]
        row={'Date':dt}
        for name,_h in horizons:
            sk,ku,es,n=_v379_dist_stats(hret[name].loc[start_dt:dt])
            row[f'{name}_Skew']=sk
            row[f'{name}_ExKurt']=ku
            row[f'{name}_ES05']=es
            row[f'{name}_N']=n
        raw.append(row)
    df=pd.DataFrame(raw)
    if df.empty:
        return df,r

    # All historical percentiles are calculated strictly from PRIOR month-end
    # observations to avoid future leakage in historical diagnostics.
    for i in range(len(df)):
        prior=df.iloc[:i]
        ready=len(prior)>=int(min_baseline_months)
        breaches=0; watch=0; scores=[]
        for name,_h in horizons:
            if ready:
                sk=float(df.at[i,f'{name}_Skew']); ku=float(df.at[i,f'{name}_ExKurt']); es=float(df.at[i,f'{name}_ES05'])
                sk_pct=_v379_percentile_le(prior[f'{name}_Skew'],sk)
                ku_pct=_v379_percentile_le(prior[f'{name}_ExKurt'],ku)
                es_pct=_v379_percentile_le(prior[f'{name}_ES05'],es)
                # Risk percentiles: low skew / low ES are bad, high kurtosis is bad.
                sk_risk=1.0-sk_pct if np.isfinite(sk_pct) else np.nan
                ku_risk=ku_pct
                es_risk=1.0-es_pct if np.isfinite(es_pct) else np.nan
                vals=[v for v in [sk_risk,ku_risk,es_risk] if np.isfinite(v)]
                score=float(np.mean(vals))*100.0 if vals else np.nan
                n_ext=int(sum(v>=0.90 for v in vals))
                breach=bool(n_ext>=2)
                is_watch=bool((n_ext==1) and not breach)
            else:
                sk_pct=ku_pct=es_pct=sk_risk=ku_risk=es_risk=score=np.nan
                n_ext=0; breach=False; is_watch=False
            df.at[i,f'{name}_SkewPct']=sk_pct
            df.at[i,f'{name}_KurtPct']=ku_pct
            df.at[i,f'{name}_ES05Pct']=es_pct
            df.at[i,f'{name}_SkewRisk']=sk_risk
            df.at[i,f'{name}_KurtRisk']=ku_risk
            df.at[i,f'{name}_ES05Risk']=es_risk
            df.at[i,f'{name}_RiskScore']=score
            df.at[i,f'{name}_ExtremeComponents']=n_ext
            df.at[i,f'{name}_Breach']=breach
            df.at[i,f'{name}_Watch']=is_watch
            breaches+=int(breach); watch+=int(is_watch)
            if np.isfinite(score): scores.append(score)
        df.at[i,'BaselineMonths']=len(prior)
        df.at[i,'BaselineReady']=bool(ready)
        df.at[i,'DefenseLinesBreached']=breaches if ready else np.nan
        df.at[i,'DefenseLinesWatch']=watch if ready else np.nan
        df.at[i,'CrossHorizonRiskScore']=float(np.mean(scores)) if scores else np.nan
    return df,r


def _v379_stress_lead_audit(timeline):
    stress_dates={
        '2015 selloff':'2015-08-31',
        'Promotion failure 2019-05':'2019-05-31',
        'COVID':'2020-03-31',
        '2022 selloff':'2022-10-31',
        '2025 selloff':'2025-04-30',
    }
    if timeline.empty:
        return pd.DataFrame()
    t=timeline.copy()
    t['Date']=pd.to_datetime(t['Date'])
    t=t[t['BaselineReady']==True].sort_values('Date')
    rows=[]
    for label,ds in stress_dates.items():
        d=pd.Timestamp(ds)
        eligible=t[t['Date']<=d]
        if eligible.empty: continue
        # Last seven available month-ends ending at/just before the episode.
        tail=eligible.tail(7).copy()
        if tail.empty: continue
        for j,(_,x) in enumerate(tail.iterrows()):
            offset=j-(len(tail)-1)  # -6 ... 0 when seven rows exist
            rows.append({
                'Episode':label,
                'EpisodeDate':d,
                'LeadMonth':int(offset),
                'ObservedMonth':x['Date'],
                'LinesBreached':int(x['DefenseLinesBreached']) if np.isfinite(x['DefenseLinesBreached']) else np.nan,
                'LinesWatch':int(x['DefenseLinesWatch']) if np.isfinite(x['DefenseLinesWatch']) else np.nan,
                'CrossHorizonRiskScore':x['CrossHorizonRiskScore'],
            })
    return pd.DataFrame(rows)


def render_v379_relative_distribution_health_light(px_close,rf_bt,start,end):
    st.markdown('### 🧬 v3.79 — Relative Distribution Health LIGHT')
    st.caption('Frozen v3.45は一切変更しません。正規分布との比較ではなく、v3.45自身の過去分布からの変質を監視します。')
    st.info('固定仕様：1D / 2D / 5D / 10D / 21D、252営業日window。各月末の Skew・Excess Kurtosis・ES5 を、未来を使わず過去月だけの分布と比較します。')
    st.warning('診断専用です。各horizonで「低Skew・高Kurtosis・悪化ES5」のうち2項目以上が過去90%極端域ならBREACH。最低36か月の過去baselineを要求し、閾値や期間はこの検証で最適化しません。')
    if not st.button('Relative Distribution Healthを計算',type='primary',use_container_width=True,key='run_v379'):
        return
    with st.spinner('v3.45自身の過去分布を基準に軽量計算中…'):
        _cl,_v345,_a75,_promo=_v374r10_build_dd_inputs(px_close,rf_bt,start,end)
        timeline,r=_v379_relative_distribution_timeline(_v345,252,36)
        stress=_v379_stress_lead_audit(timeline)
    ready=timeline[timeline['BaselineReady']==True].copy() if len(timeline) else pd.DataFrame()
    if ready.empty:
        st.warning('Relative Distribution Healthに必要なbaseline履歴が不足しています。')
        return
    latest=ready.iloc[-1]

    st.markdown('#### 現在のRelative 5防衛ライン')
    rows=[]
    for name in ['1D','2D','5D','10D','21D']:
        n_ext=int(latest[f'{name}_ExtremeComponents'])
        br=bool(latest[f'{name}_Breach']); wa=bool(latest[f'{name}_Watch'])
        status='🔴 BREACH' if br else ('🟡 WATCH' if wa else '🟢 NORMAL')
        rows.append({
            'Horizon':name,
            'Skew':latest[f'{name}_Skew'],
            'Skew risk %':100*latest[f'{name}_SkewRisk'],
            'ExKurt':latest[f'{name}_ExKurt'],
            'Kurt risk %':100*latest[f'{name}_KurtRisk'],
            'ES5':latest[f'{name}_ES05'],
            'ES5 risk %':100*latest[f'{name}_ES05Risk'],
            'Risk Score':latest[f'{name}_RiskScore'],
            'Extreme':n_ext,
            'Status':status,
        })
    cur=pd.DataFrame(rows)
    fmt=cur.copy()
    for c in ['Skew','ExKurt']: fmt[c]=pd.to_numeric(fmt[c],errors='coerce').round(3)
    for c in ['Skew risk %','Kurt risk %','ES5 risk %','Risk Score']: fmt[c]=pd.to_numeric(fmt[c],errors='coerce').round(1)
    fmt['ES5']=pd.to_numeric(fmt['ES5'],errors='coerce').map(lambda x:f'{x:.2%}' if pd.notna(x) else '')
    st.dataframe(fmt,hide_index=True,use_container_width=True)

    nb=int(latest['DefenseLinesBreached']); nw=int(latest['DefenseLinesWatch']); score=float(latest['CrossHorizonRiskScore'])
    if nb==0:
        st.success(f'現在：BREACH 0/5、WATCH {nw}/5。Cross-horizon risk score {score:.1f}/100。')
    elif nb<=2:
        st.warning(f'現在：BREACH {nb}/5、WATCH {nw}/5。Cross-horizon risk score {score:.1f}/100。監視強化レベルですが売買シグナルではありません。')
    else:
        st.error(f'現在：BREACH {nb}/5、WATCH {nw}/5。Cross-horizon risk score {score:.1f}/100。複数時間軸でv3.45自身の通常分布からtail悪化が見られます。')

    st.markdown('#### 月次監視（直近24か月）')
    recent=ready[['Date','DefenseLinesBreached','DefenseLinesWatch','CrossHorizonRiskScore']].tail(24).copy()
    recent['Date']=pd.to_datetime(recent['Date']).dt.strftime('%Y-%m')
