# v3.81 — Managed Vol Challenger #1 LIGHT
# Frozen v3.45 signals unchanged. One pre-fixed overlay only:
#   vol21(t-1) = annualized 21D realized vol of Frozen v3.45
#   exposure(t) = min(1.0, 0.30 / vol21(t-1))
# Remaining exposure is cash (0 return). No leverage-up, no sweep.
# Development cutoff: 2026-07-31.
# ============================================================
def _v381_build(v345, target_vol=0.30, lookback=21):
    r=pd.Series(v345).dropna().astype(float).sort_index()
    vol=(r.rolling(lookback).std(ddof=1)*np.sqrt(252.0)).shift(1)
    exp=(target_vol/vol).clip(upper=1.0)
    exp=exp.where(vol.notna(),1.0).clip(lower=0.0,upper=1.0)
    ch=(r*exp).rename('Managed Vol 30%')
    return pd.concat([r.rename('Frozen v3.45'),ch,vol.rename('PriorVol21'),exp.rename('Exposure')],axis=1).dropna(subset=['Frozen v3.45','Managed Vol 30%'])


def _v381_tail(r):
    r=pd.Series(r).dropna().astype(float)
    q=float(r.quantile(.05)) if len(r) else np.nan
    es=float(r[r<=q].mean()) if len(r) else np.nan
    return q,es


def _v381_metrics(name,r):
    x=pd.Series(r).dropna().astype(float)
    p=performance_metrics(x,rf_daily=None)
    mm=_monthly_maxdd_from_daily(x)
    q5,es5=_v381_tail(x)
    return {'Series':name,'CAGR':p['CAGR'],'Vol':p['Volatility'],'Daily MaxDD':p['MaxDD'],
            'Monthly MaxDD':mm,'Sharpe0':p['Sharpe'],'Sortino0':p['Sortino'],
            'Calmar_MonthlyDD':p['CAGR']/abs(mm) if mm<0 else np.nan,'Daily P05':q5,'Daily ES05':es5}


def _v381_cpcv(monthly):
    from itertools import combinations
    z=monthly[['Frozen v3.45','Managed Vol 30%']].dropna()
    groups=np.array_split(np.arange(len(z)),8); rows=[]
    for a,b in combinations(range(8),2):
        g=z.iloc[np.sort(np.r_[groups[a],groups[b]])]
        c,h=g.iloc[:,0],g.iloc[:,1]
        rows.append({'Group1':a+1,'Group2':b+1,'Months':len(g),
          'Delta Sortino0':_monthly_sortino0(h)-_monthly_sortino0(c),
          'Delta Sharpe0':_monthly_sharpe0(h)-_monthly_sharpe0(c),
          'Active AnnArithmetic':float((h-c).mean()*12),
          'Positive Delta Sortino':bool(_monthly_sortino0(h)>_monthly_sortino0(c)),
          'Positive Delta Sharpe':bool(_monthly_sharpe0(h)>_monthly_sharpe0(c)),
          'Positive Active':bool((h-c).mean()>0)})
    return pd.DataFrame(rows)


def _v381_wf(monthly,n_blocks=13):
    z=monthly[['Frozen v3.45','Managed Vol 30%']].dropna(); rows=[]
    for i,loc in enumerate(np.array_split(np.arange(len(z)),n_blocks),1):
        if not len(loc): continue
        g=z.iloc[loc]; yrs=len(g)/12
        def cg(x):
            v=float((1+x).prod()); return v**(1/yrs)-1 if yrs>0 and v>0 else np.nan
        a,b=cg(g.iloc[:,0]),cg(g.iloc[:,1])
        rows.append({'Block':i,'Start':str(g.index.min()),'End':str(g.index.max()),'Months':len(g),
                     'Frozen CAGR':a,'ManagedVol CAGR':b,'Active CAGR':b-a,'ManagedVol Win':bool(b>a)})
    return pd.DataFrame(rows)


def _v381_stress(daily):
    windows=[('2011 Jul-Oct','2011-07-01','2011-10-31'),('2015 Jul-Aug','2015-07-01','2015-08-31'),
             ('COVID','2020-02-01','2020-04-30'),('2020 Sep','2020-09-01','2020-09-30'),
             ('2022 Aug-Oct','2022-08-01','2022-10-31'),('2023 Jul-Oct','2023-07-01','2023-10-31'),
             ('2025 Feb-Apr','2025-02-01','2025-04-30')]
    rows=[]
    for nm,a,b in windows:
        z=daily.loc[a:b,['Frozen v3.45','Managed Vol 30%']]
        row={'Stress':nm,'Start':a,'End':b}
        for c in z.columns:
            x=z[c].dropna(); eq=(1+x).cumprod(); dd=eq/eq.cummax()-1
            row[c+' Return']=float((1+x).prod()-1) if len(x) else np.nan
            row[c+' MaxDD']=float(dd.min()) if len(x) else np.nan
        rows.append(row)
    return pd.DataFrame(rows)


