# v3.82 — Regime Reset Momentum Audit LIGHT
# Research-only diagnostic; Frozen v3.45 is NOT modified.
# Fixed detector reuses frozen v3.79 Relative Distribution Health:
#   shift event = first month with >=2 breached horizons after prior month <2.
# Momentum clock restarts on the NEXT month; no event/lookback tuning.
# ============================================================
def _v382_monthly_close(px, ticker):
    x=pd.Series(px[ticker]).dropna().astype(float).sort_index()
    return x.groupby(x.index.to_period('M')).last()


def _v382_mom_diag(close_m):
    c=pd.Series(close_m).dropna().astype(float).sort_index()
    out=pd.DataFrame(index=c.index)
    for m in [1,3,6,12]: out[f'{m}M']=c/c.shift(m)-1.0
    for m in [3,6,12]:
        # mM-1M: return from m months ago to one month ago.
        out[f'{m}M-1M']=c.shift(1)/c.shift(m)-1.0
    out['Composite_1_3_6_12']=out[['1M','3M','6M','12M']].mean(axis=1)
    return out


def _v382_build_audit(px_close, rf_bt, start, end):
    # Build Frozen v3.45 only once; reuse the already-frozen v3.79 detector.
    _,v345,_,_=_v374r10_build_dd_inputs(px_close,rf_bt,start,end)
    tl,_=_v379_relative_distribution_timeline(v345,252,36)
    if tl.empty: return pd.DataFrame(),pd.DataFrame(),pd.DataFrame(),pd.DataFrame()
    t=tl.copy(); t['Date']=pd.to_datetime(t['Date']); t=t[t['BaselineReady']==True].sort_values('Date')
    b=pd.to_numeric(t['DefenseLinesBreached'],errors='coerce').fillna(0)
    event=(b>=2) & (b.shift(1).fillna(0)<2)
    ev=t.loc[event,['Date','DefenseLinesBreached','CrossHorizonRiskScore']].copy().reset_index(drop=True)
    ev['ResetEffectiveMonth']=(ev['Date'].dt.to_period('M')+1).astype(str)

    lqd=_v382_monthly_close(px_close,'LQD')
    qqq=_v382_monthly_close(px_close,'QQQ')
    common=lqd.index.intersection(qqq.index)
    lqd=lqd.reindex(common); qqq=qqq.reindex(common)
    ld=_v382_mom_diag(lqd); qd=_v382_mom_diag(qqq)

    event_periods=set(pd.to_datetime(ev['Date']).dt.to_period('M')) if not ev.empty else set()
    last_event=None; rows=[]
    for per in common:
        # Event observed at month-end; reset is effective only from following month.
        if per in event_periods: last_event=per
        months_since=(per-last_event).n if last_event is not None and per>last_event else np.nan
        reset_mom=np.nan; reset_start=''
        if last_event is not None and per>last_event:
            # Exclude the most recent month exactly like 12M-1M logic.
            start_per=last_event+1; end_per=per-1
            if start_per in lqd.index and end_per in lqd.index and end_per>=start_per:
                # Start from prior regime-shift month close; through prior-month close.
                base_per=last_event
                if base_per in lqd.index:
                    reset_mom=float(lqd.loc[end_per]/lqd.loc[base_per]-1.0)
                    reset_start=str(start_per)
        rows.append({'Month':str(per),'LastShiftMonth':str(last_event) if last_event is not None else '',
                     'MonthsSinceShift':months_since,'ResetStartMonth':reset_start,
                     'LQD_12M_1M':ld.loc[per,'12M-1M'] if per in ld.index else np.nan,
                     'LQD_Reset_1MExcluded':reset_mom,
                     'LQD_1M':ld.loc[per,'1M'] if per in ld.index else np.nan,
                     'LQD_3M':ld.loc[per,'3M'] if per in ld.index else np.nan,
                     'LQD_6M':ld.loc[per,'6M'] if per in ld.index else np.nan,
                     'LQD_12M':ld.loc[per,'12M'] if per in ld.index else np.nan,
                     'QQQ_1M':qd.loc[per,'1M'] if per in qd.index else np.nan,
                     'QQQ_3M':qd.loc[per,'3M'] if per in qd.index else np.nan,
                     'QQQ_6M':qd.loc[per,'6M'] if per in qd.index else np.nan,
                     'QQQ_12M':qd.loc[per,'12M'] if per in qd.index else np.nan,
                     'QQQ_12M_1M':qd.loc[per,'12M-1M'] if per in qd.index else np.nan,
                     'QQQ_Composite':qd.loc[per,'Composite_1_3_6_12'] if per in qd.index else np.nan})
    panel=pd.DataFrame(rows)
    # Fixed stress audit: nearest shift at or before each known episode, descriptive only.
    episodes={'2015 selloff':'2015-08','2018 Q4':'2018-12','Promotion failure 2019-05':'2019-05','COVID':'2020-03','2022 selloff':'2022-10','2025 selloff':'2025-04'}
    er=[]
    for nm,ps in episodes.items():
        ep=pd.Period(ps,'M'); prior=[]
        if not ev.empty:
            for d in pd.to_datetime(ev['Date']):
                pp=d.to_period('M')
                if pp<=ep: prior.append(pp)
        last=max(prior) if prior else None
        er.append({'Episode':nm,'EpisodeMonth':str(ep),'LastDetectedShift':str(last) if last else '',
                   'LeadMonths':(ep-last).n if last is not None else np.nan,
                   'DetectedWithinPrior6M':bool(last is not None and 0 <= (ep-last).n <= 6)})
    return ev,panel,pd.DataFrame(er),t[['Date','DefenseLinesBreached','CrossHorizonRiskScore']].copy()


