# ================================================================
# v3.84 — Alpha / Correlation Architecture Audit LIGHT
# Research-only diagnostic. No trading rule / no optimization.
# ================================================================
def _v384_metrics_monthly(r, spy):
    d = pd.concat([r.rename('r'), spy.rename('spy')], axis=1).dropna()
    if len(d) < 24:
        return dict(Months=len(d), CAGR=np.nan, Vol=np.nan, Beta=np.nan, Alpha=np.nan, Sharpe=np.nan, Sortino=np.nan, CorrSPY=np.nan)
    x=d['spy']; y=d['r']
    vx=float(x.var(ddof=1))
    beta=float(y.cov(x)/vx) if vx>0 else np.nan
    alpha_m=float((y-beta*x).mean()) if np.isfinite(beta) else np.nan
    alpha=alpha_m*12.0
    n=len(y); cagr=float((1+y).prod()**(12.0/n)-1)
    vol=float(y.std(ddof=1)*np.sqrt(12))
    sh=float(y.mean()/y.std(ddof=1)*np.sqrt(12)) if y.std(ddof=1)>0 else np.nan
    neg=y[y<0]
    dd=float(np.sqrt((neg.pow(2)).mean())*np.sqrt(12)) if len(neg) else np.nan
    so=float(y.mean()*12/dd) if dd and dd>0 else np.nan
    return dict(Months=n,CAGR=cagr,Vol=vol,Beta=beta,Alpha=alpha,Sharpe=sh,Sortino=so,CorrSPY=float(y.corr(x)))


def _v384_effective_bets(corr):
    a=np.asarray(corr, dtype=float)
    if a.shape[0] < 2 or not np.isfinite(a).all(): return np.nan
    ev=np.linalg.eigvalsh(a); ev=np.clip(ev,0,None)
    den=float((ev**2).sum())
    return float(ev.sum()**2/den) if den>0 else np.nan


def render_v384_alpha_correlation_audit_light(px_close, rf_bt, start, end):
    import io, zipfile
    st.markdown('### 🧬 v3.84 — α / Correlation Architecture Audit LIGHT')
