# ================================================================
# v3.85a — Cross-Asset Dual Momentum (Strategy D) Audit LIGHT
# Pre-fixed candidate; research-only. Frozen v3.45 is unchanged.
# Candidate D:
#   Universe = QQQ / GLD / TLT
#   Signal = 12M-1M relative strength (t-1 close / t-12 close - 1)
#   Winner must also exceed matched RF over the same interval.
#   Otherwise hold Cash (matched monthly RF return).
#   Signal at month-end; holding applies to the following month.
# No lookback/universe/threshold sweep and no FoF optimizer.
# ================================================================
def _v385_rolling_p10_monthly(r):
    r=pd.Series(r).dropna().sort_index()
    rows=[]
    for y in [1,2,3,5,7,10]:
        n=12*y
        vals=[]
        if len(r)>=n:
            for i in range(n-1,len(r)):
                w=r.iloc[i-n+1:i+1]
                vals.append(float((1+w).prod()**(1/y)-1))
        rows.append({'Years':y,'Windows':len(vals),'P10_CAGR':float(np.quantile(vals,.10)) if vals else np.nan,
                     'Median_CAGR':float(np.median(vals)) if vals else np.nan})
    return pd.DataFrame(rows).set_index('Years')


def render_v385_cross_asset_dm_audit_light(px_close, rf_bt, start, end):
    import io, zipfile
    st.markdown('### 🌐 v3.85a — Cross-Asset Dual Momentum / Strategy D Audit LIGHT')
    st.caption('第4の独立alpha family候補を1本だけ事前固定で監査。QQQ / GLD / TLT、12M−1M Relative Strength + matched RF Absolute Momentum。Frozen v3.45は変更しません。')
    if not st.button('Strategy D Auditを実行',type='primary',use_container_width=True,key='run_v385'):
        return
    with st.spinner('Cross-Asset DMと既存3 familyを1回だけ構築中…'):
        dev_end=pd.Timestamp('2026-07-31')
        closes=px_close.copy(); closes.index=pd.DatetimeIndex(closes.index)
        closes=closes.loc[:dev_end].sort_index().ffill()
        rf=rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt,pd.Series) else rf_bt

        # Existing Frozen Core sleeves / three theory families (same architecture audit basis as v3.84).
        core_h=_build_core_holding_matrix(closes,rf).reindex(closes.index)
        safe_h,_=_adaptive_safe_haven_monthly_series(closes); safe_h=safe_h.reindex(closes.index).ffill()
        h=core_h.copy()
        for m in MODEL_WEIGHTS:
            mask=h[m].eq('GLD'); h.loc[mask,m]=safe_h.loc[mask]
        daily=_returns_from_holding_matrix(h,closes)
        monthly=(1+daily).resample('ME').prod(min_count=1)-1
        spy_d=closes['SPY'].pct_change(fill_method=None)
        spy_m=(1+spy_d).resample('ME').prod(min_count=1)-1
        fam=pd.DataFrame(index=monthly.index)
        fam['MOM family']=0.5*monthly['QQQ-MOM']+0.5*monthly['QLD-MOM']
        fam['MR family']=0.5*monthly['Weekly MR 24M']+0.5*monthly['Quarterly MR 24M']
        fam['VIX family']=0.25*monthly['Old VIX 15d']+0.25*monthly['Old VIX 20d']+0.5*monthly['New VIX 20d']

        # Month-end closes and fixed 12M-1M momentum: P(t-1)/P(t-12)-1.
        assets=['QQQ','GLD','TLT']
        me=closes[assets].resample('ME').last()
        mom=me.shift(1)/me.shift(12)-1.0
        # Matched RF for t-12 -> t-1. Loop is monthly (~200 calls), intentionally light.
        rf_lb=pd.Series(index=me.index,dtype=float,name='MatchedRF_12M1M')
        rf_month=pd.Series(index=me.index,dtype=float,name='CashRF')
        for i,dt in enumerate(me.index):
            if i>=12:
                s0=me.index[i-12]; s1=me.index[i-1]
                rf_lb.loc[dt]=rf_return(rf_bt,s0,s1)
            if i>=1:
                rf_month.loc[dt]=rf_return(rf_bt,me.index[i-1],dt)

        # pandas 2.x raises 'Encountered all NA values' for idxmax on the warm-up rows.
        # Evaluate the winner only after at least one momentum value exists; keep warm-up rows as NA.
        valid_mom=mom.notna().any(axis=1)
        winner=pd.Series(pd.NA,index=mom.index,dtype='object',name='RelativeWinner')
        winner_mom=pd.Series(np.nan,index=mom.index,dtype=float,name='WinnerMomentum')
        if valid_mom.any():
            winner.loc[valid_mom]=mom.loc[valid_mom].idxmax(axis=1)
            winner_mom.loc[valid_mom]=mom.loc[valid_mom].max(axis=1)
        signal=winner.where(valid_mom & rf_lb.notna() & (winner_mom>=rf_lb),'Cash')
        signal=signal.where(valid_mom & rf_lb.notna(),pd.NA).rename('Signal')
        # Signal observed at month-end t, used for return in month t+1.
        holding=signal.shift(1).rename('Holding')
        asset_ret=me.pct_change(fill_method=None)
        d_ret=pd.Series(index=me.index,dtype=float,name='Cross-Asset DM')
        for a in assets:
            mask=holding.eq(a); d_ret.loc[mask]=asset_ret.loc[mask,a]
        d_ret.loc[holding.eq('Cash')]=rf_month.loc[holding.eq('Cash')]

        all4=pd.concat([fam,d_ret],axis=1).dropna()
        spy4=spy_m.reindex(all4.index).dropna(); all4=all4.reindex(spy4.index)
        metrics=[]; residuals={}
        for c in all4.columns:
            met=_v384_metrics_monthly(all4[c],spy4); met['Strategy']=c; metrics.append(met)
            b=met['Beta']; residuals[c]=all4[c]-b*spy4 if np.isfinite(b) else all4[c]*np.nan
        metrics=pd.DataFrame(metrics).set_index('Strategy')
        raw=all4.corr(); resid=pd.DataFrame(residuals).corr()
        down=all4.loc[spy4<0].corr(); q=float(spy4.quantile(.10)); crisis=all4.loc[spy4<=q].corr()
        base3=['MOM family','MR family','VIX family']; four=base3+['Cross-Asset DM']
        eff=pd.DataFrame([
            {'Architecture':'Existing 3 families','N':3,'Effective Bets':_v384_effective_bets(raw.loc[base3,base3])},
            {'Architecture':'3 families + Strategy D','N':4,'Effective Bets':_v384_effective_bets(raw.loc[four,four])},
            {'Architecture':'Existing 3 residuals','N':3,'Effective Bets':_v384_effective_bets(resid.loc[base3,base3])},
            {'Architecture':'4 residual alpha streams','N':4,'Effective Bets':_v384_effective_bets(resid.loc[four,four])},
        ]).set_index('Architecture')
        d_corr=pd.DataFrame({
            'Raw Corr':raw.loc['Cross-Asset DM',base3],
            'Residual Corr':resid.loc['Cross-Asset DM',base3],
            'Downside Corr':down.loc['Cross-Asset DM',base3],
            'Crisis Corr':crisis.loc['Cross-Asset DM',base3],
        })
        rolling=_v385_rolling_p10_monthly(d_ret.reindex(all4.index))
        # Signal history and momentum clock for auditability.
        sig=pd.concat([mom.add_suffix('_12M1M'),rf_lb,winner.rename('RelativeWinner'),winner_mom.rename('WinnerMomentum'),signal,holding,d_ret],axis=1)
        # Fixed stress windows; no event optimization.
        episodes=[('2015 selloff','2015-07-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),
                  ('2019-05','2019-05-01','2019-05-31'),('COVID','2020-02-01','2020-04-30'),
                  ('2022 selloff','2022-04-01','2022-10-31'),('2025 selloff','2025-02-01','2025-04-30')]
        stress=[]
        for name,a,b in episodes:
            z=all4.loc[pd.Timestamp(a):pd.Timestamp(b)]
            row={'Episode':name,'Start':a,'End':b}
            for c in four:
                row[c]=float((1+z[c]).prod()-1) if len(z) else np.nan
            stress.append(row)
        stress=pd.DataFrame(stress).set_index('Episode')
        counts=holding.value_counts(dropna=True).rename('Months').to_frame(); counts['Share']=counts['Months']/counts['Months'].sum()

    st.success('完了。単独CAGRだけでなく「既存3 familyが持っていないalphaか」を主判定します。')
    dmet=metrics.loc['Cross-Asset DM']
    c1,c2,c3,c4=st.columns(4)
    c1.metric('D CAGR',f"{dmet['CAGR']*100:.2f}%")
    c2.metric('D α',f"{dmet['Alpha']*100:.2f}%")
    c3.metric('D Sortino',f"{dmet['Sortino']:.3f}")
    c4.metric('D β',f"{dmet['Beta']:.3f}")
    st.markdown('#### 独立性 — Strategy D vs existing families')
    st.dataframe(d_corr.round(3),use_container_width=True)
    st.markdown('#### Effective Betsへの寄与')
    st.dataframe(eff.round(3),use_container_width=True)
    st.markdown('#### 単独metrics')
    sm=metrics.copy()
    for c in ['CAGR','Vol','Alpha']: sm[c]=sm[c]*100
    st.dataframe(sm[['Months','CAGR','Vol','Beta','Alpha','Sharpe','Sortino','CorrSPY']].round(3),use_container_width=True)
    st.markdown('#### Strategy D Rolling P10')
    rr=rolling.copy(); rr[['P10_CAGR','Median_CAGR']]*=100
    st.dataframe(rr.round(2),use_container_width=True)
    st.markdown('#### Fixed stress audit')
    ss=stress.copy()*100
    st.dataframe(ss.round(2),use_container_width=True)
    with st.expander('Holding distribution / full signal history'):
        cc=counts.copy(); cc['Share']*=100; st.dataframe(cc.round(2),use_container_width=True)
        st.dataframe(sig.tail(36).round(4),use_container_width=True)
    st.info('事前固定：QQQ/GLD/TLT、12M−1M、matched RF absolute filter、翌月適用。6/9/18M・asset追加・閾値・weight・FoF最適化は試していません。Dが弱ければこの仕様はRejectし、lookback調整で救済しません。')

    b=io.BytesIO()
    with zipfile.ZipFile(b,'w',zipfile.ZIP_DEFLATED) as z:
        def put(name,df): z.writestr(name,df.to_csv(index=True).encode('utf-8-sig'))
        put('01_metrics_alpha_beta.csv',metrics); put('02_strategyD_vs_family_correlations.csv',d_corr)
        put('03_effective_bets.csv',eff); put('04_raw_correlation.csv',raw); put('05_residual_correlation.csv',resid)
        put('06_downside_correlation.csv',down); put('07_crisis_correlation.csv',crisis)
        put('08_strategyD_rolling_p10.csv',rolling); put('09_fixed_stress_audit.csv',stress)
        put('10_signal_and_momentum_history.csv',sig); put('11_holding_distribution.csv',counts); put('12_monthly_returns_4families.csv',all4)
        z.writestr('README.txt',('v3.85a Cross-Asset Dual Momentum Strategy D Audit LIGHT\nResearch-only; Frozen v3.45 unchanged. Development data clipped at 2026-07-31. Pre-fixed candidate: QQQ/GLD/TLT, 12M-1M relative strength, winner must exceed matched RF absolute momentum, otherwise Cash; signal month-end and holding next month. Existing MOM/MR/VIX family returns reconstructed exactly as v3.84 architecture audit. Primary question is independent alpha contribution (residual/downside/crisis correlation and Effective Bets), not standalone CAGR. No lookback/universe/threshold sweep and no FoF optimizer.\n').encode('utf-8'))
    st.download_button('📦 v3.85a Strategy D Audit ZIP',data=b.getvalue(),file_name='v385a_cross_asset_dm_audit_light.zip',mime='application/zip',use_container_width=True,on_click='ignore',key='dl_v385')



# ================================================================
# v3.86 — Treasury Direction (TMF/TMV) Signal Audit LIGHT
# Research-only. Frozen v3.45 is unchanged.
# Purpose: infer whether TMF/TMV could be the author's missing fourth
# theory family BEFORE inventing any trading mapping.
# Pre-fixed signal:
#   TMF and TMV 12M-1M momentum, month-end information only.
#   TreasuryDirection = TMF if TMF momentum > TMV momentum, else TMV.
#   Strength = TMF momentum - TMV momentum.
# No lookback sweep, no threshold, no asset-mapping optimizer.
# Audit next-month returns of TQQQ/TECL/XLU/GLD/SPXL plus existing
# MOM/MR/VIX family returns; fixed stress windows and persistence.
# ================================================================
def _v386_conditional_stats(ret, regime):
    rows=[]
    ret=pd.Series(ret).astype(float)
    regime=pd.Series(regime).reindex(ret.index)
    for lab in ['TMF','TMV']:
        x=ret.loc[regime.eq(lab)].dropna()
        rows.append({
            'Regime':lab,'Months':len(x),
            'MeanNextMonth':float(x.mean()) if len(x) else np.nan,
            'MedianNextMonth':float(x.median()) if len(x) else np.nan,
            'WinRate':float((x>0).mean()) if len(x) else np.nan,
            'P10':float(x.quantile(.10)) if len(x) else np.nan,
            'P05':float(x.quantile(.05)) if len(x) else np.nan,
            'Worst':float(x.min()) if len(x) else np.nan,
        })
    return pd.DataFrame(rows).set_index('Regime')


def render_v386_treasury_direction_signal_audit_light(px_close, rf_bt, start, end):
    import io, zipfile
    st.markdown('### 🧭 v3.86a — TMF / TMV Treasury Direction Signal Audit LIGHT')
    st.caption('作者ユニバースの未解明要素 TMF / TMV が第4の独立family候補かを、売買戦略を作る前に監査します。Frozen v3.45は変更しません。')
    if not st.button('TMF/TMV Signal Auditを実行',type='primary',use_container_width=True,key='run_v386'):
        return
    with st.spinner('TMF/TMV方向シグナルと翌月条件付きリターンを計算中…'):
        dev_end=pd.Timestamp('2026-07-31')
        closes=px_close.copy(); closes.index=pd.DatetimeIndex(closes.index)
        closes=closes.loc[:dev_end].sort_index().ffill()
        need=['TMF','TMV','TQQQ','TECL','XLU','GLD','SPXL','SPY']
        missing=[c for c in need if c not in closes.columns]
        if missing:
            st.error('必要価格がありません: '+', '.join(missing))
            return

        # Existing three families, same reconstruction as v3.84/v3.85.
        rf=rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt,pd.Series) else rf_bt
        core_h=_build_core_holding_matrix(closes,rf).reindex(closes.index)
        safe_h,_=_adaptive_safe_haven_monthly_series(closes); safe_h=safe_h.reindex(closes.index).ffill()
        h=core_h.copy()
        for m in MODEL_WEIGHTS:
            mask=h[m].eq('GLD'); h.loc[mask,m]=safe_h.loc[mask]
        daily=_returns_from_holding_matrix(h,closes)
        monthly=(1+daily).resample('ME').prod(min_count=1)-1
        fam=pd.DataFrame(index=monthly.index)
        fam['MOM family']=0.5*monthly['QQQ-MOM']+0.5*monthly['QLD-MOM']
        fam['MR family']=0.5*monthly['Weekly MR 24M']+0.5*monthly['Quarterly MR 24M']
        fam['VIX family']=0.25*monthly['Old VIX 15d']+0.25*monthly['Old VIX 20d']+0.5*monthly['New VIX 20d']

        me=closes[need].resample('ME').last()
        mom=me[['TMF','TMV']].shift(1)/me[['TMF','TMV']].shift(12)-1.0
        valid=mom.notna().all(axis=1)
        strength=(mom['TMF']-mom['TMV']).where(valid).rename('TMF_minus_TMV_12M1M')
        direction=pd.Series(pd.NA,index=me.index,dtype='object',name='TreasuryDirection')
        direction.loc[valid & strength.gt(0)]='TMF'
        direction.loc[valid & strength.le(0)]='TMV'

        # Direction observed at month-end t; evaluate returns in t+1.
        next_direction=direction.shift(1).rename('SignalUsedForMonth')
        asset_m=me[['TQQQ','TECL','XLU','GLD','SPXL','SPY']].pct_change(fill_method=None)
        fam2=fam.reindex(me.index)
        panel=pd.concat([asset_m,fam2],axis=1)
        panel=panel.loc[next_direction.notna()]
        used=next_direction.reindex(panel.index)

        stats=[]
        for c in panel.columns:
            z=_v386_conditional_stats(panel[c],used).reset_index()
            z.insert(0,'Series',c); stats.append(z)
        cond=pd.concat(stats,ignore_index=True).set_index(['Series','Regime'])
        # TMF-minus-TMV score known at t, next-month return at t+1.
        score_for_month=strength.shift(1).reindex(panel.index)
        score_corr=pd.DataFrame(index=panel.columns,columns=['Pearson','Spearman'],dtype=float)
        for c in panel.columns:
            d=pd.concat([score_for_month,panel[c]],axis=1).dropna()
            if len(d)>=12:
                score_corr.loc[c,'Pearson']=d.iloc[:,0].corr(d.iloc[:,1],method='pearson')
                score_corr.loc[c,'Spearman']=_v370_spearman_no_scipy(d.iloc[:,0], d.iloc[:,1])

        # Difference TMF-regime minus TMV-regime, fixed diagnostic (not an optimizer).
        diff=[]
        for c in panel.columns:
            a=panel.loc[used.eq('TMF'),c].dropna(); b=panel.loc[used.eq('TMV'),c].dropna()
            diff.append({'Series':c,'Mean_TMF':a.mean(),'Mean_TMV':b.mean(),'MeanDiff_TMF_minus_TMV':a.mean()-b.mean(),
                         'Median_TMF':a.median(),'Median_TMV':b.median(),'WinRate_TMF':(a>0).mean(),'WinRate_TMV':(b>0).mean()})
        diff=pd.DataFrame(diff).set_index('Series')

        # Persistence / transition audit.
        dclean=direction.dropna()
        trans=pd.crosstab(dclean.shift(1),dclean,normalize='index').rename_axis(index='Prior',columns='Current')
        runs=[]
        if len(dclean):
            vals=dclean.to_list(); idx=dclean.index.to_list(); st_i=0
            for i in range(1,len(vals)+1):
                if i==len(vals) or vals[i]!=vals[st_i]:
                    runs.append({'Regime':vals[st_i],'Start':idx[st_i],'End':idx[i-1],'Months':i-st_i})
                    st_i=i
        runs=pd.DataFrame(runs)
        persistence=pd.DataFrame({
            'Regime':['TMF','TMV'],
            'Months':[int((dclean=='TMF').sum()),int((dclean=='TMV').sum())],
            'Share':[float((dclean=='TMF').mean()),float((dclean=='TMV').mean())],
            'MedianRunMonths':[float(runs.loc[runs.Regime.eq('TMF'),'Months'].median()) if len(runs) else np.nan,
                               float(runs.loc[runs.Regime.eq('TMV'),'Months'].median()) if len(runs) else np.nan],
            'MaxRunMonths':[float(runs.loc[runs.Regime.eq('TMF'),'Months'].max()) if len(runs) and (runs.Regime=='TMF').any() else np.nan,
                            float(runs.loc[runs.Regime.eq('TMV'),'Months'].max()) if len(runs) and (runs.Regime=='TMV').any() else np.nan],
        }).set_index('Regime')

        episodes=[('2015 selloff','2015-07-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),
                  ('2019-05','2019-05-01','2019-05-31'),('COVID','2020-02-01','2020-04-30'),
                  ('2022 selloff','2022-04-01','2022-10-31'),('2025 selloff','2025-02-01','2025-04-30')]
        stress=[]
        hist=pd.concat([mom.add_suffix('_12M1M'),strength,direction,next_direction,panel],axis=1)
        for name,a,b in episodes:
            z=hist.loc[pd.Timestamp(a):pd.Timestamp(b)]
            row={'Episode':name,'Start':a,'End':b,'Months':len(z)}
            if len(z):
                sigs=z['SignalUsedForMonth'].dropna()
                row['TMF_signal_months']=int((sigs=='TMF').sum()); row['TMV_signal_months']=int((sigs=='TMV').sum())
                row['MeanStrength']=float(z['TMF_minus_TMV_12M1M'].mean())
                for c in ['TQQQ','TECL','XLU','GLD','SPXL','MOM family','MR family','VIX family']:
                    if c in z: row[c]=float((1+z[c].dropna()).prod()-1) if z[c].notna().any() else np.nan
            stress.append(row)
        stress=pd.DataFrame(stress).set_index('Episode')

    st.success('完了。これはSignal Auditのみで、TMF/TMVから保有資産へのルールはまだ作っていません。')
    c1,c2,c3,c4=st.columns(4)
    c1.metric('TMF regime',f"{persistence.loc['TMF','Share']*100:.1f}%")
    c2.metric('TMV regime',f"{persistence.loc['TMV','Share']*100:.1f}%")
    c3.metric('TMF median run',f"{persistence.loc['TMF','MedianRunMonths']:.1f}M")
    c4.metric('TMV median run',f"{persistence.loc['TMV','MedianRunMonths']:.1f}M")
    st.markdown('#### 翌月リターン：TMF regime vs TMV regime')
    dd=diff.copy();
    for c in dd.columns: dd[c]=dd[c]*100
    st.dataframe(dd.round(2),use_container_width=True)
    st.markdown('#### Signal strengthと翌月リターンの相関')
