    pp=persistence.copy(); pp['Share']*=100
    st.dataframe(pp.round(2),use_container_width=True)
    st.markdown('#### Fixed stress audit')
    ss=stress.copy()
    pct_cols=[c for c in ss.columns if c not in ['Start','End','Months','TMF_signal_months','TMV_signal_months','MeanStrength']]
    for c in pct_cols: ss[c]=ss[c]*100
