# v3.80 — Managed Volatility Persistence LIGHT
# Research-only diagnostic. Frozen v3.45 is NOT modified.
# Pre-fixed hypothesis: 21-trading-day realized volatility has persistence.
# ============================================================
def _v380_forward_21d_panel(daily_ret, horizon=21, ann=252):
    r = pd.Series(daily_ret).dropna().astype(float).sort_index()
    r = r.loc[r.index <= pd.Timestamp("2026-07-31")]
    cur_vol = r.rolling(horizon).std(ddof=1) * np.sqrt(ann)
    vals = r.to_numpy(dtype=float)
    dates = pd.DatetimeIndex(r.index)
    rows = []
    # One pass only; ~4k observations, intentionally light.
    for i in range(horizon-1, len(r)-horizon):
        f = vals[i+1:i+1+horizon]
        if len(f) != horizon or not np.isfinite(f).all():
            continue
        wealth = np.cumprod(1.0 + f)
        peak = np.maximum.accumulate(np.r_[1.0, wealth])
        dd = np.r_[1.0, wealth] / peak - 1.0
        k = max(1, int(np.ceil(0.05*horizon)))
        rows.append({
            "Date": dates[i],
            "CurrentVol21": float(cur_vol.iloc[i]),
            "FutureVol21": float(np.std(f, ddof=1)*np.sqrt(ann)),
            "FutureReturn21": float(np.prod(1.0+f)-1.0),
            "FutureMaxDD21": float(np.min(dd)),
            "FutureES5_21": float(np.mean(np.sort(f)[:k])),
            "FutureUpsideBestDay21": float(np.max(f)),
        })
    return pd.DataFrame(rows).set_index("Date"), r


def _v380_corr(x, y, method="pearson"):
    d = pd.concat([pd.Series(x), pd.Series(y)], axis=1).dropna()
    if len(d) < 3:
        return np.nan
    if method == "spearman":
        d = d.rank(method="average")
    return float(d.iloc[:,0].corr(d.iloc[:,1]))


def _v380_summary(panel):
    p = panel.dropna().copy()
    pear = _v380_corr(p["CurrentVol21"], p["FutureVol21"])
    spear = _v380_corr(p["CurrentVol21"], p["FutureVol21"], "spearman")
    # Fixed descriptive terciles; no threshold optimization and no trading rule.
    q1, q2 = p["CurrentVol21"].quantile([1/3, 2/3]).tolist()
    p["VolBucket"] = pd.cut(p["CurrentVol21"], [-np.inf,q1,q2,np.inf], labels=["Low","Normal","High"], include_lowest=True)
    grp = p.groupby("VolBucket", observed=False).agg(
        N=("FutureVol21","size"),
        CurrentVol21=("CurrentVol21","mean"),
        FutureVol21=("FutureVol21","mean"),
        FutureReturn21=("FutureReturn21","mean"),
        FutureMaxDD21=("FutureMaxDD21","mean"),
        FutureES5_21=("FutureES5_21","mean"),
        FutureUpsideBestDay21=("FutureUpsideBestDay21","mean"),
    ).reset_index()
    # Three fixed chronological eras, for direction consistency rather than parameter fitting.
    idx = np.array_split(np.arange(len(p)), 3)
    era=[]
    for j, ii in enumerate(idx,1):
        d=p.iloc[ii]
        era.append({"Era":j,"Start":d.index.min(),"End":d.index.max(),"N":len(d),
                    "Pearson_CurrentFutureVol":_v380_corr(d["CurrentVol21"],d["FutureVol21"]),
                    "Spearman_CurrentFutureVol":_v380_corr(d["CurrentVol21"],d["FutureVol21"],"spearman"),
                    "Corr_CurrentVol_FutureMaxDD":_v380_corr(d["CurrentVol21"],d["FutureMaxDD21"]),
                    "Corr_CurrentVol_FutureES5":_v380_corr(d["CurrentVol21"],d["FutureES5_21"])})
    return pear, spear, q1, q2, grp, pd.DataFrame(era), p


