def _v370_spearman_no_scipy(a, b):
    """
    Top-level compatibility implementation.
    Some older research paths refer to this exact name; keeping it globally
    available prevents NameError regardless of which diagnostic path runs.
    """
    x = pd.to_numeric(pd.Series(a), errors="coerce")
    y = pd.to_numeric(pd.Series(b), errors="coerce")
    m = x.notna() & y.notna()
    x = x[m]
    y = y[m]
    if len(x) < 3:
        return np.nan
    rx = x.rank(method="average").to_numpy(dtype=float)
    ry = y.rank(method="average").to_numpy(dtype=float)
    sx = rx.std(ddof=1)
    sy = ry.std(ddof=1)
    if not np.isfinite(sx) or not np.isfinite(sy) or sx <= 0 or sy <= 0:
        return np.nan
    return float(np.corrcoef(rx, ry)[0, 1])


def _v374r7_spearman(x, y):
    """Standalone Spearman rank correlation for the on-demand DD diagnostic."""
    a = pd.to_numeric(pd.Series(x), errors="coerce")
    b = pd.to_numeric(pd.Series(y), errors="coerce")
    m = a.notna() & b.notna()
    a = a[m]
    b = b[m]
    if len(a) < 3:
        return np.nan

    ra = a.rank(method="average").to_numpy(dtype=float)
    rb = b.rank(method="average").to_numpy(dtype=float)
    sa = ra.std(ddof=1)
    sb = rb.std(ddof=1)
    if not np.isfinite(sa) or not np.isfinite(sb) or sa <= 0 or sb <= 0:
        return np.nan
    return float(np.corrcoef(ra, rb)[0, 1])


def _v374r4_logsumexp(a, axis=None):
    a = np.asarray(a, dtype=float)
    m = np.max(a, axis=axis, keepdims=True)
    out = m + np.log(np.maximum(np.sum(np.exp(a - m), axis=axis, keepdims=True), 1e-300))
    if axis is None:
        return float(out.squeeze())
    return np.squeeze(out, axis=axis)


def _v374r4_forward_backward(X, pi, A, means, vars_):
    X = np.asarray(X, dtype=float)
    T, D = X.shape
    K = len(pi)
    logB = np.empty((T, K), dtype=float)
    for k in range(K):
        v = np.maximum(vars_[k], 1e-8)
        d = X - means[k]
        logB[:, k] = -0.5 * (
            D * np.log(2.0 * np.pi)
            + np.sum(np.log(v))
            + np.sum((d * d) / v, axis=1)
        )

    logpi = np.log(np.maximum(pi, 1e-300))
    logA = np.log(np.maximum(A, 1e-300))
    alpha = np.empty((T, K), dtype=float)
    alpha[0] = logpi + logB[0]
    for t in range(1, T):
        alpha[t] = logB[t] + np.array([
            _v374r4_logsumexp(alpha[t-1] + logA[:, j]) for j in range(K)
        ])
    ll = _v374r4_logsumexp(alpha[-1])

    beta = np.zeros((T, K), dtype=float)
    for t in range(T-2, -1, -1):
        beta[t] = np.array([
            _v374r4_logsumexp(logA[i] + logB[t+1] + beta[t+1])
            for i in range(K)
        ])

    lg = alpha + beta - ll
    gamma = np.exp(lg)
    gamma /= np.maximum(gamma.sum(axis=1, keepdims=True), 1e-300)

    xi_sum = np.zeros((K, K), dtype=float)
    for t in range(T-1):
        lx = (
            alpha[t][:, None] + logA
            + logB[t+1][None, :] + beta[t+1][None, :] - ll
        )
        xi = np.exp(lx)
        den = xi.sum()
        if den > 0:
            xi_sum += xi / den
    return gamma, xi_sum, float(ll)


def _v374r4_fit_hmm(X, max_iter=25):
    X = np.asarray(X, dtype=float)
    T, D = X.shape
    K = 3
    if T < 12:
        raise ValueError("HMM training sample too short.")

    # PC1 is ONLY a deterministic initialization seed.
    # Economic Low/Transition/High labels are assigned later from
    # the original, non-PCA feature space.
    score = X[:, 0]
    q1, q2 = np.quantile(score, [1/3, 2/3])
    init_lab = np.where(score <= q1, 0, np.where(score >= q2, 2, 1))

    means = np.zeros((K, D), dtype=float)
    vars_ = np.ones((K, D), dtype=float)
    for k in range(K):
        g = X[init_lab == k]
        if len(g) >= 2:
            means[k] = g.mean(axis=0)
            vars_[k] = np.maximum(g.var(axis=0, ddof=1), 0.10)
        else:
            means[k] = X.mean(axis=0)
            vars_[k] = np.maximum(X.var(axis=0, ddof=1), 0.10)

    pi = np.array([0.20, 0.60, 0.20], dtype=float)
    A = np.array([
        [0.90, 0.08, 0.02],
        [0.05, 0.90, 0.05],
        [0.02, 0.08, 0.90],
    ], dtype=float)

    prev_ll = -np.inf
    for _ in range(max_iter):
        gamma, xi_sum, ll = _v374r4_forward_backward(X, pi, A, means, vars_)
        w = np.maximum(gamma.sum(axis=0), 1e-8)
        pi = gamma[0]
        A = xi_sum + 1e-4
        A = A / np.maximum(A.sum(axis=1, keepdims=True), 1e-12)
        means = (gamma.T @ X) / w[:, None]
        for k in range(K):
            diff = X - means[k]
            vars_[k] = (
                gamma[:, k][:, None] * (diff ** 2)
            ).sum(axis=0) / w[k]
        vars_ = np.maximum(vars_, 0.05)
        if np.isfinite(prev_ll) and abs(ll - prev_ll) < 1e-5:
            break
        prev_ll = ll

    gamma, _, ll = _v374r4_forward_backward(X, pi, A, means, vars_)
    return {
        "pi": pi, "A": A, "means": means, "vars": vars_,
        "gamma": gamma, "loglik": ll,
    }


def _v374r2_fit_pca(train_df, n_pc=2):
    mu = train_df.mean()
    sd = train_df.std(ddof=1).replace(0, np.nan).fillna(1.0)
    z = ((train_df - mu) / sd).to_numpy(dtype=float)
    cov = np.cov(z, rowvar=False, ddof=1)
    evals, evecs = np.linalg.eigh(cov)
    order = np.argsort(evals)[::-1]
    evals = evals[order]
    evecs = evecs[:, order]
    load = evecs[:, :n_pc]
    scores = z @ load
    explained = evals[:n_pc] / max(float(np.sum(evals)), 1e-12)
    return mu, sd, load, scores, explained


@st.cache_data(ttl=86400, show_spinner=False)

@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def _v374r10_build_dd_inputs(px_close, rf_bt, start, end):
    """
    Build ONLY the frozen v3.45 daily return and market closes required by
    DD Regime. It deliberately skips Target parsing, Promotion autopsy,
    Breakout, v3.69, Managed Regime, HMM-v3.71, Context×Regime, CPCV/WF
    dashboard assembly, charts, and ZIP exports.
    """
    needed = [
        "QQQ", "QLD", "TQQQ", "LQD", "GLD", "TLT",
        "SPXL", "TECL", "XLU", "^VIX", "SPY", "XLK",
    ]

    closes = px_close.reindex(
        columns=[c for c in needed if c in px_close.columns]
    ).copy()
    missing = [x for x in needed if x not in closes.columns]
    if missing:
        closes = closes.join(
            get_close(tuple(missing), start, end),
            how="outer",
        ).sort_index().ffill()

    opens = get_open(tuple(needed), start, end)
    idx = pd.DatetimeIndex(
        closes.index.intersection(opens.index)
    ).sort_values()

    closes = closes.reindex(idx).ffill()
    opens = opens.reindex(idx).ffill()
    asset_ret = opens.pct_change(fill_method=None)

    core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

    safe_input = closes.copy()
    if "XLU" not in safe_input.columns:
        safe_input["XLU"] = safe_input["GLD"]

    safe2, _, _ = _safe_haven_multi_selector(safe_input)
    safe2 = safe2.reindex(idx).ffill()

    adaptive_h = core_h.copy()
    for model in MODEL_WEIGHTS:
        mask = adaptive_h[model].eq("GLD")
        adaptive_h.loc[mask, model] = safe2.loc[mask]

    gates, _ = _v326_bond_regime_signals(closes, idx)
    gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

    brakes, _ = _v329_brake_signals(closes, idx)
    vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
    allow_l2 = gate_a & ~vix_brake

    avix_h = _v326_apply_l2_gate(adaptive_h, allow_l2)

    inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
    inflect_eff = inflect_eff.reindex(idx).fillna(False).astype(bool)
    turbo = (allow_l2 & inflect_eff).reindex(idx).fillna(False).astype(bool)

    choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
    choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

    t1_h = _v332_apply_turbo_l3(avix_h, turbo)
    avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
    t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

    _, attack = _v335_build_t2_and_attack_returns(
        avix_ret,
        t1_ret,
        asset_ret["TQQQ"],
        asset_ret["TECL"],
        turbo,
        choose_tecl,
    )

    promo = (turbo & choose_tecl).reindex(idx).fillna(False)
    v345 = attack.copy()
    v345.loc[promo] = asset_ret["TECL"].reindex(idx).loc[promo]

    cutoff = pd.Timestamp("2026-07-31")
    return (
        closes.loc[:cutoff].copy(),
        v345.loc[:cutoff].dropna().copy(),
        attack.loc[:cutoff].dropna().copy(),
        promo.loc[:cutoff].astype(bool).copy(),
    )


def _v374r12_run(closes, v345):
    cutoff = pd.Timestamp("2026-07-31")
    min_train = 104
    refit_every = 13
    need = ["QQQ", "XLK", "TLT", "LQD", "GLD", "^VIX"]

    px = closes.loc[:cutoff].copy()
    missing = [c for c in need if c not in px.columns]
    if missing:
        raise RuntimeError(f"v3.74R5 missing columns: {missing}")

    wk = px[need].resample("W-FRI").last().dropna(how="all")
    feat = pd.DataFrame(index=wk.index)
    feat["QQQ_4W"] = wk["QQQ"] / wk["QQQ"].shift(4) - 1.0
    feat["XLK_4W"] = wk["XLK"] / wk["XLK"].shift(4) - 1.0
    feat["TLT_4W"] = wk["TLT"] / wk["TLT"].shift(4) - 1.0
    feat["LQD_4W"] = wk["LQD"] / wk["LQD"].shift(4) - 1.0
    feat["GLD_4W"] = wk["GLD"] / wk["GLD"].shift(4) - 1.0
    feat["VIX_4W_Change"] = wk["^VIX"] / wk["^VIX"].shift(4) - 1.0
    feat["VIX_Level"] = wk["^VIX"]
    feat = feat.replace([np.inf, -np.inf], np.nan).dropna()

    v345w = (1.0 + v345.loc[:cutoff].dropna()).resample("W-FRI").prod() - 1.0

    rows, errors = [], []
    latest_loadings = pd.DataFrame(
        columns=["Feature", "PC1Loading", "PC2Loading"]
    )

    model = None
    pca_mu = pca_sd = pca_load = None
    low_k = mid_k = high_k = None
    filt_prob = None
    last_refit_i = None
    last_refit_date = None

    def _emission_prob(x, means, vars_):
        x = np.asarray(x, dtype=float)
        D = x.shape[0]
        out = np.empty(3, dtype=float)
        for k in range(3):
            v = np.maximum(vars_[k], 1e-8)
            d = x - means[k]
            logp = -0.5 * (
                D * np.log(2.0 * np.pi)
                + np.sum(np.log(v))
                + np.sum((d * d) / v)
            )
            out[k] = np.exp(np.clip(logp, -700, 700))
        return np.maximum(out, 1e-300)

    for end_i in range(min_train - 1, len(feat) - 1):
        train = feat.iloc[:end_i + 1].copy()
        signal_date = train.index[-1]
        next_date = feat.index[end_i + 1]
        do_refit = (
            model is None
            or last_refit_i is None
            or (end_i - last_refit_i) >= refit_every
        )

        try:
            if do_refit:
                mu, sd, load, scores, explained = _v374r2_fit_pca(train, 2)
                fit = _v374r4_fit_hmm(scores, max_iter=25)

                # Economic state labels are determined from ORIGINAL features,
                # not from arbitrary PCA signs.
                muo = train.mean()
                sdo = train.std(ddof=1).replace(0, np.nan).fillna(1.0)
                zo = ((train - muo) / sdo).to_numpy(dtype=float)
                stress_obs = (
                    -zo[:, 0] - zo[:, 1] - zo[:, 2]
                    -zo[:, 3] - zo[:, 4]
                    +zo[:, 5] + zo[:, 6]
                )
                gamma = np.asarray(fit["gamma"], dtype=float)
                state_stress = []
                for k in range(3):
                    w = gamma[:, k]
                    den = max(float(w.sum()), 1e-12)
                    state_stress.append(
                        float(np.sum(w * stress_obs) / den)
                    )
                low_k, mid_k, high_k = map(int, np.argsort(state_stress))

                model = fit
                pca_mu, pca_sd, pca_load = mu, sd, load
                filt_prob = gamma[-1].copy()
                last_refit_i = end_i
                last_refit_date = signal_date

                latest_loadings = pd.DataFrame({
                    "Feature": train.columns,
                    "PC1Loading": load[:, 0],
                    "PC2Loading": load[:, 1],
                })
                pc_explained = explained
            else:
                # No refit: use ONLY the already-fitted ex-ante model and
                # the current week's feature vector for one-step filtering.
                row = train.iloc[[-1]]
                z = ((row - pca_mu) / pca_sd).to_numpy(dtype=float)
                x = (z @ pca_load)[0]

                pred = np.asarray(filt_prob, dtype=float) @ model["A"]
                emit = _emission_prob(x, model["means"], model["vars"])
                post = pred * emit
                den = float(post.sum())
                if not np.isfinite(den) or den <= 0:
                    post = pred / max(float(pred.sum()), 1e-12)
                else:
                    post = post / den
                filt_prob = post
                pc_explained = np.array([np.nan, np.nan])

            lastp = np.asarray(filt_prob, dtype=float)
            ml = int(np.argmax(lastp))
            nextret = v345w.reindex([next_date]).iloc[0]

            rows.append({
                "SignalDate": signal_date,
                "OutcomeWeek": next_date,
                "LowRiskProb": float(lastp[low_k]),
                "TransitionProb": float(lastp[mid_k]),
                "HighRiskProb": float(lastp[high_k]),
                "Confidence": float(np.max(lastp)),
                "MostLikelyRiskState": (
                    "Low-Risk" if ml == low_k
                    else "High-Risk" if ml == high_k
                    else "Transition"
                ),
                "NextWeekReturn": float(nextret) if pd.notna(nextret) else np.nan,
                "NextWeekLoss": (
                    float(-min(nextret, 0.0))
                    if pd.notna(nextret) else np.nan
                ),
                "NextWeekNegative": (
                    bool(nextret < 0) if pd.notna(nextret) else np.nan
                ),
                "PC1Explained": (
                    float(pc_explained[0])
                    if np.isfinite(pc_explained[0]) else np.nan
                ),
                "PC2Explained": (
                    float(pc_explained[1])
                    if np.isfinite(pc_explained[1]) else np.nan
                ),
                "TrainWeeks": int(len(train)),
                "LogLikelihood": (
                    float(model["loglik"]) if do_refit else np.nan
                ),
                "Refit": bool(do_refit),
                "ModelRefitDate": last_refit_date,
            })

        except Exception as e:
            errors.append({
                "SignalDate": signal_date,
                "OutcomeWeek": next_date,
                "TrainWeeks": int(len(train)),
                "Refit": bool(do_refit),
                "Error": repr(e),
            })
            # If a full refit fails, force another attempt next week.
            if do_refit:
                model = None
                filt_prob = None
                last_refit_i = None

    weekly_cols = [
        "SignalDate", "OutcomeWeek", "LowRiskProb", "TransitionProb",
        "HighRiskProb", "Confidence", "MostLikelyRiskState",
        "NextWeekReturn", "NextWeekLoss", "NextWeekNegative",
        "PC1Explained", "PC2Explained", "TrainWeeks", "LogLikelihood",
        "Refit", "ModelRefitDate",
    ]
    weekly = pd.DataFrame(rows, columns=weekly_cols)
    fit_errors = pd.DataFrame(
        errors,
        columns=[
            "SignalDate", "OutcomeWeek", "TrainWeeks", "Refit", "Error"
        ],
    )

    valid = weekly.dropna(
        subset=["HighRiskProb", "NextWeekLoss", "NextWeekReturn"]
    ).copy()

    rho_loss = (
        _v374r7_spearman(valid["HighRiskProb"], valid["NextWeekLoss"])
        if len(valid) >= 3 else np.nan
    )
    rho_ret = (
        _v374r7_spearman(valid["HighRiskProb"], valid["NextWeekReturn"])
        if len(valid) >= 3 else np.nan
    )

    state_rows = []
    for state in ["Low-Risk", "Transition", "High-Risk"]:
        g = valid[valid["MostLikelyRiskState"].eq(state)]
        state_rows.append({
            "State": state,
            "N": int(len(g)),
            "MeanNextWeek": float(g["NextWeekReturn"].mean()) if len(g) else np.nan,
            "MedianNextWeek": float(g["NextWeekReturn"].median()) if len(g) else np.nan,
            "P10NextWeek": float(g["NextWeekReturn"].quantile(.10)) if len(g) else np.nan,
            "P05NextWeek": float(g["NextWeekReturn"].quantile(.05)) if len(g) else np.nan,
            "NegativeRate": float((g["NextWeekReturn"] < 0).mean()) if len(g) else np.nan,
            "MeanDownsideLoss": float(g["NextWeekLoss"].mean()) if len(g) else np.nan,
        })
    state_summary = pd.DataFrame(state_rows)

    era_rows = []
    if len(valid):
        for i, ix in enumerate(np.array_split(np.arange(len(valid)), 3), 1):
            g = valid.iloc[ix]
            era_rows.append({
                "Era": f"E{i}",
                "Start": g["OutcomeWeek"].min(),
                "End": g["OutcomeWeek"].max(),
                "N": int(len(g)),
                "Spearman HighRiskProb vs NextWeekLoss": (
                    _v374r7_spearman(
                        g["HighRiskProb"], g["NextWeekLoss"]
                    ) if len(g) >= 3 else np.nan
                ),
                "Spearman HighRiskProb vs NextWeekReturn": (
                    _v374r7_spearman(
                        g["HighRiskProb"], g["NextWeekReturn"]
                    ) if len(g) >= 3 else np.nan
                ),
            })
    era_summary = pd.DataFrame(era_rows)

    cpcv_rows = []
    if len(valid) >= 40:
        import itertools as _it
        groups = np.array_split(np.arange(len(valid)), 8)
        for a, b in _it.combinations(range(8), 2):
            ix = np.concatenate([groups[a], groups[b]])
            g = valid.iloc[np.sort(ix)]
            cpcv_rows.append({
                "HoldoutA": int(a + 1),
                "HoldoutB": int(b + 1),
                "N": int(len(g)),
                "SpearmanLoss": _v374r7_spearman(
                    g["HighRiskProb"], g["NextWeekLoss"]
                ),
                "SpearmanReturn": _v374r7_spearman(
                    g["HighRiskProb"], g["NextWeekReturn"]
                ),
            })
    cpcv_detail = pd.DataFrame(cpcv_rows)

    if len(cpcv_detail):
        lv = cpcv_detail["SpearmanLoss"].dropna()
        rv = cpcv_detail["SpearmanReturn"].dropna()
        cpcv_summary = pd.DataFrame([{
            "Splits": int(len(cpcv_detail)),
            "Positive Loss Relation": int((lv > 0).sum()),
            "Negative Return Relation": int((rv < 0).sum()),
            "Median Spearman Loss": (
                float(lv.median()) if len(lv) else np.nan
            ),
            "P10 Spearman Loss": (
                float(lv.quantile(.10)) if len(lv) else np.nan
            ),
            "Median Spearman Return": (
                float(rv.median()) if len(rv) else np.nan
            ),
            "P90 Spearman Return": (
                float(rv.quantile(.90)) if len(rv) else np.nan
            ),
        }])
    else:
        cpcv_summary = pd.DataFrame()

    headline = pd.DataFrame([{
        "Rows": int(len(weekly)),
        "Valid Rows": int(len(valid)),
        "Full Refits": (
            int(weekly["Refit"].sum()) if len(weekly) else 0
        ),
        "Refit Every Weeks": refit_every,
        "Spearman HighRiskProb vs NextWeekLoss": rho_loss,
        "Spearman HighRiskProb vs NextWeekReturn": rho_ret,
        "Fit Errors": int(len(fit_errors)),
    }])

    return {
        "headline": headline,
        "weekly": weekly,
        "state_summary": state_summary,
        "era_summary": era_summary,
        "cpcv_detail": cpcv_detail,
        "cpcv_summary": cpcv_summary,
        "pca_loadings": latest_loadings,
        "fit_errors": fit_errors,
    }


def _v374r12_auc_failure(highrisk, failure):
    """
    Pairwise AUC: probability that a randomly chosen failure month has a
    higher HighRiskProb than a randomly chosen success month.
    0.5 = no discrimination. No threshold fitting.
    """
    x = pd.DataFrame({
        "HighRiskProb": pd.to_numeric(highrisk, errors="coerce"),
        "Failure": pd.Series(failure).astype("boolean"),
    }).dropna()
    a = x.loc[x["Failure"].eq(True), "HighRiskProb"].to_numpy(dtype=float)
    b = x.loc[x["Failure"].eq(False), "HighRiskProb"].to_numpy(dtype=float)
    if len(a) == 0 or len(b) == 0:
        return np.nan
    wins = 0.0
    total = 0
    for av in a:
        for bv in b:
            wins += 1.0 if av > bv else 0.5 if av == bv else 0.0
            total += 1
    return float(wins / total) if total else np.nan


def _v374r12_promotion_hmm_autopsy(weekly_hmm, attack75, v345, promo_mask):
    """
    Promotion100 × HighRiskProb one-shot autopsy.

    For execution month M:
    - Promotion outcome = Frozen v3.45 monthly return minus frozen 75% attack
      counterfactual monthly return.
    - Risk score = last available weekly HMM HighRiskProb strictly BEFORE M.
    - No threshold sweep, no new sizing rule.
    """
    cutoff = pd.Timestamp("2026-07-31")

    # HARD CUTOFF: every input is truncated before any grouping/merge.
    v345 = v345.loc[:cutoff].copy()
    attack75 = attack75.loc[:cutoff].copy()
    promo_mask = promo_mask.loc[:cutoff].copy()

    w = weekly_hmm.copy()
    if "SignalDate" in w.columns:
        w["SignalDate"] = pd.to_datetime(w["SignalDate"], errors="coerce")
        w = w[w["SignalDate"] <= cutoff].copy()
    if "OutcomeWeek" in w.columns:
        w["OutcomeWeek"] = pd.to_datetime(w["OutcomeWeek"], errors="coerce")
        w = w[w["OutcomeWeek"] <= cutoff].copy()

    d = pd.DataFrame({
        "V345": v345,
        "Attack75": attack75,
        "Promotion100": promo_mask,
    }).loc[:cutoff].dropna(subset=["V345", "Attack75"])

    rows = []
    for per, g in d.groupby(d.index.to_period("M")):
        if not bool(g["Promotion100"].max()):
            continue
        actual = float((1.0 + g["V345"]).prod() - 1.0)
        cf75 = float((1.0 + g["Attack75"]).prod() - 1.0)
        active = actual - cf75
        rows.append({
            "Month": per,
            "MonthStart": per.start_time,
            "Promotion100_Return": actual,
            "Counterfactual75_Return": cf75,
            "Promotion_Active": active,
            "PromotionLabel": "100% Winner" if active > 0 else "75% Winner",
            "Failure": bool(active <= 0),
        })

    events = pd.DataFrame(rows)
    if not events.empty:
        events = events[
            events["Month"] <= pd.Period("2026-07", freq="M")
        ].copy()

    if events.empty:
        return {
            "events": events,
            "summary": pd.DataFrame(),
            "state_summary": pd.DataFrame(),
        }

    w = w.dropna(subset=["SignalDate", "HighRiskProb"]).sort_values("SignalDate")

    # Strictly pre-month score: subtract 1 ns so a Friday equal to month-start
    # cannot leak same-day information into the month.
    q = events[["Month", "MonthStart"]].copy()
    q["MonthStart"] = pd.to_datetime(q["MonthStart"], errors="coerce").astype("datetime64[ns]")
    q["RiskLookupTime"] = (
        q["MonthStart"] - pd.Timedelta(nanoseconds=1)
    ).astype("datetime64[ns]")
    q = q.sort_values("RiskLookupTime")

    # Normalize weekly key to the exact same dtype for merge_asof.
    w["SignalDate"] = pd.to_datetime(
        w["SignalDate"], errors="coerce"
    ).astype("datetime64[ns]")
    w = w.dropna(subset=["SignalDate"]).sort_values("SignalDate")

    risk_cols = [
        "SignalDate", "HighRiskProb", "LowRiskProb", "TransitionProb",
        "MostLikelyRiskState", "Confidence", "ModelRefitDate", "Refit",
    ]
    risk_cols = [c for c in risk_cols if c in w.columns]

    _wrisk12 = w[risk_cols].copy()
    _wrisk12["SignalDate"] = _wrisk12["SignalDate"].astype("datetime64[ns]")
    _wrisk12 = _wrisk12.sort_values("SignalDate")

    risk = pd.merge_asof(
        q.sort_values("RiskLookupTime"),
        _wrisk12,
        left_on="RiskLookupTime",
        right_on="SignalDate",
        direction="backward",
        allow_exact_matches=True,
    )

    events = events.merge(
        risk.drop(columns=["MonthStart", "RiskLookupTime"]),
        on="Month",
        how="left",
    )

    valid = events.dropna(subset=["HighRiskProb", "Promotion_Active"]).copy()
    failures = valid[valid["Failure"]]
    winners = valid[~valid["Failure"]]

    rho_active = _v374r7_spearman(
        valid["HighRiskProb"], valid["Promotion_Active"]
    ) if len(valid) >= 3 else np.nan
    auc_failure = _v374r12_auc_failure(
        valid["HighRiskProb"], valid["Failure"]
    )

    summary = pd.DataFrame([{
        "Promotion Months": int(len(valid)),
        "100% Winners": int((~valid["Failure"]).sum()),
        "75% Winners / Failures": int(valid["Failure"].sum()),
        "100% Winner Rate": float((~valid["Failure"]).mean()) if len(valid) else np.nan,
        "Median HighRiskProb - 100% Winner": (
            float(winners["HighRiskProb"].median()) if len(winners) else np.nan
        ),
        "Median HighRiskProb - Failure": (
            float(failures["HighRiskProb"].median()) if len(failures) else np.nan
        ),
        "Failure-minus-Winner Median Prob": (
            float(failures["HighRiskProb"].median() - winners["HighRiskProb"].median())
            if len(failures) and len(winners) else np.nan
        ),
        "AUC HighRiskProb predicts Failure": auc_failure,
        "Spearman HighRiskProb vs Promotion_Active": rho_active,
        "Mean Promotion Active": float(valid["Promotion_Active"].mean()),
        "P10 Promotion Active": float(valid["Promotion_Active"].quantile(.10)),
    }])

    state_rows = []
    for state, g in valid.groupby("MostLikelyRiskState", dropna=False):
        state_rows.append({
            "RiskState": state,
            "N": int(len(g)),
            "Failures": int(g["Failure"].sum()),
            "FailureRate": float(g["Failure"].mean()),
            "MeanPromotionActive": float(g["Promotion_Active"].mean()),
            "MedianPromotionActive": float(g["Promotion_Active"].median()),
            "MedianHighRiskProb": float(g["HighRiskProb"].median()),
        })
    state_summary = pd.DataFrame(state_rows)

    events = events.sort_values("HighRiskProb", ascending=False).reset_index(drop=True)

    audit = pd.DataFrame([{
        "DevelopmentCutoff": cutoff,
        "V345_MaxDate": pd.to_datetime(v345.index.max()) if len(v345) else pd.NaT,
        "Attack75_MaxDate": pd.to_datetime(attack75.index.max()) if len(attack75) else pd.NaT,
        "PromoMask_MaxDate": pd.to_datetime(promo_mask.index.max()) if len(promo_mask) else pd.NaT,
        "WeeklySignal_MaxDate": pd.to_datetime(w["SignalDate"].max()) if len(w) else pd.NaT,
        "WeeklyOutcome_MaxDate": (
            pd.to_datetime(w["OutcomeWeek"].max())
            if len(w) and "OutcomeWeek" in w.columns else pd.NaT
        ),
        "PromotionMonth_Max": (
            str(events["Month"].max()) if len(events) else ""
        ),
        "PromotionMonth_Min": (
            str(events["Month"].min()) if len(events) else ""
        ),
        "PromotionMonths": int(len(events)),
    }])

    # Explicit hard-cutoff status.
    _date_cols = [
        "V345_MaxDate", "Attack75_MaxDate", "PromoMask_MaxDate",
        "WeeklySignal_MaxDate", "WeeklyOutcome_MaxDate",
    ]
    _date_ok = True
    for _c in _date_cols:
        _v = audit.loc[0, _c]
        if pd.notna(_v) and pd.Timestamp(_v) > cutoff:
            _date_ok = False
    _month_ok = (
        True if events.empty
        else events["Month"].max() <= pd.Period("2026-07", freq="M")
    )
    audit["CutoffStatus"] = "PASS" if (_date_ok and _month_ok) else "FAIL"

    return {
        "events": events,
        "summary": summary,
        "state_summary": state_summary,
        "audit": audit,
    }


