def _r15c_aggregate_holdings(row):
    out = {}
    for model, weight in MODEL_WEIGHTS.items():
        h = str(row.get(model, ""))
        if not h:
            continue
        out[h] = out.get(h, 0.0) + float(weight)
    return out


def _r15c_format_alloc(alloc):
    if not alloc:
        return "—"
    return " / ".join(
        f"{k} {v*100:.1f}%"
        for k, v in sorted(alloc.items(), key=lambda kv: (-kv[1], kv[0]))
        if abs(v) > 1e-12
    )


def _r15c_current_v345(asof, px_close, rf):
    """
    Reconstruct only the CURRENT frozen v3.45 state from the same frozen rules.
    No optimization and no research diagnostics.
    """
    needed = [
        "QQQ", "QLD", "LQD", "GLD", "TLT", "SPXL",
        "TQQQ", "TECL", "XLU", "^VIX", "SPY", "XLK",
    ]
    closes = px_close.reindex(columns=needed).copy().ffill()
    idx = pd.DatetimeIndex(closes.index).sort_values()

    core_h = _build_core_holding_matrix(closes, rf).reindex(idx)

    safe2, safe_audit, _ = _safe_haven_multi_selector(closes)
    safe2 = safe2.reindex(idx).ffill()

    adaptive_h = core_h.copy()
    for model in MODEL_WEIGHTS:
        m = adaptive_h[model].eq("GLD")
        adaptive_h.loc[m, model] = safe2.loc[m]

    gates, gate_audit = _v326_bond_regime_signals(closes, idx)
    gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

    brakes, brake_raw = _v329_brake_signals(closes, idx)
    vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
    allow_l2 = gate_a & ~vix_brake

    avix_h = _v326_apply_l2_gate(adaptive_h, allow_l2)

    inflect_eff, inflect_raw = _v332_xlk_inflection_signal(closes, idx)
    inflect_eff = inflect_eff.reindex(idx).fillna(False).astype(bool)
    turbo = (allow_l2 & inflect_eff).reindex(idx).fillna(False).astype(bool)

    choose_tecl, selector_raw = _v335_attack_selector_signal(closes, idx)
    choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

    t1_h = _v332_apply_turbo_l3(avix_h, turbo)

    valid = idx[idx <= pd.Timestamp(asof)]
    if len(valid) == 0:
        raise RuntimeError("v3.45 current signal has no valid date.")
    d = valid[-1]

    ga = bool(gate_a.loc[d])
    vb = bool(vix_brake.loc[d])
    tb = bool(turbo.loc[d])
    tecl = bool(choose_tecl.loc[d])
    promo = bool(tb and tecl)

    safe = str(safe2.loc[d]) if d in safe2.index and pd.notna(safe2.loc[d]) else "—"

    # Exact v3.45 portfolio state.
    if promo:
        mode = "Promotion100"
        alloc = {"TECL": 1.0}
        action = "100% TECL"
    elif tb:
        # T2 = 0.5*TQQQ + 0.5*T1
        t1_alloc = _r15c_aggregate_holdings(t1_h.loc[d])
        alloc = {k: 0.5 * v for k, v in t1_alloc.items()}
        alloc["TQQQ"] = alloc.get("TQQQ", 0.0) + 0.5
        mode = "Turbo 75%"
        action = _r15c_format_alloc(alloc)
    else:
        alloc = _r15c_aggregate_holdings(avix_h.loc[d])
        mode = "Baseline"
        action = _r15c_format_alloc(alloc)

    return {
        "date": d,
        "mode": mode,
        "allocation": alloc,
        "allocation_text": action,
        "safe_haven": safe,
        "gate_a": ga,
        "vix_brake": vb,
        "allow_l2": bool(allow_l2.loc[d]),
        "inflection": bool(inflect_eff.loc[d]),
        "turbo": tb,
        "tecl_leadership": tecl,
        "promotion100": promo,
        "core_row": core_h.loc[d],
        "adaptive_row": adaptive_h.loc[d],
        "avix_row": avix_h.loc[d],
    }



def _r15j_alloc_equal(a, b, tol=1e-9):
    keys = set(a) | set(b)
    return all(abs(float(a.get(k, 0.0)) - float(b.get(k, 0.0))) <= tol for k in keys)


def _r15j_v345_daily_allocations(asof, px_close, rf):
    """Final v3.45 allocation by trading day, display/audit only."""
    needed = [
        "QQQ", "QLD", "LQD", "GLD", "TLT", "SPXL",
        "TQQQ", "TECL", "XLU", "^VIX", "SPY", "XLK",
    ]
    closes = px_close.reindex(columns=needed).copy().ffill()
    idx = pd.DatetimeIndex(closes.index).sort_values()

    core_h = _build_core_holding_matrix(closes, rf).reindex(idx)
    safe2, _, _ = _safe_haven_multi_selector(closes)
    safe2 = safe2.reindex(idx).ffill()

    adaptive_h = core_h.copy()
    for model in MODEL_WEIGHTS:
        m = adaptive_h[model].eq("GLD")
        adaptive_h.loc[m, model] = safe2.loc[m]

    gates, _ = _v326_bond_regime_signals(closes, idx)
    gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

    brakes, _ = _v329_brake_signals(closes, idx)
    vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
    allow_l2 = gate_a & ~vix_brake

    avix_h = _v326_apply_l2_gate(adaptive_h, allow_l2)

    inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
    inflect_eff = inflect_eff.reindex(idx).fillna(False).astype(bool)
    turbo = (allow_l2 & inflect_eff).reindex(idx).fillna(False).astype(bool)

    choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
    choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)
    t1_h = _v332_apply_turbo_l3(avix_h, turbo)
    promo = (turbo & choose_tecl).fillna(False)

    rows = []
    for d in idx:
        if d > pd.Timestamp(asof):
            continue
        if bool(promo.loc[d]):
            alloc = {"TECL": 1.0}
            mode = "Promotion100"
        elif bool(turbo.loc[d]):
            t1_alloc = _r15c_aggregate_holdings(t1_h.loc[d])
            alloc = {k: 0.5 * v for k, v in t1_alloc.items()}
            alloc["TQQQ"] = alloc.get("TQQQ", 0.0) + 0.5
            mode = "Turbo 75%"
        else:
            alloc = _r15c_aggregate_holdings(avix_h.loc[d])
            mode = "Baseline"

        # clean zero weights
        alloc = {k: float(v) for k, v in alloc.items() if abs(float(v)) > 1e-12}
        rows.append({
            "Date": pd.Timestamp(d),
            "Allocation": alloc,
            "Mode": mode,
            "GateA": bool(gate_a.loc[d]),
            "VIXBrake": bool(vix_brake.loc[d]),
            "AllowL2": bool(allow_l2.loc[d]),
            "Inflection": bool(inflect_eff.loc[d]),
            "Turbo": bool(turbo.loc[d]),
            "TECLLeadership": bool(choose_tecl.loc[d]),
            "Promotion100": bool(promo.loc[d]),
        })
    return pd.DataFrame(rows)


def _r15j_v345_operational_state(asof, px_close, rf):
    hist = _r15j_v345_daily_allocations(asof, px_close, rf)
    if hist.empty:
        raise RuntimeError("v3.45 allocation history unavailable.")

    cur = hist.iloc[-1]
    prev = hist.iloc[-2] if len(hist) >= 2 else None

    changed = False
    if prev is not None:
        changed = not _r15j_alloc_equal(cur["Allocation"], prev["Allocation"])

    today = pd.Timestamp(asof).normalize()
    data_date = pd.Timestamp(cur["Date"]).normalize()
    due_today = bool(changed and data_date == today)

    # Next check dates: display concrete dates in Japan Standard Time.
    # VIX30 can change at the next US session.
    daily_anchor = max(today + pd.Timedelta(days=1), data_date + pd.Timedelta(days=1))
    daily_next = _r15ab_next_us_trading_day_on_or_after(daily_anchor)

    # Weekly MR next weekly cycle.
    days_to_friday = (4 - today.weekday()) % 7
    coming_friday = today + pd.Timedelta(days=days_to_friday)
    if today.weekday() >= 5:
        coming_friday = today + pd.Timedelta(days=(11 - today.weekday()))
    weekly_anchor = coming_friday + pd.Timedelta(days=1)
    weekly_next = _r15ab_next_us_trading_day_on_or_after(weekly_anchor)

    # Safe Haven / TLT3M / Inflection / XLK6M-vs-QQQ6M refresh
    # on the next monthly execution date.
    next_month = (today + pd.offsets.MonthBegin(1)).normalize()
    monthly_next = _r15ab_next_us_trading_day_on_or_after(next_month)

    return {
        "hist": hist,
        "current": cur,
        "previous": prev,
        "changed": changed,
        "due_today": due_today,
        "data_date": data_date,
        "daily_next": f"次の取引日 ｜ {_r15ab_fmt_jst_date(daily_next)}",
        "weekly_next": f"次週の初営業日 ｜ {_r15ab_fmt_jst_date(weekly_next)}",
        "monthly_next": f"{next_month:%Y-%m} 初営業日 ｜ {_r15ab_fmt_jst_date(monthly_next)}",
    }



@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def _r15k_build_v345_live_inputs(px_close, rf_bt, start, end):
    """
    Live/operations v3.45 reconstruction.
    IMPORTANT: unlike the research DD builder, this has NO 2026-07 cutoff.
    Frozen rules are identical; only the research cutoff is removed.
    """
    needed = [
        "QQQ", "QLD", "TQQQ", "LQD", "GLD", "TLT",
        "SPXL", "TECL", "XLU", "^VIX", "SPY", "XLK",
    ]

    closes = px_close.reindex(
        columns=[c for c in needed if c in px_close.columns]
    ).copy()
    missing = [x for x in needed if x not in closes.columns]
    if missing:
        closes = closes.join(
            get_close(tuple(missing), start, end),
            how="outer",
        ).sort_index().ffill()

    opens = get_open(tuple(needed), start, end)
    idx = pd.DatetimeIndex(
        closes.index.intersection(opens.index)
    ).sort_values()

    closes = closes.reindex(idx).ffill()
    opens = opens.reindex(idx).ffill()
    asset_ret = opens.pct_change(fill_method=None)

    core_h = _build_core_holding_matrix(closes, rf_bt).reindex(idx)

    safe2, _, _ = _safe_haven_multi_selector(closes)
    safe2 = safe2.reindex(idx).ffill()

    adaptive_h = core_h.copy()
    for model in MODEL_WEIGHTS:
        mask = adaptive_h[model].eq("GLD")
        adaptive_h.loc[mask, model] = safe2.loc[mask]

    gates, _ = _v326_bond_regime_signals(closes, idx)
    gate_a = gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)

    brakes, _ = _v329_brake_signals(closes, idx)
    vix_brake = brakes["V VIX30"].reindex(idx).fillna(False)
    allow_l2 = gate_a & ~vix_brake

    avix_h = _v326_apply_l2_gate(adaptive_h, allow_l2)

    inflect_eff, _ = _v332_xlk_inflection_signal(closes, idx)
    inflect_eff = inflect_eff.reindex(idx).fillna(False).astype(bool)
    turbo = (allow_l2 & inflect_eff).reindex(idx).fillna(False).astype(bool)

    choose_tecl, _ = _v335_attack_selector_signal(closes, idx)
    choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

    t1_h = _v332_apply_turbo_l3(avix_h, turbo)
    avix_ret = _portfolio_return_from_holdings_fast(avix_h, asset_ret)
    t1_ret = _portfolio_return_from_holdings_fast(t1_h, asset_ret)

    _, attack = _v335_build_t2_and_attack_returns(
        avix_ret,
        t1_ret,
        asset_ret["TQQQ"],
        asset_ret["TECL"],
        turbo,
        choose_tecl,
    )

    promo = (turbo & choose_tecl).reindex(idx).fillna(False)
    v345 = attack.copy()
    v345.loc[promo] = asset_ret["TECL"].reindex(idx).loc[promo]

    return (
        closes.copy(),
        v345.dropna().copy(),
        attack.dropna().copy(),
        promo.astype(bool).copy(),
    )


def _r15j_v345_monthly_return_panel(px, rf_rates, asof):
    """v3.45 version of Frozen Core's live monthly return panel."""
    try:
        start = pd.Timestamp(px.index.min()).strftime("%Y-%m-%d")
        end = (pd.Timestamp(asof) + pd.Timedelta(days=10)).strftime("%Y-%m-%d")
        _, v345, _, _ = _r15k_build_v345_live_inputs(px, rf_rates, start, end)

        # SPY open-to-open to match v3.45 execution convention.
        needed = [
            "QQQ","QLD","LQD","GLD","TLT","SPXL",
            "TQQQ","TECL","XLU","^VIX","SPY","XLK",
        ]
        opens = get_open(tuple(needed), start, end)
        spy = opens["SPY"].pct_change(fill_method=None)

        # Frozen Core on the same Open→Open convention.
        _, core_ret, _, _, _ = _r15o_build_core_open_live(
            px, rf_rates, start, end
        )

        daily = pd.concat(
            [
                pd.Series(v345).rename("Frozen v3.45"),
                pd.Series(core_ret).rename("Frozen Core"),
                spy.rename("SPY"),
            ],
            axis=1,
        ).dropna(how="all")
    except Exception as e:
        st.warning("v3.45の月次リターンを計算できませんでした。")
        st.caption(str(e))
        return

    if daily.empty:
        st.info("月次リターンを計算できる履歴が不足しています。")
        return

    periods = daily.index.to_period("M")
    monthly = (1.0 + daily).groupby(periods).prod(min_count=1).sub(1.0)
    monthly.index = monthly.index.astype(str)

    latest_px_date = pd.Timestamp(daily.index.max()).normalize()
    current_period = pd.Timestamp(asof).to_period("M")
    latest_period = pd.Period(monthly.index[-1], freq="M")
    latest_is_partial = latest_period == current_period

    y = latest_px_date.year
    y_rows = monthly[pd.PeriodIndex(monthly.index, freq="M").year == y]
    ytd = (1.0 + y_rows["Frozen v3.45"].dropna()).prod() - 1.0

    st.markdown("## 月次リターン")
    st.caption(
        f"Frozen v3.45 自前計算 ｜ Open→Open ｜ 最新価格 {latest_px_date:%Y-%m-%d}"
    )

    last = monthly.iloc[-1]
    last_label = monthly.index[-1]
    prev = monthly.iloc[-2] if len(monthly) >= 2 else None
    prev_label = monthly.index[-2] if len(monthly) >= 2 else None

    _r15ag_kpi_grid([
        (
            f"最新 {last_label}{' MTD*' if latest_is_partial else ''}",
            "—" if pd.isna(last["Frozen v3.45"]) else f"{float(last['Frozen v3.45'])*100:+.2f}%"
        ),
        (
            f"前月 {prev_label}" if prev is not None else "前月",
            "—" if prev is None or pd.isna(prev["Frozen v3.45"]) else f"{float(prev['Frozen v3.45'])*100:+.2f}%"
        ),
        (f"{y} YTD*", f"{ytd*100:+.2f}%"),
    ])

    if latest_is_partial:
        st.caption("* MTD / YTD は最新取得価格までの暫定値。")

    st.markdown("### 直近12か月")
    recent = monthly.tail(12).iloc[::-1]
    rows = []
    for month, r in recent.iterrows():
        is_partial = pd.Period(month, freq="M") == current_period
        mark = " MTD" if is_partial else ""

        v_raw = r.get("Frozen v3.45", np.nan)
        c_raw = r.get("Frozen Core", np.nan)
        spy_raw = r.get("SPY", np.nan)

        v = float(v_raw)*100 if pd.notna(v_raw) else np.nan
        c = float(c_raw)*100 if pd.notna(c_raw) else np.nan
        spy_v = float(spy_raw)*100 if pd.notna(spy_raw) else np.nan
        edge = v-spy_v if np.isfinite(v) and np.isfinite(spy_v) else np.nan

        v_txt = "—" if not np.isfinite(v) else f"{v:+.2f}%"
        spy_txt = "—" if not np.isfinite(spy_v) else f"{spy_v:+.2f}%"
        edge_txt = "—" if not np.isfinite(edge) else f"{edge:+.2f}pt"

        # Different realized return implies the strategies were not identical
        # over that month. Use a subtle red card; same months stay neutral.
        differs = np.isfinite(v) and np.isfinite(c) and abs(v-c) > 0.005
        row_style = (
            "background:#fff1f2;border:1.5px solid #fb7185;"
            if differs else ""
        )
        diff_badge = (
            '<span style="font-size:.72rem;font-weight:700;color:#be123c;'
            'background:#ffe4e6;border-radius:999px;padding:.12rem .42rem;">'
            'Coreと異なる</span>'
            if differs else
            '<span style="font-size:.72rem;color:#15803d;">Coreと同じ</span>'
        )

        rows.append(
            f"""
            <div class="fc-return-row" style="{row_style}">
              <div class="fc-return-month">{month}{mark}<br>{diff_badge}</div>
              <div class="fc-return-cell">
                <span class="fc-return-label">Frozen v3.45</span>
                <b>{v_txt}</b>
              </div>
              <div class="fc-return-cell">
                <span class="fc-return-label">SPY</span>
                <b>{spy_txt}</b>
              </div>
              <div class="fc-return-edge">{edge_txt}</div>
            </div>
            """
        )
    st.markdown("".join(rows), unsafe_allow_html=True)




# ============================================================
# R15AE — Dashboard G1 / G2 / P health dots
# Thresholds reproduce the reference dashboard color functions.
# ============================================================

_R15AE_GOOD = "#22c55e"
_R15AE_CAUTION = "#eab308"
_R15AE_WARNING = "#f97316"
_R15AE_NEUTRAL = "#9ca3af"


def _r15ae_deterioration_label(p6, p12, p24):
    vals = (p6, p12, p24)
    if any(v is None or not np.isfinite(v) for v in vals):
        return "INSUFFICIENT_DATA"

    # Reference classification order.
    if p12 >= 0.80 and p24 >= 0.80:
        return "DETERIORATING"
    if p6 >= 0.85 and p12 < 0.70 and p24 < 0.70:
        return "EARLY_WARNING"
    if p12 < 0.70 and p24 < 0.70:
        return "GOOD"
    if p12 >= 0.70 and p24 < 0.80:
        return "WATCH"
    return "MIXED"


def _r15ae_g1_color(slope):
    if slope is None or not np.isfinite(slope):
        return _R15AE_NEUTRAL
    if slope < -0.0002:
        return _R15AE_WARNING
    if slope < 0:
        return _R15AE_CAUTION
    return _R15AE_GOOD


def _r15ae_g2_color(p_erosion):
    if p_erosion is None or not np.isfinite(p_erosion):
        return _R15AE_NEUTRAL
    if p_erosion >= 0.80:
        return _R15AE_WARNING
    if p_erosion >= 0.70:
        return _R15AE_CAUTION
    return _R15AE_GOOD


def _r15ae_p_color(label):
    if label in ("GOOD", "EARLY_WARNING"):
        return _R15AE_GOOD
    if label in ("WATCH", "MIXED"):
        return _R15AE_CAUTION
    if label == "DETERIORATING":
        return _R15AE_WARNING
    return _R15AE_NEUTRAL


def _r15ae_g1_slope_12(monthly_return):
    """
    Reconstruct g1_slope_12 from the definition:
    time slope of the long-period average monthly return.

    We build the same long-period mean used by the erosion monitor at
    successive monthly endpoints, then take the linear slope across
    the latest 12 available long-mean observations.
    """
    r = pd.Series(monthly_return).dropna().astype(float)
    long_means = []

    # Need enough history for the fixed 84M anchor + 12M warm-up.
    for n in range(96, len(r) + 1):
        e = _p_erosion(r.iloc[:n], 12)
        if e is not None and np.isfinite(e["current_long_mean"]):
            long_means.append(float(e["current_long_mean"]))

    if len(long_means) < 12:
        return np.nan

    y = np.asarray(long_means[-12:], dtype=float)
    x = np.arange(12, dtype=float)
    return float(np.polyfit(x, y, 1)[0])


def _r15ae_health_snapshot_from_series(monthly_return):
    r = pd.Series(monthly_return).dropna().astype(float)
    if len(r) < 96:
        return {
            "g1": np.nan, "g2": np.nan, "label": "INSUFFICIENT_DATA",
            "g1_color": _R15AE_NEUTRAL,
            "g2_color": _R15AE_NEUTRAL,
            "p_color": _R15AE_NEUTRAL,
        }

    d6 = _p_deterioration(r, 6)
    d12 = _p_deterioration(r, 12)
    d24 = _p_deterioration(r, 24)
    e12 = _p_erosion(r, 12)

    p6 = d6["pdet"] if d6 else np.nan
    p12 = d12["pdet"] if d12 else np.nan
    p24 = d24["pdet"] if d24 else np.nan
    g2 = e12["perosion"] if e12 else np.nan
    g1 = _r15ae_g1_slope_12(r)

    label = _r15ae_deterioration_label(p6, p12, p24)

    return {
        "g1": g1,
        "g2": g2,
        "label": label,
        "g1_color": _r15ae_g1_color(g1),
        "g2_color": _r15ae_g2_color(g2),
        "p_color": _r15ae_p_color(label),
    }


@st.cache_data(ttl=86400, show_spinner=False)
def _r15ae_main_health_snapshots(asof_key):
    """
    One cached full-history reconstruction supplies health dots for
    Frozen Core, Frozen v3.45, and all three frozen 4F variants using identical definitions.
    """
    asof = pd.Timestamp(asof_key)
    start = "2009-01-01"
    end = (asof + pd.Timedelta(days=10)).strftime("%Y-%m-%d")
    monthly = _r15d_main_performance(start, end).copy()

    cur = asof.to_period("M")
    if len(monthly) and monthly.index[-1] == cur:
        monthly = monthly.iloc[:-1].copy()

    out = {}
    for name in (
        "Frozen Core", "Frozen v3.45", "Frozen 4F",
        "4F Attack75", "4F Promotion100",
    ):
        out[name] = _r15ae_health_snapshot_from_series(
            monthly[name].dropna()
        )
    return out


def _r15ae_status_items(strategy_name, asof):
    try:
        h = _r15ae_main_health_snapshots(str(pd.Timestamp(asof).date()))[strategy_name]
        return [
            ("G1", True, h["g1_color"]),
            ("G2", True, h["g2_color"]),
            ("P", True, h["p_color"]),
        ], h
    except Exception:
        return [
            ("G1", None, _R15AE_NEUTRAL),
            ("G2", None, _R15AE_NEUTRAL),
            ("P", None, _R15AE_NEUTRAL),
        ], {
            "g1": np.nan, "g2": np.nan, "label": "INSUFFICIENT_DATA"
        }


def _r15p_norm_alloc(a, tol=1e-6):
    out = {}
    for k, v in dict(a).items():
        try:
            fv = float(v)
        except Exception:
            continue
        if np.isfinite(fv) and abs(fv) > tol:
            out[str(k)] = fv
    total = sum(out.values())
    if total > 0:
        out = {k: v/total for k, v in out.items()}
    return out

def _r15p_alloc_same(a, b, tol=5e-4):
    aa, bb = _r15p_norm_alloc(a), _r15p_norm_alloc(b)
    keys = set(aa) | set(bb)
    return all(abs(aa.get(k,0.0)-bb.get(k,0.0)) <= tol for k in keys)

def _r15p_signal_compare_banner(core_alloc, v345_alloc, title="Frozen Core ↔ v3.45"):
    same = _r15p_alloc_same(core_alloc, v345_alloc)
    if same:
        st.success(f"🟢 {title}：現在のシグナルは同じ")
    else:
        st.error(f"🔴 {title}：現在のシグナルが異なります")
        st.caption(
            f"Frozen Core：{_r15c_format_alloc(core_alloc)} ｜ "
            f"v3.45：{_r15c_format_alloc(v345_alloc)}"
        )
    return same


