def _r15d_r235_r195_candidates():
    import io as _r195_io, zipfile as _r195_zip, json as _r195_json, base64 as _r195_b64, zlib as _r195_zlib, gzip as _r195_gzip, hashlib as _r195_hash
    BUILD="R195-L1-ACTIVE-REGISTRY-FINAL-ROBUSTNESS-GATE-PATCH2-v1.0"
    DEV=pd.Timestamp("2026-07-31")
    CUTOFF=pd.Period("2026-07",freq="M")
    class _R216NullStatus:
        def write(self,*args,**kwargs): pass
    status=_R216NullStatus()

    # ---------- pinned predecessor / official artifact identities ----------
    _R193_ZIP_B64=""
    _R194_ZIP_B64=""
    _R193_SHA="fe02a812b791b4a79a4dbb4e1c8670ff88702991f8956fe776af16528ccb15ba"
    _R194_SHA="a59d25ce1203abe7c22423473ae531b4e2fc1c150eaaab2d50d7bc683ab72758"
    _B_BY=""
    _B_SU=""
    _B_GE=""
    _B_GEM=""

    def _raw_csv(blob):
        return _r195_zlib.decompress(_r195_b64.b64decode(blob))
    def _csv_blob(blob):
        return pd.read_csv(_r195_io.BytesIO(_raw_csv(blob)))
    def _month_compound(s):
        s=pd.Series(s).dropna().astype(float)
        if not len(s): return pd.Series(dtype=float)
        return (1+s).groupby(pd.DatetimeIndex(s.index).to_period("M")).prod(min_count=1)-1
    def _perf(r):
        r=pd.Series(r).dropna().astype(float)
        if len(r)<2:return {"N":len(r),"CAGR":np.nan,"Sharpe":np.nan,"MaxDD":np.nan,"Calmar":np.nan}
        nav=(1+r).cumprod(); yrs=len(r)/12.0
        c=float(nav.iloc[-1]**(1/yrs)-1) if nav.iloc[-1]>0 else np.nan
        sd=float(r.std(ddof=1)); sh=float(r.mean()/sd*np.sqrt(12)) if sd>0 else np.nan
        dd=float((nav/nav.cummax()-1).min()); cal=c/abs(dd) if dd<0 else np.nan
        return {"N":len(r),"CAGR":c,"Sharpe":sh,"MaxDD":dd,"Calmar":cal}
    def _beta_resid(s,b,fit=None):
        z=pd.concat([pd.Series(s).rename('s'),pd.Series(b).rename('b')],axis=1).dropna()
        if fit is not None: zfit=z.loc[:fit]
        else: zfit=z
        vb=float(zfit['b'].var(ddof=1))
        beta=float(zfit['s'].cov(zfit['b'])/vb) if vb>0 else np.nan
        resid=z['s']-beta*z['b']
        return beta,resid
    def _resid_cagr(r):
        r=pd.Series(r).dropna().astype(float)
        if len(r)<2:return np.nan
        w=float((1+r).prod()); yrs=len(r)/12
        return float(w**(1/yrs)-1) if w>0 else np.nan

    status.write("青龍4候補をofficial frozen monthly artifactsから復元中…")
    # PATCH2: Do not re-estimate completed Seiryu objects from refreshed market data.
    # R108 comes from the official R189 monthly artifact inherited by R190.
    # Balanced / QLD / TQQQ come from R113's immutable official-parent championship panel.
    _R189_MONTHLY_B64=''
    _R189_MONTHLY_SHA="890ef59e0cfe5cddb94ba7bedc1845c0d41ac9a36d6abcf216b654d1c967a085"
    _R113_PANEL_B64=''
    _R113_PANEL_SHA="3e6f7e9b09483626665a225bef0d5442b81e473fe82a6c36a79368fc2053988a"
    _r189_raw=_r195_zlib.decompress(_r195_b64.b64decode(_R189_MONTHLY_B64))
    _r113_raw=_r195_gzip.decompress(_r195_b64.b64decode(_R113_PANEL_B64))
    _r189_sha_obs=_r195_hash.sha256(_r189_raw).hexdigest()
    _r113_sha_obs=_r195_hash.sha256(_r113_raw).hexdigest()
    _r189=pd.read_csv(_r195_io.BytesIO(_r189_raw))
    _r189['Month']=pd.PeriodIndex(_r189['Month'].astype(str),freq='M'); _r189=_r189.set_index('Month').sort_index()
    _r113=pd.read_csv(_r195_io.BytesIO(_r113_raw))
    _r113['Date']=pd.PeriodIndex(_r113['Date'].astype(str),freq='M'); _r113=_r113.set_index('Date').sort_index()
    se_month=pd.DataFrame(index=_r189.index.union(_r113.index).sort_values())
    se_month['Seiryu Full5P-ASH']=_r189['Seiryu / MOM — R108'].astype(float)
    se_month['Seiryu Full5P-Balanced']=_r113['Full5P_QQQQLD50_GLD'].astype(float)
    se_month['Seiryu Full5P-QLD']=_r113['Full5P_QLD_GLD'].astype(float)
    se_month['Seiryu Full5P-TQQQ']=_r113['Full5P_TQQQ_GLD'].astype(float)
    se_month=se_month.loc[:CUTOFF]

    status.write("白虎 official frozen seriesを読込中…")
    by=_csv_blob(_B_BY); by['Date']=pd.to_datetime(by['Date']); by=by.set_index('Date')
    by_month=pd.DataFrame({
        'Byakko FrozenVIX':_month_compound(by['GLD_control']),
        'Byakko FrozenVIX-GLD/XLU126':_month_compound(by['R138_GLD_XLU_6M']),
    })
    raw193=_r195_b64.b64decode(_R193_ZIP_B64)
    with _r195_zip.ZipFile(_r195_io.BytesIO(raw193)) as zf:
        ex193=pd.read_csv(zf.open('01_exactness.csv'))
        m193=pd.read_csv(zf.open('06_monthly_returns.csv'))
        try:
            globals()['_R193_QUARTERLY_SIGNAL_CACHE']=pd.read_csv(zf.open('04_quarterly_signal_audit.csv'))
        except Exception:
            pass
    m193['Month']=pd.to_datetime(m193['Month']).dt.to_period('M'); m193=m193.set_index('Month')
    by_month['Byakko Equal2P-47D/20M']=m193['Equal2P GLD Control']
    by_month['Byakko Equal2P-GLD/XLU126']=m193['Equal2P GLD/XLU-126D Challenger']

    status.write("朱雀 official R147 seriesを読込中…")
    su=_csv_blob(_B_SU); su['Date']=pd.to_datetime(su['Date']); su=su.set_index('Date')
    su30=2.0*su['2P_3M30M_EW'].astype(float)-su['1P_3M'].astype(float)
    su_month=pd.DataFrame({
        'Suzaku TEL-3M':_month_compound(su['1P_3M']),
        'Suzaku TEL-30M':_month_compound(su30),
        'Suzaku TEL-3M/30M':_month_compound(su['2P_3M30M_EW']),
    })

    status.write("玄武 official signalsからTriEWを再構築中…")
    ge=_csv_blob(_B_GE); ge['Date']=pd.to_datetime(ge['Date']); ge=ge.set_index('Date')
    gem=_csv_blob(_B_GEM); gem['TradeDate']=pd.to_datetime(gem['TradeDate']); gem=gem.set_index('TradeDate')
    globals()['_R235_GENBU_SIGNAL_CACHE']=gem.reset_index().copy()
    gx=get_close(('TQQQ','XLU'),'2009-01-01','2026-08-10').sort_index().loc[:DEV]
    gar=gx[['TQQQ','XLU']].pct_change(fill_method=None); gidx=pd.DatetimeIndex(gx.index)
    def _target_return(target,name):
        h=target.reindex(gidx).ffill().shift(1); r=pd.Series(index=gidx,dtype=float,name=name)
        r.loc[h.eq('TQQQ')]=gar.loc[h.eq('TQQQ'),'TQQQ']; r.loc[h.eq('XLU')]=gar.loc[h.eq('XLU'),'XLU']; return r
    indiv=[]
    for lab,col in [('6D','6D_RiskOff'),('11M','11M_RiskOff'),('24M','24M_RiskOff')]:
        t=pd.Series(np.where(gem[col].astype(int).eq(1),'XLU','TQQQ'),index=gem.index)
        indiv.append(_target_return(t,'Genbu '+lab))
    tri=pd.concat(indiv,axis=1).mean(axis=1,skipna=True).where(pd.concat(indiv,axis=1).notna().sum(axis=1)>=3).rename('Genbu MR-TriEW-6D/11M/24M')
    ge_month=pd.DataFrame({
        'Genbu MR-24M':_month_compound(ge['Control_24M_RAW']),
        'Genbu MR-TriEW-6D/11M/24M':_month_compound(tri),
        'Genbu MR-Majority-6D/11M/24M':_month_compound(ge['Genbu_Majority']),
    })

    expected=[
        'Seiryu Full5P-ASH','Seiryu Full5P-Balanced','Seiryu Full5P-QLD','Seiryu Full5P-TQQQ',
        'Byakko FrozenVIX','Byakko Equal2P-47D/20M','Byakko FrozenVIX-GLD/XLU126','Byakko Equal2P-GLD/XLU126',
        'Suzaku TEL-3M','Suzaku TEL-30M','Suzaku TEL-3M/30M',
        'Genbu MR-24M','Genbu MR-TriEW-6D/11M/24M','Genbu MR-Majority-6D/11M/24M']
    cand=pd.concat([se_month,by_month,su_month,ge_month],axis=1).sort_index().loc[:CUTOFF]
    cand=cand.reindex(columns=expected)
    registry=list(cand.columns)
    return cand, registry, _R193_SHA, _R194_SHA

@st.cache_data(show_spinner=False, ttl=86400)
def _r15d_four_gods_family_monthly():
    """Frozen Four Gods Layer-0/1 family series for Performance.

    Display-only.  The four parent series are the frozen KIRIN representative
    families; child columns preserve the complete R235/R195 candidate registry.
    No research rule is changed.
    """
    cand, _, _, _ = _r15d_r235_r195_candidates()
    out = cand.copy().astype(float)
    parents = {
        "Four Gods — Seiryu": "Seiryu Full5P-Balanced",
        "Four Gods — Byakko": "Byakko FrozenVIX",
        "Four Gods — Suzaku": "Suzaku TEL-3M/30M",
        "Four Gods — Genbu": "Genbu MR-Majority-6D/11M/24M",
    }
    for parent, child in parents.items():
        out[parent] = out[child]
    parent_cols = list(parents)
    child_cols = [c for c in cand.columns]
    return out[parent_cols + child_cols]

def _r15d_erc_weights(cov):
    """R237 PATCH1 ERC solver, unchanged."""
    import numpy as _np
    from scipy.optimize import minimize as _minimize
    S=_np.asarray(cov,dtype=float)
    n=S.shape[0]
    if S.shape!=(n,n) or n<2 or not _np.isfinite(S).all():
        raise ValueError("ERC covariance is invalid")
    S=(S+S.T)/2.0
    scale=float(_np.trace(S)/n) if n else 1.0
    ridge=max(abs(scale)*1e-12,1e-16)
    S=S+_np.eye(n)*ridge
    sscale=max(float(_np.mean(_np.diag(S))),1e-18)
    A=S/sscale
    b=_np.full(n,1.0/n,dtype=float)
    vol=_np.sqrt(_np.maximum(_np.diag(A),1e-18))
    x0=1.0/vol
    q=float(x0@A@x0)
    if _np.isfinite(q) and q>0:
        x0=x0/_np.sqrt(q)
    def _obj(x):
        if _np.any(x<=0) or not _np.isfinite(x).all():
            return 1e100
        return float(0.5*(x@A@x)-_np.sum(b*_np.log(x)))
    def _jac(x):
        return A@x-b/x
    res=_minimize(_obj,x0,jac=_jac,method="L-BFGS-B",
                  bounds=[(1e-12,None)]*n,
                  options={"ftol":1e-15,"gtol":1e-12,"maxiter":10000,"maxls":100})
    if (not res.success) or (not _np.isfinite(res.x).all()):
        raise RuntimeError(f"ERC solver failed: {getattr(res,'message','unknown')}")
    w=_np.asarray(res.x,dtype=float); w=w/w.sum()
    pvar=float(w@A@w); rc=w*(A@w); target=pvar/n
    rel=float(_np.max(_np.abs(rc-target))/pvar) if pvar>0 else _np.inf
    if not _np.isfinite(rel):
        raise RuntimeError("ERC solver produced non-finite RC error")
    return w,rel

