@st.cache_data(show_spinner=False, ttl=86400)
def _r15d_r276_hybrid_max_monthly():
    """Rebuild the frozen R276 PATCH1 hybrid back to its maximum valid history.

    Display-only extension for the Performance page.  The strategy rules are
    unchanged from official R276 PATCH1:
      * ERC6 uses six completed representative months.
      * Frozen R181 A-state has absolute priority and forces Genbu 100%.
      * Outside A-state, the frozen R6 month-entry Turbo/Selector may allocate
        75% to TECL/TQQQ; the residual 25% preserves ERC6 relative weights
        across Byakko/Suzaku/Genbu.

    The earliest possible month is therefore the first valid ERC6 month,
    2014-08.  Attack75 inputs are already available by then.  A hard parity
    check against the official R276 PATCH1 2016-02..2026-07 series prevents
    display-only reconstruction drift.
    """
    # Canonical Layer1/A-state lineage and frozen representative families.
    l1 = _r15d_layer1_research_monthly().copy()
    if not isinstance(l1.index, pd.PeriodIndex):
        l1.index = pd.to_datetime(l1.index).to_period("M")
    l1 = l1.sort_index()
    a_state = (
        l1["Layer1 New-R181"].astype(float)
        .sub(l1["Layer1 New-R180"].astype(float))
        .abs() > 1e-12
    )

    cand, _, _, _ = _r15d_r235_r195_candidates()
    canonical = {n: f"{f} {n}" for f, n, _ in _R15D_R235_REGISTRY}
    reps_map = {
        "Seiryu": "Full5P-Balanced",
        "Byakko": "FrozenVIX",
        "Suzaku": "TEL-3M/30M",
        "Genbu": "MR-Majority-6D/11M/24M",
    }
    rep_cols = {fam: canonical[name] for fam, name in reps_map.items()}
    missing = [col for col in rep_cols.values() if col not in cand.columns]
    if missing:
        raise RuntimeError(f"R276 max-history representatives unresolved: {missing}")
    reps = pd.DataFrame({fam: pd.Series(cand[col]).astype(float) for fam, col in rep_cols.items()})
    if not isinstance(reps.index, pd.PeriodIndex):
        reps.index = pd.to_datetime(reps.index).to_period("M")
    reps = reps.sort_index().dropna(how="any")
    reps = reps.loc[reps.index.intersection(l1.index)]
    spear = ["Seiryu", "Byakko", "Suzaku"]

    # Reconstruct ERC6 weights for every valid month, not just the old common
    # comparison window.  Six completed months are required.
    wrows = []
    for i in range(6, len(reps)):
        month = reps.index[i]
        hist = reps.iloc[i-6:i]
        if len(hist) != 6 or hist.index.max() != month - 1:
            continue
        w, err = _r15d_erc_weights(hist[spear].cov().to_numpy())
        if not np.isfinite(err) or err > 1e-7:
            raise RuntimeError(f"R276 max-history ERC6 solver failed at {month}: {err}")
        ww = pd.Series({
            "Seiryu": 0.75 * float(w[0]),
            "Byakko": 0.75 * float(w[1]),
            "Suzaku": 0.75 * float(w[2]),
            "Genbu": 0.25,
        }, dtype=float)
        ast = bool(a_state.reindex([month]).fillna(False).iloc[0])
        if ast:
            ww[:] = 0.0
            ww["Genbu"] = 1.0
        wrows.append({"Month": month, "AState": ast, **{f"W_{k}": float(v) for k, v in ww.items()}})
    weights = pd.DataFrame(wrows).set_index("Month").sort_index()

    # Frozen R6 month-entry Attack75 state.  Keep a long warm-up exactly as in
    # R276 PATCH1 so no signal lookback is shortened for the display extension.
    rstart = "2009-01-01"
    rend = "2026-08-10"
    needed = ["QQQ", "QLD", "LQD", "GLD", "TLT", "SPXL", "TQQQ", "TECL",
              "XLU", "^VIX", "SPY", "XLK", "TMF", "TMV"]
    px = get_close(needed, rstart, rend)
    rf = get_self_backtest_rf(rstart, rend)
    suite = _r15t_build_4f_suite_live_inputs(px, rf, rstart, rend)
    states = suite["states"].copy()
    states["Month"] = states.index.to_period("M")
    ms = states.groupby("Month")[["Turbo", "Choose TECL"]].first().astype(bool)

    opens = get_open(("TQQQ", "TECL"), rstart, rend).sort_index().ffill()
    aret = opens.pct_change(fill_method=None)
    am = ((1.0 + aret).groupby(aret.index.to_period("M")).prod(min_count=1) - 1.0)

    # The hybrid can start only where ERC6 weights, representative returns,
    # month-entry state and both attack assets are all observable.
    valid = weights.index.intersection(reps.index).intersection(ms.index).intersection(am.dropna().index)
    valid = valid[valid <= pd.Period("2026-07", "M")]
    rows = []
    for month in valid:
        ww = weights.loc[month]
        ast = bool(ww["AState"])
        rr = reps.loc[month].astype(float)
        base_w = pd.Series({k.replace("W_", ""): float(ww[k]) for k in ["W_Seiryu", "W_Byakko", "W_Suzaku", "W_Genbu"]})
        ret = float((base_w * rr[base_w.index]).sum())
        if (not ast) and bool(ms.loc[month, "Turbo"]):
            asset = "TECL" if bool(ms.loc[month, "Choose TECL"]) else "TQQQ"
            raw = pd.Series({
                "Byakko": float(ww["W_Byakko"]),
                "Suzaku": float(ww["W_Suzaku"]),
                "Genbu": float(ww["W_Genbu"]),
            })
            denom = float(raw.sum())
            if not np.isfinite(denom) or denom <= 1e-12:
                raise RuntimeError(f"R276 max-history residual weights invalid at {month}: {denom}")
            rw = raw / denom
            residual = float((rw * rr[rw.index]).sum())
            ret = 0.75 * float(am.loc[month, asset]) + 0.25 * residual
        rows.append((month, ret))

    out = pd.Series(dict(rows), dtype=float, name="ERC6 + Attack75").sort_index().to_frame()

    # Official-overlap parity and bit-for-bit replacement on the official R276
    # PATCH1 evidence window.
    official = _r15d_r276_hybrid_monthly()
    idx = out.index.intersection(official.index)
    if len(idx) != len(official):
        raise RuntimeError("R276 max-history reconstruction does not cover the full official overlap")
    maxerr = float((out.loc[idx, "ERC6 + Attack75"] - official.loc[idx, "ERC6 + Attack75"]).abs().max())
    if not np.isfinite(maxerr) or maxerr > 5.1e-7:
        raise RuntimeError(f"R276 max-history reconstruction parity failed: {maxerr:.3e}")
    out.loc[idx, "ERC6 + Attack75"] = official.loc[idx, "ERC6 + Attack75"]

    expected = pd.Period("2014-08", "M")
    actual = out["ERC6 + Attack75"].dropna().index.min()
    if actual != expected:
        raise RuntimeError(f"ERC6 + Attack75: unexpected max-history start {actual}, expected {expected}")
    return out


