@st.cache_data(show_spinner=False)
def _r15d_current_layer1_challengers_max_monthly():
    """Rebuild each frozen Layer1 challenger back to its maximum valid history.

    Display-only extension for the Performance page.  The canonical DEV rules are
    unchanged; this function merely uses the already-frozen representative series
    before the common 2016-02 comparison start whenever the rule has enough
    completed history to be evaluated without look-ahead.

    Earliest valid months implied by the frozen constructions:
      R181      : 2014-02 (embedded R201 lineage starts here)
      ERC6      : 2014-08 (6 completed monthly returns needed for ERC)
      R255 Split: 2015-02 (12 completed months needed for prior-12 ranking)
      R259 Gate : 2015-02 (same prior-12 ranking plus prior-12<0 gate)

    A hard overlap parity check against the embedded official 2016-02..2026-07
    return series prevents a display-only reconstruction drift from being shown.
    """
    # Canonical R181 / A-state lineage.
    l1 = _r15d_layer1_research_monthly().copy()
    if not isinstance(l1.index, pd.PeriodIndex):
        l1.index = pd.to_datetime(l1.index).to_period("M")
    l1 = l1.sort_index()
    r181 = l1["Layer1 New-R181"].astype(float).rename("R181")
    a_state = (
        l1["Layer1 New-R181"].astype(float)
        .sub(l1["Layer1 New-R180"].astype(float))
        .abs() > 1e-12
    )

    # Frozen Layer1 representatives.
    cand, _, _, _ = _r15d_r235_r195_candidates()
    canonical = {n: f"{f} {n}" for f, n, _ in _R15D_R235_REGISTRY}
    reps_map = {
        "Seiryu": "Full5P-Balanced",
        "Byakko": "FrozenVIX",
        "Suzaku": "TEL-3M/30M",
        "Genbu": "MR-Majority-6D/11M/24M",
    }
    rep_cols = {fam: canonical[name] for fam, name in reps_map.items()}
    missing = [col for col in rep_cols.values() if col not in cand.columns]
    if missing:
        raise RuntimeError(f"Layer1 max-history representatives unresolved: {missing}")
    reps = pd.DataFrame({fam: pd.Series(cand[col]).astype(float) for fam, col in rep_cols.items()})
    if not isinstance(reps.index, pd.PeriodIndex):
        reps.index = pd.to_datetime(reps.index).to_period("M")
    reps = reps.sort_index().dropna(how="any")
    reps = reps.loc[reps.index.intersection(l1.index)]

    spear = ["Seiryu", "Byakko", "Suzaku"]

    # ERC6: trailing 6 completed monthly returns; 75% ERC Spear + 25% Genbu,
    # with the frozen R181 A-state replacing the whole allocation by Genbu.
    erc_rows = []
    for i in range(6, len(reps)):
        month = reps.index[i]
        hist = reps.iloc[i-6:i]
        if len(hist) != 6 or hist.index.max() != month - 1:
            continue
        w, err = _r15d_erc_weights(hist[spear].cov().to_numpy())
        if not np.isfinite(err) or err > 1e-7:
            raise RuntimeError(f"ERC6 max-history solver parity failed at {month}: {err}")
        ww = pd.Series({
            "Seiryu": 0.75 * float(w[0]),
            "Byakko": 0.75 * float(w[1]),
            "Suzaku": 0.75 * float(w[2]),
            "Genbu": 0.25,
        })
        if bool(a_state.reindex([month]).fillna(False).iloc[0]):
            ww[:] = 0.0
            ww["Genbu"] = 1.0
        erc_rows.append((month, float((ww * reps.loc[month, ww.index]).sum())))
    erc6 = pd.Series(dict(erc_rows), dtype=float, name="ERC6").sort_index()

    # R255 / R259: same frozen family-aware prior-12 ranking logic.  We start
    # only when twelve completed representative months exist.
    r255_rows, r259_rows = [], []
    for i in range(12, len(reps)):
        month = reps.index[i]
        hist = reps.iloc[i-12:i]
        if len(hist) != 12 or hist.index.max() != month - 1:
            continue
        score = (1.0 + hist[spear]).prod().sub(1.0)
        strongest = str(score.idxmax())
        weakest = str(score.idxmin())
        middle = [g for g in spear if g not in {strongest, weakest}][0]

        w_bun = pd.Series(0.25, index=["Seiryu", "Byakko", "Suzaku", "Genbu"], dtype=float)
        w_split = w_bun.copy()
        trigger = weakest in {"Byakko", "Suzaku"}
        if trigger:
            w_split[:] = 0.0
            w_split[strongest] = 0.25
            w_split[middle] = 0.0
            w_split[weakest] = 0.375
            w_split["Genbu"] = 0.375

        rr = reps.loc[month, w_bun.index]
        r255_ret = float((w_split * rr).sum())
        r255_rows.append((month, r255_ret))

        # R259 single frozen gate: use R255 only when its family trigger is ON
        # and the weakest Spear's trailing-12 total return is negative.
        gate_on = bool(trigger and float(score[weakest]) < 0.0)
        w_gate = w_split if gate_on else w_bun
        r259_rows.append((month, float((w_gate * rr).sum())))

    r255 = pd.Series(dict(r255_rows), dtype=float, name="R255 Split").sort_index()
    r259 = pd.Series(dict(r259_rows), dtype=float, name="R259 Gate").sort_index()

    out = pd.concat([r181, erc6, r255, r259], axis=1).sort_index()

    # Official-overlap parity.  Keep the embedded series as the authority and
    # fail closed if the extended reconstruction does not reproduce it.
    official = _r15d_current_layer1_challengers_monthly()
    for col in ["R181", "ERC6", "R255 Split", "R259 Gate"]:
        idx = out[col].dropna().index.intersection(official[col].dropna().index)
        if len(idx) == 0:
            raise RuntimeError(f"{col}: no overlap with official Performance lineage")
        maxerr = float((out.loc[idx, col] - official.loc[idx, col]).abs().max())
        if maxerr > 5.1e-7:
            raise RuntimeError(f"{col}: max-history reconstruction parity failed: {maxerr:.3e}")
        # On official months use the official frozen values bit-for-bit.
        out.loc[idx, col] = official.loc[idx, col]

    expected_starts = {
        "R181": pd.Period("2014-02", "M"),
        "ERC6": pd.Period("2014-08", "M"),
        "R255 Split": pd.Period("2015-02", "M"),
        "R259 Gate": pd.Period("2015-02", "M"),
    }
    for col, expected in expected_starts.items():
        actual = out[col].dropna().index.min()
        if actual != expected:
            raise RuntimeError(f"{col}: unexpected max-history start {actual}, expected {expected}")
    return out


@st.cache_data(
    ttl=86400,
    show_spinner=False,
    hash_funcs={
        pd.DatetimeIndex: lambda x: x.asi8.tobytes(),
        pd.PeriodIndex: lambda x: (x.asi8.tobytes(), str(x.freq)),
    },
)
def _r15d_main_performance(start, end):
    needed = [
        "QQQ", "QLD", "LQD", "GLD", "TLT", "SPXL",
        "TQQQ", "TECL", "XLU", "^VIX", "SPY", "XLK", "TMF", "TMV",
    ]
    px = get_close(needed, start, end)
    rf = get_self_backtest_rf(start, end)

    # Frozen Core: Open→Open, same execution convention as v3.45.
    _, fc, _, _, _ = _r15o_build_core_open_live(px, rf, start, end)
    fc = pd.Series(fc).dropna().rename("Frozen Core")

    # Frozen v3.45: same frozen stack used by DD-regime input builder.
    _, v345, _, _ = _r15k_build_v345_live_inputs(
        px, rf, start, end
    )
    v345 = pd.Series(v345).dropna().rename("Frozen v3.45")

    # Complete 4F suite: one common family build, then frozen enhancements.
    fourf_suite = _r15t_build_4f_suite_live_inputs(px, rf, start, end)["daily"]

    # Benchmarks on next-open / open-to-open basis to match v3.45 execution.
    opens = get_open(tuple(needed), start, end)
    spy = opens["SPY"].pct_change(fill_method=None).rename("SPY")
    tqqq = opens["TQQQ"].pct_change(fill_method=None).rename("TQQQ")

    daily = pd.concat([fc, v345, fourf_suite, spy, tqqq], axis=1).sort_index()

    # Complete monthly compounded returns.
    monthly = (
        (1.0 + daily)
        .groupby(daily.index.to_period("M"))
        .prod(min_count=1)
        .sub(1.0)
    )

    # Avoid pre-live zeros / partial histories.
    monthly["Frozen Core"] = monthly["Frozen Core"].where(
        daily["Frozen Core"].groupby(daily.index.to_period("M")).count() > 0
    )
    monthly["Frozen v3.45"] = monthly["Frozen v3.45"].where(
        daily["Frozen v3.45"].groupby(daily.index.to_period("M")).count() > 0
    )
    monthly["Frozen 4F"] = monthly["Frozen 4F"].where(
        daily["Frozen 4F"].groupby(daily.index.to_period("M")).count() > 0
    )
    monthly["4F Attack75"] = monthly["4F Attack75"].where(
        daily["4F Attack75"].groupby(daily.index.to_period("M")).count() > 0
    )
    monthly["4F Promotion100"] = monthly["4F Promotion100"].where(
        daily["4F Promotion100"].groupby(daily.index.to_period("M")).count() > 0
    )
    monthly["SPY"] = monthly["SPY"].where(
        daily["SPY"].groupby(daily.index.to_period("M")).count() > 0
    )
    monthly["TQQQ"] = monthly["TQQQ"].where(
        daily["TQQQ"].groupby(daily.index.to_period("M")).count() > 0
    )

    return monthly




@st.cache_data(show_spinner=False, ttl=86400)
def _r15z_full5p_dashboard_monthly(end):
    """Fixed R113-family strategies, rebuilt over each strategy's maximum valid history."""
    start = "2003-01-01"  # warm-up before QLD inception and 24M signal
    tickers = ("LQD", "QQQ", "QLD", "TQQQ", "GLD", "TLT")
    close = get_close(tickers, start, end).sort_index()
    op = get_open(("QQQ", "QLD", "TQQQ", "GLD", "TLT"), start, end).sort_index()
    idx = pd.DatetimeIndex(close.index.intersection(op.index)).sort_values()
    close = close.reindex(idx)
    op = op.reindex(idx)
    rf = get_self_backtest_rf(start, end)

    # RF helpers identical to the canonical R102 monthly RAW/EX1 construction.
    days = pd.date_range(idx.min().normalize()-pd.Timedelta(days=1), idx.max().normalize(), freq="D")
    rfs = pd.Series(rf).sort_index().astype(float)
    rr = rfs.reindex(days, method="ffill")
    if rr.isna().any():
        prior = rfs.loc[:days[0]].dropna()
        if len(prior): rr = rr.fillna(float(prior.iloc[-1]))
        rr = rr.bfill().fillna(0.0)
    rfc = (np.log1p(rr/100.0)/365.25).cumsum()
    def rf_interval(a,b):
        a=pd.Timestamp(a).normalize(); b=pd.Timestamp(b).normalize()
        if b<=a: return 0.0
        try: return float(np.expm1(float(rfc.loc[b]-rfc.loc[a-pd.Timedelta(days=1)])))
        except Exception: return np.nan

    lqd = close["LQD"].dropna()
    me0 = pd.DataFrame({"value":lqd.values,"date":lqd.index},index=lqd.index)
    me0["period"] = me0.index.to_period("M")
    me = me0.groupby("period",sort=True).tail(1).set_index("period")[["value","date"]]
    me.index = pd.PeriodIndex(me.index,freq="M")
    trade_dates = _model_trade_dates(idx,"QQQ-MOM")
    labs = ["10D","54D","6M_EX1","12M_EX1","24M_RAW","11M_RAW"]
    sig = pd.DataFrame(index=trade_dates,columns=labs,dtype="boolean")
    for td in trade_dates:
        month_start=pd.Timestamp(td.year,td.month,1)
        try: end0=last_trading_day_before(pd.DatetimeIndex(lqd.index),month_start)
        except Exception: continue
        for d in (10,54):
            try:
                mom,a,b=trading_return(lqd,end0,d); rfv=rf_return(rf,a,b)
                sig.at[td,f"{d}D"] = bool(mom>=rfv)
            except Exception: pass
        latest=pd.Period(pd.Timestamp(td),freq="M")-1
        for n,mode in ((6,"EX1"),(12,"EX1"),(24,"RAW"),(11,"RAW")):
            sp=latest-n; ep=latest if mode=="RAW" else latest-1
            if sp not in me.index or ep not in me.index: continue
            p0=float(me.loc[sp,"value"]); p1=float(me.loc[ep,"value"])
            d0=pd.Timestamp(me.loc[sp,"date"]); d1=pd.Timestamp(me.loc[ep,"date"])
            if not(np.isfinite(p0) and np.isfinite(p1) and p0>0): continue
            rfv=rf_interval(d0,d1)
            if np.isfinite(rfv): sig.at[td,f"{n}M_{mode}"]=bool((p1/p0-1)>=rfv)

    def effective(series):
        out=pd.Series(np.nan,index=idx,dtype=float)
        for td,v in series.dropna().items():
            try: loc=idx.get_loc(pd.Timestamp(td))
            except KeyError: continue
            if loc+1<len(idx): out.iloc[loc+1]=float(bool(v))
        return out.ffill()

    full = sig[["10D","54D","6M_EX1","12M_EX1","24M_RAW"]].dropna(how="any")
    maj = (full.astype(int).sum(axis=1)>=3)
    h5 = effective(maj)
    h11 = effective(sig["11M_RAW"])
    ar = op[["QQQ","QLD","TQQQ","GLD","TLT"]].pct_change(fill_method=None)
    safe,_ = _adaptive_safe_haven_monthly_series(close[["GLD","TLT"]].dropna(how="all"))
    safe=safe.reindex(idx).ffill()
    ashret=pd.Series(np.nan,index=idx,dtype=float)
    ashret.loc[safe.eq("GLD")]=ar.loc[safe.eq("GLD"),"GLD"]
    ashret.loc[safe.eq("TLT")]=ar.loc[safe.eq("TLT"),"TLT"]
    bal=0.5*ar["QQQ"]+0.5*ar["QLD"]

    daily=pd.DataFrame(index=idx)
    daily["Frozen Operational 11M"] = np.where(h11.eq(1),bal,ashret)
    daily["Full5P × QQQ/QLD 50:50 × GLD"] = np.where(h5.eq(1),bal,ar["GLD"])
    daily["Full5P × QLD × GLD"] = np.where(h5.eq(1),ar["QLD"],ar["GLD"])
    daily["Full5P × TQQQ × GLD"] = np.where(h5.eq(1),ar["TQQQ"],ar["GLD"])
    # np.where loses missing-data semantics; restore validity explicitly.
    daily.loc[h11.isna(),"Frozen Operational 11M"] = np.nan
    for c in ["Full5P × QQQ/QLD 50:50 × GLD","Full5P × QLD × GLD","Full5P × TQQQ × GLD"]:
        daily.loc[h5.isna(),c]=np.nan
    daily.loc[h11.eq(1)&bal.isna(),"Frozen Operational 11M"]=np.nan
    daily.loc[h11.eq(0)&ashret.isna(),"Frozen Operational 11M"]=np.nan
    daily.loc[h5.eq(1)&bal.isna(),"Full5P × QQQ/QLD 50:50 × GLD"]=np.nan
    daily.loc[h5.eq(1)&ar["QLD"].isna(),"Full5P × QLD × GLD"]=np.nan
    daily.loc[h5.eq(1)&ar["TQQQ"].isna(),"Full5P × TQQQ × GLD"]=np.nan
    daily.loc[h5.eq(0)&ar["GLD"].isna(),["Full5P × QQQ/QLD 50:50 × GLD","Full5P × QLD × GLD","Full5P × TQQQ × GLD"]]=np.nan

    monthly=(1+daily).groupby(daily.index.to_period("M")).prod(min_count=1)-1
    counts=daily.groupby(daily.index.to_period("M")).count()
    monthly=monthly.where(counts>0)
    # Trim leading gaps independently so each selector item retains maximum valid history.
    for c in monthly.columns:
        first=monthly[c].first_valid_index()
        if first is not None: monthly.loc[monthly.index<first,c]=np.nan
    return monthly


def _r15d_svg_equity(df, log_y=True, height=430):
    """Responsive static SVG. No drag/pan/zoom; tap-safe on mobile."""
    width = 760
    ml, mr, mt, mb = 82, 22, 62, 52
    pw, ph = width - ml - mr, height - mt - mb

    vals = df.astype(float).copy()
    if log_y:
        vals = np.log10(vals.where(vals > 0))

    finite = vals.to_numpy(dtype=float)
    finite = finite[np.isfinite(finite)]
    if finite.size == 0:
        return "<div>no data</div>"

    ymin, ymax = float(finite.min()), float(finite.max())
    if ymin == ymax:
        ymax = ymin + 1.0
    pad = (ymax - ymin) * 0.08
    ymin -= pad
    ymax += pad

    n = len(vals)
    def sx(i):
        return ml + (0 if n <= 1 else i / (n - 1)) * pw
    def sy(v):
        return mt + (ymax - v) / (ymax - ymin) * ph

    palette = {
        "Frozen Core": "#1565c0",
        "Frozen v3.45": "#7b1fa2",
        "Frozen 4F": "#00897b",
        "4F Attack75": "#00a6a6",
        "ERC6 + Attack75": "#b45309",
        "麒麟「天界」": "#b45309",
        "麒麟「現世」": "#0f766e",
        "4F Promotion100": "#d81b60",
        "SPY": "#78909c",
        "TQQQ": "#ef6c00",
    }

    parts = [
        f'<div style="width:100%;overflow:hidden;">'
        f'<svg viewBox="0 0 {width} {height}" '
        f'xmlns="http://www.w3.org/2000/svg" role="img" '
        f'style="width:100%;height:auto;display:block;">',
        '<rect width="100%" height="100%" fill="transparent"/>'
    ]

    for j in range(6):
        vv = ymin + (ymax - ymin) * j / 5
        yy = sy(vv)
        parts.append(
            f'<line x1="{ml}" y1="{yy:.1f}" x2="{width-mr}" y2="{yy:.1f}" '
            'stroke="#d9dde3" stroke-width="1"/>'
        )
        display = 10 ** vv if log_y else vv
        if display >= 1_000_000:
            label = f"${display/1_000_000:.1f}M"
        elif display >= 1_000:
            label = f"${display/1_000:.0f}K"
        else:
            label = f"${display:.0f}"
        parts.append(
            f'<text x="{ml-10}" y="{yy+4:.1f}" text-anchor="end" '
            f'font-size="12" fill="#687386">{label}</text>'
        )

    dates = pd.PeriodIndex(vals.index, freq="M")
    years = sorted(set(dates.year))
    step = max(1, len(years) // 6)
    tick_years = years[::step]
    if years and years[-1] not in tick_years:
        tick_years.append(years[-1])

    for yr in tick_years:
        idx0 = next((i for i, p in enumerate(dates) if p.year == yr), None)
        if idx0 is not None:
            xx = sx(idx0)
            parts.append(
                f'<text x="{xx:.1f}" y="{height-16}" text-anchor="middle" '
                f'font-size="12" fill="#687386">{yr}</text>'
            )

    for col in vals.columns:
        pts = []
        for i, v in enumerate(vals[col].to_numpy(dtype=float)):
            if np.isfinite(v):
                pts.append(f"{sx(i):.1f},{sy(float(v)):.1f}")
        if not pts:
            continue
        parts.append(
            f'<polyline points="{" ".join(pts)}" fill="none" '
            f'stroke="{palette.get(col, "#455a64")}" stroke-width="3" '
            f'stroke-linejoin="round" stroke-linecap="round"/>'
        )

    # Legend
    legend_columns = 3
    legend_width = (width - ml - mr) / legend_columns
    for i, col in enumerate(vals.columns):
        lx = ml + (i % legend_columns) * legend_width
        ly = 17 + (i // legend_columns) * 22
        color = palette.get(col, "#455a64")
        parts.append(
            f'<line x1="{lx}" y1="{ly}" x2="{lx+20}" y2="{ly}" '
            f'stroke="{color}" stroke-width="4"/>'
        )
        parts.append(
            f'<text x="{lx+27}" y="{ly+4}" font-size="12" fill="#46505c">{col}</text>'
        )

    parts.append("</svg></div>")
    return "".join(parts)



def _r15e_slice_period(df, period_label):
    if df.empty or period_label == "ALL":
        return df
    months = {"1Y": 12, "2Y": 24, "3Y": 36, "5Y": 60, "10Y": 120}.get(period_label)
    if months is None:
        return df
    return df.tail(months)


def _r15e_mtd_table(asof, start, end):
    """
    Lightweight MTD view for the two main strategies + selected benchmark.
    Uses the same daily Frozen Core and v3.45 reconstruction as Performance.
    """
    needed = [
        "QQQ", "QLD", "LQD", "GLD", "TLT", "SPXL",
        "TQQQ", "TECL", "XLU", "^VIX", "SPY", "XLK",
    ]
    px = get_close(needed, start, end)
    rf = get_self_backtest_rf(start, end)
    bt, _ = run_backtest_detailed(px, rf)
    fc = bt["Frozen Core"].rename("Frozen Core")
    _, v345, _, _ = _v374r10_build_dd_inputs(px, rf, start, end)
    v345 = pd.Series(v345).rename("Frozen v3.45")
    opens = get_open(tuple(needed), start, end)
    spy = opens["SPY"].pct_change(fill_method=None).rename("SPY")
    tq = opens["TQQQ"].pct_change(fill_method=None).rename("TQQQ")
    d = pd.concat([fc, v345, spy, tq], axis=1).sort_index()
    cur = pd.Timestamp(asof).to_period("M")
    d = d[d.index.to_period("M") == cur].copy()
    return d


def _r15e_render_mtd(asof, strategy_name, benchmark_name):
    month_start = pd.Timestamp(asof).to_period("M").start_time
    start = (month_start - pd.Timedelta(days=10)).strftime("%Y-%m-%d")
    end = (pd.Timestamp(asof) + pd.Timedelta(days=4)).strftime("%Y-%m-%d")

    try:
        d = _r15e_mtd_table(asof, start, end)
    except Exception as e:
        st.caption(f"MTDを構築できませんでした: {e}")
        return

    if strategy_name not in d or benchmark_name not in d:
        return

    x = d[[strategy_name, benchmark_name]].dropna(how="all").copy()
    if x.empty:
        return

    cum = (1.0 + x.fillna(0.0)).cumprod().sub(1.0) * 100.0

    st.markdown("### MTD Performance")
    st.caption(f"As of {pd.Timestamp(asof).strftime('%m/%d')} ｜ {benchmark_name}")

    plot = cum.copy()
    plot.columns = [strategy_name, benchmark_name]
    st.line_chart(plot, use_container_width=True, height=280)

    st.markdown("### MTD Daily Returns")
    rows = []
    for dt in reversed(cum.index):
        rows.append({
            "Date": pd.Timestamp(dt).strftime("%m/%d"),
            "Portfolio": f"{cum.loc[dt, strategy_name]:+.2f}%",
            "Benchmark": f"{cum.loc[dt, benchmark_name]:+.2f}%",
        })
    st.dataframe(
        pd.DataFrame(rows),
        hide_index=True,
        use_container_width=True,
    )
    st.caption("Values are cumulative returns from month start.")



def _r15g_metrics_table(view, strategy, benchmark):
    rows = []
    for name in [strategy, benchmark]:
        m = monthly_metrics_0rf(view[name].dropna())
        rows.append({
            "Series": name,
            "CAGR": m.get("CAGR", np.nan),
            "Sortino": m.get("Sortino", np.nan),
            "Sharpe": m.get("Sharpe", np.nan),
            "MaxDD": m.get("MaxDD", np.nan),
            "Volatility": m.get("Volatility", np.nan),
            "Calmar": m.get("Calmar", np.nan),
        })
    mt = pd.DataFrame(rows)
    show = mt.copy()
    for col in ["CAGR", "MaxDD", "Volatility"]:
        show[col] = show[col].map(
            lambda x: "—" if pd.isna(x) else f"{x*100:.2f}%"
        )
    for col in ["Sortino", "Sharpe", "Calmar"]:
        show[col] = show[col].map(
            lambda x: "—" if pd.isna(x) else f"{x:.3f}"
        )
    return show




def _r15q_hover_equity_chart(equity, title=None, log_y=True, height=395):
    """
    Mobile-friendly fixed-axis return chart.
    - all selected series start at 0%
    - Y axis = return %
    - LOG toggle = symlog
    - tap/click selects a date and keeps the values visible
    - selected values are shown in a clean two-row readout above the plot
    - X/Y baseline axes remain visible
    - asymmetric Y bounds avoid excessive empty space below 0%
    - no pan / zoom
    """
    import altair as alt
    import math

    z = equity.copy().astype(float)
    if isinstance(z.index, pd.PeriodIndex):
        z.index = pd.to_datetime(z.index.astype(str) + "-01")
    else:
        z.index = pd.to_datetime(z.index)
    z = z.sort_index()
    z.index.name = "Date"

    first = z.iloc[0].replace(0, np.nan)
    ret = z.div(first).sub(1.0).mul(100.0)

    long = (
        ret.reset_index()
        .melt(id_vars="Date", var_name="Series", value_name="ReturnPct")
        .replace([np.inf, -np.inf], np.nan)
        .dropna()
    )
    if long.empty:
        st.info("表示できる資産曲線がありません。")
        return

    # Pre-format percentage text because this Altair version does not
    # support a Tooltip suffix parameter.
    long["ReturnLabel"] = long["ReturnPct"].map(lambda x: f"{x:+.2f}%")

    x_min = pd.Timestamp(ret.index.min())
    x_max = pd.Timestamp(ret.index.max())
    y_vals = long["ReturnPct"].to_numpy(dtype=float)
    y_vals = y_vals[np.isfinite(y_vals)]
    if y_vals.size == 0:
        return

    ymin = float(y_vals.min())
    ymax = float(y_vals.max())

    # --- Asymmetric Y bounds ---
    # Upper range is driven by the large positive return, while the lower
    # bound is determined only by the actual negative excursion.
    # This avoids a chart with -100% of empty space when the worst point is
    # only around -10% to -20%.
    pos_max = max(0.0, ymax)
    neg_min = min(0.0, ymin)

    def _nice_step(v):
        if v <= 0:
            return 5.0
        mag = 10 ** math.floor(math.log10(v))
        x = v / mag
        if x <= 1:
            n = 1
        elif x <= 2:
            n = 2
        elif x <= 2.5:
            n = 2.5
        elif x <= 5:
            n = 5
        else:
            n = 10
        return n * mag

    # Positive ticks: roughly 4–5 intervals.
    pos_step = _nice_step(max(pos_max / 4.0, 5.0))
    hi = max(pos_step, math.ceil((pos_max * 1.04) / pos_step) * pos_step)

    # Negative side: scale independently from positive side.
    if neg_min < 0:
        neg_extent = abs(neg_min)
        neg_step = _nice_step(max(neg_extent / 2.0, 5.0))
        lo = math.floor((neg_min * 1.10) / neg_step) * neg_step

        # Do not allow the lower padding to become disproportionate.
        # At most about 1.6x the observed negative excursion.
        lo_floor = -max(10.0, neg_extent * 1.6)
        lo = max(lo, lo_floor)
    else:
        neg_step = 5.0
        lo = 0.0

    # Tick values: only meaningful levels.
    ticks = [0.0]
    if lo < 0:
        neg_ticks = []
        v = -neg_step
        while v >= lo - 1e-9:
            neg_ticks.append(v)
            v -= neg_step
        ticks = list(reversed(neg_ticks)) + ticks

    v = pos_step
    while v <= hi + 1e-9:
        ticks.append(v)
        v += pos_step

    y_scale = (
        alt.Scale(
            type="symlog",
            constant=max(10.0, min(pos_step, 25.0)),
            domain=[lo, hi],
            nice=False,
        )
        if log_y
        else alt.Scale(domain=[lo, hi], nice=False)
    )
    x_scale = alt.Scale(domain=[x_min, x_max], nice=False)

    x_axis = alt.Axis(
        title="",
        labelAngle=0,
        labelFontSize=11,
        tickCount=6,
        grid=False,
        domain=True,
        domainWidth=1.0,
        tickWidth=0.9,
        labelPadding=7,
    )
    y_axis = alt.Axis(
        title="",
        labelFontSize=11,
        values=ticks,
        grid=True,
        gridOpacity=0.22,
        domain=True,
        domainWidth=1.0,
        tickWidth=0.9,
        labelPadding=5,
        labelExpr="datum.value > 0 ? '+' + format(datum.value, '.0f') + '%' : format(datum.value, '.0f') + '%'",
    )

    color = alt.Color(
        "Series:N",
        title="",
        legend=alt.Legend(
            orient="top",
            direction="horizontal",
            columns=3,
            labelFontSize=11,
            symbolSize=70,
            offset=2,
            title="",
        ),
    )

    tooltip_fields = [
        alt.Tooltip("Date:T", title="Date", format="%Y-%m-%d"),
        alt.Tooltip("Series:N", title="Series"),
        alt.Tooltip("ReturnLabel:N", title="Return"),
    ]

    base = alt.Chart(long).encode(
        x=alt.X("Date:T", scale=x_scale, axis=x_axis),
        y=alt.Y("ReturnPct:Q", scale=y_scale, axis=y_axis),
        color=color,
    )

    tap = alt.selection_point(
        name="tapdate",
        nearest=True,
        on="click",
        fields=["Date"],
        empty=False,
        clear=False,
    )
    hover = alt.selection_point(
        name="hoverdate",
        nearest=True,
        on="pointerover",
        fields=["Date"],
        empty=False,
        clear="pointerout",
    )

    lines = base.mark_line(strokeWidth=2.35).encode(
        tooltip=tooltip_fields
    )

    selectors = (
        alt.Chart(long)
        .mark_point(opacity=0, size=280)
        .encode(
            x=alt.X("Date:T", scale=x_scale),
            y=alt.Y("ReturnPct:Q", scale=y_scale),
            tooltip=tooltip_fields,
        )
        .add_params(tap, hover)
    )

    selected_points = base.mark_point(size=72, filled=True).encode(
        opacity=alt.condition(
            tap | hover,
            alt.value(1),
            alt.value(0),
        ),
        tooltip=tooltip_fields,
    )

    selected_rule = (
        alt.Chart(long)
        .mark_rule(strokeWidth=1.0)
        .encode(
            x=alt.X("Date:T", scale=x_scale),
            opacity=alt.condition(
                tap | hover,
                alt.value(0.38),
                alt.value(0),
            ),
        )
        .transform_filter(tap | hover)
    )

    selected = long.copy()
    selected["ReturnLabel"] = selected["ReturnPct"].map(lambda x: f"{x:+.2f}%")

    date_text = (
        alt.Chart(selected)
        .transform_filter(tap)
        .transform_aggregate(Date="max(Date)")
        .mark_text(
            align="center",
            baseline="middle",
            fontSize=12,
            fontWeight="bold",
            color="#6b7280",
        )
        .encode(
            text=alt.Text("Date:T", format="%Y-%m-%d"),
            x=alt.value(330),
            y=alt.value(12),
        )
        .properties(height=24)
    )

    selected_text = (
        alt.Chart(selected)
        .transform_filter(tap)
        .mark_text(
            fontSize=13,
            fontWeight="bold",
            baseline="middle",
        )
        .encode(
            x=alt.X(
                "Series:N",
                sort=list(ret.columns),
                axis=None,
            ),
            y=alt.value(13),
            color=color,
            text=alt.Text("ReturnLabel:N"),
        )
        .properties(height=28)
    )

    main_chart = (
        lines + selectors + selected_rule + selected_points
    ).properties(
        width="container",
        height=height,
    )

    chart = alt.vconcat(
        date_text,
        selected_text,
        main_chart,
        spacing=2,
    ).resolve_scale(
        color="shared"
    )

    if title:
        chart = chart.properties(title=str(title))

    chart = chart.configure_view(strokeWidth=0)
    st.altair_chart(chart, use_container_width=True)


def _r15i_hover_line_chart(df, title=None, percent=False, height=320):
    """
    Fixed-axis Altair line chart:
    - no pan / no zoom / no scale dragging
    - hover only shows values
    - legend is compact and embedded at the top of the plot
    - full container width on mobile
    """
    import altair as alt

    z = df.copy()
    if isinstance(z.index, pd.PeriodIndex):
        z.index = pd.to_datetime(z.index.astype(str) + "-01")
    else:
        z.index = pd.to_datetime(z.index)
    z.index.name = "Date"

    long = (
        z.reset_index()
        .melt(id_vars="Date", var_name="Series", value_name="Value")
        .dropna()
    )
    if long.empty:
        st.info("表示できるデータがありません。")
        return

    y_axis = alt.Axis(
        format=".1f" if percent else ".2f",
        title="%" if percent else None,
        labelFontSize=11,
        titleFontSize=11,
        grid=True,
    )
    x_axis = alt.Axis(
        title=None,
        labelAngle=0,
        labelFontSize=11,
        tickCount=6,
    )

    color_enc = alt.Color(
        "Series:N",
        title=None,
        legend=alt.Legend(
            orient="top",
            direction="horizontal",
            columns=3,
            labelFontSize=10,
            symbolSize=70,
            offset=4,
        ),
    )

    base = alt.Chart(long).encode(
        x=alt.X("Date:T", axis=x_axis),
        y=alt.Y("Value:Q", axis=y_axis),
        color=color_enc,
    )

    nearest = alt.selection_point(
        nearest=True,
        on="mouseover",
        fields=["Date"],
        empty=False,
        clear="mouseout",
    )

    lines = base.mark_line(strokeWidth=2.2)
    selectors = (
        alt.Chart(long)
        .mark_point(opacity=0)
        .encode(x="Date:T")
        .add_params(nearest)
    )
    points = base.mark_point(size=48).encode(
        opacity=alt.condition(nearest, alt.value(1), alt.value(0))
    )
    rule = (
        alt.Chart(long)
        .mark_rule()
        .encode(
            x="Date:T",
            opacity=alt.condition(nearest, alt.value(0.22), alt.value(0)),
        )
        .transform_filter(nearest)
    )
    tooltip = (
        alt.Chart(long)
        .mark_point(opacity=0)
        .encode(
            x="Date:T",
            tooltip=[
                alt.Tooltip("Date:T", title="Date", format="%Y-%m"),
                alt.Tooltip("Series:N", title="Series"),
                alt.Tooltip(
                    "Value:Q",
                    title="Value",
                    format="+.2f" if percent else ".3f",
                ),
            ],
        )
        .transform_filter(nearest)
    )

    chart = (
        (lines + selectors + points + rule + tooltip)
        .properties(width="container", height=height, title=title)
        .configure_view(strokeWidth=0)
    )

    st.altair_chart(chart, use_container_width=True)


def _r15i_worst_drawdowns(r, strategy_name, topn=10):
    """Top drawdown episodes from monthly returns."""
    r = pd.Series(r).dropna().astype(float)
    if r.empty:
        return pd.DataFrame()

    wealth = (1.0 + r).cumprod()
    dd = wealth.div(wealth.cummax()).sub(1.0)

    rows = []
    in_dd = False
    peak_date = None
    trough_date = None
    trough_dd = 0.0

    for i, d in enumerate(dd.index):
        val = float(dd.loc[d])
        if val < -1e-12 and not in_dd:
            in_dd = True
            prior = wealth.iloc[:i]
            peak_date = prior.idxmax() if len(prior) else d
            trough_date = d
            trough_dd = val
        elif in_dd:
            if val < trough_dd:
                trough_dd = val
                trough_date = d
            if val >= -1e-12:
                rows.append({
                    "Strategy": strategy_name,
                    "Peak": str(peak_date),
                    "Trough": str(trough_date),
                    "Recovery": str(d),
                    "MaxDD": trough_dd,
                })
                in_dd = False

    if in_dd:
        rows.append({
            "Strategy": strategy_name,
            "Peak": str(peak_date),
            "Trough": str(trough_date),
            "Recovery": "Not recovered",
            "MaxDD": trough_dd,
        })

    out = pd.DataFrame(rows)
    if out.empty:
        return out
    out = out.sort_values("MaxDD").head(topn).reset_index(drop=True)
    out.insert(0, "Rank", np.arange(1, len(out) + 1))
    out["MaxDD"] = out["MaxDD"].map(lambda x: f"{x*100:.2f}%")
    return out


def _r15i_rolling_returns(monthly, benchmark, strategies):
    st.markdown("### Rolling Returns")
    st.caption(
        "統計表はFrozen Core / Frozen v3.45 / Benchmarkごとに分けて表示。"
        "グラフは選択系列を重ねて比較します。"
    )

    series_list = list(strategies) + [benchmark]
    windows = [
        ("1Y", 12), ("2Y", 24), ("3Y", 36),
        ("5Y", 60), ("7Y", 84), ("10Y", 120),
    ]

    chart_store = {}

    # Separate tables for readability.
    for idx_series, series_name in enumerate(series_list):
        if idx_series:
            st.divider()

        st.markdown(f"#### {series_name}")
        r = monthly[series_name].dropna().astype(float)
        if r.empty:
            st.caption("Rolling Returnを計算できる履歴がありません。")
            continue

        rows = []
        for label, n in windows:
            if len(r) < n:
                continue

            w = (1.0 + r).rolling(n).apply(np.prod, raw=True)
            rr = (w - 1.0) if n <= 12 else (w.pow(12.0 / n) - 1.0)
            rr = rr.dropna()
            if rr.empty:
                continue

            rows.append({
                "Period": label,
                "Current": f"{rr.iloc[-1]*100:+.2f}%",
                "Median": f"{rr.median()*100:+.2f}%",
                "P10": f"{rr.quantile(.10)*100:+.2f}%",
                "Worst": f"{rr.min()*100:+.2f}%",
                "Positive": f"{(rr > 0).mean()*100:.1f}%",
            })

            if label in ("1Y", "3Y", "5Y"):
                chart_store[(series_name, label)] = rr * 100.0

        if rows:
            st.dataframe(
                pd.DataFrame(rows),
                hide_index=True,
                use_container_width=True,
            )

    st.divider()
    st.markdown("#### Rolling chart — Overlay")
    roll_period = st.segmented_control(
        "Period",
        options=["1Y", "3Y", "5Y"],
        default="3Y",
        key="r15o_roll_overlay_period",
        label_visibility="collapsed",
    )
    if roll_period is None:
        roll_period = "3Y"

    overlay = {}
    for series_name in series_list:
        ser = chart_store.get((series_name, roll_period))
        if ser is not None and not ser.empty:
            overlay[series_name] = ser

    if overlay:
        chart_df = pd.DataFrame(overlay).dropna(how="all")
        _r15i_hover_line_chart(
            chart_df,
            title=f"{roll_period} Rolling Return",
            percent=True,
            height=340,
        )

def _r15i_risk_page(monthly, benchmark, strategies):
    st.markdown("### Risk")
    d = monthly[strategies + [benchmark]].dropna().copy()
    if d.empty:
        st.info("リスク指標を計算できません。")
        return

    st.markdown("#### Drawdown")
    wealth = (1.0 + d).cumprod()
    dd = wealth.div(wealth.cummax()).sub(1.0) * 100.0
    _r15i_hover_line_chart(
        dd,
        title="Drawdown",
        percent=True,
        height=330,
    )

    st.markdown("#### Worst 10 Drawdowns")
    st.caption("戦略ごとに分けて表示。Benchmarkも別表で確認できます。")
    for series_name in list(strategies) + [benchmark]:
        st.markdown(f"##### {series_name}")
        w = _r15i_worst_drawdowns(d[series_name], series_name, topn=10)
        if w.empty:
            st.caption("Drawdown episodeなし")
            continue
        show_w = w.drop(columns=["Strategy"], errors="ignore")
        st.dataframe(
            show_w,
            hide_index=True,
            use_container_width=True,
        )

    st.markdown("#### 36M Rolling Risk")
    latest_rows = []
    metric_frames = {
        "Sharpe": pd.DataFrame(),
        "Tracking Error": pd.DataFrame(),
        "Information Ratio": pd.DataFrame(),
    }

    for strategy in strategies:
        x = d[[strategy, benchmark]].dropna()
        if len(x) < 36:
            continue
        active = x[strategy] - x[benchmark]

        rr = pd.DataFrame(index=x.index)
        rr["Sharpe"] = (
            x[strategy].rolling(36).mean()
            / x[strategy].rolling(36).std(ddof=1)
            * np.sqrt(12.0)
        )
        rr["Tracking Error"] = active.rolling(36).std(ddof=1) * np.sqrt(12.0)
        rr["Information Ratio"] = (
            active.rolling(36).mean()
            / active.rolling(36).std(ddof=1)
            * np.sqrt(12.0)
        )
        rr = rr.replace([np.inf, -np.inf], np.nan).dropna()
        if rr.empty:
            continue

        latest = rr.iloc[-1]
        latest_rows.append({
            "Strategy": strategy,
            "36M Sharpe": latest["Sharpe"],
            "36M Tracking Error": latest["Tracking Error"],
            "36M Information Ratio": latest["Information Ratio"],
        })

        for metric in metric_frames:
            metric_frames[metric][strategy] = rr[metric]

    if latest_rows:
        z = pd.DataFrame(latest_rows)
        z["36M Sharpe"] = z["36M Sharpe"].map(lambda x: f"{x:.2f}")
        z["36M Tracking Error"] = z["36M Tracking Error"].map(lambda x: f"{x*100:.2f}%")
        z["36M Information Ratio"] = z["36M Information Ratio"].map(lambda x: f"{x:.2f}")
        st.dataframe(z, hide_index=True, use_container_width=True)

    risk_metric = st.segmented_control(
        "Risk metric",
        options=["Sharpe", "Tracking Error", "Information Ratio"],
        default="Information Ratio",
        key="r15i_risk_metric",
        label_visibility="collapsed",
    )
    if risk_metric is None:
        risk_metric = "Information Ratio"

    rf = metric_frames.get(risk_metric)
    if rf is not None and not rf.empty:
        plot = rf.copy()
        is_pct = risk_metric == "Tracking Error"
        if is_pct:
            plot = plot * 100.0
        _r15i_hover_line_chart(
            plot,
            title=f"36M {risk_metric}",
            percent=is_pct,
            height=300,
        )


def _r15i_health_one(monthly, strategy, benchmark):
    d = monthly[[strategy, benchmark]].dropna().copy()
    if d.empty:
        return

    r = d[strategy].astype(float)
    bm = d[benchmark].astype(float)
    active = (r - bm).dropna()
    windows = (6, 12, 24)

    ds = [_p_deterioration(r, w) for w in windows]
    es = [_p_erosion(r, w) for w in windows]

    level = _health_level(
        [x["pdet"] for x in ds if x],
        [x["perosion"] for x in es if x],
    )

    st.markdown(f"#### {strategy} — {level}")

    cols = st.columns(3)
    for col, w, x in zip(cols, windows, ds):
        if x:
            col.metric(
                f"P(det) · {w}M",
                f"{x['pdet']*100:.1f}%",
                f"{x['recent_mean']*100:+.2f}%/mo",
            )
        else:
            col.metric(f"P(det) · {w}M", "—")

    rows = []
    for n in (3, 5, 10):
        pa, _ = _pbar_consistency(r, n)
        pr, _ = _pbar_consistency(active, n)
        rows.append({
            "Split": f"{n}-split" + (" · Primary" if n == 5 else ""),
            f"{strategy} > 0 p̄": f"{pa:.4f}",
            "Strength": _pbar_label(pa),
            f"{strategy} > {benchmark} p̄": f"{pr:.4f}",
            "Active strength": _pbar_label(pr),
        })
    st.dataframe(pd.DataFrame(rows), hide_index=True, use_container_width=True)


def _r15i_health_page(monthly, benchmark, strategies):
    st.markdown("### Strategy Health")
    st.caption(
        "Frozen Core と Frozen v3.45 を同じページで常時監視。"
        "監視専用で、売買ルールは変更しません。"
    )
    for i, strategy in enumerate(strategies):
        if i:
            st.divider()
        _r15i_health_one(monthly, strategy, benchmark)



# ============================================================
# R15AH — Metrics page
# Reproduces the metric item set from the attached reference.
# ============================================================

def _r15ah_period_index(r):
    if isinstance(r.index, pd.PeriodIndex):
        return r.index.asfreq("M")
    return pd.DatetimeIndex(r.index).to_period("M")


def _r15ah_annual_returns(r):
    r = pd.Series(r).dropna().astype(float)
    if r.empty:
        return pd.Series(dtype=float)
    p = _r15ah_period_index(r)
    tmp = pd.DataFrame({"r": r.to_numpy(), "year": p.year}, index=r.index)
    counts = tmp.groupby("year").size()
    ann = tmp.groupby("year")["r"].apply(lambda x: (1.0 + x).prod() - 1.0)
    return ann[counts >= 12]


def _r15ah_drawdown_stats(r):
    r = pd.Series(r).dropna().astype(float)
    if r.empty:
        return {}

    wealth = (1.0 + r).cumprod()
    peak = wealth.cummax()
    dd = wealth / peak - 1.0
    mdd_date = dd.idxmin()
    mdd = float(dd.min())

    # Peak immediately preceding max drawdown.
    upto = wealth.loc[:mdd_date]
    peak_val = float(peak.loc[mdd_date])
    peak_candidates = upto[upto >= peak_val * (1 - 1e-12)]
    peak_date = peak_candidates.index[-1] if len(peak_candidates) else wealth.index[0]

    # Recovery date after trough.
    after = wealth.loc[mdd_date:]
    rec = after[after >= peak_val * (1 - 1e-12)]
    recovery_date = rec.index[0] if len(rec) else None

    def months_between(a, b):
        if a is None or b is None:
            return np.nan
        pa = pd.Period(a, freq="M")
        pb = pd.Period(b, freq="M")
        return int(pb.ordinal - pa.ordinal)

    dd_len = months_between(peak_date, mdd_date)
    recovery_time = months_between(mdd_date, recovery_date) if recovery_date is not None else np.nan
    underwater_period = months_between(peak_date, recovery_date) if recovery_date is not None else np.nan

    # Completed underwater episodes + PTU.
    completed = []
    underwater = dd < -1e-12
    start_peak = None
    trough = None
    for i, idx in enumerate(dd.index):
        if underwater.loc[idx] and start_peak is None:
            prior = wealth.iloc[:i]
            start_peak = prior.idxmax() if len(prior) else idx
            trough = idx
        elif start_peak is not None:
            if dd.loc[idx] < dd.loc[trough]:
                trough = idx
            if not underwater.loc[idx]:
                completed.append(months_between(start_peak, idx))
                start_peak = None
                trough = None

    avg_uw = float(np.mean(completed)) if completed else np.nan
    ptu = float(underwater.mean())

    return {
        "Maximum Drawdown": mdd,
        "MDD Date": mdd_date,
        "Drawdown Length": dd_len,
        "Recovery Time": recovery_time,
        "Underwater Period": underwater_period,
        "Avg Underwater Period": avg_uw,
        "PTU(%)": ptu,
        "Peak Date": peak_date,
        "Trough Date": mdd_date,
        "Recovery Date": recovery_date,
        "New High Frequency": float((wealth >= peak * (1 - 1e-12)).mean()),
    }


def _r15ah_max_runup(r):
    r = pd.Series(r).dropna().astype(float)
    if r.empty:
        return np.nan
    wealth = (1.0 + r).cumprod()
    rolling_min = wealth.cummin()
    runup = wealth / rolling_min - 1.0
    return float(runup.max())


def _r15ah_max_consecutive_losses(r):
    best = cur = 0
    for x in pd.Series(r).dropna().astype(float):
        if x < 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best


def _r15ah_min_months_vs_benchmark_ttest(active):
    """
    Approximate minimum months required for a two-sided 5% t-test
    to distinguish mean active return from zero, using observed mean/std.
    """
    a = pd.Series(active).dropna().astype(float)
    if len(a) < 3:
        return np.nan
    mu = float(a.mean())
    sd = float(a.std(ddof=1))
    if sd <= 0 or abs(mu) <= 1e-12:
        return np.nan
    # Normal approximation: n >= (1.96 * sd / mean)^2
    return float(math.ceil((1.96 * sd / abs(mu)) ** 2))


def _r15ah_tail_contribution_ratio(r):
    r = pd.Series(r).dropna().astype(float)
    if len(r) < 20:
        return np.nan
    q10 = r.quantile(0.10)
    q90 = r.quantile(0.90)
    left = abs(float(r[r <= q10].sum()))
    right = abs(float(r[r >= q90].sum()))
    return right / left if left > 0 else np.nan


def _r15ah_left_tail_jumps(r):
    r = pd.Series(r).dropna().astype(float)
    if len(r) < 12:
        return np.nan
    sd = float(r.std(ddof=1))
    if sd <= 0:
        return 0
    return int((r < r.mean() - 2.0 * sd).sum())


def _r15ah_metric_values(r, bm=None):
    r = pd.Series(r).dropna().astype(float)
    if bm is not None:
        pair = pd.concat([r.rename("r"), pd.Series(bm).rename("bm")], axis=1).dropna()
        r = pair["r"]
        b = pair["bm"]
    else:
        b = None

    n = len(r)
    years = n / 12.0 if n else np.nan

    arithmetic_m = float(r.mean()) if n else np.nan
    arithmetic_a = arithmetic_m * 12.0 if n else np.nan
    geom_m = float((1.0 + r).prod() ** (1.0 / n) - 1.0) if n else np.nan
    geom_a = float((1.0 + geom_m) ** 12 - 1.0) if n else np.nan
    sd_m = float(r.std(ddof=1)) if n > 1 else np.nan
    sd_a = sd_m * np.sqrt(12.0) if np.isfinite(sd_m) else np.nan

    downside = np.minimum(r.to_numpy(), 0.0)
    downside_m = float(np.sqrt(np.mean(downside ** 2))) if n else np.nan

    ann = _r15ah_annual_returns(r)
    best_year = float(ann.max()) if len(ann) else np.nan
    worst_year = float(ann.min()) if len(ann) else np.nan

    dd = _r15ah_drawdown_stats(r)

    sharpe = arithmetic_m / sd_m * np.sqrt(12.0) if sd_m and sd_m > 0 else np.nan
    downside_a = downside_m * np.sqrt(12.0) if np.isfinite(downside_m) else np.nan
    sortino = arithmetic_m * 12.0 / downside_a if downside_a and downside_a > 0 else np.nan
    calmar = geom_a / abs(dd.get("Maximum Drawdown", np.nan)) if dd.get("Maximum Drawdown", 0) < 0 else np.nan

    gains = r[r > 0]
    losses = r[r < 0]
    gain_loss = float(gains.mean() / abs(losses.mean())) if len(gains) and len(losses) else np.nan
    positive = int((r > 0).sum())

    # Parametric 5% monthly VaR, shown as a positive loss magnitude.
    var5 = max(0.0, -(arithmetic_m - 1.6448536269514722 * sd_m)) if np.isfinite(sd_m) else np.nan

    vals = {
        "Arithmetic Mean (monthly)": arithmetic_m,
        "Arithmetic Mean (annualized)": arithmetic_a,
        "Geometric Mean (monthly)": geom_m,
        "Geometric Mean (annualized)": geom_a,
        "Standard Deviation (monthly)": sd_m,
        "Standard Deviation (annualized)": sd_a,
        "Downside Deviation (monthly)": downside_m,
        "Best Year": best_year,
        "Worst Year": worst_year,
        "Maximum Drawdown": dd.get("Maximum Drawdown", np.nan),
        "MDD Date": dd.get("MDD Date"),
        "Drawdown Length": dd.get("Drawdown Length", np.nan),
        "Recovery Time": dd.get("Recovery Time", np.nan),
        "Underwater Period": dd.get("Underwater Period", np.nan),
        "Avg Underwater Period": dd.get("Avg Underwater Period", np.nan),
        "PTU(%)": dd.get("PTU(%)", np.nan),
        "Peak Date": dd.get("Peak Date"),
        "Trough Date": dd.get("Trough Date"),
        "Recovery Date": dd.get("Recovery Date"),
        "Sharpe Ratio": sharpe,
        "Sortino Ratio": sortino,
        "Calmar Ratio": calmar,
        "Analytical Value-at-Risk (5%)": var5,
        "Positive Periods": f"{positive}/{n} ({positive/n*100:.2f}%)" if n else "—",
        "Gain/Loss Ratio": gain_loss,
        "Skewness": float(r.skew()) if n > 2 else np.nan,
        "Excess Kurtosis": float(r.kurt()) if n > 3 else np.nan,
        "Volatility Drag": arithmetic_a - geom_a if np.isfinite(geom_a) else np.nan,
        "Max Consecutive Loss": _r15ah_max_consecutive_losses(r),
        "Max Run-up": _r15ah_max_runup(r),
        "Tail Contribution Ratio": _r15ah_tail_contribution_ratio(r),
        "Left-tail Jumps": _r15ah_left_tail_jumps(r),
        "New High Frequency": dd.get("New High Frequency", np.nan),
    }

    if b is not None and len(b):
        corr = float(r.corr(b))
        var_b = float(b.var(ddof=1))
        beta = float(r.cov(b) / var_b) if var_b > 0 else np.nan
        alpha_m = float(r.mean() - beta * b.mean()) if np.isfinite(beta) else np.nan
        alpha_a = (1.0 + alpha_m) ** 12 - 1.0 if np.isfinite(alpha_m) and alpha_m > -1 else np.nan
        r2 = corr ** 2 if np.isfinite(corr) else np.nan

        active = r - b
        te = float(active.std(ddof=1) * np.sqrt(12.0)) if len(active) > 1 else np.nan
        active_a = float(active.mean() * 12.0)
        ir = float(active.mean() / active.std(ddof=1) * np.sqrt(12.0)) if active.std(ddof=1) > 0 else np.nan

        # Treynor with 0 RF, consistent with current dashboard convention.
        treynor = arithmetic_a / beta if np.isfinite(beta) and abs(beta) > 1e-12 else np.nan

        up = b > 0
        down = b < 0
        port_up = float(r[up].mean()) if up.any() else np.nan
        bm_up = float(b[up].mean()) if up.any() else np.nan
        port_down = float(r[down].mean()) if down.any() else np.nan
        bm_down = float(b[down].mean()) if down.any() else np.nan

        up_capture = port_up / bm_up if np.isfinite(bm_up) and abs(bm_up) > 1e-12 else np.nan
        down_capture = port_down / bm_down if np.isfinite(bm_down) and abs(bm_down) > 1e-12 else np.nan
        updown_spread = up_capture - down_capture if np.isfinite(up_capture) and np.isfinite(down_capture) else np.nan
        updown_ratio = up_capture / down_capture if np.isfinite(down_capture) and abs(down_capture) > 1e-12 else np.nan
        updown_vector = np.sqrt(up_capture ** 2 + down_capture ** 2) if np.isfinite(up_capture) and np.isfinite(down_capture) else np.nan

        vals.update({
            "Benchmark Correlation": corr,
            "Beta": beta,
            "Alpha (annualized)": alpha_a,
            "R²": r2,
            "Treynor Ratio (%)": treynor,
            "Upside Capture Ratio (%)": up_capture,
            "Downside Capture Ratio (%)": down_capture,
            "Up/Down Spread": updown_spread,
            "Up/Down Ratio": updown_ratio,
            "Up/Down Vector": updown_vector,
            "Min Months vs Benchmark (t-test)": _r15ah_min_months_vs_benchmark_ttest(active),
            "Active Return": active_a,
            "Tracking Error": te,
            "Information Ratio": ir,
        })

    return vals


