def _r15ah_fmt_metric(name, value):
    if value is None:
        return "—"
    if isinstance(value, str):
        return value

    if name in ("MDD Date", "Peak Date", "Trough Date", "Recovery Date"):
        if pd.isna(value):
            return "—"
        try:
            return str(pd.Period(value, freq="M"))
        except Exception:
            return str(value)

    if name in ("Drawdown Length", "Recovery Time", "Underwater Period", "Avg Underwater Period"):
        if pd.isna(value):
            return "—"
        return f"{float(value):.1f} months" if name == "Avg Underwater Period" else f"{int(round(float(value)))} months"

    if name in ("Max Consecutive Loss", "Left-tail Jumps", "Min Months vs Benchmark (t-test)"):
        return "—" if pd.isna(value) else str(int(round(float(value))))

    if pd.isna(value):
        return "—"

    if name in _R15AH_PERCENT_METRICS:
        # Capture/Treynor are stored as ratios and shown as percentages, matching reference.
        return f"{float(value)*100:+.2f}%"

    if name in ("Sharpe Ratio", "Sortino Ratio", "Calmar Ratio", "Benchmark Correlation",
                "Beta", "R²", "Gain/Loss Ratio", "Skewness", "Excess Kurtosis",
                "Up/Down Ratio", "Up/Down Vector", "Tail Contribution Ratio",
                "Information Ratio"):
        return f"{float(value):.2f}"

    return f"{float(value):.3f}"


