def _r15ai_month_label(x):
    try:
        return str(pd.Period(x, freq="M"))
    except Exception:
        return str(x)


def _r15ai_analysis_period_text(df):
    if df.empty:
        return "Analysis Period: —"
    idx = pd.PeriodIndex(df.index, freq="M")
    start = idx.min().to_timestamp(how="end").normalize()
    end = idx.max().to_timestamp(how="end").normalize()
    return f"Analysis Period: {start:%Y-%m-%d} to {end:%Y-%m-%d} ({len(idx)} months)"


def _r15ai_metrics_html(rows, strategy, benchmark):
    """
    Mobile-first HTML table.
    IMPORTANT: return compact, non-indented HTML so Streamlit Markdown
    never interprets the rows as a code block on mobile.
    """
    body = []
    for r in rows:
        metric = str(r["Metric"])
        p = str(r[strategy])
        b = str(r[benchmark])
        body.append(
            '<div class="r15ai-metric-row">'
            f'<div class="r15ai-metric-name">{metric}</div>'
            f'<div class="r15ai-metric-val r15ai-strategy">{p}</div>'
            f'<div class="r15ai-metric-val">{b}</div>'
            '</div>'
        )

    return (
        '<div class="r15ai-metrics-wrap">'
        '<div class="r15ai-metric-head">'
        '<div>Metric</div>'
        f'<div class="r15ai-strategy">{strategy}</div>'
        f'<div>{benchmark}</div>'
        '</div>'
        + ''.join(body) +
        '</div>'
    )


def _r15ai_market_summary(pair, strategy, benchmark):
    d = pair[[strategy, benchmark]].dropna().copy()
    if d.empty:
        return pd.DataFrame()

    # Same three-way market framing used by the prior dashboard:
    # benchmark > +2% / between ±2% / benchmark < -2%.
    d["Market Type"] = np.where(
        d[benchmark] > 0.02,
        "Up Market",
        np.where(d[benchmark] < -0.02, "Down Market", "Sideways"),
    )
    d["AboveBM"] = d[strategy] > d[benchmark]
    d["Active"] = d[strategy] - d[benchmark]

    rows = []
    for label in ["Up Market", "Sideways", "Down Market"]:
        x = d[d["Market Type"] == label]
        if x.empty:
            continue
        above = int(x["AboveBM"].sum())
        below = int(len(x) - above)
        rows.append({
            "Market Type": label,
            "Above BM": above,
            "Below BM": below,
            "Total": len(x),
            "% Above": above / len(x),
            "Avg Active": float(x["Active"].mean()),
        })

    above = int(d["AboveBM"].sum())
    rows.append({
        "Market Type": "Total",
        "Above BM": above,
        "Below BM": int(len(d) - above),
        "Total": len(d),
        "% Above": above / len(d),
        "Avg Active": float(d["Active"].mean()),
    })
    return pd.DataFrame(rows)


def _r15ai_market_summary_html(df):
    if df.empty:
        return ""

    parts = []
    for _, r in df.iterrows():
        label = str(r["Market Type"])
        cls = " r15ai-up" if label == "Up Market" else (" r15ai-down" if label == "Down Market" else "")
        if label == "Total":
            cls += " r15ai-total"
        parts.append(
            f'<div class="r15ai-market-row{cls}">'
            f'<div>{label}</div>'
            f'<div>{int(r["Above BM"])}</div>'
            f'<div>{int(r["Below BM"])}</div>'
            f'<div>{int(r["Total"])}</div>'
            f'<div>{r["% Above"]*100:.0f}%</div>'
            f'<div>{r["Avg Active"]*100:+.2f}%</div>'
            '</div>'
        )

    return (
        '<div class="r15ai-market-wrap">'
        '<div class="r15ai-market-head">'
        '<div>Market Type</div>'
        '<div>Above BM</div>'
        '<div>Below BM</div>'
        '<div>Total</div>'
        '<div>% Above</div>'
        '<div>Avg Active</div>'
        '</div>'
        + ''.join(parts) +
        '</div>'
    )


def _r15ai_benchmark_buckets(pair, strategy, benchmark):
    d = pair[[strategy, benchmark]].dropna().copy()
    if d.empty:
        return pd.DataFrame()

    # Monthly benchmark return buckets matching the reference view.
    # Values are decimal returns: -0.12 = -12%.
    bins = [
        -np.inf, -0.12, -0.08, -0.06, -0.04, -0.02,
        0.00, 0.02, 0.04, 0.06, 0.08, 0.10, 0.15, np.inf
    ]
    labels = [
        "< -12%",
        "-12 to -8%",
        "-8 to -6%",
        "-6 to -4%",
        "-4 to -2%",
        "-2 to 0%",
        "0 to 2%",
        "2 to 4%",
        "4 to 6%",
        "6 to 8%",
        "8 to 10%",
        "10 to 15%",
        "> 15%",
    ]

    bucket = pd.cut(
        d[benchmark],
        bins=bins,
        labels=labels,
        include_lowest=True,
        right=False,
    )

    g = (
        d.assign(Bucket=bucket)
        .groupby("Bucket", observed=False)[[strategy, benchmark]]
        .mean()
        * 100.0
    )

    # Keep only buckets that actually contain observations, preserving order.
    counts = d.assign(Bucket=bucket).groupby("Bucket", observed=False).size()
    keep = counts[counts > 0].index
    return g.loc[keep].dropna(how="all")


def _r15ai_market_bar_chart(bucket_df, strategy, benchmark):
    if bucket_df is None or bucket_df.empty:
        return

    import altair as alt

    z = bucket_df.reset_index().melt(
        id_vars="Bucket",
        value_vars=[strategy, benchmark],
        var_name="Series",
        value_name="Average Return",
    )
    z["ReturnLabel"] = z["Average Return"].map(lambda x: f"{x:+.2f}%")

    chart = (
        alt.Chart(z)
        .mark_bar()
        .encode(
            x=alt.X(
                "Bucket:N",
                sort=list(bucket_df.index.astype(str)),
                title="Benchmark Return Range",
                axis=alt.Axis(
                    labelAngle=-52,
                    labelFontSize=8,
                    titleFontSize=10,
                    labelLimit=85,
                ),
            ),
            y=alt.Y(
                "Average Return:Q",
                title="Average Return",
                axis=alt.Axis(
                    labelFontSize=9,
                    titleFontSize=10,
                    tickCount=5,
                    labelExpr="format(datum.value, '.0f') + '%'",
                    gridOpacity=.22,
                ),
            ),
            xOffset="Series:N",
            color=alt.Color(
                "Series:N",
                title="",
                legend=alt.Legend(
                    orient="bottom",
                    direction="horizontal",
                    labelFontSize=10,
                    symbolSize=70,
                ),
            ),
            tooltip=[
                alt.Tooltip("Bucket:N", title="BM range"),
                alt.Tooltip("Series:N", title="Series"),
                alt.Tooltip("ReturnLabel:N", title="Avg return"),
            ],
        )
        .properties(width="container", height=300)
        .configure_view(strokeWidth=0)
    )
    st.altair_chart(chart, use_container_width=True)


