def _r15al_metrics_valid_sample(monthly, strategy, benchmark):
    """
    Metrics-only valid-sample filter.

    Important:
    - Do not treat pre-live padding / synthetic zero months as strategy history.
    - Frozen v3.45 and all 4F variants have a frozen valid return start of 2011-04.
    - Benchmark is clipped to the exact same months as the selected strategy.
    """
    d = monthly[[strategy, benchmark]].copy()

    # monthly can use either DatetimeIndex or PeriodIndex depending on the
    # upstream dashboard path. pandas intentionally rejects pd.to_datetime()
    # on PeriodDtype, so convert PeriodIndex explicitly.
    if isinstance(d.index, pd.PeriodIndex):
        d.index = d.index.to_timestamp(how="end").normalize()
    else:
        d.index = pd.DatetimeIndex(pd.to_datetime(d.index))

    # Frozen v3.45: frozen implementation becomes valid from Apr-2011.
    if str(strategy) in (
        "Frozen v3.45", "Frozen 4F", "4F Attack75", "4F Promotion100"
    ):
        d = d.loc[d.index >= pd.Timestamp("2011-04-01")]

    # Remove missing rows first.
    d = d.dropna()

    if d.empty:
        return d

    # Defensive guard for legacy/padded series:
    # strip leading strategy returns that are exactly zero until the first
    # genuinely non-zero observation. Do NOT remove legitimate zero months
    # after the strategy has started.
    vals = pd.to_numeric(d[strategy], errors="coerce")
    nz = np.flatnonzero(np.isfinite(vals.to_numpy()) & (np.abs(vals.to_numpy()) > 1e-14))
    if len(nz):
        d = d.iloc[int(nz[0]):]

    return d


def _r15ah_render_metrics_page(monthly, strategies, benchmark):
    st.markdown("### Risk and Return Metrics")

    # Benchmark-only remains supported.
    if not strategies:
        d = monthly[[benchmark]].dropna().copy()
        st.caption(_r15ai_analysis_period_text(d))
        vals = _r15ah_metric_values(d[benchmark], None)
        rows = [
            {"Metric": name, benchmark: _r15ah_fmt_metric(name, vals.get(name))}
            for name in _R15AH_METRIC_ORDER
            if name in vals
        ]
        st.dataframe(
            pd.DataFrame(rows),
            hide_index=True,
            use_container_width=True,
            height=900,
        )
        return

    # Strategy tabs: render only the selected strategy.
    # This is intentionally a segmented control rather than st.tabs so the
    # unselected strategy is not rendered/calculated again on every rerun.
    metric_strategy = st.segmented_control(
        "Strategy tab",
        options=list(strategies),
        default=list(strategies)[0],
        key="r15ak_metrics_strategy_tab",
        label_visibility="collapsed",
    )
    if metric_strategy is None:
        metric_strategy = list(strategies)[0]

    strategy = metric_strategy
    pair = _r15al_metrics_valid_sample(monthly, strategy, benchmark)
    if pair.empty:
        st.info("選択した戦略とBenchmarkの共通期間がありません。")
        return

    st.caption(_r15ai_analysis_period_text(pair))

    pvals = _r15ah_metric_values(pair[strategy], pair[benchmark])
    bvals = _r15ah_metric_values(pair[benchmark], None)

    rows = []
    for name in _R15AH_METRIC_ORDER:
        if name not in pvals and name not in bvals:
            continue
        rows.append({
            "Metric": name,
            strategy: _r15ah_fmt_metric(name, pvals.get(name)),
            benchmark: _r15ah_fmt_metric(name, bvals.get(name)),
        })

    st.markdown(f"#### {strategy} vs. {benchmark}")
    st.markdown(
        str(_r15ai_metrics_html(rows, strategy, benchmark)),
        unsafe_allow_html=True,
    )

    st.markdown("### Up vs. Down Market Performance")
    st.caption(f"({len(pair)} months)")
    summary = _r15ai_market_summary(pair, strategy, benchmark)
    st.markdown(
        str(_r15ai_market_summary_html(summary)),
        unsafe_allow_html=True,
    )

    bucket_df = _r15ai_benchmark_buckets(pair, strategy, benchmark)
    _r15ai_market_bar_chart(bucket_df, strategy, benchmark)


def _r15s_annual_returns_data(monthly, series, initial_balance=100000.0):
    """Tiny in-memory aggregation; no downloads and no backtest rebuild."""
    names = list(dict.fromkeys(series))
    d = monthly[names].dropna().astype(float).copy()
    if d.empty:
        return pd.DataFrame(), pd.DataFrame()
    years = pd.Index(d.index.year if isinstance(d.index, pd.PeriodIndex) else pd.DatetimeIndex(d.index).year)
    annual = (1.0 + d).groupby(years).prod(min_count=1).sub(1.0)
    annual.index.name = "Year"
    balance_monthly = (1.0 + d).cumprod() * float(initial_balance)
    balances = balance_monthly.groupby(years).last()
    balances.index.name = "Year"
    return annual, balances


def _r15s_render_annual_returns(monthly, strategies, benchmark, asof):
    st.markdown("### Annual Returns")
    st.caption("既に読み込み済みの月次リターンから集計。追加の価格取得・バックテスト計算は行いません。")

    if strategies:
        strategy = st.selectbox(
            "Strategy",
            options=list(strategies),
            index=0,
            key="r15s_annual_strategy",
        )
        series = [strategy, benchmark] if strategy != benchmark else [strategy]
    else:
        strategy = None
        series = [benchmark]

    annual, balances = _r15s_annual_returns_data(monthly, series)
    if annual.empty:
        st.info("年次リターンを表示できる共通期間がありません。")
        return

    latest_year = int(annual.index.max())
    latest_month = monthly.index.max()
    latest_month_num = int(latest_month.month)
    current_year_partial = latest_year == pd.Timestamp(asof).year and latest_month_num < 12
    years_label = f"{len(annual)} years"
    if current_year_partial:
        latest_available = pd.Timestamp(asof).strftime("%Y-%m-%d")
        st.caption(f"{years_label} ｜ {latest_year}年は最新取得日 {latest_available} までのYTD*")
    else:
        st.caption(years_label)

    import altair as alt
    chart_df = (
        annual.mul(100.0)
        .reset_index()
        .melt(id_vars="Year", var_name="Series", value_name="AnnualReturnPct")
    )
    chart_df["Year"] = chart_df["Year"].astype(str)
    chart_df["ReturnLabel"] = chart_df["AnnualReturnPct"].map(lambda x: f"{x:+.2f}%")
    # Only register the series actually drawn.  A fixed all-strategy domain
    # creates unused legend entries and clips the last label on mobile.
    palette = {
        "Frozen Core": "#1565c0",
        "Frozen v3.45": "#7b1fa2",
        "Frozen 4F": "#00897b",
        "4F Attack75": "#00a6a6",
        "ERC6 + Attack75": "#b45309",
        "麒麟「天界」": "#b45309",
        "麒麟「現世」": "#0f766e",
        "4F Promotion100": "#d81b60",
        "SPY": "#94a3b8",
        "TQQQ": "#ef6c00",
        "Layer1 New-EW": "#475569",
        "Layer1 New-R180": "#2563eb",
        "Layer1 New-R181": "#dc2626",
        "Layer1 New-R183": "#7c3aed",
        "Layer1 New-R184": "#059669",
    }
    color_scale = alt.Scale(
        domain=series,
        range=[palette.get(name, "#64748b") for name in series],
    )
    chart = (
        alt.Chart(chart_df)
        .mark_bar(cornerRadiusTopLeft=2, cornerRadiusTopRight=2)
        .encode(
            x=alt.X("Year:N", title="Year", sort=list(chart_df["Year"].drop_duplicates()), axis=alt.Axis(labelAngle=0, labelFontSize=10)),
            xOffset=alt.XOffset("Series:N", sort=series),
            y=alt.Y("AnnualReturnPct:Q", title="Annual Return", axis=alt.Axis(labelExpr="format(datum.value, '.0f') + '%'", gridOpacity=.20)),
            color=alt.Color(
                "Series:N",
                title="",
                scale=color_scale,
                legend=alt.Legend(
                    orient="bottom",
                    direction="horizontal",
                    columns=min(2, len(series)),
                    labelLimit=160,
                    symbolSize=75,
                    columnPadding=12,
                    rowPadding=6,
                ),
            ),
            tooltip=[
                alt.Tooltip("Year:N", title="Year"),
                alt.Tooltip("Series:N", title="Series"),
                alt.Tooltip("ReturnLabel:N", title="Return"),
            ],
        )
        .properties(width="container", height=330)
        .configure_view(strokeWidth=0)
    )
    st.altair_chart(chart, use_container_width=True)

    st.markdown("### Annual Returns Table")
    st.caption("Balanceは共通開始月に$100,000を投資し、追加投資・引出しなしで複利運用した年末残高です。")
    rows = []
    for year in reversed(annual.index):
        row = {"Year": f"{int(year)}{' YTD*' if current_year_partial and int(year) == latest_year else ''}"}
        for name in series:
            row[f"{name} Return"] = f"{float(annual.loc[year, name])*100:+.2f}%"
            row[f"{name} Balance"] = f"${float(balances.loc[year, name]):,.0f}"
        rows.append(row)
    st.dataframe(pd.DataFrame(rows), hide_index=True, use_container_width=True)
    if current_year_partial:
        st.caption("* 当月を含む最新取得価格までの暫定YTD。月末確定前はMTDを含みます。")


def _r15d_render_performance(asof):
    st.subheader("📊 Performance Dashboard")
    st.caption(
        "Frozen Core / v3.45 / 4F / Layer1 / 麒麟「天界」 / 麒麟「現世」を個別・同時比較できます。"
        "単独=最長履歴、複数=最長共通期間。"
    )

    start = "2009-01-01"
    end = (pd.Timestamp(asof) + pd.Timedelta(days=10)).strftime("%Y-%m-%d")

    with st.spinner("Frozen Core / v3.45 / 4F Suite の履歴を準備中…"):
        monthly = _r15d_main_performance(start, end)
    with st.spinner("Full5P / Frozen Operational の最長履歴を準備中…"):
        _new = _r15z_full5p_dashboard_monthly(end)
        monthly = pd.concat([monthly, _new], axis=1)
    # Add the frozen Layer1 research cohort from official R201 PATCH2.
    # No post-2026-07 values are fabricated; selecting these series therefore
    # naturally aligns comparisons to the common available research period.
    _l1 = _r15d_layer1_research_monthly()
    monthly = pd.concat([monthly, _l1], axis=1)
    # Current Layer1 challengers are rebuilt back to each rule's maximum valid
    # pre-2016 history, with hard parity to the embedded official overlap.
    _l1_current = _r15d_current_layer1_challengers_max_monthly()
    monthly = pd.concat([monthly, _l1_current], axis=1)
    # R276 PATCH1 defense-first hybrid, extended back to the earliest month
