    # Official 2016-02..2026-07 values remain the parity authority.
    _r276_hybrid = _r15d_r276_hybrid_max_monthly()
    # User-facing KIRIN names: 天界 = canonical Exact; 現世 = frozen R289 practical execution.
    _r276_hybrid = _r276_hybrid.rename(columns={"ERC6 + Attack75":"麒麟「天界」"})
    _r289_gense = _r15d_r289_gense_monthly()
    monthly = pd.concat([monthly, _r276_hybrid, _r289_gense], axis=1)
