# ================================================================
# v3.89 — Treasury–Equity Layered Dual Momentum Challenger LIGHT
# Hypothesis derived from v3.88 author-label reverse engineering.
# Fixed two-layer rule (NO sweep):
#   Layer 1 at month-end: TMV 3M > TMF 3M -> TMV
#   else Layer 2: TQQQ 3M > TECL 3M -> TQQQ else TECL
# Signal is known at month-end and position enters next first tradable OPEN.
# Open->Open return is applied only after entry (position shifted one row).
# Frozen v3.45 is unchanged. Development cutoff 2026-07-31.
# ================================================================
def _v389_layered_dm(px_close, start, end):
    need=['TMF','TMV','TQQQ','TECL']
    closes=px_close.reindex(columns=[c for c in need if c in px_close.columns]).copy()
    missing=[c for c in need if c not in closes.columns]
    if missing:
        closes=closes.join(get_close(tuple(missing),start,end),how='outer').sort_index().ffill()
    opens=get_open(tuple(need),start,end).sort_index().ffill()
    idx=pd.DatetimeIndex(opens.index).sort_values()
    closes=closes.reindex(closes.index).sort_index().ffill()
    me=closes[need].resample('ME').last()
    mom3=me/me.shift(3)-1.0
    sig=pd.Series(pd.NA,index=me.index,dtype='object',name='Signal')
    valid=mom3[need].notna().all(axis=1)
    tmv=valid & (mom3['TMV']>mom3['TMF'])
    eq=valid & ~tmv
    sig.loc[tmv]='TMV'
    sig.loc[eq & (mom3['TQQQ']>mom3['TECL'])]='TQQQ'
    sig.loc[eq & ~(mom3['TQQQ']>mom3['TECL'])]='TECL'

    # Signal at month-end t -> enter at first tradable open in month t+1.
    pos_open=pd.Series(pd.NA,index=idx,dtype='object',name='PositionAtOpen')
    audit=[]
    for dt,val in sig.dropna().items():
        cand=idx[idx>pd.Timestamp(dt)]
        if len(cand)==0: continue
        e=cand[0]
        pos_open.loc[e]=val
        audit.append({'SignalMonthEnd':dt,'EntryOpen':e,'Signal':val,
                      'TMF_3M':mom3.loc[dt,'TMF'],'TMV_3M':mom3.loc[dt,'TMV'],
                      'TQQQ_3M':mom3.loc[dt,'TQQQ'],'TECL_3M':mom3.loc[dt,'TECL']})
    pos_open=pos_open.ffill()
    ar=opens.pct_change(fill_method=None)
    # Return dated d is previous-open -> current-open, so use previous open's position.
    hold_for_return=pos_open.shift(1)
    ret=pd.Series(np.nan,index=idx,dtype=float,name='Layered DM 3M')
    for a in need:
        m=hold_for_return.eq(a)
        ret.loc[m]=ar.loc[m,a]
    return ret.dropna(),pd.DataFrame(audit),mom3,sig,pos_open


def _v389_alpha_corr(strategy_daily, px_close, rf_bt, start, end):
    # Reuse v3.84 family architecture for independent-alpha diagnostics.
    cutoff=pd.Timestamp('2026-07-31')
    closes=px_close.copy(); closes.index=pd.DatetimeIndex(closes.index)
    closes=closes.loc[:cutoff].sort_index().ffill()
    rf=rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt,pd.Series) else rf_bt
    core_h=_build_core_holding_matrix(closes,rf).reindex(closes.index)
    safe_h,_=_adaptive_safe_haven_monthly_series(closes); safe_h=safe_h.reindex(closes.index).ffill()
    h=core_h.copy()
    for m in MODEL_WEIGHTS:
        mask=h[m].eq('GLD'); h.loc[mask,m]=safe_h.loc[mask]
    daily=_returns_from_holding_matrix(h,closes)
    monthly=(1+daily).resample('ME').prod(min_count=1)-1
    fam=pd.DataFrame(index=monthly.index)
    fam['MOM family']=0.5*monthly['QQQ-MOM']+0.5*monthly['QLD-MOM']
    fam['MR family']=0.5*monthly['Weekly MR 24M']+0.5*monthly['Quarterly MR 24M']
    fam['VIX family']=0.25*monthly['Old VIX 15d']+0.25*monthly['Old VIX 20d']+0.5*monthly['New VIX 20d']
    dm_m=(1+strategy_daily.loc[:cutoff]).resample('ME').prod(min_count=1)-1
    fam['Layered DM 3M']=dm_m
    spy=(1+closes['SPY'].pct_change(fill_method=None)).resample('ME').prod(min_count=1)-1
    z=pd.concat([fam,spy.rename('SPY')],axis=1).dropna()
    fam=z[fam.columns]; spy=z['SPY']
    rows=[]; residuals={}
    for c in fam.columns:
        met=_v384_metrics_monthly(fam[c],spy); met['Strategy']=c; rows.append(met)
        b=met['Beta']; residuals[c]=fam[c]-b*spy if np.isfinite(b) else fam[c]*np.nan
    metrics=pd.DataFrame(rows).set_index('Strategy')
    raw=fam.corr(); resid=pd.DataFrame(residuals).corr()
    down=fam.loc[spy<0].corr(); q=float(spy.quantile(.10)); crisis=fam.loc[spy<=q].corr()
    base=['MOM family','MR family','VIX family']; four=base+['Layered DM 3M']
    eff=pd.DataFrame([
        {'Architecture':'Existing 3 families','Effective Bets':_v384_effective_bets(raw.loc[base,base])},
        {'Architecture':'3 + Layered DM','Effective Bets':_v384_effective_bets(raw.loc[four,four])},
        {'Architecture':'Existing 3 residuals','Effective Bets':_v384_effective_bets(resid.loc[base,base])},
        {'Architecture':'4 residual alpha streams','Effective Bets':_v384_effective_bets(resid.loc[four,four])},
    ]).set_index('Architecture')
    corr=pd.DataFrame({'Raw Corr':raw.loc['Layered DM 3M',base],
                       'Residual Corr':resid.loc['Layered DM 3M',base],
                       'Downside Corr':down.loc['Layered DM 3M',base],
                       'Crisis Corr':crisis.loc['Layered DM 3M',base]})
    return metrics,corr,eff,raw,resid,down,crisis,fam


def render_v389_treasury_equity_layered_dm(px_close,rf_bt,start,end):
    import io,zipfile
    st.markdown('### 🐉 v3.89 — Treasury–Equity Layered DM Challenger LIGHT')
