    with st.spinner('Layered DMを1回だけ構築し、v3.45・頑健性・独立alphaを監査中…'):
        cutoff=pd.Timestamp('2026-07-31')
        dm,audit,mom3,sig,pos=_v389_layered_dm(px_close,start,end)
        dm=dm.loc[:cutoff]
        _,v345,_,_=_v374r10_build_dd_inputs(px_close,rf_bt,start,end)
        d=pd.concat([v345.rename('Frozen v3.45'),dm.rename('Layered DM 3M')],axis=1).dropna()
        monthly=(1+d).resample('ME').prod()-1
        metrics=pd.DataFrame([_v325_metric_row(c,d[c]) for c in d.columns]).set_index('Variant')
        roll=_v326_rolling_p10_table(d,list(d.columns))
        cpcv,_=_v326_cpcv_summary(monthly.to_period('M'),'Frozen v3.45',['Layered DM 3M'])
        wf=_v355_wf_blocks(monthly.to_period('M'),'Frozen v3.45','Layered DM 3M',13)
        ametrics,corr,eff,raw,resid,down,crisis,fam=_v389_alpha_corr(dm,px_close,rf_bt,start,end)
        counts=sig.loc[:cutoff].value_counts().rename('SignalMonths').to_frame(); counts['Share']=counts['SignalMonths']/counts['SignalMonths'].sum()
        runs=[]
        ss=sig.loc[:cutoff].dropna(); run_id=(ss!=ss.shift()).cumsum()
        for _,g in ss.groupby(run_id): runs.append({'Signal':g.iloc[0],'Start':g.index[0],'End':g.index[-1],'Months':len(g)})
        runs=pd.DataFrame(runs)
        episodes=[('2015 selloff','2015-07-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),('2019-05','2019-05-01','2019-05-31'),('COVID','2020-02-01','2020-04-30'),('2022 selloff','2022-04-01','2022-10-31'),('2025 selloff','2025-02-01','2025-04-30')]
        stress=[]
        for nm,a,b in episodes:
            z=d.loc[a:b]; row={'Episode':nm,'Start':a,'End':b}
            for c in d.columns:
                x=z[c].dropna(); eq=(1+x).cumprod(); dd=eq/eq.cummax()-1
                row[c+' Return']=float((1+x).prod()-1) if len(x) else np.nan
                row[c+' MaxDD']=float(dd.min()) if len(x) else np.nan
            stress.append(row)
        stress=pd.DataFrame(stress)

    st.markdown('#### 単独成績 vs Frozen v3.45')
    show=metrics.copy()
    for c in ['CAGR','Vol','Daily MaxDD','Monthly MaxDD']: show[c]=show[c].map(lambda x:f'{x:.2%}')
    for c in ['Sharpe0','Sortino0']: show[c]=show[c].map(lambda x:f'{x:.3f}')
    st.dataframe(show,use_container_width=True)
    st.markdown('#### Rolling CAGR P10')
    rr=roll.copy()
