    st.dataframe(rr,hide_index=True,use_container_width=True)
    st.markdown('#### CPCV / WF')
    if len(cpcv):
        st.write({'CPCV Sortino wins':f"{int(cpcv['Positive Delta Sortino'].sum())}/{len(cpcv)}",
                  'CPCV Sharpe wins':f"{int(cpcv['Positive Delta Sharpe'].sum())}/{len(cpcv)}",
                  'CPCV Active+':f"{int(cpcv['Positive Active'].sum())}/{len(cpcv)}",
                  'Median ΔSortino':float(cpcv['Delta Sortino0'].median()),
                  'P10 ΔSortino':float(cpcv['Delta Sortino0'].quantile(.10))})
    if len(wf):
        act=wf['Active CAGR'].astype(float); st.write({'WF wins':int((act>1e-12).sum()),'ties':int((act.abs()<=1e-12).sum()),'losses':int((act< -1e-12).sum())})
    st.markdown('#### β-adjusted α / 既存3 familyとの独立性')
    st.dataframe(ametrics[['CAGR','Vol','Beta','Alpha','Sharpe','Sortino','CorrSPY']].round(4),use_container_width=True)
    st.dataframe(corr.round(3),use_container_width=True)
    st.markdown('#### Effective Bets')
