# ================================================================
# v3.90 — 4-Family Equal-Weight FoF Audit LIGHT
# Fixed, no optimization:
#   Control = MOM/MR/VIX, 1/3 each
#   Challenger = MOM/MR/VIX/TEL-DM, 1/4 each
# TEL-DM is the fixed v3.89 two-layer module.
# ================================================================
def _v390_monthly_rebalanced_ew(daily_components):
    x=daily_components.dropna().copy()
    if x.empty: return pd.Series(dtype=float)
    out=[]
    for _,g in x.groupby(x.index.to_period('M')):
        wealth=pd.Series(1.0,index=g.columns)
        for dt,row in g.iterrows():
            w=wealth/wealth.sum()
            r=float((w*row).sum())
            out.append((dt,r))
            wealth=wealth*(1.0+row)
    return pd.Series(dict(out)).sort_index()

def _v390_build(px_close,rf_bt,start,end):
    cutoff=pd.Timestamp('2026-07-31')
    closes=px_close.copy(); closes.index=pd.DatetimeIndex(closes.index); closes=closes.loc[:cutoff].sort_index().ffill()
    rf=rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt,pd.Series) else rf_bt
    core_h=_build_core_holding_matrix(closes,rf).reindex(closes.index)
    safe_h,_=_adaptive_safe_haven_monthly_series(closes); safe_h=safe_h.reindex(closes.index).ffill()
    h=core_h.copy()
    for m in MODEL_WEIGHTS:
        mask=h[m].eq('GLD'); h.loc[mask,m]=safe_h.loc[mask]
    sleeve=_returns_from_holding_matrix(h,closes)
    famd=pd.DataFrame(index=sleeve.index)
    famd['MOM']=0.5*sleeve['QQQ-MOM']+0.5*sleeve['QLD-MOM']
    famd['MR']=0.5*sleeve['Weekly MR 24M']+0.5*sleeve['Quarterly MR 24M']
    famd['VIX']=0.25*sleeve['Old VIX 15d']+0.25*sleeve['Old VIX 20d']+0.5*sleeve['New VIX 20d']
    tel,_,_,_,_=_v389_layered_dm(px_close,start,end)
    famd['TEL-DM']=tel.reindex(famd.index)
    famd=famd.dropna()
    ctrl=_v390_monthly_rebalanced_ew(famd[['MOM','MR','VIX']]).rename('3-Family EW')
    chal=_v390_monthly_rebalanced_ew(famd[['MOM','MR','VIX','TEL-DM']]).rename('4-Family EW + TEL-DM')
    d=pd.concat([ctrl,chal],axis=1).dropna().loc[:cutoff]
    return d,famd.loc[d.index.min():d.index.max()]

def render_v390_four_family_ew_fof(px_close,rf_bt,start,end):
    import io,zipfile
    st.markdown('### 🧩 v3.90 — 4-Family Equal-Weight FoF Audit LIGHT')
    st.caption('TEL-DMを独立alpha moduleとしてFoFへ追加する価値を、最適化なしの固定Equal Weightで監査します。')
    st.info('Control = MOM/MR/VIX 各1/3。Challenger = MOM/MR/VIX/TEL-DM 各1/4。各月初にEqual Weightへリバランス。ALM・α最適化・7PF探索はまだ行いません。')
    if not st.button('4-Family Equal-Weight FoFを検証',type='primary',use_container_width=True,key='run_v390'):
        return
    with st.spinner('固定EW FoFを1回だけ構築し、Rolling・CPCV・WF・stressを監査中…'):
        d,famd=_v390_build(px_close,rf_bt,start,end)
        monthly=(1+d).resample('ME').prod(min_count=1)-1
        metrics=pd.DataFrame([_v325_metric_row(c,d[c]) for c in d.columns]).set_index('Variant')
        roll=_v326_rolling_p10_table(d,list(d.columns))
        cpcv,_=_v326_cpcv_summary(monthly.to_period('M'),'3-Family EW',['4-Family EW + TEL-DM'])
        wf=_v355_wf_blocks(monthly.to_period('M'),'3-Family EW','4-Family EW + TEL-DM',13)
        spy=(1+px_close['SPY'].pct_change(fill_method=None)).resample('ME').prod(min_count=1)-1
        z=pd.concat([monthly,spy.rename('SPY')],axis=1).dropna()
        ab=[]
        for c in monthly.columns:
            m=_v384_metrics_monthly(z[c],z['SPY']); m['Strategy']=c; ab.append(m)
        ab=pd.DataFrame(ab).set_index('Strategy')
        episodes=[('2015 selloff','2015-07-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),('2019-05','2019-05-01','2019-05-31'),('COVID','2020-02-01','2020-04-30'),('2022 selloff','2022-04-01','2022-10-31'),('2025 selloff','2025-02-01','2025-04-30')]
        stress=[]
        for nm,a,b in episodes:
            row={'Episode':nm}
            for c in d.columns:
                x=d.loc[a:b,c].dropna(); eq=(1+x).cumprod(); dd=eq/eq.cummax()-1
                row[c+' Return']=float((1+x).prod()-1) if len(x) else np.nan
                row[c+' MaxDD']=float(dd.min()) if len(x) else np.nan
            stress.append(row)
        stress=pd.DataFrame(stress)
        fm=(1+famd).resample('ME').prod(min_count=1)-1
        corr=fm.corr()
        eff=pd.DataFrame([
            {'Architecture':'3 families','Effective Bets':_v384_effective_bets(corr.loc[['MOM','MR','VIX'],['MOM','MR','VIX']])},
            {'Architecture':'4 families + TEL-DM','Effective Bets':_v384_effective_bets(corr.loc[['MOM','MR','VIX','TEL-DM'],['MOM','MR','VIX','TEL-DM']])}
        ])
    st.markdown('#### Full metrics')
    show=metrics.copy()
    for c in ['CAGR','Vol','Daily MaxDD','Monthly MaxDD']:
        if c in show: show[c]=show[c].map(lambda x:f'{x:.2%}')
    for c in ['Sharpe0','Sortino0']:
        if c in show: show[c]=show[c].map(lambda x:f'{x:.3f}')
    st.dataframe(show,use_container_width=True)
    st.markdown('#### Rolling CAGR P10'); rr=roll.copy()
    for c in d.columns: rr[c]=rr[c].map(lambda x:'—' if pd.isna(x) else f'{x:.2%}')
    st.dataframe(rr,hide_index=True,use_container_width=True)
    st.markdown('#### α / β'); st.dataframe(ab[['CAGR','Vol','Beta','Alpha','Sharpe','Sortino','CorrSPY']].round(4),use_container_width=True)
    st.markdown('#### Effective Bets'); st.dataframe(eff,hide_index=True,use_container_width=True)
    st.markdown('#### Stress'); st.dataframe(stress,use_container_width=True,hide_index=True)
    if len(cpcv):
        st.write({'CPCV Sortino wins':f"{int(cpcv['Positive Delta Sortino'].sum())}/{len(cpcv)}",'CPCV Sharpe wins':f"{int(cpcv['Positive Delta Sharpe'].sum())}/{len(cpcv)}",'CPCV Active+':f"{int(cpcv['Positive Active'].sum())}/{len(cpcv)}"})
    if len(wf):
        act=wf['Active CAGR'].astype(float); st.write({'WF wins':int((act>1e-12).sum()),'ties':int((act.abs()<=1e-12).sum()),'losses':int((act< -1e-12).sum())})
    files={
      '01_full_metrics.csv':metrics.reset_index(), '02_rolling_p10.csv':roll, '03_cpcv_detail.csv':cpcv, '04_wf_blocks.csv':wf,
      '05_alpha_beta.csv':ab.reset_index(), '06_effective_bets.csv':eff, '07_family_correlation.csv':corr.reset_index(),
      '08_fixed_stress.csv':stress, '09_monthly_returns.csv':monthly.reset_index(), '10_daily_returns.csv':d.reset_index(),
      '11_family_monthly_returns.csv':fm.reset_index()}
    b=io.BytesIO()
    with zipfile.ZipFile(b,'w',zipfile.ZIP_DEFLATED) as zf:
        for fn,df in files.items(): zf.writestr(fn,df.to_csv(index=False).encode('utf-8-sig'))
        zf.writestr('README.txt','v3.90 fixed equal-weight FoF audit. Control=MOM/MR/VIX 1/3 each. Challenger=MOM/MR/VIX/TEL-DM 1/4 each. Monthly rebalance. No weight optimization. Development cutoff 2026-07-31.'.encode('utf-8'))
    st.download_button('📦 v3.90 FoF 検証ZIP',data=b.getvalue(),file_name='v390_four_family_equal_weight_fof_audit.zip',mime='application/zip',use_container_width=True,on_click='ignore',key='dl_v390')

def _v388_mom(s, months, skip=0):
    s = pd.Series(s).astype(float)
    return s.shift(skip) / s.shift(months + skip) - 1.0

def _v388_build(px_close):
    dev_cut = pd.Timestamp("2026-07-31")
    mc = px_close.copy()
    mc.index = pd.DatetimeIndex(pd.to_datetime(mc.index))
    mc = mc.sort_index().resample("ME").last()
    mc.index = mc.index.to_period("M")
    labels = pd.DataFrame(_AUTHOR_SIGNAL_ROWS_V388, columns=["Month","AuthorPosition","AuthorReturn"])
    labels["Month"] = pd.PeriodIndex(labels["Month"], freq="M")
    labels = labels.set_index("Month").sort_index()
    labels["Sample"] = ["DEV" if p.to_timestamp(how="end").normalize() <= dev_cut else "FORWARD_REFERENCE" for p in labels.index]
    # Author holding in month t must be explained only with information through t-1 month-end.
    sig = pd.DataFrame(index=labels.index)
    lbs = [("1M",1,0),("3M",3,0),("6M",6,0),("12M",12,0),("3M-1M",2,1),("6M-1M",5,1),("12M-1M",11,1)]
    assets=["GLD","LQD","SPXL","TECL","TMF","TMV","TQQQ","XLU","SPY","^VIX"]
    for nm,n,skip in lbs:
        mm={}
        for a in assets:
            if a in mc.columns:
                mm[a]=_v388_mom(mc[a],n,skip).shift(1).reindex(labels.index)
        # Prespecified theory comparisons; descriptive only, no parameter selection.
        pairs=[("TMF","TMV"),("LQD","GLD"),("SPXL","GLD"),("SPY","GLD"),("TQQQ","TECL"),("XLU","GLD")]
        for a,b in pairs:
            if a in mm and b in mm:
                sig[f"{a}_minus_{b}__{nm}"] = mm[a]-mm[b]
        for a in ["TMF","TMV","LQD","SPXL","SPY","TQQQ","TECL","XLU","GLD","^VIX"]:
            if a in mm: sig[f"{a}__{nm}"] = mm[a]
    out=labels.join(sig)
    out["IsTMV"]=(out["AuthorPosition"]=="TMV").astype(int)
    out["IsTQQQ"]=(out["AuthorPosition"]=="TQQQ").astype(int)
    return out

def _v388_rule_audit(d):
    rows=[]
    dev=d[d["Sample"]=="DEV"].copy()
    # Stage A: Does a prespecified sign screen separate TMV from equity? Both sign orientations are reported, not optimized.
    stageA=[c for c in dev.columns if c.startswith(("TMF_minus_TMV__","LQD_minus_GLD__","SPXL_minus_GLD__","SPY_minus_GLD__"))]
    for c in stageA:
        z=dev[[c,"IsTMV"]].dropna()
        if len(z)==0: continue
        for orient in ["positive=>TMV","negative=>TMV"]:
            pred=(z[c]>0).astype(int) if orient.startswith("positive") else (z[c]<0).astype(int)
            acc=float((pred==z["IsTMV"]).mean())
            tmv_recall=float(pred[z["IsTMV"]==1].mean()) if (z["IsTMV"]==1).any() else float('nan')
            equity_spec=float((1-pred[z["IsTMV"]==0]).mean()) if (z["IsTMV"]==0).any() else float('nan')
            rows.append({"Stage":"A: TMV vs Equity","Screen":c,"Orientation":orient,"N":len(z),"Accuracy":acc,"TMV_Recall":tmv_recall,"Equity_Recall":equity_spec})
    # Stage B: within equity months, can TQQQ-vs-TECL relative momentum explain the author's choice?
    eq=dev[dev["AuthorPosition"].isin(["TQQQ","TECL"])].copy()
    for c in [x for x in eq.columns if x.startswith("TQQQ_minus_TECL__")]:
        z=eq[[c,"IsTQQQ"]].dropna()
        if len(z)==0: continue
        for orient in ["positive=>TQQQ","negative=>TQQQ"]:
            pred=(z[c]>0).astype(int) if orient.startswith("positive") else (z[c]<0).astype(int)
            rows.append({"Stage":"B: TQQQ vs TECL","Screen":c,"Orientation":orient,"N":len(z),"Accuracy":float((pred==z["IsTQQQ"]).mean()),"TMV_Recall":float('nan'),"Equity_Recall":float('nan')})
    return pd.DataFrame(rows)

def _v388_transitions(d):
    z=d.copy().sort_index()
    z["PrevPosition"]=z["AuthorPosition"].shift(1)
    z=z[z["AuthorPosition"]!=z["PrevPosition"]].copy()
    keep=["AuthorPosition","PrevPosition","Sample"]+[c for c in z.columns if any(k in c for k in ["TMF_minus_TMV__","LQD_minus_GLD__","SPXL_minus_GLD__","SPY_minus_GLD__","TQQQ_minus_TECL__"])]
    return z[keep]

def _v388_conditional_layers(d):
    dev=d[d["Sample"]=="DEV"].copy()
    rows=[]
    # Fixed 12M-1M architecture table only; not a trading rule.
    screens=["TMF_minus_TMV__12M-1M","LQD_minus_GLD__12M-1M","SPXL_minus_GLD__12M-1M","SPY_minus_GLD__12M-1M"]
    for c in screens:
        if c not in dev: continue
        z=dev.dropna(subset=[c])
        for side,mask in [("Positive",z[c]>0),("Negative",z[c]<0)]:
            q=z[mask]
            if len(q)==0: continue
            cnt=q["AuthorPosition"].value_counts()
            rows.append({"Screen":c,"Side":side,"N":len(q),"TMV_pct":cnt.get("TMV",0)/len(q),"TQQQ_pct":cnt.get("TQQQ",0)/len(q),"TECL_pct":cnt.get("TECL",0)/len(q),"AuthorMeanReturn":q["AuthorReturn"].mean()})
    return pd.DataFrame(rows)

def render_v388_author_signal_reverse_engineering(px_close, rf_bt, start, end):
    st.subheader("v3.88 Author Signal Reverse Engineering Audit LIGHT")
    st.caption("作者の実際の月次保有ラベルを正解データとして、TMV選択とTQQQ/TECL選択を別々に監査します。売買戦略・最適lookback・最適thresholdは作りません。各保有月は必ず前月末までの情報だけで説明します。2026-08以降はForward Referenceとして探索集計から除外します。")
    if not st.button("Author Signal Auditを実行",type="primary",use_container_width=True,key="run_v388"):
        return
    d=_v388_build(px_close)
    rules=_v388_rule_audit(d)
    trans=_v388_transitions(d)
    layers=_v388_conditional_layers(d)
    dev=d[d["Sample"]=="DEV"]
    c1,c2,c3=st.columns(3)
    c1.metric("Author months (DEV)",f"{len(dev)}")
    c2.metric("Transitions",f"{len(trans[trans['Sample']=='DEV'])}")
    c3.metric("TMV share",f"{(dev['AuthorPosition']=='TMV').mean():.1%}")
    st.markdown("#### Stage A/B rule audit")
    st.dataframe(rules,use_container_width=True,hide_index=True)
    st.markdown("#### 12M−1M conditional architecture")
    st.dataframe(layers,use_container_width=True,hide_index=True)
    st.markdown("#### Transition months")
    st.dataframe(trans.reset_index().tail(60),use_container_width=True,hide_index=True)
    # One compact ZIP for iPhone.
    import io, zipfile
    b=io.BytesIO()
    with zipfile.ZipFile(b,"w",zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("01_author_signal_features.csv",d.reset_index().to_csv(index=False))
        zf.writestr("02_stage_rule_audit.csv",rules.to_csv(index=False))
        zf.writestr("03_transition_audit.csv",trans.reset_index().to_csv(index=False))
        zf.writestr("04_conditional_layer_table.csv",layers.to_csv(index=False))
        zf.writestr("README.txt","v3.88 Author Signal Reverse Engineering Audit LIGHT\nResearch only. No trading challenger. Author holding month t is matched only to features known through t-1 month-end. DEV ends 2026-07; later author labels are forward-reference only. Lookbacks are descriptive fixed set: 1M,3M,6M,12M,3M-1M,6M-1M,12M-1M. No best-lookback selection is performed.\n")
    st.download_button("📦 v3.88 Author Signal Audit ZIP",data=b.getvalue(),file_name="v388_author_signal_reverse_engineering_audit.zip",mime="application/zip",use_container_width=True,on_click="ignore",key="dl_v388")



# ================================================================
# v3.98 — TEL-DM vs シン朱雀-激攻 Deep Reverse-Engineering Audit LIGHT
# Purpose: explain the residual disagreement between the fixed TEL-DM 3M
# proxy and the author's actual monthly holdings. This is NOT a challenger
# and does NOT optimize a lookback/threshold.
#
# Fixed TEL-DM proxy inherited from v3.88/v3.89:
#   Stage A: TMF_3M - TMV_3M < 0  => TMV
#   Stage B: otherwise TQQQ_3M - TECL_3M > 0 => TQQQ else TECL
# Author holding month t and TEL prediction both use features known through
# t-1 month-end. DEV cutoff remains 2026-07-31.
# ================================================================
def _v398_tel_from_features(d):
    z=d.copy()
    a='TMF_minus_TMV__3M'; b='TQQQ_minus_TECL__3M'
    valid=z[a].notna() & z[b].notna()
    pred=pd.Series(pd.NA,index=z.index,dtype='object')
    pred.loc[valid & (z[a] < 0)]='TMV'
    pred.loc[valid & ~(z[a] < 0) & (z[b] > 0)]='TQQQ'
    pred.loc[valid & ~(z[a] < 0) & ~(z[b] > 0)]='TECL'
    z['TELPosition']=pred
    z['Match']=z['AuthorPosition'].eq(z['TELPosition'])
    z['AuthorLayer']=np.where(z['AuthorPosition'].eq('TMV'),'Treasury','Equity')
    z['TELLayer']=np.where(z['TELPosition'].eq('TMV'),'Treasury','Equity')
    z['LayerMatch']=z['AuthorLayer'].eq(z['TELLayer'])
    def cls(r):
        a=r['AuthorPosition']; t=r['TELPosition']
        if pd.isna(t) or a==t: return 'MATCH'
        if a=='TMV' and t in ('TQQQ','TECL'): return 'Author TMV / TEL Equity'
        if a in ('TQQQ','TECL') and t=='TMV': return 'Author Equity / TEL TMV'
        if a=='TQQQ' and t=='TECL': return 'Author TQQQ / TEL TECL'
        if a=='TECL' and t=='TQQQ': return 'Author TECL / TEL TQQQ'
        return f'{a} / {t}'
    z['DisagreementType']=z.apply(cls,axis=1)
    return z


def _v398_monthly_open_returns(start,end):
    assets=['TMV','TQQQ','TECL']
    op=get_open(tuple(assets),start,end).sort_index().ffill()
    if op.empty: return pd.DataFrame(columns=assets)
    op.index=pd.DatetimeIndex(pd.to_datetime(op.index))
    # First tradable OPEN of each month. Holding-month return is first OPEN(t)
    # -> first OPEN(t+1), matching the Open->Open semantics used elsewhere.
    fo=op[assets].resample('MS').first()
    fo.index=fo.index.to_period('M')
    r=fo.shift(-1)/fo-1.0
    return r


def _v398_common_basis_returns(z,start,end):
    r=_v398_monthly_open_returns(start,end)
    q=z.join(r.add_prefix('O2O_'),how='left')
    def pick(row,col):
        p=row[col]
        if pd.isna(p): return np.nan
        return row.get('O2O_'+str(p),np.nan)
    q['AuthorCommonReturn']=q.apply(lambda x: pick(x,'AuthorPosition'),axis=1)
    q['TELCommonReturn']=q.apply(lambda x: pick(x,'TELPosition'),axis=1)
    q['AuthorMinusTEL']=q['AuthorCommonReturn']-q['TELCommonReturn']
    q['AuthorWonMonth']=q['AuthorMinusTEL']>0
    q['TELWonMonth']=q['AuthorMinusTEL']<0
    # Difference between the creator-reported monthly return and our common
    # Open->Open reconstruction for the author's same holding. Diagnostic only.
    q['ReportedMinusCommon']=q['AuthorReturn']-q['AuthorCommonReturn']
    return q


def _v398_confusion(z):
    dev=z[(z['Sample']=='DEV') & z['TELPosition'].notna()].copy()
    cm=pd.crosstab(dev['AuthorPosition'],dev['TELPosition'],dropna=False)
    order=['TMV','TQQQ','TECL']
    cm=cm.reindex(index=order,columns=order,fill_value=0)
    cm.index.name='Author'; cm.columns.name='TEL'
    layer=pd.crosstab(dev['AuthorLayer'],dev['TELLayer'],dropna=False).reindex(index=['Treasury','Equity'],columns=['Treasury','Equity'],fill_value=0)
    layer.index.name='AuthorLayer'; layer.columns.name='TELLayer'
    return cm,layer


def _v398_disagreement_summary(z):
    dev=z[(z['Sample']=='DEV') & z['TELPosition'].notna()].copy()
    mis=dev[~dev['Match']].copy()
    rows=[]
    for typ,g in mis.groupby('DisagreementType',sort=False):
        active=g['AuthorMinusTEL'].dropna()
        rows.append({
            'DisagreementType':typ,'Months':len(g),'ShareOfDEV':len(g)/len(dev) if len(dev) else np.nan,
            'AuthorWins':int((active>0).sum()),'TELWins':int((active<0).sum()),'Ties':int((active==0).sum()),
            'MeanAuthorMinusTEL':active.mean() if len(active) else np.nan,
            'MedianAuthorMinusTEL':active.median() if len(active) else np.nan,
            'CompoundedAuthor':(1+g['AuthorCommonReturn'].dropna()).prod()-1 if g['AuthorCommonReturn'].notna().any() else np.nan,
            'CompoundedTEL':(1+g['TELCommonReturn'].dropna()).prod()-1 if g['TELCommonReturn'].notna().any() else np.nan,
        })
    return pd.DataFrame(rows)


def _v398_horizon_state_table(z):
    dev=z[(z['Sample']=='DEV') & z['TELPosition'].notna()].copy()
    lbs=['1M','3M','6M','12M','3M-1M','6M-1M','12M-1M']
    rows=[]
    for typ,g in dev.groupby('DisagreementType',sort=False):
        if typ=='MATCH': continue
        row={'DisagreementType':typ,'Months':len(g)}
        for lb in lbs:
            tc=f'TMF_minus_TMV__{lb}'
            ec=f'TQQQ_minus_TECL__{lb}'
            if tc in g:
                row[f'TMV_vote_{lb}']=float((g[tc]<0).mean())
                row[f'TreasurySpreadMean_{lb}']=float(g[tc].mean())
            if ec in g:
                row[f'TQQQ_vote_{lb}']=float((g[ec]>0).mean())
                row[f'EquitySpreadMean_{lb}']=float(g[ec].mean())
        rows.append(row)
    return pd.DataFrame(rows)


def _v398_run_table(z):
    dev=z[(z['Sample']=='DEV') & z['TELPosition'].notna()].copy().sort_index()
    rows=[]; detail=[]
    for col,label in [('AuthorPosition','Suzaku'),('TELPosition','TEL-DM')]:
        s=dev[col].astype(str)
        grp=s.ne(s.shift()).cumsum()
        runs=[]
        for _,g in dev.assign(_p=s,_grp=grp).groupby('_grp'):
            p=g['_p'].iloc[0]; n=len(g); start=g.index.min(); end=g.index.max()
            runs.append(n)
            detail.append({'Strategy':label,'Position':p,'StartMonth':str(start),'EndMonth':str(end),'RunMonths':n})
        rows.append({'Strategy':label,'Months':len(s),'Switches':max(len(runs)-1,0),'MeanRunMonths':np.mean(runs) if runs else np.nan,'MedianRunMonths':np.median(runs) if runs else np.nan,'MaxRunMonths':max(runs) if runs else np.nan})
    return pd.DataFrame(rows),pd.DataFrame(detail)


def _v398_switch_timing(z):
    dev=z[(z['Sample']=='DEV') & z['TELPosition'].notna()].copy().sort_index()
    def switches(col):
        x=dev[[col]].copy(); x['Prev']=x[col].shift(1)
        return x[(x[col]!=x['Prev']) & x['Prev'].notna()].copy()
    a=switches('AuthorPosition'); t=switches('TELPosition')
    rows=[]
    for m,r in a.iterrows():
        target=r['AuthorPosition']
        cand=t[t['TELPosition'].eq(target)]
        if cand.empty:
            rows.append({'AuthorSwitchMonth':str(m),'From':r['Prev'],'To':target,'NearestTELSwitchMonth':None,'TELMinusAuthorMonths':np.nan,'Within3M':False})
            continue
        offsets=np.array([(x.year-m.year)*12+(x.month-m.month) for x in cand.index],dtype=int)
        j=int(np.argmin(np.abs(offsets)))
        off=int(offsets[j]); tm=cand.index[j]
        rows.append({'AuthorSwitchMonth':str(m),'From':r['Prev'],'To':target,'NearestTELSwitchMonth':str(tm),'TELMinusAuthorMonths':off,'Within3M':abs(off)<=3})
    return pd.DataFrame(rows)


def _v398_stress(z):
    dev=z[(z['Sample']=='DEV') & z['TELPosition'].notna()].copy()
    windows=[('COVID','2020-02','2020-04'),('2022 inflation/rates','2022-01','2022-12'),('2023 Jul-Oct','2023-07','2023-10'),('2025 Feb-Apr','2025-02','2025-04')]
    rows=[]
    for name,s,e in windows:
        g=dev.loc[pd.Period(s,'M'):pd.Period(e,'M')].copy()
        if g.empty: continue
        rows.append({
            'Window':name,'Months':len(g),'Matches':int(g['Match'].sum()),'MismatchMonths':int((~g['Match']).sum()),
            'MatchRate':float(g['Match'].mean()),
            'SuzakuCommonReturn':float((1+g['AuthorCommonReturn'].dropna()).prod()-1),
            'TELCommonReturn':float((1+g['TELCommonReturn'].dropna()).prod()-1),
            'SuzakuMinusTEL':float((1+g['AuthorCommonReturn'].dropna()).prod()-(1+g['TELCommonReturn'].dropna()).prod()),
        })
    return pd.DataFrame(rows)


def _v398_metrics_monthly(s,name):
    x=pd.Series(s).dropna().astype(float)
    if x.empty: return {'Strategy':name}
    n=len(x); yrs=n/12.0
    cagr=(1+x).prod()**(1/yrs)-1 if yrs>0 else np.nan
    vol=x.std(ddof=1)*np.sqrt(12) if n>1 else np.nan
    sharpe=(x.mean()/x.std(ddof=1))*np.sqrt(12) if n>1 and x.std(ddof=1)>0 else np.nan
    neg=x[x<0]
    sortino=(x.mean()/np.sqrt((np.minimum(x,0)**2).mean()))*np.sqrt(12) if (np.minimum(x,0)**2).mean()>0 else np.nan
    eq=(1+x).cumprod(); dd=eq/eq.cummax()-1
    return {'Strategy':name,'Months':n,'CAGR':cagr,'Vol':vol,'MonthlyMaxDD':dd.min(),'Sharpe0':sharpe,'Sortino0':sortino,'PositiveMonths':(x>0).mean()}


def render_v398_tel_vs_suzaku_deep_audit(px_close,rf_bt,start,end):
    import io,zipfile
    st.markdown('### 🔬 v3.98 — TEL-DM vs シン朱雀-激攻 Deep Reverse-Engineering Audit LIGHT')
