# ================================================================
# v3.99 — TEL-DM Treasury 3M × 6M Confirmation Diagnostic LIGHT
# POST-HOC DIAGNOSTIC ONLY. No challenger / no trading rule is created.
# Hypothesis inherited from v3.98 disagreement audit:
#   Among months where the fixed TEL 3M Treasury router says TMV,
#   does independent 6M Treasury direction separate useful vs false-positive TMV calls?
# Fixed diagnostic split only: 6M confirms iff TMV 6M > TMF 6M.
# Forward payoff: next holding-month O2O TMV return minus the frozen TEL Equity
# engine choice (TQQQ vs TECL by 3M). DEV cutoff 2026-07-31.
# ================================================================
def _v399_treasury_confirmation_table(px_close,start,end):
    base=_v388_build(px_close)
    z=_v398_tel_from_features(base)
    r=_v398_monthly_open_returns(start,end)
    z=z.join(r.add_prefix('O2O_'),how='left')
    a3='TMF_minus_TMV__3M'; a6='TMF_minus_TMV__6M'; e3='TQQQ_minus_TECL__3M'
    valid=z[[a3,a6,e3]].notna().all(axis=1)
    z=z[valid].copy()
    z['TEL3M_Treasury']=z[a3] < 0
    z['Confirm6M']=z[a6] < 0
    z['ConfirmationState']=np.where(z['Confirm6M'],'3M+6M CONFIRM','3M ONLY / 6M CONFLICT')
    z['FrozenEquityChoice']=np.where(z[e3]>0,'TQQQ','TECL')
    z['TMV_O2O']=z['O2O_TMV']
    z['Equity_O2O']=np.where(z['FrozenEquityChoice'].eq('TQQQ'),z['O2O_TQQQ'],z['O2O_TECL'])
    z['TMV_minus_Equity']=z['TMV_O2O']-z['Equity_O2O']
    z['TMV_Wins']=z['TMV_minus_Equity']>0
    z['SuzakuLayer']=np.where(z['AuthorPosition'].eq('TMV'),'Treasury','Equity')
    return z


def _v399_summary(g):
    x=g['TMV_minus_Equity'].dropna()
    return {
        'Months':len(g),'ForwardMonths':len(x),
        'Mean_TMV_minus_Equity':x.mean() if len(x) else np.nan,
        'Median_TMV_minus_Equity':x.median() if len(x) else np.nan,
        'TMV_WinRate':(x>0).mean() if len(x) else np.nan,
        'P10_TMV_minus_Equity':x.quantile(.10) if len(x) else np.nan,
        'P90_TMV_minus_Equity':x.quantile(.90) if len(x) else np.nan,
        'Compounded_TMV':(1+g['TMV_O2O'].dropna()).prod()-1 if g['TMV_O2O'].notna().any() else np.nan,
        'Compounded_Equity':(1+g['Equity_O2O'].dropna()).prod()-1 if g['Equity_O2O'].notna().any() else np.nan,
        'SuzakuTreasuryShare':g['AuthorPosition'].eq('TMV').mean() if len(g) else np.nan,
    }


def _v399_era_table(dev):
    eras=[('2011-2014','2011-01','2014-12'),('2015-2018','2015-01','2018-12'),('2019-2022','2019-01','2022-12'),('2023-2026-07','2023-01','2026-07')]
    rows=[]
    for en,a,b in eras:
        q=dev[(dev.index>=pd.Period(a,'M'))&(dev.index<=pd.Period(b,'M'))]
        for state,g in q.groupby('ConfirmationState'):
            rows.append({'Era':en,'State':state}|_v399_summary(g))
    return pd.DataFrame(rows)


def _v399_cpcv(dev):
    # Diagnostic stability only: 8 chronological groups, all 28 two-group holdouts.
    d=dev[dev['TEL3M_Treasury'] & dev['TMV_minus_Equity'].notna()].copy().sort_index()
    if len(d)<16: return pd.DataFrame()
    grp=np.minimum((np.arange(len(d))*8//len(d)),7)
    d['ChronoGroup']=grp+1
    rows=[]
    import itertools
    for a,b in itertools.combinations(range(1,9),2):
        q=d[d['ChronoGroup'].isin([a,b])]
        c=q[q['Confirm6M']]; k=q[~q['Confirm6M']]
        rows.append({
            'HoldoutGroups':f'{a}-{b}','Months':len(q),
            'ConfirmMonths':len(c),'ConflictMonths':len(k),
            'ConfirmMeanSpread':c['TMV_minus_Equity'].mean() if len(c) else np.nan,
            'ConflictMeanSpread':k['TMV_minus_Equity'].mean() if len(k) else np.nan,
            'Separation_ConfirmMinusConflict':(c['TMV_minus_Equity'].mean()-k['TMV_minus_Equity'].mean()) if len(c) and len(k) else np.nan,
            'ConfirmTMVWinRate':c['TMV_Wins'].mean() if len(c) else np.nan,
            'ConflictTMVWinRate':k['TMV_Wins'].mean() if len(k) else np.nan,
        })
    return pd.DataFrame(rows)


