# ================================================================
# v3.92 — TEL-DM Multi-Horizon Consensus / Sequential Screen Audit LIGHT
# Research-only. Family-internal screening, NOT FoF winner selection.
# Fixed horizon set comes from the creator's stated ALM inspection menu:
#   1M, 3M, 6M, 12M, 3M-1M, 6M-1M, 12M-1M.
# No horizon weights, no threshold sweep, no parameter tuning.
# For each pair at month-end, each horizon casts one binary vote.
# Majority (4/7) determines the pair winner.
# Sequential architecture:
#   Layer 1 Treasury: majority TMV > TMF => TMV.
#   Else Layer 2 Equity: majority TQQQ > TECL => TQQQ, otherwise TECL.
# Signal month-end -> next first tradable OPEN. Open-to-Open thereafter.
# Evaluate both standalone TEL-DM and its role inside the 4-family EW FoF.
# ================================================================
def _v392_lookback_panel(me):
    p={}
    p['1M']=me/me.shift(1)-1.0
    p['3M']=me/me.shift(3)-1.0
    p['6M']=me/me.shift(6)-1.0
    p['12M']=me/me.shift(12)-1.0
    p['3M-1M']=me.shift(1)/me.shift(3)-1.0
    p['6M-1M']=me.shift(1)/me.shift(6)-1.0
    p['12M-1M']=me.shift(1)/me.shift(12)-1.0
    return p


def _v392_tel_dm_consensus(px_close,start,end):
    need=['TMF','TMV','TQQQ','TECL']
    closes=px_close.reindex(columns=[c for c in need if c in px_close.columns]).copy()
    missing=[c for c in need if c not in closes.columns]
    if missing:
        closes=closes.join(get_close(tuple(missing),start,end),how='outer').sort_index().ffill()
    opens=get_open(tuple(need),start,end).sort_index().ffill()
    idx=pd.DatetimeIndex(opens.index).sort_values()
    closes=closes.sort_index().ffill()
    me=closes[need].resample('ME').last()
    lbs=_v392_lookback_panel(me)
    names=list(lbs.keys())

    votes_t=pd.DataFrame(index=me.index,columns=names,dtype=float)
    votes_e=pd.DataFrame(index=me.index,columns=names,dtype=float)
    for nm,m in lbs.items():
        vt=(m['TMV']>m['TMF']).astype(float)
        ve=(m['TQQQ']>m['TECL']).astype(float)
        valid_t=m[['TMV','TMF']].notna().all(axis=1)
        valid_e=m[['TQQQ','TECL']].notna().all(axis=1)
        votes_t.loc[valid_t,nm]=vt.loc[valid_t]
        votes_e.loc[valid_e,nm]=ve.loc[valid_e]

    t_count=votes_t.sum(axis=1,min_count=7)
    e_count=votes_e.sum(axis=1,min_count=7)
    valid=t_count.notna() & e_count.notna()
    sig=pd.Series(pd.NA,index=me.index,dtype='object',name='ConsensusSignal')
    choose_tmv=valid & (t_count>=4)
    sig.loc[choose_tmv]='TMV'
    eq=valid & ~choose_tmv
    sig.loc[eq & (e_count>=4)]='TQQQ'
    sig.loc[eq & (e_count<4)]='TECL'

    pos_open=pd.Series(pd.NA,index=idx,dtype='object',name='PositionAtOpen')
    audit=[]
    for dt,val in sig.dropna().items():
        cand=idx[idx>pd.Timestamp(dt)]
        if len(cand)==0: continue
        e=cand[0]
        pos_open.loc[e]=val
        row={'SignalMonthEnd':dt,'EntryOpen':e,'Signal':val,
             'Treasury_TMV_Votes':int(t_count.loc[dt]),'Equity_TQQQ_Votes':int(e_count.loc[dt])}
        for nm in names:
            row[f'Treasury_{nm}_TMVvote']=votes_t.loc[dt,nm]
            row[f'Equity_{nm}_TQQQvote']=votes_e.loc[dt,nm]
        audit.append(row)
    pos_open=pos_open.ffill()
    ar=opens.pct_change(fill_method=None)
    hold=pos_open.shift(1)
    ret=pd.Series(np.nan,index=idx,dtype=float,name='TEL-DM Consensus7')
    for a in need:
        m=hold.eq(a)
        ret.loc[m]=ar.loc[m,a]
    return ret.dropna(),pd.DataFrame(audit),sig,pos_open,t_count,e_count,votes_t,votes_e


def _v392_fof_with_tel_variant(px_close,rf_bt,start,end,tel_variant):
    cutoff=pd.Timestamp('2026-07-31')
    _,famd=_v390_build(px_close,rf_bt,start,end)
    famd=famd.loc[:cutoff].copy()
    famd['TEL-DM']=tel_variant.reindex(famd.index)
    famd=famd.dropna()
    fof=_v390_monthly_rebalanced_ew(famd[['MOM','MR','VIX','TEL-DM']]).rename('4F EW + TEL Consensus7')
    return fof.loc[:cutoff],famd


def render_v392_tel_dm_multihorizon_consensus(px_close,rf_bt,start,end):
    import io,zipfile
    st.markdown('### 🧭 v3.92 — TEL-DM Multi-Horizon Consensus Audit LIGHT')
    st.caption('v3.91でPF winner selectionがREJECTだったため、FoF配分ではなくTEL-DM family内部のSequential Screeningへ移ります。')
    st.info('固定7 horizon = 1M / 3M / 6M / 12M / 3M−1M / 6M−1M / 12M−1M。各horizonは1票。Layer 1はTMV vs TMF、Layer 2はTQQQ vs TECL。4/7多数決のみで決定します。')
    st.warning('これは作者ALMの完全再現ではなく、作者が挙げたlookback群を使うparameter-free consensus proxyです。結果を見て票数閾値・horizon weight・lookback集合を変更しません。3M TEL-DMは作者ラベル由来なので真のOOSではありません。')
    if not st.button('TEL-DM内部 Multi-Horizon Screeningを検証',type='primary',use_container_width=True,key='run_v392'):
        return
    with st.spinner('3M control / Consensus7 / 4-family FoFを構築し、頑健性を監査中…'):
        cutoff=pd.Timestamp('2026-07-31')
        tel3,a3,_,s3,_=_v389_layered_dm(px_close,start,end)
        telc,ac,sc,pc,tc,ec,vt,ve=_v392_tel_dm_consensus(px_close,start,end)
        tel3=tel3.loc[:cutoff]; telc=telc.loc[:cutoff]
        stand=pd.concat([tel3.rename('TEL-DM 3M Control'),telc.rename('TEL-DM Consensus7')],axis=1).dropna()
        # FoF control comes from v3.90 exact fixed ALL4 with TEL-DM 3M.
