# v4.00 — My FoF v1: 4-Family Architecture Audit LIGHT
# Research architecture only; NO weight optimization.
# Frozen families: MOM / MR / VIX / TEL-DM.
# Control FoF = monthly-rebalanced 25% each.
# Diagnostics: standalone alpha/beta, raw/residual/up/down correlations,
# Effective Bets, Leave-One-F-Out, rolling alpha, stress and contribution.
# Development cutoff = 2026-07-31.
# ================================================================
def _v400_ew_with_contrib(famd):
    x=famd.dropna().copy().sort_index()
    if x.empty: return pd.Series(dtype=float),pd.DataFrame()
    pret=[]; contrib=[]
    for _,g in x.groupby(x.index.to_period('M')):
        wealth=pd.Series(1.0,index=g.columns,dtype=float)
        for dt,row in g.iterrows():
            w=wealth/wealth.sum()
            c=w*row
            pret.append((dt,float(c.sum())))
            contrib.append(pd.Series(c,index=g.columns,name=dt))
            wealth=wealth*(1.0+row)
    return pd.Series(dict(pret)).sort_index(),pd.DataFrame(contrib).sort_index()


def _v400_residuals(monthly,spy):
    z=monthly.join(spy.rename('SPY'),how='inner').dropna()
    out=pd.DataFrame(index=z.index)
    x=z['SPY'].values.astype(float)
    X=np.column_stack([np.ones(len(x)),x])
    for c in monthly.columns:
        y=z[c].values.astype(float)
        try:
            b=np.linalg.lstsq(X,y,rcond=None)[0]
            out[c]=y-X@b
        except Exception:
            out[c]=np.nan
    return out


def _v400_roll_alpha(monthly,spy,window=36):
    z=monthly.join(spy.rename('SPY'),how='inner').dropna()
    rows=[]
    for i in range(window-1,len(z)):
        g=z.iloc[i-window+1:i+1]
        x=g['SPY'].values.astype(float); X=np.column_stack([np.ones(len(x)),x])
        row={'Date':g.index[-1]}
        for c in monthly.columns:
            y=g[c].values.astype(float)
            try:
                a=np.linalg.lstsq(X,y,rcond=None)[0][0]
                row[c]=float((1+a)**12-1) if a>-1 else np.nan
            except Exception: row[c]=np.nan
        rows.append(row)
    return pd.DataFrame(rows).set_index('Date') if rows else pd.DataFrame()


def _v400_stress(daily):
    windows=[('2011 Jul-Oct','2011-07-01','2011-10-31'),('2015 Jul-Aug','2015-07-01','2015-08-31'),
             ('2018 Q4','2018-10-01','2018-12-31'),('2019-05','2019-05-01','2019-05-31'),
             ('COVID','2020-02-01','2020-04-30'),('2020 Sep','2020-09-01','2020-09-30'),
             ('2022 Apr-Oct','2022-04-01','2022-10-31'),('2023 Jul-Oct','2023-07-01','2023-10-31'),
             ('2025 Feb-Apr','2025-02-01','2025-04-30')]
    rows=[]
    for nm,a,b in windows:
        row={'Stress':nm,'Start':a,'End':b}
        for c in daily.columns:
            x=daily.loc[a:b,c].dropna(); eq=(1+x).cumprod(); dd=eq/eq.cummax()-1
            row[c+' Return']=float((1+x).prod()-1) if len(x) else np.nan
            row[c+' MaxDD']=float(dd.min()) if len(x) else np.nan
        rows.append(row)
    return pd.DataFrame(rows)


