# ================================================================
# v4.01 — My FoF v2: Dual-Momentum Family Selector Audit LIGHT
# Fixed meta-DM hypothesis over the four Frozen families.
# Signal at month-end: 12M-1M family momentum vs matched RF momentum.
# Relative selection among absolute-momentum-eligible families.
# Top1 = best eligible F; Top2 = equal-weight best two eligible Fs.
# If none eligible -> CASH. Signal applies next calendar month.
# No horizon/threshold/weight sweep. DEV cutoff = 2026-07-31.
# ================================================================
def _v401_monthly_rf(famd, rf_rates):
    rows=[]
    for p,g in famd.groupby(famd.index.to_period('M')):
        if len(g):
            rows.append((p, rf_return(rf_rates, g.index[0], g.index[-1])))
    return pd.Series(dict(rows), name='RF').sort_index()


def _v401_cash_daily(index, rf_rates):
    idx=pd.DatetimeIndex(index).sort_values()
    out=pd.Series(0.0,index=idx,name='CASH')
    if len(idx)<2: return out
    rfs=rf_rates.sort_index()
    for i in range(1,len(idx)):
        a,b=idx[i-1],idx[i]
        y=rfs.loc[:a].dropna()
        rate=float(y.iloc[-1])/100.0 if len(y) else 0.0
        days=max((b.normalize()-a.normalize()).days,1)
        out.iloc[i]=(1.0+rate)**(days/365.25)-1.0
    return out


def _v401_meta_dm_weights(famd, rf_rates, topn=1):
    cols=list(famd.columns)
    fm=(1.0+famd).groupby(famd.index.to_period('M')).prod().sub(1.0)
    rfm=_v401_monthly_rf(famd,rf_rates).reindex(fm.index).fillna(0.0)
    sig=[]
    # Fixed 12M-1M: at month-end p, exclude p and use the preceding 11 completed monthly returns.
    for i,p in enumerate(fm.index):
        row={'SignalMonth':str(p),'ApplyMonth':str(p+1),'RF_12M1M':np.nan}
        for c in cols: row[c+'_12M1M']=np.nan
        row.update({c:0.0 for c in cols}); row['CASH']=0.0; row['EligibleCount']=0; row['Selected']='INSUFFICIENT'
        if i>=11:
            hist=fm.iloc[i-11:i]
            mom=(1.0+hist).prod()-1.0
            rf_mom=float((1.0+rfm.iloc[i-11:i]).prod()-1.0)
            eligible=mom[mom>rf_mom].sort_values(ascending=False)
            for c in cols: row[c+'_12M1M']=float(mom[c])
            row['RF_12M1M']=rf_mom; row['EligibleCount']=int(len(eligible))
            if len(eligible)==0:
                row['CASH']=1.0; row['Selected']='CASH'
            else:
                chosen=list(eligible.index[:min(topn,len(eligible))])
                for c in chosen: row[c]=1.0/len(chosen)
                row['Selected']='+'.join(chosen)
        sig.append(row)
    return pd.DataFrame(sig)


def _v401_apply_monthly_weights(famd, rf_rates, sig):
    cash=_v401_cash_daily(famd.index,rf_rates)
    wcols=list(famd.columns)+['CASH']
    mp={pd.Period(r['ApplyMonth'],freq='M'):r for _,r in sig.iterrows() if r['Selected']!='INSUFFICIENT'}
    ret=[]; wrows=[]
    for p,g in famd.groupby(famd.index.to_period('M')):
        r=mp.get(p)
        if r is None: continue
        w=pd.Series({c:float(r[c]) for c in wcols})
        for dt,row in g.iterrows():
            rr=pd.concat([row,cash.loc[[dt]]]).copy()
            rr.index=wcols
            ret.append((dt,float((w*rr).sum())))
            wr=w.copy(); wr.name=dt; wrows.append(wr)
    return pd.Series(dict(ret)).sort_index(), pd.DataFrame(wrows).sort_index()


def _v401_signal_summary(sig,label):
    z=sig.loc[sig['Selected'].ne('INSUFFICIENT')].copy()
    rows=[]
    for c in ['MOM','MR','VIX','TEL-DM','CASH']:
        rows.append({'Variant':label,'F':c,'Mean Weight':float(z[c].mean()) if len(z) else np.nan,
                     'Months Active':int((z[c]>0).sum()) if len(z) else 0})
    return pd.DataFrame(rows)


