# ================================================================
# v4.02 — My FoF: Family Price vs Sharpe vs Sortino Momentum Diagnostic LIGHT
# Fixed 12 completed monthly observations at each month-end.
# Signal is diagnostic only: rank the four Frozen families by Price / Sharpe / Sortino,
# then observe NEXT-month raw and beta-adjusted residual returns.
# No allocation challenger, no horizon sweep, no score-weight tuning.
# RF is matched monthly RF from the app's canonical rf_return().
# Beta for next-month residual is estimated only from trailing 36 completed months
# available at the signal month-end. DEV cutoff = 2026-07-31.
# ================================================================

def _v402_monthly_family_and_rf(famd, rf_rates, spy_daily):
    fm=(1.0+famd).resample('ME').prod(min_count=1).sub(1.0)
    sm=(1.0+spy_daily.reindex(famd.index).fillna(0.0)).resample('ME').prod(min_count=1).sub(1.0).rename('SPY')
    rows=[]
    for p,g in famd.groupby(famd.index.to_period('M')):
        if len(g):
            rows.append((p, rf_return(rf_rates, g.index[0], g.index[-1])))
    rf=pd.Series(dict(rows),name='RF')
    rf.index=rf.index.to_timestamp(how='end').normalize()
    rf=rf.reindex(fm.index).fillna(0.0)
    return fm,sm.reindex(fm.index),rf


def _v402_scores(fm,rfm):
    fams=list(fm.columns)
    rows=[]
    for i,dt in enumerate(fm.index):
        if i<11: continue
        hist=fm.iloc[i-11:i+1]
        rh=rfm.iloc[i-11:i+1]
        if len(hist)!=12: continue
        for f in fams:
            x=hist[f].astype(float)
            ex=x-rh.values
            price=float((1.0+x).prod()-1.0)
            sd=float(ex.std(ddof=1))
            sharpe=float(ex.mean()/sd*np.sqrt(12.0)) if sd>1e-12 else np.nan
            down=ex[ex<0]
            ddev=float(np.sqrt(np.mean(np.square(down)))) if len(down) else 0.0
            sortino=float(ex.mean()/ddev*np.sqrt(12.0)) if ddev>1e-12 else (np.inf if ex.mean()>0 else np.nan)
            rows.append({'SignalDate':dt,'ApplyDate': fm.index[i+1] if i+1<len(fm) else pd.NaT,
                         'Family':f,'Price12M':price,'Sharpe12M':sharpe,'Sortino12M':sortino})
    z=pd.DataFrame(rows)
    if z.empty: return z
    for score in ['Price12M','Sharpe12M','Sortino12M']:
        z[score+'_Rank']=z.groupby('SignalDate')[score].rank(method='first',ascending=False)
    return z


def _v402_attach_forward(z,fm,sm,rfm):
    if z.empty: return z
    fams=list(fm.columns)
    beta_rows=[]
    # trailing 36M beta known at each signal month-end, using excess monthly returns
    for i,dt in enumerate(fm.index):
        if i<35: continue
        hidx=fm.index[i-35:i+1]
        mx=(sm.loc[hidx]-rfm.loc[hidx]).astype(float)
        vx=float(mx.var(ddof=1))
        for f in fams:
            y=(fm.loc[hidx,f]-rfm.loc[hidx]).astype(float)
            beta=float(y.cov(mx)/vx) if vx>1e-12 else np.nan
            beta_rows.append({'SignalDate':dt,'Family':f,'Beta36M':beta})
    bet=pd.DataFrame(beta_rows)
    o=z.merge(bet,on=['SignalDate','Family'],how='left')
    fr=[]
    for _,r in o.iterrows():
        ad=r['ApplyDate']; f=r['Family']
        if pd.isna(ad) or ad not in fm.index:
            fr.append((np.nan,np.nan,np.nan,np.nan)); continue
        raw=float(fm.at[ad,f]); spy=float(sm.at[ad]); rf=float(rfm.at[ad]); b=r['Beta36M']
        resid=float((raw-rf)-b*(spy-rf)) if pd.notna(b) else np.nan
        fr.append((raw,spy,rf,resid))
    arr=np.asarray(fr,dtype=float)
    o['NextReturn']=arr[:,0]; o['NextSPY']=arr[:,1]; o['NextRF']=arr[:,2]; o['NextResidual']=arr[:,3]
    return o


def _v402_rank_summary(a,score):
    rk=score+'_Rank'
    q=a.dropna(subset=[rk,'NextReturn','NextResidual']).copy()
    rows=[]
    for r in [1,2,3,4]:
        g=q.loc[q[rk].eq(r)]
        rows.append({'Score':score,'Rank':r,'N':len(g),
                     'Mean Next Return':g['NextReturn'].mean(),'Median Next Return':g['NextReturn'].median(),
                     'Positive Next Return':(g['NextReturn']>0).mean(),
                     'Mean Next Residual':g['NextResidual'].mean(),'Median Next Residual':g['NextResidual'].median(),
                     'Positive Next Residual':(g['NextResidual']>0).mean()})
    top=q.loc[q[rk].le(2)]; bot=q.loc[q[rk].ge(3)]
    rows.append({'Score':score,'Rank':'Top2-Bottom2','N':min(len(top),len(bot)),
                 'Mean Next Return':top['NextReturn'].mean()-bot['NextReturn'].mean(),
                 'Median Next Return':top['NextReturn'].median()-bot['NextReturn'].median(),
                 'Positive Next Return':np.nan,
                 'Mean Next Residual':top['NextResidual'].mean()-bot['NextResidual'].mean(),
                 'Median Next Residual':top['NextResidual'].median()-bot['NextResidual'].median(),
                 'Positive Next Residual':np.nan})
    return pd.DataFrame(rows)


def _v402_era_summary(a,score):
    rk=score+'_Rank'; q=a.dropna(subset=[rk,'NextResidual']).copy()
    if q.empty: return pd.DataFrame()
    y=pd.to_datetime(q['SignalDate']).dt.year
    q['Era']=pd.cut(y,bins=[2010,2014,2018,2022,2026],labels=['2011-14','2015-18','2019-22','2023-26'])
    rows=[]
    for era,g in q.groupby('Era',observed=True):
        top=g[g[rk].le(2)]; bot=g[g[rk].ge(3)]
        rows.append({'Score':score,'Era':str(era),'N':len(g),
                     'Top2 Mean Next Return':top['NextReturn'].mean(),'Bottom2 Mean Next Return':bot['NextReturn'].mean(),
                     'Top2-Bottom2 Return':top['NextReturn'].mean()-bot['NextReturn'].mean(),
                     'Top2 Mean Residual':top['NextResidual'].mean(),'Bottom2 Mean Residual':bot['NextResidual'].mean(),
                     'Top2-Bottom2 Residual':top['NextResidual'].mean()-bot['NextResidual'].mean()})
    return pd.DataFrame(rows)


def _v402_wf_blocks(a,score,nblocks=13):
    rk=score+'_Rank'; q=a.dropna(subset=[rk,'NextResidual']).copy()
    dates=np.array(sorted(pd.to_datetime(q['SignalDate']).unique()))
    chunks=np.array_split(dates,min(nblocks,len(dates))) if len(dates) else []
    rows=[]
    for j,ch in enumerate(chunks,1):
        if not len(ch): continue
        g=q[q['SignalDate'].isin(ch)]; top=g[g[rk].le(2)]; bot=g[g[rk].ge(3)]
        rows.append({'Score':score,'Block':j,'Start':pd.Timestamp(ch[0]),'End':pd.Timestamp(ch[-1]),'N':len(g),
                     'Top2-Bottom2 Return':top['NextReturn'].mean()-bot['NextReturn'].mean(),
                     'Top2-Bottom2 Residual':top['NextResidual'].mean()-bot['NextResidual'].mean(),
                     'Residual Positive':(top['NextResidual'].mean()-bot['NextResidual'].mean())>0})
    return pd.DataFrame(rows)


def _v402_cpcv_style(a,score):
    rk=score+'_Rank'; q=a.dropna(subset=[rk,'NextResidual']).copy()
    dates=np.array(sorted(pd.to_datetime(q['SignalDate']).unique()))
    groups=np.array_split(dates,8) if len(dates)>=8 else []
    rows=[]
    import itertools
    for k,(i,j) in enumerate(itertools.combinations(range(len(groups)),2),1):
        hold=np.concatenate([groups[i],groups[j]])
        g=q[q['SignalDate'].isin(hold)]; top=g[g[rk].le(2)]; bot=g[g[rk].ge(3)]
        dr=top['NextReturn'].mean()-bot['NextReturn'].mean(); da=top['NextResidual'].mean()-bot['NextResidual'].mean()
        rows.append({'Score':score,'Split':k,'Groups':f'{i+1}+{j+1}','N':len(g),
                     'Top2-Bottom2 Return':dr,'Top2-Bottom2 Residual':da,
                     'Positive Return Spread':dr>0,'Positive Residual Spread':da>0})
    return pd.DataFrame(rows)


def _v402_rank_persistence(a,score):
    rk=score+'_Rank'; q=a.dropna(subset=[rk]).copy().sort_values(['Family','SignalDate'])
    q['PrevRank']=q.groupby('Family')[rk].shift(1)
    z=q.dropna(subset=['PrevRank'])
    return pd.DataFrame([{
        'Score':score,'Observations':len(z),
        'Exact Rank Persistence':float((z[rk]==z['PrevRank']).mean()) if len(z) else np.nan,
        'Top2 Persistence':float(((z[rk]<=2)==(z['PrevRank']<=2)).mean()) if len(z) else np.nan,
        'Mean Absolute Rank Change':float((z[rk]-z['PrevRank']).abs().mean()) if len(z) else np.nan,
    }])


def render_v402_family_momentum_diagnostic(px_close,rf_bt,start,end):
    import io,zipfile
    st.markdown('### 🧪 v4.02 — Family Price vs Sharpe vs Sortino Momentum Diagnostic LIGHT')
    st.caption('バムさんの「価格モメンタムに加えてSharpe / SortinoでFamilyを評価する」着想を、Frozen 4F = MOM / MR / VIX / TEL-DMで診断します。')
    st.info('各月末で直近12 completed monthsを固定使用。Price=12M複利return、Sharpe=matched RFに対する月次excess returnの年率Sharpe、Sortino=同excess returnのdownside deviation版。各scoreで4FをRank 1〜4にし、翌月のraw returnとSPY β-adjusted residual returnを観測します。')
    st.warning('今回はselector/tilt戦略を作りません。12M固定、score混合なし、thresholdなし、weight最適化なし。βは各signal時点までの過去36Mだけで推定。DEV cutoff = 2026-07-31。結果を見てPrice+Sharpeの混合比を作ることもしません。')
    if not st.button('Family Momentum Diagnosticを実行',type='primary',use_container_width=True,key='run_v402'):
        return
    with st.spinner('4Fを一度だけ構築し、Price / Sharpe / Sortino rankの翌月情報価値を監査中…'):
        _,famd=_v390_build(px_close,rf_bt,start,end)
        famd=famd[['MOM','MR','VIX','TEL-DM']].dropna().loc[:pd.Timestamp('2026-07-31')]
        spy_d=px_close['SPY'].pct_change(fill_method=None).reindex(famd.index)
        fm,sm,rfm=_v402_monthly_family_and_rf(famd,rf_bt,spy_d)
        z=_v402_scores(fm,rfm)
        a=_v402_attach_forward(z,fm,sm,rfm)
        scores=['Price12M','Sharpe12M','Sortino12M']
        rank=pd.concat([_v402_rank_summary(a,s) for s in scores],ignore_index=True)
        era=pd.concat([_v402_era_summary(a,s) for s in scores],ignore_index=True)
        wf=pd.concat([_v402_wf_blocks(a,s,13) for s in scores],ignore_index=True)
        cpcv=pd.concat([_v402_cpcv_style(a,s) for s in scores],ignore_index=True)
        pers=pd.concat([_v402_rank_persistence(a,s) for s in scores],ignore_index=True)
        comp=[]
        for s in scores:
            rr=rank[(rank['Score']==s)&(rank['Rank']=='Top2-Bottom2')].iloc[0]
            ww=wf[wf['Score']==s]; cc=cpcv[cpcv['Score']==s]
            comp.append({'Score':s,'Top2-Bottom2 Next Return':rr['Mean Next Return'],
                         'Top2-Bottom2 Next Residual':rr['Mean Next Residual'],
                         'WF Residual Wins':int(ww['Residual Positive'].sum()),'WF Blocks':len(ww),
                         'CPCV Residual Wins':int(cc['Positive Residual Spread'].sum()),'CPCV Splits':len(cc)})
        comp=pd.DataFrame(comp)
        sanity=pd.DataFrame([
            {'Check':'Family rows daily','Value':len(famd)},
            {'Check':'Monthly rows','Value':len(fm)},
            {'Check':'First monthly date','Value':str(fm.index.min().date())},
            {'Check':'Last monthly date','Value':str(fm.index.max().date())},
            {'Check':'Rank observations','Value':len(a)},
            {'Check':'Residual non-null','Value':int(a['NextResidual'].notna().sum())},
            {'Check':'DEV cutoff','Value':'2026-07-31'},
            {'Check':'Lookback','Value':'12 completed months'},
            {'Check':'Beta window','Value':'36 completed months, trailing only'},
        ])
    st.markdown('#### Score comparison')
    sh=comp.copy()
    for c in ['Top2-Bottom2 Next Return','Top2-Bottom2 Next Residual']: sh[c]=sh[c].map(lambda x:f'{x:.3%}')
    st.dataframe(sh,hide_index=True,use_container_width=True)
    st.markdown('#### Rank → next-month outcome')
    show=rank.copy()
    for c in ['Mean Next Return','Median Next Return','Positive Next Return','Mean Next Residual','Median Next Residual','Positive Next Residual']:
        show[c]=show[c].map(lambda x:'' if pd.isna(x) else f'{x:.3%}')
    st.dataframe(show,hide_index=True,use_container_width=True)
    st.markdown('#### Era stability'); st.dataframe(era.round(4),hide_index=True,use_container_width=True)
    st.markdown('#### WF chronological blocks'); st.dataframe(wf.round(4),hide_index=True,use_container_width=True)
    st.markdown('#### CPCV-style chronological holdouts'); st.dataframe(cpcv.round(4),hide_index=True,use_container_width=True)
    st.markdown('#### Rank persistence'); st.dataframe(pers.round(4),hide_index=True,use_container_width=True)
    st.caption('判定の核心は「Rank1/2が翌月のraw returnだけでなくβ-adjusted residualでもRank3/4を安定して上回るか」。単一full-sample CAGRは使いません。')

    files={'01_score_comparison.csv':comp,'02_rank_forward_summary.csv':rank,'03_month_level_scores_forward.csv':a,
           '04_era_stability.csv':era,'05_wf_blocks.csv':wf,'06_cpcv_style_holdouts.csv':cpcv,
           '07_rank_persistence.csv':pers,'08_family_monthly_returns.csv':fm.reset_index(),
           '09_spy_monthly_returns.csv':sm.reset_index(),'10_monthly_rf.csv':rfm.reset_index(),
           '11_family_daily_returns.csv':famd.reset_index(),'12_sanity.csv':sanity}
    b=io.BytesIO()
    with zipfile.ZipFile(b,'w',zipfile.ZIP_DEFLATED) as zf:
        for fn,df in files.items(): zf.writestr(fn,df.to_csv(index=False).encode('utf-8-sig'))
        zf.writestr('README.txt',(
            'v4.02 My FoF Family Price vs Sharpe vs Sortino Momentum Diagnostic LIGHT\n'
            'Frozen families: MOM / MR / VIX / TEL-DM.\n'
            'At each month-end, use exactly 12 completed monthly family returns. Signal applies diagnostically to the next month only.\n'
            'Price12M = compounded 12M family return. Sharpe12M = annualized mean monthly excess return / monthly SD, matched RF. Sortino12M = annualized mean monthly excess return / downside deviation, matched RF.\n'
            'NextResidual = (F_next-RF_next) - beta36*(SPY_next-RF_next), with beta36 estimated only from the trailing 36 completed months available at signal time.\n'
            'No selector/tilt strategy, no horizon sweep, no score mixing, no threshold/weight tuning. DEV cutoff=2026-07-31.\n'
            'This is hypothesis diagnosis inspired by the supplied Bam X comment; it does not assume Bam used these exact definitions.\n'
        ).encode('utf-8'))
