# v4.02e — TEL-DM Inverse Signal Mechanism Audit LIGHT
# Continuation of v4.02 family-momentum research.
# Frozen diagnostic only: no parameter/threshold/weight optimization.
# ================================================================
def _v402e_simple_ols(g,xcol='Price12M',ycol='NextResidual'):
    q=g[[xcol,ycol]].replace([np.inf,-np.inf],np.nan).dropna(); n=len(q)
    if n<8: return {'N':n,'Slope':np.nan,'HC1_t':np.nan,'R2':np.nan}
    x=q[xcol].to_numpy(float); y=q[ycol].to_numpy(float); X=np.column_stack([np.ones(n),x])
    inv=np.linalg.pinv(X.T@X); b=inv@(X.T@y); u=y-X@b; meat=np.zeros((2,2))
    for i in range(n):
        xi=X[i:i+1].T; meat+=(u[i]**2)*(xi@xi.T)
    cov=inv@meat@inv*n/max(n-2,1); se=float(np.sqrt(max(cov[1,1],0)))
    ss=float(((y-y.mean())**2).sum())
    return {'N':n,'Slope':float(b[1]),'HC1_t':float(b[1]/se) if se>0 else np.nan,'R2':1-float((u*u).sum()/ss) if ss>0 else np.nan}

def _v402e_tel_signal_audit(px_close,start,end):
    need=['TMF','TMV','TQQQ','TECL']; closes=px_close.copy()
    missing=[c for c in need if c not in closes.columns]
    if missing: closes=closes.join(get_close(tuple(missing),start,end),how='outer')
    me=closes[need].sort_index().ffill().resample('ME').last(); mom3=me/me.shift(3)-1.0
    valid=mom3.notna().all(axis=1); sig=pd.Series(pd.NA,index=me.index,dtype='object')
    sig.loc[valid & (mom3['TMV']>mom3['TMF'])]='TMV'
    eq=valid & ~(mom3['TMV']>mom3['TMF'])
    sig.loc[eq & (mom3['TQQQ']>mom3['TECL'])]='TQQQ'; sig.loc[eq & ~(mom3['TQQQ']>mom3['TECL'])]='TECL'
    a=mom3.rename(columns={c:c+'_3M' for c in need}); a['TELSignal']=sig
    a['Treasury_TMV']=sig.eq('TMV'); return a.dropna(subset=['TELSignal'])

