# ================================================================
# v4.02f — TEL-DM 12M Inverse Signal Decomposition / Falsification LIGHT
# Frozen follow-up to v4.02e. No optimization.
# Question: is the 12M inverse effect genuine medium-term mean reversion,
# or mostly a latest-1M reversal / internal-state composition artifact?
# ================================================================
def _v402f_ols_table(df, ycol, xcols, add_state_fe=False, hac_lags=3):
    import statsmodels.api as sm
    q=df[[ycol]+list(xcols)+(['TELSignal'] if add_state_fe else [])].replace([np.inf,-np.inf],np.nan).dropna().copy()
    if len(q) < max(12, len(xcols)+5):
        return pd.DataFrame([{'Term':x,'N':len(q),'Coef':np.nan,'HC1_t':np.nan,'HAC3_t':np.nan,'R2':np.nan} for x in xcols])
    X=q[list(xcols)].astype(float).copy()
    if add_state_fe:
        dummies=pd.get_dummies(q['TELSignal'].astype(str),prefix='State',drop_first=True,dtype=float)
        X=pd.concat([X.reset_index(drop=True),dummies.reset_index(drop=True)],axis=1)
    X=sm.add_constant(X,has_constant='add')
    y=q[ycol].astype(float).reset_index(drop=True)
    X=X.reset_index(drop=True)
    m=sm.OLS(y,X).fit()
    hc=m.get_robustcov_results(cov_type='HC1')
    hac=m.get_robustcov_results(cov_type='HAC',maxlags=hac_lags)
    names=list(m.params.index)
    out=[]
    for x in xcols:
        if x not in names: continue
        j=names.index(x)
        out.append({'Term':x,'N':len(q),'Coef':float(m.params[x]),'HC1_t':float(hc.tvalues[j]),'HAC3_t':float(hac.tvalues[j]),'R2':float(m.rsquared)})
    return pd.DataFrame(out)

def _v402f_month_end_values(values):
    """Robustly normalize array/Series/Index of dates to month-end Timestamps.
    Avoid pandas Series/RangeIndex .to_period dispatch differences across versions.
    """
    idx = pd.DatetimeIndex(pd.to_datetime(list(values), errors="coerce"))
    return idx.to_period("M").to_timestamp("M").normalize()

def render_v402f_tel_inverse_decomposition(px_close,rf_bt,start,end):
    import io, zipfile
    st.markdown('### 🧪 v4.02f — TEL-DM 12M Inverse Signal Decomposition / Falsification LIGHT')
    st.caption('v4.02eで確認したTEL-DM Price12M逆方向性が、最新1か月の反転・内部state構成・特定年への集中で説明できないかを固定手順で反証します。')
    st.info('事前固定：Price12Mを「Latest 1M」と「Prior 11M excluding latest month」に分解。NextResidualを主評価、NextReturnを副評価。HC1/HAC(3)、state FE、leave-one-calendar-year-outを実施。')
    st.warning('診断専用。lookback sweep、閾値探索、weight最適化、結果を見ての救済ルール追加は行いません。')
    if not st.button('v4.02f Decomposition / Falsificationを実行',type='primary',use_container_width=True,key='run_v402f'): return

    with st.spinner('TEL-DM 12M inverse signalを分解・反証中…'):
        _,famd=_v390_build(px_close,rf_bt,start,end)
        famd=famd[['MOM','MR','VIX','TEL-DM']].dropna().loc[:pd.Timestamp('2026-07-31')]
        spy_d=px_close['SPY'].pct_change(fill_method=None).reindex(famd.index)
        fm,sm,rfm=_v402_monthly_family_and_rf(famd,rf_bt,spy_d)
        base=_v402_attach_forward(_v402_scores(fm,rfm),fm,sm,rfm)
        tel=base[base['Family'].eq('TEL-DM')].copy().sort_values('SignalDate')
        sa=_v402e_tel_signal_audit(px_close,start,end).reset_index()
        sa=sa.rename(columns={sa.columns[0]:'SignalDate'})
        sa['SignalDate']=_v402f_month_end_values(sa['SignalDate'])
        tel['SignalDate']=_v402f_month_end_values(tel['SignalDate'])
        e=tel.merge(sa,on='SignalDate',how='left').sort_values('SignalDate')
        e['Branch']=np.where(e['TELSignal'].eq('TMV'),'Treasury',np.where(e['TELSignal'].isin(['TQQQ','TECL']),'Equity','Unknown'))

        # Frozen decomposition of the same 12 completed months used by Price12M.
        tel_m=fm['TEL-DM'].copy().sort_index()
        latest1=tel_m
        prior11=(1.0+tel_m.shift(1)).rolling(11,min_periods=11).apply(np.prod,raw=True)-1.0
        prior3=(1.0+tel_m.shift(1)).rolling(3,min_periods=3).apply(np.prod,raw=True)-1.0
        decomp=pd.DataFrame({'SignalDate':tel_m.index,'Latest1M':latest1.values,'Prior11M_ex1':prior11.values,'Prior3M_ex1':prior3.values})
        decomp['SignalDate']=_v402f_month_end_values(decomp['SignalDate'])
        e=e.merge(decomp,on='SignalDate',how='left')
        e['Rebuilt12M']=(1.0+e['Latest1M'])*(1.0+e['Prior11M_ex1'])-1.0
        e['Price12M_Rebuild_Error']=e['Rebuilt12M']-e['Price12M']
        e['Year']=e['SignalDate'].dt.year

        # 1) Univariate decomposition
        uni=[]
        for y in ['NextResidual','NextReturn']:
            for x in ['Price12M','Latest1M','Prior11M_ex1']:
                t=_v402f_ols_table(e,y,[x],False)
                if len(t):
                    r=t.iloc[0].to_dict(); r.update({'Model':'Univariate','Outcome':y,'StateFE':False}); uni.append(r)
        uni=pd.DataFrame(uni)

        # 2) Joint decomposition: latest 1M + preceding 11M
        joint=[]
        for y in ['NextResidual','NextReturn']:
            for fe in [False,True]:
                t=_v402f_ols_table(e,y,['Latest1M','Prior11M_ex1'],fe)
                for _,r0 in t.iterrows():
                    r=r0.to_dict(); r.update({'Model':'Joint 1M + prior11','Outcome':y,'StateFE':fe}); joint.append(r)
        joint=pd.DataFrame(joint)

        # 3) State-specific joint slopes (only where sample allows)
        state_rows=[]
        for state,g in e.groupby('TELSignal'):
            t=_v402f_ols_table(g,'NextResidual',['Latest1M','Prior11M_ex1'],False)
            for _,r0 in t.iterrows():
                r=r0.to_dict(); r.update({'TELSignal':state}); state_rows.append(r)
        state_joint=pd.DataFrame(state_rows)

        # 4) Leave-one-calendar-year-out: fixed influence guardrail.
        loo=[]
        q=e.dropna(subset=['NextResidual','Latest1M','Prior11M_ex1']).copy()
        years=sorted(q['Year'].unique())
        for yr in years:
            g=q[q['Year']!=yr]
            t=_v402f_ols_table(g,'NextResidual',['Latest1M','Prior11M_ex1'],True)
            for _,r0 in t.iterrows():
                r=r0.to_dict(); r.update({'ExcludedYear':int(yr)}); loo.append(r)
        loo=pd.DataFrame(loo)

        # 5) Chronological era summary of decomposition, no fitted thresholds.
        e['Era']=pd.cut(e['SignalDate'].dt.year,[2010,2014,2018,2022,2026],labels=['2011-14','2015-18','2019-22','2023-26'])
        era_rows=[]
        for er,g in e.dropna(subset=['Era']).groupby('Era',observed=True):
            t=_v402f_ols_table(g,'NextResidual',['Latest1M','Prior11M_ex1'],True)
            for _,r0 in t.iterrows():
                r=r0.to_dict(); r.update({'Era':str(er)}); era_rows.append(r)
        era=pd.DataFrame(era_rows)

        # 6) Fixed interpretation checks.
        jres=joint[(joint['Outcome']=='NextResidual') & (joint['StateFE']==True)]
        def _get(term,col):
            q=jres[jres['Term']==term]
            return float(q.iloc[0][col]) if len(q) else np.nan
        p11=_get('Prior11M_ex1','Coef'); t11=_get('Prior11M_ex1','HAC3_t')
        p1=_get('Latest1M','Coef'); t1=_get('Latest1M','HAC3_t')
        if np.isfinite(p11) and p11<0 and np.isfinite(t11) and abs(t11)>=1.96:
            verdict='A: Prior-11M inverse survives state FE and HAC(3) -> medium-term inverse regime hypothesis survives this falsification.'
        elif np.isfinite(p1) and p1<0 and np.isfinite(t1) and abs(t1)>=1.96 and (not np.isfinite(t11) or abs(t11)<1.96):
            verdict='B: Effect is mainly Latest-1M reversal -> reject interpreting Price12M as a medium-term inverse regime signal.'
        else:
            verdict='C: Decomposition is mixed/weak -> do not promote to implementation; require further validation or prospective OOS.'

        sanity=pd.DataFrame([
            {'Check':'DEV cutoff','Value':'2026-07-31'},
            {'Check':'Primary outcome','Value':'NextResidual'},
            {'Check':'Frozen decomposition','Value':'Price12M = Latest1M + prior 11 completed months multiplicatively'},
            {'Check':'State controls','Value':'TELSignal FE (TMV/TQQQ/TECL)'},
            {'Check':'Robust SE','Value':'HC1 + HAC(3)'},
            {'Check':'Influence guardrail','Value':'leave-one-calendar-year-out'},
            {'Check':'Max abs Price12M rebuild error','Value':float(e['Price12M_Rebuild_Error'].abs().max(skipna=True))},
            {'Check':'Optimization','Value':'NONE'},
            {'Check':'Interpretation','Value':verdict},
        ])

    st.markdown('#### 1. Univariate decomposition')
    show=uni.copy(); show['Coef per +10% predictor']=show['Coef']*0.10
    st.dataframe(show[['Outcome','Term','N','Coef per +10% predictor','HC1_t','HAC3_t','R2']].round(4),hide_index=True,use_container_width=True)
    st.markdown('#### 2. Joint Latest-1M + Prior-11M')
    show=joint.copy(); show['Coef per +10% predictor']=show['Coef']*0.10
    st.dataframe(show[['Outcome','StateFE','Term','N','Coef per +10% predictor','HC1_t','HAC3_t','R2']].round(4),hide_index=True,use_container_width=True)
    st.markdown('#### 3. TEL internal state × decomposition')
    show=state_joint.copy(); show['Coef per +10% predictor']=show['Coef']*0.10
    st.dataframe(show[['TELSignal','Term','N','Coef per +10% predictor','HC1_t','HAC3_t','R2']].round(4),hide_index=True,use_container_width=True)
    st.markdown('#### 4. Leave-one-calendar-year-out guardrail')
    show=loo.copy(); show['Coef per +10% predictor']=show['Coef']*0.10
    st.dataframe(show[['ExcludedYear','Term','N','Coef per +10% predictor','HC1_t','HAC3_t','R2']].round(4),hide_index=True,use_container_width=True)
    st.markdown('#### 5. Era stability')
    show=era.copy(); show['Coef per +10% predictor']=show['Coef']*0.10
    st.dataframe(show[['Era','Term','N','Coef per +10% predictor','HC1_t','HAC3_t','R2']].round(4),hide_index=True,use_container_width=True)
    st.markdown('#### Fixed interpretation')
    st.info(verdict)

    files={
        '01_univariate_decomposition.csv':uni,
        '02_joint_decomposition.csv':joint,
        '03_state_joint_decomposition.csv':state_joint,
        '04_leave_one_year_out.csv':loo,
        '05_era_decomposition.csv':era,
        '06_tel_month_level_decomposed.csv':e,
        '07_tel_signal_audit.csv':sa,
        '08_family_monthly_returns.csv':fm.reset_index(),
        '09_monthly_rf.csv':rfm.reset_index(),
        '10_sanity_and_fixed_interpretation.csv':sanity,
    }
    b=io.BytesIO()
    with zipfile.ZipFile(b,'w',zipfile.ZIP_DEFLATED) as zf:
        for fn,df in files.items(): zf.writestr(fn,df.to_csv(index=False).encode('utf-8-sig'))
        zf.writestr('README.txt',(
            'v4.02f TEL-DM 12M Inverse Signal Decomposition / Falsification LIGHT\n'
            'Frozen follow-up to v4.02e. No optimization. DEV cutoff=2026-07-31.\n'
            'Primary question: whether the v4.02e Price12M inverse effect survives decomposition into Latest1M and Prior11M excluding latest month, TEL internal-state fixed effects, HAC(3), and leave-one-calendar-year-out guardrails.\n'
            'This is historical/pseudo-OOS falsification, not new prospective OOS.\n'
        ).encode('utf-8'))
    st.download_button('📦 v4.02f Decomposition / Falsification 検証ZIP',data=b.getvalue(),file_name='v402f_tel_dm_inverse_decomposition_falsification.zip',mime='application/zip',use_container_width=True,on_click='ignore',key='dl_v402f')

# ================================================================
# v4.02g — TEL-DM Inverse Economic Mechanism / Orthogonality Audit LIGHT
# Frozen continuation of v4.02f. Diagnostic only; no optimization.
# Primary inherited signal = TEL-DM Price12M. Prior11M is a pre-declared
# decomposition-confirmatory signal, not a replacement lookback.
# Controls are fixed BEFORE this run: SPY Price12M, TEL state FE, other-family
# Price12M levels (MOM/MR/VIX), TEL cross-sectional Price rank, and Beta36M.
# DEV cutoff = 2026-07-31. NextResidual remains the primary outcome.
# ================================================================

def _v402g_fit(df, y, xcols, state_fe=False, hac_lags=3):
    import statsmodels.api as sm
    cols=[y]+list(xcols)+(['TELSignal'] if state_fe else [])
    z=df[cols].copy().dropna()
    if len(z)<30: return pd.DataFrame(), {'N':len(z),'R2':np.nan,'AdjR2':np.nan,'CondNo':np.nan}
    X=z[list(xcols)].astype(float).copy()
    if state_fe:
        d=pd.get_dummies(z['TELSignal'].astype(str),prefix='State',drop_first=True,dtype=float)
        X=pd.concat([X,d],axis=1)
    X=sm.add_constant(X,has_constant='add')
    m=sm.OLS(z[y].astype(float),X).fit()
    hc=m.get_robustcov_results(cov_type='HC1')
    ha=m.get_robustcov_results(cov_type='HAC',maxlags=hac_lags)
    names=list(m.params.index)
    out=pd.DataFrame({'Term':names,'Coef':m.params.values,'SE_OLS':m.bse.values,
                      't_OLS':m.tvalues,'p_OLS':m.pvalues,
                      'SE_HC1':hc.bse,'t_HC1':hc.tvalues,'p_HC1':hc.pvalues,
                      'SE_HAC3':ha.bse,'t_HAC3':ha.tvalues,'p_HAC3':ha.pvalues})
    meta={'N':int(m.nobs),'R2':float(m.rsquared),'AdjR2':float(m.rsquared_adj),'CondNo':float(m.condition_number)}
    return out,meta


def _v402g_vif(df, cols):
    import statsmodels.api as sm
    from statsmodels.stats.outliers_influence import variance_inflation_factor
    z=df[list(cols)].dropna().astype(float)
    if len(z)<10: return pd.DataFrame()
    X=sm.add_constant(z,has_constant='add')
    rows=[]
    for i,c in enumerate(X.columns):
        if c=='const': continue
        try: v=float(variance_inflation_factor(X.values,i))
        except Exception: v=np.nan
        rows.append({'Term':c,'VIF':v})
    return pd.DataFrame(rows)


