# ================================================================
# v4.03a — Frozen TEL Inverse Overlay Prototype LIGHT
# First portfolio-level prototype after v4.02c-g mechanism audits.
# IMPORTANT: one pre-specified mapping only; no strength/threshold/lookback sweep.
# DEV cutoff = 2026-07-31. Historical robustness, not true prospective OOS.
# ================================================================
def _v403a_monthly_price12(fm):
    """TEL-DM trailing 12 completed-month compounded return at each month-end."""
    s=pd.Series(fm['TEL-DM']).dropna().astype(float).sort_index()
    return (1.0+s).rolling(12,min_periods=12).apply(np.prod,raw=True)-1.0


def _v403a_frozen_signal(fm,min_history=36):
    """
    Frozen transform decided before portfolio results are viewed:
      - primary signal = TEL-DM Price12M (same signal as v4.02c-g)
      - standardization = expanding PRIOR-ONLY mean / sample SD
      - require 36 prior Price12M observations
      - bounded continuous inverse tilt = -tanh(z)
      - TEL target weight = 25% * (1 - 0.5*tanh(z))
        => mechanically bounded to 12.5%..37.5%, i.e. max tilt = 50% of base TEL sleeve
      - remaining weight split equally across MOM/MR/VIX
      - signal observed at month-end t applies only to month t+1
    No parameter is selected from portfolio outcomes.
    """
    p=_v403a_monthly_price12(fm).rename('TEL_Price12M')
    rows=[]
    vals=[]
    for dt,val in p.items():
        if pd.isna(val):
            continue
        hist=np.asarray(vals,dtype=float)
        mu=sd=z=np.nan
        if len(hist)>=min_history:
            mu=float(np.mean(hist)); sd=float(np.std(hist,ddof=1))
            if np.isfinite(sd) and sd>1e-12:
                z=float((val-mu)/sd)
        inv=float(-np.tanh(z)) if np.isfinite(z) else np.nan
        wtel=float(0.25*(1.0+0.5*inv)) if np.isfinite(inv) else np.nan
        if np.isfinite(wtel):
            wtel=float(np.clip(wtel,0.125,0.375))
            wother=float((1.0-wtel)/3.0)
        else:
            wother=np.nan
        sig_period=pd.Timestamp(dt).to_period('M')
        apply_period=sig_period+1
        rows.append({
            'SignalDate':pd.Timestamp(dt),
            'SignalMonth':str(sig_period),
            'ApplyMonth':str(apply_period),
            'TEL_Price12M':float(val),
            'PriorHistoryN':int(len(hist)),
            'PriorMean':mu,'PriorSD':sd,'Z_prior_only':z,
            'InverseScore_minus_tanh_z':inv,
            'TEL_TargetWeight':wtel,
            'MOM_TargetWeight':wother,'MR_TargetWeight':wother,'VIX_TargetWeight':wother,
        })
        vals.append(float(val))
    return pd.DataFrame(rows)


def _v403a_monthly_target_portfolio(famd,weight_table,name):
    """Monthly target-weight portfolio; target is set at first available day then drifts within month."""
    x=famd[['MOM','MR','VIX','TEL-DM']].dropna().astype(float).sort_index()
    if x.empty:
        return pd.Series(dtype=float,name=name),pd.DataFrame(),pd.DataFrame()
    wt=weight_table.copy()
    if not isinstance(wt.index,pd.PeriodIndex):
        wt.index=pd.PeriodIndex(wt.index,freq='M')
    wt=wt[['MOM','MR','VIX','TEL-DM']].astype(float)
    out=[]; wlog=[]; turns=[]
    prev_end_w=None
    for per,g in x.groupby(x.index.to_period('M')):
        if per not in wt.index:
            continue
        target=wt.loc[per]
        if isinstance(target,pd.DataFrame): target=target.iloc[-1]
        target=target.reindex(x.columns).astype(float)
        if target.isna().any() or target.sum()<=0:
            continue
        target=target/target.sum()
        if prev_end_w is None:
            turnover=0.0
        else:
            pe=prev_end_w.reindex(x.columns).fillna(0.0)
            turnover=float(0.5*np.abs(target-pe).sum())
        turns.append({'Month':str(per),'RebalanceDate':g.index[0],'OneWayTurnover':turnover,**{f'Target_{c}':float(target[c]) for c in x.columns}})
        wealth=target.copy()
        for dt,row in g.iterrows():
            w=wealth/wealth.sum()
            r=float((w*row).sum())
            out.append((dt,r))
            rec={'Date':dt,'Month':str(per)}
            rec.update({f'PreReturnWeight_{c}':float(w[c]) for c in x.columns})
            wlog.append(rec)
            wealth=wealth*(1.0+row)
        prev_end_w=wealth/wealth.sum()
    s=pd.Series(dict(out),name=name,dtype=float).sort_index()
    return s,pd.DataFrame(wlog),pd.DataFrame(turns)


def _v403a_annual_returns(daily):
    rows=[]
    for c in daily.columns:
        for y,g in daily[c].dropna().groupby(daily[c].dropna().index.year):
            rows.append({'Series':c,'Year':int(y),'Return':float((1.0+g).prod()-1.0)})
    return pd.DataFrame(rows)


def _v403a_rolling36(monthly):
    rows=[]
    for c in monthly.columns:
        s=monthly[c].dropna().astype(float)
        for i in range(35,len(s)):
            g=s.iloc[i-35:i+1]; v=float((1+g).prod())
            cg=v**(1/3.0)-1 if v>0 else np.nan
            rows.append({'Series':c,'End':g.index[-1],'Rolling3Y_CAGR':cg})
    d=pd.DataFrame(rows)
    if d.empty: return d,pd.DataFrame()
    sm=d.groupby('Series')['Rolling3Y_CAGR'].agg(
        N='count',Mean='mean',Median='median',Min='min',P10=lambda x:x.quantile(.10),PositiveShare=lambda x:(x>0).mean()
    ).reset_index()
    return d,sm


def _v403a_wf(monthly,control='4F EW Control',challenger='TEL Inverse Overlay',nblocks=13):
    z=monthly[[control,challenger]].dropna(); rows=[]
    for i,loc in enumerate(np.array_split(np.arange(len(z)),min(nblocks,len(z))),1):
        if not len(loc): continue
        g=z.iloc[loc]; yrs=len(g)/12.0
        def cg(s):
            v=float((1+s).prod()); return v**(1/yrs)-1 if yrs>0 and v>0 else np.nan
        ca,ch=cg(g[control]),cg(g[challenger])
        ds=_monthly_sortino0(g[challenger])-_monthly_sortino0(g[control])
        dsh=_monthly_sharpe0(g[challenger])-_monthly_sharpe0(g[control])
        rows.append({'Block':i,'Start':str(g.index.min()),'End':str(g.index.max()),'Months':len(g),
                     'Control CAGR':ca,'Overlay CAGR':ch,'Active CAGR':ch-ca,
                     'Delta Sortino0':ds,'Delta Sharpe0':dsh,
                     'Overlay CAGR Win':bool(ch>ca),'Overlay Sortino Win':bool(ds>0),'Overlay Sharpe Win':bool(dsh>0)})
    return pd.DataFrame(rows)


def _v403a_cpcv(monthly,control='4F EW Control',challenger='TEL Inverse Overlay'):
    from itertools import combinations
    z=monthly[[control,challenger]].dropna(); rows=[]
    if len(z)<8:return pd.DataFrame(),pd.DataFrame()
    groups=np.array_split(np.arange(len(z)),8); bounds=[]
    for k,loc in enumerate(groups,1):
        if len(loc): bounds.append({'Group':k,'Start':str(z.index[loc[0]]),'End':str(z.index[loc[-1]]),'Months':len(loc)})
    for a,b in combinations(range(8),2):
        loc=np.sort(np.r_[groups[a],groups[b]]); g=z.iloc[loc]
        ds=_monthly_sortino0(g[challenger])-_monthly_sortino0(g[control])
        dsh=_monthly_sharpe0(g[challenger])-_monthly_sharpe0(g[control])
        active=float((g[challenger]-g[control]).mean()*12.0)
        rows.append({'Group1':a+1,'Group2':b+1,'Months':len(g),'Delta Sortino0':ds,'Delta Sharpe0':dsh,
                     'Active AnnArithmetic':active,'Positive Delta Sortino':bool(ds>0),
                     'Positive Delta Sharpe':bool(dsh>0),'Positive Active':bool(active>0)})
    return pd.DataFrame(rows),pd.DataFrame(bounds)


def _v403a_stress(daily):
    windows=[('2015 Jul-Sep','2015-07-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),
             ('2019-05','2019-05-01','2019-05-31'),('COVID','2020-02-01','2020-04-30'),
             ('2022 Apr-Oct','2022-04-01','2022-10-31'),('2023 Jul-Oct','2023-07-01','2023-10-31'),
             ('2025 Feb-Apr','2025-02-01','2025-04-30')]
    rows=[]
    for nm,a,b in windows:
        row={'Stress':nm,'Start':a,'End':b}
        for c in daily.columns:
            x=daily.loc[a:b,c].dropna(); eq=(1+x).cumprod(); dd=eq/eq.cummax()-1
            row[c+' Return']=float((1+x).prod()-1) if len(x) else np.nan
            row[c+' MaxDD']=float(dd.min()) if len(x) else np.nan
        rows.append(row)
    return pd.DataFrame(rows)


def render_v403a_frozen_tel_inverse_overlay(px_close,rf_bt,start,end):
    import io,zipfile
    st.markdown('### 🧊 v4.03a — Frozen TEL Inverse Overlay Prototype LIGHT')
    st.caption('v4.02c→gで反証を重ねたTEL-DM Price12M inverse candidateを、初めてportfolio-levelの固定overlayへ変換します。')
    st.info(
        '事前固定: Primary signal = TEL-DM Price12M。各signal時点より前のPrice12M履歴だけでexpanding z-scoreを作り、最低36 observations。'
        'Overlay = TEL weight 25% × [1 − 0.5×tanh(z)]。したがってTELは12.5%〜37.5%に自動的にbounded、残りをMOM/MR/VIXへ等分。'
        '月末tのsignalは翌月t+1だけに適用。Control=同じ評価期間の4F 25% EW。'
    )
    st.warning(
        'このmappingは1本だけを事前固定。strength sweep、threshold、lookback変更、Prior11Mへの乗換え、結果後のweight修正は行いません。'
        'DEV cutoff=2026-07-31。今回のWF/CPCVはhistorical robustnessであり、真のprospective OOSではありません。'
    )
    if not st.button('v4.03a Frozen TEL Inverse Overlayを実行',type='primary',use_container_width=True,key='run_v403a'):
        return
    with st.spinner('Frozen 4Fを構築し、事前固定した1本のTEL inverse overlayだけをportfolio-levelで監査中…'):
        # Use the exact frozen 4F construction already used by v4.00-v4.02g.
        _,famd=_v390_build(px_close,rf_bt,start,end)
        famd=famd[['MOM','MR','VIX','TEL-DM']].dropna().loc[:pd.Timestamp('2026-07-31')]
        fm=(1.0+famd).resample('ME').prod(min_count=1)-1.0
        sig=_v403a_frozen_signal(fm,min_history=36)
        valid=sig.dropna(subset=['TEL_TargetWeight']).copy()
        if valid.empty:
            raise ValueError('v4.03a: signal history is insufficient after the fixed 36-observation warm-up.')
        w_overlay=pd.DataFrame({
            'MOM':valid['MOM_TargetWeight'].to_numpy(float),
            'MR':valid['MR_TargetWeight'].to_numpy(float),
            'VIX':valid['VIX_TargetWeight'].to_numpy(float),
            'TEL-DM':valid['TEL_TargetWeight'].to_numpy(float),
        },index=pd.PeriodIndex(valid['ApplyMonth'],freq='M'))
        # Control is deliberately restricted to identical apply months.
        w_control=pd.DataFrame(0.25,index=w_overlay.index,columns=['MOM','MR','VIX','TEL-DM'])
        inv,inv_wlog,inv_turn=_v403a_monthly_target_portfolio(famd,w_overlay,'TEL Inverse Overlay')
        ctrl,ctrl_wlog,ctrl_turn=_v403a_monthly_target_portfolio(famd,w_control,'4F EW Control')
        daily=pd.concat([ctrl,inv],axis=1).dropna()
        if daily.empty: raise ValueError('v4.03a: no common daily portfolio observations were produced.')
        monthly=(1.0+daily).resample('ME').prod(min_count=1)-1.0

        metrics=pd.DataFrame([_v381_metrics(c,daily[c]) for c in daily.columns]).set_index('Series')
        annual=_v403a_annual_returns(daily)
        worst=(annual.sort_values('Return').groupby('Series',as_index=False).first()
               .rename(columns={'Year':'WorstYear','Return':'WorstYearReturn'})) if len(annual) else pd.DataFrame()
        roll36,roll36sum=_v403a_rolling36(monthly)
        wf=_v403a_wf(monthly)
        cpcv,cpcv_groups=_v403a_cpcv(monthly)
        stress=_v403a_stress(daily)

        # Turnover comparison. First month is initialization and excluded from average rebalance turnover.
        tsum=[]
        for nm,t in [('4F EW Control',ctrl_turn),('TEL Inverse Overlay',inv_turn)]:
            q=t.copy()
            if len(q)>1:q=q.iloc[1:]
            tsum.append({'Series':nm,'Rebalances':len(q),'Mean OneWay Turnover':q['OneWayTurnover'].mean() if len(q) else np.nan,
                         'Median OneWay Turnover':q['OneWayTurnover'].median() if len(q) else np.nan,
                         'Annualized OneWay Turnover':q['OneWayTurnover'].mean()*12 if len(q) else np.nan,
                         'Max OneWay Turnover':q['OneWayTurnover'].max() if len(q) else np.nan})
