def _v403b_cost_stress(monthly, inv_turn, ctrl_turn, bps_grid=(0,5,10,20,50)):
    """Apply fixed one-way transaction-cost stress to each portfolio's actual monthly rebalance turnover."""
    z=monthly[['4F EW Control','TEL Inverse Overlay']].dropna().copy()
    idx=z.index.to_period('M')
    def turn_series(t):
        if t is None or len(t)==0: return pd.Series(0.0,index=idx)
        q=t.copy(); q['P']=pd.PeriodIndex(q['Month'].astype(str),freq='M')
        s=q.groupby('P')['OneWayTurnover'].last().astype(float)
        return pd.Series(idx.map(s).to_numpy(),index=z.index,dtype=float).fillna(0.0)
    tc=turn_series(ctrl_turn); ti=turn_series(inv_turn)
    rows=[]; net_tables=[]
    for bps in bps_grid:
        k=float(bps)/10000.0
        net=pd.DataFrame(index=z.index)
        net['4F EW Control']=z['4F EW Control']-tc*k
        net['TEL Inverse Overlay']=z['TEL Inverse Overlay']-ti*k
        yrs=len(net)/12.0
        def cagr(s):
            v=float((1+s).prod()); return v**(1/yrs)-1 if yrs>0 and v>0 else np.nan
        cc,ci=cagr(net.iloc[:,0]),cagr(net.iloc[:,1])
        rows.append({'OneWayCost_bps':bps,'Control CAGR Net':cc,'Overlay CAGR Net':ci,'Delta CAGR Net':ci-cc,
                     'Control Sortino0 Net':_monthly_sortino0(net.iloc[:,0]),'Overlay Sortino0 Net':_monthly_sortino0(net.iloc[:,1]),
                     'Delta Sortino0 Net':_monthly_sortino0(net.iloc[:,1])-_monthly_sortino0(net.iloc[:,0]),
                     'Control AnnTurnover':float(tc.iloc[1:].mean()*12) if len(tc)>1 else np.nan,
                     'Overlay AnnTurnover':float(ti.iloc[1:].mean()*12) if len(ti)>1 else np.nan})
        q=net.reset_index(); q['OneWayCost_bps']=bps; net_tables.append(q)
    return pd.DataFrame(rows),pd.concat(net_tables,ignore_index=True) if net_tables else pd.DataFrame()


def _v403b_active_attribution(monthly):
    z=monthly[['4F EW Control','TEL Inverse Overlay']].dropna().copy()
    z['ActiveMonthly']=z['TEL Inverse Overlay']-z['4F EW Control']
    z['Year']=z.index.year
    s=z['ActiveMonthly']; pos=s.clip(lower=0)
    top=s.sort_values(ascending=False)
    rows=[]
    base_years=len(z)/12.0
    def cagr(x):
        v=float((1+x).prod()); return v**(1/base_years)-1 if base_years>0 and v>0 else np.nan
    ctrl_cg=cagr(z['4F EW Control']); ov_cg=cagr(z['TEL Inverse Overlay'])
    for n in [0,1,3,5]:
        alt=z['TEL Inverse Overlay'].copy()
        removed=[]
        if n>0:
            removed=list(top.head(n).index)
            alt.loc[removed]=z.loc[removed,'4F EW Control']
        rows.append({'BestActiveMonthsRemoved':n,'Overlay CAGR after removal':cagr(alt),
                     'Control CAGR':ctrl_cg,'Delta CAGR after removal':cagr(alt)-ctrl_cg,
                     'Original Overlay CAGR':ov_cg,
                     'RemovedMonths':' | '.join(str(pd.Timestamp(x).date()) for x in removed)})
    concentration=pd.DataFrame([{
        'Months':len(s),'PositiveActiveMonths':int((s>0).sum()),'PositiveActiveShare':float((s>0).mean()),
        'MeanActiveMonthly':float(s.mean()),'MedianActiveMonthly':float(s.median()),
        'Top1ShareOfPositiveActive':float(top.head(1).clip(lower=0).sum()/pos.sum()) if pos.sum()>0 else np.nan,
        'Top3ShareOfPositiveActive':float(top.head(3).clip(lower=0).sum()/pos.sum()) if pos.sum()>0 else np.nan,
        'Top5ShareOfPositiveActive':float(top.head(5).clip(lower=0).sum()/pos.sum()) if pos.sum()>0 else np.nan,
    }])
    yearly=z.groupby('Year').agg(ControlReturn=('4F EW Control',lambda x:(1+x).prod()-1),
                                  OverlayReturn=('TEL Inverse Overlay',lambda x:(1+x).prod()-1),
                                  MeanActiveMonthly=('ActiveMonthly','mean'),Months=('ActiveMonthly','size')).reset_index()
    yearly['ActiveAnnualReturnDiff']=yearly['OverlayReturn']-yearly['ControlReturn']
    months=z.reset_index().rename(columns={z.index.name or 'index':'Month'})
    return pd.DataFrame(rows),concentration,yearly,months


def _v403b_weight_regime_attribution(monthly, valid):
    z=monthly[['4F EW Control','TEL Inverse Overlay']].dropna().copy()
    z['ApplyMonth']=z.index.to_period('M').astype(str)
    v=valid[['ApplyMonth','TEL_Price12M','Z_prior_only','TEL_TargetWeight']].copy()
    v['ApplyMonth']=v['ApplyMonth'].astype(str)
    d=z.reset_index().merge(v,on='ApplyMonth',how='left')
    d['ActiveMonthly']=d['TEL Inverse Overlay']-d['4F EW Control']
    d['TiltDirection']=np.where(d['TEL_TargetWeight']>0.2500001,'TEL Increased',np.where(d['TEL_TargetWeight']<0.2499999,'TEL Reduced','Neutral'))
    rows=[]
    for nm,g in d.groupby('TiltDirection',dropna=False):
        if len(g)==0: continue
        rows.append({'TiltDirection':nm,'Months':len(g),'MeanTELWeight':g['TEL_TargetWeight'].mean(),
                     'MeanActiveMonthly':g['ActiveMonthly'].mean(),'MedianActiveMonthly':g['ActiveMonthly'].median(),
                     'PositiveActiveShare':(g['ActiveMonthly']>0).mean(),'ArithmeticActiveAnnualized':g['ActiveMonthly'].mean()*12,
                     'SumActiveMonthly':g['ActiveMonthly'].sum()})
    return pd.DataFrame(rows),d


