def _v403_live_standard_universe(px_close, rf_bt, start, end):
    """Rebuild the current standard sleeves and TEL-DM without a historical DEV cutoff."""
    closes=px_close.copy()
    closes.index=pd.DatetimeIndex(pd.to_datetime(closes.index))
    closes=closes.sort_index().ffill()
    rf=rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt,pd.Series) else rf_bt
    core_h=_build_core_holding_matrix(closes,rf).reindex(closes.index)
    safe_h,_=_adaptive_safe_haven_monthly_series(closes)
    safe_h=safe_h.reindex(closes.index).ffill()
    h=core_h.copy()
    for m in MODEL_WEIGHTS:
        mask=h[m].eq('GLD')
        h.loc[mask,m]=safe_h.loc[mask]
    sleeve=_returns_from_holding_matrix(h,closes)
    tel,_,_,_,_=_v389_layered_dm(px_close,start,end)
    famd=pd.DataFrame(index=sleeve.index)
    famd['MOM']=0.5*sleeve['QQQ-MOM']+0.5*sleeve['QLD-MOM']
    famd['MR']=0.5*sleeve['Weekly MR 24M']+0.5*sleeve['Quarterly MR 24M']
    famd['VIX']=0.25*sleeve['Old VIX 15d']+0.25*sleeve['Old VIX 20d']+0.5*sleeve['New VIX 20d']
    famd['TEL-DM']=tel.reindex(famd.index)
    famd=famd.dropna().sort_index()
    return sleeve.sort_index(),famd


def _v403_oos_simple_metrics(r):
    x=pd.Series(r).dropna().astype(float)
    if x.empty:
        return {'Months':0,'TotalReturn':np.nan,'CAGR':np.nan,'Sharpe0':np.nan,'Sortino0':np.nan,'MaxDD':np.nan}
    eq=(1.0+x).cumprod(); dd=eq/eq.cummax()-1.0
    n=len(x); total=float(eq.iloc[-1]-1.0)
    cagr=float(eq.iloc[-1]**(12.0/n)-1.0) if n>=12 else np.nan
    sd=float(x.std(ddof=1)) if n>1 else np.nan
    sh=float(x.mean()/sd*np.sqrt(12.0)) if np.isfinite(sd) and sd>0 and n>=6 else np.nan
    dn=x[x<0]; dsd=float(np.sqrt(np.mean(np.square(dn)))) if len(dn) else np.nan
    so=float(x.mean()/dsd*np.sqrt(12.0)) if np.isfinite(dsd) and dsd>0 and n>=6 else np.nan
    return {'Months':n,'TotalReturn':total,'CAGR':cagr,'Sharpe0':sh,'Sortino0':so,'MaxDD':float(dd.min())}


def render_v403_prospective_oos_monitor(px_close,rf_bt,start,end):
    import io,zipfile
