def _genbu_target_monthly_positions():
    rows = []
    for line in _GENBU_MONTHLY_POSITION_TEXT.strip().splitlines():
        parts = line.split()
        if len(parts) != 2:
            continue
        rows.append((pd.Period(parts[0], freq="M"), parts[1]))
    s = pd.Series(dict(rows), name="Genbu").sort_index()
    s.index.name = "Month"
    return s


def _genbu_open_aligned_mr_monthly_positions(px, rf_rates, model):
    """Month-start / next-open labels using the existing Frozen-Core MR signal."""
    idx = pd.DatetimeIndex(px.index).sort_values()
    sparse = {}
    for d in _model_trade_dates(idx, model):
        h = _signal_on_trade_date(model, d, px, rf_rates)
        if h in ("TQQQ", "XLU"):
            sparse[pd.Timestamp(d)] = h
    if not sparse:
        return pd.Series(dtype="object", name=model)
    h = pd.Series(sparse, dtype="object").sort_index().reindex(idx).ffill()
    periods = idx.to_period("M")
    first_dates = pd.Series(idx, index=periods).groupby(level=0).first()
    vals = {p: h.loc[d] for p, d in first_dates.items() if d in h.index and pd.notna(h.loc[d])}
    s = pd.Series(vals, name=model, dtype="object").sort_index()
    s.index = pd.PeriodIndex(s.index, freq="M", name="Month")
    return s


def _genbu_binary_similarity(target, pred):
    z = pd.concat([target.rename("Target"), pred.rename("Pred")], axis=1).dropna()
    z = z[z["Target"].isin(["TQQQ", "XLU"]) & z["Pred"].isin(["TQQQ", "XLU"])]
    if z.empty:
        return {}, z
    yt = z["Target"].eq("TQQQ")
    yp = z["Pred"].eq("TQQQ")
    tp = int((yt & yp).sum()); tn = int((~yt & ~yp).sum())
    fp = int((~yt & yp).sum()); fn = int((yt & ~yp).sum())
    n = len(z)
    acc = (tp + tn) / n
    precision = tp / (tp + fp) if (tp + fp) else np.nan
    recall = tp / (tp + fn) if (tp + fn) else np.nan
    f1 = 2 * precision * recall / (precision + recall) if pd.notna(precision) and pd.notna(recall) and (precision + recall) else np.nan
    specificity = tn / (tn + fp) if (tn + fp) else np.nan
    bal = np.nanmean([recall, specificity])
    denom = math.sqrt((tp + fp) * (tp + fn) * (tn + fp) * (tn + fn))
    mcc = ((tp * tn - fp * fn) / denom) if denom else np.nan
    union = int((yt | yp).sum())
    jacc = tp / union if union else np.nan
    always_xlu = float((~yt).mean())
    return {
        "N": n, "Accuracy": acc, "Always-XLU baseline": always_xlu,
        "Accuracy minus baseline": acc - always_xlu,
        "TQQQ precision": precision, "TQQQ recall": recall, "TQQQ F1": f1,
        "XLU recall / specificity": specificity, "Balanced accuracy": bal,
        "MCC": mcc, "TQQQ month Jaccard": jacc,
        "TP": tp, "FP": fp, "FN": fn, "TN": tn,
        "Target TQQQ months": int(yt.sum()), "Pred TQQQ months": int(yp.sum()),
    }, z


def _genbu_episode_diagnostics(series, name):
    s = series.dropna().astype(str).sort_index()
    rows = []; in_ep = False; start = None; last = None
    for p, v in s.items():
        if v == "TQQQ" and not in_ep:
            in_ep = True; start = p
        if in_ep and v == "TQQQ":
            last = p
        if in_ep and v != "TQQQ":
            rows.append({"Series": name, "Start": str(start), "End": str(last), "Months": int(last.ordinal - start.ordinal + 1)})
            in_ep = False; start = None; last = None
    if in_ep:
        rows.append({"Series": name, "Start": str(start), "End": str(last), "Months": int(last.ordinal - start.ordinal + 1)})
    return pd.DataFrame(rows)


def _genbu_change_months(series, to_value):
    s = series.dropna().astype(str).sort_index()
    prev = s.shift(1)
    return set(s.index[s.eq(to_value) & ~prev.eq(to_value)])




# ================================================================
# Genbu RE R2 — Entry Fingerprint
# Descriptive event study only. No rule fitting, threshold search,
# lookback optimization, or return optimization.
# ================================================================
_GENBU_R2_UNIVERSE = [
    "QQQ", "QLD", "TQQQ", "LQD", "GLD", "TLT", "SPXL",
    "TECL", "XLU", "^VIX", "SPY", "XLK", "TMF", "TMV",
]
_GENBU_R2_RANK_ASSETS = [
    "QQQ", "QLD", "TQQQ", "LQD", "GLD", "TLT", "SPXL",
    "TECL", "XLU", "SPY", "XLK", "TMF", "TMV",
]


def _genbu_r2_month_end_features(px):
    """Prior-month-end state features for the fixed existing research universe."""
    c = px.reindex(columns=[x for x in _GENBU_R2_UNIVERSE if x in px.columns]).copy()
    c.index = pd.DatetimeIndex(c.index)
    c = c.sort_index().ffill()
    me = c.resample("ME").last()
    me.index = me.index.to_period("M")
    me.index.name = "SignalMonth"

    feats = {}
    for a in [x for x in _GENBU_R2_UNIVERSE if x in me.columns]:
        # Fixed descriptive horizons, chosen before seeing R2 output.
        for h in (1, 3, 6, 12, 24):
            feats[f"{a}_Ret{h}M"] = me[a] / me[a].shift(h) - 1.0
        # Distance from rolling high is a state descriptor, not a trading rule.
        feats[f"{a}_DD12M"] = me[a] / me[a].rolling(12, min_periods=12).max() - 1.0
        feats[f"{a}_DD24M"] = me[a] / me[a].rolling(24, min_periods=24).max() - 1.0

    f = pd.DataFrame(feats, index=me.index)

    # Cross-sectional percentile ranks. VIX is intentionally excluded from price ranks.
    for h in (1, 3, 6, 12, 24):
        cols = [f"{a}_Ret{h}M" for a in _GENBU_R2_RANK_ASSETS if f"{a}_Ret{h}M" in f.columns]
        if cols:
            rr = f[cols].rank(axis=1, pct=True, method="average")
            for a in _GENBU_R2_RANK_ASSETS:
                col = f"{a}_Ret{h}M"
                if col in rr.columns:
                    f[f"{a}_Rank{h}M"] = rr[col]

    if "^VIX" in me.columns:
        f["VIX_Level"] = me["^VIX"]
        for h in (1, 3, 6, 12):
            f[f"VIX_Change{h}M"] = me["^VIX"] / me["^VIX"].shift(h) - 1.0

    return me, f


def _genbu_r2_group_labels(target, weekly, quarterly):
    z = pd.concat([
        target.rename("Genbu"), weekly.rename("Weekly MR 24M"), quarterly.rename("Quarterly MR 24M")
    ], axis=1).sort_index()
    prev_g = z["Genbu"].shift(1)
    prev_w = z["Weekly MR 24M"].shift(1)
    prev_q = z["Quarterly MR 24M"].shift(1)
    z["Genbu Entry"] = z["Genbu"].eq("TQQQ") & ~prev_g.eq("TQQQ")
    z["Genbu TQQQ Continue"] = z["Genbu"].eq("TQQQ") & prev_g.eq("TQQQ")
    z["Genbu XLU Continue"] = z["Genbu"].eq("XLU") & prev_g.eq("XLU")
    z["Weekly MR Entry"] = z["Weekly MR 24M"].eq("TQQQ") & ~prev_w.eq("TQQQ")
    z["Quarterly MR Entry"] = z["Quarterly MR 24M"].eq("TQQQ") & ~prev_q.eq("TQQQ")
    z["Genbu-only Entry vs Weekly"] = z["Genbu Entry"] & ~z["Weekly MR 24M"].eq("TQQQ")
    z["Genbu-only Entry vs Quarterly"] = z["Genbu Entry"] & ~z["Quarterly MR 24M"].eq("TQQQ")
    return z


def _genbu_r2_feature_summary(features_by_position_month, labels, dev_end):
    """Summarize fingerprints. No feature selection is used to construct a strategy."""
    x = features_by_position_month.loc[:dev_end].copy()
    lab = labels.reindex(x.index)
    groups = [
        "Genbu Entry", "Genbu TQQQ Continue", "Genbu XLU Continue",
        "Weekly MR Entry", "Quarterly MR Entry",
        "Genbu-only Entry vs Weekly", "Genbu-only Entry vs Quarterly",
    ]
    rows = []
    base = lab["Genbu XLU Continue"].fillna(False)
    for g in groups:
        mask = lab[g].fillna(False)
        for c in x.columns:
            a = x.loc[mask, c].dropna()
            b = x.loc[base, c].dropna()
            if a.empty:
                continue
            pooled = pd.concat([a, b])
            sd = float(pooled.std(ddof=1)) if len(pooled) > 1 else np.nan
            diff_sd = (float(a.mean()) - float(b.mean())) / sd if pd.notna(sd) and sd > 0 and not b.empty else np.nan
            # Percentile of event median relative to all available DEV months.
            allv = x[c].dropna()
            event_med = float(a.median())
            pct = float((allv <= event_med).mean()) if len(allv) else np.nan
            rows.append({
                "Group": g, "Feature": c, "N": int(len(a)),
                "Mean": float(a.mean()), "Median": event_med,
                "P25": float(a.quantile(.25)), "P75": float(a.quantile(.75)),
                "PctPositive": float((a > 0).mean()),
                "XLUContinueMean": float(b.mean()) if not b.empty else np.nan,
                "MeanDiff": float(a.mean() - b.mean()) if not b.empty else np.nan,
                "StandardizedDiff": diff_sd,
                "EventMedianPercentile": pct,
            })
    return pd.DataFrame(rows)


def _genbu_r2_event_panel(monthly_prices, entry_months, window_left=12, window_right=6):
    """Raw normalized event paths around Genbu entries. T=0 is position month."""
    rows = []
    assets = [a for a in _GENBU_R2_UNIVERSE if a in monthly_prices.columns]
    for em in sorted(entry_months):
        if em not in monthly_prices.index:
            continue
        # Normalize to prior month end (T=-1), matching information available before T=0 position month.
        base_m = em - 1
        if base_m not in monthly_prices.index:
            continue
        for rel in range(-window_left, window_right + 1):
            m = em + rel
            if m not in monthly_prices.index:
                continue
            for a in assets:
                base = monthly_prices.at[base_m, a]
                val = monthly_prices.at[m, a]
                if pd.notna(base) and pd.notna(val) and base != 0:
                    rows.append({
                        "EntryMonth": str(em), "RelMonth": rel, "Asset": a,
                        "NormalizedReturnFromTminus1": float(val / base - 1.0),
                    })
    return pd.DataFrame(rows)


def _genbu_r2_event_medians(panel):
    if panel.empty:
        return pd.DataFrame()
    return (panel.groupby(["Asset", "RelMonth"])["NormalizedReturnFromTminus1"]
            .agg(N="count", Median="median", Mean="mean", P25=lambda s: s.quantile(.25), P75=lambda s: s.quantile(.75))
            .reset_index())




# ================================================================
# Genbu RE R3 — State Transition Audit
# Fixed-state descriptive audit. Reuses ONLY the R2 feature universe
# and horizons; no new assets, lookbacks, thresholds, or fitted model.
# ================================================================
def _genbu_r3_transition_labels(target, weekly, quarterly):
    z = pd.concat([
        target.rename("Genbu"),
        weekly.rename("Weekly MR 24M"),
        quarterly.rename("Quarterly MR 24M"),
    ], axis=1).sort_index()
    prev = z["Genbu"].shift(1)
    cur = z["Genbu"]
    z["XLU→XLU"] = prev.eq("XLU") & cur.eq("XLU")
    z["XLU→TQQQ (Entry)"] = prev.eq("XLU") & cur.eq("TQQQ")
    z["TQQQ→TQQQ (Hold)"] = prev.eq("TQQQ") & cur.eq("TQQQ")
    z["TQQQ→XLU (Exit)"] = prev.eq("TQQQ") & cur.eq("XLU")
    z["Transition"] = np.select(
        [z["XLU→XLU"], z["XLU→TQQQ (Entry)"], z["TQQQ→TQQQ (Hold)"], z["TQQQ→XLU (Exit)"]],
        ["XLU→XLU", "XLU→TQQQ (Entry)", "TQQQ→TQQQ (Hold)", "TQQQ→XLU (Exit)"],
        default="Other/Initial",
    )
    return z


def _genbu_r3_transition_feature_summary(features_by_position_month, labels, dev_end):
    x = features_by_position_month.loc[:dev_end].copy()
    lab = labels.reindex(x.index)
    groups = ["XLU→XLU", "XLU→TQQQ (Entry)", "TQQQ→TQQQ (Hold)", "TQQQ→XLU (Exit)"]
    rows = []
    for g in groups:
        mask = lab[g].fillna(False)
        for c in x.columns:
            a = x.loc[mask, c].dropna()
            if a.empty:
                continue
            allv = x[c].dropna()
            rows.append({
                "Transition": g,
                "Feature": c,
                "N": int(len(a)),
                "Mean": float(a.mean()),
                "Median": float(a.median()),
                "P25": float(a.quantile(.25)),
                "P75": float(a.quantile(.75)),
                "PctPositive": float((a > 0).mean()),
                "MedianPercentileAllDEV": float((allv <= float(a.median())).mean()) if len(allv) else np.nan,
            })
    return pd.DataFrame(rows)


def _genbu_r3_pairwise_contrasts(features_by_position_month, labels, dev_end):
    """Fixed pairwise descriptive contrasts. No feature ranking/selection."""
    x = features_by_position_month.loc[:dev_end].copy()
    lab = labels.reindex(x.index)
    pairs = [
        ("Entry vs XLU Continue", "XLU→TQQQ (Entry)", "XLU→XLU"),
        ("Entry vs Hold", "XLU→TQQQ (Entry)", "TQQQ→TQQQ (Hold)"),
        ("Exit vs Hold", "TQQQ→XLU (Exit)", "TQQQ→TQQQ (Hold)"),
        ("Exit vs XLU Continue", "TQQQ→XLU (Exit)", "XLU→XLU"),
    ]
    rows=[]
    for label, ga, gb in pairs:
        ma=lab[ga].fillna(False); mb=lab[gb].fillna(False)
        for c in x.columns:
            a=x.loc[ma,c].dropna(); b=x.loc[mb,c].dropna()
            if a.empty or b.empty:
                continue
            pooled=pd.concat([a,b])
            sd=float(pooled.std(ddof=1)) if len(pooled)>1 else np.nan
            rows.append({
                "Contrast":label,"GroupA":ga,"GroupB":gb,"Feature":c,
                "N_A":int(len(a)),"N_B":int(len(b)),
                "Mean_A":float(a.mean()),"Mean_B":float(b.mean()),
                "Median_A":float(a.median()),"Median_B":float(b.median()),
                "MeanDiff":float(a.mean()-b.mean()),
                "StandardizedDiff":float((a.mean()-b.mean())/sd) if pd.notna(sd) and sd>0 else np.nan,
            })
    return pd.DataFrame(rows)


def _genbu_r3_episode_table(target, dev_end):
    s=target.loc[:dev_end].dropna().sort_index()
    episodes=[]
    start=None
    vals=[]
    prev=None
    for m,v in s.items():
        if v=="TQQQ" and prev!="TQQQ":
            start=m; vals=[m]
        elif v=="TQQQ" and prev=="TQQQ":
            vals.append(m)
        if v!="TQQQ" and prev=="TQQQ" and start is not None:
            episodes.append({"EntryMonth":str(start),"ExitMonth":str(m),"TQQQMonths":len(vals),"LastTQQQMonth":str(vals[-1])})
            start=None; vals=[]
        prev=v
    if start is not None:
        episodes.append({"EntryMonth":str(start),"ExitMonth":"OPEN_at_DEV_end","TQQQMonths":len(vals),"LastTQQQMonth":str(vals[-1])})
    return pd.DataFrame(episodes)




# ================================================================
# Genbu RE R4 — Frozen-Rule Archetype Falsification
# Compare Genbu's binary risk state / transitions with already-existing
# Frozen Core rule archetypes. No Genbu-specific threshold or fitted model.
# ================================================================
def _genbu_r4_core_model_monthly_state(px, rf_rates, model):
    """Map an existing Frozen Core model to a monthly binary RiskOn/Defensive state."""
    idx = pd.DatetimeIndex(px.index).sort_values()
    sparse = {}
    for d in _model_trade_dates(idx, model):
        h = _signal_on_trade_date(model, d, px, rf_rates)
        if h is not None:
            sparse[pd.Timestamp(d)] = h
    if not sparse:
        return pd.Series(dtype="object", name=model)
    h = pd.Series(sparse, dtype="object").sort_index().reindex(idx).ffill()
    periods = idx.to_period("M")
    first_dates = pd.Series(idx, index=periods).groupby(level=0).first()
    risk_assets = {
        "QQQ-MOM": {"QQQ"},
        "QLD-MOM": {"QLD"},
        "Weekly MR 24M": {"TQQQ"},
        "Quarterly MR 24M": {"TQQQ"},
        "Old VIX 15d": {"SPXL"},
        "Old VIX 20d": {"SPXL"},
        "New VIX 20d": {"TQQQ", "TECL"},
    }[model]
    vals = {}
    for per, d in first_dates.items():
        if d in h.index and pd.notna(h.loc[d]):
            vals[per] = "TQQQ" if str(h.loc[d]) in risk_assets else "XLU"
    out = pd.Series(vals, name=model, dtype="object").sort_index()
    out.index = pd.PeriodIndex(out.index, freq="M", name="Month")
    return out


def _genbu_r4_event_metrics(target, pred, event_to="TQQQ"):
    z = pd.concat([target.rename("Target"), pred.rename("Pred")], axis=1).dropna().sort_index()
    if z.empty:
        return {}
    tprev = z["Target"].shift(1); pprev = z["Pred"].shift(1)
    te = z.index[z["Target"].eq(event_to) & ~tprev.eq(event_to)]
    pe = z.index[z["Pred"].eq(event_to) & ~pprev.eq(event_to)]
    ts, ps = set(te), set(pe)
    tp=len(ts & ps); fp=len(ps-ts); fn=len(ts-ps)
    precision=tp/(tp+fp) if tp+fp else np.nan
    recall=tp/(tp+fn) if tp+fn else np.nan
    f1=2*precision*recall/(precision+recall) if pd.notna(precision) and pd.notna(recall) and precision+recall else np.nan
    return {"Target events":len(ts),"Pred events":len(ps),"Exact matches":tp,"Precision":precision,"Recall":recall,"F1":f1}





