# Genbu RE R5 — Two-Rule Logic Truth Table
# Frozen two-bit state audit only. No AND/OR strategy is constructed.
# Uses only already-existing MR24M and VIX20d Frozen Core states.
# ================================================================
def _genbu_r5_joint_state(mr_state, vix_state):
    z = pd.concat([mr_state.rename("MR"), vix_state.rename("VIX")], axis=1).dropna()
    mr_on = z["MR"].eq("TQQQ")
    vx_on = z["VIX"].eq("TQQQ")
    state = pd.Series(index=z.index, dtype="object", name="JointState")
    state.loc[~vx_on & ~mr_on] = "00 Neither"
    state.loc[vx_on & ~mr_on] = "10 VIX only"
    state.loc[~vx_on & mr_on] = "01 MR only"
    state.loc[vx_on & mr_on] = "11 Both"
    return state



