# Genbu RE R7 — DM7-proxy → Shin Genbu-Gekiko Delta Audit
# Target identity is now known from Bam-san's supplied comment/image:
# supplied monthly trade = Shin Genbu-Gekiko, Genbu family = DM7-based.
# User MR24M is used ONLY as a DM7 proxy; no claim of exact DM7 identity.
# No new feature/rule/threshold optimization.
# ================================================================
def _genbu_r7_delta_labels(genbu, proxy):
    z = pd.concat([genbu.rename("Shin Genbu-Gekiko"), proxy.rename("DM7 proxy")], axis=1).dropna()
    g = z["Shin Genbu-Gekiko"].eq("TQQQ")
    p = z["DM7 proxy"].eq("TQQQ")
    lab = pd.Series(index=z.index, dtype="object", name="DeltaClass")
    lab.loc[~p & ~g] = "00 Same Defensive"
    lab.loc[p & g] = "11 Same Attack"
    lab.loc[~p & g] = "01 Added Attack"
    lab.loc[p & ~g] = "10 Added Defense"
    return z.join(lab)


def _genbu_r7_fixed_feature_contrasts(feat_for_position, delta, proxy_name):
    rows=[]
    classes=["00 Same Defensive","01 Added Attack","11 Same Attack","10 Added Defense"]
    x=feat_for_position.reindex(delta.index)
    for cls in classes:
        mask=delta["DeltaClass"].eq(cls)
        for c in x.columns:
            a=x.loc[mask,c].dropna()
            if a.empty: continue
            rows.append({"Proxy":proxy_name,"DeltaClass":cls,"Feature":c,"N":len(a),
                         "Mean":float(a.mean()),"Median":float(a.median()),"P25":float(a.quantile(.25)),
                         "P75":float(a.quantile(.75)),"PctPositive":float((a>0).mean())})
    summary=pd.DataFrame(rows)
    contrasts=[]
    # Added Attack is compared with the natural no-change defensive state;
    # Added Defense with the natural no-change attack state. This pairing is frozen by semantics, not results.
    for focal,base,label in [("01 Added Attack","00 Same Defensive","Added Attack vs Same Defensive"),
                             ("10 Added Defense","11 Same Attack","Added Defense vs Same Attack")]:
        for c in x.columns:
            a=x.loc[delta["DeltaClass"].eq(focal),c].dropna(); b=x.loc[delta["DeltaClass"].eq(base),c].dropna()
            if a.empty or b.empty: continue
            pooled=pd.concat([a,b]); sd=float(pooled.std(ddof=1)) if len(pooled)>1 else np.nan
            contrasts.append({"Proxy":proxy_name,"Contrast":label,"Feature":c,"FocalN":len(a),"BaseN":len(b),
                              "FocalMean":float(a.mean()),"BaseMean":float(b.mean()),"MeanDiff":float(a.mean()-b.mean()),
                              "StandardizedDiff":float((a.mean()-b.mean())/sd) if pd.notna(sd) and sd>0 else np.nan})
    return summary,pd.DataFrame(contrasts)




