def _dm7_sparse_positions(px, rf_rates, rebalance="weekly", lookback_mode="calendar24"):
    """Published-spec DM7 reconstruction.

    Direct source facts: SPXL is the timing/risk signal used by the user's existing DM7-equivalent
    implementation, 24M long-term reversal, XLU normally/in-market, TQQQ on reversal/out-of-market,
    weekly canonical rebalance; monthly addendum changes only rebalance frequency.

    Critical implementation uncertainty: the archived PV short-link server state is not embedded in
    the webarchive. Therefore the exact PV internal 24M endpoint convention cannot be proven here.
    We expose two fixed interpretations without selecting a winner:
      - calendar24: 24 calendar-month total return ending at the completed prior trading day.
      - trading504: pre-existing Frozen-Core approximation, 504 trading days.
    Matched RF is compounded over the same signal interval.
    """
    idx=pd.DatetimeIndex(px.index).sort_values()
    sparse={}
    for i in range(1,len(idx)):
        d=idx[i]
        if rebalance=="weekly":
            is_reb=_is_first_trading_day_of_week(idx,i)
        elif rebalance=="monthly":
            is_reb=_is_first_trading_day_of_month(idx,i)
        else:
            raise ValueError(rebalance)
        if not is_reb:
            continue
        try:
            signal_end=idx[idx<d][-1]
            if lookback_mode=="calendar24":
                r,s0,s1=calendar_return(px["SPXL"],signal_end,24,exclude_recent=0)
            elif lookback_mode=="trading504":
                r,s0,s1=trading_return(px["SPXL"],signal_end,504)
            else:
                raise ValueError(lookback_mode)
            rf=rf_return(rf_rates,s0,s1)
            sparse[pd.Timestamp(d)]="XLU" if r>=rf else "TQQQ"
        except (ValueError,IndexError,KeyError):
            pass
    return pd.Series(sparse,dtype="object").sort_index()


def _dm7_month_start_positions_from_sparse(px, sparse, name):
    idx=pd.DatetimeIndex(px.index).sort_values()
    if sparse.empty:
        return pd.Series(dtype="object",name=name)
    h=sparse.reindex(idx).ffill()
    periods=idx.to_period("M")
    first_dates=pd.Series(idx,index=periods).groupby(level=0).first()
    vals={p:h.loc[d] for p,d in first_dates.items() if d in h.index and pd.notna(h.loc[d])}
    z=pd.Series(vals,name=name,dtype="object").sort_index()
    z.index=pd.PeriodIndex(z.index,freq="M",name="Month")
    return z


def _dm7_trade_episode_summary(sparse,name):
    if sparse.empty:
        return pd.DataFrame()
    s=sparse.dropna().sort_index()
    changes=s[s.ne(s.shift(1))]
    rows=[]
    for d,v in changes.items():
        rows.append({"Reconstruction":name,"TradeDate":pd.Timestamp(d).strftime("%Y-%m-%d"),"NewHolding":v})
    return pd.DataFrame(rows)



