def _genbu_r9_quintile_audit(feature, target_tqqq, direction):
    z = pd.concat([feature.rename("FeatureValue"), target_tqqq.rename("TQQQ")], axis=1).dropna()
    if z.empty:
        return pd.DataFrame(), {}
    # ReversalOpportunity is oriented so larger always means 'more reversal opportunity'.
    z["ReversalOpportunity"] = -z["FeatureValue"] if direction == "lower" else z["FeatureValue"]
    try:
        q = pd.qcut(z["ReversalOpportunity"], q=5, labels=False, duplicates="drop")
    except Exception:
        q = pd.Series(index=z.index, dtype=float)
    z["QuintileRaw"] = q
    z = z.dropna(subset=["QuintileRaw"])
    if z.empty:
        return pd.DataFrame(), {}
    z["Quintile"] = z["QuintileRaw"].astype(int) + 1
    rows=[]
    for qi,g in z.groupby("Quintile", sort=True):
        n=len(g); k=int(g["TQQQ"].sum()); p=float(k/n) if n else np.nan
        # Wilson 95% interval, descriptive only.
        zz=1.959963984540054
        den=1+zz*zz/n
        center=(p+zz*zz/(2*n))/den
        half=zz*np.sqrt((p*(1-p)+zz*zz/(4*n))/n)/den
        rows.append({"Quintile":int(qi),"N":int(n),"TQQQ_Months":k,"TQQQ_Rate":p,
                     "Wilson95_Low":max(0.0,center-half),"Wilson95_High":min(1.0,center+half),
                     "FeatureMedian":float(g["FeatureValue"].median()),
                     "OpportunityMedian":float(g["ReversalOpportunity"].median())})
    bins=pd.DataFrame(rows)
    rates=bins.sort_values("Quintile")["TQQQ_Rate"].to_numpy(dtype=float)
    qs=bins.sort_values("Quintile")["Quintile"].to_numpy(dtype=float)
    rho=float(pd.Series(qs).corr(pd.Series(rates), method="spearman")) if len(rates)>=2 else np.nan
    steps=int(np.sum(np.diff(rates)>=-1e-15)) if len(rates)>=2 else 0
    total_steps=max(len(rates)-1,0)
    endpoint=float(rates[-1]-rates[0]) if len(rates)>=2 else np.nan
    # Rank correlation with binary target: continuous association, not a fitted classifier.
    rank_corr=float(pd.Series(z["ReversalOpportunity"].rank(method="average").to_numpy()).corr(
        pd.Series(z["TQQQ"].astype(float).to_numpy()), method="pearson")) if len(z)>2 else np.nan
    stats={"N":int(len(z)),"Bins":int(len(bins)),"Spearman_Q_vs_Rate":rho,
           "Nondecreasing_Steps":steps,"Total_Steps":total_steps,
           "Q5_minus_Q1_TQQQ_Rate":endpoint,"RankCorr_Opportunity_vs_TQQQ":rank_corr}
    return bins,stats





