_GENBU_R10_FEATURES = ["SPXL_Ret24M", "SPXL_DD24M", "SPXL_DD12M"]
_GENBU_R10_PHASES = ["PreEntry12", "Entry", "Hold", "Exit", "PostExit6"]


def _genbu_r10_phase_months(entry, last_tqqq, exit_month, dev_end):
    """Fixed phase windows from the pre-registered R10 design."""
    pre = [entry - k for k in range(12, 0, -1)]
    hold = []
    if pd.notna(last_tqqq):
        m = entry + 1
        while m <= last_tqqq:
            hold.append(m)
            m += 1
    post = []
    if pd.notna(exit_month):
        post = [exit_month + k for k in range(1, 7) if exit_month + k <= dev_end]
    return {
        "PreEntry12": [m for m in pre if m <= dev_end],
        "Entry": [entry] if entry <= dev_end else [],
        "Hold": [m for m in hold if m <= dev_end],
        "Exit": [exit_month] if pd.notna(exit_month) and exit_month <= dev_end else [],
        "PostExit6": post,
    }


def _genbu_r10_event_trajectory(feat, anchors, rel_start, rel_end, anchor_name):
    rows=[]
    for episode_id, anchor in anchors:
        if pd.isna(anchor):
            continue
        for rel in range(rel_start, rel_end + 1):
            m = anchor + rel
            for f in _GENBU_R10_FEATURES:
                if f in feat.columns and m in feat.index:
                    v = feat.at[m, f]
                    if pd.notna(v):
                        rows.append({"Episode": episode_id, anchor_name: anchor, "RelativeMonth": rel, "Feature": f, "Value": float(v)})
    raw=pd.DataFrame(rows)
    if raw.empty:
        return raw, pd.DataFrame()
    agg=(raw.groupby(["Feature","RelativeMonth"],as_index=False)
           .agg(N=("Value","size"),Mean=("Value","mean"),Median=("Value","median")))
    return raw, agg





