def _genbu_r12_cell_table(work, state_col, state_mode, dir_col, state_name, lag):
    d=work[["Target",state_col,dir_col]].dropna().copy()
    if d.empty:
        return pd.DataFrame(), {}
    state_med=float(d[state_col].median())
    dir_med=float(d[dir_col].median())
    if state_mode=="low_is_state":
        d["State"] = np.where(d[state_col] <= state_med, "Weak/Deep", "Strong/Shallow")
    else:
        d["State"] = np.where(d[state_col] >= state_med, "Weak/Deep", "Strong/Shallow")
    d["Direction"] = np.where(d[dir_col] <= dir_med, "Deteriorating", "Improving")
    d["TQQQ"]=(d["Target"]=="TQQQ").astype(int)
    rows=[]
    order=[("Strong/Shallow","Improving"),("Strong/Shallow","Deteriorating"),("Weak/Deep","Improving"),("Weak/Deep","Deteriorating")]
    for stt,dr in order:
        g=d[(d["State"]==stt)&(d["Direction"]==dr)]
        rows.append({
            "StateAxis":state_name,"DirectionLagM":lag,"State":stt,"Direction":dr,
            "N":int(len(g)),"TQQQ_N":int(g["TQQQ"].sum()),
            "TQQQ_Rate":float(g["TQQQ"].mean()) if len(g) else np.nan,
            "StateMedian":state_med,"DirectionMedian":dir_med,
        })
    return pd.DataFrame(rows), {"state_median":state_med,"dir_median":dir_med,"classified":d}


























# ================================================================
# My 4F R4 — Actual TQQQ Substitution Audit
#
# User-specified counterfactual:
#   QQQ-MOM risk-on QQQ  -> TQQQ
#   QLD-MOM risk-on QLD  -> TQQQ
#
# EVERYTHING ELSE IS IDENTICAL:
#   - same signal universe
#   - same signal definitions / lookbacks
#   - same trade dates / rebalance rules
#   - same defensive holdings / adaptive safe haven
#   - MR unchanged
#   - VIX unchanged
#   - TEL-DM unchanged
#   - same 4-family monthly EW architecture
#
# This is NOT synthetic leverage.
# It uses actual historical TQQQ adjusted-price returns.
#
# No leverage ladder and no tuning:
#   Control = Frozen original MOM (QQQ + QLD sleeves)
#   Challenger = both MOM risk-on sleeves use TQQQ
#
# DEV cutoff = 2026-07-31.
# ================================================================

def _r4tqqq_build(px_close, rf_bt, start, end):
    cutoff = pd.Timestamp("2026-07-31")
    closes = px_close.copy()
    closes.index = pd.DatetimeIndex(closes.index)
    closes = closes.loc[:cutoff].sort_index().ffill()

    required = ["QQQ","QLD","TQQQ","LQD","GLD","TLT","SPXL","TECL","XLU","^VIX","SPY"]
    miss = [x for x in required if x not in closes.columns]
    if miss:
        raise RuntimeError("Missing required ticker(s): " + ", ".join(miss))

    rf = rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt, pd.Series) else rf_bt

    # EXACT Frozen holding matrix first.
    core_h = _build_core_holding_matrix(closes, rf).reindex(closes.index)

    # EXACT same Adaptive Safe Haven replacement as frozen _v390_build.
    safe_h, _ = _adaptive_safe_haven_monthly_series(closes)
    safe_h = safe_h.reindex(closes.index).ffill()

    h1 = core_h.copy()
    for m in MODEL_WEIGHTS:
        mask = h1[m].eq("GLD")
        h1.loc[mask, m] = safe_h.loc[mask]

    # Counterfactual: only risk-on holdings of the two MOM sleeves are replaced.
    h3 = h1.copy()
    qqq_mask = h3["QQQ-MOM"].eq("QQQ")
    qld_mask = h3["QLD-MOM"].eq("QLD")
    h3.loc[qqq_mask, "QQQ-MOM"] = "TQQQ"
    h3.loc[qld_mask, "QLD-MOM"] = "TQQQ"

    sleeve1 = _returns_from_holding_matrix(h1, closes)
    sleeve3 = _returns_from_holding_matrix(h3, closes)

    f1 = pd.DataFrame(index=sleeve1.index)
    f3 = pd.DataFrame(index=sleeve3.index)

    # Only MOM differs.
    f1["MOM"] = 0.5*sleeve1["QQQ-MOM"] + 0.5*sleeve1["QLD-MOM"]
    f3["MOM"] = 0.5*sleeve3["QQQ-MOM"] + 0.5*sleeve3["QLD-MOM"]

    # MR / VIX copied unchanged from the same original holdings.
    for f in (f1, f3):
        f["MR"] = 0.5*sleeve1["Weekly MR 24M"] + 0.5*sleeve1["Quarterly MR 24M"]
        f["VIX"] = (
            0.25*sleeve1["Old VIX 15d"]
            + 0.25*sleeve1["Old VIX 20d"]
            + 0.5*sleeve1["New VIX 20d"]
        )

    # TEL-DM unchanged.
    tel, _, _, _, _ = _v389_layered_dm(px_close, start, end)
    f1["TEL-DM"] = tel.reindex(f1.index)
    f3["TEL-DM"] = tel.reindex(f3.index)

    common = pd.concat(
        [f1.add_suffix("_1x"), f3.add_suffix("_TQQQ")], axis=1
    ).dropna()
    f1 = f1.reindex(common.index)
    f3 = f3.reindex(common.index)

    p1 = _v390_monthly_rebalanced_ew(f1[["MOM","MR","VIX","TEL-DM"]]).rename("Frozen 4F EW")
    p3 = _v390_monthly_rebalanced_ew(f3[["MOM","MR","VIX","TEL-DM"]]).rename("TQQQ-MOM 4F EW")
    pf = pd.concat([p1,p3],axis=1).dropna().loc[:cutoff]

    # Exact implementation audit.
    audit = pd.DataFrame({
        "Date": h1.index,
        "QQQ-MOM original": h1["QQQ-MOM"].astype(str).values,
        "QQQ-MOM TQQQ version": h3["QQQ-MOM"].astype(str).values,
        "QLD-MOM original": h1["QLD-MOM"].astype(str).values,
        "QLD-MOM TQQQ version": h3["QLD-MOM"].astype(str).values,
    }).set_index("Date")
    audit["QQQ sleeve changed"] = audit["QQQ-MOM original"] != audit["QQQ-MOM TQQQ version"]
    audit["QLD sleeve changed"] = audit["QLD-MOM original"] != audit["QLD-MOM TQQQ version"]

    return pf, f1, f3, audit

def _r4tqqq_monthly(x):
    return (1.0 + x).resample("ME").prod(min_count=1) - 1.0

def _r4tqqq_metric_table(d):
    return pd.DataFrame([_v325_metric_row(c,d[c]) for c in d.columns]).set_index("Variant")

def _r4tqqq_family_metrics(f1, f3):
    rows=[]
    for fam in ["MOM","MR","VIX","TEL-DM"]:
        a=_v325_metric_row(fam+" Original", f1[fam])
        b=_v325_metric_row(fam+" TQQQ-version", f3[fam])
        a["Family"]=fam; a["Version"]="Original"
        b["Family"]=fam; b["Version"]="TQQQ-version"
        rows.extend([a,b])
    return pd.DataFrame(rows)

def _r4tqqq_mapping_stats(f1m, f3m):
    gods = _fgmap_r3_gods()
    expected = {
        "Seiryu-Gekiko":"MOM",
        "Suzaku-Gekiko":"TEL-DM",
        "Byakko-Gekiko":"VIX",
        "Genbu-Gekiko":"MR",
    }
    rows=[]
    for god, fam in expected.items():
        g = gods[god]["Return"]
        for version, fs in [("Original",f1m),("TQQQ-version",f3m)]:
            z=pd.concat([g.rename("God"),fs[fam].rename("Family")],axis=1).dropna()
            if len(z)<12: continue
            x=z["Family"].to_numpy(float); y=z["God"].to_numpy(float)
            X=np.column_stack([np.ones(len(x)),x])
            coef=np.linalg.lstsq(X,y,rcond=None)[0]
            fit=X@coef
            sst=float(np.sum((y-y.mean())**2))
            ssr=float(np.sum((y-fit)**2))
            rows.append({
                "God":god,"ExpectedFamily":fam,"Version":version,"Months":len(z),
                "Pearson":float(z["God"].corr(z["Family"])),
                "Spearman":float(z["God"].corr(z["Family"],method="spearman")),
                "God_on_Family_Beta":float(coef[1]),
                "R2":float(1-ssr/sst) if sst>0 else np.nan,
                "GodAnnVol":float(z["God"].std(ddof=1)*np.sqrt(12)),
                "FamilyAnnVol":float(z["Family"].std(ddof=1)*np.sqrt(12)),
                "VolRatio_God_over_Family":float(
                    (z["God"].std(ddof=1)*np.sqrt(12)) /
                    (z["Family"].std(ddof=1)*np.sqrt(12))
                ) if z["Family"].std(ddof=1)>0 else np.nan,
            })
    return pd.DataFrame(rows)

def _r4tqqq_seiryu_fingerprint(f1m, f3m, spy):
    gods=_fgmap_r3_gods()
    g=gods["Seiryu-Gekiko"]["Return"]

    def row(name,s):
        z=pd.concat([s.rename("R"),spy.rename("SPY")],axis=1).dropna()
        q10=z["SPY"].quantile(.10); q90=z["SPY"].quantile(.90)
        up=z[z["SPY"]>0]; dn=z[z["SPY"]<0]
        return {
            "Series":name,"Months":len(z),
            "AnnVol":float(z["R"].std(ddof=1)*np.sqrt(12)),
            "SPY_Corr":float(z["R"].corr(z["SPY"])),
            "SPY_Beta":_fgmap_r3_beta(z["R"],z["SPY"]),
            "UpBeta":_fgmap_r3_beta(up["R"],up["SPY"]),
            "DownBeta":_fgmap_r3_beta(dn["R"],dn["SPY"]),
            "WorstSPYDecileMean":float(z.loc[z["SPY"]<=q10,"R"].mean()),
            "BestSPYDecileMean":float(z.loc[z["SPY"]>=q90,"R"].mean()),
            "MeanMonthly":float(z["R"].mean()),
        }
    fp=pd.DataFrame([
        row("Seiryu-Gekiko",g),
        row("MOM Original",f1m["MOM"]),
        row("MOM TQQQ-version",f3m["MOM"]),
    ])
    feats=["AnnVol","SPY_Corr","SPY_Beta","UpBeta","DownBeta",
           "WorstSPYDecileMean","BestSPYDecileMean","MeanMonthly"]
    # Distances relative to Seiryu, feature-scaled using these three observed series.
    z=fp.set_index("Series")[feats]
    sd=z.std(ddof=0).replace(0,np.nan)
    zz=(z-z.mean())/sd
    rows=[]
    for s in ["MOM Original","MOM TQQQ-version"]:
        rows.append({
            "Series":s,
            "DistanceToSeiryu":float(np.sqrt(np.nanmean((zz.loc[s]-zz.loc["Seiryu-Gekiko"])**2)))
        })
    return fp,pd.DataFrame(rows)

def _r4tqqq_fixed_eras(pf):
    eras=[
        ("2012-2015","2012-01-01","2015-12-31"),
        ("2016-2019","2016-01-01","2019-12-31"),
        ("2020-2022","2020-01-01","2022-12-31"),
        ("2023-DEV","2023-01-01","2026-07-31"),
    ]
    rows=[]
    for nm,a,b in eras:
        x=pf.loc[a:b].dropna()
        for c in pf.columns:
            if len(x):
                r=_v325_metric_row(c,x[c])
                r.update({"Era":nm})
                rows.append(r)
    return pd.DataFrame(rows)

def _r4tqqq_wf_blocks(monthly):
    return _v355_wf_blocks(monthly.to_period("M"),"Frozen 4F EW","TQQQ-MOM 4F EW",13)

def _r4tqqq_cpcv(monthly):
    return _v326_cpcv_summary(monthly.to_period("M"),"Frozen 4F EW",["TQQQ-MOM 4F EW"])

def _r4tqqq_month_removal(monthly):
    z=monthly.dropna().copy()
    z["Active"]=z["TQQQ-MOM 4F EW"]-z["Frozen 4F EW"]
    rows=[]
    for n in [0,1,3,5,10]:
        q=z if n==0 else z.drop(index=z.nlargest(n,"Active").index)
        rows.append({
            "RemovedBestActiveMonths":n,
            "Months":len(q),
            "MeanActiveMonthly":float((q["TQQQ-MOM 4F EW"]-q["Frozen 4F EW"]).mean()),
            "TQQQVersionWins":bool((q["TQQQ-MOM 4F EW"]-q["Frozen 4F EW"]).mean()>0),
        })
    return pd.DataFrame(rows)



# ================================================================
# Four Gods × My Families R5 — Leveraged Asset Substitution Decomposition
#
# Goal:
#   For each already-mapped family, ask whether replacing ONLY the
#   family's original exposure asset(s) by the leveraged ETF(s) actually
#   used by the corresponding Shin-God moves the user family closer to
#   that God.
#
# Fixed mapping inherited from R3:
#   Seiryu -> MOM
#   Suzaku -> TEL-DM
#   Byakko -> VIX
#   Genbu  -> MR
#
# Pre-fixed substitutions:
#   Seiryu/MOM:
#       QQQ-MOM: QQQ -> TQQQ
#       QLD-MOM: QLD -> TQQQ
#
#   Suzaku/TEL:
#       TEL already uses TMV / TQQQ / TECL.
#       Therefore NO substitution is made. This is the same leveraged
#       asset universe already and acts as the positive lineage control.
#
#   Byakko/VIX:
#       Only leveraged-tech exposure assets are normalized to the
#       Byakko attack universe:
#       QQQ -> TQQQ, QLD -> TQQQ, SPXL -> TQQQ.
#       GLD / safe-haven logic and all VIX signals/timing remain unchanged.
#       Existing TQQQ / TECL stay unchanged.
#
#   Genbu/MR:
#       Only risk-on QQQ / QLD exposures are replaced by TQQQ.
#       XLU and all MR signals/timing remain unchanged.
#       This matches Genbu's observed XLU/TQQQ asset universe without
#       changing the reversal rule.
#
# No alternative mappings, no leverage sweep, no parameter tuning,
# no signal/lookback/timing changes, no rescue.
# Actual historical ETF adjusted-price returns are used.
# DEV cutoff = 2026-07-31.
# ================================================================

def _r5_build_all(px_close, rf_bt, start, end):
    cutoff=pd.Timestamp("2026-07-31")
    closes=px_close.copy()
    closes.index=pd.DatetimeIndex(closes.index)
    closes=closes.loc[:cutoff].sort_index().ffill()
    required=["QQQ","QLD","TQQQ","SPXL","TECL","XLU","GLD","TMV","LQD","TLT","^VIX","SPY"]
    miss=[x for x in required if x not in closes.columns]
    if miss: raise RuntimeError("Missing required ticker(s): "+", ".join(miss))
    rf=rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt,pd.Series) else rf_bt

    core_h=_build_core_holding_matrix(closes,rf).reindex(closes.index)
    safe_h,_=_adaptive_safe_haven_monthly_series(closes)
    safe_h=safe_h.reindex(closes.index).ffill()

    h0=core_h.copy()
    for m in MODEL_WEIGHTS:
        mask=h0[m].eq("GLD")
        h0.loc[mask,m]=safe_h.loc[mask]

    # Original frozen returns.
    r0=_returns_from_holding_matrix(h0,closes)

    # Counterfactual holdings: one common matrix is enough because substitutions
    # affect only the sleeves specified below.
    hc=h0.copy()

    # Seiryu/MOM
    hc.loc[hc["QQQ-MOM"].eq("QQQ"),"QQQ-MOM"]="TQQQ"
    hc.loc[hc["QLD-MOM"].eq("QLD"),"QLD-MOM"]="TQQQ"

    # Genbu/MR: only QQQ/QLD risk-on exposures -> TQQQ.
    for col in ["Weekly MR 24M","Quarterly MR 24M"]:
        hc.loc[hc[col].isin(["QQQ","QLD"]),col]="TQQQ"

    # Byakko/VIX: tech/equity attack exposures -> TQQQ.
    # Existing TQQQ/TECL are already in Byakko's leveraged-tech attack universe
    # and remain unchanged. Defensive/safe-haven holdings are untouched.
    for col in ["Old VIX 15d","Old VIX 20d","New VIX 20d"]:
        hc.loc[hc[col].isin(["QQQ","QLD","SPXL"]),col]="TQQQ"

    rc=_returns_from_holding_matrix(hc,closes)

    f0=pd.DataFrame(index=r0.index)
    fc=pd.DataFrame(index=rc.index)
    f0["MOM"]=0.5*r0["QQQ-MOM"]+0.5*r0["QLD-MOM"]
    fc["MOM"]=0.5*rc["QQQ-MOM"]+0.5*rc["QLD-MOM"]

    f0["MR"]=0.5*r0["Weekly MR 24M"]+0.5*r0["Quarterly MR 24M"]
    fc["MR"]=0.5*rc["Weekly MR 24M"]+0.5*rc["Quarterly MR 24M"]

    f0["VIX"]=0.25*r0["Old VIX 15d"]+0.25*r0["Old VIX 20d"]+0.5*r0["New VIX 20d"]
    fc["VIX"]=0.25*rc["Old VIX 15d"]+0.25*rc["Old VIX 20d"]+0.5*rc["New VIX 20d"]

    tel,_,_,_,_=_v389_layered_dm(px_close,start,end)
    tel=tel.reindex(f0.index)
    f0["TEL-DM"]=tel
    fc["TEL-DM"]=tel  # exact unchanged positive-lineage control

    both=pd.concat([f0.add_suffix("_Original"),fc.add_suffix("_GodAssets")],axis=1).dropna()
    f0=f0.reindex(both.index)
    fc=fc.reindex(both.index)

    p0=_v390_monthly_rebalanced_ew(f0[["MOM","MR","VIX","TEL-DM"]]).rename("Frozen 4F EW")
    pc=_v390_monthly_rebalanced_ew(fc[["MOM","MR","VIX","TEL-DM"]]).rename("God-Asset 4F EW")
    pf=pd.concat([p0,pc],axis=1).dropna().loc[:cutoff]

    # Holding-change audit by sleeve.
    audit=[]
    for col in h0.columns:
        a=h0[col].astype(str); b=hc[col].astype(str)
        ch=a.ne(b)
        if ch.any():
            trans=pd.DataFrame({"From":a[ch],"To":b[ch]})
            for (fr,to),n in trans.value_counts().items():
                audit.append({"Sleeve":col,"From":fr,"To":to,"TradingDays":int(n)})
    audit=pd.DataFrame(audit)

    return f0,fc,pf,h0,hc,audit

def _r5_monthly(x):
    return (1+x).resample("ME").prod(min_count=1)-1

def _r5_pair(god,fam):
    z=pd.concat([god.rename("God"),fam.rename("Family")],axis=1).dropna()
    if len(z)<12: return {}
    x=z["Family"].to_numpy(float); y=z["God"].to_numpy(float)
    X=np.column_stack([np.ones(len(x)),x])
    coef=np.linalg.lstsq(X,y,rcond=None)[0]
    fit=X@coef
    sst=float(np.sum((y-y.mean())**2)); ssr=float(np.sum((y-fit)**2))
    return {
        "Months":len(z),
        "Pearson":float(z["God"].corr(z["Family"])),
        "Spearman":float(z["God"].corr(z["Family"],method="spearman")),
        "R2":float(1-ssr/sst) if sst>0 else np.nan,
        "God_on_Family_Beta":float(coef[1]),
        "GodAnnVol":float(z["God"].std(ddof=1)*np.sqrt(12)),
        "FamilyAnnVol":float(z["Family"].std(ddof=1)*np.sqrt(12)),
    }

def _r5_fingerprint_row(name,r,spy):
    z=pd.concat([r.rename("R"),spy.rename("SPY")],axis=1).dropna()
    q10=z["SPY"].quantile(.10); q90=z["SPY"].quantile(.90)
    up=z[z["SPY"]>0]; dn=z[z["SPY"]<0]
    return {
        "Series":name,"Months":len(z),
        "AnnVol":float(z["R"].std(ddof=1)*np.sqrt(12)),
        "SPY_Corr":float(z["R"].corr(z["SPY"])),
        "SPY_Beta":_fgmap_r3_beta(z["R"],z["SPY"]),
        "UpBeta":_fgmap_r3_beta(up["R"],up["SPY"]),
        "DownBeta":_fgmap_r3_beta(dn["R"],dn["SPY"]),
        "WorstSPYDecileMean":float(z.loc[z["SPY"]<=q10,"R"].mean()),
        "BestSPYDecileMean":float(z.loc[z["SPY"]>=q90,"R"].mean()),
        "MeanMonthly":float(z["R"].mean()),
    }

def _r5_family_god_compare(f0m,fcm,spy):
    gods=_fgmap_r3_gods()
    mapping={
        "Seiryu-Gekiko":"MOM",
        "Suzaku-Gekiko":"TEL-DM",
        "Byakko-Gekiko":"VIX",
        "Genbu-Gekiko":"MR",
    }
    pairrows=[]; fprows=[]; distrows=[]
    feats=["AnnVol","SPY_Corr","SPY_Beta","UpBeta","DownBeta",
           "WorstSPYDecileMean","BestSPYDecileMean","MeanMonthly"]

    for god,fam in mapping.items():
        g=gods[god]["Return"]
        a=_r5_pair(g,f0m[fam]); b=_r5_pair(g,fcm[fam])
        pairrows += [
            {"God":god,"Family":fam,"Version":"Original",**a},
            {"God":god,"Family":fam,"Version":"God-Asset",**b},
        ]

        tmp=pd.DataFrame([
            _r5_fingerprint_row(god,g,spy),
            _r5_fingerprint_row(fam+" Original",f0m[fam],spy),
            _r5_fingerprint_row(fam+" God-Asset",fcm[fam],spy),
        ])
        fprows.append(tmp.assign(God=god,Family=fam))

        z=tmp.set_index("Series")[feats]
        sd=z.std(ddof=0).replace(0,np.nan)
        zz=(z-z.mean())/sd
        d0=float(np.sqrt(np.nanmean((zz.loc[fam+" Original"]-zz.loc[god])**2)))
        d1=float(np.sqrt(np.nanmean((zz.loc[fam+" God-Asset"]-zz.loc[god])**2)))
        distrows.append({
            "God":god,"Family":fam,
            "OriginalDistance":d0,"GodAssetDistance":d1,
            "DistanceChange":d1-d0,
            "GodAssetCloser":bool(d1<d0-1e-12),
            "PearsonOriginal":a.get("Pearson",np.nan),
            "PearsonGodAsset":b.get("Pearson",np.nan),
            "PearsonChange":b.get("Pearson",np.nan)-a.get("Pearson",np.nan),
            "VolOriginal":a.get("FamilyAnnVol",np.nan),
            "VolGodAsset":b.get("FamilyAnnVol",np.nan),
            "GodVol":a.get("GodAnnVol",np.nan),
        })
    return pd.DataFrame(pairrows),pd.concat(fprows,ignore_index=True),pd.DataFrame(distrows)

def _r5_perf(f0,fc,pf):
    rows=[]
    for fam in ["MOM","MR","VIX","TEL-DM"]:
        for lab,d in [("Original",f0),("God-Asset",fc)]:
            q=_v325_metric_row(fam+" "+lab,d[fam])
            q.update({"Family":fam,"Version":lab})
            rows.append(q)
    famperf=pd.DataFrame(rows)
    pfperf=pd.DataFrame([_v325_metric_row(c,pf[c]) for c in pf.columns])
    return famperf,pfperf

def _r5_eras(f0m,fcm):
    gods=_fgmap_r3_gods()
    mapping={"Seiryu-Gekiko":"MOM","Suzaku-Gekiko":"TEL-DM",
             "Byakko-Gekiko":"VIX","Genbu-Gekiko":"MR"}
    eras=[("2012-2015","2012-01-01","2015-12-31"),
          ("2016-2019","2016-01-01","2019-12-31"),
          ("2020-2022","2020-01-01","2022-12-31"),
          ("2023-DEV","2023-01-01","2026-07-31")]
    rows=[]
    for god,fam in mapping.items():
        for era,a,b in eras:
            g=gods[god]["Return"].loc[a:b]
            for ver,d in [("Original",f0m),("God-Asset",fcm)]:
                z=pd.concat([g.rename("G"),d[fam].loc[a:b].rename("F")],axis=1).dropna()
                rows.append({"God":god,"Family":fam,"Era":era,"Version":ver,
                             "Months":len(z),
                             "Pearson":float(z["G"].corr(z["F"])) if len(z)>=6 else np.nan})
    return pd.DataFrame(rows)



# ================================================================
# 4F Booster R6 — v3.45 Attack Overlay Transplant
#
# Source-frozen v3.45 logic transplanted onto Frozen 4F:
#   A Gate       = prior month-end TLT 3M total return > 0
#   VIX Brake    = ^VIX close > 30, effective next trading row
#   allow_L2     = A & ~Brake
#   L2 MOM only  = QQQ->QLD, QLD->TQQQ
#   Inflection   = XLK 1M - XLK 3M
#   Turbo        = allow_L2 & (Inflection_t > Inflection_t-1)
#   Selector     = XLK 6M > QQQ 6M => TECL, else TQQQ
#   T2           = Turbo -> 75% TQQQ + 25% proportional non-MOM
#   Attack75     = Turbo -> 75% selected attack asset + 25% proportional non-MOM
#   Promotion100 = Turbo & TECL selected -> 100% TECL
#
# 4F adaptation:
#   - Normal 4F = MOM/MR/VIX/TEL-DM 25% each, monthly rebalanced.
#   - Accelerator only alters MOM risk-on holdings one leverage step.
#   - MR / VIX / TEL-DM signals and returns are never altered by A/Brake.
#   - During Turbo, residual 25% "non-MOM" is proportional across
#     MR/VIX/TEL-DM = 1/3 each within the residual.
#   - No Adaptive Safe Haven change is introduced here: whatever the Frozen
#     4F already uses remains exactly as-is.
#
# No 60/70/80/90 sweep, no threshold/lookback changes, no rescue.
# DEV cutoff = 2026-07-31.
# Current Frozen 4F P&L convention is preserved for clean attribution.
# ================================================================

def _r6_build(px_close, rf_bt, start, end):
    cutoff = pd.Timestamp("2026-07-31")
    closes = px_close.copy()
    closes.index = pd.DatetimeIndex(closes.index)
    closes = closes.loc[:cutoff].sort_index().ffill()

    required = ["QQQ","QLD","TQQQ","TECL","LQD","GLD","TLT","SPXL","XLU","^VIX","SPY","XLK"]
    miss = [x for x in required if x not in closes.columns]
    if miss:
        raise RuntimeError("Missing required ticker(s): " + ", ".join(miss))

    rf = rf_bt.reindex(closes.index).ffill() if isinstance(rf_bt, pd.Series) else rf_bt

    # Frozen 4F source holdings/returns, same as prior 4F research.
    core_h = _build_core_holding_matrix(closes, rf).reindex(closes.index)
    safe_h, _ = _adaptive_safe_haven_monthly_series(closes)
    safe_h = safe_h.reindex(closes.index).ffill()

    h0 = core_h.copy()
    for m in MODEL_WEIGHTS:
        mask = h0[m].eq("GLD")
        h0.loc[mask, m] = safe_h.loc[mask]

    r0 = _returns_from_holding_matrix(h0, closes)

    f0 = pd.DataFrame(index=r0.index)
    f0["MOM"] = 0.5*r0["QQQ-MOM"] + 0.5*r0["QLD-MOM"]
    f0["MR"] = 0.5*r0["Weekly MR 24M"] + 0.5*r0["Quarterly MR 24M"]
    f0["VIX"] = (
        0.25*r0["Old VIX 15d"]
        + 0.25*r0["Old VIX 20d"]
        + 0.5*r0["New VIX 20d"]
    )
    tel, _, _, _, _ = _v389_layered_dm(px_close, start, end)
    f0["TEL-DM"] = tel.reindex(f0.index)
    f0 = f0.dropna()

    idx = f0.index

    # ---- Source-frozen booster signals ----
    gates, gate_audit = _v326_bond_regime_signals(closes, idx)
    gate_a = gates["A TLT3M>0"].reindex(idx).fillna(False).astype(bool)

    # Close(D) VIX signal -> affects next close-to-close row in the current 4F convention.
    vix_raw = (closes["^VIX"] > 30).reindex(idx).fillna(False).astype(bool)
    vix_brake = vix_raw.shift(1).fillna(False).astype(bool)
    allow_l2 = (gate_a & ~vix_brake).astype(bool)

    inflect, inflect_audit = _v332_xlk_inflection_signal(closes, idx)
    inflect = inflect.reindex(idx).fillna(False).astype(bool)
    turbo = (allow_l2 & inflect).astype(bool)

    choose_tecl, selector_audit = _v335_attack_selector_signal(closes, idx)
    choose_tecl = choose_tecl.reindex(idx).fillna(False).astype(bool)

    # ---- A+Brake: alter MOM risk-on holdings only ----
    hab = h0.copy()
    m1 = allow_l2 & hab["QQQ-MOM"].eq("QQQ")
    m2 = allow_l2 & hab["QLD-MOM"].eq("QLD")
    hab.loc[m1, "QQQ-MOM"] = "QLD"
    hab.loc[m2, "QLD-MOM"] = "TQQQ"

    rab = _returns_from_holding_matrix(hab, closes).reindex(idx)
    fab = f0.copy()
    fab["MOM"] = 0.5*rab["QQQ-MOM"] + 0.5*rab["QLD-MOM"]

    # Frozen 4F and A+Brake 4F preserve monthly 25%×4 rebalance.
    control = _v390_monthly_rebalanced_ew(f0[["MOM","MR","VIX","TEL-DM"]]).rename("Frozen 4F EW")
    ab = _v390_monthly_rebalanced_ew(fab[["MOM","MR","VIX","TEL-DM"]]).rename("A+VIX30")

    # Proportional non-MOM = MR / VIX / TEL equally weighted within residual.
    nonmom = _v390_monthly_rebalanced_ew(f0[["MR","VIX","TEL-DM"]]).rename("nonMOM")
    tq = closes["TQQQ"].pct_change(fill_method=None).reindex(idx)
    te = closes["TECL"].pct_change(fill_method=None).reindex(idx)

    # T2: frozen 75% TQQQ +25% proportional non-MOM during Turbo.
    t2 = ab.copy().rename("Turbo75 TQQQ")
    t2.loc[turbo] = 0.75*tq.loc[turbo] + 0.25*nonmom.loc[turbo]

    # Attack #1 equivalent: selector chooses TECL/TQQQ, both at 75%.
    attack75 = ab.copy().rename("Attack75 Selector")
    use_tecl = turbo & choose_tecl
    use_tqqq = turbo & ~choose_tecl
    attack75.loc[use_tecl] = 0.75*te.loc[use_tecl] + 0.25*nonmom.loc[use_tecl]
    attack75.loc[use_tqqq] = 0.75*tq.loc[use_tqqq] + 0.25*nonmom.loc[use_tqqq]

    # v3.45 final: only TECL-selected Turbo rows are promoted from 75% to 100% TECL.
    promo100 = attack75.copy().rename("Promotion100")
    promo = (turbo & choose_tecl).astype(bool)
    promo100.loc[promo] = te.loc[promo]

    daily = pd.concat([control, ab, t2, attack75, promo100], axis=1).dropna().loc[:cutoff]

    states = pd.DataFrame(index=daily.index)
    states["A Gate"] = gate_a.reindex(daily.index).fillna(False)
    states["VIX30 Brake"] = vix_brake.reindex(daily.index).fillna(False)
    states["allow_L2"] = allow_l2.reindex(daily.index).fillna(False)
    states["Inflection improving"] = inflect.reindex(daily.index).fillna(False)
    states["Turbo"] = turbo.reindex(daily.index).fillna(False)
    states["Choose TECL"] = choose_tecl.reindex(daily.index).fillna(False)
    states["Promotion100"] = promo.reindex(daily.index).fillna(False)

    return daily, f0.reindex(daily.index), fab.reindex(daily.index), states, h0, hab, gate_audit, inflect_audit, selector_audit


def _r6_monthly(d):
    return (1+d).resample("ME").prod(min_count=1)-1


def _r6_metrics(d):
    return pd.DataFrame([_v325_metric_row(c, d[c]) for c in d.columns])


def _r6_stage_attribution(monthly):
    stages = [
        ("Accelerator+Brake", "Frozen 4F EW", "A+VIX30"),
        ("Turbo 75% TQQQ", "A+VIX30", "Turbo75 TQQQ"),
        ("TECL/TQQQ Selector", "Turbo75 TQQQ", "Attack75 Selector"),
        ("75→100% TECL Promotion", "Attack75 Selector", "Promotion100"),
        ("Full Booster vs Frozen", "Frozen 4F EW", "Promotion100"),
    ]
    rows = []
    for name, base, ch in stages:
        z = monthly[[base,ch]].dropna()
        active = z[ch]-z[base]
        rows.append({
            "Stage": name,
            "Base": base,
            "Challenger": ch,
            "Months": len(z),
            "MeanActiveMonthly": float(active.mean()),
            "AnnArithmeticActive": float(active.mean()*12),
            "PositiveActiveMonths": int((active>0).sum()),
            "NegativeActiveMonths": int((active<0).sum()),
            "BaseCAGR": _annualized_return_monthly(z[base]),
            "ChallengerCAGR": _annualized_return_monthly(z[ch]),
            "DeltaSharpe0": _monthly_sharpe0(z[ch])-_monthly_sharpe0(z[base]),
            "DeltaSortino0": _monthly_sortino0(z[ch])-_monthly_sortino0(z[base]),
        })
    return pd.DataFrame(rows)


def _r6_state_summary(states):
    n = max(len(states),1)
    rows = []
    for c in states.columns:
        s = states[c].astype(bool)
        # month share uses whether state occurred at least once in calendar month
        mon = s.groupby(s.index.to_period("M")).max()
        rows.append({
            "State": c,
            "TradingDays": int(s.sum()),
            "PctTradingDays": float(s.mean()),
            "MonthsWithState": int(mon.sum()),
            "PctMonthsWithState": float(mon.mean()) if len(mon) else np.nan,
            "Switches": int(s.ne(s.shift()).sum()-1) if len(s) else 0,
        })
    return pd.DataFrame(rows)


def _r6_active_by_state(daily, states):
    active = daily["Promotion100"] - daily["Frozen 4F EW"]
    rows=[]
    for c in ["allow_L2","Turbo","Promotion100"]:
        s=states[c].reindex(active.index).fillna(False).astype(bool)
        for val,label in [(True,"ON"),(False,"OFF")]:
            x=active[s.eq(val)].dropna()
            rows.append({
                "State":c,"Condition":label,"Days":len(x),
                "MeanDailyActive":float(x.mean()) if len(x) else np.nan,
                "PositiveDayShare":float((x>0).mean()) if len(x) else np.nan,
                "CumulativeActiveApprox":float((1+x).prod()-1) if len(x) else np.nan,
            })
    return pd.DataFrame(rows)


def _r6_fixed_eras(daily):
    eras=[
        ("2012-2015","2012-01-01","2015-12-31"),
        ("2016-2019","2016-01-01","2019-12-31"),
        ("2020-2022","2020-01-01","2022-12-31"),
        ("2023-DEV","2023-01-01","2026-07-31"),
    ]
    rows=[]
    for nm,a,b in eras:
        x=daily.loc[a:b].dropna()
        for c in ["Frozen 4F EW","A+VIX30","Turbo75 TQQQ","Attack75 Selector","Promotion100"]:
            if len(x):
                r=_v325_metric_row(c,x[c]); r["Era"]=nm
                rows.append(r)
    return pd.DataFrame(rows)


def _r6_best_month_removal(monthly):
    z=monthly[["Frozen 4F EW","Promotion100"]].dropna().copy()
    z["Active"]=z["Promotion100"]-z["Frozen 4F EW"]
    rows=[]
    for n in [0,1,3,5,10]:
        q=z if n==0 else z.drop(index=z.nlargest(n,"Active").index)
        rows.append({
            "RemovedBestActiveMonths":n,
            "Months":len(q),
            "MeanActiveMonthly":float((q["Promotion100"]-q["Frozen 4F EW"]).mean()),
            "PromotionWins":bool((q["Promotion100"]-q["Frozen 4F EW"]).mean()>0),
        })
    return pd.DataFrame(rows)


def _r6_stress(daily):
    episodes=[
        ("2015 selloff","2015-07-01","2015-09-30"),
        ("2018 Q4","2018-10-01","2018-12-31"),
        ("COVID","2020-02-01","2020-04-30"),
        ("2022 selloff","2022-04-01","2022-10-31"),
        ("2025 selloff","2025-02-01","2025-04-30"),
    ]
    rows=[]
    for nm,a,b in episodes:
        row={"Episode":nm}
        for c in ["Frozen 4F EW","A+VIX30","Attack75 Selector","Promotion100"]:
            x=daily.loc[a:b,c].dropna()
            eq=(1+x).cumprod()
            row[c+" Return"]=float((1+x).prod()-1) if len(x) else np.nan
            row[c+" MaxDD"]=float((eq/eq.cummax()-1).min()) if len(x) else np.nan
        rows.append(row)
    return pd.DataFrame(rows)



# ================================================================
# R7 — Frozen v3.45 vs 4F Attack75 Championship
#
# PRE-REGISTERED PURPOSE:
#   Directly compare the two already-frozen architectures on one common
#   DEV sample and one common Close-to-Close adjusted-price convention.
#   This is comparison/falsification only — NOT optimization.
#
# Competitors:
#   A) Frozen v3.45 = Frozen Core + Adaptive Safe Haven + A/VIX30 +
#      Turbo/Selector + TECL Promotion100.
#   B) 4F Attack75 = Frozen 4F EW + source-frozen A/VIX30 +
#      Turbo75 TECL/TQQQ selector, NO Promotion100.
#   C) Frozen 4F EW is retained as reference only.
#
# No threshold/lookback/weight search. No rescue. DEV cutoff=2026-07-31.
# ================================================================

def _r7_v345_close(px_close, rf_bt, start, end):
    cutoff=pd.Timestamp('2026-07-31')
    closes=px_close.copy(); closes.index=pd.DatetimeIndex(closes.index)
    closes=closes.loc[:cutoff].sort_index().ffill()
    idx=closes.index
    needed=['QQQ','QLD','TQQQ','LQD','GLD','TLT','SPXL','TECL','XLU','^VIX','SPY','XLK']
    miss=[x for x in needed if x not in closes.columns]
    if miss: raise RuntimeError('R7 missing ticker(s): '+', '.join(miss))
    ret=closes.pct_change(fill_method=None)
    core_h=_build_core_holding_matrix(closes,rf_bt).reindex(idx)
    safe_h,_=_adaptive_safe_haven_monthly_series(closes)
    safe_h=safe_h.reindex(idx).ffill()
    adaptive_h=core_h.copy()
    for m in MODEL_WEIGHTS:
        mask=adaptive_h[m].eq('GLD'); adaptive_h.loc[mask,m]=safe_h.loc[mask]
    gates,_=_v326_bond_regime_signals(closes,idx)
    gate_a=gates['A TLT3M>0'].reindex(idx).ffill().fillna(False).astype(bool)
    # Same Close-to-Close convention as R6: today's VIX close brakes next return row.
    vix_raw=(closes['^VIX']>30).reindex(idx).fillna(False).astype(bool)
    vix_brake=vix_raw.shift(1).fillna(False).astype(bool)
    allow=(gate_a & ~vix_brake).astype(bool)
    avix_h=_v326_apply_l2_gate(adaptive_h,allow)
    avix_ret=_portfolio_return_from_holdings_fast(avix_h,ret)
    inflect,_=_v332_xlk_inflection_signal(closes,idx)
    inflect=inflect.reindex(idx).fillna(False).astype(bool)
    turbo=(allow & inflect).astype(bool)
    choose,_=_v335_attack_selector_signal(closes,idx)
    choose=choose.reindex(idx).fillna(False).astype(bool)
    t1_h=_v332_apply_turbo_l3(avix_h,turbo)
    t1_ret=_portfolio_return_from_holdings_fast(t1_h,ret)
    _,attack=_v335_build_t2_and_attack_returns(avix_ret,t1_ret,ret['TQQQ'],ret['TECL'],turbo,choose)
    promo=(turbo & choose).astype(bool)
    v345=attack.copy(); v345.loc[promo]=ret['TECL'].reindex(idx).loc[promo]
    states=pd.DataFrame({'v345_GateA':gate_a,'v345_VIXBrake':vix_brake,'v345_Turbo':turbo,'v345_ChooseTECL':choose,'v345_Promotion100':promo},index=idx)
    return v345.rename('Frozen v3.45'),states

def _r7_perf_rows(d):
    return pd.DataFrame([_v325_metric_row(c,d[c]) for c in d.columns])

def _r7_eras(d):
    eras=[('2012-2015','2012-01-01','2015-12-31'),('2016-2019','2016-01-01','2019-12-31'),('2020-2022','2020-01-01','2022-12-31'),('2023-DEV','2023-01-01','2026-07-31')]
    rows=[]
    for name,a,b in eras:
        q=d.loc[a:b]
        if len(q)<20: continue
        m=_r7_perf_rows(q).set_index('Variant')
        row={'Era':name,'Start':q.index.min(),'End':q.index.max(),'TradingDays':len(q)}
        for c in d.columns:
            row[c+'_CAGR']=m.loc[c,'CAGR']; row[c+'_Sharpe0']=m.loc[c,'Sharpe0']; row[c+'_Sortino0']=m.loc[c,'Sortino0']; row[c+'_DailyMaxDD']=m.loc[c,'Daily MaxDD']
        row['Attack75_minus_v345_CAGR']=row['4F Attack75_CAGR']-row['Frozen v3.45_CAGR']
        rows.append(row)
    return pd.DataFrame(rows)

def _r7_rolling36(monthly):
    rows=[]
    for i in range(35,len(monthly)):
        q=monthly.iloc[i-35:i+1]
        a=_annualized_return_monthly(q['4F Attack75']); v=_annualized_return_monthly(q['Frozen v3.45'])
        rows.append({'EndMonth':q.index[-1],'StartMonth':q.index[0],'Attack75_CAGR':a,'v345_CAGR':v,'DeltaCAGR':a-v,
                     'Attack75_Sharpe0':_monthly_sharpe0(q['4F Attack75']),'v345_Sharpe0':_monthly_sharpe0(q['Frozen v3.45']),
                     'Attack75_Sortino0':_monthly_sortino0(q['4F Attack75']),'v345_Sortino0':_monthly_sortino0(q['Frozen v3.45'])})
    return pd.DataFrame(rows)

def _r7_best_month_removal(monthly):
    z=monthly[['Frozen v3.45','4F Attack75']].dropna().copy(); z['Active']=z['4F Attack75']-z['Frozen v3.45']
    ranked=z['Active'].sort_values(ascending=False); rows=[]
    for k in [0,1,3,5,10]:
        q=z.drop(index=ranked.head(k).index) if k else z
        rows.append({'RemovedBestAttack75ActiveMonths':k,'Months':len(q),'MeanActiveMonthly':q['Active'].mean(),
                     'Attack75_CAGR':_annualized_return_monthly(q['4F Attack75']),'v345_CAGR':_annualized_return_monthly(q['Frozen v3.45']),
                     'DeltaCAGR':_annualized_return_monthly(q['4F Attack75'])-_annualized_return_monthly(q['Frozen v3.45'])})
    return pd.DataFrame(rows)

def _r7_stress(d):
    windows=[('2015 selloff','2015-08-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),('COVID','2020-02-01','2020-04-30'),('2022 selloff','2022-01-01','2022-10-31'),('2025 selloff','2025-01-01','2025-06-30')]
    rows=[]
    for name,a,b in windows:
        q=d.loc[a:b]
        if not len(q): continue
        row={'Window':name,'TradingDays':len(q)}
        for c in d.columns:
            row[c+'_Return']=float((1+q[c]).prod()-1); row[c+'_MaxDD']=float(((1+q[c]).cumprod()/(1+q[c]).cumprod().cummax()-1).min())
        rows.append(row)
    return pd.DataFrame(rows)

