# ================================================================
# R8 — v3.45 Advantage Decomposition
#
# PRE-REGISTERED PURPOSE:
#   Explain WHY Frozen v3.45 beat 4F Attack75 in official R7.
#   Diagnostic / attribution only. No optimization, no threshold search,
#   no alternative lookback, no weight sweep, no rescue rule.
#
# Fixed decomposition:
#   1) Base composition: 4F 25/25/25/25 -> 3F 50/25/25 (TEL -> MOM)
#   2) Rebalancing convention: monthly family rebalance -> v3.45 fixed
#      7-sleeve weights (daily portfolio aggregation)
#   3) A+VIX30 state under matched architectures
#   4) Common Attack75 selector architecture difference
#   5) Promotion100 increment (75% -> 100% TECL) separately
#   6) Final R7 championship difference = architecture + promotion
#
# DEV cutoff = 2026-07-31. Historical results cannot change rules.
# ================================================================

def _r8_monthly_rebalanced_weighted(daily_components, weights, name):
    x=daily_components[list(weights)].dropna().copy()
    if x.empty:
        return pd.Series(dtype=float,name=name)
    w0=pd.Series(weights,dtype=float).reindex(x.columns)
    w0=w0/w0.sum()
    out=[]
    for _,g in x.groupby(x.index.to_period('M')):
        wealth=w0.copy()
        for dt,row in g.iterrows():
            w=wealth/wealth.sum()
            rr=float((w*row).sum())
            out.append((dt,rr))
            wealth=wealth*(1.0+row)
    return pd.Series(dict(out),name=name).sort_index()


def _r8_v345_components(px_close,rf_bt,start,end):
    cutoff=pd.Timestamp('2026-07-31')
    closes=px_close.copy(); closes.index=pd.DatetimeIndex(closes.index)
    closes=closes.loc[:cutoff].sort_index().ffill(); idx=closes.index
    ret=closes.pct_change(fill_method=None)
    core_h=_build_core_holding_matrix(closes,rf_bt).reindex(idx)
    safe_h,_=_adaptive_safe_haven_monthly_series(closes); safe_h=safe_h.reindex(idx).ffill()
    adaptive_h=core_h.copy()
    for m in MODEL_WEIGHTS:
        mask=adaptive_h[m].eq('GLD'); adaptive_h.loc[mask,m]=safe_h.loc[mask]
    adaptive_ret=_portfolio_return_from_holdings_fast(adaptive_h,ret).rename('v345 Adaptive Base')
    gates,_=_v326_bond_regime_signals(closes,idx)
    gate_a=gates['A TLT3M>0'].reindex(idx).ffill().fillna(False).astype(bool)
    vix_raw=(closes['^VIX']>30).reindex(idx).fillna(False).astype(bool)
    vix_brake=vix_raw.shift(1).fillna(False).astype(bool)
    allow=(gate_a & ~vix_brake).astype(bool)
    avix_h=_v326_apply_l2_gate(adaptive_h,allow)
    avix_ret=_portfolio_return_from_holdings_fast(avix_h,ret).rename('v345 A+VIX30')
    inflect,_=_v332_xlk_inflection_signal(closes,idx); inflect=inflect.reindex(idx).fillna(False).astype(bool)
    turbo=(allow & inflect).astype(bool)
    choose,_=_v335_attack_selector_signal(closes,idx); choose=choose.reindex(idx).fillna(False).astype(bool)
    t1_h=_v332_apply_turbo_l3(avix_h,turbo)
    t1_ret=_portfolio_return_from_holdings_fast(t1_h,ret)
    _,attack75=_v335_build_t2_and_attack_returns(avix_ret,t1_ret,ret['TQQQ'],ret['TECL'],turbo,choose)
    attack75=attack75.rename('v345 Attack75 pre-Promotion')
    promo=(turbo & choose).astype(bool)
    final=attack75.copy().rename('Frozen v3.45 Final')
    final.loc[promo]=ret['TECL'].reindex(idx).loc[promo]
    states=pd.DataFrame({'GateA':gate_a,'VIX30 Brake':vix_brake,'allow_L2':allow,'Turbo':turbo,'Choose TECL':choose,'Promotion100':promo},index=idx)
    return pd.concat([adaptive_ret,avix_ret,attack75,final],axis=1),states,adaptive_h,avix_h


def _r8_build(px_bt,rf_bt,start,end):
    cutoff=pd.Timestamp('2026-07-31')
    r6,f0,fab,r6states,h0,hab,_,_,_=_r6_build(px_bt,rf_bt,start,end)
    v,states,_,_=_r8_v345_components(px_bt,rf_bt,start,end)
    # Diagnostic composition bridge: same 3 families as v3.45, frozen weights 50/25/25,
    # but using the 4F monthly-rebalance convention. No optimized weight is introduced.
    three_base=_r8_monthly_rebalanced_weighted(f0,{'MOM':0.50,'MR':0.25,'VIX':0.25},'3F 50/25/25 Monthly')
    three_ab=_r8_monthly_rebalanced_weighted(fab,{'MOM':0.50,'MR':0.25,'VIX':0.25},'3F A+Brake 50/25/25 Monthly')
    d=pd.concat([
        r6['Frozen 4F EW'].rename('Frozen 4F Base'),three_base,
        v['v345 Adaptive Base'],r6['A+VIX30'].rename('4F A+VIX30'),three_ab,
        v['v345 A+VIX30'],r6['Attack75 Selector'].rename('4F Attack75'),
        v['v345 Attack75 pre-Promotion'],r6['Promotion100'].rename('4F Promotion100'),
        v['Frozen v3.45 Final']
    ],axis=1).dropna().loc[:cutoff]
    states=states.reindex(d.index).fillna(False)
    return d,states,f0.reindex(d.index),fab.reindex(d.index)


def _r8_pairwise_stage(monthly):
    pairs=[
      ('Base composition: TEL25→MOM25','Frozen 4F Base','3F 50/25/25 Monthly'),
      ('Base rebalance convention','3F 50/25/25 Monthly','v345 Adaptive Base'),
      ('Base total architecture','Frozen 4F Base','v345 Adaptive Base'),
      ('A+Brake composition','4F A+VIX30','3F A+Brake 50/25/25 Monthly'),
      ('A+Brake rebalance convention','3F A+Brake 50/25/25 Monthly','v345 A+VIX30'),
      ('A+Brake total architecture','4F A+VIX30','v345 A+VIX30'),
      ('Common Attack75 architecture','4F Attack75','v345 Attack75 pre-Promotion'),
      ('Promotion on 4F architecture','4F Attack75','4F Promotion100'),
      ('Promotion on v345 architecture','v345 Attack75 pre-Promotion','Frozen v3.45 Final'),
      ('Official R7 final gap','4F Attack75','Frozen v3.45 Final'),
    ]
    rows=[]
    for stage,a,b in pairs:
        z=monthly[[a,b]].dropna(); act=z[b]-z[a]
        rows.append({'Stage':stage,'Base':a,'Challenger':b,'Months':len(z),
          'MeanActiveMonthly':float(act.mean()),'PositiveMonthShare':float((act>0).mean()),
          'BaseCAGR':_annualized_return_monthly(z[a]),'ChallengerCAGR':_annualized_return_monthly(z[b]),
          'DeltaCAGR':_annualized_return_monthly(z[b])-_annualized_return_monthly(z[a]),
          'DeltaSharpe0':_monthly_sharpe0(z[b])-_monthly_sharpe0(z[a]),
          'DeltaSortino0':_monthly_sortino0(z[b])-_monthly_sortino0(z[a])})
    return pd.DataFrame(rows)


def _r8_state_attribution(d,states):
    # Exact R7 daily active = architecture at common Attack75 + promotion increment.
    arch=d['v345 Attack75 pre-Promotion']-d['4F Attack75']
    promo=d['Frozen v3.45 Final']-d['v345 Attack75 pre-Promotion']
    final=d['Frozen v3.45 Final']-d['4F Attack75']
    state=pd.Series('Turbo TQQQ',index=d.index,dtype=object)
    state.loc[~states['Turbo']]='Non-Turbo'
    state.loc[states['Turbo'] & states['Choose TECL']]='Turbo TECL'
    rows=[]
    for nm in ['All','Non-Turbo','Turbo TQQQ','Turbo TECL']:
        mask=pd.Series(True,index=d.index) if nm=='All' else state.eq(nm)
        for comp,x in [('Architecture common Attack75',arch),('Promotion increment',promo),('Final v345 - 4F Attack75',final)]:
            q=x[mask].dropna()
            rows.append({'State':nm,'Component':comp,'Days':len(q),'ShareDays':float(len(q)/len(d)),
                         'MeanDailyActive':float(q.mean()) if len(q) else np.nan,
                         'SumDailyActive':float(q.sum()) if len(q) else np.nan,
                         'PositiveDayShare':float((q>0).mean()) if len(q) else np.nan})
    return pd.DataFrame(rows),pd.DataFrame({'State':state,'ArchitectureActive':arch,'PromotionActive':promo,'FinalActive':final},index=d.index)


def _r8_yearly_decomposition(d):
    x=pd.DataFrame(index=d.index)
    x['Architecture']=d['v345 Attack75 pre-Promotion']-d['4F Attack75']
    x['Promotion']=d['Frozen v3.45 Final']-d['v345 Attack75 pre-Promotion']
    x['Final']=d['Frozen v3.45 Final']-d['4F Attack75']
    rows=[]
    for y,g in x.groupby(x.index.year):
        rows.append({'Year':int(y),'Days':len(g),'ArchitectureMeanDaily':g['Architecture'].mean(),
                     'PromotionMeanDaily':g['Promotion'].mean(),'FinalMeanDaily':g['Final'].mean(),
                     'ArchitectureSum':g['Architecture'].sum(),'PromotionSum':g['Promotion'].sum(),'FinalSum':g['Final'].sum()})
    return pd.DataFrame(rows)


def _r8_rolling36(monthly):
    rows=[]
    for i in range(35,len(monthly)):
        q=monthly.iloc[i-35:i+1]
        for label,a,b in [('Architecture','4F Attack75','v345 Attack75 pre-Promotion'),('Final','4F Attack75','Frozen v3.45 Final')]:
            rows.append({'Comparison':label,'StartMonth':q.index[0],'EndMonth':q.index[-1],
                         'DeltaCAGR':_annualized_return_monthly(q[b])-_annualized_return_monthly(q[a]),
                         'DeltaSharpe0':_monthly_sharpe0(q[b])-_monthly_sharpe0(q[a]),
                         'DeltaSortino0':_monthly_sortino0(q[b])-_monthly_sortino0(q[a])})
    return pd.DataFrame(rows)


def _r8_stress(d):
    windows=[('2015 selloff','2015-08-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),('COVID','2020-02-01','2020-04-30'),('2022 selloff','2022-01-01','2022-10-31'),('2025 selloff','2025-01-01','2025-06-30')]
    cols=['Frozen 4F Base','v345 Adaptive Base','4F Attack75','v345 Attack75 pre-Promotion','Frozen v3.45 Final']
    rows=[]
    for nm,a,b in windows:
        q=d.loc[a:b]; row={'Window':nm,'TradingDays':len(q)}
        for c in cols:
            x=q[c].dropna(); eq=(1+x).cumprod(); row[c+' Return']=float((1+x).prod()-1); row[c+' MaxDD']=float((eq/eq.cummax()-1).min())
        rows.append(row)
    return pd.DataFrame(rows)


