def _r9_pair_metrics(d):
    cols=['Frozen 4F Base','4F Attack75','4F Promotion100','Frozen v3.45 Final']
    return _r7_perf_rows(d[cols])

def _r9_rolling36(monthly):
    rows=[]
    a='4F Promotion100'; b='Frozen v3.45 Final'
    for i in range(35,len(monthly)):
        q=monthly.iloc[i-35:i+1][[a,b]].dropna()
        if len(q)<36: continue
        rows.append({'StartMonth':q.index[0],'EndMonth':q.index[-1],
          'DeltaCAGR_v345_minus_4FPromo':_annualized_return_monthly(q[b])-_annualized_return_monthly(q[a]),
          'DeltaSharpe0':_monthly_sharpe0(q[b])-_monthly_sharpe0(q[a]),
          'DeltaSortino0':_monthly_sortino0(q[b])-_monthly_sortino0(q[a])})
    return pd.DataFrame(rows)

def _r9_state_compare(d,states):
    active=d['Frozen v3.45 Final']-d['4F Promotion100']
    state=pd.Series('Turbo TQQQ',index=d.index,dtype=object)
    state.loc[~states['Turbo']]='Non-Turbo'
    state.loc[states['Turbo'] & states['Choose TECL']]='Turbo TECL / Promotion100'
    rows=[]
    for nm in ['All','Non-Turbo','Turbo TQQQ','Turbo TECL / Promotion100']:
        mask=pd.Series(True,index=d.index) if nm=='All' else state.eq(nm)
        q=active[mask].dropna()
        rows.append({'State':nm,'Days':len(q),'ShareDays':len(q)/len(d),'MeanDailyActive_v345_minus_4FPromo':q.mean(),
                     'PositiveDayShare':(q>0).mean(),'SumDailyActive':q.sum()})
    return pd.DataFrame(rows)

def render_r9_v345_vs_4f_promotion100(px_bt,rf_bt,bt_start,bt_end):
    st.header('🧪 R9b — v3.45 Final vs 4F Promotion100 Consistency Audit')
    st.caption('R9の戦略仕様は一切変更せず、日次headline指標と月次robustness指標を明示的に分離して再集計します。')
    st.info('固定比較のみ。4F Promotion100 = Frozen 4F + source-frozen v3.45 attack engine + TECL-selected Turbo時100% TECL。対戦相手はFrozen v3.45 Final。DEV cutoff=2026-07-31。75%、VIX30、TLT3M、XLK lookback、selector等の再調整なし。')
    if not st.button('R9b Consistency Auditを実行',type='primary',use_container_width=True,key='run_r9b_champ'):
        return
    p=st.progress(0,text='R9b 0/11 — R9と同じ両Final strategyを固定仕様で再構築中…')
    d,states,_,_=_r8_build(px_bt,rf_bt,bt_start,bt_end)
    pair=d[['4F Promotion100','Frozen v3.45 Final']].dropna().loc[:pd.Timestamp('2026-07-31')]
    p.progress(12,text='R9b 1/11 — Full metricsを計算中…')
    metrics=_r9_pair_metrics(d)
    # _r7_perf_rows uses the canonical column name 'Variant'. R9b presents it as 'Strategy'
    # only for this audit/export layer; strategy calculations are unchanged.
    if 'Strategy' not in metrics.columns and 'Variant' in metrics.columns:
        metrics=metrics.rename(columns={'Variant':'Strategy'})
    monthly=(1+pair).resample('ME').prod(min_count=1)-1
    active=monthly['Frozen v3.45 Final']-monthly['4F Promotion100']
    m4=metrics.set_index('Strategy').loc['4F Promotion100']
    mv=metrics.set_index('Strategy').loc['Frozen v3.45 Final']
    summary=pd.DataFrame([{'Months':len(monthly),'MeanActiveMonthly_v345_minus_4FPromo':active.mean(),
      'PositiveMonthShare_v345':(active>0).mean(),'DailyCorrelation':pair.corr().iloc[0,1],
      'MonthlyCorrelation':monthly.corr().iloc[0,1],
      'Headline_DeltaCAGR_v345_minus_4FPromo':float(mv['CAGR']-m4['CAGR']),
      'Headline_DeltaSharpe0_DAILY':float(mv['Sharpe0']-m4['Sharpe0']),
      'Headline_DeltaSortino0_DAILY':float(mv['Sortino0']-m4['Sortino0']),
      'Robustness_DeltaCAGR_MONTHLY':_annualized_return_monthly(monthly['Frozen v3.45 Final'])-_annualized_return_monthly(monthly['4F Promotion100']),
      'Robustness_DeltaSharpe0_MONTHLY':_monthly_sharpe0(monthly['Frozen v3.45 Final'])-_monthly_sharpe0(monthly['4F Promotion100']),
      'Robustness_DeltaSortino0_MONTHLY':_monthly_sortino0(monthly['Frozen v3.45 Final'])-_monthly_sortino0(monthly['4F Promotion100'])}])
    p.progress(23,text='R9b 2/11 — 4 fixed erasを比較中…')
    eras=[]
    for nm,a,b in [('2012-2015','2012-01-01','2015-12-31'),('2016-2019','2016-01-01','2019-12-31'),('2020-2022','2020-01-01','2022-12-31'),('2023-DEV','2023-01-01','2026-07-31')]:
        q=monthly.loc[a:b]; x=q['4F Promotion100']; y=q['Frozen v3.45 Final']
        dc=_annualized_return_monthly(y)-_annualized_return_monthly(x)
        ds=_monthly_sharpe0(y)-_monthly_sharpe0(x); dso=_monthly_sortino0(y)-_monthly_sortino0(x)
        ma=(y-x).mean()
        eras.append({'Era':nm,'Months':len(q),'MeanActiveMonthly':ma,'v345Wins_MeanActive':ma>0,
          'DeltaCAGR':dc,'v345Wins_CAGR':dc>0,
          'DeltaSharpe0_MONTHLY':ds,'v345Wins_Sharpe_MONTHLY':ds>0,
          'DeltaSortino0_MONTHLY':dso,'v345Wins_Sortino_MONTHLY':dso>0})
    eras=pd.DataFrame(eras)
    p.progress(34,text='R9b 3/11 — 13-block WFを比較中…')
    wf=_v355_wf_blocks(monthly.to_period('M'),'4F Promotion100','Frozen v3.45 Final',13)
    p.progress(46,text='R9b 4/11 — CPCV 28を比較中…')
    cpcv,groups=_v326_cpcv_summary(monthly.to_period('M'),'4F Promotion100',['Frozen v3.45 Final'])
    p.progress(57,text='R9b 5/11 — Rolling36Mを比較中…'); rolling=_r9_rolling36(monthly)
    p.progress(67,text='R9b 6/11 — best-month dependenceを監査中…')
    rem=[]; rank=active.sort_values(ascending=False)
    for k in [0,1,3,5,10]:
        q=monthly.drop(index=rank.head(k).index) if k else monthly
        x=q['4F Promotion100']; y=q['Frozen v3.45 Final']
        rem.append({'RemovedBest_v345_ActiveMonths':k,'Months':len(q),'MeanActiveMonthly':(y-x).mean(),
                    'DeltaCAGR':_annualized_return_monthly(y)-_annualized_return_monthly(x)})
    removal=pd.DataFrame(rem)
    p.progress(76,text='R9b 7/11 — State attributionを比較中…'); state_attr=_r9_state_compare(d,states)
    p.progress(84,text='R9b 8/11 — Stressを比較中…')
    stress=[]
    for nm,a,b in [('2015 selloff','2015-08-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),('COVID','2020-02-01','2020-04-30'),('2022 selloff','2022-01-01','2022-10-31'),('2025 selloff','2025-01-01','2025-06-30')]:
        row={'Window':nm}
        for c in ['4F Promotion100','Frozen v3.45 Final']:
            x=d.loc[a:b,c].dropna(); eq=(1+x).cumprod(); row[c+' Return']=(1+x).prod()-1; row[c+' MaxDD']=(eq/eq.cummax()-1).min()
        stress.append(row)
    stress=pd.DataFrame(stress)
    p.progress(91,text='R9b 9/11 — 年別activeを計算中…')
    yd=(pair['Frozen v3.45 Final']-pair['4F Promotion100']).groupby(pair.index.year).agg(['count','mean','sum']).reset_index(); yd.columns=['Year','Days','MeanDailyActive','SumDailyActive']
    p.progress(96,text='R9b 10/11 — implementation audit / ZIPを作成中…')
    consistency=pd.DataFrame([
      {'Check':'Headline CAGR delta equals full_metrics difference','Expected':float(mv['CAGR']-m4['CAGR']),'Reported':float(summary.iloc[0]['Headline_DeltaCAGR_v345_minus_4FPromo'])},
      {'Check':'Headline daily Sharpe delta equals full_metrics difference','Expected':float(mv['Sharpe0']-m4['Sharpe0']),'Reported':float(summary.iloc[0]['Headline_DeltaSharpe0_DAILY'])},
      {'Check':'Headline daily Sortino delta equals full_metrics difference','Expected':float(mv['Sortino0']-m4['Sortino0']),'Reported':float(summary.iloc[0]['Headline_DeltaSortino0_DAILY'])},
    ])
    consistency['AbsError']=(consistency['Expected']-consistency['Reported']).abs()
    consistency['PASS']=consistency['AbsError']<1e-12
    audit=pd.DataFrame([
      {'Item':'Purpose','Frozen value':'R9b aggregation/label consistency audit only; no strategy search','Changed':False},
      {'Item':'DEV cutoff','Frozen value':'2026-07-31','Changed':False},
      {'Item':'4F Promotion100','Frozen value':'Frozen4F + v3.45 frozen attack engine; TECL Turbo=>100% TECL','Changed':False},
      {'Item':'v3.45 Final','Frozen value':'Frozen v3.45 final rules','Changed':False},
      {'Item':'Attack parameters','Frozen value':'TLT3M>0; VIX30; XLK inflection; XLK6M>QQQ6M; Attack75; Promotion100','Changed':False},
      {'Item':'Optimization','Frozen value':'None; no threshold/lookback/weight/rescue sweep','Changed':False}])
    import io,zipfile
    buf=io.BytesIO()
    with zipfile.ZipFile(buf,'w',zipfile.ZIP_DEFLATED) as zf:
        outs=[('00_full_metrics.csv',metrics),('01_head_to_head_summary.csv',summary),('02_fixed_eras.csv',eras),('03_wf_13blocks.csv',wf),
              ('04_cpcv_28.csv',cpcv),('05_cpcv_groups.csv',groups),('06_rolling36.csv',rolling),('07_best_month_removal.csv',removal),
              ('08_state_attribution.csv',state_attr),('09_stress.csv',stress),('10_yearly_active.csv',yd),
              ('11_daily_pair.csv',pair.reset_index(names='Date')),('12_monthly_pair.csv',monthly.reset_index(names='Month')),
              ('13_states_daily.csv',states.reset_index(names='Date')),('14_implementation_audit.csv',audit),('15_consistency_audit.csv',consistency)]
        for fn,obj in outs: zf.writestr(fn,obj.to_csv(index=False))
        zf.writestr('README.txt','R9b Frozen v3.45 Final vs 4F Promotion100 Consistency Audit\nStrategy specification unchanged from R9. DEV cutoff=2026-07-31.\nHeadline Sharpe/Sortino are DAILY metrics from 00_full_metrics; robustness Sharpe/Sortino are MONTHLY metrics and are explicitly labeled.\nEra winner flags are metric-specific. No optimization.\nOfficial interpretation must use this user-run ZIP.\n')
    p.progress(100,text='R9b 完了 — consistency audit ZIP作成済み')
    st.success('R9b完了。consistency auditが全PASSであることを確認し、ZIPをこのチャットへアップロードしてください。')
    st.dataframe(metrics,use_container_width=True,hide_index=True); st.dataframe(summary,use_container_width=True,hide_index=True)
    st.subheader('Fixed eras'); st.dataframe(eras,use_container_width=True,hide_index=True)
    st.subheader('State attribution'); st.dataframe(state_attr,use_container_width=True,hide_index=True)
    st.subheader('Stress'); st.dataframe(stress,use_container_width=True,hide_index=True)
    st.subheader('Consistency audit'); st.dataframe(consistency,use_container_width=True,hide_index=True)
    st.download_button('📦 R9b Consistency Audit ZIP',data=buf.getvalue(),file_name='r9b_v345_vs_4f_promotion100_consistency_audit.zip',mime='application/zip',use_container_width=True,on_click='ignore',key='dl_r9b_champ')


# ================================================================
# R10 — v3.45 vs 4F Promotion100 Drawdown / Regime Anatomy
#
# PRE-REGISTERED PURPOSE:
#   Diagnose WHY the two already-frozen final strategies behave differently
#   in crash / inflationary / normal regimes. Attribution only; no strategy
#   search, no threshold/lookback/weight sweep, no rescue rule.
#
# Frozen competitors:
#   A) Frozen v3.45 Final
#   B) Frozen 4F + Attack75 + Promotion100
#
# Fixed anatomy views:
#   - Base family/sleeve contribution (MOM / MR / VIX / TEL-DM where present)
#   - Adaptive Safe Haven effect
#   - A Gate effect
#   - VIX30 Brake effect
#   - Turbo 75% TQQQ effect
#   - TECL/TQQQ selector effect
#   - Promotion100 effect
#   - Non-Turbo / Turbo-TQQQ / Turbo-TECL regime performance
#   - fixed historical stress windows + data-derived top drawdown cycles
#
# DEV cutoff = 2026-07-31. No OOS data may alter historical rules.
# ================================================================

def _r10_weighted_monthly_rebalance_contrib(daily_components, weights):
    """Exact daily contribution matrix for a monthly-rebalanced weighted basket."""
    cols=list(weights)
    x=daily_components[cols].dropna().copy()
    if x.empty:
        return pd.DataFrame(index=x.index,columns=cols,dtype=float),pd.DataFrame(index=x.index,columns=cols,dtype=float)
    w0=pd.Series(weights,dtype=float).reindex(cols)
    w0=w0/w0.sum()
    contrib=[]; whist=[]
    for _,g in x.groupby(x.index.to_period('M')):
        wealth=w0.copy()
        for dt,row in g.iterrows():
            w=wealth/wealth.sum()
            contrib.append(pd.Series((w*row).values,index=cols,name=dt))
            whist.append(pd.Series(w.values,index=cols,name=dt))
            wealth=wealth*(1.0+row)
    return pd.DataFrame(contrib).sort_index(),pd.DataFrame(whist).sort_index()


def _r10_v345_grouped_sleeve_contrib(holding_matrix, closes):
    sleeves=_returns_from_holding_matrix(holding_matrix,closes)
    out=pd.DataFrame(index=sleeves.index)
    out['MOM']=0.25*sleeves['QQQ-MOM']+0.25*sleeves['QLD-MOM']
    out['MR']=0.125*sleeves['Weekly MR 24M']+0.125*sleeves['Quarterly MR 24M']
    out['VIX']=0.0625*sleeves['Old VIX 15d']+0.0625*sleeves['Old VIX 20d']+0.125*sleeves['New VIX 20d']
    return out


def _r10_build(px_bt,rf_bt,start,end):
    cutoff=pd.Timestamp('2026-07-31')
    closes=px_bt.copy(); closes.index=pd.DatetimeIndex(closes.index)
    closes=closes.loc[:cutoff].sort_index().ffill()
    ret=closes.pct_change(fill_method=None)

    # Existing frozen builds are reused first.
    r6,f0,fab,states,h0,hab,_,_,_=_r6_build(px_bt,rf_bt,start,end)
    v345,states_v,adaptive_h,avix_h=_r8_v345_components(px_bt,rf_bt,start,end)
    idx=r6.index.intersection(v345.index).sort_values()
    states=states.reindex(idx).fillna(False)

    # ---------- 4F BASE FAMILY CONTRIBUTIONS ----------
    f0=f0.reindex(idx)
    c4,w4=_r10_weighted_monthly_rebalance_contrib(
        f0[['MOM','MR','VIX','TEL-DM']],{'MOM':0.25,'MR':0.25,'VIX':0.25,'TEL-DM':0.25})
    c4=c4.reindex(idx)

    # Core-before-Adaptive-Safe-Haven counterfactual for exact Safe Haven effect.
    core_h=_build_core_holding_matrix(closes,rf_bt).reindex(closes.index)
    core_sleeves=_returns_from_holding_matrix(core_h,closes)
    fcore=pd.DataFrame(index=core_sleeves.index)
    fcore['MOM']=0.5*core_sleeves['QQQ-MOM']+0.5*core_sleeves['QLD-MOM']
    fcore['MR']=0.5*core_sleeves['Weekly MR 24M']+0.5*core_sleeves['Quarterly MR 24M']
    fcore['VIX']=0.25*core_sleeves['Old VIX 15d']+0.25*core_sleeves['Old VIX 20d']+0.5*core_sleeves['New VIX 20d']
    fcore['TEL-DM']=f0['TEL-DM'].reindex(fcore.index)
    core4=_v390_monthly_rebalanced_ew(fcore[['MOM','MR','VIX','TEL-DM']].dropna()).rename('4F Core pre-SafeHaven')

    # Gate-only bridge: same frozen Gate A, no VIX brake.
    gate_a=states['A Gate'].astype(bool)
    hgate=h0.copy().reindex(closes.index)
    g1=gate_a.reindex(hgate.index).fillna(False) & hgate['QQQ-MOM'].eq('QQQ')
    g2=gate_a.reindex(hgate.index).fillna(False) & hgate['QLD-MOM'].eq('QLD')
    hgate.loc[g1,'QQQ-MOM']='QLD'; hgate.loc[g2,'QLD-MOM']='TQQQ'
    rgate=_returns_from_holding_matrix(hgate,closes).reindex(idx)
    fgate=f0.copy()
    fgate['MOM']=0.5*rgate['QQQ-MOM']+0.5*rgate['QLD-MOM']
    gate4=_v390_monthly_rebalanced_ew(fgate[['MOM','MR','VIX','TEL-DM']]).rename('4F GateOnly')

    layer4=pd.DataFrame(index=idx)
    layer4['Adaptive Safe Haven']=r6['Frozen 4F EW'].reindex(idx)-core4.reindex(idx)
    layer4['A Gate']=gate4.reindex(idx)-r6['Frozen 4F EW'].reindex(idx)
    layer4['VIX30 Brake']=r6['A+VIX30'].reindex(idx)-gate4.reindex(idx)
    layer4['Turbo 75% TQQQ']=r6['Turbo75 TQQQ'].reindex(idx)-r6['A+VIX30'].reindex(idx)
    layer4['Attack asset selector']=r6['Attack75 Selector'].reindex(idx)-r6['Turbo75 TQQQ'].reindex(idx)
    layer4['Promotion100']=r6['Promotion100'].reindex(idx)-r6['Attack75 Selector'].reindex(idx)

    # ---------- v3.45 BASE SLEEVE CONTRIBUTIONS ----------
    cv=_r10_v345_grouped_sleeve_contrib(adaptive_h,closes).reindex(idx)
    corev=_portfolio_return_from_holdings_fast(core_h,ret).reindex(idx).rename('v345 Core pre-SafeHaven')
    adaptive=v345['v345 Adaptive Base'].reindex(idx)

    # Gate-only bridge for v3.45.
    vg_h=_v326_apply_l2_gate(adaptive_h,gate_a.reindex(adaptive_h.index).ffill().fillna(False).astype(bool))
    vg_ret=_portfolio_return_from_holdings_fast(vg_h,ret).reindex(idx).rename('v345 GateOnly')
    avix=v345['v345 A+VIX30'].reindex(idx)
    turbo=states['Turbo'].reindex(idx).fillna(False).astype(bool)
    choose=states['Choose TECL'].reindex(idx).fillna(False).astype(bool)
    t1_h=_v332_apply_turbo_l3(avix_h,turbo.reindex(avix_h.index).fillna(False).astype(bool))
    t1_ret=_portfolio_return_from_holdings_fast(t1_h,ret).reindex(idx)
    t2v,attackv=_v335_build_t2_and_attack_returns(avix,t1_ret,ret['TQQQ'],ret['TECL'],turbo,choose)
    t2v=t2v.reindex(idx).rename('v345 Turbo75 TQQQ')
    attackv=attackv.reindex(idx).rename('v345 Attack75')
    finalv=v345['Frozen v3.45 Final'].reindex(idx)

    layerv=pd.DataFrame(index=idx)
    layerv['Adaptive Safe Haven']=adaptive-corev
    layerv['A Gate']=vg_ret-adaptive
    layerv['VIX30 Brake']=avix-vg_ret
    layerv['Turbo 75% TQQQ']=t2v-avix
    layerv['Attack asset selector']=attackv-t2v
    layerv['Promotion100']=finalv-attackv

    finals=pd.DataFrame({
        '4F Promotion100':r6['Promotion100'].reindex(idx),
        'Frozen v3.45 Final':finalv,
        '4F Base':r6['Frozen 4F EW'].reindex(idx),
        'v345 Adaptive Base':adaptive,
    }).dropna()
    idx=finals.index
    return {
        'closes':closes.reindex(idx),'finals':finals,'states':states.reindex(idx),
        'fourf_family_contrib':c4.reindex(idx),'fourf_family_weights':w4.reindex(idx),
        'v345_family_contrib':cv.reindex(idx),'fourf_layers':layer4.reindex(idx),
        'v345_layers':layerv.reindex(idx),'fourf_core':core4.reindex(idx),
        'fourf_gate':gate4.reindex(idx),'v345_core':corev.reindex(idx),'v345_gate':vg_ret.reindex(idx),
        'v345_t2':t2v.reindex(idx),'v345_attack75':attackv.reindex(idx),
    }


def _r10_drawdown_cycles(series,top_n=5):
    x=series.dropna().copy()
    if x.empty: return pd.DataFrame()
    eq=(1+x).cumprod(); peak=eq.cummax(); dd=eq/peak-1
    rows=[]; in_dd=False; peak_date=None; trough_date=None; trough_dd=0.0
    prev_peak_date=x.index[0]
    for dt in x.index:
        if dd.loc[dt] >= -1e-12:
            if in_dd:
                rows.append({'PeakDate':peak_date,'TroughDate':trough_date,'RecoveryDate':dt,'MaxDD':trough_dd,'Recovered':True})
                in_dd=False
            prev_peak_date=dt
        else:
            if not in_dd:
                in_dd=True; peak_date=prev_peak_date; trough_date=dt; trough_dd=float(dd.loc[dt])
            if float(dd.loc[dt])<trough_dd:
                trough_dd=float(dd.loc[dt]); trough_date=dt
    if in_dd:
        rows.append({'PeakDate':peak_date,'TroughDate':trough_date,'RecoveryDate':pd.NaT,'MaxDD':trough_dd,'Recovered':False})
    z=pd.DataFrame(rows)
    if z.empty: return z
    z=z.sort_values('MaxDD').head(top_n).reset_index(drop=True)
    z.insert(0,'Rank',range(1,len(z)+1))
    return z


def _r10_episode_windows(finals):
    rows=[]
    fixed=[
      ('2015 selloff','2015-08-01','2015-09-30'),('2018 Q4','2018-10-01','2018-12-31'),
      ('COVID','2020-02-01','2020-04-30'),('2022 selloff','2022-01-01','2022-10-31'),
      ('2025 selloff','2025-01-01','2025-06-30')]
    for nm,a,b in fixed: rows.append({'EpisodeType':'Fixed stress','Strategy':'Both','Episode':nm,'Start':pd.Timestamp(a),'End':pd.Timestamp(b)})
    dd_tables=[]
    for strat in ['4F Promotion100','Frozen v3.45 Final']:
        dd=_r10_drawdown_cycles(finals[strat],5)
        if len(dd):
            dd=dd.assign(Strategy=strat)
            dd_tables.append(dd)
            for _,r in dd.iterrows():
                rows.append({'EpisodeType':'Top drawdown','Strategy':strat,'Episode':f"{strat} DD#{int(r['Rank'])}",
                             'Start':pd.Timestamp(r['PeakDate']),'End':pd.Timestamp(r['TroughDate'])})
    return pd.DataFrame(rows), (pd.concat(dd_tables,ignore_index=True) if dd_tables else pd.DataFrame())


def _r10_episode_strategy_stats(finals,episodes):
    rows=[]
    for _,e in episodes.iterrows():
        for strat in ['4F Promotion100','Frozen v3.45 Final']:
            x=finals.loc[e['Start']:e['End'],strat].dropna()
            if x.empty: continue
            eq=(1+x).cumprod()
            rows.append({'EpisodeType':e['EpisodeType'],'Episode':e['Episode'],'WindowOwner':e['Strategy'],
                         'Start':e['Start'],'End':e['End'],'Strategy':strat,'Days':len(x),
                         'Return':float((1+x).prod()-1),'MaxDD':float((eq/eq.cummax()-1).min()),
                         'MeanDaily':float(x.mean()),'PositiveDayShare':float((x>0).mean())})
    return pd.DataFrame(rows)


def _r10_episode_component_summary(episodes,c4,cv,l4,lv):
    rows=[]
    sets=[('4F Promotion100','Base family',c4),('Frozen v3.45 Final','Base family',cv),
          ('4F Promotion100','Layer effect',l4),('Frozen v3.45 Final','Layer effect',lv)]
    for _,e in episodes.iterrows():
        for strat,view,df in sets:
            q=df.loc[e['Start']:e['End']]
            for comp in q.columns:
                x=q[comp].dropna()
                if x.empty: continue
                rows.append({'EpisodeType':e['EpisodeType'],'Episode':e['Episode'],'WindowOwner':e['Strategy'],
                             'Start':e['Start'],'End':e['End'],'Strategy':strat,'View':view,'Component':comp,
                             'Days':len(x),'ArithmeticSum':float(x.sum()),'MeanDailyContribution':float(x.mean()),
                             'PositiveContributionShare':float((x>0).mean()),'NegativeContributionShare':float((x<0).mean())})
    return pd.DataFrame(rows)


def _r10_regime_summary(finals,states):
    idx=finals.index
    turbo=states['Turbo'].reindex(idx).fillna(False).astype(bool)
    tecl=states['Choose TECL'].reindex(idx).fillna(False).astype(bool)
    regime=pd.Series('Turbo TQQQ',index=idx,dtype=object)
    regime.loc[~turbo]='Non-Turbo'
    regime.loc[turbo & tecl]='Turbo TECL / Promotion100'
    rows=[]
    for rg in ['All','Non-Turbo','Turbo TQQQ','Turbo TECL / Promotion100']:
        mask=pd.Series(True,index=idx) if rg=='All' else regime.eq(rg)
        for strat in ['4F Promotion100','Frozen v3.45 Final']:
            x=finals.loc[mask,strat].dropna()
            if x.empty: continue
            rows.append({'Regime':rg,'Strategy':strat,'Days':len(x),'ShareDays':len(x)/len(idx),
                         'MeanDaily':float(x.mean()),'AnnArithmeticApprox':float(x.mean()*252),
                         'VolAnn':float(x.std(ddof=1)*np.sqrt(252)) if len(x)>1 else np.nan,
                         'PositiveDayShare':float((x>0).mean()),'CompoundedObservedDays':float((1+x).prod()-1)})
    return pd.DataFrame(rows),pd.DataFrame({'Regime':regime},index=idx)


def _r10_exactness_audit(b):
    f=b['finals']; c4=b['fourf_family_contrib']; cv=b['v345_family_contrib']; l4=b['fourf_layers']; lv=b['v345_layers']
    core4=b['fourf_core']; corev=b['v345_core']
    recon4=core4 + l4.sum(axis=1)
    reconv=corev + lv.sum(axis=1)
    checks=[
      ('4F base family contributions sum to Frozen 4F Base',float((c4.sum(axis=1)-f['4F Base']).abs().max())),
      ('v3.45 adaptive family contributions sum to Adaptive Base',float((cv.sum(axis=1)-f['v345 Adaptive Base']).abs().max())),
      ('4F layer bridge reconstructs Promotion100',float((recon4-f['4F Promotion100']).abs().max())),
      ('v3.45 layer bridge reconstructs Final',float((reconv-f['Frozen v3.45 Final']).abs().max())),
      ('Promotion100 rows identical across architectures',float((f.loc[b['states']['Promotion100'].reindex(f.index).fillna(False).astype(bool),'Frozen v3.45 Final']-f.loc[b['states']['Promotion100'].reindex(f.index).fillna(False).astype(bool),'4F Promotion100']).abs().max())),
    ]
    out=pd.DataFrame(checks,columns=['Check','MaxAbsError'])
    out['Tolerance']=1e-10; out['PASS']=out['MaxAbsError'].fillna(0)<=out['Tolerance']
    return out


