def _fgmap_r3_gods():
    out={}
    for name, rows in _FOURGODS_R3_ROWS.items():
        q=pd.DataFrame(rows,columns=["Date","Position","Return"])
        q["Date"]=pd.to_datetime(q["Date"])
        out[name]=q.set_index("Date").sort_index()
    return out

def _fgmap_r3_families(px_bt,rf_bt,bt_start,bt_end,cutoff):
    _, famd=_v390_build(px_bt,rf_bt,bt_start,bt_end)
    famd=famd.loc[:cutoff].copy()
    fam=_fofs1_monthly_from_daily(famd[["MOM","MR","VIX","TEL-DM"]]).dropna()
    fam.index=pd.to_datetime(fam.index)+pd.offsets.MonthEnd(0)
    fam=fam[~fam.index.duplicated(keep="last")].sort_index()
    return fam.loc[:cutoff]

def _fgmap_r3_spy(px_bt,start,end,cutoff):
    if "SPY" not in px_bt.columns:
        return pd.Series(dtype=float,name="SPY")
    s=px_bt["SPY"].loc[start:end].dropna()
    if not len(s):
        return pd.Series(dtype=float,name="SPY")
    m=s.resample("ME").last().pct_change().dropna()
    m.index=pd.to_datetime(m.index)+pd.offsets.MonthEnd(0)
    return m[~m.index.duplicated(keep="last")].sort_index().loc[:cutoff].rename("SPY")

def _fgmap_r3_pair_stats(god,fam):
    z=pd.concat([god.rename("G"),fam.rename("F")],axis=1).dropna()
    if len(z)<12:
        return {"Months":len(z),"Pearson":np.nan,"Spearman":np.nan,
                 "AlphaMonthly":np.nan,"Beta":np.nan,"R2":np.nan}
    x=z["F"].to_numpy(float); y=z["G"].to_numpy(float)
    X=np.column_stack([np.ones(len(x)),x])
    coef=np.linalg.lstsq(X,y,rcond=None)[0]; fit=X@coef
    sst=float(np.sum((y-y.mean())**2)); ssr=float(np.sum((y-fit)**2))
    return {
        "Months":len(z),
        "Pearson":float(z["G"].corr(z["F"],method="pearson")),
        "Spearman":float(z["G"].corr(z["F"],method="spearman")),
        "AlphaMonthly":float(coef[0]),"Beta":float(coef[1]),
        "R2":float(1-ssr/sst) if sst>0 else np.nan
    }

def _fgmap_r3_pair_table(gods,fam):
    rows=[]
    for g,gdf in gods.items():
        for f in ["MOM","MR","VIX","TEL-DM"]:
            rows.append({"God":g,"Family":f,**_fgmap_r3_pair_stats(gdf["Return"],fam[f])})
    q=pd.DataFrame(rows)
    for m in ["Pearson","Spearman","R2"]:
        q[m+"Rank"]=q.groupby("God")[m].rank(method="min",ascending=False)
    return q.sort_values(["God","PearsonRank","Family"])

def _fgmap_r3_fixed_eras(gods,fam):
    eras=[
        ("2012-2015","2012-01-01","2015-12-31"),
        ("2016-2019","2016-01-01","2019-12-31"),
        ("2020-2022","2020-01-01","2022-12-31"),
        ("2023-DEV","2023-01-01","2026-07-31"),
    ]
    rows=[]
    for g,gdf in gods.items():
        for en,a,b in eras:
            vals=[]
            for f in ["MOM","MR","VIX","TEL-DM"]:
                z=pd.concat([gdf["Return"].rename("G"),fam[f].rename("F")],axis=1).loc[a:b].dropna()
                c=float(z["G"].corr(z["F"])) if len(z)>=6 else np.nan
                vals.append((f,c,len(z)))
            valid=[x for x in vals if np.isfinite(x[1])]
            top=max(valid,key=lambda x:x[1])[0] if valid else None
            for f,c,n in vals:
                rows.append({"God":g,"Era":en,"Family":f,"Months":n,"Pearson":c,
                             "TopFamily":top,"IsTop":bool(f==top)})
    return pd.DataFrame(rows)

def _fgmap_r3_rolling36(gods,fam):
    rows=[]
    for g,gdf in gods.items():
        z=pd.concat([gdf["Return"].rename("God"),fam],axis=1).dropna()
        for i in range(35,len(z)):
            w=z.iloc[i-35:i+1]
            cs={f:float(w["God"].corr(w[f])) for f in ["MOM","MR","VIX","TEL-DM"]}
            top=max(cs,key=cs.get)
            row={"God":g,"End":w.index[-1],"TopFamily":top}
            row.update({f+"_Corr":v for f,v in cs.items()})
            rows.append(row)
    return pd.DataFrame(rows)

def _fgmap_r3_loo(gods,fam):
    rows=[]
    for g,gdf in gods.items():
        z=pd.concat([gdf["Return"].rename("God"),fam],axis=1).dropna()
        for y in sorted(z.index.year.unique()):
            q=z[z.index.year!=y]
            cs={f:float(q["God"].corr(q[f])) for f in ["MOM","MR","VIX","TEL-DM"]}
            top=max(cs,key=cs.get)
            rows.append({"God":g,"LeftOutYear":int(y),"Months":len(q),"TopFamily":top,
                         **{f+"_Corr":v for f,v in cs.items()}})
    return pd.DataFrame(rows)

def _fgmap_r3_beta(y,x):
    z=pd.concat([y.rename("Y"),x.rename("X")],axis=1).dropna()
    if len(z)<6 or float(z["X"].var())<=0: return np.nan
    return float(np.cov(z["Y"],z["X"],ddof=1)[0,1]/np.var(z["X"],ddof=1))

def _fgmap_r3_fingerprint(gods,fam,spy):
    series={f:fam[f] for f in ["MOM","MR","VIX","TEL-DM"]}
    series.update({g:gods[g]["Return"] for g in gods})
    rows=[]
    for name,s in series.items():
        z=pd.concat([s.rename("R"),spy.rename("SPY")],axis=1).dropna()
        if not len(z): continue
        q10=z["SPY"].quantile(.10); q90=z["SPY"].quantile(.90)
        up=z[z["SPY"]>0]; dn=z[z["SPY"]<0]
        rows.append({
            "Strategy":name,"Months":len(z),
            "AnnVol":float(z["R"].std(ddof=1)*np.sqrt(12)),
            "SPY_Corr":float(z["R"].corr(z["SPY"])),
            "SPY_Beta":_fgmap_r3_beta(z["R"],z["SPY"]),
            "UpBeta":_fgmap_r3_beta(up["R"],up["SPY"]),
            "DownBeta":_fgmap_r3_beta(dn["R"],dn["SPY"]),
            "WorstSPYDecileMean":float(z.loc[z["SPY"]<=q10,"R"].mean()),
            "BestSPYDecileMean":float(z.loc[z["SPY"]>=q90,"R"].mean()),
            "MeanMonthly":float(z["R"].mean()),
        })
    fp=pd.DataFrame(rows).set_index("Strategy")
    feats=["AnnVol","SPY_Corr","SPY_Beta","UpBeta","DownBeta",
           "WorstSPYDecileMean","BestSPYDecileMean","MeanMonthly"]
    zz=(fp[feats]-fp[feats].mean())/fp[feats].std(ddof=0).replace(0,np.nan)
    ds=[]
    for g in gods:
        for f in ["MOM","MR","VIX","TEL-DM"]:
            ds.append({"God":g,"Family":f,
                       "FingerprintDistance":float(np.sqrt(np.nanmean((zz.loc[g]-zz.loc[f])**2)))})
    dd=pd.DataFrame(ds)
    dd["DistanceRank"]=dd.groupby("God")["FingerprintDistance"].rank(method="min")
    return fp.reset_index(),dd.sort_values(["God","DistanceRank","Family"])

def _fgmap_r3_state(gods,fam):
    rows=[]
    for g,gdf in gods.items():
        q=pd.concat([gdf[["Position","Return"]],fam],axis=1).dropna()
        q["State"]=np.where(q["Position"].isin(["TQQQ","TECL"]),"Attack","Base/Defense")
        for state,x in q.groupby("State"):
            row={"God":g,"State":state,"Months":len(x),"GodMean":float(x["Return"].mean())}
            for f in ["MOM","MR","VIX","TEL-DM"]:
                row[f+"_Mean"]=float(x[f].mean())
                row[f+"_CorrWithGod"]=float(x["Return"].corr(x[f])) if len(x)>=6 else np.nan
            rows.append(row)
    return pd.DataFrame(rows)


# ================================================================
# Four Gods × My Families Role Mapping R1
#
# User-supplied source lineage (fixed prior knowledge):
#   Shin Seiryu <- DM2
#   Shin Suzaku <- DM3
#   Shin Byakko <- DM6
#   Shin Genbu  <- DM7
#
# Current one-shot hypotheses, fixed BEFORE this audit:
#   H1: Shin Seiryu-Gekiko is closest to user's MOM family.
#   H2: Shin Byakko-Gekiko is closest to user's VIX family.
#
# Primary similarity:
#   Pearson correlation of contemporaneous completed monthly returns.
# Secondary:
#   Spearman correlation, simple OLS R^2, 4 fixed eras,
#   rolling-36m top-family share, leave-one-year-out mapping,
#   and role-fingerprint distance versus SPY.
#
# No family construction changes, no lag search, no weight search,
# no alternate horizon, no threshold/rescue rule.
# DEV cutoff = 2026-07-31.
