def _fgmap_r1_gods():
    out={}
    for name, rows in _FOURGODS_R1_ROWS.items():
        q=pd.DataFrame(rows,columns=["Date","Position","Return"])
        q["Date"]=pd.to_datetime(q["Date"])
        q=q.set_index("Date").sort_index()
        out[name]=q
    return out

def _fgmap_r1_families(px_bt,rf_bt,bt_start,bt_end,cutoff):
    _, famd=_v390_build(px_bt,rf_bt,bt_start,bt_end)
    famd=famd.loc[:cutoff].copy()
    fam=_fofs1_monthly_from_daily(famd[["MOM","MR","VIX","TEL-DM"]]).dropna()
    fam.index=pd.to_datetime(fam.index)+pd.offsets.MonthEnd(0)
    fam=fam[~fam.index.duplicated(keep="last")].sort_index()
    return fam.loc[:cutoff]

def _fgmap_r1_spy_monthly(px_bt, start, end, cutoff):
    if "SPY" not in px_bt.columns:
        return pd.Series(dtype=float,name="SPY")
    s=px_bt["SPY"].loc[start:end].dropna()
    if not len(s):
        return pd.Series(dtype=float,name="SPY")
    m=s.resample("ME").last().pct_change().dropna()
    m.index=pd.to_datetime(m.index)+pd.offsets.MonthEnd(0)
    m=m[~m.index.duplicated(keep="last")]
    return m.loc[:cutoff].rename("SPY")

def _fgmap_r1_pair_stats(god, fam):
    z=pd.concat([god.rename("G"),fam.rename("F")],axis=1).dropna()
    if len(z)<12:
        return {"Months":len(z),"Pearson":np.nan,"Spearman":np.nan,
                "AlphaMonthly":np.nan,"Beta":np.nan,"R2":np.nan}
    x=z["F"].to_numpy(float); y=z["G"].to_numpy(float)
    pear=float(z["G"].corr(z["F"],method="pearson"))
    spear=float(z["G"].corr(z["F"],method="spearman"))
    X=np.column_stack([np.ones(len(x)),x])
    coef=np.linalg.lstsq(X,y,rcond=None)[0]
    fit=X@coef
    ssr=float(np.sum((y-fit)**2)); sst=float(np.sum((y-y.mean())**2))
    r2=1.0-ssr/sst if sst>0 else np.nan
    return {"Months":len(z),"Pearson":pear,"Spearman":spear,
            "AlphaMonthly":float(coef[0]),"Beta":float(coef[1]),"R2":float(r2)}

def _fgmap_r1_pair_table(gods,fam):
    rows=[]
    for gname,gdf in gods.items():
        for f in ["MOM","MR","VIX","TEL-DM"]:
            r=_fgmap_r1_pair_stats(gdf["Return"],fam[f])
            rows.append({"God":gname,"Family":f,**r})
    q=pd.DataFrame(rows)
    q["PearsonRank"]=q.groupby("God")["Pearson"].rank(method="min",ascending=False)
    q["SpearmanRank"]=q.groupby("God")["Spearman"].rank(method="min",ascending=False)
    q["R2Rank"]=q.groupby("God")["R2"].rank(method="min",ascending=False)
    return q.sort_values(["God","PearsonRank","Family"])

def _fgmap_r1_fixed_eras(gods,fam):
    eras=[
        ("2012-2015","2012-01-01","2015-12-31"),
        ("2016-2019","2016-01-01","2019-12-31"),
        ("2020-2022","2020-01-01","2022-12-31"),
        ("2023-DEV","2023-01-01","2026-07-31"),
    ]
    rows=[]
    for gname,gdf in gods.items():
        for en,a,b in eras:
            vals=[]
            for f in ["MOM","MR","VIX","TEL-DM"]:
                z=pd.concat([gdf["Return"].rename("G"),fam[f].rename("F")],axis=1).loc[a:b].dropna()
                corr=float(z["G"].corr(z["F"])) if len(z)>=6 else np.nan
                vals.append((f,corr,len(z)))
            valid=[x for x in vals if np.isfinite(x[1])]
            top=max(valid,key=lambda x:x[1])[0] if valid else None
            for f,c,n in vals:
                rows.append({"God":gname,"Era":en,"Family":f,"Months":n,
                             "Pearson":c,"TopFamily":top,"IsTop":bool(f==top)})
    return pd.DataFrame(rows)

def _fgmap_r1_rolling36(gods,fam):
    rows=[]
    for gname,gdf in gods.items():
        z=pd.concat([gdf["Return"].rename("God"),fam],axis=1).dropna()
        if len(z)<36:
            continue
        for i in range(35,len(z)):
            w=z.iloc[i-35:i+1]
            cs={f:float(w["God"].corr(w[f])) for f in ["MOM","MR","VIX","TEL-DM"]}
            top=max(cs,key=cs.get)
            row={"God":gname,"End":w.index[-1],"TopFamily":top}
            row.update({f+"_Corr":v for f,v in cs.items()})
            rows.append(row)
    return pd.DataFrame(rows)

def _fgmap_r1_loo_year(gods,fam):
    rows=[]
    for gname,gdf in gods.items():
        z=pd.concat([gdf["Return"].rename("God"),fam],axis=1).dropna()
        for y in sorted(z.index.year.unique()):
            q=z[z.index.year!=y]
            cs={f:float(q["God"].corr(q[f])) for f in ["MOM","MR","VIX","TEL-DM"]}
            top=max(cs,key=cs.get)
            rows.append({"God":gname,"LeftOutYear":int(y),"Months":len(q),
                         "TopFamily":top,**{f+"_Corr":v for f,v in cs.items()}})
    return pd.DataFrame(rows)

def _fgmap_r1_beta(y,x):
    z=pd.concat([y.rename("Y"),x.rename("X")],axis=1).dropna()
    if len(z)<6 or float(z["X"].var())<=0:
        return np.nan
    return float(np.cov(z["Y"],z["X"],ddof=1)[0,1]/np.var(z["X"],ddof=1))

def _fgmap_r1_fingerprint(gods,fam,spy):
    series={f:fam[f] for f in ["MOM","MR","VIX","TEL-DM"]}
    series.update({g:gods[g]["Return"] for g in gods})
    rows=[]
    for name,s in series.items():
        z=pd.concat([s.rename("R"),spy.rename("SPY")],axis=1).dropna()
        if not len(z): continue
        q10=z["SPY"].quantile(.10); q90=z["SPY"].quantile(.90)
        up=z[z["SPY"]>0]; dn=z[z["SPY"]<0]
        rows.append({
            "Strategy":name,"Months":len(z),
            "AnnVol":float(z["R"].std(ddof=1)*np.sqrt(12)),
            "SPY_Corr":float(z["R"].corr(z["SPY"])),
            "SPY_Beta":_fgmap_r1_beta(z["R"],z["SPY"]),
            "UpBeta":_fgmap_r1_beta(up["R"],up["SPY"]),
            "DownBeta":_fgmap_r1_beta(dn["R"],dn["SPY"]),
            "WorstSPYDecileMean":float(z.loc[z["SPY"]<=q10,"R"].mean()),
            "BestSPYDecileMean":float(z.loc[z["SPY"]>=q90,"R"].mean()),
            "MeanMonthly":float(z["R"].mean()),
        })
    fp=pd.DataFrame(rows).set_index("Strategy")
    feats=["AnnVol","SPY_Corr","SPY_Beta","UpBeta","DownBeta",
           "WorstSPYDecileMean","BestSPYDecileMean","MeanMonthly"]
    zz=(fp[feats]-fp[feats].mean())/fp[feats].std(ddof=0).replace(0,np.nan)
    dist=[]
    for g in gods:
        if g not in zz.index: continue
        for f in ["MOM","MR","VIX","TEL-DM"]:
            d=float(np.sqrt(np.nanmean((zz.loc[g]-zz.loc[f])**2)))
            dist.append({"God":g,"Family":f,"FingerprintDistance":d})
    dd=pd.DataFrame(dist)
    dd["DistanceRank"]=dd.groupby("God")["FingerprintDistance"].rank(method="min")
    return fp.reset_index(),dd.sort_values(["God","DistanceRank"])

def _fgmap_r1_state_mechanism(gods,fam):
    rows=[]
    for gname,gdf in gods.items():
        defense_asset="XLU" if "Seiryu" in gname else "GLD"
        q=pd.concat([gdf[["Position","Return"]],fam],axis=1).dropna()
        q["State"]=np.where(q["Position"].eq(defense_asset),"Defense","Attack")
        for state,x in q.groupby("State"):
            row={"God":gname,"State":state,"Months":len(x),
                 "GodMean":float(x["Return"].mean())}
            for f in ["MOM","MR","VIX","TEL-DM"]:
                row[f+"_Mean"]=float(x[f].mean())
                row[f+"_CorrWithGod"]=float(x["Return"].corr(x[f])) if len(x)>=6 else np.nan
            rows.append(row)
    return pd.DataFrame(rows)


# ================================================================
# FoF B6 — Fixed VIX Tilt Falsification
#
# Post-hoc candidate discovered in B3:
#   VIX 50% + TEL-DM 25% + MR 25% + MOM 0%
#
# IMPORTANT:
#   This candidate was NOT pre-registered before B3 and therefore cannot
#   earn "clean historical discovery" status from the same DEV sample.
#   B6 is a falsification / robustness audit only.
#
# Frozen control:
#   MOM 25% + VIX 25% + TEL-DM 25% + MR 25%
#
# Exact active identity:
#   Candidate - Control = 25% * (VIX - MOM)
#
# No weight search, no selector, no rescue rule.
# DEV cutoff = 2026-07-31.
# ================================================================

def _fofb6_build(px_bt, rf_bt, bt_start, bt_end, cutoff):
    d = _fofb1_monthly_dataset(px_bt, rf_bt, bt_start, bt_end, cutoff)
    fam = ["MOM","MR","VIX","TEL-DM"]

    w_ctrl = pd.DataFrame(0.25, index=d.index, columns=fam)

    w_vix = pd.DataFrame(0.0, index=d.index, columns=fam)
    w_vix["VIX"] = 0.50
    w_vix["TEL-DM"] = 0.25
    w_vix["MR"] = 0.25

    realized_fam = d[fam].shift(-1)

    z = pd.DataFrame(index=d.index)
    z["Control4F_EW"] = (w_ctrl * realized_fam).sum(axis=1, min_count=1)
    z["FixedVIXTilt"] = (w_vix * realized_fam).sum(axis=1, min_count=1)
    z["Active"] = z["FixedVIXTilt"] - z["Control4F_EW"]
    z["VIX_minus_MOM"] = realized_fam["VIX"] - realized_fam["MOM"]
    z["IdentityResidual"] = z["Active"] - 0.25 * z["VIX_minus_MOM"]
    for f in fam:
        z[f+"_ret"] = realized_fam[f]

    z = z.iloc[:-1].dropna()
    return z, w_ctrl.reindex(z.index), w_vix.reindex(z.index), realized_fam.reindex(z.index), d

def _fofb6_perf(z):
    rows=[]
    for label,col in [("Frozen 4F EW","Control4F_EW"),("Fixed VIX Tilt","FixedVIXTilt")]:
        rows.append({"Strategy":label, **_fofs1_monthly_perf(z[col])})
    q=z["Active"]
    sd=float(q.std(ddof=1))
    rows.append({
        "Strategy":"Active: Fixed VIX Tilt - Control",
        "Months":len(q),"CAGR":np.nan,
        "Vol":float(sd*np.sqrt(12)),"MaxDD":np.nan,
        "Sharpe":float(q.mean()/sd*np.sqrt(12)) if sd>0 else np.nan,
        "Sortino":np.nan,"Calmar":np.nan,
        "MeanMonthly":float(q.mean()),"MedianMonthly":float(q.median()),
        "PositiveRate":float((q>0).mean()),
    })
    return pd.DataFrame(rows)

def _fofb6_era(z):
    eras=[("2012-2015","2012-01-01","2015-12-31"),
          ("2016-2019","2016-01-01","2019-12-31"),
          ("2020-2022","2020-01-01","2022-12-31"),
          ("2023-DEV","2023-01-01","2026-07-31")]
    rows=[]
    for e,a,b in eras:
        q=z.loc[a:b]
        if not len(q): continue
        pc=_fofs1_monthly_perf(q["Control4F_EW"])
        pv=_fofs1_monthly_perf(q["FixedVIXTilt"])
        rows.append({
            "Era":e,"Months":len(q),
            "Control_CAGR":pc.get("CAGR"),"VIXTilt_CAGR":pv.get("CAGR"),
            "DeltaCAGR":pv.get("CAGR")-pc.get("CAGR"),
            "Control_MaxDD":pc.get("MaxDD"),"VIXTilt_MaxDD":pv.get("MaxDD"),
            "Control_Sharpe":pc.get("Sharpe"),"VIXTilt_Sharpe":pv.get("Sharpe"),
            "MeanActive":float(q["Active"].mean()),
            "PositiveActiveRate":float((q["Active"]>0).mean()),
            "Mean_VIXminusMOM":float(q["VIX_minus_MOM"].mean()),
        })
    return pd.DataFrame(rows)

def _fofb6_wf13(z):
    rows=[]
