def _fofb6_rolling36(z):
    a=z["Active"]
    r=pd.DataFrame(index=z.index)
    r["Rolling36_MeanActive"]=a.rolling(36,min_periods=36).mean()
    r["Rolling36_Positive"]=r["Rolling36_MeanActive"]>0
    r["Rolling36_AnnualizedIR"]=(
        a.rolling(36,min_periods=36).mean() /
        a.rolling(36,min_periods=36).std(ddof=1) * np.sqrt(12)
    )
    return r.dropna().reset_index()

def _fofb6_stress(z):
    windows=[
        ("2015 selloff","2015-08-01","2015-09-30"),
        ("2018 Q4","2018-10-01","2018-12-31"),
        ("2019-05","2019-05-01","2019-05-31"),
        ("COVID","2020-02-01","2020-04-30"),
        ("2022 selloff","2022-01-01","2022-10-31"),
        ("2025 selloff","2025-01-01","2025-06-30"),
    ]
    rows=[]
    for n,a,b in windows:
        q=z.loc[a:b]
        if not len(q): continue
        rows.append({
            "Window":n,"Months":len(q),
            "Control":float(np.prod(1+q["Control4F_EW"])-1),
            "FixedVIXTilt":float(np.prod(1+q["FixedVIXTilt"])-1),
            "ActiveGeometric":float(np.prod(1+q["FixedVIXTilt"])/np.prod(1+q["Control4F_EW"])-1),
            "Mean_VIXminusMOM":float(q["VIX_minus_MOM"].mean()),
        })
    return pd.DataFrame(rows)

def _fofb6_drift_turnover(target_w, realized_fam):
    rows=[]
    prev_post=None
    for dt in target_w.index:
        tgt=target_w.loc[dt].astype(float)
        turn=0.0 if prev_post is None else float((tgt-prev_post).abs().sum()/2.0)
        gross=1.0+realized_fam.loc[dt].astype(float)
        denom=float((tgt*gross).sum())
        post=(tgt*gross/denom) if denom>0 else tgt.copy()
        rows.append((dt,turn))
        prev_post=post
    return pd.Series(dict(rows)).sort_index()

def _fofb6_cost(z,w_ctrl,w_vix,realized_fam):
    rows=[]
    for label,col,w in [
        ("Frozen 4F EW","Control4F_EW",w_ctrl),
        ("Fixed VIX Tilt","FixedVIXTilt",w_vix),
    ]:
        turn=_fofb6_drift_turnover(w,realized_fam)
        for bps in [0,10,25,50]:
            net=z[col]-(bps/10000.0)*turn.reindex(z.index).fillna(0)
            rows.append({
                "Strategy":label,"Cost_bps_per_oneway":bps,
                "AnnualizedOneWayTurnover":float(turn.mean()*12),
                **_fofs1_monthly_perf(net)
            })
    return pd.DataFrame(rows)

def _fofb6_identity(z):
    return pd.DataFrame([{
        "MaxAbsIdentityResidual":float(z["IdentityResidual"].abs().max()),
        "MeanIdentityResidual":float(z["IdentityResidual"].mean()),
        "Identity":"Active = 0.25 * (VIX - MOM)",
        "Interpretation":"The candidate is exactly a permanent +25% VIX / -25% MOM active bet."
    }])


# ================================================================
# FoF B5 — Acceleration Spear Selector Audit
#
# Hypothesis inspired by Bam's "Acceleration":
#   choose the spear whose momentum is accelerating more strongly.
#
# Pre-registered definition:
#   Acceleration_f(t) = Price12M_f(t) - Price12M_f(t-1)
#   for f in {MOM, VIX}
#
# Role architecture remains frozen:
#   MR 25% fixed
#   TEL-DM 25% fixed
#   Spear block = 50%
#
# Strategies compared:
#   Control Spear EW  = MOM25 / VIX25 / TEL25 / MR25
#   Price12M winner   = MOM50 or VIX50 based on Price12M level
#   Prior11M winner   = MOM50 or VIX50 based on frozen Prior11M
#   Acceleration      = MOM50 or VIX50 based on ΔPrice12M
#
# No threshold / lookback / weight tuning.
# DEV cutoff = 2026-07-31.
# ================================================================

def _fofb5_build(px_bt, rf_bt, bt_start, bt_end, cutoff):
    d = _fofb1_monthly_dataset(px_bt, rf_bt, bt_start, bt_end, cutoff)
    fam = ["MOM","MR","VIX","TEL-DM"]
    idx = d.index

    # Frozen role architecture control
    w_ctrl = pd.DataFrame(0.0, index=idx, columns=fam)
    w_ctrl[["MOM","VIX","MR","TEL-DM"]] = 0.25

    # Price12M level winner
    w_price = pd.DataFrame(0.0, index=idx, columns=fam)
    w_price["MR"] = 0.25
    w_price["TEL-DM"] = 0.25
    pick_price_mom = d["MOM_Price12M"] >= d["VIX_Price12M"]
    w_price.loc[pick_price_mom,"MOM"] = 0.50
    w_price.loc[~pick_price_mom,"VIX"] = 0.50

    # Frozen Prior11M winner benchmark
    w_prior = pd.DataFrame(0.0, index=idx, columns=fam)
    w_prior["MR"] = 0.25
    w_prior["TEL-DM"] = 0.25
    pick_prior_mom = d["MOM_Prior11M"] >= d["VIX_Prior11M"]
    w_prior.loc[pick_prior_mom,"MOM"] = 0.50
    w_prior.loc[~pick_prior_mom,"VIX"] = 0.50

    # Pre-registered Acceleration = one-month change in the frozen Price12M state
    mom_acc = d["MOM_Price12M"] - d["MOM_Price12M"].shift(1)
    vix_acc = d["VIX_Price12M"] - d["VIX_Price12M"].shift(1)
    pick_acc_mom = mom_acc >= vix_acc

    w_acc = pd.DataFrame(0.0, index=idx, columns=fam)
    w_acc["MR"] = 0.25
    w_acc["TEL-DM"] = 0.25
    w_acc.loc[pick_acc_mom,"MOM"] = 0.50
    w_acc.loc[~pick_acc_mom,"VIX"] = 0.50

    ret = d[fam].shift(-1)
    weights = {
        "ControlSpearEW": w_ctrl,
        "Price12Winner": w_price,
        "Prior11Winner": w_prior,
        "AccelerationWinner": w_acc,
    }

    z = pd.DataFrame(index=idx)
    for n,w in weights.items():
        z[n] = (w * ret).sum(axis=1, min_count=1)

    z["Price_vs_Control"] = z["Price12Winner"] - z["ControlSpearEW"]
    z["Prior_vs_Control"] = z["Prior11Winner"] - z["ControlSpearEW"]
    z["Accel_vs_Control"] = z["AccelerationWinner"] - z["ControlSpearEW"]
    z["Accel_vs_Price"] = z["AccelerationWinner"] - z["Price12Winner"]
    z["Accel_vs_Prior"] = z["AccelerationWinner"] - z["Prior11Winner"]

    z["PriceWinner"] = np.where(pick_price_mom,"MOM","VIX")
    z["PriorWinner"] = np.where(pick_prior_mom,"MOM","VIX")
    z["AccelerationWinnerFamily"] = np.where(pick_acc_mom,"MOM","VIX")
    z["MOM_Acceleration"] = mom_acc
    z["VIX_Acceleration"] = vix_acc
    z["AccelerationSpread"] = mom_acc - vix_acc
    z["PriceSpread"] = d["MOM_Price12M"] - d["VIX_Price12M"]
    z["Prior11Spread"] = d["MOM_Prior11M"] - d["VIX_Prior11M"]

    z = z.iloc[:-1].dropna()
    for k in weights:
        weights[k] = weights[k].reindex(z.index)
    return z, weights, d

def _fofb5_perf(z):
    rows=[]
    for label,col in [
        ("Control Spear 50/50","ControlSpearEW"),
        ("Price12M winner","Price12Winner"),
        ("Prior11M winner","Prior11Winner"),
        ("Acceleration winner","AccelerationWinner"),
    ]:
        rows.append({"Strategy":label, **_fofs1_monthly_perf(z[col])})
    return pd.DataFrame(rows)

