def _fofb5_cpcv28(z):
    import itertools
    blocks=np.array_split(np.arange(len(z)),8)
    rows=[]
    for k,(i,j) in enumerate(itertools.combinations(range(8),2),1):
        ix=np.r_[blocks[i],blocks[j]]
