# ================================================================
# FoF B4 — Kawarimi Role Architecture Audit
#
# Hypothesis inspired by Bam's "Kawarimi":
#   combine the strongest and weakest.
#
# User-adapted role architecture, pre-registered BEFORE seeing B4 results:
#   - MR stays fixed at 25% as Shield / Counter-Reversal sleeve.
#   - Rank only MOM / VIX / TEL-DM by frozen Price12M.
#   - Kawarimi allocates the remaining 75% equally to:
#         strongest 37.5% + weakest 37.5%
#     and 0% to the middle-ranked family.
#
# Mechanism ablations:
#   - Strongest-only: MR25 + strongest75
#   - Weakest-only:   MR25 + weakest75
#   - Middle-only:    MR25 + middle75
#
# Control:
#   Frozen 4F EW = MOM25 / MR25 / VIX25 / TEL25.
#
# No threshold / lookback / weight optimization.
# Price12M definition is inherited/frozen.
# Signal month-end t -> return month t+1.
# DEV cutoff = 2026-07-31.
# ================================================================

def _fofb4_build(px_bt, rf_bt, bt_start, bt_end, cutoff):
    d = _fofb1_monthly_dataset(px_bt, rf_bt, bt_start, bt_end, cutoff)
    fam = ["MOM","MR","VIX","TEL-DM"]
    rankfam = ["MOM","VIX","TEL-DM"]

    # Frozen control
    w_ctrl = pd.DataFrame(0.25, index=d.index, columns=fam)

    # Rank by frozen Price12M, higher = stronger.
    score = d[[f"{f}_Price12M" for f in rankfam]].copy()
    score.columns = rankfam
    ranks = score.rank(axis=1, method="first", ascending=False)

    strongest = ranks.idxmin(axis=1)
    weakest = ranks.idxmax(axis=1)
    middle = ranks.apply(lambda r: r.index[r.eq(2)][0] if (r.eq(2)).any() else np.nan, axis=1)

    def make_weights(kind):
        w = pd.DataFrame(0.0, index=d.index, columns=fam)
        w["MR"] = 0.25
        if kind == "Kawarimi":
            for f in rankfam:
                w.loc[strongest.eq(f), f] += 0.375
                w.loc[weakest.eq(f), f] += 0.375
        elif kind == "Strongest":
            for f in rankfam:
                w.loc[strongest.eq(f), f] = 0.75
        elif kind == "Weakest":
            for f in rankfam:
                w.loc[weakest.eq(f), f] = 0.75
        elif kind == "Middle":
            for f in rankfam:
                w.loc[middle.eq(f), f] = 0.75
        return w

    weights = {
        "Control4F_EW": w_ctrl,
        "Kawarimi": make_weights("Kawarimi"),
        "StrongestOnly": make_weights("Strongest"),
        "WeakestOnly": make_weights("Weakest"),
        "MiddleOnly": make_weights("Middle"),
    }

    ret = d[fam].shift(-1)
    out = pd.DataFrame(index=d.index)
    for n,w in weights.items():
        out[n] = (w * ret).sum(axis=1, min_count=1)

    out["Kawarimi_vs_Control"] = out["Kawarimi"] - out["Control4F_EW"]
    out["Strongest_vs_Control"] = out["StrongestOnly"] - out["Control4F_EW"]
    out["Weakest_vs_Control"] = out["WeakestOnly"] - out["Control4F_EW"]
    out["Middle_vs_Control"] = out["MiddleOnly"] - out["Control4F_EW"]
    out["Kawarimi_vs_Strongest"] = out["Kawarimi"] - out["StrongestOnly"]
    out["Kawarimi_vs_Weakest"] = out["Kawarimi"] - out["WeakestOnly"]
    out["Strongest"] = strongest
    out["Weakest"] = weakest
    out["Middle"] = middle
    combo = strongest.astype(str) + " + " + weakest.astype(str)
    out["KawarimiPair"] = combo

    # Drop final signal month without next-month realized return.
    out = out.iloc[:-1].dropna()

    for k in list(weights):
        weights[k] = weights[k].reindex(out.index)

    return out, weights, d

def _fofb4_perf(z):
    rows=[]
    labels=[
        ("Control 4F EW","Control4F_EW"),
        ("Kawarimi strongest+weakest","Kawarimi"),
        ("Strongest-only","StrongestOnly"),
        ("Weakest-only","WeakestOnly"),
        ("Middle-only","MiddleOnly"),
    ]
    for n,c in labels:
        rows.append({"Strategy":n, **_fofs1_monthly_perf(z[c])})
    return pd.DataFrame(rows)

