# ================================================================
# FoF B3 — Nukimi vs Fixed VIX Tilt Falsification
#
# Purpose:
#   Test whether the promising B1/B2 Role-preserving Nukimi edge is
#   genuine conditional selection alpha, or mainly a VIX-overweight effect.
#
# Pre-registered strategies only:
#   Control 4F EW       = MOM25 / VIX25 / TEL25 / MR25
#   Role Nukimi         = MOM50 or VIX50 by frozen Prior11M winner
#                         + TEL25 + MR25
#   Fixed VIX Tilt      = MOM0 / VIX50 / TEL25 / MR25
#   Fixed MOM Tilt      = MOM50 / VIX0 / TEL25 / MR25
#
# No threshold / lookback / weight search.
# Signal month-end t -> return month t+1.
# DEV cutoff = 2026-07-31.
# ================================================================

def _fofb3_build(px_bt, rf_bt, bt_start, bt_end, cutoff):
    d = _fofb1_monthly_dataset(px_bt, rf_bt, bt_start, bt_end, cutoff)
    fam = ["MOM","MR","VIX","TEL-DM"]

    w_ctrl = pd.DataFrame(0.25, index=d.index, columns=fam)

    w_nuk = pd.DataFrame(0.0, index=d.index, columns=fam)
    w_nuk["MR"] = 0.25
    w_nuk["TEL-DM"] = 0.25
    pick_mom = d["MOM_Prior11M"] >= d["VIX_Prior11M"]
    w_nuk.loc[pick_mom, "MOM"] = 0.50
    w_nuk.loc[~pick_mom, "VIX"] = 0.50

    w_vix = pd.DataFrame(0.0, index=d.index, columns=fam)
    w_vix["VIX"] = 0.50
    w_vix["TEL-DM"] = 0.25
    w_vix["MR"] = 0.25

    w_mom = pd.DataFrame(0.0, index=d.index, columns=fam)
    w_mom["MOM"] = 0.50
    w_mom["TEL-DM"] = 0.25
    w_mom["MR"] = 0.25

    ret = d[fam].shift(-1)
    out = pd.DataFrame(index=d.index)
    out["Control4F_EW"] = (w_ctrl * ret).sum(axis=1, min_count=1)
    out["RoleNukimi"] = (w_nuk * ret).sum(axis=1, min_count=1)
    out["FixedVIX"] = (w_vix * ret).sum(axis=1, min_count=1)
    out["FixedMOM"] = (w_mom * ret).sum(axis=1, min_count=1)

    out["Nukimi_vs_Control"] = out["RoleNukimi"] - out["Control4F_EW"]
    out["VIX_vs_Control"] = out["FixedVIX"] - out["Control4F_EW"]
    out["MOM_vs_Control"] = out["FixedMOM"] - out["Control4F_EW"]
    out["Nukimi_vs_VIX"] = out["RoleNukimi"] - out["FixedVIX"]
    out["Nukimi_vs_MOM"] = out["RoleNukimi"] - out["FixedMOM"]
    out["SelectedSpear"] = np.where(pick_mom, "MOM", "VIX")
    out["Switch"] = pd.Series(out["SelectedSpear"], index=out.index).ne(
        pd.Series(out["SelectedSpear"], index=out.index).shift(1)
    ).fillna(False)
    out["Prior11_MOMminusVIX"] = d["MOM_Prior11M"] - d["VIX_Prior11M"]

    return out.iloc[:-1].dropna(), {
        "Control4F_EW": w_ctrl.iloc[:-1],
        "RoleNukimi": w_nuk.iloc[:-1],
        "FixedVIX": w_vix.iloc[:-1],
        "FixedMOM": w_mom.iloc[:-1],
    }, d

