# ================================================================
# FoF S1 — Shield Role Audit
#
# Primary question:
#   Can the user's Frozen Weekly MR24M be called a "shield" in the
#   FoF sense — i.e. does it help specifically when the OTHER
#   families are hurting, rather than merely having low standalone DD?
#
# Primary MR = exact Frozen Weekly MR24M (504d).
# Secondary architecture view = frozen MR family
#   50% Weekly MR24M + 50% Quarterly MR24M.
#
# Other families are inherited frozen:
#   MOM, VIX, TEL-DM.
#
# No fitting, no weight optimization, no new indicators.
# DEV cutoff fixed at 2026-07-31.
# ================================================================

def _fofs1_monthly_from_daily(x):
    return (1.0 + x).resample("ME").prod(min_count=1) - 1.0

def _fofs1_monthly_ew(monthly_df):
    # Fixed equal-weight monthly family portfolio from monthly returns.
    return monthly_df.mean(axis=1, skipna=False)

def _fofs1_beta(y, x):
    z = pd.concat([pd.Series(y), pd.Series(x)], axis=1).dropna()
    if len(z) < 3 or float(z.iloc[:,1].var()) == 0:
        return np.nan
    return float(z.iloc[:,0].cov(z.iloc[:,1]) / z.iloc[:,1].var())

def _fofs1_capture(y, spy):
    z = pd.concat([pd.Series(y).rename("Y"), pd.Series(spy).rename("SPY")], axis=1).dropna()
    up = z[z["SPY"] > 0]
    dn = z[z["SPY"] < 0]
    upcap = float(up["Y"].mean() / up["SPY"].mean()) if len(up) and up["SPY"].mean()!=0 else np.nan
    dncap = float(dn["Y"].mean() / dn["SPY"].mean()) if len(dn) and dn["SPY"].mean()!=0 else np.nan
    return upcap, dncap

def _fofs1_shield_stats(name, shield, exshield, spy):
    z = pd.concat([
        shield.rename("Shield"),
        exshield.rename("ExShield"),
        spy.rename("SPY")
    ], axis=1).dropna()
    if z.empty:
        return {}
    worst10_cut = z["ExShield"].quantile(0.10)
    spy10_cut = z["SPY"].quantile(0.10)
    exneg = z[z["ExShield"] < 0]
    exworst = z[z["ExShield"] <= worst10_cut]
    spyneg = z[z["SPY"] < 0]
    spyworst = z[z["SPY"] <= spy10_cut]
    upcap, dncap = _fofs1_capture(z["Shield"], z["SPY"])
    return {
        "Shield": name,
        "Months": len(z),
        "MeanReturn": float(z["Shield"].mean()),
        "VolMonthly": float(z["Shield"].std(ddof=1)),
        "BetaToSPY": _fofs1_beta(z["Shield"], z["SPY"]),
        "CorrToExShield": float(z["Shield"].corr(z["ExShield"])),
        "ShieldHitRate_ExShieldNeg":
            float((exneg["Shield"] > 0).mean()) if len(exneg) else np.nan,
        "MeanShieldReturn_ExShieldNeg":
            float(exneg["Shield"].mean()) if len(exneg) else np.nan,
        "MeanShieldReturn_ExShieldWorst10":
            float(exworst["Shield"].mean()) if len(exworst) else np.nan,
        "PositiveRate_ExShieldWorst10":
            float((exworst["Shield"] > 0).mean()) if len(exworst) else np.nan,
        "MeanShieldReturn_SPYNeg":
            float(spyneg["Shield"].mean()) if len(spyneg) else np.nan,
        "MeanShieldReturn_SPYWorst10":
            float(spyworst["Shield"].mean()) if len(spyworst) else np.nan,
        "PositiveRate_SPYWorst10":
            float((spyworst["Shield"] > 0).mean()) if len(spyworst) else np.nan,
        "UpsideCapture_MeanRatio": upcap,
        "DownsideCapture_MeanRatio": dncap,
    }

def _fofs1_monthly_perf(r):
    r = pd.Series(r).dropna()
    if not len(r):
        return {}
    ann = 12.0
    eq = (1+r).cumprod()
    yrs = len(r)/12.0
    cagr = float(eq.iloc[-1]**(1/yrs)-1) if yrs>0 else np.nan
    vol = float(r.std(ddof=1)*np.sqrt(ann)) if len(r)>1 else np.nan
    sh = float(r.mean()/r.std(ddof=1)*np.sqrt(ann)) if len(r)>1 and r.std(ddof=1)>0 else np.nan
    neg = r[r<0]
    sort = float(r.mean()/np.sqrt((np.minimum(r,0)**2).mean())*np.sqrt(ann)) if len(r) and np.sqrt((np.minimum(r,0)**2).mean())>0 else np.nan
    dd = eq/eq.cummax()-1
    mdd = float(dd.min())
    cal = float(cagr/abs(mdd)) if pd.notna(cagr) and mdd<0 else np.nan
    return {"CAGR":cagr,"Vol":vol,"MaxDD":mdd,"Sharpe0":sh,"Sortino0":sort,"Calmar":cal}

def _fofs1_drawdown_addition(exshield, shield, shield_weight=0.25):
    # Compare ex-shield 3F EW with 4F equal weight (25% each).
    z = pd.concat([exshield.rename("3F_exMR"), shield.rename("MR")],axis=1).dropna()
    four = (1-shield_weight)*z["3F_exMR"] + shield_weight*z["MR"]
    rows = []
    for nm, s in [("3F ex-MR", z["3F_exMR"]), ("4F with MR", four)]:
        rows.append({"Portfolio":nm, **_fofs1_monthly_perf(s)})
    return pd.DataFrame(rows), four

def _fofs1_stress(shields, exshield, spy):
    episodes = [
        ("2015 selloff","2015-07-01","2015-09-30"),
        ("2018 Q4","2018-10-01","2018-12-31"),
        ("2019-05","2019-05-01","2019-05-31"),
        ("COVID","2020-02-01","2020-04-30"),
        ("2022 selloff","2022-04-01","2022-10-31"),
        ("2025 selloff","2025-02-01","2025-04-30"),
    ]
    rows=[]
    for nm,a,b in episodes:
        row={"Episode":nm}
        ex = exshield.loc[a:b].dropna()
        sp = spy.loc[a:b].dropna()
        row["ExMR Return"]=float((1+ex).prod()-1) if len(ex) else np.nan
        row["SPY Return"]=float((1+sp).prod()-1) if len(sp) else np.nan
        for n,s in shields.items():
            q=s.loc[a:b].dropna()
            row[n+" Return"]=float((1+q).prod()-1) if len(q) else np.nan
            both=pd.concat([ex.rename("Ex"),q.rename("MR")],axis=1).dropna()
            row[n+" BeatsExMRRate"]=float((both["MR"]>both["Ex"]).mean()) if len(both) else np.nan
        rows.append(row)
    return pd.DataFrame(rows)

def _fofs1_attack_state(sig, monthly_index):
    # Monthly indicator: did exact Frozen Weekly MR spend any weekly signal point
    # in TQQQ during that month? Also first-state and fraction of weekly signals.
    s=(sig["FrozenHolding"]=="TQQQ").astype(float)
    tmp=pd.DataFrame({"Attack":s})
    tmp["Month"]=tmp.index.to_period("M")
    agg=tmp.groupby("Month")["Attack"].agg(["mean","max","first"])
    agg.index=agg.index.to_timestamp("M")
    out=agg.reindex(monthly_index)
    out.columns=["WeeklySignalAttackFraction","AnyAttack","FirstWeeklySignalAttack"]
    return out

