# ================================================================
# MR Evolution E2 — Sparse Early Attack Audit
# Exact Frozen Core Weekly MR24M (504 trading days) is preserved.
# Early Attack is allowed ONLY while Frozen MR says XLU.
# Trigger is pre-fixed from already-established RE evidence:
#   weak long-term state + deep 12M drawdown, both measured as
#   prior-only expanding lower-quartile states among prior Frozen-XLU weeks.
# No Shin-Genbu labels are used to define or fit the trigger.
# ================================================================

def _mr_e2_signal_table(px, rf_rates):
    idx = pd.DatetimeIndex(px.index).sort_values()
    rows = []
    for d in _model_trade_dates(idx, "Weekly MR 24M"):
        try:
            signal_end = idx[idx < d][-1]
            r504, s0, s1 = trading_return(px["SPXL"], signal_end, 504)
            rf504 = rf_return(rf_rates, s0, s1)
            gap = float(r504 - rf504)

            # Existing R2/R8-established descriptor family: 12M drawdown.
            s = px["SPXL"].loc[:signal_end].dropna()
            start = signal_end - pd.DateOffset(months=12)
            win = s.loc[s.index >= start]
            if len(win) < 2:
                dd12 = np.nan
            else:
                dd12 = float(s.loc[signal_end] / win.max() - 1.0)

            rows.append({
                "TradeDate": pd.Timestamp(d),
                "SignalEnd": pd.Timestamp(signal_end),
                "Ret504": float(r504),
                "RF504": float(rf504),
                "Gap504": gap,
                "DD12M": dd12,
                "FrozenHolding": "TQQQ" if gap < 0 else "XLU",
                "FrozenTQQQWeight": 1.0 if gap < 0 else 0.0,
            })
        except (ValueError, IndexError, KeyError):
            pass
    z = pd.DataFrame(rows)
    if len(z):
        z = z.set_index("TradeDate").sort_index()
    return z

def _mr_e2_prior_xlu_quantiles(sig, min_xlu_obs=52, q=0.25):
    gap_q = []
    dd_q = []
    for i, (_, row) in enumerate(sig.iterrows()):
        hist = sig.iloc[:i]
        hist = hist[hist["FrozenHolding"] == "XLU"]
        hist = hist.dropna(subset=["Gap504","DD12M"])
        if len(hist) < min_xlu_obs:
            gap_q.append(np.nan); dd_q.append(np.nan)
        else:
            gap_q.append(float(hist["Gap504"].quantile(q)))
            dd_q.append(float(hist["DD12M"].quantile(q)))
    out = sig.copy()
    out["PriorXLU_Gap_Q25"] = gap_q
    out["PriorXLU_DD12_Q25"] = dd_q
    out["EarlyAttackTrigger"] = (
        (out["FrozenHolding"] == "XLU") &
        out["PriorXLU_Gap_Q25"].notna() &
        out["PriorXLU_DD12_Q25"].notna() &
        (out["Gap504"] <= out["PriorXLU_Gap_Q25"]) &
        (out["DD12M"] <= out["PriorXLU_DD12_Q25"])
    )
    return out

def _mr_e2_weights(sig):
    s = sig.copy()
    s["A_Frozen504"] = s["FrozenTQQQWeight"]
    for frac, tag in [(0.25,"B_Early25"),(0.50,"C_Early50"),(1.00,"D_Early100")]:
        s[tag] = s["A_Frozen504"].astype(float)
        m = s["EarlyAttackTrigger"] & (s["FrozenHolding"] == "XLU")
        s.loc[m, tag] = frac
    return s

def _mr_e2_daily_returns(px, w):
    idx = pd.DatetimeIndex(px.index).sort_values()
    rr = px[["TQQQ","XLU"]].pct_change().reindex(idx)
    out = {}
    cols = ["A_Frozen504","B_Early25","C_Early50","D_Early100"]
    for c in cols:
        ww = w[c].reindex(idx).ffill().shift(1)
        out[c] = ww*rr["TQQQ"] + (1.0-ww)*rr["XLU"]
    return pd.DataFrame(out)


# ================================================================
# MR Evolution E1 — Continuous / Asymmetric Reversal Ablation
# Goal: transfer only already-discovered Genbu mechanisms into the
# user's Frozen Weekly MR24M, without reconstructing Bam's hidden pool.
# ================================================================

def _mr_e1_weekly_signal_table(px, rf_rates):
    idx = pd.DatetimeIndex(px.index).sort_values()
    rows = []
    for i in range(1, len(idx)):
        d = idx[i]
        if not _is_first_trading_day_of_week(idx, i):
            continue
        try:
            signal_end = idx[idx < d][-1]
            r24, s0, s1 = calendar_return(px["SPXL"], signal_end, 24, exclude_recent=0)
            rf24 = rf_return(rf_rates, s0, s1)
            # Same-state 1M change: current Ret24M minus the Ret24M observed one calendar month earlier.
            prev_end_candidates = idx[idx <= (signal_end - pd.DateOffset(months=1))]
            if len(prev_end_candidates):
                prev_end = prev_end_candidates[-1]
                prev_r24, _, _ = calendar_return(px["SPXL"], prev_end, 24, exclude_recent=0)
                d1 = r24 - prev_r24
            else:
                d1 = np.nan
            rows.append({
                "Date": pd.Timestamp(d), "SignalEnd": pd.Timestamp(signal_end),
                "Ret24M": float(r24), "RF24M": float(rf24),
                "Gap24M": float(r24-rf24), "dRet24M_1M": float(d1) if np.isfinite(d1) else np.nan,
            })
        except (ValueError, IndexError, KeyError):
            pass
    z = pd.DataFrame(rows)
    if len(z):
        z = z.set_index("Date").sort_index()
    return z

def _mr_e1_expanding_z(x, min_obs=36):
    x = pd.Series(x, dtype=float)
    mu = x.expanding(min_periods=min_obs).mean().shift(1)
    sd = x.expanding(min_periods=min_obs).std(ddof=1).shift(1)
    return (x-mu)/sd.replace(0, np.nan)

def _mr_e1_weights(signals):
    s = signals.copy()
    # A. Frozen source-consistent calendar-24 binary prototype.
    s["A_FrozenBinary"] = (s["Gap24M"] < 0).astype(float)

    # B. Continuous Reversal:
    # parameter-free smooth mapping borrowed from already-frozen TEL v4.03 machinery.
    # z is expanding prior-only, min 36 observations; no full-sample normalization.
    s["GapZ"] = _mr_e1_expanding_z(s["Gap24M"], 36)
    s["B_Continuous"] = 0.5 * (1.0 - np.tanh(s["GapZ"]))
    s["B_Continuous"] = s["B_Continuous"].clip(0.0, 1.0)

    # C. Asymmetric binary:
    # Entry is unchanged (Gap<0). Once in TQQQ, recovery does not exit merely
    # because Gap crosses >=0; exit requires Gap>=0 AND 24M state is improving (d1>0).
    # This is a fixed mechanism transfer from R14, not a fitted threshold.
    c = []
    prev = 0.0
    for _, r in s.iterrows():
        gap = r["Gap24M"]; d1 = r["dRet24M_1M"]
        if prev < 0.5:
            cur = 1.0 if gap < 0 else 0.0
        else:
            cur = 0.0 if (gap >= 0 and pd.notna(d1) and d1 > 0) else 1.0
        c.append(cur); prev = cur
    s["C_Asymmetric"] = c

    # D. Continuous + persistence:
    # continuous target is allowed to rise immediately (early attack);
    # while the 24M state is still below RF, do not mechanically cut a previously
    # larger TQQQ weight during a one-month rebound. Once Gap>=0, follow the smooth target.
    d = []
    prev = np.nan
    for _, r in s.iterrows():
        base = r["B_Continuous"]
        if pd.isna(base):
            d.append(np.nan); continue
        if pd.isna(prev):
            cur = float(base)
        elif r["Gap24M"] < 0 and pd.notna(r["dRet24M_1M"]) and r["dRet24M_1M"] > 0:
            cur = max(float(base), float(prev))
        else:
            cur = float(base)
        d.append(cur); prev = cur
    s["D_ContinuousPlusPersistence"] = d
    return s

def _mr_e1_daily_returns_from_weekly_weights(px, w):
    idx = pd.DatetimeIndex(px.index).sort_values()
    rr = px[["TQQQ","XLU"]].pct_change().reindex(idx)
    out = {}
    for col in ["A_FrozenBinary","B_Continuous","C_Asymmetric","D_ContinuousPlusPersistence"]:
        ww = w[col].reindex(idx).ffill().shift(1)  # rebalance-date close -> next trading day return
        out[col] = ww*rr["TQQQ"] + (1.0-ww)*rr["XLU"]
    return pd.DataFrame(out).dropna(how="all")

def _mr_e1_perf(r):
    r = pd.Series(r).dropna().astype(float)
    if len(r) < 2: return {}
    wealth=(1+r).cumprod()
    yrs=len(r)/252.0
    cagr=float(wealth.iloc[-1]**(1/yrs)-1) if yrs>0 and wealth.iloc[-1]>0 else np.nan
    vol=float(r.std(ddof=1)*np.sqrt(252))
    dd=wealth/wealth.cummax()-1
    sharpe=float(r.mean()/r.std(ddof=1)*np.sqrt(252)) if r.std(ddof=1)>0 else np.nan
    downside=r[r<0].std(ddof=1)*np.sqrt(252)
    sortino=float((r.mean()*252)/downside) if pd.notna(downside) and downside>0 else np.nan
    return {"Days":len(r),"CAGR":cagr,"Vol":vol,"MaxDD":float(dd.min()),"Sharpe0":sharpe,"Sortino0":sortino}



# ================================================================
# Genbu RE R16 — Objective Metric Audit
# Author definitions now fixed from user-supplied Bam-san context:
#   激攻 = CAGR
#   常勝 = NHF (New High Frequency / 新高値更新頻度)
#   鉄壁 = Max Drawdown
# Candidate redesign:
#   激攻 = CAGR
#   鉄壁? = Worst Year
#   常勝? = AveUWP (Average Underwater Period / 平均水面下期間)
# ================================================================

def _genbu_r16_objective_metrics(r):
    """
    Fixed descriptive monthly-equity accounting.
    NHF = fraction of observed month-end equity points at a new all-time high
          (ties included, tolerance 1e-12).
    AveUWP = mean duration, in observed monthly intervals, of COMPLETED underwater
             episodes only. An episode begins after leaving a prior high and ends
             when the equity curve regains/exceeds that prior high.
    Open/unrecovered terminal underwater episode is reported separately and is
    NOT silently folded into AveUWP.
    """
    r = pd.Series(r).dropna().astype(float)
    if r.empty:
        return {}, pd.DataFrame(), pd.DataFrame()

    wealth = (1.0 + r).cumprod()
    peak = wealth.cummax()
    dd = wealth / peak - 1.0
    tol = 1e-12
    is_high = wealth >= peak * (1.0 - tol)

    years = len(r) / 12.0
    cagr = float(wealth.iloc[-1] ** (1.0 / years) - 1.0) if years > 0 and wealth.iloc[-1] > 0 else np.nan
    maxdd = float(dd.min())
    yearly = r.groupby(r.index.year).apply(lambda x: float((1.0 + x).prod() - 1.0))
    worst_year = float(yearly.min()) if len(yearly) else np.nan
    nhf = float(is_high.mean())

    # Completed underwater episodes in monthly observations.
    episodes = []
    in_uw = False
    start_i = None
    start_month = None
    prior_peak_month = None
    last_high_month = None
    for i, (m, high) in enumerate(is_high.items()):
        if bool(high):
            if in_uw:
                duration = i - start_i + 1
                episodes.append({
                    "StartUnderwaterMonth": str(start_month),
                    "RecoveryMonth": str(m),
                    "PriorHighMonth": str(prior_peak_month) if prior_peak_month is not None else "",
                    "DurationObservedMonths": int(duration),
                    "Completed": True,
                })
                in_uw = False
                start_i = None
                start_month = None
            last_high_month = m
        else:
            if not in_uw:
                in_uw = True
                start_i = i
                start_month = m
                prior_peak_month = last_high_month

    open_uw_months = 0
    if in_uw and start_i is not None:
        open_uw_months = int(len(is_high) - start_i)
        episodes.append({
            "StartUnderwaterMonth": str(start_month),
            "RecoveryMonth": "",
            "PriorHighMonth": str(prior_peak_month) if prior_peak_month is not None else "",
            "DurationObservedMonths": open_uw_months,
            "Completed": False,
        })

    ep = pd.DataFrame(episodes)
    completed = ep.loc[ep["Completed"] == True] if len(ep) else pd.DataFrame()
    ave_uwp = float(completed["DurationObservedMonths"].mean()) if len(completed) else np.nan
    med_uwp = float(completed["DurationObservedMonths"].median()) if len(completed) else np.nan
    max_completed_uwp = int(completed["DurationObservedMonths"].max()) if len(completed) else np.nan

    curve = pd.DataFrame({
        "Month": [str(x) for x in r.index],
        "Return": r.values,
        "Wealth": wealth.values,
        "Drawdown": dd.values,
        "NewHigh": is_high.values,
    })

    metrics = {
        "Months": int(len(r)),
        "CAGR": cagr,
        "MaxDrawdown": maxdd,
        "WorstYear": worst_year,
        "NHF": nhf,
        "NewHighMonths": int(is_high.sum()),
        "CompletedUnderwaterEpisodes": int(len(completed)),
        "AveUWP_Months": ave_uwp,
        "MedianUWP_Months": med_uwp,
        "MaxCompletedUWP_Months": max_completed_uwp,
        "OpenUnderwaterEpisode": bool(in_uw),
        "OpenUWP_Months_at_DEV_End": int(open_uw_months),
    }
    return metrics, ep, curve


