def _genbu_parse_position_text(txt, name):
    rows = []
    for line in txt.strip().splitlines():
        parts = line.split()
        if len(parts) != 2:
            continue
        rows.append((pd.Period(parts[0], freq="M"), parts[1]))
    s = pd.Series(dict(rows), name=name, dtype="object").sort_index()
    s.index.name = "Month"
    return s

def _genbu_three_variant_targets():
    return {
        "激攻": _genbu_target_monthly_positions().rename("激攻"),
        "常勝": _genbu_parse_position_text(_GENBU_JOUSHOU_MONTHLY_POSITION_TEXT, "常勝"),
        "鉄壁": _genbu_parse_position_text(_GENBU_TEPPEKI_MONTHLY_POSITION_TEXT, "鉄壁"),
    }

def _genbu_monthly_strategy_proxy_returns(px, labels):
    """
    Fixed descriptive proxy only:
    hold the month-T label from the first available trading-day close of T
    to the first available trading-day close of T+1.
    This is NOT claimed to reproduce Bam-san's optimization engine/PV accounting.
    """
    idx = pd.DatetimeIndex(px.index).sort_values()
    periods = idx.to_period("M")
    first_dates = pd.Series(idx, index=periods).groupby(level=0).first()
    out = {}
    for p, asset in labels.dropna().items():
        if asset not in ("TQQQ", "XLU"):
            continue
        if p not in first_dates.index or (p+1) not in first_dates.index:
            continue
        d0 = pd.Timestamp(first_dates.loc[p]); d1 = pd.Timestamp(first_dates.loc[p+1])
        try:
            a = float(px.loc[d0, asset]); b = float(px.loc[d1, asset])
            if np.isfinite(a) and np.isfinite(b) and a > 0:
                out[p] = b/a - 1.0
        except Exception:
            pass
    s = pd.Series(out, dtype=float, name=labels.name).sort_index()
    s.index = pd.PeriodIndex(s.index, freq="M", name="Month")
    return s

def _genbu_path_metrics_from_monthly(r):
    r = pd.Series(r).dropna().astype(float)
    if r.empty:
        return {}
    wealth = (1+r).cumprod()
    years = len(r)/12.0
    cagr = float(wealth.iloc[-1]**(1/years)-1) if years > 0 and wealth.iloc[-1] > 0 else np.nan
    vol = float(r.std(ddof=1)*np.sqrt(12)) if len(r)>1 else np.nan
    dd = wealth/wealth.cummax()-1
    maxdd = float(dd.min())
    yearly = r.groupby(r.index.year).apply(lambda x: float((1+x).prod()-1))
    worst_year = float(yearly.min()) if len(yearly) else np.nan
    return {
        "Months": int(len(r)),
        "CAGR_proxy": cagr,
        "Vol_proxy": vol,
        "MonthlyMaxDD_proxy": maxdd,
        "WorstYear_proxy": worst_year,
    }


