def _genbu_r13_smd(a, b):
    """Standardized mean difference: mean(a)-mean(b) using pooled sample SD."""
    a = pd.Series(a).dropna().astype(float)
    b = pd.Series(b).dropna().astype(float)
    if len(a) < 2 or len(b) < 2:
        return np.nan
    va = float(a.var(ddof=1)); vb = float(b.var(ddof=1))
    den_n = len(a) + len(b) - 2
    if den_n <= 0:
        return np.nan
    pooled = np.sqrt(((len(a)-1)*va + (len(b)-1)*vb) / den_n)
    if not np.isfinite(pooled) or pooled == 0:
        return np.nan
    return float((a.mean() - b.mean()) / pooled)

def _genbu_r13_pair_superiority(a, b):
    """
    P(A > B) + 0.5 P(A == B), distribution-free descriptive effect.
    Returns NaN if either group is empty. Small N is expected; no p-values.
    """
    a = pd.Series(a).dropna().astype(float).to_numpy()
    b = pd.Series(b).dropna().astype(float).to_numpy()
    if len(a) == 0 or len(b) == 0:
        return np.nan
    comp = a[:, None] - b[None, :]
    return float(((comp > 0).sum() + 0.5*(comp == 0).sum()) / comp.size)



# ================================================================
# Genbu RE R6 — Entry Episode Casebook
# Twelve DEV entry events are inspected one by one using ONLY the
# R2-frozen feature universe/horizons and R4/R5 pre-existing native states.
# No clustering, threshold search, classifier, or rule construction.
# ================================================================
def _genbu_r6_prior_xlu_streak(target, entry_month):
    """Consecutive XLU months immediately before an entry position month."""
    s = pd.Series(target).sort_index()
    if entry_month not in s.index:
        return np.nan
    loc = s.index.get_loc(entry_month)
    if isinstance(loc, slice) or isinstance(loc, np.ndarray):
        return np.nan
    n = 0
    i = int(loc) - 1
    while i >= 0 and s.iloc[i] == "XLU":
        n += 1
        i -= 1
    return n


def _genbu_r6_episode_map(target, dev_end):
    """Map each TQQQ entry month to its DEV-observed episode length/last month/exit."""
    s = pd.Series(target).sort_index().loc[:dev_end]
    rows = []
    prev = None
    start = None
    months = []
    for m, v in s.items():
        if v == "TQQQ" and prev != "TQQQ":
            start = m
            months = [m]
        elif v == "TQQQ" and prev == "TQQQ" and start is not None:
            months.append(m)
        elif v != "TQQQ" and prev == "TQQQ" and start is not None:
            rows.append({
                "EntryMonth": start,
                "EpisodeTQQQMonths": len(months),
                "LastTQQQMonth": months[-1],
                "ExitMonth": m,
                "EpisodeOpenAtDEVEnd": False,
            })
            start = None
            months = []
        prev = v
    if start is not None:
        rows.append({
            "EntryMonth": start,
            "EpisodeTQQQMonths": len(months),
            "LastTQQQMonth": months[-1],
            "ExitMonth": pd.NaT,
            "EpisodeOpenAtDEVEnd": True,
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out = out.set_index("EntryMonth")
    return out


def _genbu_r6_forward_entry_returns(monthly_prices, entry_months):
    """Descriptive outcome only: cumulative TQQQ return over entry month + next k-1 months."""
    if "TQQQ" not in monthly_prices.columns:
        return pd.DataFrame(index=pd.Index(entry_months, name="EntryMonth"))
    p = monthly_prices["TQQQ"].dropna().copy()
    p.index = pd.PeriodIndex(p.index, freq="M")
    rows = []
    for e in entry_months:
        row = {"EntryMonth": e}
        # Position month T return is from T-1 month-end to T month-end.
        for h in (1, 3, 6):
            p0 = p.get(e - 1, np.nan)
            p1 = p.get(e + h - 1, np.nan)
            row[f"TQQQ_Forward{h}M_from_Tminus1"] = (p1 / p0 - 1.0) if pd.notna(p0) and pd.notna(p1) and p0 != 0 else np.nan
        rows.append(row)
    return pd.DataFrame(rows).set_index("EntryMonth") if rows else pd.DataFrame()



# ================================================================
# R11 — 4F Promotion100 Top Drawdown Daily Anatomy
# PRE-REGISTERED DIAGNOSTIC ONLY. No rule/parameter/weight search.
# DEV cutoff = 2026-07-31.
# Purpose: decompose realized 4F Promotion100 top-5 peak→trough paths
# day by day into frozen family contribution, frozen booster layers,
# trigger states, concentration, and trigger timing.
# ================================================================

def _r11_build_tables(px_bt, rf_bt, start, end):
    b = _r10_build(px_bt, rf_bt, start, end)
    f = b['finals'].copy()
    dd = _r10_drawdown_cycles(f['4F Promotion100'], 5)
    daily_rows=[]; summary=[]; fam_rows=[]; layer_rows=[]; trigger_rows=[]
    state_cols=[c for c in ['A Gate','VIX30 Brake','allow_L2','Turbo','Choose TECL','Promotion100'] if c in b['states'].columns]
    for _,r in dd.iterrows():
        rank=int(r['Rank']); a=pd.Timestamp(r['PeakDate']); z=pd.Timestamp(r['TroughDate'])
        ix=f.loc[a:z].index
        if len(ix)==0: continue
        x=f.loc[ix,'4F Promotion100'].astype(float)
        v=f.loc[ix,'Frozen v3.45 Final'].astype(float)
        eq=(1+x).cumprod(); pathdd=eq/eq.cummax()-1
        c4=b['fourf_family_contrib'].reindex(ix).fillna(0.0)
        l4=b['fourf_layers'].reindex(ix).fillna(0.0)
        st=b['states'].reindex(ix)
        # Daily table: exact additive base-family view and exact additive layer bridge are separate.
        for dt in ix:
            row={'DDRank':rank,'PeakDate':a,'TroughDate':z,'Date':dt,
                 '4F_Return':float(x.loc[dt]),'v345_Return':float(v.loc[dt]),
                 'v345_minus_4F':float(v.loc[dt]-x.loc[dt]),
                 '4F_CumReturn_FromPeak':float((1+x.loc[:dt]).prod()-1),
                 '4F_PathDD':float(pathdd.loc[dt])}
            for c in c4.columns: row['Family_'+c]=float(c4.loc[dt,c])
            for c in l4.columns: row['Layer_'+c]=float(l4.loc[dt,c])
            for c in state_cols: row['State_'+c]=bool(st.loc[dt,c]) if pd.notna(st.loc[dt,c]) else False
            daily_rows.append(row)
        # Concentration of realized 4F losses.
        neg=x[x<0].sort_values()
        total_loss=float((-x.clip(upper=0)).sum())
        def loss_share(n):
            if total_loss<=0 or len(neg)==0: return np.nan
            return float((-neg.head(n)).sum()/total_loss)
        summary.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'RecoveryDate':r.get('RecoveryDate',pd.NaT),
                        'TradingDays':len(ix),'4F_Return':float((1+x).prod()-1),'4F_MaxDD':float(pathdd.min()),
                        'v345_Return_SameWindow':float((1+v).prod()-1),
                        'Worst1Day':float(x.min()),'Worst1Date':x.idxmin(),
                        'LossShareWorst1':loss_share(1),'LossShareWorst3':loss_share(3),'LossShareWorst5':loss_share(5),
                        'NegativeDays':int((x<0).sum()),'PositiveDays':int((x>0).sum())})
        # Additive contribution sums over the exact peak→trough path.
        for c in c4.columns:
            fam_rows.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'Family':c,
                             'SumDailyContribution':float(c4[c].sum()),
                             'WorstDailyContribution':float(c4[c].min()),'WorstDate':c4[c].idxmin()})
        for c in l4.columns:
            layer_rows.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'Layer':c,
                               'SumDailyEffect':float(l4[c].sum()),
                               'WorstDailyEffect':float(l4[c].min()),'WorstDate':l4[c].idxmin()})
        # Trigger timing/frequency inside the realized drawdown path.
        for c in state_cols:
            s=st[c].fillna(False).astype(bool)
            on=s[s].index
            trigger_rows.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'State':c,
                                 'OnDays':int(s.sum()),'OnShare':float(s.mean()),
                                 'FirstOnDate':on[0] if len(on) else pd.NaT,
                                 'DaysFromPeakToFirstOn':int(ix.get_loc(on[0])) if len(on) else np.nan})
    daily=pd.DataFrame(daily_rows); summ=pd.DataFrame(summary); fam=pd.DataFrame(fam_rows); layers=pd.DataFrame(layer_rows); triggers=pd.DataFrame(trigger_rows)
    # Exactness: family contributions reconstruct Frozen 4F base; layers bridge base→Promotion100.
    exact=[]
    idx=f.index
    fam_sum=b['fourf_family_contrib'].reindex(idx).sum(axis=1)
    base=f['4F Base'].reindex(idx)
    final=f['4F Promotion100'].reindex(idx)
    layer_sum=b['fourf_layers'].reindex(idx).sum(axis=1)
    e1=float((fam_sum-base).abs().max())
    e2=float((base+layer_sum-final).abs().max())
    exact.append({'Check':'4F family contribution reconstructs 4F Base','MaxAbsError':e1,'PASS':e1<1e-10})
    exact.append({'Check':'4F Base + all frozen layer effects reconstructs Promotion100','MaxAbsError':e2,'PASS':e2<1e-10})
    exact.append({'Check':'Top-5 drawdowns extracted from frozen 4F Promotion100 only','MaxAbsError':0.0,'PASS':len(dd)==5})
    return b,dd,daily,summ,fam,layers,triggers,pd.DataFrame(exact)


def render_r11_topdd_daily_anatomy(px_bt, rf_bt, bt_start, bt_end):
    st.header('🩻 R11 — 4F Promotion100 Top-DD Daily Anatomy')
    st.caption('R10 follow-up: realized Top-5 drawdownsをpeak→troughの日次で完全分解。診断のみ、ルール生成・最適化なし。DEV cutoff 2026-07-31。')
    st.info('固定仕様はR10/R9bから変更なし。MOM/MR/VIX/TEL、Adaptive Safe Haven、A Gate、VIX30 Brake、Turbo75、Attack selector、Promotion100をそのまま使用します。')
    p=st.progress(0,text='R11 0/8 — frozen R10 inputsを再構築中…')
    b,dd,daily,summ,fam,layers,triggers,exact=_r11_build_tables(px_bt,rf_bt,bt_start,bt_end)
    p.progress(25,text='R11 2/8 — Top-5 drawdown pathsを抽出済み…')
    # Worst-day detail for quick inspection.
    worst=daily.sort_values('4F_Return').groupby('DDRank',as_index=False).head(5).sort_values(['DDRank','4F_Return']) if len(daily) else pd.DataFrame()
    p.progress(45,text='R11 4/8 — family/layer contributionを集計済み…')
