# ================================================================
# R11b — 4F Promotion100 Top-DD Daily Anatomy Exactness Fix
# IMPLEMENTATION BUGFIX ONLY. No research rule/parameter/weight changes.
# Fix: R11 mixed two valid attribution origins:
#   (A) post-Adaptive-Safe-Haven 4F Base family contribution, and
#   (B) pre-Safe-Haven Core -> Safe Haven -> Gate -> Brake -> Turbo -> Selector -> Promotion bridge.
# Therefore adding *all* layer effects to the already-post-Safe-Haven 4F Base double-counted
# Adaptive Safe Haven. R11b keeps both views explicit and tests each with its proper origin.
# DEV cutoff = 2026-07-31.
# ================================================================

def _r11b_build_tables(px_bt, rf_bt, start, end):
    b = _r10_build(px_bt, rf_bt, start, end)
    f = b['finals'].copy()
    dd = _r10_drawdown_cycles(f['4F Promotion100'], 5)
    daily_rows=[]; summary=[]; fam_rows=[]; layer_rows=[]; trigger_rows=[]
    state_cols=[c for c in ['A Gate','VIX30 Brake','allow_L2','Turbo','Choose TECL','Promotion100'] if c in b['states'].columns]

    # Two exact additive views, intentionally kept separate:
    # 1) Family view reconstructs post-Safe-Haven Frozen 4F Base.
    # 2) Sequential bridge view starts at pre-Safe-Haven Core and includes every frozen layer.
    #    If starting from post-Safe-Haven 4F Base, Adaptive Safe Haven MUST be excluded.
    bridge_from_base_cols=[c for c in b['fourf_layers'].columns if c != 'Adaptive Safe Haven']

    for _,r in dd.iterrows():
        rank=int(r['Rank']); a=pd.Timestamp(r['PeakDate']); z=pd.Timestamp(r['TroughDate'])
        ix=f.loc[a:z].index
        if len(ix)==0: continue
        x=f.loc[ix,'4F Promotion100'].astype(float)
        v=f.loc[ix,'Frozen v3.45 Final'].astype(float)
        base=f.loc[ix,'4F Base'].astype(float)
        core=b['fourf_core'].reindex(ix).astype(float)
        eq=(1+x).cumprod(); pathdd=eq/eq.cummax()-1
        c4=b['fourf_family_contrib'].reindex(ix).fillna(0.0)
        l4=b['fourf_layers'].reindex(ix).fillna(0.0)
        st=b['states'].reindex(ix)

        for dt in ix:
            row={'DDRank':rank,'PeakDate':a,'TroughDate':z,'Date':dt,
                 '4F_Return':float(x.loc[dt]),'v345_Return':float(v.loc[dt]),
                 'v345_minus_4F':float(v.loc[dt]-x.loc[dt]),
                 '4F_Base_Return_PostSafeHaven':float(base.loc[dt]),
                 '4F_Core_Return_PreSafeHaven':float(core.loc[dt]),
                 '4F_CumReturn_FromPeak':float((1+x.loc[:dt]).prod()-1),
                 '4F_PathDD':float(pathdd.loc[dt])}
            for c in c4.columns: row['Family_'+c]=float(c4.loc[dt,c])
            for c in l4.columns: row['Layer_'+c]=float(l4.loc[dt,c])
            row['Recon_FromPostSafeHavenBase']=float(base.loc[dt] + l4.loc[dt,bridge_from_base_cols].sum())
            row['Recon_FromPreSafeHavenCore']=float(core.loc[dt] + l4.loc[dt].sum())
            row['ReconError_FromPostSafeHavenBase']=float(row['Recon_FromPostSafeHavenBase']-x.loc[dt])
            row['ReconError_FromPreSafeHavenCore']=float(row['Recon_FromPreSafeHavenCore']-x.loc[dt])
            for c in state_cols: row['State_'+c]=bool(st.loc[dt,c]) if pd.notna(st.loc[dt,c]) else False
            daily_rows.append(row)

        neg=x[x<0].sort_values()
        total_loss=float((-x.clip(upper=0)).sum())
        def loss_share(n):
            if total_loss<=0 or len(neg)==0: return np.nan
            return float((-neg.head(n)).sum()/total_loss)
        summary.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'RecoveryDate':r.get('RecoveryDate',pd.NaT),
                        'TradingDays':len(ix),'4F_Return':float((1+x).prod()-1),'4F_MaxDD':float(pathdd.min()),
                        'v345_Return_SameWindow':float((1+v).prod()-1),
                        'Worst1Day':float(x.min()),'Worst1Date':x.idxmin(),
                        'LossShareWorst1':loss_share(1),'LossShareWorst3':loss_share(3),'LossShareWorst5':loss_share(5),
                        'NegativeDays':int((x<0).sum()),'PositiveDays':int((x>0).sum())})

        for c in c4.columns:
            fam_rows.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'Family':c,
                             'SumDailyContribution':float(c4[c].sum()),
                             'WorstDailyContribution':float(c4[c].min()),'WorstDate':c4[c].idxmin()})
        for c in l4.columns:
            layer_rows.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'Layer':c,
                               'BridgeOrigin':'Pre-Safe-Haven Core' if c=='Adaptive Safe Haven' else 'Sequential frozen stage',
                               'IncludedWhenStartingFrom4FBase':bool(c!='Adaptive Safe Haven'),
                               'SumDailyEffect':float(l4[c].sum()),
                               'WorstDailyEffect':float(l4[c].min()),'WorstDate':l4[c].idxmin()})
        for c in state_cols:
            ss=st[c].fillna(False).astype(bool)
            on=ss[ss].index
            trigger_rows.append({'DDRank':rank,'PeakDate':a,'TroughDate':z,'State':c,
                                 'OnDays':int(ss.sum()),'OnShare':float(ss.mean()),
                                 'FirstOnDate':on[0] if len(on) else pd.NaT,
                                 'DaysFromPeakToFirstOn':int(ix.get_loc(on[0])) if len(on) else np.nan})

    daily=pd.DataFrame(daily_rows); summ=pd.DataFrame(summary); fam=pd.DataFrame(fam_rows); layers=pd.DataFrame(layer_rows); triggers=pd.DataFrame(trigger_rows)

    # Exactness with the correct attribution origin for each view.
    idx=f.index
    fam_sum=b['fourf_family_contrib'].reindex(idx).sum(axis=1)
    base=f['4F Base'].reindex(idx)
    core=b['fourf_core'].reindex(idx)
    final=f['4F Promotion100'].reindex(idx)
    layer_all=b['fourf_layers'].reindex(idx)
    layer_postbase=layer_all[bridge_from_base_cols].sum(axis=1)
    layer_all_sum=layer_all.sum(axis=1)

    e_family=float((fam_sum-base).abs().max())
    e_postbase=float((base+layer_postbase-final).abs().max())
    e_precore=float((core+layer_all_sum-final).abs().max())
    safehaven_identity=float(((core+layer_all['Adaptive Safe Haven'])-base).abs().max())
    exact=pd.DataFrame([
        {'Check':'4F family contribution reconstructs post-Safe-Haven 4F Base','AttributionOrigin':'Post-Safe-Haven 4F Base','MaxAbsError':e_family,'PASS':e_family<1e-10},
        {'Check':'4F Base + layers AFTER Safe Haven reconstructs Promotion100','AttributionOrigin':'Post-Safe-Haven 4F Base','MaxAbsError':e_postbase,'PASS':e_postbase<1e-10},
        {'Check':'Pre-Safe-Haven Core + ALL frozen layers reconstructs Promotion100','AttributionOrigin':'Pre-Safe-Haven Core','MaxAbsError':e_precore,'PASS':e_precore<1e-10},
        {'Check':'Pre-Safe-Haven Core + Adaptive Safe Haven equals 4F Base','AttributionOrigin':'Pre-Safe-Haven Core','MaxAbsError':safehaven_identity,'PASS':safehaven_identity<1e-10},
        {'Check':'Top-5 drawdowns extracted from frozen 4F Promotion100 only','AttributionOrigin':'Frozen final path','MaxAbsError':0.0,'PASS':len(dd)==5},
    ])
    return b,dd,daily,summ,fam,layers,triggers,exact


def render_r11b_topdd_daily_anatomy(px_bt, rf_bt, bt_start, bt_end):
    st.header('🧪 R11b — 4F Promotion100 Top-DD Daily Anatomy Exactness Fix')
