# ================================================================
# R12 — Tail-Risk Efficiency Frontier
#
# PRE-REGISTERED PURPOSE:
#   Compare the six already-frozen stages/finals on one common daily
#   return sample. This is measurement/ranking only, never optimization.
#
# Fixed competitors (no additions/substitutions):
#   Frozen 4F / A+Brake / Turbo75 / Attack75 / Promotion100 / v3.45.
# Fixed definitions:
#   ES q%       = arithmetic mean of the worst ceil(N*q) observed daily
#                 returns (non-parametric historical expected shortfall).
#   Worst k-day = minimum overlapping k-row compounded return, k=1/3/5.
#   Underwater  = equity below its prior running high.
#   Recovery    = trough through first subsequent recovery high; incomplete
#                 episodes remain explicitly marked unrecovered.
#   Depth×duration = abs(episode depth) * underwater trading days.
#
# No new parameter, threshold, weight, Brake, rescue, or post-hoc rule.
# DEV cutoff = 2026-07-31. User-run ZIP alone is official.
# ================================================================

_R12_CUTOFF = pd.Timestamp('2026-07-31')
_R12_ORDER = [
    'Frozen 4F', 'A+Brake', 'Turbo75', 'Attack75',
    'Promotion100', 'Frozen v3.45 Final',
]


def _r12_build_frozen_competitors(px_bt, rf_bt, start, end):
    r6, _, _, states, _, _, _, _, _ = _r6_build(px_bt, rf_bt, start, end)
    v345, _ = _r7_v345_close(px_bt, rf_bt, start, end)
    daily = pd.concat([
        r6['Frozen 4F EW'].rename('Frozen 4F'),
        r6['A+VIX30'].rename('A+Brake'),
        r6['Turbo75 TQQQ'].rename('Turbo75'),
        r6['Attack75 Selector'].rename('Attack75'),
        r6['Promotion100'].rename('Promotion100'),
        v345.rename('Frozen v3.45 Final'),
    ], axis=1).dropna().loc[:_R12_CUTOFF]
    if daily.empty:
        raise RuntimeError('R12 common daily sample is empty.')
    return daily[_R12_ORDER], states.reindex(daily.index)


def _r12_compounded_rolling(r, window):
    return (1.0 + r).rolling(window, min_periods=window).apply(np.prod, raw=True) - 1.0


def _r12_historical_es(r, q):
    x = pd.Series(r).dropna().sort_values()
    if x.empty:
        return np.nan, 0
    n = max(1, int(np.ceil(len(x) * float(q))))
    return float(x.iloc[:n].mean()), n


def _r12_drawdown_path(r):
    x = pd.Series(r).dropna().astype(float)
    wealth = (1.0 + x).cumprod()
    running_peak = wealth.cummax()
    dd = wealth / running_peak - 1.0
    return wealth, running_peak, dd


def _r12_underwater_episodes(name, r):
    wealth, _, dd = _r12_drawdown_path(r)
    idx = dd.index
    rows = []
    in_episode = False
    start_pos = None
    peak_pos = None

    for i, value in enumerate(dd.to_numpy(float)):
        underwater = bool(value < -1e-15)
        if underwater and not in_episode:
            in_episode = True
            start_pos = i
            peak_pos = max(0, i - 1)
        recovered = in_episode and not underwater
        is_last = i == len(dd) - 1
        if in_episode and (recovered or is_last):
            last_underwater_pos = i - 1 if recovered else i
            seg = dd.iloc[start_pos:last_underwater_pos + 1]
            trough_date = seg.idxmin()
            trough_pos = int(idx.get_loc(trough_date))
            recovery_date = idx[i] if recovered else pd.NaT
            underwater_days = int(last_underwater_pos - start_pos + 1)
            recovery_days = int(i - trough_pos) if recovered else np.nan
            depth = float(seg.min())
            area = float((-seg).sum())
            rows.append({
                'Strategy': name,
                'PeakDate': idx[peak_pos],
                'UnderwaterStart': idx[start_pos],
                'TroughDate': trough_date,
                'RecoveryDate': recovery_date,
                'Recovered': bool(recovered),
                'UnderwaterTradingDays': underwater_days,
                'TroughToRecoveryTradingDays': recovery_days,
                'CalendarDaysPeakToRecoveryOrCutoff': int((idx[i] - idx[peak_pos]).days),
                'Depth': depth,
                'DrawdownArea': area,
                'Depth_x_Duration': abs(depth) * underwater_days,
                'PeakWealth': float(wealth.iloc[peak_pos]),
                'TroughWealth': float(wealth.loc[trough_date]),
            })
            in_episode = False
    return pd.DataFrame(rows)


def _r12_metric_row(name, r, episodes):
    x = pd.Series(r).dropna().astype(float)
    canonical = _v325_metric_row(name, x)
    _, _, dd = _r12_drawdown_path(x)
    es1, n1 = _r12_historical_es(x, 0.01)
    es5, n5 = _r12_historical_es(x, 0.05)
    w1 = float(x.min())
    w3s = _r12_compounded_rolling(x, 3).dropna()
    w5s = _r12_compounded_rolling(x, 5).dropna()
    w3 = float(w3s.min()) if len(w3s) else np.nan
    w5 = float(w5s.min()) if len(w5s) else np.nan
    ulcer = float(np.sqrt(np.mean(np.square(dd.clip(upper=0.0)))))
    ep = episodes.loc[episodes['Strategy'].eq(name)].copy()
    complete = ep.loc[ep['Recovered']].copy() if len(ep) else ep
    underwater_days = int((dd < -1e-15).sum())
    max_depth_duration = float(ep['Depth_x_Duration'].max()) if len(ep) else 0.0
    max_area = float(ep['DrawdownArea'].max()) if len(ep) else 0.0
    cagr = float(canonical['CAGR'])

    def ratio(denom):
        return cagr / abs(float(denom)) if pd.notna(denom) and abs(float(denom)) > 0 else np.nan

    return {
        'Strategy': name,
        'Start': x.index.min(), 'End': x.index.max(), 'TradingDays': len(x),
        'CAGR': cagr, 'Vol': canonical['Vol'],
        'Daily MaxDD': canonical['Daily MaxDD'],
        'Monthly MaxDD': canonical['Monthly MaxDD'],
        'Sharpe0': canonical['Sharpe0'], 'Sortino0': canonical['Sortino0'],
        'Expected Shortfall 1%': es1, 'ES1 Observations': n1,
        'Expected Shortfall 5%': es5, 'ES5 Observations': n5,
        'Worst 1-day': w1, 'Worst 1-day End': x.idxmin(),
        'Worst 3-day': w3, 'Worst 3-day End': w3s.idxmin() if len(w3s) else pd.NaT,
        'Worst 5-day': w5, 'Worst 5-day End': w5s.idxmin() if len(w5s) else pd.NaT,
        'Ulcer Index': ulcer,
        'Time Under Water Days': underwater_days,
        'Time Under Water Share': underwater_days / len(dd),
        'Drawdown Episodes': len(ep),
        'Unrecovered Episodes': int((~ep['Recovered']).sum()) if len(ep) else 0,
        'Max Time Under Water Days': int(ep['UnderwaterTradingDays'].max()) if len(ep) else 0,
        'Mean Time Under Water Days': float(ep['UnderwaterTradingDays'].mean()) if len(ep) else 0.0,
        'Max Trough-to-Recovery Days': float(complete['TroughToRecoveryTradingDays'].max()) if len(complete) else np.nan,
        'Mean Trough-to-Recovery Days': float(complete['TroughToRecoveryTradingDays'].mean()) if len(complete) else np.nan,
        'Max Drawdown Area': max_area,
        'Max Depth x Duration': max_depth_duration,
        'CAGR / abs(ES1)': ratio(es1),
        'CAGR / abs(ES5)': ratio(es5),
        'CAGR / abs(Worst5D)': ratio(w5),
        'CAGR / Ulcer': ratio(ulcer),
        'CAGR / MaxDepthDurationYear': ratio(max_depth_duration / 252.0),
    }


def _r12_exactness_audit(daily, metrics, episodes, r6, v345):
    source = pd.concat([
        r6['Frozen 4F EW'].rename('Frozen 4F'),
        r6['A+VIX30'].rename('A+Brake'),
        r6['Turbo75 TQQQ'].rename('Turbo75'),
        r6['Attack75 Selector'].rename('Attack75'),
        r6['Promotion100'].rename('Promotion100'),
        v345.rename('Frozen v3.45 Final'),
    ], axis=1).reindex(daily.index)[_R12_ORDER]
    max_source_error = float((daily - source).abs().max().max())
    monthly = (1.0 + daily).resample('ME').prod(min_count=1) - 1.0
    rebuilt = (1.0 + monthly).prod()
    direct = (1.0 + daily).prod()
    monthly_error = float((rebuilt - direct).abs().max())
    metric_dd = metrics.set_index('Strategy')['Daily MaxDD']
    episode_dd = episodes.groupby('Strategy')['Depth'].min().reindex(_R12_ORDER)
    episode_error = float((metric_dd - episode_dd).abs().max())
    checks = [
        ('Six frozen competitors present in pre-registered order', float(list(daily.columns) != _R12_ORDER), 0.0),
        ('R12 daily returns equal frozen source builders', max_source_error, 1e-12),
        ('Daily-to-monthly wealth reconstruction', monthly_error, 1e-12),
        ('Episode deepest depth equals canonical Daily MaxDD', episode_error, 1e-12),
        ('Common sample ends no later than DEV cutoff', float(daily.index.max() > _R12_CUTOFF), 0.0),
    ]
    return pd.DataFrame([
        {'Check': label, 'MaxAbsError': err, 'Tolerance': tol, 'PASS': bool(err <= tol)}
        for label, err, tol in checks
    ])


def _r12b_exactness_audit(daily, metrics, episodes, r6, v345):
    """R12b: implementation-only fix for scale-dependent wealth comparison."""
    source = pd.concat([
        r6['Frozen 4F EW'].rename('Frozen 4F'),
        r6['A+VIX30'].rename('A+Brake'),
        r6['Turbo75 TQQQ'].rename('Turbo75'),
        r6['Attack75 Selector'].rename('Attack75'),
        r6['Promotion100'].rename('Promotion100'),
        v345.rename('Frozen v3.45 Final'),
    ], axis=1).reindex(daily.index)[_R12_ORDER]
    max_source_error = float((daily - source).abs().max().max())

    monthly = (1.0 + daily).resample('ME').prod(min_count=1) - 1.0
    rebuilt = (1.0 + monthly).prod()
    direct = (1.0 + daily).prod()
    wealth_abs = (rebuilt - direct).abs()
    wealth_scale = pd.concat([rebuilt.abs(), direct.abs()], axis=1).max(axis=1).clip(lower=1.0)
    wealth_relative = wealth_abs / wealth_scale
    max_wealth_relative_error = float(wealth_relative.max())

    metric_dd = metrics.set_index('Strategy')['Daily MaxDD']
    episode_dd = episodes.groupby('Strategy')['Depth'].min().reindex(_R12_ORDER)
    episode_error = float((metric_dd - episode_dd).abs().max())
    checks = [
        ('Six frozen competitors present in pre-registered order', 'Binary mismatch', float(list(daily.columns) != _R12_ORDER), 0.0),
        ('R12b daily returns equal frozen source builders', 'Maximum absolute return error', max_source_error, 1e-12),
        ('Daily-to-monthly terminal wealth reconstruction', 'Maximum relative wealth error', max_wealth_relative_error, 1e-12),
        ('Episode deepest depth equals canonical Daily MaxDD', 'Maximum absolute drawdown error', episode_error, 1e-12),
        ('Common sample ends no later than DEV cutoff', 'Binary mismatch', float(daily.index.max() > _R12_CUTOFF), 0.0),
    ]
    out = pd.DataFrame([
        {'Check': label, 'ErrorMetric': metric, 'Error': err, 'Tolerance': tol, 'PASS': bool(err <= tol)}
        for label, metric, err, tol in checks
    ])
    out.attrs['wealth_absolute_errors'] = wealth_abs
    out.attrs['wealth_relative_errors'] = wealth_relative
    return out


def _render_r12_tail_risk_efficiency_frontier(px_bt, rf_bt, bt_start, bt_end, exactness_fix=False):
    version = 'R12b' if exactness_fix else 'R12'
    if exactness_fix:
        st.header('🧪 R12b — Tail-Risk Efficiency Frontier Exactness Fix')
        st.caption('R12の全戦略・指標・結果を固定したまま、terminal wealth再構成監査をscale-aware relative toleranceへ修正します。')
        st.warning('R12の唯一のFAILは長期複利wealthに対する絶対許容値1e-12のscale依存でした。R12bは監査式のみのimplementation bugfixで、日次リターン・戦略ロジック・tail指標は変更しません。')
    else:
        st.header('📉 R12 — Tail-Risk Efficiency Frontier')
        st.caption('R11b後に事前固定した6戦略のtail-risk比較。新しいルール・threshold・weight・Brakeは探索しません。')
    st.info('Production Control = Frozen 4F。Moderate = Attack75。Balanced High-Return = Promotion100。Crash comparator = Frozen v3.45 Final。DEV cutoff 2026-07-31。結果を見た救済変更は禁止。')
