# ================================================================
# R13 — 4F Dynamic Risk Weight (21D Inverse-Vol)
# PRE-REGISTERED ONE-SHOT CHALLENGER.
#
# Control:
#   Frozen 4F EW = MOM / MR / VIX / TEL-DM, 25% each.
# Challenger:
#   For each month M, estimate each Family's sample volatility from the
#   immediately preceding 21 completed trading-return rows. Target weight is
#   proportional to 1/Vol and becomes effective on M's first common return row.
#   Hold through month M with natural drift and reset only next month.
#   Return convention remains the R6/R12b common adjusted Close-to-Close basis.
#
# No cap, floor, threshold, alternative lookback, weight sweep, leverage,
# Brake, or post-hoc rescue.  21D is inherited from prior Managed Vol work.
# DEV cutoff = 2026-07-31.  User-run ZIP is the only official result.
# ================================================================

_R13_CUTOFF = pd.Timestamp("2026-07-31")
_R13_FAMILIES = ["MOM", "MR", "VIX", "TEL-DM"]
_R13_CONTROL = "Frozen 4F EW"
_R13_CHALLENGER = "4F Dynamic Risk Weight"


def _r13_inverse_vol_targets(family_daily):
    x = family_daily[_R13_FAMILIES].dropna().astype(float).sort_index().loc[:_R13_CUTOFF]
    rows = []
    for period, g in x.groupby(x.index.to_period("M")):
        rebalance_date = pd.Timestamp(g.index[0])
        prior = x.loc[x.index < rebalance_date].tail(21)
        if len(prior) != 21:
            continue
        vol = prior.std(ddof=1) * np.sqrt(252.0)
        if (not np.isfinite(vol.to_numpy(float)).all()) or bool((vol <= 1e-12).any()):
            continue
        inv = 1.0 / vol
        target = inv / inv.sum()
        risk_proxy = target * vol
        risk_budget = risk_proxy / risk_proxy.sum()
        row = {
            "Month": period,
            "SignalThrough": pd.Timestamp(prior.index[-1]),
            "RebalanceDate": rebalance_date,
            "LookbackObservations": int(len(prior)),
        }
        for family in _R13_FAMILIES:
            row[family] = float(target[family])
            row[f"Vol21_{family}"] = float(vol[family])
            row[f"ExAnteRiskBudget_{family}"] = float(risk_budget[family])
        row["WeightSum"] = float(target.sum())
        row["RiskBudgetDispersion"] = float(risk_budget.max() - risk_budget.min())
        rows.append(row)
    audit = pd.DataFrame(rows)
    if audit.empty:
        return pd.DataFrame(), audit
    targets = audit.set_index("Month")[_R13_FAMILIES].copy()
    targets.index = pd.PeriodIndex(targets.index, freq="M")
    return targets, audit


def _r13_family_contributions(family_daily, weight_log, label):
    if weight_log is None or weight_log.empty:
        return pd.DataFrame()
    w = weight_log.copy()
    w["Date"] = pd.to_datetime(w["Date"])
    w = w.set_index("Date")
    f = family_daily[_R13_FAMILIES].reindex(w.index).astype(float)
    out = pd.DataFrame(index=w.index)
    for family in _R13_FAMILIES:
        out[family] = w[f"PreReturnWeight_{family}"].astype(float) * f[family]
    out["ReconstructedReturn"] = out[_R13_FAMILIES].sum(axis=1)
    out.insert(0, "Strategy", label)
    return out


def _r13_weight_summary(target_audit, turnover):
    rows = []
    for family in _R13_FAMILIES:
        s = target_audit[family].dropna().astype(float)
        rows.append({
            "Family": family, "Months": len(s), "MeanWeight": s.mean(),
            "MinWeight": s.min(), "P10Weight": s.quantile(.10),
            "MedianWeight": s.median(), "P90Weight": s.quantile(.90),
            "MaxWeight": s.max(),
        })
    if len(turnover):
        rows.append({
            "Family": "PORTFOLIO TURNOVER", "Months": len(turnover),
            "MeanWeight": turnover["OneWayTurnover"].mean(),
            "MinWeight": turnover["OneWayTurnover"].min(),
            "P10Weight": turnover["OneWayTurnover"].quantile(.10),
            "MedianWeight": turnover["OneWayTurnover"].median(),
            "P90Weight": turnover["OneWayTurnover"].quantile(.90),
            "MaxWeight": turnover["OneWayTurnover"].max(),
        })
    return pd.DataFrame(rows)


def _r13_fixed_eras(daily):
    eras = [
        ("2012-2015", "2012-01-01", "2015-12-31"),
        ("2016-2019", "2016-01-01", "2019-12-31"),
        ("2020-2022", "2020-01-01", "2022-12-31"),
        ("2023-DEV", "2023-01-01", "2026-07-31"),
    ]
    rows = []
    for label, start, end in eras:
        g = daily.loc[start:end].dropna()
        if len(g) < 20:
            continue
        row = {"Era": label, "Start": g.index.min(), "End": g.index.max(), "Days": len(g)}
        for name in daily.columns:
            m = _v325_metric_row(name, g[name])
            for metric in ["CAGR", "Vol", "Daily MaxDD", "Sharpe0", "Sortino0"]:
                row[f"{name}_{metric}"] = m[metric]
        row["Dynamic_minus_Control_CAGR"] = row[f"{_R13_CHALLENGER}_CAGR"] - row[f"{_R13_CONTROL}_CAGR"]
        rows.append(row)
    return pd.DataFrame(rows)


def _r13_tel_episode_contribution(control_contrib, dynamic_contrib):
    windows = [
        ("COVID", "2020-02-01", "2020-04-30"),
        ("2022 rate shock", "2022-01-01", "2022-12-31"),
    ]
    rows = []
    for label, start, end in windows:
        for name, contrib in [(_R13_CONTROL, control_contrib), (_R13_CHALLENGER, dynamic_contrib)]:
            g = contrib.loc[start:end] if len(contrib) else pd.DataFrame()
            row = {"Episode": label, "Strategy": name, "Days": len(g)}
            for family in _R13_FAMILIES:
                row[f"SumDailyContribution_{family}"] = float(g[family].sum()) if len(g) else np.nan
            row["SumDailyPortfolioReturn"] = float(g["ReconstructedReturn"].sum()) if len(g) else np.nan
            rows.append(row)
    return pd.DataFrame(rows)


def _r13_exactness(r6_control, daily, targets, target_audit, dynamic_contrib, control_rebuilt):
    source = r6_control.reindex(daily.index)
    control_error = float((daily[_R13_CONTROL] - source).abs().max())
    ew_rebuild_error = float((control_rebuilt.reindex(daily.index) - source).abs().max())
    dynamic_error = float((
        dynamic_contrib["ReconstructedReturn"].reindex(daily.index)
        - daily[_R13_CHALLENGER]
    ).abs().max())
    weight_error = float((targets.sum(axis=1) - 1.0).abs().max())
    risk_budget_error = float(target_audit["RiskBudgetDispersion"].abs().max())
    lookahead_bad = int((
        pd.to_datetime(target_audit["SignalThrough"])
        >= pd.to_datetime(target_audit["RebalanceDate"])
    ).sum())
    lookback_bad = int((target_audit["LookbackObservations"] != 21).sum())
    cutoff_bad = int(daily.index.max() > _R13_CUTOFF)
    return pd.DataFrame([
        {"Check": "Control equals frozen R6 4F EW", "Error": control_error, "Tolerance": 1e-12, "PASS": control_error <= 1e-12},
        {"Check": "Independent EW rebuild equals frozen control", "Error": ew_rebuild_error, "Tolerance": 1e-12, "PASS": ew_rebuild_error <= 1e-12},
        {"Check": "Dynamic return equals daily family contribution sum", "Error": dynamic_error, "Tolerance": 1e-12, "PASS": dynamic_error <= 1e-12},
        {"Check": "Monthly target weights sum to one", "Error": weight_error, "Tolerance": 1e-12, "PASS": weight_error <= 1e-12},
        {"Check": "Inverse-vol ex-ante risk budgets are equal", "Error": risk_budget_error, "Tolerance": 1e-12, "PASS": risk_budget_error <= 1e-12},
        {"Check": "Signal date strictly precedes rebalance date", "Error": float(lookahead_bad), "Tolerance": 0.0, "PASS": lookahead_bad == 0},
        {"Check": "Every estimate uses exactly 21 completed observations", "Error": float(lookback_bad), "Tolerance": 0.0, "PASS": lookback_bad == 0},
        {"Check": "Common sample ends no later than DEV cutoff", "Error": float(cutoff_bad), "Tolerance": 0.0, "PASS": cutoff_bad == 0},
    ])


def render_r13_4f_dynamic_risk_weight(px_bt, rf_bt, bt_start, bt_end):
    import io, zipfile
    st.header("⚖️ R13 — 4F Dynamic Risk Weight")
    st.caption("Frozen 4F EWをProduction Controlとして維持し、21D Inverse-Volの1本だけを事前固定検証します。")
    st.info(
        "Challenger: MOM / MR / VIX / TEL-DMの直前21営業日実現Volの逆数で翌月ウェイトを決定。"
        "R6/R12bと同じAdjusted Close→Close基準で月初の最初の共通return rowだけ更新し、"
        "月中は自然ドリフト。総ウェイト100%、レバレッジなし。"
    )
    st.warning(
        "上限・下限・threshold・別lookback・weight sweep・Brake・DD後のTEL削減は行いません。"
        "Attack75 / Promotion100への適用は、本検証の結果を見る前には行いません。DEV cutoff=2026-07-31。"
    )
    if not st.button("R13 Dynamic Risk Weightを実行", type="primary", use_container_width=True, key="run_r13_dynamic_risk"):
        return

    p = st.progress(0, text="R13 0/10 — Frozen 4F familyを再構築中…")
    r6, family_daily, _, _, _, _, _, _, _ = _r6_build(px_bt, rf_bt, bt_start, bt_end)
    family_daily = family_daily[_R13_FAMILIES].dropna().loc[:_R13_CUTOFF]

    p.progress(14, text="R13 1/10 — 直前21営業日Volと翌月targetを計算中…")
    targets, target_audit = _r13_inverse_vol_targets(family_daily)
    if targets.empty:
        st.error("R13 target weightを構築できませんでした。")
        return
    ew_targets = pd.DataFrame(0.25, index=targets.index, columns=_R13_FAMILIES)

    p.progress(27, text="R13 3/10 — 月初リバランスと月中weight driftを再構築中…")
    dynamic, dynamic_wlog, dynamic_turn = _v403a_monthly_target_portfolio(
        family_daily, targets, _R13_CHALLENGER
    )
    control_rebuilt, control_wlog, control_turn = _v403a_monthly_target_portfolio(
        family_daily, ew_targets, _R13_CONTROL
    )
    daily = pd.concat([
        r6[_R13_CONTROL].rename(_R13_CONTROL), dynamic
    ], axis=1).dropna().loc[:_R13_CUTOFF]
    monthly = (1.0 + daily).resample("ME").prod(min_count=1) - 1.0

    p.progress(40, text="R13 4/10 — Tail Risk / underwater metricsを計算中…")
    episode_parts = [_r12_underwater_episodes(name, daily[name]) for name in daily.columns]
