# ================================================================
# R15 — All-4F Ninjutsu Suite Audit (MR fixation removed)
#
# One-shot extension after the official R14 result:
#   - MOM / MR / VIX / TEL-DM are all eligible on identical terms.
#   - No family is protected or fixed outside Bunshin Control.
#   - Technique definitions, timing, lookbacks and fallback are inherited.
#
# Techniques:
#   Bunshin      = all four families at 25% each
#   Gatekeeper   = EW among all Price12M > matched RF12M families;
#                  if none passes, fall back to four-family Bunshin
#   Tailwind     = strongest Price12M family at 100%
#   Nukimi       = strongest Prior11M-ex-latest family at 100%
#   Acceleration = strongest one-month change in Price12M at 100%
#   Kawarimi     = Price12M strongest 50% + weakest 50%
#
# Signal month-end t -> realized family return month t+1.
# No threshold / lookback / weight / Brake exploration.
# Historical DEV cutoff remains 2026-07-31.
# ================================================================

_R15_CUTOFF = pd.Timestamp("2026-07-31")
_R15_FAMILIES = ["MOM", "MR", "VIX", "TEL-DM"]


def _r15_all4_build(px_bt, rf_bt, bt_start, bt_end):
    base = _fofb1_monthly_dataset(
        px_bt, rf_bt, bt_start, bt_end, _R15_CUTOFF
    ).copy()
    p12 = base[[f"{f}_Price12M" for f in _R15_FAMILIES]].copy()
    p12.columns = _R15_FAMILIES
    prior = base[[f"{f}_Prior11M" for f in _R15_FAMILIES]].copy()
    prior.columns = _R15_FAMILIES
    gate = base[[f"{f}_GateExcess" for f in _R15_FAMILIES]].copy()
    gate.columns = _R15_FAMILIES
    acceleration = p12.diff()

    valid = (
        p12.notna().all(axis=1)
        & prior.notna().all(axis=1)
        & gate.notna().all(axis=1)
        & acceleration.notna().all(axis=1)
    )
    idx = base.index[valid]
    p12 = p12.reindex(idx)
    prior = prior.reindex(idx)
    gate = gate.reindex(idx)
    acceleration = acceleration.reindex(idx)

    def blank():
        return pd.DataFrame(0.0, index=idx, columns=_R15_FAMILIES)

    weights = {}

    w = blank()
    w.loc[:, :] = 0.25
    weights["Bunshin Control"] = w

    w = blank()
    for dt in idx:
        eligible = [f for f in _R15_FAMILIES if gate.loc[dt, f] > 0]
        if not eligible:
            eligible = list(_R15_FAMILIES)
        w.loc[dt, eligible] = 1.0 / len(eligible)
    weights["Gatekeeper"] = w

    tail_pick = p12.idxmax(axis=1)
    w = blank()
    for family in _R15_FAMILIES:
        w.loc[tail_pick.eq(family), family] = 1.0
    weights["Tailwind"] = w

    nukimi_pick = prior.idxmax(axis=1)
    w = blank()
    for family in _R15_FAMILIES:
        w.loc[nukimi_pick.eq(family), family] = 1.0
    weights["Nukimi"] = w

    accel_pick = acceleration.idxmax(axis=1)
    w = blank()
    for family in _R15_FAMILIES:
        w.loc[accel_pick.eq(family), family] = 1.0
    weights["Acceleration"] = w

    strongest = p12.idxmax(axis=1)
    weakest = p12.idxmin(axis=1)
    w = blank()
    for family in _R15_FAMILIES:
        w.loc[strongest.eq(family), family] += 0.50
        w.loc[weakest.eq(family), family] += 0.50
    weights["Kawarimi"] = w

    next_returns = base[_R15_FAMILIES].shift(-1).reindex(idx)
    return_month = pd.Series(
        base.index.to_series().shift(-1).values,
        index=base.index,
        name="ReturnMonth",
    ).reindex(idx)

    strategies = pd.DataFrame(index=idx)
    for name, target in weights.items():
        strategies[name] = (target * next_returns).sum(axis=1, min_count=1)

    common = strategies.notna().all(axis=1) & next_returns.notna().all(axis=1)
    strategies = strategies.loc[common]
    next_returns = next_returns.loc[common]
    return_month = return_month.loc[common]
    p12 = p12.loc[common]
    prior = prior.loc[common]
    gate = gate.loc[common]
    acceleration = acceleration.loc[common]
    for name in weights:
        weights[name] = weights[name].loc[common]

    audit = pd.DataFrame(index=strategies.index)
    audit.index.name = "SignalMonth"
    audit["ReturnMonth"] = return_month
    audit["TailwindPick"] = tail_pick.reindex(audit.index)
    audit["NukimiPick"] = nukimi_pick.reindex(audit.index)
    audit["AccelerationPick"] = accel_pick.reindex(audit.index)
    audit["KawarimiStrongest"] = strongest.reindex(audit.index)
    audit["KawarimiWeakest"] = weakest.reindex(audit.index)
    audit["GatekeeperEligibleCount"] = (gate > 0).sum(axis=1)
    return strategies, weights, next_returns, audit, p12, prior, gate, acceleration


def _r15_rule_expected_weights(audit, gate):
    idx = audit.index
    expected = {}

    w = pd.DataFrame(0.0, index=idx, columns=_R15_FAMILIES)
    for dt in idx:
        eligible = [f for f in _R15_FAMILIES if gate.loc[dt, f] > 0]
        if not eligible:
            eligible = list(_R15_FAMILIES)
        w.loc[dt, eligible] = 1.0 / len(eligible)
    expected["Gatekeeper"] = w

    for name, pick_column in [
        ("Tailwind", "TailwindPick"),
        ("Nukimi", "NukimiPick"),
        ("Acceleration", "AccelerationPick"),
    ]:
        w = pd.DataFrame(0.0, index=idx, columns=_R15_FAMILIES)
        for family in _R15_FAMILIES:
            w.loc[audit[pick_column].eq(family), family] = 1.0
        expected[name] = w

    w = pd.DataFrame(0.0, index=idx, columns=_R15_FAMILIES)
    for family in _R15_FAMILIES:
        w.loc[audit["KawarimiStrongest"].eq(family), family] += 0.50
        w.loc[audit["KawarimiWeakest"].eq(family), family] += 0.50
    expected["Kawarimi"] = w
    return expected


def _r15_exactness(strategies, weights, next_returns, audit, gate):
    all_weights = pd.concat(weights, names=["Strategy", "SignalMonth"])
    max_sum_error = float((all_weights.sum(axis=1) - 1.0).abs().max())

    control_expected = pd.DataFrame(
        0.25, index=weights["Bunshin Control"].index,
        columns=_R15_FAMILIES,
    )
    max_control_error = float(
        (weights["Bunshin Control"] - control_expected).abs().to_numpy().max()
    )

    rule_expected = _r15_rule_expected_weights(audit, gate)
    max_rule_error = 0.0
    for name, expected in rule_expected.items():
        max_rule_error = max(
            max_rule_error,
            float((weights[name] - expected).abs().to_numpy().max()),
        )

    max_return_error = 0.0
    for name in _R14_STRATEGIES:
        reconstructed = (weights[name] * next_returns).sum(axis=1, min_count=1)
        max_return_error = max(
            max_return_error,
            float((strategies[name] - reconstructed).abs().max()),
        )

    lag_ok = bool(
        (pd.to_datetime(audit["ReturnMonth"]) > pd.DatetimeIndex(audit.index)).all()
        and pd.to_datetime(audit["ReturnMonth"]).max() <= _R15_CUTOFF
    )
    rows = [
        ("Every target-weight row sums to 100%", max_sum_error <= 1e-12, max_sum_error),
        ("Bunshin control exactly equals Frozen 4F EW", max_control_error <= 1e-12, max_control_error),
        ("All five selector rules exactly match their frozen definitions", max_rule_error <= 1e-12, max_rule_error),
        ("Portfolio return reconstructs from weights × next returns", max_return_error <= 1e-12, max_return_error),
        ("Signal month t applies only to later return month t+1 within cutoff", lag_ok, float(lag_ok)),
    ]
    return pd.DataFrame([
        {"Check": check, "PASS": bool(ok), "MaxAbsError_or_Flag": value}
        for check, ok, value in rows
    ])


