# ================================================================
# R16 — 4F Meta-Dual-Momentum Exact Revalidation
#
# Exactness-first successor to legacy v4.01 and the official R14/R15 audits.
# Frozen family universe: MOM / MR / VIX / TEL-DM. No attack overlay.
#
# Signal at calendar month t:
#   1) For each family, compound the preceding 11 completed family months
#      (the inherited 12M-1M convention; current month excluded).
#   2) Compound matched RF over those same completed months.
#   3) Keep families with family momentum > matched RF.
#   4) Top1 selects the strongest eligible family at 100%.
#      Top2 equally weights the strongest two eligible families, or uses the
#      single eligible family at 100% when only one passes.
#   5) If none passes, allocate 100% to CASH.
#   6) Apply only in month t+1, rebalance at its first common return row,
#      then allow natural intra-month drift.
#
# No horizon / threshold / score / weight / Brake search.
# DEV cutoff = 2026-07-31. User-returned ZIP is the only official result.
# ================================================================

_R16_CUTOFF = pd.Timestamp("2026-07-31")
_R16_FAMILIES = ["MOM", "MR", "VIX", "TEL-DM"]
_R16_ASSETS = _R16_FAMILIES + ["CASH"]
_R16_CONTROL = "Frozen 4F EW"
_R16_TOP1 = "4F Meta-DM Top1"
_R16_TOP2 = "4F Meta-DM Top2"


def _r16_meta_dm_targets(family_daily, rf_rates, topn):
    x = family_daily[_R16_FAMILIES].dropna().astype(float).sort_index().loc[:_R16_CUTOFF]
    fm = (1.0 + x).groupby(x.index.to_period("M")).prod().sub(1.0)
    rfm = _v401_monthly_rf(x, rf_rates).reindex(fm.index)
    rows = []
    targets = []
    for i, signal_month in enumerate(fm.index):
        if i < 11:
            continue
        history = fm.iloc[i - 11:i]
        rf_history = rfm.iloc[i - 11:i]
        if history.isna().any().any() or rf_history.isna().any():
            continue
        score = (1.0 + history).prod() - 1.0
        rf_score = float((1.0 + rf_history).prod() - 1.0)
        eligible = score[score > rf_score].sort_values(ascending=False)
        chosen = list(eligible.index[:min(int(topn), len(eligible))])
        apply_month = signal_month + 1

        target = {asset: 0.0 for asset in _R16_ASSETS}
        if chosen:
            for family in chosen:
                target[family] = 1.0 / len(chosen)
            selected = "+".join(chosen)
        else:
            target["CASH"] = 1.0
            selected = "CASH"

        audit = {
            "Variant": f"Top{topn}",
            "SignalMonth": str(signal_month),
            "ScoreStartMonth": str(history.index[0]),
            "ScoreEndMonth": str(history.index[-1]),
            "ApplyMonth": str(apply_month),
            "CompletedScoreMonths": int(len(history)),
            "MatchedRF_12M1M": rf_score,
            "EligibleCount": int(len(eligible)),
            "Selected": selected,
        }
        for family in _R16_FAMILIES:
            audit[f"Score_{family}"] = float(score[family])
            audit[f"Eligible_{family}"] = bool(score[family] > rf_score)
        for asset in _R16_ASSETS:
            audit[f"Target_{asset}"] = float(target[asset])
        rows.append(audit)
        targets.append({"ApplyMonth": apply_month, **target})

    audit = pd.DataFrame(rows)
    if not targets:
        return pd.DataFrame(), audit, fm, rfm
    wt = pd.DataFrame(targets).set_index("ApplyMonth")[_R16_ASSETS]
    wt.index = pd.PeriodIndex(wt.index, freq="M")
    return wt, audit, fm, rfm


def _r16_cash_daily(index, rf_rates):
    return _v401_cash_daily(pd.DatetimeIndex(index), rf_rates).rename("CASH")


def _r16_monthly_target_portfolio(asset_daily, target_table, name):
    x = asset_daily[_R16_ASSETS].dropna().astype(float).sort_index().loc[:_R16_CUTOFF]
    wt = target_table.copy()
    if not isinstance(wt.index, pd.PeriodIndex):
        wt.index = pd.PeriodIndex(wt.index, freq="M")
    wt = wt[_R16_ASSETS].astype(float)
    returns = []
    weight_log = []
    turnover_rows = []
    previous_end = None
    for period, month_rows in x.groupby(x.index.to_period("M")):
        if period not in wt.index:
            continue
        target = wt.loc[period]
        if isinstance(target, pd.DataFrame):
            target = target.iloc[-1]
        target = target.reindex(_R16_ASSETS).astype(float)
        if target.isna().any() or target.sum() <= 0:
            continue
        target = target / target.sum()
        if previous_end is None:
            turnover = 0.0
        else:
            turnover = float(0.5 * (target - previous_end).abs().sum())
        turnover_rows.append({
            "Strategy": name,
            "Month": str(period),
            "RebalanceDate": month_rows.index[0],
            "OneWayTurnover": turnover,
            **{f"Target_{asset}": float(target[asset]) for asset in _R16_ASSETS},
        })

        wealth = target.copy()
        for date, asset_return in month_rows.iterrows():
            pre_weight = wealth / wealth.sum()
            portfolio_return = float((pre_weight * asset_return).sum())
            returns.append((date, portfolio_return))
            log_row = {"Strategy": name, "Date": date, "Month": str(period)}
            for asset in _R16_ASSETS:
                log_row[f"PreReturnWeight_{asset}"] = float(pre_weight[asset])
                log_row[f"Contribution_{asset}"] = float(pre_weight[asset] * asset_return[asset])
            log_row["ReconstructedReturn"] = float(sum(log_row[f"Contribution_{a}"] for a in _R16_ASSETS))
            weight_log.append(log_row)
            wealth = wealth * (1.0 + asset_return)
        previous_end = wealth / wealth.sum()

    series = pd.Series(dict(returns), name=name, dtype=float).sort_index()
    return series, pd.DataFrame(weight_log), pd.DataFrame(turnover_rows)


def _r16_rule_error(targets, audit, topn):
    max_error = 0.0
    for _, row in audit.iterrows():
        apply_month = pd.Period(row["ApplyMonth"], freq="M")
        if apply_month not in targets.index:
            return np.inf
        scores = pd.Series({f: float(row[f"Score_{f}"]) for f in _R16_FAMILIES})
        rf_score = float(row["MatchedRF_12M1M"])
        eligible = scores[scores > rf_score].sort_values(ascending=False)
        chosen = list(eligible.index[:min(int(topn), len(eligible))])
        expected = pd.Series(0.0, index=_R16_ASSETS)
        if chosen:
            expected.loc[chosen] = 1.0 / len(chosen)
        else:
            expected.loc["CASH"] = 1.0
        actual = targets.loc[apply_month, _R16_ASSETS]
        if isinstance(actual, pd.DataFrame):
            actual = actual.iloc[-1]
        max_error = max(max_error, float((actual.astype(float) - expected).abs().max()))
    return max_error


def _r16_reconstruction_error(strategy, weight_log):
    if weight_log.empty:
        return np.inf
    log = weight_log.copy()
    log["Date"] = pd.to_datetime(log["Date"])
    rebuilt = log.set_index("Date")["ReconstructedReturn"].sort_index()
    return float((strategy.reindex(rebuilt.index) - rebuilt).abs().max())


def _r16_exactness(
    r6_control, control_rebuilt, top1, top2,
    targets1, targets2, audit1, audit2, log1, log2, daily,
):
    control_error = float((r6_control.reindex(daily.index) - control_rebuilt.reindex(daily.index)).abs().max())
    target_error = max(
        float((targets1.sum(axis=1) - 1.0).abs().max()),
        float((targets2.sum(axis=1) - 1.0).abs().max()),
    )
    rule_error = max(
        _r16_rule_error(targets1, audit1, 1),
        _r16_rule_error(targets2, audit2, 2),
    )
    reconstruction_error = max(
        _r16_reconstruction_error(top1, log1),
        _r16_reconstruction_error(top2, log2),
    )
    timing_bad = 0
    for audit in [audit1, audit2]:
        signal = pd.PeriodIndex(audit["SignalMonth"], freq="M")
        score_end = pd.PeriodIndex(audit["ScoreEndMonth"], freq="M")
        apply = pd.PeriodIndex(audit["ApplyMonth"], freq="M")
        timing_bad += int((score_end >= signal).sum())
        timing_bad += int((signal >= apply).sum())
        timing_bad += int((audit["CompletedScoreMonths"] != 11).sum())
    cutoff_bad = int(pd.DatetimeIndex(daily.index).max() > _R16_CUTOFF)
    return pd.DataFrame([
        {"Check": "Independent monthly-drift EW rebuild equals frozen R6 control", "Error": control_error, "Tolerance": 1e-12, "PASS": control_error <= 1e-12},
        {"Check": "Every Top1/Top2 target row sums to 100%", "Error": target_error, "Tolerance": 1e-12, "PASS": target_error <= 1e-12},
        {"Check": "Absolute gate, relative rank, TopN and CASH rules reconstruct exactly", "Error": rule_error, "Tolerance": 1e-12, "PASS": rule_error <= 1e-12},
        {"Check": "Top1/Top2 daily return equals contribution reconstruction", "Error": reconstruction_error, "Tolerance": 1e-12, "PASS": reconstruction_error <= 1e-12},
        {"Check": "11 completed score months end before signal; signal precedes apply month", "Error": float(timing_bad), "Tolerance": 0.0, "PASS": timing_bad == 0},
        {"Check": "Common sample ends no later than DEV cutoff", "Error": float(cutoff_bad), "Tolerance": 0.0, "PASS": cutoff_bad == 0},
    ])


def _r16_fixed_eras(daily):
    eras = [
        ("2012-2015", "2012-01-01", "2015-12-31"),
        ("2016-2019", "2016-01-01", "2019-12-31"),
        ("2020-2022", "2020-01-01", "2022-12-31"),
        ("2023-DEV", "2023-01-01", "2026-07-31"),
    ]
    rows = []
    for era, start, end in eras:
        q = daily.loc[start:end].dropna()
        if len(q) < 20:
            continue
        for name in daily.columns:
            rows.append({"Era": era, **_v325_metric_row(name, q[name])})
    return pd.DataFrame(rows)


def _r16_cost_sensitivity(daily, turnover_map):
    rows = []
    for name in daily.columns:
        turnover = turnover_map[name].copy()
        turnover["RebalanceDate"] = pd.to_datetime(turnover["RebalanceDate"])
        cost_base = turnover.set_index("RebalanceDate")["OneWayTurnover"].groupby(level=0).sum()
        for bps in [0, 10, 25, 50]:
            net = daily[name].copy()
            charges = cost_base.reindex(net.index).fillna(0.0) * (bps / 10000.0)
            net = net - charges
            row = _v325_metric_row(name, net)
            rows.append({
                "Strategy": name,
                "CostBpsPerOneWay": bps,
                "AnnualizedOneWayTurnover": float(turnover["OneWayTurnover"].mean() * 12.0),
                **{k: row[k] for k in ["CAGR", "Vol", "Daily MaxDD", "Monthly MaxDD", "Sharpe0", "Sortino0"]},
            })
    return pd.DataFrame(rows)


def _r16_selection_summary(audit1, audit2):
    rows = []
    for label, audit in [(_R16_TOP1, audit1), (_R16_TOP2, audit2)]:
        for asset in _R16_ASSETS:
            weight = audit[f"Target_{asset}"].astype(float)
            rows.append({
                "Strategy": label,
                "Asset": asset,
                "SignalMonths": len(audit),
                "MonthsSelected": int((weight > 0).sum()),
                "MeanTargetWeight": float(weight.mean()),
                "MaxTargetWeight": float(weight.max()),
            })
        rows.append({
            "Strategy": label,
            "Asset": "ELIGIBILITY",
            "SignalMonths": len(audit),
            "MonthsSelected": int((audit["EligibleCount"] > 0).sum()),
            "MeanTargetWeight": float(audit["EligibleCount"].mean()),
            "MaxTargetWeight": float(audit["EligibleCount"].max()),
        })
    return pd.DataFrame(rows)


