# ================================================================
# R17 — Bam Multi-Horizon FoF Falsification
#
# External, pre-published hypothesis from Bam's 2023-10-01 article.
# Frozen family universe and execution are inherited from R16.
# Each article challenger uses Top2 only; Top1 is deliberately excluded after
# R16 showed destructive concentration.  At signal month t, all component
# returns use completed family months ending at t-1:
#   Short    = 50% R1M + 30% R3M + 15% R6M +  5% R12M
#   Long     =  5% R1M + 15% R3M + 30% R6M + 50% R12M
#   Balanced = 25% R1M + 25% R3M + 25% R6M + 25% R12M
# The matched RF score uses the identical horizon formula. Eligible families
# must beat it; the best two are equally weighted, one eligible receives 100%,
# and no eligible family means CASH 100%. Signal t applies only in t+1.
# No horizon / coefficient / threshold / TopN / weight / Cash / Brake search.
# DEV cutoff = 2026-07-31. User-returned ZIP is the only official result.
# ================================================================

_R17_VARIANTS = {
    "Bam Short Top2": {1: 0.50, 3: 0.30, 6: 0.15, 12: 0.05},
    "Bam Long Top2": {1: 0.05, 3: 0.15, 6: 0.30, 12: 0.50},
    "Bam Balanced Top2": {1: 0.25, 3: 0.25, 6: 0.25, 12: 0.25},
}
_R17_NORMAL = "R16 Normal 12M-1M Top2"


def _r17_multihorizon_targets(family_monthly, rf_monthly, variant, coefficients):
    fm = family_monthly[_R16_FAMILIES].dropna().astype(float).sort_index()
    rfm = rf_monthly.reindex(fm.index).astype(float)
    rows, targets = [], []
    horizons = [1, 3, 6, 12]
    for i, signal_month in enumerate(fm.index):
        if i < 12:
            continue
        family_components = {}
        rf_components = {}
        valid = True
        for horizon in horizons:
            family_window = fm.iloc[i - horizon:i]
            rf_window = rfm.iloc[i - horizon:i]
            if len(family_window) != horizon or family_window.isna().any().any() or rf_window.isna().any():
                valid = False
                break
            family_components[horizon] = (1.0 + family_window).prod() - 1.0
            rf_components[horizon] = float((1.0 + rf_window).prod() - 1.0)
        if not valid:
            continue

        score = sum(float(coefficients[h]) * family_components[h] for h in horizons)
        rf_score = float(sum(float(coefficients[h]) * rf_components[h] for h in horizons))
        eligible = score[score > rf_score].sort_values(ascending=False, kind="mergesort")
        chosen = list(eligible.index[:2])
        apply_month = signal_month + 1
        target = {asset: 0.0 for asset in _R16_ASSETS}
        if chosen:
            for family in chosen:
                target[family] = 1.0 / len(chosen)
            selected = "+".join(chosen)
        else:
            target["CASH"] = 1.0
            selected = "CASH"

        audit = {
            "Variant": variant,
            "SignalMonth": str(signal_month),
            "Lookback12StartMonth": str(fm.index[i - 12]),
            "LookbackEndMonth": str(fm.index[i - 1]),
            "ApplyMonth": str(apply_month),
            "Completed12MMonths": 12,
            "MatchedRF_Composite": rf_score,
            "EligibleCount": int(len(eligible)),
            "Selected": selected,
        }
        for horizon in horizons:
            audit[f"Coefficient_{horizon}M"] = float(coefficients[horizon])
            audit[f"RFReturn_{horizon}M"] = float(rf_components[horizon])
        for family in _R16_FAMILIES:
            for horizon in horizons:
                audit[f"Return_{horizon}M_{family}"] = float(family_components[horizon][family])
            audit[f"Score_{family}"] = float(score[family])
            audit[f"Eligible_{family}"] = bool(score[family] > rf_score)
        for asset in _R16_ASSETS:
            audit[f"Target_{asset}"] = float(target[asset])
        rows.append(audit)
        targets.append({"ApplyMonth": apply_month, **target})

    audit = pd.DataFrame(rows)
    if not targets:
        return pd.DataFrame(), audit
    wt = pd.DataFrame(targets).set_index("ApplyMonth")[_R16_ASSETS]
    wt.index = pd.PeriodIndex(wt.index, freq="M")
    return wt, audit


def _r17_rule_error(targets, audit, coefficients):
    max_error = 0.0
    for _, row in audit.iterrows():
        scores = pd.Series(index=_R16_FAMILIES, dtype=float)
        for family in _R16_FAMILIES:
            scores[family] = sum(
                float(coefficients[h]) * float(row[f"Return_{h}M_{family}"])
                for h in [1, 3, 6, 12]
            )
            max_error = max(max_error, abs(float(row[f"Score_{family}"]) - float(scores[family])))
        rf_score = sum(
            float(coefficients[h]) * float(row[f"RFReturn_{h}M"])
            for h in [1, 3, 6, 12]
        )
        max_error = max(max_error, abs(float(row["MatchedRF_Composite"]) - rf_score))
        eligible = scores[scores > rf_score].sort_values(ascending=False, kind="mergesort")
        chosen = list(eligible.index[:2])
        expected = pd.Series(0.0, index=_R16_ASSETS)
        if chosen:
            expected.loc[chosen] = 1.0 / len(chosen)
        else:
            expected.loc["CASH"] = 1.0
        apply_month = pd.Period(row["ApplyMonth"], freq="M")
        actual = targets.loc[apply_month, _R16_ASSETS]
        if isinstance(actual, pd.DataFrame):
            actual = actual.iloc[-1]
        max_error = max(max_error, float((actual.astype(float) - expected).abs().max()))
    return max_error


def _r17_selection_summary(audits):
    rows = []
    for variant, audit in audits.items():
        for asset in _R16_ASSETS:
            weight = audit[f"Target_{asset}"].astype(float)
            rows.append({
                "Strategy": variant,
                "Asset": asset,
                "SignalMonths": len(audit),
                "MonthsSelected": int((weight > 0).sum()),
                "MeanTargetWeight": float(weight.mean()),
                "MaxTargetWeight": float(weight.max()),
            })
        rows.append({
            "Strategy": variant,
            "Asset": "ELIGIBILITY",
            "SignalMonths": len(audit),
            "MonthsSelected": int((audit["EligibleCount"] > 0).sum()),
            "MeanTargetWeight": float(audit["EligibleCount"].mean()),
            "MaxTargetWeight": float(audit["EligibleCount"].max()),
        })
    return pd.DataFrame(rows)


def _r17_exactness(r6_control, control_rebuilt, daily, targets, audits, portfolios, logs):
    control_error = float(
        (r6_control.reindex(daily.index) - control_rebuilt.reindex(daily.index)).abs().max()
    )
    target_error = max(float((table.sum(axis=1) - 1.0).abs().max()) for table in targets.values())
    coefficient_error = 0.0
    for variant, coefficients in _R17_VARIANTS.items():
        audit = audits[variant]
        coefficient_error = max(
            coefficient_error,
            abs(sum(coefficients.values()) - 1.0),
            *[
                float((audit[f"Coefficient_{h}M"] - coefficients[h]).abs().max())
                for h in [1, 3, 6, 12]
            ],
        )
    rule_error = max(
        _r17_rule_error(targets[variant], audits[variant], coefficients)
        for variant, coefficients in _R17_VARIANTS.items()
    )
    normal_rule_error = _r16_rule_error(targets[_R17_NORMAL], audits[_R17_NORMAL], 2)
    reconstruction_error = max(
        _r16_reconstruction_error(portfolios[name], logs[name]) for name in portfolios
    )
    timing_bad = 0
    for variant in _R17_VARIANTS:
        audit = audits[variant]
        signal = pd.PeriodIndex(audit["SignalMonth"], freq="M")
        start = pd.PeriodIndex(audit["Lookback12StartMonth"], freq="M")
        end = pd.PeriodIndex(audit["LookbackEndMonth"], freq="M")
        apply = pd.PeriodIndex(audit["ApplyMonth"], freq="M")
        timing_bad += int((start > end).sum() + (end >= signal).sum() + (signal >= apply).sum())
        timing_bad += int((audit["Completed12MMonths"] != 12).sum())
    cutoff_bad = int(pd.DatetimeIndex(daily.index).max() > _R16_CUTOFF)
    return pd.DataFrame([
        {"Check": "Independent monthly-drift EW rebuild equals Frozen 4F EW", "Error": control_error, "Tolerance": 1e-12, "PASS": control_error <= 1e-12},
        {"Check": "Every Normal/Short/Long/Balanced Top2 target sums to 100%", "Error": target_error, "Tolerance": 1e-12, "PASS": target_error <= 1e-12},
        {"Check": "Published Bam coefficients are exact and each set sums to 100%", "Error": coefficient_error, "Tolerance": 1e-12, "PASS": coefficient_error <= 1e-12},
        {"Check": "Multi-horizon score, matched RF gate and Top2 rule reconstruct exactly", "Error": rule_error, "Tolerance": 1e-12, "PASS": rule_error <= 1e-12},
        {"Check": "Inherited R16 Normal 12M-1M Top2 rule reconstructs exactly", "Error": normal_rule_error, "Tolerance": 1e-12, "PASS": normal_rule_error <= 1e-12},
        {"Check": "All challenger daily returns equal contribution reconstruction", "Error": reconstruction_error, "Tolerance": 1e-12, "PASS": reconstruction_error <= 1e-12},
        {"Check": "12 completed months end before signal; signal precedes apply month; DEV cutoff held", "Error": float(timing_bad + cutoff_bad), "Tolerance": 0.0, "PASS": (timing_bad + cutoff_bad) == 0},
    ])


