# ================================================================
# R18 — Four-Archetype Role Coverage Audit
#
# Primary-source architecture memo from Bam:
#   starting point = trend following;
#   four structural archetypes = Trend/MR x Long/Short;
#   leveraged-equity universe concentration is offset by combining systems
#   whose definitions produce low correlation;
#   Average5/Average7 = simple equal weight; MIX = fixed reweighting;
#   DM1-DM7 are selected again through Trend / Mean Reversion / Balance roles.
#
# R18 is descriptive only. It does NOT create a selector, challenger, dynamic
# weight, threshold, Brake, or post-hoc rescue. It tests the current exact
# Frozen 4F family NAVs (MOM/MR/VIX/TEL-DM), not the earlier NDL-R7 proxy mix.
#
# Fixed monthly factors:
#   MarketDirection_t = SPY monthly total price return at t.
#   PriorTrendSign_t  = +1 if SPY trailing 12M price return measured at t-1
#                       is > 0; otherwise -1.
#   TrendPayoff_t     = PriorTrendSign_t * MarketDirection_t.
# Regression: family_t = a + b_direction*MarketDirection_t
#                         + b_trend*TrendPayoff_t + residual_t.
# Quadrant uses zero only: b_direction >=0 => Long else Short;
#                          b_trend >=0 => Trend else Mean Reversion.
# HAC lag=3 is descriptive inference only. Rolling window=36 completed months.
# DEV cutoff=2026-07-31. Only the user-run ZIP is official.
# ================================================================

_R18_CONTROL = "Frozen 4F EW"
_R18_HAC_LAG = 3
_R18_ROLLING_MONTHS = 36


def _r18_ols_hac(frame, y_col, lag=_R18_HAC_LAG):
    cols = [y_col, "MarketDirection", "TrendPayoff"]
    q = frame[cols].dropna().astype(float)
    if len(q) < 12:
        return None
    y = q[y_col].to_numpy(dtype=float)
    x = np.column_stack([
        np.ones(len(q), dtype=float),
        q["MarketDirection"].to_numpy(dtype=float),
        q["TrendPayoff"].to_numpy(dtype=float),
    ])
    inv_xx = np.linalg.pinv(x.T @ x)
    beta = inv_xx @ x.T @ y
    residual = y - x @ beta
    meat = np.zeros((x.shape[1], x.shape[1]), dtype=float)
    for t in range(len(q)):
        xu = x[t] * residual[t]
        meat += np.outer(xu, xu)
    max_lag = min(int(lag), len(q) - 1)
    for ell in range(1, max_lag + 1):
        weight = 1.0 - ell / (max_lag + 1.0)
        cross = np.zeros_like(meat)
        for t in range(ell, len(q)):
            cross += np.outer(x[t] * residual[t], x[t - ell] * residual[t - ell])
        meat += weight * (cross + cross.T)
    cov = inv_xx @ meat @ inv_xx
    se = np.sqrt(np.maximum(np.diag(cov), 0.0))
    tstat = np.divide(beta, se, out=np.full_like(beta, np.nan), where=se > 0)
    sst = float(np.square(y - y.mean()).sum())
    r2 = 1.0 - float(np.square(residual).sum()) / sst if sst > 0 else np.nan
    normal_error = float(np.max(np.abs(x.T @ residual)))
    direction = "Long" if beta[1] >= 0 else "Short"
    behavior = "Trend" if beta[2] >= 0 else "Mean Reversion"
    return {
        "N": int(len(q)), "AlphaMonthly": float(beta[0]),
        "BetaDirection": float(beta[1]), "BetaTrend": float(beta[2]),
        "HAC3_t_Direction": float(tstat[1]), "HAC3_t_Trend": float(tstat[2]),
        "R2": float(r2), "DirectionAxis": direction, "BehaviorAxis": behavior,
        "Quadrant": f"{behavior} × {direction}", "NormalEquationMaxError": normal_error,
    }


def _r18_factor_frame(px_bt, family_daily):
    spy = px_bt["SPY"].dropna().astype(float).sort_index().loc[:_R16_CUTOFF]
    spy_me = spy.resample("ME").last()
    spy_me.index = spy_me.index.to_period("M")
    spy_return = spy_me.pct_change(fill_method=None).rename("MarketDirection")
    trailing12 = (spy_me / spy_me.shift(12) - 1.0)
    prior_trend = trailing12.shift(1)
    trend_sign = pd.Series(
        np.where(prior_trend > 0.0, 1.0, -1.0), index=prior_trend.index,
        name="PriorTrendSign",
    )
    trend_sign.loc[prior_trend.isna()] = np.nan
    factors = pd.concat([spy_return, prior_trend.rename("PriorSPY12M"), trend_sign], axis=1)
    factors["TrendPayoff"] = factors["PriorTrendSign"] * factors["MarketDirection"]
    factors["ReversalPayoff"] = -factors["TrendPayoff"]
    factors["FactorSignalMonth"] = [str(p - 1) for p in factors.index]

    family_monthly = (1.0 + family_daily[_R16_FAMILIES]).groupby(
        family_daily.index.to_period("M")
    ).prod().sub(1.0)
    common = family_monthly.join(factors, how="inner").dropna()
    common.index.name = "Month"
    return common, family_monthly, factors


def _r18_rolling_roles(common):
    rows = []
    for end_i in range(_R18_ROLLING_MONTHS - 1, len(common)):
        window = common.iloc[end_i - _R18_ROLLING_MONTHS + 1:end_i + 1]
        for family in _R16_FAMILIES:
            fit = _r18_ols_hac(window, family)
            if fit is None:
                continue
            rows.append({
                "Family": family, "WindowStart": str(window.index[0]),
                "WindowEnd": str(window.index[-1]), "Months": len(window), **fit,
            })
    detail = pd.DataFrame(rows)
    summary_rows = []
    for family, group in detail.groupby("Family"):
        full = _r18_ols_hac(common, family)
        summary_rows.append({
            "Family": family, "FullQuadrant": full["Quadrant"], "Windows": len(group),
            "SameQuadrantShare": float((group["Quadrant"] == full["Quadrant"]).mean()),
            "LongShare": float((group["DirectionAxis"] == "Long").mean()),
            "TrendShare": float((group["BehaviorAxis"] == "Trend").mean()),
            "MedianBetaDirection": float(group["BetaDirection"].median()),
            "MedianBetaTrend": float(group["BetaTrend"].median()),
        })
    return detail, pd.DataFrame(summary_rows)


def _r18_state_anatomy(common):
    q = common.copy()
    prior = np.where(q["PriorTrendSign"] > 0, "Prior Up", "Prior Down")
    current = np.where(q["MarketDirection"] >= 0, "Current Up", "Current Down")
    q["State"] = pd.Series(prior, index=q.index) + " → " + pd.Series(current, index=q.index)
    rows = []
    for state, group in q.groupby("State"):
        continuation = (
            ("Prior Up" in state and "Current Up" in state)
            or ("Prior Down" in state and "Current Down" in state)
        )
        for family in _R16_FAMILIES:
            r = group[family].dropna()
            rows.append({
                "State": state, "StructuralType": "Continuation" if continuation else "Reversal",
                "Family": family, "Months": len(r), "MeanMonthly": float(r.mean()),
                "MedianMonthly": float(r.median()), "PositiveShare": float((r > 0).mean()),
                "AnnualArithmetic": float(r.mean() * 12.0),
            })
    return pd.DataFrame(rows), q[["PriorSPY12M", "PriorTrendSign", "MarketDirection", "State"]]


def _r18_correlation_audit(common):
    matrices = {}
    matrices["All"] = common[_R16_FAMILIES].corr()
    matrices["Prior Up"] = common.loc[common["PriorTrendSign"] > 0, _R16_FAMILIES].corr()
    matrices["Prior Down"] = common.loc[common["PriorTrendSign"] < 0, _R16_FAMILIES].corr()
    long_rows = []
    for state, matrix in matrices.items():
        for left in _R16_FAMILIES:
            for right in _R16_FAMILIES:
                long_rows.append({"State": state, "Family1": left, "Family2": right, "Correlation": float(matrix.loc[left, right])})
    return matrices, pd.DataFrame(long_rows)


def _r18_risk_contribution(common):
    cov = common[_R16_FAMILIES].cov().to_numpy(dtype=float)
    w = np.repeat(0.25, len(_R16_FAMILIES))
    total = float(w @ cov @ w)
    component = w * (cov @ w)
    return pd.DataFrame({
        "Family": _R16_FAMILIES, "Weight": w, "ComponentVariance": component,
        "VarianceShare": component / total if total != 0 else np.nan,
    })


def _r18_stress_contribution(weight_log):
    windows = [
        ("2015 Jul-Sep", "2015-07-01", "2015-09-30"),
        ("2018 Q4", "2018-10-01", "2018-12-31"),
        ("COVID", "2020-02-01", "2020-04-30"),
        ("2022 Apr-Oct", "2022-04-01", "2022-10-31"),
        ("2023 Jul-Oct", "2023-07-01", "2023-10-31"),
        ("2025 Feb-Apr", "2025-02-01", "2025-04-30"),
    ]
    q = weight_log.copy()
    q["Date"] = pd.to_datetime(q["Date"])
    rows = []
    for label, start, end in windows:
        g = q[(q["Date"] >= pd.Timestamp(start)) & (q["Date"] <= pd.Timestamp(end))]
        if g.empty:
            continue
        total = float(g["ReconstructedReturn"].sum())
        for family in _R16_FAMILIES:
            contribution = float(g[f"Contribution_{family}"].sum())
            rows.append({
                "Stress": label, "Start": start, "End": end, "Family": family,
                "ArithmeticContribution": contribution,
                "ShareOfArithmeticPortfolioReturn": contribution / total if total != 0 else np.nan,
                "PortfolioArithmeticReturn": total,
            })
    return pd.DataFrame(rows)


def _r18_exactness(r6_control, rebuilt, common, family_daily, family_monthly, weight_log, roles):
    control_error = float((r6_control.reindex(rebuilt.index) - rebuilt).abs().max())
    rebuilt_monthly = (1.0 + family_daily[_R16_FAMILIES]).groupby(
        family_daily.index.to_period("M")
    ).prod().sub(1.0)
    monthly_error = float((family_monthly.reindex(rebuilt_monthly.index) - rebuilt_monthly).abs().max().max())
    factor_error = float((common["TrendPayoff"] - common["PriorTrendSign"] * common["MarketDirection"]).abs().max())
    signal_period = pd.PeriodIndex(common["FactorSignalMonth"], freq="M")
    timing_bad = int((signal_period != common.index - 1).sum())
    log = weight_log.copy()
    contribution_error = float(abs(
        log["ReconstructedReturn"]
        - sum(log[f"Contribution_{family}"] for family in _R16_FAMILIES)
        - log["Contribution_CASH"]
    ).max())
    normal_error = float(roles["NormalEquationMaxError"].max())
    quadrant_bad = int((roles["DirectionAxis"] != np.where(roles["BetaDirection"] >= 0, "Long", "Short")).sum())
    quadrant_bad += int((roles["BehaviorAxis"] != np.where(roles["BetaTrend"] >= 0, "Trend", "Mean Reversion")).sum())
    cutoff_bad = int(family_daily.index.max() > _R16_CUTOFF)
    return pd.DataFrame([
        {"Check": "Independent monthly-drift rebuild equals Frozen 4F EW", "Error": control_error, "Tolerance": 1e-12, "PASS": control_error <= 1e-12},
        {"Check": "Family monthly returns exactly compound current Frozen family daily returns", "Error": monthly_error, "Tolerance": 1e-12, "PASS": monthly_error <= 1e-12},
        {"Check": "TrendPayoff equals prior trend sign times current SPY return", "Error": factor_error, "Tolerance": 1e-12, "PASS": factor_error <= 1e-12},
        {"Check": "Every trend signal is measured at month t-1", "Error": float(timing_bad), "Tolerance": 0.0, "PASS": timing_bad == 0},
        {"Check": "Daily family contributions reconstruct control return", "Error": contribution_error, "Tolerance": 1e-12, "PASS": contribution_error <= 1e-12},
        {"Check": "OLS normal equations solved", "Error": normal_error, "Tolerance": 1e-10, "PASS": normal_error <= 1e-10},
        {"Check": "Quadrant labels use coefficient signs and zero boundary only", "Error": float(quadrant_bad), "Tolerance": 0.0, "PASS": quadrant_bad == 0},
        {"Check": "DEV cutoff held", "Error": float(cutoff_bad), "Tolerance": 0.0, "PASS": cutoff_bad == 0},
    ])


