# ================================================================
# R19 — TEL-Fixed 3F Ninjutsu Suite Audit
#
# Pre-registered mirror of R14 after official R18 role evidence:
#   - TEL-DM remains fixed at 25% as the time-varying Macro-Regime Diversifier.
#   - Only MOM / MR / VIX share the remaining 75%.
#   - Every technique, timing rule, lookback, fallback, and fixed weight is
#     inherited unchanged from R14. Only the identity of the fixed family is
#     changed from MR to TEL-DM.
#
# Techniques:
#   Bunshin      = MOM/MR/VIX 25% each + TEL-DM 25% (Frozen 4F EW)
#   Gatekeeper   = equal-weight eligible 3F where Price12M > RF12M;
#                  if none eligible, fall back to 3F Bunshin
#   Tailwind     = strongest Price12M family receives 75%
#   Nukimi       = strongest Prior11M-ex-latest family receives 75%
#   Acceleration = strongest one-month change in Price12M receives 75%
#   Kawarimi     = Price12M strongest 37.5% + weakest 37.5%
#
# Signal month-end t -> realized family return month t+1.
# No new technique / threshold / lookback / weight / Brake exploration.
# Historical DEV cutoff remains 2026-07-31. This is hypothesis-generating
# because TEL fixation was motivated by R18 on the same DEV sample.
# ================================================================

_R19_CUTOFF = pd.Timestamp("2026-07-31")
_R19_ALL_FAMILIES = ["MOM", "MR", "VIX", "TEL-DM"]
_R19_RANK_FAMILIES = ["MOM", "MR", "VIX"]
_R19_FIXED_FAMILY = "TEL-DM"


def _r19_tel_fixed_build(px_bt, rf_bt, bt_start, bt_end):
    base = _fofb1_monthly_dataset(
        px_bt, rf_bt, bt_start, bt_end, _R19_CUTOFF
    ).copy()
    p12 = base[[f"{f}_Price12M" for f in _R19_RANK_FAMILIES]].copy()
    p12.columns = _R19_RANK_FAMILIES
    prior = base[[f"{f}_Prior11M" for f in _R19_RANK_FAMILIES]].copy()
    prior.columns = _R19_RANK_FAMILIES
    gate = base[[f"{f}_GateExcess" for f in _R19_RANK_FAMILIES]].copy()
    gate.columns = _R19_RANK_FAMILIES
    acceleration = p12.diff()

    valid = (
        p12.notna().all(axis=1)
        & prior.notna().all(axis=1)
        & gate.notna().all(axis=1)
        & acceleration.notna().all(axis=1)
    )
    idx = base.index[valid]
    p12 = p12.reindex(idx)
    prior = prior.reindex(idx)
    gate = gate.reindex(idx)
    acceleration = acceleration.reindex(idx)

    def blank():
        w = pd.DataFrame(0.0, index=idx, columns=_R19_ALL_FAMILIES)
        w[_R19_FIXED_FAMILY] = 0.25
        return w

    weights = {}
    w = blank()
    w[_R19_RANK_FAMILIES] = 0.25
    weights["Bunshin Control"] = w

    w = blank()
    for dt in idx:
        eligible = [f for f in _R19_RANK_FAMILIES if gate.loc[dt, f] > 0]
        if not eligible:
            eligible = list(_R19_RANK_FAMILIES)
        w.loc[dt, eligible] = 0.75 / len(eligible)
    weights["Gatekeeper"] = w

    tail_pick = p12.idxmax(axis=1)
    w = blank()
    for family in _R19_RANK_FAMILIES:
        w.loc[tail_pick.eq(family), family] = 0.75
    weights["Tailwind"] = w

    nukimi_pick = prior.idxmax(axis=1)
    w = blank()
    for family in _R19_RANK_FAMILIES:
        w.loc[nukimi_pick.eq(family), family] = 0.75
    weights["Nukimi"] = w

    accel_pick = acceleration.idxmax(axis=1)
    w = blank()
    for family in _R19_RANK_FAMILIES:
        w.loc[accel_pick.eq(family), family] = 0.75
    weights["Acceleration"] = w

    strongest = p12.idxmax(axis=1)
    weakest = p12.idxmin(axis=1)
    w = blank()
    for family in _R19_RANK_FAMILIES:
        w.loc[strongest.eq(family), family] += 0.375
        w.loc[weakest.eq(family), family] += 0.375
    weights["Kawarimi"] = w

    next_returns = base[_R19_ALL_FAMILIES].shift(-1).reindex(idx)
    return_month = pd.Series(
        base.index.to_series().shift(-1).values,
        index=base.index, name="ReturnMonth",
    ).reindex(idx)
    strategies = pd.DataFrame(index=idx)
    for name, target in weights.items():
        strategies[name] = (target * next_returns).sum(axis=1, min_count=1)

    common = strategies.notna().all(axis=1) & next_returns.notna().all(axis=1)
    strategies = strategies.loc[common]
    next_returns = next_returns.loc[common]
    return_month = return_month.loc[common]
    p12, prior, gate, acceleration = (
        p12.loc[common], prior.loc[common], gate.loc[common], acceleration.loc[common]
    )
    for name in weights:
        weights[name] = weights[name].loc[common]

    audit = pd.DataFrame(index=strategies.index)
    audit.index.name = "SignalMonth"
    audit["ReturnMonth"] = return_month
    audit["TailwindPick"] = tail_pick.reindex(audit.index)
    audit["NukimiPick"] = nukimi_pick.reindex(audit.index)
    audit["AccelerationPick"] = accel_pick.reindex(audit.index)
    audit["KawarimiStrongest"] = strongest.reindex(audit.index)
    audit["KawarimiWeakest"] = weakest.reindex(audit.index)
    audit["GatekeeperEligibleCount"] = (gate > 0).sum(axis=1)
    return strategies, weights, next_returns, audit, p12, prior, gate, acceleration


def _r19_rule_expected_weights(audit, gate):
    idx = audit.index

    def blank():
        w = pd.DataFrame(0.0, index=idx, columns=_R19_ALL_FAMILIES)
        w[_R19_FIXED_FAMILY] = 0.25
        return w

    expected = {}
    w = blank()
    for dt in idx:
        eligible = [f for f in _R19_RANK_FAMILIES if gate.loc[dt, f] > 0]
        if not eligible:
            eligible = list(_R19_RANK_FAMILIES)
        w.loc[dt, eligible] = 0.75 / len(eligible)
    expected["Gatekeeper"] = w

    for name, pick_column in [
        ("Tailwind", "TailwindPick"),
        ("Nukimi", "NukimiPick"),
        ("Acceleration", "AccelerationPick"),
    ]:
        w = blank()
        for family in _R19_RANK_FAMILIES:
            w.loc[audit[pick_column].eq(family), family] = 0.75
        expected[name] = w

    w = blank()
    for family in _R19_RANK_FAMILIES:
        w.loc[audit["KawarimiStrongest"].eq(family), family] += 0.375
        w.loc[audit["KawarimiWeakest"].eq(family), family] += 0.375
    expected["Kawarimi"] = w
    return expected


def _r19_exactness(strategies, weights, next_returns, audit, gate):
    all_weights = pd.concat(weights, names=["Strategy", "SignalMonth"])
    fixed_error = float((all_weights[_R19_FIXED_FAMILY] - 0.25).abs().max())
    sum_error = float((all_weights.sum(axis=1) - 1.0).abs().max())
    control_expected = pd.DataFrame(
        0.25, index=weights["Bunshin Control"].index,
        columns=_R19_ALL_FAMILIES,
    )
    control_error = float(
        (weights["Bunshin Control"] - control_expected).abs().to_numpy().max()
    )
    expected = _r19_rule_expected_weights(audit, gate)
    rule_error = 0.0
    for name, target in expected.items():
        rule_error = max(
            rule_error,
            float((weights[name] - target).abs().to_numpy().max()),
        )
    return_error = 0.0
    for name in _R14_STRATEGIES:
        rebuilt = (weights[name] * next_returns).sum(axis=1, min_count=1)
        return_error = max(return_error, float((strategies[name] - rebuilt).abs().max()))
    signal = pd.DatetimeIndex(audit.index)
    apply = pd.to_datetime(audit["ReturnMonth"])
    timing_bad = int((apply <= signal).sum()) + int(apply.max() > _R19_CUTOFF)
    return pd.DataFrame([
        {"Check": "TEL-DM fixed at 25% for every strategy/month", "Error": fixed_error, "Tolerance": 1e-12, "PASS": fixed_error <= 1e-12},
        {"Check": "Every target-weight row sums to 100%", "Error": sum_error, "Tolerance": 1e-12, "PASS": sum_error <= 1e-12},
        {"Check": "Bunshin control exactly equals Frozen 4F EW", "Error": control_error, "Tolerance": 1e-12, "PASS": control_error <= 1e-12},
        {"Check": "All five R14 selector rules reconstruct exactly with TEL fixed", "Error": rule_error, "Tolerance": 1e-12, "PASS": rule_error <= 1e-12},
        {"Check": "Portfolio returns reconstruct from weights times next-family returns", "Error": return_error, "Tolerance": 1e-12, "PASS": return_error <= 1e-12},
        {"Check": "Signal month t applies only to t+1 within DEV cutoff", "Error": float(timing_bad), "Tolerance": 0.0, "PASS": timing_bad == 0},
    ])


