# ================================================================
# R20 — TEL-Fixed Nukimi vs Frozen Challengers Daily Tail Championship
#
# Pre-registered after official R19 Exactness 6/6 PASS:
#   Frozen 4F EW / 4F Attack75 / 4F Promotion100 /
#   Frozen v3.45 Final / TEL-Fixed Nukimi.
# R19 month-end signal t is mapped to month t+1, the target is reset
# on the first common daily row, and family weights drift naturally.
# No new parameter, lookback, threshold, weight, Brake, or rescue.
# ================================================================

_R20_CUTOFF = pd.Timestamp("2026-07-31")
_R20_CONTROL = "Frozen 4F EW"
_R20_NUKIMI = "TEL-Fixed Nukimi"
_R20_ORDER = [
    _R20_CONTROL, "4F Attack75", "4F Promotion100",
    "Frozen v3.45 Final", _R20_NUKIMI,
]


def _r20_apply_targets(weights, audit):
    """Map frozen R19 signal-month weights to their recorded t+1 month."""
    idx = weights.index.intersection(audit.index)
    apply_months = pd.PeriodIndex(
        pd.to_datetime(audit.loc[idx, "ReturnMonth"]), freq="M", name="ApplyMonth"
    )
    target = pd.DataFrame(0.0, index=apply_months, columns=_R16_ASSETS)
    target.loc[:, _R19_ALL_FAMILIES] = weights.loc[idx, _R19_ALL_FAMILIES].to_numpy(float)
    return target


def _r20_build_daily(px_bt, rf_bt, bt_start, bt_end):
    r6, family_daily, _, states, _, _, _, _, _ = _r6_build(
        px_bt, rf_bt, bt_start, bt_end
    )
    v345, _ = _r7_v345_close(px_bt, rf_bt, bt_start, bt_end)
    r19_monthly, r19_weights, _, r19_audit, _, r19_prior, _, _ = (
        _r19_tel_fixed_build(px_bt, rf_bt, bt_start, bt_end)
    )
    family_daily = family_daily[_R19_ALL_FAMILIES].dropna().loc[:_R20_CUTOFF]
    cash = _r16_cash_daily(family_daily.index, rf_bt).reindex(family_daily.index).fillna(0.0)
    asset_daily = family_daily.assign(CASH=cash)
    nukimi_targets = _r20_apply_targets(r19_weights["Nukimi"], r19_audit)
    control_targets = pd.DataFrame(0.0, index=nukimi_targets.index, columns=_R16_ASSETS)
    control_targets.loc[:, _R19_ALL_FAMILIES] = 0.25
    nukimi, nukimi_log, nukimi_turn = _r16_monthly_target_portfolio(
        asset_daily, nukimi_targets, _R20_NUKIMI
    )
    control_rebuilt, control_log, control_turn = _r16_monthly_target_portfolio(
        asset_daily, control_targets, _R20_CONTROL
    )
    frozen = pd.concat([
        r6["Frozen 4F EW"].rename(_R20_CONTROL),
        r6["Attack75 Selector"].rename("4F Attack75"),
        r6["Promotion100"].rename("4F Promotion100"),
        v345.rename("Frozen v3.45 Final"),
    ], axis=1)
    daily = pd.concat([frozen, nukimi.rename(_R20_NUKIMI)], axis=1)
    daily = daily.dropna().loc[:_R20_CUTOFF, _R20_ORDER]
    if daily.empty:
        raise RuntimeError("R20 common daily sample is empty.")
    return daily, {
        "r6": r6, "v345": v345, "states": states.reindex(daily.index),
        "r19_monthly": r19_monthly, "r19_audit": r19_audit,
        "r19_prior": r19_prior, "nukimi_targets": nukimi_targets,
        "nukimi_log": nukimi_log, "nukimi_turn": nukimi_turn,
        "control_rebuilt": control_rebuilt, "control_log": control_log,
        "control_turn": control_turn,
    }


def _r20_exactness(daily, metrics, episodes, payload):
    r6 = payload["r6"]
    source = pd.concat([
        r6["Frozen 4F EW"].rename(_R20_CONTROL),
        r6["Attack75 Selector"].rename("4F Attack75"),
        r6["Promotion100"].rename("4F Promotion100"),
        payload["v345"].rename("Frozen v3.45 Final"),
    ], axis=1).reindex(daily.index)
    frozen_error = float(
        (daily[_R20_ORDER[:-1]] - source[_R20_ORDER[:-1]]).abs().to_numpy().max()
    )
    targets = payload["nukimi_targets"]
    tel_error = float((targets["TEL-DM"] - 0.25).abs().max())
    sum_error = float((targets.sum(axis=1) - 1.0).abs().max())
    audit = payload["r19_audit"]
    prior = payload["r19_prior"]
    signal_idx = audit.index.intersection(prior.index)
    expected_pick = prior.loc[signal_idx, _R19_RANK_FAMILIES].idxmax(axis=1)
    pick_error = float(
        (audit.loc[signal_idx, "NukimiPick"].astype(str) != expected_pick.astype(str)).sum()
    )
    signal_period = pd.DatetimeIndex(signal_idx).to_period("M")
    apply_period = pd.PeriodIndex(
        pd.to_datetime(audit.loc[signal_idx, "ReturnMonth"]), freq="M"
    )
    lag_error = float((apply_period != signal_period + 1).sum())
    log = payload["nukimi_log"].copy()
    log["Date"] = pd.to_datetime(log["Date"])
    rebuilt_daily = log.set_index("Date")["ReconstructedReturn"].sort_index()
    contribution_error = float(
        (daily[_R20_NUKIMI].reindex(rebuilt_daily.index) - rebuilt_daily).dropna().abs().max()
    )
    daily_monthly = (
        (1.0 + rebuilt_daily).groupby(rebuilt_daily.index.to_period("M")).prod() - 1.0
    )
    r19 = payload["r19_monthly"]["Nukimi"].copy()
    r19_audit = payload["r19_audit"].reindex(r19.index)
    r19_apply = pd.PeriodIndex(pd.to_datetime(r19_audit["ReturnMonth"]), freq="M")
    r19_by_apply = pd.Series(r19.to_numpy(float), index=r19_apply).sort_index()
    cm = daily_monthly.index.intersection(r19_by_apply.index)
    monthly_error = float((daily_monthly.loc[cm] - r19_by_apply.loc[cm]).abs().max())
    metric_dd = metrics.set_index("Strategy")["Daily MaxDD"]
    episode_dd = episodes.groupby("Strategy")["Depth"].min().reindex(_R20_ORDER)
    dd_error = float((metric_dd.reindex(_R20_ORDER) - episode_dd).abs().max())
    monthly = (1.0 + daily).resample("ME").prod(min_count=1) - 1.0
    direct = (1.0 + daily).prod()
    via_month = (1.0 + monthly).prod()
    scale = pd.concat([direct.abs(), via_month.abs()], axis=1).max(axis=1).clip(lower=1.0)
    wealth_error = float(((direct - via_month).abs() / scale).max())
    timing_bad = int(daily.index.max() > _R20_CUTOFF)
    timing_bad += int(not daily.index.is_monotonic_increasing)
    timing_bad += int(daily.index.has_duplicates)
    checks = [
        ("Five pre-registered competitors present in fixed order", float(list(daily.columns) != _R20_ORDER), 0.0),
        ("Four legacy competitors equal frozen daily source builders", frozen_error, 1e-12),
        ("TEL-DM remains exactly 25% in every Nukimi apply month", tel_error, 1e-12),
        ("Every TEL-Fixed Nukimi target row sums to 100%", sum_error, 1e-12),
        ("R19 Prior11M strongest-family rule reconstructs every Nukimi pick", pick_error, 0.0),
        ("Every frozen R19 signal month t maps only to apply month t+1", lag_error, 0.0),
        ("Nukimi daily return equals drifting family contribution reconstruction", contribution_error, 1e-12),
        ("Rebuilt Nukimi daily path compounds exactly to frozen R19 monthly return", monthly_error, 1e-12),
        ("Episode depths equal canonical Daily MaxDD", dd_error, 1e-12),
        ("Daily-to-monthly terminal wealth reconstruction is scale-aware exact", wealth_error, 1e-12),
        ("Daily index is ordered, unique, and within DEV cutoff", float(timing_bad), 0.0),
    ]
    return pd.DataFrame([
        {"Check": label, "Error": error, "Tolerance": tolerance,
         "PASS": bool(error <= tolerance)}
        for label, error, tolerance in checks
    ])


def _r20_validation_tables(monthly):
    wf_parts, cpcv_parts, group_parts = [], [], []
    for challenger in [c for c in _R20_ORDER if c != _R20_CONTROL]:
        wf = _v403a_wf(monthly, _R20_CONTROL, challenger, 13)
        wf.insert(0, "Variant", challenger)
        wf_parts.append(wf)
        cpcv, groups = _v403a_cpcv(monthly, _R20_CONTROL, challenger)
        cpcv.insert(0, "Variant", challenger)
        groups.insert(0, "Variant", challenger)
        cpcv_parts.append(cpcv)
        group_parts.append(groups)
    wf = pd.concat(wf_parts, ignore_index=True)
    cpcv = pd.concat(cpcv_parts, ignore_index=True)
    groups = pd.concat(group_parts, ignore_index=True)
    cpcv_summary = cpcv.groupby("Variant", as_index=False).agg(
        Splits=("Positive Active", "count"), ActiveWins=("Positive Active", "sum"),
        SharpeWins=("Positive Delta Sharpe", "sum"),
        SortinoWins=("Positive Delta Sortino", "sum"),
        MedianActiveAnnual=("Active AnnArithmetic", "median"),
        MedianDeltaSharpe=("Delta Sharpe0", "median"),
        MedianDeltaSortino=("Delta Sortino0", "median"),
    )
    return wf, cpcv, groups, cpcv_summary


