# ================================================================
# R21 — 4F Temporal Sleeve Diversification Audit
#
# Research branch from R17, NOT a rescue/tuning of R20.
# R17 combined 1/3/6/12M scores BEFORE selection. R21 keeps each horizon
# as an independent Top2 strategy sleeve and combines completed sleeves only
# at the portfolio layer. Therefore:
#   Select(sum_h w_h Score_h) != sum_h w_h Select(Score_h)
#
# Frozen horizons: 1M / 3M / 6M / 12M, inherited from R17.
# For sleeve h at signal month t, score = compounded family return over the
# preceding h completed family months ending t-1. Matched RF uses the same
# h-month window. Eligible families beat matched RF; Top2 is equally weighted,
# one eligible receives 100%, none -> CASH. Signal t applies t+1.
#
# All sleeves share the same first signal month (12M history required) so every
# 1/2/3/4-sleeve combination is compared over one identical sample.
# Portfolio layer: equal sleeve capital at each apply-month start, natural
# intra-month drift. No best-combination selection, no horizon/weight/threshold
# search. Primary hypothesis: robustness distributions by sleeve count (1->4),
# including CPCV split-wise medians, not the ex-post best combination.
# DEV cutoff = 2026-07-31. Only the user-run ZIP is official.
# ================================================================

_R21_HORIZONS = (1, 3, 6, 12)
_R21_CONTROL = "Frozen 4F EW"
_R21_CUTOFF = pd.Timestamp("2026-07-31")


def _r21_slug_horizons(horizons):
    return "+".join(f"{int(h)}M" for h in horizons)


def _r21_single_horizon_targets(family_monthly, rf_monthly, horizon):
    horizon = int(horizon)
    fm = family_monthly[_R16_FAMILIES].dropna().astype(float).sort_index()
    rfm = rf_monthly.reindex(fm.index).astype(float)
    rows, targets = [], []
    # Common 12M warm-up is deliberate. It makes all four sleeves and all
    # 15 combinations start from exactly the same apply month.
    for i, signal_month in enumerate(fm.index):
        if i < max(_R21_HORIZONS):
            continue
        family_window = fm.iloc[i-horizon:i]
        rf_window = rfm.iloc[i-horizon:i]
        if len(family_window) != horizon or family_window.isna().any().any() or rf_window.isna().any():
            continue
        score = (1.0 + family_window).prod() - 1.0
        rf_score = float((1.0 + rf_window).prod() - 1.0)
        eligible = score[score > rf_score].sort_values(ascending=False, kind="mergesort")
        chosen = list(eligible.index[:2])
        target = {asset: 0.0 for asset in _R16_ASSETS}
        if chosen:
            for family in chosen:
                target[family] = 1.0 / len(chosen)
            selected = "+".join(chosen)
        else:
            target["CASH"] = 1.0
            selected = "CASH"
        apply_month = signal_month + 1
        audit = {
            "HorizonMonths": horizon,
            "SignalMonth": str(signal_month),
            "ScoreStartMonth": str(fm.index[i-horizon]),
            "ScoreEndMonth": str(fm.index[i-1]),
            "ApplyMonth": str(apply_month),
            "CompletedScoreMonths": horizon,
            "MatchedRF": rf_score,
            "EligibleCount": int(len(eligible)),
            "Selected": selected,
        }
        for family in _R16_FAMILIES:
            audit[f"Score_{family}"] = float(score[family])
            audit[f"Eligible_{family}"] = bool(score[family] > rf_score)
        for asset in _R16_ASSETS:
            audit[f"Target_{asset}"] = float(target[asset])
        rows.append(audit)
        targets.append({"ApplyMonth": apply_month, **target})
    audit = pd.DataFrame(rows)
    if not targets:
        return pd.DataFrame(), audit
    wt = pd.DataFrame(targets).set_index("ApplyMonth")[_R16_ASSETS]
    wt.index = pd.PeriodIndex(wt.index, freq="M")
    return wt, audit


def _r21_rule_error(targets, audit, horizon):
    if targets.empty or audit.empty:
        return np.inf
    err = 0.0
    for _, row in audit.iterrows():
        scores = pd.Series({f: float(row[f"Score_{f}"]) for f in _R16_FAMILIES})
        rf_score = float(row["MatchedRF"])
        eligible = scores[scores > rf_score].sort_values(ascending=False, kind="mergesort")
        chosen = list(eligible.index[:2])
        expected = pd.Series(0.0, index=_R16_ASSETS)
        if chosen:
            expected.loc[chosen] = 1.0 / len(chosen)
        else:
            expected.loc["CASH"] = 1.0
        month = pd.Period(row["ApplyMonth"], freq="M")
        if month not in targets.index:
            return np.inf
        actual = targets.loc[month, _R16_ASSETS]
        if isinstance(actual, pd.DataFrame):
            actual = actual.iloc[-1]
        err = max(err, float((actual.astype(float) - expected).abs().max()))
        err = max(err, abs(float(row["CompletedScoreMonths"]) - float(horizon)))
    return err


def _r21_portfolioize_sleeves(sleeve_daily, horizons, name):
    """Independent sleeve NAVs -> month-start EW across sleeves, natural drift."""
    cols = [f"{int(h)}M" for h in horizons]
    x = sleeve_daily[cols].dropna().astype(float).sort_index().loc[:_R21_CUTOFF]
    out, logs = [], []
    for period, month_rows in x.groupby(x.index.to_period("M")):
        wealth = pd.Series(1.0 / len(cols), index=cols, dtype=float)
        for date, rr in month_rows.iterrows():
            pre = wealth / wealth.sum()
            pr = float((pre * rr).sum())
            out.append((date, pr))
            row = {"Strategy": name, "Date": date, "Month": str(period), "ReconstructedReturn": pr}
            for c in cols:
                row[f"PreReturnWeight_{c}"] = float(pre[c])
                row[f"Contribution_{c}"] = float(pre[c] * rr[c])
            logs.append(row)
            wealth = wealth * (1.0 + rr)
    return pd.Series(dict(out), name=name, dtype=float).sort_index(), pd.DataFrame(logs)


def _r21_pairwise_selection(audits, sleeve_daily):
    from itertools import combinations
    rows = []
    for h1, h2 in combinations(_R21_HORIZONS, 2):
        a = audits[h1].set_index("ApplyMonth")
        b = audits[h2].set_index("ApplyMonth")
        common = a.index.intersection(b.index)
        exact, any_overlap, jaccards = [], [], []
        for m in common:
            s1 = str(a.loc[m, "Selected"])
            s2 = str(b.loc[m, "Selected"])
            set1 = set() if s1 == "CASH" else set(s1.split("+"))
            set2 = set() if s2 == "CASH" else set(s2.split("+"))
            exact.append(set1 == set2)
            any_overlap.append(bool(set1.intersection(set2)) if (set1 or set2) else True)
            union = set1.union(set2)
            jaccards.append(1.0 if not union else len(set1.intersection(set2)) / len(union))
        c1, c2 = f"{h1}M", f"{h2}M"
        d = sleeve_daily[[c1, c2]].dropna()
        mret = (1.0 + d).resample("ME").prod(min_count=1) - 1.0
        dd1 = (1.0 + d[c1]).cumprod(); dd1 = dd1 / dd1.cummax() - 1.0
        dd2 = (1.0 + d[c2]).cumprod(); dd2 = dd2 / dd2.cummax() - 1.0
        rows.append({
            "Sleeve1": c1, "Sleeve2": c2, "ApplyMonths": len(common),
            "Exact Top2 Set Agreement": float(np.mean(exact)) if exact else np.nan,
            "Any Family Overlap": float(np.mean(any_overlap)) if any_overlap else np.nan,
            "Mean Jaccard Similarity": float(np.mean(jaccards)) if jaccards else np.nan,
            "Daily Return Correlation": float(d[c1].corr(d[c2])) if len(d) else np.nan,
            "Monthly Return Correlation": float(mret[c1].corr(mret[c2])) if len(mret) else np.nan,
            "Drawdown Correlation": float(dd1.corr(dd2)) if len(dd1) else np.nan,
            "Horizon Distance Months": abs(int(h2)-int(h1)),
        })
    return pd.DataFrame(rows)


def _r21_diversification_ratio(sleeve_daily, combo_daily, horizons):
    cols = [f"{int(h)}M" for h in horizons]
    z = pd.concat([sleeve_daily[cols], combo_daily.rename("Portfolio")], axis=1).dropna()
    if len(z) < 2:
        return np.nan
    sleeve_vol = z[cols].std(ddof=1) * np.sqrt(252.0)
    port_vol = float(z["Portfolio"].std(ddof=1) * np.sqrt(252.0))
    return float(sleeve_vol.mean() / port_vol) if port_vol > 0 else np.nan


def _r21_combo_group_summary(combo_metrics):
    numeric = [
        "CAGR", "Vol", "Daily MaxDD", "Sharpe0", "Sortino0", "Expected Shortfall 5%",
        "Worst 5-day", "Ulcer Index", "Max Depth x Duration", "Diversification Ratio",
        "Annualized OneWay Turnover",
    ]
    rows = []
    for n, g in combo_metrics.groupby("SleeveCount"):
        row = {"SleeveCount": int(n), "Combinations": len(g)}
        for c in numeric:
            if c in g:
                row[f"Median {c}"] = float(g[c].median())
                row[f"Mean {c}"] = float(g[c].mean())
                row[f"Worst {c}"] = float(g[c].min() if c not in ["Daily MaxDD", "Expected Shortfall 5%", "Worst 5-day"] else g[c].min())
                row[f"Best {c}"] = float(g[c].max())
        rows.append(row)
    return pd.DataFrame(rows).sort_values("SleeveCount")


def _r21_cpcv_all(monthly, combo_names):
    from itertools import combinations
    groups = np.array_split(np.arange(len(monthly)), 8)
    details = []
    group_bounds = []
    for k, loc in enumerate(groups, 1):
        if len(loc):
            group_bounds.append({"Group": k, "Start": str(monthly.index[loc[0]]), "End": str(monthly.index[loc[-1]]), "Months": len(loc)})
    if len(monthly) < 8:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame()
    for a, b in combinations(range(8), 2):
        loc = np.sort(np.r_[groups[a], groups[b]])
        g = monthly.iloc[loc]
        for name in combo_names:
            s = g[name].dropna()
            details.append({
                "Group1": a+1, "Group2": b+1, "Strategy": name,
                "SleeveCount": int(name.split("S:",1)[0]), "Months": len(s),
                "CAGRProxy": float((1.0+s).prod() ** (12.0/len(s)) - 1.0) if len(s) else np.nan,
                "Sharpe0": _monthly_sharpe0(s) if len(s) else np.nan,
                "Sortino0": _monthly_sortino0(s) if len(s) else np.nan,
            })
    detail = pd.DataFrame(details)
    # Primary anti-selection-bias view: within every held-out split, summarize
    # the whole set of combinations at each sleeve count.
    split_summary = detail.groupby(["Group1", "Group2", "SleeveCount"], as_index=False).agg(
        Combinations=("Strategy", "count"),
        MedianCAGRProxy=("CAGRProxy", "median"), MeanCAGRProxy=("CAGRProxy", "mean"),
        MedianSharpe0=("Sharpe0", "median"), MeanSharpe0=("Sharpe0", "mean"),
        MedianSortino0=("Sortino0", "median"), MeanSortino0=("Sortino0", "mean"),
        WorstSharpe0=("Sharpe0", "min"), WorstSortino0=("Sortino0", "min"),
    )
    return detail, split_summary, pd.DataFrame(group_bounds)


def _r21_cpcv_progression(split_summary):
    rows = []
    if split_summary.empty:
        return pd.DataFrame()
    wide_s = split_summary.pivot_table(index=["Group1","Group2"], columns="SleeveCount", values="MedianSortino0")
    wide_h = split_summary.pivot_table(index=["Group1","Group2"], columns="SleeveCount", values="MedianSharpe0")
    for a, b in [(1,2),(2,3),(3,4),(1,3),(1,4)]:
        if a in wide_s.columns and b in wide_s.columns:
            ds = wide_s[b] - wide_s[a]
            dh = wide_h[b] - wide_h[a]
            rows.append({
                "Comparison": f"{a}->${b}".replace("$", ""), "Splits": int(ds.notna().sum()),
                "Median Sortino Improved Splits": int((ds > 0).sum()),
                "Median Sharpe Improved Splits": int((dh > 0).sum()),
                "Median Delta Sortino": float(ds.median()), "Median Delta Sharpe": float(dh.median()),
            })
    return pd.DataFrame(rows)


def _r21_fixed_year_regimes(daily):
    rows = []
    for year in [2020, 2022, 2025]:
        q = daily.loc[f"{year}-01-01":f"{year}-12-31"]
        if q.empty:
            continue
        for c in q.columns:
            x = q[c].dropna()
            if not len(x):
                continue
            wealth = (1.0+x).cumprod(); dd = wealth/wealth.cummax()-1.0
            rows.append({
                "Year": year, "Strategy": c, "TradingDays": len(x),
                "Return": float((1.0+x).prod()-1.0), "MaxDD": float(dd.min()),
                "Sharpe0": float(x.mean()/x.std(ddof=1)*np.sqrt(252.0)) if x.std(ddof=1)>0 else np.nan,
                "Sortino0": float(x.mean()/(np.sqrt(np.mean(np.square(np.minimum(x.to_numpy(dtype=float),0.0)))))*np.sqrt(252.0)) if np.sqrt(np.mean(np.square(np.minimum(x.to_numpy(dtype=float),0.0))))>0 else np.nan,
            })
    return pd.DataFrame(rows)


def _r21_exactness(r6_control, control_rebuilt, sleeve_targets, sleeve_audits,
                   sleeve_daily, sleeve_logs, combo_targets, combo_daily,
                   combo_logs, sleeve_nav_checks):
    errors = []
    control_error = float((r6_control.reindex(control_rebuilt.index)-control_rebuilt).dropna().abs().max())
    target_error = max(float((t.sum(axis=1)-1.0).abs().max()) for t in sleeve_targets.values())
    rule_error = max(_r21_rule_error(sleeve_targets[h], sleeve_audits[h], h) for h in _R21_HORIZONS)
    sleeve_recon = max(_r16_reconstruction_error(sleeve_daily[f"{h}M"], sleeve_logs[h]) for h in _R21_HORIZONS)
    combo_target_error = max(float((t.sum(axis=1)-1.0).abs().max()) for t in combo_targets.values())
    combo_recon = max(_r16_reconstruction_error(combo_daily[name], combo_logs[name]) for name in combo_daily.columns)
    nav_equiv = max(float(v) for v in sleeve_nav_checks.values()) if sleeve_nav_checks else np.inf
    timing_bad = 0
    for h in _R21_HORIZONS:
        a = sleeve_audits[h]
        signal = pd.PeriodIndex(a["SignalMonth"], freq="M")
        start = pd.PeriodIndex(a["ScoreStartMonth"], freq="M")
        end = pd.PeriodIndex(a["ScoreEndMonth"], freq="M")
        apply = pd.PeriodIndex(a["ApplyMonth"], freq="M")
        timing_bad += int((start > end).sum() + (end >= signal).sum() + (signal >= apply).sum())
        timing_bad += int((a["CompletedScoreMonths"].astype(int) != int(h)).sum())
    common_start_error = float(len(set(t.index.min() for t in sleeve_targets.values())) - 1)
    combo_count_error = abs(len(combo_targets)-15)
    cutoff_bad = int(pd.DatetimeIndex(combo_daily.index).max() > _R21_CUTOFF)
    errors.extend([
        ("Independent monthly-drift EW rebuild equals Frozen 4F EW", control_error, 1e-12),
        ("Every 1M/3M/6M/12M sleeve target sums to 100%", target_error, 1e-12),
        ("Each horizon matched-RF gate + Top2 rule reconstructs exactly", rule_error, 1e-12),
        ("Every single-horizon daily return equals contribution reconstruction", sleeve_recon, 1e-12),
        ("All 15 equal-sleeve aggregate target rows sum to 100%", combo_target_error, 1e-12),
        ("All 15 portfolio daily returns equal underlying contribution reconstruction", combo_recon, 1e-12),
        ("Independent sleeve-NAV portfolio equals aggregate underlying-target portfolio", nav_equiv, 1e-12),
        ("All horizons share one common post-12M warm-up start", common_start_error, 0.0),
        ("Exactly 15 non-empty horizon combinations are generated", float(combo_count_error), 0.0),
        ("Score windows end before signal; signal precedes apply; DEV cutoff held", float(timing_bad+cutoff_bad), 0.0),
    ])
    return pd.DataFrame([
        {"Check": n, "Error": e, "Tolerance": tol, "PASS": bool(np.isfinite(e) and e <= tol)}
        for n,e,tol in errors
    ])


def render_r21_temporal_sleeve_diversification(px_bt, rf_bt, bt_start, bt_end):
    import io, zipfile
    from itertools import combinations

    st.header("🕰️ R21 — 4F Temporal Sleeve Diversification Audit")
    st.caption("Module build: R21-TEMPORAL-SLEEVE-DIVERSIFICATION — R17 branch / independent horizon sleeves / no best-combination selection")
    st.success(
        "R20公式結果はExactness 11/11 PASS。TEL-Fixed NukimiはCAGRを維持した一方、Daily MaxDD・Worst5D・Ulcer・underwaterで悪化し、tail-risk改善策としては不採用。"
    )
    st.info(
        "R17は1/3/6/12M scoreを先に1個へ圧縮してからTop2を選びました。R21は別物です。"
        "1M・3M・6M・12Mをそれぞれ独立Top2戦略として最後まで構築し、その後だけsleeve portfolio化します。"
    )
    st.latex(r"\mathrm{Select}(\sum_h w_h\,Score_h) \neq \sum_h w_h\,\mathrm{Select}(Score_h)")
    st.warning(
        "固定仕様: horizons=1/3/6/12M、各hはcompleted months ending t-1、matched RFも同一h、Top2、signal t→apply t+1。"
        "全sleeveは12M warm-up後の同一開始月へ揃えます。15組合せは等sleeve weight・月初リバランス・月内自然drift。"
        "最良組合せを採用する検証ではなく、1→2→3→4 sleevesで組合せ全体の分布/CPCVが改善するかが主仮説です。DEV cutoff=2026-07-31。"
    )
    design = pd.DataFrame([
        {"SleeveCount":1,"Combinations":4,"Interpretation":"single-horizon baseline distribution"},
        {"SleeveCount":2,"Combinations":6,"Interpretation":"pairwise temporal diversification"},
        {"SleeveCount":3,"Combinations":4,"Interpretation":"three-horizon diversification"},
        {"SleeveCount":4,"Combinations":1,"Interpretation":"full 1/3/6/12M temporal ensemble"},
    ])
    st.dataframe(design, hide_index=True, use_container_width=True)
    if not st.button("R21 Temporal Sleeve Diversificationを実行", type="primary", use_container_width=True, key="run_r21_temporal_sleeves"):
        return

    p = st.progress(0, text="R21 0/14 — Frozen 4F family NAVを再構築中…")
    r6, family_daily, _, _, _, _, _, _, _ = _r6_build(px_bt, rf_bt, bt_start, bt_end)
    family_daily = family_daily[_R16_FAMILIES].dropna().loc[:_R21_CUTOFF]
    cash = _r16_cash_daily(family_daily.index, rf_bt).reindex(family_daily.index).fillna(0.0)
    asset_daily = family_daily.assign(CASH=cash)
    family_monthly = (1.0 + family_daily).groupby(family_daily.index.to_period("M")).prod().sub(1.0)
    rf_monthly = _v401_monthly_rf(family_daily, rf_bt).reindex(family_monthly.index)

    p.progress(10, text="R21 1/14 — 1M / 3M / 6M / 12Mを独立Top2 sleeve化中…")
    sleeve_targets, sleeve_audits = {}, {}
    for h in _R21_HORIZONS:
        sleeve_targets[h], sleeve_audits[h] = _r21_single_horizon_targets(family_monthly, rf_monthly, h)
    if any(t.empty for t in sleeve_targets.values()):
        st.error("R21 sleeve targetを構築できませんでした。")
        return
    common_months = None
    for t in sleeve_targets.values():
        common_months = t.index if common_months is None else common_months.intersection(t.index)
    sleeve_targets = {h:t.loc[common_months].copy() for h,t in sleeve_targets.items()}
    for h,a in list(sleeve_audits.items()):
        sleeve_audits[h] = a[pd.PeriodIndex(a["ApplyMonth"],freq="M").isin(common_months)].reset_index(drop=True)

    p.progress(20, text="R21 3/14 — 独立sleeveの日次NAV・自然driftを再構築中…")
    sleeve_series, sleeve_logs, sleeve_turnovers = {}, {}, {}
    for h in _R21_HORIZONS:
        s, log, turn = _r16_monthly_target_portfolio(asset_daily, sleeve_targets[h], f"{h}M")
        sleeve_series[h], sleeve_logs[h], sleeve_turnovers[h] = s.rename(f"{h}M"), log, turn
    sleeve_daily = pd.concat([sleeve_series[h] for h in _R21_HORIZONS], axis=1).dropna()

    ew_targets = pd.DataFrame(0.0,index=common_months,columns=_R16_ASSETS)
    ew_targets[_R16_FAMILIES] = 0.25
    control_rebuilt, control_log, control_turnover = _r16_monthly_target_portfolio(asset_daily, ew_targets, _R21_CONTROL)

    p.progress(31, text="R21 4/14 — 15通りを機械生成（等sleeve weight）中…")
    combo_targets, combo_series, combo_logs, combo_turnovers = {}, {}, {}, {}
    combo_meta, sleeve_nav_checks = [], {}
    for n in range(1,5):
        for hs in combinations(_R21_HORIZONS,n):
            label = f"{n}S:{_r21_slug_horizons(hs)}"
            agg = sum(sleeve_targets[h] for h in hs) / float(n)
            combo_targets[label] = agg
            s, log, turn = _r16_monthly_target_portfolio(asset_daily, agg, label)
            combo_series[label], combo_logs[label], combo_turnovers[label] = s.rename(label), log, turn
            independent, _ = _r21_portfolioize_sleeves(sleeve_daily, hs, label)
            common_idx = s.index.intersection(independent.index)
            sleeve_nav_checks[label] = float((s.loc[common_idx]-independent.loc[common_idx]).abs().max()) if len(common_idx) else np.inf
            combo_meta.append({"Strategy":label,"SleeveCount":n,"Horizons":_r21_slug_horizons(hs)})
    combo_meta = pd.DataFrame(combo_meta)
    combo_daily = pd.concat([combo_series[x] for x in combo_meta["Strategy"]],axis=1).dropna()
    common_daily_idx = combo_daily.index.intersection(control_rebuilt.index).intersection(sleeve_daily.index)
    combo_daily = combo_daily.loc[common_daily_idx]
    sleeve_daily = sleeve_daily.loc[common_daily_idx]
    control = r6["Frozen 4F EW"].rename(_R21_CONTROL).reindex(common_daily_idx)
    daily_all = pd.concat([control, combo_daily],axis=1).dropna()

    p.progress(43, text="R21 6/14 — 相関・Family一致率・Jaccard・Diversification Ratioを計算中…")
    pairwise = _r21_pairwise_selection(sleeve_audits, sleeve_daily)
    # Selection state table for direct audit.
    sel_state = None
    for h in _R21_HORIZONS:
        z = sleeve_audits[h][["ApplyMonth","Selected","EligibleCount"]].copy()
        z = z.rename(columns={"Selected":f"Selected_{h}M","EligibleCount":f"EligibleCount_{h}M"})
        sel_state = z if sel_state is None else sel_state.merge(z,on="ApplyMonth",how="inner")

    p.progress(53, text="R21 7/14 — Tail / underwater / turnoverを全15構成で計算中…")
    episodes = pd.concat([_r12_underwater_episodes(name,daily_all[name]) for name in daily_all.columns],ignore_index=True)
    metrics_rows = []
    for name in combo_meta["Strategy"]:
        row = _r12_metric_row(name,daily_all[name],episodes)
        hs = tuple(int(x.replace("M","")) for x in combo_meta.loc[combo_meta["Strategy"].eq(name),"Horizons"].iloc[0].split("+"))
        row["SleeveCount"] = len(hs)
        row["Horizons"] = _r21_slug_horizons(hs)
        row["Diversification Ratio"] = _r21_diversification_ratio(sleeve_daily,daily_all[name],hs)
        turn = combo_turnovers[name]
        row["Annualized OneWay Turnover"] = float(turn["OneWayTurnover"].mean()*12.0) if len(turn) else np.nan
        metrics_rows.append(row)
    combo_metrics = pd.DataFrame(metrics_rows)
    control_metric = _r12_metric_row(_R21_CONTROL,daily_all[_R21_CONTROL],episodes)
    control_metric.update({"SleeveCount":0,"Horizons":"Control","Diversification Ratio":np.nan,
                           "Annualized OneWay Turnover":float(control_turnover["OneWayTurnover"].mean()*12.0) if len(control_turnover) else np.nan})
    full_metrics = pd.concat([pd.DataFrame([control_metric]),combo_metrics],ignore_index=True)
    group_summary = _r21_combo_group_summary(combo_metrics)

    p.progress(64, text="R21 9/14 — CPCV 28をsplitごとのsleeve数分布で監査中…")
    monthly = (1.0+daily_all).resample("ME").prod(min_count=1)-1.0
    cpcv_detail, cpcv_split, cpcv_groups = _r21_cpcv_all(monthly,list(combo_meta["Strategy"]))
    cpcv_progression = _r21_cpcv_progression(cpcv_split)

    p.progress(74, text="R21 10/14 — Walk-forward 13Mを全15構成で計算中…")
    wf_parts=[]
    for name in combo_meta["Strategy"]:
        wf=_v403a_wf(monthly,_R21_CONTROL,name,13)
        wf.insert(0,"Strategy",name)
        wf.insert(1,"SleeveCount",int(combo_meta.loc[combo_meta["Strategy"].eq(name),"SleeveCount"].iloc[0]))
        wf_parts.append(wf)
    wf_detail=pd.concat(wf_parts,ignore_index=True) if wf_parts else pd.DataFrame()
    wf_summary = wf_detail.groupby("SleeveCount",as_index=False).agg(
        Rows=("Strategy","count"), MedianDeltaSortino=("Delta Sortino0","median"),
        MedianDeltaSharpe=("Delta Sharpe0","median"), MeanDeltaSortino=("Delta Sortino0","mean"),
        PositiveSortinoShare=("Overlay Sortino Win","mean"), PositiveSharpeShare=("Overlay Sharpe Win","mean"),
    ) if len(wf_detail) else pd.DataFrame()

    p.progress(82, text="R21 11/14 — 2020 / 2022 / 2025・固定stress・eraを集計中…")
    year_regimes = _r21_fixed_year_regimes(daily_all)
    stress = _v403a_stress(daily_all)
    eras = _r16_fixed_eras(daily_all)
    annual = _v403a_annual_returns(daily_all)

    p.progress(88, text="R21 12/14 — turnover cost sensitivityを計算中…")
    turnover_map = {_R21_CONTROL:control_turnover, **combo_turnovers}
    cost = _r16_cost_sensitivity(daily_all,turnover_map)
    turnover_all = pd.concat([control_turnover]+[combo_turnovers[n] for n in combo_meta["Strategy"]],ignore_index=True)

    p.progress(94, text="R21 13/14 — Exactness Audit 10項目を実行中…")
    exact = _r21_exactness(
        r6["Frozen 4F EW"],control_rebuilt,sleeve_targets,sleeve_audits,
        sleeve_daily,sleeve_logs,combo_targets,combo_daily,combo_logs,sleeve_nav_checks,
    )
    implementation = pd.DataFrame([
        {"Item":"Research branch","FrozenValue":"R17 branch: independent temporal sleeves, not R20 rescue","Changed":False},
        {"Item":"Horizons","FrozenValue":"1M / 3M / 6M / 12M inherited from R17","Changed":False},
        {"Item":"Single sleeve rule","FrozenValue":"matched-RF absolute gate -> relative Top2; one=100%, none=CASH","Changed":False},
        {"Item":"Timing","FrozenValue":"completed months ending t-1; signal t -> apply t+1","Changed":False},
        {"Item":"Warm-up","FrozenValue":"all horizons use common 12M warm-up for identical sample","Changed":False},
        {"Item":"Portfolio layer","FrozenValue":"equal sleeve capital at month start; natural intra-month drift","Changed":False},
        {"Item":"Combination set","FrozenValue":"all 15 non-empty subsets of 1/3/6/12M","Changed":False},
        {"Item":"Primary inference","FrozenValue":"distribution by sleeve count + CPCV split-wise medians; no best-combo selection","Changed":False},
        {"Item":"Search","FrozenValue":"no horizon/threshold/TopN/sleeve-weight/Brake/rescue search","Changed":False},
        {"Item":"DEV cutoff","FrozenValue":"2026-07-31","Changed":False},
        {"Item":"Official result","FrozenValue":"only user-run exported ZIP","Changed":False},
    ])

    p.progress(97, text="R21 14/14 — 完全監査ZIPを作成中…")
    exports = {
        "00_full_tail_metrics.csv":full_metrics,
        "01_combo_group_summary.csv":group_summary,
        "02_combo_definition.csv":combo_meta,
        "03_sleeve_daily_returns.csv":sleeve_daily.reset_index(),
        "04_all_combo_daily_returns.csv":daily_all.reset_index(),
        "05_monthly_returns.csv":monthly.reset_index(),
        "06_pairwise_selection_and_return_diversification.csv":pairwise,
        "07_monthly_selection_states.csv":sel_state,
        "08_underwater_episodes.csv":episodes,
        "09_cpcv28_detail.csv":cpcv_detail,
        "10_cpcv28_sleeve_count_split_summary.csv":cpcv_split,
        "11_cpcv28_progression.csv":cpcv_progression,
        "12_cpcv_groups.csv":cpcv_groups,
        "13_walk_forward_13_detail.csv":wf_detail,
        "14_walk_forward_sleeve_count_summary.csv":wf_summary,
        "15_2020_2022_2025_regimes.csv":year_regimes,
        "16_fixed_stress.csv":stress,
        "17_fixed_eras.csv":eras,
        "18_annual_returns.csv":annual,
        "19_turnover.csv":turnover_all,
        "20_cost_sensitivity.csv":cost,
        "21_family_daily_returns.csv":family_daily.reset_index(),
        "22_family_monthly_returns.csv":family_monthly.reset_index(),
        "23_matched_rf_monthly_returns.csv":rf_monthly.reset_index(),
        "24_exactness_audit.csv":exact,
        "25_implementation_audit.csv":implementation,
        "26_control_daily_weight_contribution_log.csv":control_log,
        "27_sleeve_nav_equivalence_checks.csv":pd.DataFrame([{"Strategy":k,"MaxAbsError":v} for k,v in sleeve_nav_checks.items()]),
    }
    file_no=28
    for h in _R21_HORIZONS:
        exports[f"{file_no:02d}_{h}m_signal_audit.csv"] = sleeve_audits[h]; file_no+=1
        exports[f"{file_no:02d}_{h}m_monthly_targets.csv"] = sleeve_targets[h].reset_index(); file_no+=1
        exports[f"{file_no:02d}_{h}m_daily_weight_contribution_log.csv"] = sleeve_logs[h]; file_no+=1
    for name in combo_meta["Strategy"]:
        slug=name.lower().replace(":","_").replace("+","_")
        exports[f"{file_no:02d}_{slug}_monthly_targets.csv"] = combo_targets[name].reset_index(); file_no+=1
        exports[f"{file_no:02d}_{slug}_daily_weight_contribution_log.csv"] = combo_logs[name]; file_no+=1

    buf=io.BytesIO()
    with zipfile.ZipFile(buf,"w",zipfile.ZIP_DEFLATED) as zf:
        for fn,df in exports.items():
            zf.writestr(fn,df.to_csv(index=False).encode("utf-8-sig"))
        zf.writestr("README.txt",(
            "R21 4F Temporal Sleeve Diversification Audit\n"
            "Research branch from R17; not an R20 rescue. DEV cutoff=2026-07-31.\n"
            "Frozen horizons: 1M/3M/6M/12M. Each horizon is an independent Top2 strategy sleeve.\n"
            "At signal month t, horizon h compounds the preceding h completed family months ending t-1; matched RF uses the identical window.\n"
            "Eligible families beat matched RF; Top2 equally weighted, one eligible=100%, none=CASH. Signal t applies t+1.\n"
            "All sleeves share a common 12M warm-up. All 15 non-empty horizon subsets are generated mechanically.\n"
            "Combination portfolios equal-weight sleeve capital at each month start and naturally drift within the month.\n"
            "Primary inference is NOT the ex-post best combination: compare distributions for 1 vs 2 vs 3 vs 4 sleeves, including CPCV split-wise medians.\n"
            "Diagnostics include family-selection agreement/Jaccard, return & drawdown correlation, Diversification Ratio, tail/underwater, CPCV, WF, turnover/cost, 2020/2022/2025 and fixed stress.\n"
            "No horizon/threshold/TopN/sleeve-weight/Brake/rescue optimization. Only the user-run returned ZIP is official.\n"
        ).encode("utf-8"))

    p.progress(100, text="R21 完了 — Exactnessと完全監査ZIPを作成済み")
    pass_count=int(exact["PASS"].sum())
    if pass_count==len(exact):
        st.success(f"R21完了。Exactness Audit {pass_count}/{len(exact)} PASS。ZIPをこのチャットへ送ってください。")
    else:
        st.error(f"R21 Exactness Audit {pass_count}/{len(exact)} PASS。FAILがあるため公式解釈前に実装確認が必要です。")

    st.subheader("1. Primary result — sleeve count distribution")
    st.dataframe(group_summary,use_container_width=True,hide_index=True)
    st.caption("主判定はこの1S→2S→3S→4Sの分布推移。最良の個別組合せを採用するための表ではありません。")
    st.subheader("2. All 15 combinations — diagnostic only")
    st.dataframe(combo_metrics,use_container_width=True,hide_index=True)
    st.subheader("3. Temporal diversification mechanism")
    st.dataframe(pairwise,use_container_width=True,hide_index=True)
    st.dataframe(sel_state,use_container_width=True,hide_index=True)
    st.subheader("4. CPCV 28 — sleeve-count progression")
    st.dataframe(cpcv_progression,use_container_width=True,hide_index=True)
    st.dataframe(cpcv_split,use_container_width=True,hide_index=True)
    st.subheader("5. Walk-forward / regimes / stress")
    st.dataframe(wf_summary,use_container_width=True,hide_index=True)
    st.dataframe(year_regimes,use_container_width=True,hide_index=True)
    st.dataframe(stress,use_container_width=True,hide_index=True)
    st.subheader("6. Turnover / cost")
    st.dataframe(cost,use_container_width=True,hide_index=True)
    st.subheader("7. Exactness audit")
    st.dataframe(exact,use_container_width=True,hide_index=True)
    st.download_button(
        "📦 R21 4F Temporal Sleeve Diversification ZIP",data=buf.getvalue(),
        file_name="r21_4f_temporal_sleeve_diversification_audit.zip",mime="application/zip",
        use_container_width=True,on_click="ignore",key="dl_r21_temporal_sleeves",
    )


# ================================================================
# R22 — Frozen 4F + Temporal Satellite 25% Audit
#
# Follow-up to official R21 Exactness 10/10 PASS.
# R21 established a temporal-diversification mechanism among independent
# 1M/3M/6M/12M Meta-DM sleeves, but the standalone Meta-DM portfolios were
# weaker than Frozen 4F EW. R22 therefore does NOT replace Frozen 4F.
# Instead it preserves 75% Frozen 4F EW as a core and allocates exactly 25%
# (one frozen 4F family unit) to an R21 temporal satellite.
#
# For each of all 15 non-empty horizon subsets:
#   Target_R22 = 75% * Frozen4F_EW_target + 25% * TemporalCombo_target
# TemporalCombo_target is the equal-capital average of independent R21
# horizon targets. Monthly reset, natural intra-month drift.
#
# 25% is inherited from the frozen 4F family unit; no weight sweep.
# Primary inference is distribution by temporal sleeve count and robust
# active performance vs Frozen 4F EW, NOT the ex-post best combination.
# DEV cutoff=2026-07-31. Only user-run ZIP is official.
# ================================================================

_R22_CUTOFF = pd.Timestamp("2026-07-31")
_R22_CONTROL = "Frozen 4F EW"
_R22_CORE_WEIGHT = 0.75
_R22_SAT_WEIGHT = 0.25


def _r22_combo_horizons(label):
    rhs = str(label).split(":",1)[1]
    return tuple(int(x.replace("M","")) for x in rhs.split("+"))


def _r22_cpcv_vs_control(monthly, combo_meta):
    from itertools import combinations
    groups=np.array_split(np.arange(len(monthly)),8)
    rows=[]
    for a,b in combinations(range(8),2):
        loc=np.sort(np.r_[groups[a],groups[b]])
        q=monthly.iloc[loc]
        c=q[_R22_CONTROL].dropna()
        csh=_monthly_sharpe0(c); cso=_monthly_sortino0(c)
        for _,meta in combo_meta.iterrows():
            name=meta["Strategy"]
            x=q[name].dropna()
            rows.append({
                "Group1":a+1,"Group2":b+1,"Strategy":name,
                "SleeveCount":int(meta["SleeveCount"]),"Months":len(x),
                "ControlSharpe0":csh,"OverlaySharpe0":_monthly_sharpe0(x),
                "DeltaSharpe0":_monthly_sharpe0(x)-csh,
                "ControlSortino0":cso,"OverlaySortino0":_monthly_sortino0(x),
                "DeltaSortino0":_monthly_sortino0(x)-cso,
                "SharpeWin":bool(_monthly_sharpe0(x)>csh),
                "SortinoWin":bool(_monthly_sortino0(x)>cso),
                "MeanActiveMonthly":float((q[name]-q[_R22_CONTROL]).mean()),
            })
    detail=pd.DataFrame(rows)
    summary=detail.groupby("SleeveCount",as_index=False).agg(
        Rows=("Strategy","count"),
        MedianDeltaSharpe=("DeltaSharpe0","median"),
        MedianDeltaSortino=("DeltaSortino0","median"),
        MeanDeltaSharpe=("DeltaSharpe0","mean"),
        MeanDeltaSortino=("DeltaSortino0","mean"),
        SharpeWinShare=("SharpeWin","mean"),
        SortinoWinShare=("SortinoWin","mean"),
        MedianMeanActive=("MeanActiveMonthly","median"),
    ) if len(detail) else pd.DataFrame()
    return detail,summary


def _r22_group_active_summary(metrics, control_row):
    rows=[]
    for n,g in metrics.groupby("SleeveCount"):
        rows.append({
            "SleeveCount":int(n),"Combinations":len(g),
            "Median CAGR":float(g["CAGR"].median()),
            "Median Delta CAGR":float(g["CAGR"].median()-control_row["CAGR"]),
            "Median Sharpe0":float(g["Sharpe0"].median()),
            "Median Delta Sharpe0":float(g["Sharpe0"].median()-control_row["Sharpe0"]),
            "Median Sortino0":float(g["Sortino0"].median()),
            "Median Delta Sortino0":float(g["Sortino0"].median()-control_row["Sortino0"]),
            "Median Daily MaxDD":float(g["Daily MaxDD"].median()),
            "Median Delta MaxDD":float(g["Daily MaxDD"].median()-control_row["Daily MaxDD"]),
            "Median ES5":float(g["Expected Shortfall 5%"].median()),
            "Median Ulcer":float(g["Ulcer Index"].median()),
            "Median Depth x Duration":float(g["Max Depth x Duration"].median()),
            "Median Annualized Turnover":float(g["Annualized OneWay Turnover"].median()),
            "CAGR Win Share":float((g["CAGR"]>control_row["CAGR"]).mean()),
            "Sharpe Win Share":float((g["Sharpe0"]>control_row["Sharpe0"]).mean()),
            "Sortino Win Share":float((g["Sortino0"]>control_row["Sortino0"]).mean()),
            "MaxDD Win Share":float((g["Daily MaxDD"]>control_row["Daily MaxDD"]).mean()),
        })
    return pd.DataFrame(rows).sort_values("SleeveCount")


def _r22_exactness(r6_control, control_rebuilt, sleeve_targets, sleeve_audits,
                   combo_targets, overlay_targets, overlay_daily, overlay_logs,
                   combo_meta):
    control_error=float((r6_control.reindex(control_rebuilt.index)-control_rebuilt).dropna().abs().max())
    sleeve_rule=max(_r21_rule_error(sleeve_targets[h],sleeve_audits[h],h) for h in _R21_HORIZONS)
    combo_sum=max(float((t.sum(axis=1)-1.0).abs().max()) for t in combo_targets.values())
    overlay_sum=max(float((t.sum(axis=1)-1.0).abs().max()) for t in overlay_targets.values())
    blend_error=0.0
    fixed_core_error=0.0
    control_target=pd.DataFrame(0.0,index=next(iter(combo_targets.values())).index,columns=_R16_ASSETS)
    control_target[_R16_FAMILIES]=0.25
    for _, meta in combo_meta.iterrows():
        name=meta["Strategy"]
        base=meta["BaseTemporal"]
        exp=_R22_CORE_WEIGHT*control_target + _R22_SAT_WEIGHT*combo_targets[base]
        blend_error=max(blend_error,float((overlay_targets[name]-exp).abs().to_numpy().max()))
        # Sum of the inherited core contribution is exactly 75% every month.
        fixed_core_error=max(fixed_core_error,abs(float((_R22_CORE_WEIGHT*control_target).sum(axis=1).iloc[0])-_R22_CORE_WEIGHT))
    recon=max(_r16_reconstruction_error(overlay_daily[name],overlay_logs[name]) for name in combo_meta["Strategy"])
    combo_count=abs(len(combo_targets)-15)
    timing_bad=0
    for h in _R21_HORIZONS:
        a=sleeve_audits[h]
        signal=pd.PeriodIndex(a["SignalMonth"],freq="M")
        end=pd.PeriodIndex(a["ScoreEndMonth"],freq="M")
        apply=pd.PeriodIndex(a["ApplyMonth"],freq="M")
        timing_bad += int((end>=signal).sum()+(signal>=apply).sum())
        timing_bad += int((a["CompletedScoreMonths"].astype(int)!=int(h)).sum())
    cutoff_bad=int(pd.DatetimeIndex(overlay_daily.index).max()>_R22_CUTOFF)
    checks=[
        ("Monthly-drift control rebuild equals Frozen 4F EW",control_error,1e-12),
        ("Inherited R21 independent horizon rules reconstruct exactly",sleeve_rule,1e-12),
        ("All 15 temporal combo targets sum to 100%",combo_sum,1e-12),
        ("All 15 R22 overlay targets sum to 100%",overlay_sum,1e-12),
        ("Every R22 target equals 75% Frozen4F core + 25% temporal satellite",blend_error,1e-12),
        ("Frozen core contribution is fixed at exactly 75%",fixed_core_error,1e-12),
        ("Every R22 daily return equals contribution reconstruction",recon,1e-12),
        ("Exactly 15 temporal subsets are generated",float(combo_count),0.0),
        ("Signal timing and DEV cutoff are preserved",float(timing_bad+cutoff_bad),0.0),
    ]
    return pd.DataFrame([{"Check":n,"Error":e,"Tolerance":tol,"PASS":bool(np.isfinite(e) and e<=tol)} for n,e,tol in checks])


def render_r22_frozen4f_temporal_satellite(px_bt, rf_bt, bt_start, bt_end):
    import io,zipfile
    from itertools import combinations

    st.header("🛰️ R22 — Frozen 4F + Temporal Satellite 25% Audit")
    st.caption("Module build: R22-FROZEN4F-TEMPORAL-SAT25 — mechanism transplant / no weight or horizon search")
    st.success(
        "R21公式結果: Exactness 10/10 PASS。独立lookbackの時間的分散は1→2→3 sleeveで再現した一方、standalone Meta-DMはFrozen 4F EWを置換できませんでした。"
    )
    st.info(
        "R22はR21戦略を本体へ昇格させません。Frozen 4F EWを75%コアとして固定し、残り25%だけにR21 temporal portfolioを置きます。"
        "25%は4Fの1 family単位から固定継承し、weight sweepは行いません。"
    )
    st.warning(
        "Primary hypothesis: 1/2/3/4 temporal sleevesをsatellite内で増やすと、Frozen 4Fに対するactive risk-adjusted/tail性能が組合せ全体として改善するか。"
        "全15通りを生成しますが、最良組合せの採用は目的ではありません。DEV cutoff=2026-07-31。"
    )
    if not st.button("R22 Frozen 4F + Temporal Satellite 25%を実行",type="primary",use_container_width=True,key="run_r22_temporal_sat25"):
        return

    p=st.progress(0,text="R22 0/13 — Frozen 4F family NAVを再構築中…")
    r6,family_daily,_,_,_,_,_,_,_=_r6_build(px_bt,rf_bt,bt_start,bt_end)
    family_daily=family_daily[_R16_FAMILIES].dropna().loc[:_R22_CUTOFF]
    cash=_r16_cash_daily(family_daily.index,rf_bt).reindex(family_daily.index).fillna(0.0)
    asset_daily=family_daily.assign(CASH=cash)
    family_monthly=(1.0+family_daily).groupby(family_daily.index.to_period("M")).prod().sub(1.0)
    rf_monthly=_v401_monthly_rf(family_daily,rf_bt).reindex(family_monthly.index)

    p.progress(10,text="R22 1/13 — R21の1M/3M/6M/12M独立sleeve targetを再構築中…")
    sleeve_targets,sleeve_audits={},{}
    for h in _R21_HORIZONS:
        sleeve_targets[h],sleeve_audits[h]=_r21_single_horizon_targets(family_monthly,rf_monthly,h)
    common_months=None
    for t in sleeve_targets.values():
        common_months=t.index if common_months is None else common_months.intersection(t.index)
    if common_months is None or len(common_months)==0:
        st.error("R22 common apply monthsを構築できませんでした。")
        return
    sleeve_targets={h:t.loc[common_months].copy() for h,t in sleeve_targets.items()}
    for h,a in list(sleeve_audits.items()):
        sleeve_audits[h]=a[pd.PeriodIndex(a["ApplyMonth"],freq="M").isin(common_months)].reset_index(drop=True)

    p.progress(20,text="R22 2/13 — 15 temporal satellite targetを機械生成中…")
    combo_targets={}; combo_meta=[]
    for n in range(1,5):
        for hs in combinations(_R21_HORIZONS,n):
            base_label=f"{n}S:{_r21_slug_horizons(hs)}"
            agg=sum(sleeve_targets[h] for h in hs)/float(n)
            combo_targets[base_label]=agg
            combo_meta.append({"BaseTemporal":base_label,"SleeveCount":n,"Horizons":_r21_slug_horizons(hs),
                               "Strategy":f"R22 {base_label}"})
    combo_meta=pd.DataFrame(combo_meta)

    p.progress(30,text="R22 3/13 — 75% Frozen core + 25% temporal targetへ合成中…")
    control_targets=pd.DataFrame(0.0,index=common_months,columns=_R16_ASSETS)
    control_targets[_R16_FAMILIES]=0.25
    control_rebuilt,control_log,control_turn=_r16_monthly_target_portfolio(asset_daily,control_targets,_R22_CONTROL)
    overlay_targets={}; overlay_series={}; overlay_logs={}; overlay_turnovers={}
    for _,meta in combo_meta.iterrows():
        base=meta["BaseTemporal"]; name=meta["Strategy"]
        target=_R22_CORE_WEIGHT*control_targets + _R22_SAT_WEIGHT*combo_targets[base]
        overlay_targets[name]=target
        s,log,turn=_r16_monthly_target_portfolio(asset_daily,target,name)
        overlay_series[name]=s.rename(name); overlay_logs[name]=log; overlay_turnovers[name]=turn

    p.progress(42,text="R22 5/13 — common daily sampleとtail metricsを計算中…")
    overlay_daily=pd.concat([overlay_series[n] for n in combo_meta["Strategy"]],axis=1).dropna()
    common_idx=overlay_daily.index.intersection(control_rebuilt.index)
    overlay_daily=overlay_daily.loc[common_idx]
    control=r6["Frozen 4F EW"].rename(_R22_CONTROL).reindex(common_idx)
    daily=pd.concat([control,overlay_daily],axis=1).dropna()
    episodes=pd.concat([_r12_underwater_episodes(c,daily[c]) for c in daily.columns],ignore_index=True)
    rows=[]
    for _,meta in combo_meta.iterrows():
        name=meta["Strategy"]
        row=_r12_metric_row(name,daily[name],episodes)
        row["SleeveCount"]=int(meta["SleeveCount"]); row["Horizons"]=meta["Horizons"]
        turn=overlay_turnovers[name]
        row["Annualized OneWay Turnover"]=float(turn["OneWayTurnover"].mean()*12.0) if len(turn) else np.nan
        active=daily[name]-daily[_R22_CONTROL]
        row["Active Daily Vol"]=float(active.std(ddof=1)*np.sqrt(252.0))
        row["Active Mean Ann"] = float(active.mean()*252.0)
        row["Information Ratio"] = float(active.mean()/active.std(ddof=1)*np.sqrt(252.0)) if active.std(ddof=1)>0 else np.nan
        rows.append(row)
    metrics=pd.DataFrame(rows)
    control_row=_r12_metric_row(_R22_CONTROL,daily[_R22_CONTROL],episodes)
    control_row.update({"SleeveCount":0,"Horizons":"Control","Annualized OneWay Turnover":float(control_turn["OneWayTurnover"].mean()*12.0) if len(control_turn) else np.nan,
                        "Active Daily Vol":0.0,"Active Mean Ann":0.0,"Information Ratio":np.nan})
    full_metrics=pd.concat([pd.DataFrame([control_row]),metrics],ignore_index=True)
    group_summary=_r22_group_active_summary(metrics,control_row)

    p.progress(55,text="R22 7/13 — CPCV 28をControl対比で監査中…")
    monthly=(1.0+daily).resample("ME").prod(min_count=1)-1.0
    cpcv_detail,cpcv_summary=_r22_cpcv_vs_control(monthly,combo_meta)

    p.progress(66,text="R22 8/13 — Walk-forward 13 blocksを監査中…")
    wf_parts=[]
    for _,meta in combo_meta.iterrows():
        name=meta["Strategy"]
        wf=_v403a_wf(monthly,_R22_CONTROL,name,13)
        wf.insert(0,"Strategy",name); wf.insert(1,"SleeveCount",int(meta["SleeveCount"])); wf.insert(2,"Horizons",meta["Horizons"])
        wf_parts.append(wf)
    wf_detail=pd.concat(wf_parts,ignore_index=True) if wf_parts else pd.DataFrame()
    wf_summary=wf_detail.groupby("SleeveCount",as_index=False).agg(
        Rows=("Strategy","count"),MedianDeltaSortino=("Delta Sortino0","median"),MedianDeltaSharpe=("Delta Sharpe0","median"),
        MeanDeltaSortino=("Delta Sortino0","mean"),PositiveSortinoShare=("Overlay Sortino Win","mean"),PositiveSharpeShare=("Overlay Sharpe Win","mean"),
    ) if len(wf_detail) else pd.DataFrame()

    p.progress(76,text="R22 9/13 — 2020/2022/2025・stress・eraを集計中…")
    year_regimes=_r21_fixed_year_regimes(daily)
    stress=_v403a_stress(daily)
    eras=_r16_fixed_eras(daily)
    annual=_v403a_annual_returns(daily)

    p.progress(84,text="R22 10/13 — turnover cost sensitivityを計算中…")
    turnover_map={_R22_CONTROL:control_turn,**overlay_turnovers}
    cost=_r16_cost_sensitivity(daily,turnover_map)
    turnover_all=pd.concat([control_turn]+[overlay_turnovers[n] for n in combo_meta["Strategy"]],ignore_index=True)

    p.progress(91,text="R22 11/13 — Exactness Auditを実行中…")
    exact=_r22_exactness(r6["Frozen 4F EW"],control_rebuilt,sleeve_targets,sleeve_audits,
                         combo_targets,overlay_targets,overlay_daily,overlay_logs,combo_meta)
    implementation=pd.DataFrame([
        {"Item":"R21 finding inherited","FrozenValue":"Temporal diversification mechanism confirmed; standalone Meta-DM rejected as control replacement","Changed":False},
        {"Item":"Core","FrozenValue":"75% Frozen 4F EW target every apply month","Changed":False},
        {"Item":"Satellite weight","FrozenValue":"25% = one frozen 4F family unit; no weight sweep","Changed":False},
        {"Item":"Temporal horizons","FrozenValue":"1M / 3M / 6M / 12M inherited from R17/R21","Changed":False},
        {"Item":"Temporal sleeve rule","FrozenValue":"independent matched-RF gate -> Top2; one=100%, none=CASH","Changed":False},
        {"Item":"Combination set","FrozenValue":"all 15 non-empty horizon subsets","Changed":False},
        {"Item":"Portfolio execution","FrozenValue":"monthly target reset; natural intra-month drift","Changed":False},
        {"Item":"Primary inference","FrozenValue":"sleeve-count distribution + CPCV/WF active performance vs Frozen 4F; no ex-post best-combo promotion","Changed":False},
        {"Item":"Search","FrozenValue":"no new horizon/threshold/TopN/core-satellite weight/Brake/Promotion search","Changed":False},
        {"Item":"DEV cutoff","FrozenValue":"2026-07-31","Changed":False},
        {"Item":"Official result","FrozenValue":"only user-run exported ZIP","Changed":False},
    ])

    p.progress(96,text="R22 12/13 — 完全監査ZIPを作成中…")
    exports={
        "00_full_tail_metrics.csv":full_metrics,
        "01_sleeve_count_active_summary.csv":group_summary,
        "02_combo_definition.csv":combo_meta,
        "03_all_daily_returns.csv":daily.reset_index(),
        "04_monthly_returns.csv":monthly.reset_index(),
        "05_underwater_episodes.csv":episodes,
        "06_cpcv28_detail_vs_control.csv":cpcv_detail,
        "07_cpcv28_sleeve_count_summary.csv":cpcv_summary,
        "08_walk_forward_13_detail.csv":wf_detail,
        "09_walk_forward_sleeve_count_summary.csv":wf_summary,
        "10_2020_2022_2025_regimes.csv":year_regimes,
        "11_fixed_stress.csv":stress,
        "12_fixed_eras.csv":eras,
        "13_annual_returns.csv":annual,
        "14_turnover.csv":turnover_all,
        "15_cost_sensitivity.csv":cost,
        "16_exactness_audit.csv":exact,
        "17_implementation_audit.csv":implementation,
        "18_family_daily_returns.csv":family_daily.reset_index(),
        "19_family_monthly_returns.csv":family_monthly.reset_index(),
        "20_control_daily_weight_contribution_log.csv":control_log,
    }
    no=21
    for h in _R21_HORIZONS:
        exports[f"{no:02d}_{h}m_signal_audit.csv"]=sleeve_audits[h]; no+=1
        exports[f"{no:02d}_{h}m_monthly_targets.csv"]=sleeve_targets[h].reset_index(); no+=1
    for _,meta in combo_meta.iterrows():
        name=meta["Strategy"]; slug=name.lower().replace(" ","_").replace(":","_").replace("+","_")
        exports[f"{no:02d}_{slug}_monthly_target.csv"]=overlay_targets[name].reset_index(); no+=1
        exports[f"{no:02d}_{slug}_daily_weight_contribution_log.csv"]=overlay_logs[name]; no+=1

    buf=io.BytesIO()
    with zipfile.ZipFile(buf,"w",zipfile.ZIP_DEFLATED) as zf:
        for fn,df in exports.items():
            zf.writestr(fn,df.to_csv(index=False).encode("utf-8-sig"))
        zf.writestr("README.txt",(
            "R22 Frozen 4F + Temporal Satellite 25% Audit\n"
            "Follow-up to official R21 Exactness 10/10 PASS. DEV cutoff=2026-07-31.\n"
            "Control=Frozen 4F EW. Every challenger keeps 75% of the Frozen 4F monthly target and allocates 25% to an R21 temporal combo.\n"
            "25% is inherited from one frozen 4F family unit; there is no core/satellite weight sweep.\n"
            "Temporal horizons=1M/3M/6M/12M; each is an independent matched-RF absolute-gate -> Top2 sleeve, signal t -> apply t+1.\n"
            "All 15 non-empty horizon subsets are generated mechanically; temporal sleeves are equal-weighted inside the 25% satellite.\n"
            "Portfolio targets reset monthly and drift naturally within month.\n"
            "Primary inference is distribution by temporal sleeve count plus CPCV/WF active performance vs Frozen 4F, not ex-post best-combination selection.\n"
            "No new horizon, threshold, TopN, core/satellite weight, Brake, Promotion, or rescue optimization.\n"
            "Only the user-run ZIP returned to the research chat is official.\n"
        ).encode("utf-8"))

    p.progress(100,text="R22 完了 — Exactnessと完全監査ZIPを作成済み")
    pass_count=int(exact["PASS"].sum())
    if pass_count==len(exact):
        st.success(f"R22完了。Exactness Audit {pass_count}/{len(exact)} PASS。ZIPをこのチャットへ送ってください。")
    else:
        st.error(f"R22 Exactness Audit {pass_count}/{len(exact)} PASS。FAILがあるため公式解釈前に実装確認が必要です。")
    st.subheader("1. Primary — sleeve-count active distribution vs Frozen 4F")
