def _fgd_pct(x, digits=2):
    try:
        x=float(x)
        if not np.isfinite(x):
            return "—"
        return f"{x*100:+.{digits}f}%"
    except Exception:
        return "—"


def _fgd_allocation_frame(alloc):
    if not alloc:
        return pd.DataFrame(columns=["Asset","Weight"])
    z=(pd.DataFrame({"Asset":list(alloc.keys()),"Weight":list(alloc.values())})
       .sort_values("Weight",ascending=False).reset_index(drop=True))
    return z


def _fgd_render_allocation_html(alloc):
    if not alloc:
        st.info("現在のAllocationを構築できません。")
        return
    items=[]
    for ticker,w in sorted(alloc.items(), key=lambda kv:(-kv[1],kv[0])):
        items.append(
            f'<div class="fgd-alloc-item"><div class="fgd-alloc-ticker">{ticker}</div>'
            f'<div class="fgd-alloc-weight">{float(w)*100:.1f}%</div></div>'
        )
    st.markdown('<div class="fgd-alloc-grid">'+''.join(items)+'</div>',unsafe_allow_html=True)


def _fgd_metric_cards(cards):
    html=[]
    for title,value,sub in cards:
        html.append(
            '<div class="fgd-kpi">'
            f'<div class="fgd-kpi-title">{title}</div>'
            f'<div class="fgd-kpi-value">{value}</div>'
            f'<div class="fgd-kpi-sub">{sub}</div>'
            '</div>'
        )
    st.markdown('<div class="fgd-kpi-grid">'+''.join(html)+'</div>',unsafe_allow_html=True)


@st.cache_data(show_spinner=False, ttl=86400)
def _erc6_attack75_latest_official_snapshot():
    """Latest official R276 PATCH1 state on the frozen evidence window.

    Display-only reconstruction.  No strategy parameters are changed.
    """
    idx = pd.period_range("2016-02", "2026-07", freq="M")
    l1 = _r15d_layer1_research_monthly().copy()
    if not isinstance(l1.index, pd.PeriodIndex):
        l1.index = pd.to_datetime(l1.index).to_period("M")
    l1 = l1.sort_index()
    a_state = (
        l1["Layer1 New-R181"].astype(float)
        .sub(l1["Layer1 New-R180"].astype(float))
        .abs() > 1e-12
    )

    cand, _, _, _ = _r15d_r235_r195_candidates()
    canonical = {n: f"{f} {n}" for f, n, _ in _R15D_R235_REGISTRY}
    reps_map = {
        "Seiryu": "Full5P-Balanced",
        "Byakko": "FrozenVIX",
        "Suzaku": "TEL-3M/30M",
        "Genbu": "MR-Majority-6D/11M/24M",
    }
    rep_cols = {fam: canonical[name] for fam, name in reps_map.items()}
    reps = pd.DataFrame({fam: pd.Series(cand[col]).astype(float) for fam, col in rep_cols.items()})
    if not isinstance(reps.index, pd.PeriodIndex):
        reps.index = pd.to_datetime(reps.index).to_period("M")
    reps = reps.sort_index().dropna(how="any")

    month = idx[-1]
    pos = reps.index.get_loc(month)
    hist = reps.iloc[pos-6:pos]
    spear = ["Seiryu", "Byakko", "Suzaku"]
    w, err = _r15d_erc_weights(hist[spear].cov().to_numpy())
    if not np.isfinite(err) or err > 1e-7:
        raise RuntimeError(f"ERC6 solver parity failed at {month}: {err}")
    ww = pd.Series({
        "Seiryu": 0.75 * float(w[0]),
        "Byakko": 0.75 * float(w[1]),
        "Suzaku": 0.75 * float(w[2]),
        "Genbu": 0.25,
    }, dtype=float)
    ast = bool(a_state.reindex([month]).fillna(False).iloc[0])
    if ast:
        ww[:] = 0.0
        ww["Genbu"] = 1.0

    rstart = "2009-01-01"
    rend = "2026-08-10"
    needed = ["QQQ","QLD","LQD","GLD","TLT","SPXL","TQQQ","TECL","XLU","^VIX","SPY","XLK","TMF","TMV"]
    px = get_close(tuple(needed), rstart, rend)
    rf = get_self_backtest_rf(rstart, rend)
    suite = _r15t_build_4f_suite_live_inputs(px, rf, rstart, rend)
    states = suite["states"].copy()
    states["Month"] = states.index.to_period("M")
    ms = states.groupby("Month")[["Turbo", "Choose TECL"]].first().astype(bool)
    turbo = bool(ms.loc[month, "Turbo"])
    choose_tecl = bool(ms.loc[month, "Choose TECL"])

    mode = "ERC6_NORMAL"
    attack_asset = ""
    family_alloc = ww.copy()
    if ast:
        mode = "A_STATE_GENBU100"
    elif turbo:
        attack_asset = "TECL" if choose_tecl else "TQQQ"
        mode = f"ATTACK75_{attack_asset}"
        raw = ww[["Byakko", "Suzaku", "Genbu"]].copy()
        residual = raw / float(raw.sum())
        family_alloc[:] = 0.0
        family_alloc["Attack75 " + attack_asset] = 0.75
        for fam, val in residual.items():
            family_alloc[fam] = 0.25 * float(val)
        family_alloc = family_alloc[family_alloc > 1e-12]

    return {
        "month": month,
        "mode": mode,
        "a_state": ast,
        "turbo": turbo,
        "choose_tecl": choose_tecl,
        "attack_asset": attack_asset,
        "allocation": family_alloc.to_dict(),
    }


def _r15f_health_strip(h):
    """Compact traffic-light health strip. Display state only; hide raw G1/G2 numbers."""
    def cell(label, color, sub):
        return (f'<div style="background:#f7f7f8;border-radius:14px;padding:12px 8px;text-align:center;min-width:0">'
                f'<div style="font-size:.82rem;opacity:.65">{label}</div>'
                f'<div style="font-size:1.65rem;font-weight:800;line-height:1.25;color:{color}">●</div>'
                f'<div style="font-size:.68rem;opacity:.55">{sub}</div></div>')
    html=('<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:.35rem 0 1rem">'
          +cell("G1",h.get("g1_color",_R15AE_NEUTRAL),"long-term")
          +cell("G2",h.get("g2_color",_R15AE_NEUTRAL),"erosion")
          +cell("P",h.get("p_color",_R15AE_NEUTRAL),"overall")+'</div>')
    st.markdown(html,unsafe_allow_html=True)


@st.cache_data(show_spinner=False, ttl=1800)
def _erc6_attack75_forward_monitor(asof, _px_signal, _rf_signal):
    """Forward-OOS operational monitor.

    Frozen DEV evidence ends 2026-07.  This monitor extends only rules that can
    be reconstructed from frozen code and labels each component independently.
    No proxy series is silently accepted: historical overlap must pass a parity
    check before a forward value is marked EXACT.
    """
    z = _erc6_attack75_latest_official_snapshot()
    now = pd.Timestamp(asof).to_period("M")
    dev_end = pd.Period("2026-07", "M")
    target_month = now
    signal_month = target_month - 1

    # ---- canonical frozen history used as the parity reference ----
    cand, _, _, _ = _r15d_r235_r195_candidates()
    canonical = {n: f"{f} {n}" for f, n, _ in _R15D_R235_REGISTRY}
    hist = pd.DataFrame({
        "Seiryu": cand[canonical["Full5P-Balanced"]].astype(float),
        "Byakko": cand[canonical["FrozenVIX"]].astype(float),
        "Suzaku": cand[canonical["TEL-3M/30M"]].astype(float),
        "Genbu": cand[canonical["MR-Majority-6D/11M/24M"]].astype(float),
    })
    hist.index = pd.PeriodIndex(hist.index, freq="M")

    start = "2009-01-01"
    end = (pd.Timestamp(asof) + pd.Timedelta(days=10)).strftime("%Y-%m-%d")
    needed = ("QQQ","QLD","LQD","GLD","TLT","SPXL","TQQQ","TECL","XLU","^VIX","SPY","XLK","TMF","TMV")
    px = _px_signal.copy().sort_index()
    missing = [c for c in needed if c not in px.columns]
    if missing:
        px = px.join(get_close(tuple(missing), start, end), how="outer").sort_index().ffill()
    rf = _rf_signal

    def mcomp(x):
        x = pd.Series(x).dropna().astype(float)
        if x.empty: return pd.Series(dtype=float)
        out = (1.0+x).groupby(x.index.to_period("M")).prod(min_count=1)-1.0
        out.index = pd.PeriodIndex(out.index, freq="M")
        return out

    live = {}
    holdings = {}
    parity = {}

    # Seiryu — exact frozen R113 Full5P Balanced generator.
    try:
        se = _r15z_full5p_dashboard_monthly(end)["Full5P × QQQ/QLD 50:50 × GLD"].astype(float)
        se.index = pd.PeriodIndex(se.index, freq="M")
        live["Seiryu"] = se
        ov = hist.index.intersection(se.index)
        parity["Seiryu"] = float((hist.loc[ov,"Seiryu"]-se.loc[ov]).abs().max()) if len(ov) else np.inf
        # Exact current R113 Full5P majority state for ticker expansion.
        cl=px[["LQD","QQQ","QLD","GLD"]].sort_index().ffill()
        op=get_open(("QQQ","QLD","GLD"),start,end).sort_index().ffill()
        ix=pd.DatetimeIndex(cl.index.intersection(op.index)).sort_values(); lqd=cl["LQD"].reindex(ix).dropna()
        tds=_model_trade_dates(ix,"QQQ-MOM"); tdv=[d for d in tds if pd.Timestamp(d).to_period("M")==target_month]
        if tdv:
            td=pd.Timestamp(tdv[0]); month_start=pd.Timestamp(td.year,td.month,1); end0=last_trading_day_before(pd.DatetimeIndex(lqd.index),month_start)
            votes=[]
            for dd in (10,54):
                mom,a,b=trading_return(lqd,end0,dd); votes.append(bool(mom>=rf_return(rf,a,b)))
            me0=pd.DataFrame({"value":lqd.values,"date":lqd.index},index=lqd.index); me0["period"]=me0.index.to_period("M")
            me=me0.groupby("period",sort=True).tail(1).set_index("period")[["value","date"]]; me.index=pd.PeriodIndex(me.index,freq="M")
            latest=target_month-1
            # canonical EX1 6M/12M and RAW 24M; same as _r15z_full5p_dashboard_monthly.
            days=pd.date_range(ix.min().normalize()-pd.Timedelta(days=1),ix.max().normalize(),freq="D"); rfs=pd.Series(rf).sort_index().astype(float); rr=rfs.reindex(days,method="ffill").bfill().fillna(0.0); rfc=(np.log1p(rr/100.0)/365.25).cumsum()
            def _rfi(a,b):
                a=pd.Timestamp(a).normalize(); b=pd.Timestamp(b).normalize(); return float(np.expm1(float(rfc.loc[b]-rfc.loc[a-pd.Timedelta(days=1)])))
            for n,md in ((6,"EX1"),(12,"EX1"),(24,"RAW")):
                sp=latest-n; ep=latest if md=="RAW" else latest-1
                p0=float(me.loc[sp,"value"]); p1=float(me.loc[ep,"value"]); d0=pd.Timestamp(me.loc[sp,"date"]); d1=pd.Timestamp(me.loc[ep,"date"]); votes.append(bool((p1/p0-1)>=_rfi(d0,d1)))
            risk_on=sum(votes)>=3
            holdings["Seiryu"]={"QQQ":.5,"QLD":.5} if risk_on else {"GLD":1.0}
    except Exception:
        live["Seiryu"] = pd.Series(dtype=float); parity["Seiryu"] = np.inf

    # Byakko — FrozenVIX is reconstructed from the frozen VIX family stack.
    try:
        _, _, fam, h0, _, _, _ = _r15r_build_4f_live_inputs(px, rf, start, end)
        by = mcomp(fam["VIX"])
        live["Byakko"] = by
        ov = hist.index.intersection(by.index)
        parity["Byakko"] = float((hist.loc[ov,"Byakko"]-by.loc[ov]).abs().max()) if len(ov) else np.inf
        # Month-entry VIX holdings: 25% Old15, 25% Old20, 50% New20.
        d = h0.index[h0.index.to_period("M")==target_month]
        if len(d):
            r=h0.loc[d[0]]; a={}
            for col,w in [("Old VIX 15d",.25),("Old VIX 20d",.25),("New VIX 20d",.50)]:
                t=str(r.get(col,""));
                if t and t.lower()!="nan": a[t]=a.get(t,0.0)+w
            holdings["Byakko"] = a
    except Exception:
        live["Byakko"] = pd.Series(dtype=float); parity["Byakko"] = np.inf

    # Suzaku — frozen TEL 3M and 30M are identical two-layer rules with only
    # the declared lookback changed; canonical representative is 50/50 EW.
    def tel_lb(lb):
        need=["TMF","TMV","TQQQ","TECL"]
        cl=px[need].sort_index().ffill()
        op=get_open(tuple(need),start,end).sort_index().ffill()
        idx=pd.DatetimeIndex(op.index).sort_values()
        me=cl[need].resample("ME").last(); mom=me/me.shift(lb)-1.0
        sig=pd.Series(pd.NA,index=me.index,dtype="object")
        valid=mom[need].notna().all(axis=1)
        tmv=valid & (mom["TMV"]>mom["TMF"]); eq=valid & ~tmv
        sig.loc[tmv]="TMV"; sig.loc[eq & (mom["TQQQ"]>mom["TECL"])]="TQQQ"; sig.loc[eq & ~(mom["TQQQ"]>mom["TECL"])]="TECL"
        pos=pd.Series(pd.NA,index=idx,dtype="object")
        for dt,val in sig.dropna().items():
            q=idx[idx>pd.Timestamp(dt)]
            if len(q): pos.loc[q[0]]=val
        pos=pos.ffill(); ar=op.pct_change(fill_method=None); hold=pos.shift(1)
        ret=pd.Series(np.nan,index=idx,dtype=float)
        for a in need:
            mask=hold.eq(a); ret.loc[mask]=ar.loc[mask,a]
        return ret.dropna(),pos
    try:
        r3,p3=tel_lb(3); r30,p30=tel_lb(30)
        su=mcomp(.5*r3.reindex(r3.index.union(r30.index))+.5*r30.reindex(r3.index.union(r30.index)))
        live["Suzaku"] = su
        ov=hist.index.intersection(su.index)
        parity["Suzaku"] = float((hist.loc[ov,"Suzaku"]-su.loc[ov]).abs().max()) if len(ov) else np.inf
        d3=p3.index[p3.index.to_period("M")==target_month]; d30=p30.index[p30.index.to_period("M")==target_month]
        if len(d3) and len(d30):
            a={}; t3=str(p3.loc[d3[0]]); t30=str(p30.loc[d30[0]])
            a[t3]=a.get(t3,0)+.5; a[t30]=a.get(t30,0)+.5; holdings["Suzaku"]=a
    except Exception:
        live["Suzaku"] = pd.Series(dtype=float); parity["Suzaku"] = np.inf

    # Genbu — frozen Majority generator: 6 trading-day / 11M / 24M LQD-vs-RF
    # risk states, majority vote, weekly signal -> next-session TQQQ/XLU holding.
    # It is accepted only if its DEV overlap reproduces the official artifact.
    try:
        cl=px[["LQD","TQQQ","XLU"]].sort_index().ffill(); idx=pd.DatetimeIndex(cl.index)
        op=get_open(("TQQQ","XLU"),start,end).sort_index().ffill(); ridx=pd.DatetimeIndex(op.index)
        lqd=cl["LQD"].dropna(); rfs=pd.Series(rf).sort_index().astype(float)
        # use Friday-known signal, enter next available open
        fridays=pd.Series(index=idx,data=idx).groupby(idx.to_period("W-FRI")).last().dropna().values
        target=pd.Series(pd.NA,index=ridx,dtype="object")
        for sd in pd.DatetimeIndex(fridays):
            if sd not in lqd.index: continue
            votes=[]
            # 6 trading days
            loc=lqd.index.get_loc(sd)
            if isinstance(loc,(int,np.integer)) and loc>=6:
                a=lqd.index[loc-6]; pr=float(lqd.loc[sd]/lqd.loc[a]-1)
                try: rr=float(rf_return(rf,a,sd))
                except Exception: rr=0.0
                votes.append(pr < rr)
            # 11M and 24M raw calendar-month endpoint convention
            for n in (11,24):
                a0=sd-pd.DateOffset(months=n)
                prior=lqd.index[lqd.index<=a0]
                if len(prior):
                    a=prior[-1]; pr=float(lqd.loc[sd]/lqd.loc[a]-1)
                    try: rr=float(rf_return(rf,a,sd))
                    except Exception: rr=0.0
                    votes.append(pr < rr)
            if len(votes)==3:
                q=ridx[ridx>sd]
                if len(q): target.loc[q[0]]="XLU" if sum(votes)>=2 else "TQQQ"
        target=target.ffill(); ar=op.pct_change(fill_method=None); hold=target.shift(1)
        gr=pd.Series(np.nan,index=ridx,dtype=float)
        for a in ("TQQQ","XLU"):
            mask=hold.eq(a); gr.loc[mask]=ar.loc[mask,a]
        ge=mcomp(gr.dropna()); live["Genbu"]=ge
        ov=hist.index.intersection(ge.index)
        parity["Genbu"] = float((hist.loc[ov,"Genbu"]-ge.loc[ov]).abs().max()) if len(ov) else np.inf
        d=target.index[target.index.to_period("M")==target_month]
        if len(d) and pd.notna(target.loc[d[0]]): holdings["Genbu"]={str(target.loc[d[0]]):1.0}
    except Exception:
        live["Genbu"] = pd.Series(dtype=float); parity["Genbu"] = np.inf

    # Historical parity is an audit diagnostic, not an operational gate.
    # The frozen DEV artifacts are pinned through 2026-07, while live vendor
    # histories can be revised afterwards.  Blocking a new monthly signal on
    # byte/numerical identity to a historical download would therefore make a
    # frozen-rule forward monitor unusable.  Operational readiness instead
    # requires the frozen-rule generator to produce the completed t-1 month.
    exact={k: bool(np.isfinite(v) and v<=1e-8) for k,v in parity.items()}
    ready={k: bool(signal_month in live.get(k,pd.Series(dtype=float)).index and
                  pd.notna(live.get(k,pd.Series(dtype=float)).get(signal_month,np.nan)))
           for k in hist.columns}

    # Official DEV remains immutable.  Only post-cutoff months generated by the
    # frozen rule are appended; historical parity drift is retained separately
    # for audit and never written back into DEV.
    reps=hist.copy()
    for fam in reps.columns:
        if ready.get(fam,False):
            for m,v in live[fam].items():
                if m>dev_end and m<target_month and pd.notna(v): reps.loc[m,fam]=float(v)
    reps=reps.sort_index()

    # ERC6 for operational month uses six completed months ending signal_month.
    family_alloc=None; asset_alloc=None; mode="PENDING"; attack_asset=""; turbo=False; choose_tecl=False
    all_forward_exact=all(ready.get(f,False) and signal_month in reps.index and pd.notna(reps.loc[signal_month,f]) for f in reps.columns)

    # Frozen R180/R181 A-state, reconstructed directly from the Master rule:
    # prior Spear 1M < 0 AND prior 12M Shield return > prior 12M Spear return.
    # All inputs are completed t-1 information; no threshold or lookback is changed.
    def _a_state_for(month):
        pm=month-1
        need=pd.period_range(pm-11,pm,freq="M")
        if not all(x in reps.index for x in need): return None
        spear=reps[["Seiryu","Byakko","Suzaku"]].mean(axis=1)
        shield=reps["Genbu"]
        if pd.isna(spear.get(pm,np.nan)): return None
        sp12=float((1.0+spear.reindex(need)).prod()-1.0)
        sh12=float((1.0+shield.reindex(need)).prod()-1.0)
        return bool(float(spear.loc[pm])<0.0 and sh12>sp12)

    a_state_forward=_a_state_for(target_month)

    suite=_r15t_build_4f_suite_live_inputs(px,rf,start,end)
    stt=suite["states"].copy(); stt["M"]=stt.index.to_period("M")
    sm=stt.groupby("M")[["Turbo","Choose TECL"]].first().astype(bool)

    def _family_alloc_for(month):
        pm=month-1
        if pm not in reps.index or reps.loc[pm].isna().any(): return None,None,False,False,""
        h6=reps.loc[pm-5:pm,["Seiryu","Byakko","Suzaku"]]
        if len(h6)!=6 or h6.isna().any().any(): return None,None,False,False,""
        ast=_a_state_for(month)
        if ast is None: return None,None,False,False,""
        w,err=_r15d_erc_weights(h6.cov().to_numpy())
        if not np.isfinite(err) or err>1e-7: return None,None,False,False,""
        base=pd.Series({"Seiryu":.75*w[0],"Byakko":.75*w[1],"Suzaku":.75*w[2],"Genbu":.25},dtype=float)
        if ast: return {"Genbu":1.0},"A_STATE_GENBU100",False,False,""
        tb=bool(sm.loc[month,"Turbo"]) if month in sm.index else False
        ct=bool(sm.loc[month,"Choose TECL"]) if month in sm.index else False
        if tb:
            atk="TECL" if ct else "TQQQ"; raw=base[["Byakko","Suzaku","Genbu"]]; residual=raw/raw.sum()
            fa={"Attack75 "+atk:.75,**{k:.25*float(v) for k,v in residual.items()}}
            return fa,"ATTACK75_"+atk,tb,ct,atk
        return base.to_dict(),"ERC6_NORMAL",tb,ct,""

    if all_forward_exact and a_state_forward is not None:
        family_alloc,mode,turbo,choose_tecl,attack_asset=_family_alloc_for(target_month)
        # expand family allocation into actual tickers
        if family_alloc is not None:
            aa={}
            for fam,wf in family_alloc.items():
                if fam.startswith("Attack75 "):
                    t=fam.split()[-1]; aa[t]=aa.get(t,0)+float(wf); continue
                for t,wa in holdings.get(fam,{}).items(): aa[t]=aa.get(t,0)+float(wf)*float(wa)
            if aa and abs(sum(aa.values())-1)<1e-6: asset_alloc=aa
    previous_family_alloc,previous_mode,_,_,_=_family_alloc_for(target_month-1)

    rows=[]
    for m in pd.period_range(dev_end+1,target_month,freq="M"):
        completed=m<target_month
        row={"Month":str(m),"Classification":"Real Forward OOS","DEV retune":"NO"}
        for fam,label in [("Seiryu","Seiryu Full5P-Balanced"),("Byakko","Byakko FrozenVIX"),("Suzaku","Suzaku TEL-3M/30M"),("Genbu","Genbu Majority")]:
            if not completed: state="IN PROGRESS"
            elif m in live[fam].index and pd.notna(live[fam].loc[m]): state="LIVE RULE"
            else: state="MISSING"
            row[label]=state
        ast=_a_state_for(m) if completed else None
        row["A-state"]=("ON" if ast else "OFF") if ast is not None else "IN PROGRESS"
        row["Hybrid allocation"]="EXACT" if (m==target_month and family_alloc is not None) else ("LOCKED" if completed else "IN PROGRESS")
        rows.append(row)

    # Previous exact allocation remains official July until forward state engine is exact.
    # Real Forward OOS monthly returns.  Completed forward months and the
    # current MTD are calculated from the frozen month-entry allocation; they
    # are display/monitoring outputs only and never feed back into DEV.
    forward_monthly={}
    forward_gense_monthly={}
    try:
        # Monthly open-to-open/available-session returns for Attack75 assets.
        atk_open=get_open(("TQQQ","TECL"),start,end).sort_index().ffill()
        atk_daily=atk_open.pct_change(fill_method=None)
        atk_monthly={a:mcomp(atk_daily[a].dropna()) for a in ("TQQQ","TECL")}

        # live[] already contains frozen-rule family monthly returns, including
        # the current partial month when market data are available.
        live_frame=pd.concat({k:v for k,v in live.items()},axis=1).sort_index()

        def _realized_for_month(m):
            fa,md,tb,ct,atk=_family_alloc_for(m)
            if fa is None: return np.nan
            total=0.0
            for block,w in fa.items():
                w=float(w)
                if block.startswith("Attack75 "):
                    t=block.split()[-1]
                    rr=atk_monthly.get(t,pd.Series(dtype=float)).get(m,np.nan)
                else:
                    rr=live_frame.get(block,pd.Series(dtype=float)).get(m,np.nan)
                if pd.isna(rr): return np.nan
                total += w*float(rr)
            return float(total)

        def _seiryu_holdings_for_month(m):
            # Same frozen Full5P month-entry state used above, evaluated for m.
            month_start=pd.Timestamp(m.start_time); end0=last_trading_day_before(pd.DatetimeIndex(lqd.index),month_start)
            votes=[]
            for dd in (10,54):
                mom,a,b=trading_return(lqd,end0,dd); votes.append(bool(mom>=rf_return(rf,a,b)))
            latest=m-1
            for n,md in ((6,"EX1"),(12,"EX1"),(24,"RAW")):
                sp=latest-n; ep=latest if md=="RAW" else latest-1
                p0=float(me.loc[sp,"value"]); p1=float(me.loc[ep,"value"]); d0=pd.Timestamp(me.loc[sp,"date"]); d1=pd.Timestamp(me.loc[ep,"date"])
                votes.append(bool((p1/p0-1)>=_rfi(d0,d1)))
            return {"QQQ":.5,"QLD":.5} if sum(votes)>=3 else {"GLD":1.0}

        def _holdings_for_month(fam,m):
            if fam=="Seiryu":
                return _seiryu_holdings_for_month(m)
            if fam=="Byakko":
                dd=h0.index[h0.index.to_period("M")==m]
                if not len(dd): return None
                r=h0.loc[dd[0]]; a={}
                for col,w0 in [("Old VIX 15d",.25),("Old VIX 20d",.25),("New VIX 20d",.50)]:
                    t=str(r.get(col,""))
                    if t and t.lower()!="nan": a[t]=a.get(t,0.0)+w0
                return a or None
            if fam=="Suzaku":
                d3=p3.index[p3.index.to_period("M")==m]; d30=p30.index[p30.index.to_period("M")==m]
                if not len(d3) or not len(d30): return None
                a={}; t3=str(p3.loc[d3[0]]); t30=str(p30.loc[d30[0]])
                a[t3]=a.get(t3,0.0)+.5; a[t30]=a.get(t30,0.0)+.5
                return a
            if fam=="Genbu":
                dd=target.index[target.index.to_period("M")==m]
                return {str(target.loc[dd[0]]):1.0} if len(dd) and pd.notna(target.loc[dd[0]]) else None
            return None

        # v77: preserve the prior-month Canonical Exact ticker target as well.
        # This closes the 2026-08 Heaven seam without deriving it from Practical/R289.
        previous_asset_alloc={}
        try:
            _pm=target_month-1
            for _b,_wb in (previous_family_alloc or {}).items():
                if str(_b).startswith("Attack75 "):
                    _hh={str(_b).split()[-1]:1.0}
                else:
                    _hh=_holdings_for_month(str(_b),_pm) or {}
                for _t,_wh in _hh.items():
                    previous_asset_alloc[str(_t)]=previous_asset_alloc.get(str(_t),0.0)+float(_wb)*float(_wh)
            if previous_asset_alloc and abs(sum(previous_asset_alloc.values())-1.0)>1e-6:
                previous_asset_alloc={}
        except Exception:
            previous_asset_alloc={}

        def _realized_gense_for_month(m):
            # Mirror the audited R285/R289 attribution exactly: construct the
            # month-entry executable ticker target, apply frozen R289, then
            # attribute each practical ticker bucket back to its frozen source
            # blocks pro-rata. Family-native intramonth switching stays intact.
            fa,md,tb,ct,atk=_family_alloc_for(m)
            if fa is None: return np.nan
            contrib={}; blockret={}
            for b,wb in fa.items():
                if b.startswith("Attack75 "):
                    t=b.split()[-1]; hh={t:1.0}; rv=atk_monthly.get(t,pd.Series(dtype=float)).get(m,np.nan)
                else:
                    hh=_holdings_for_month(b,m); rv=live_frame.get(b,pd.Series(dtype=float)).get(m,np.nan)
                if not hh or pd.isna(rv): return np.nan
                blockret[b]=float(rv)
                for t,wh in hh.items(): contrib[(b,t)]=float(wb)*float(wh)
            exact_t={}
            for (b,t),v in contrib.items(): exact_t[t]=exact_t.get(t,0.0)+v
            q=_kirin_quantize_10pct(exact_t)
            if not q: return np.nan
            eff={b:0.0 for b in fa}
            for t,qt in q.items():
                src={b:v for (b,tt),v in contrib.items() if tt==t and v>0}; den=sum(src.values())
                if den>0:
                    for b,v in src.items(): eff[b]+=float(qt)*v/den
            return float(sum(float(eff.get(b,0.0))*blockret[b] for b in fa))

        for m in pd.period_range(dev_end+1,target_month,freq="M"):
            rr=_realized_for_month(m)
            if pd.notna(rr): forward_monthly[m]=float(rr)
            rg=_realized_gense_for_month(m)
            if pd.notna(rg): forward_gense_monthly[m]=float(rg)
    except Exception:
        forward_monthly={}
        forward_gense_monthly={}

    # Month-by-month frozen mode labels for operational return cards.
    mode_history={}
    for _m in pd.period_range(max(reps.index.min()+6, pd.Period("2015-01","M")), target_month, freq="M"):
        try:
            _fa,_md,_tb,_ct,_atk=_family_alloc_for(_m)
            if _fa is not None:
                mode_history[_m]={"mode":_md,"a_state":bool(_md=="A_STATE_GENBU100"),"booster":bool(_tb),"attack_asset":_atk or ""}
        except Exception:
            pass

    result=dict(z)
    result.update({
        "operational_month":target_month,"signal_month":signal_month,"parity":parity,"component_exact":exact,"component_ready":ready,
        "forward_representatives":reps,"family_holdings":holdings,"a_state_forward":a_state_forward,
        "forward_allocation":family_alloc,"previous_forward_allocation":previous_family_alloc,"previous_forward_mode":previous_mode,
        "asset_allocation":asset_alloc,"previous_asset_allocation":previous_asset_alloc,"forward_mode":mode,
        "forward_turbo":turbo,"forward_choose_tecl":choose_tecl,"forward_attack_asset":attack_asset,
        "forward_monthly_returns":pd.Series(forward_monthly,dtype=float).sort_index(),
        "forward_gense_monthly_returns":pd.Series(forward_gense_monthly,dtype=float).sort_index(),
        "mode_history":mode_history,
    })
    return result,pd.DataFrame(rows)


def _erc6_attack75_donut(title, allocation, subtitle=None, label_mode="legend"):
    import math
    items = list(allocation.items()) if isinstance(allocation, dict) else list(allocation)
    items = [(str(k), float(v)) for k, v in items if pd.notna(v) and float(v) > 1e-12]
    total = sum(v for _, v in items)
    if total <= 0:
        st.info("現在の配分を表示できません。")
        return
    items = [(k, v / total) for k, v in items]
    fallback=["#38BDF8","#A78BFA","#34D399","#F59E0B","#FB7185","#22D3EE","#F97316","#8B5CF6"]
    stops=[]; legend=[]; labels=[]; cursor=0.0
    size=230; center=size/2; radius=82
    for i,(ticker,w) in enumerate(items):
        a=cursor*100; mid=(cursor+w/2)*2*math.pi-math.pi/2; cursor+=w; b=cursor*100
        color=_R15F_SIGNAL_COLORS.get(ticker,fallback[i%len(fallback)])
        stops.append(f"{color} {a:.4f}% {b:.4f}%")
        legend.append(f'<span style="display:flex;align-items:center;gap:.28rem;white-space:nowrap"><i style="display:inline-block;width:.62rem;height:.62rem;border-radius:50%;background:{color}"></i><b>{ticker}</b><span>{w*100:.1f}%</span></span>')
        if label_mode == "inside" and w >= 0.045:
            x=center+radius*math.cos(mid); y=center+radius*math.sin(mid)
            fs="11" if w < .09 else "12"
            labels.append(f'<div style="position:absolute;left:{x:.1f}px;top:{y:.1f}px;transform:translate(-50%,-50%);font-size:{fs}px;font-weight:800;color:#111;background:rgba(255,255,255,.86);padding:2px 5px;border-radius:7px;line-height:1.05;box-shadow:0 1px 3px rgba(0,0,0,.10);white-space:nowrap">{ticker}<br>{w*100:.1f}%</div>')
    html = f"""<div style="width:100%;text-align:center;margin:.25rem 0 1.1rem">
      <div style="text-align:left;font-size:1.12rem;font-weight:700;margin-bottom:.12rem">{title}</div>
      <div style="text-align:left;opacity:.62;font-size:.82rem;margin-bottom:.55rem">{subtitle or ''}</div>
      <div style="position:relative;width:{size}px;height:{size}px;margin:.25rem auto .7rem">
        <div style="position:absolute;inset:0;border-radius:50%;background:conic-gradient({','.join(stops)});display:flex;align-items:center;justify-content:center">
          <div style="width:44%;height:44%;border-radius:50%;background:#fff"></div>
        </div>
        {''.join(labels)}
      </div>
      <div style="display:flex;flex-wrap:wrap;justify-content:center;gap:.3rem .85rem;margin:.15rem 0 .4rem;font-size:.84rem">{''.join(legend)}</div>
    </div>"""
    st.markdown(html, unsafe_allow_html=True)


def _kirin_quantize_10pct(allocation):
    """Frozen R289 Practical 10% execution: prune exact sleeves <10%, renormalize survivors, then 5% grid to 100%."""
    if not isinstance(allocation, dict) or not allocation:
        return {}
    vals={str(k):max(0.0,float(v)) for k,v in allocation.items() if pd.notna(v) and float(v)>1e-12}
    total=sum(vals.values())
    if total<=0:
        return {}
    vals={k:v/total for k,v in vals.items()}
    # R289 frozen rule: exact ticker sleeves strictly below 10% are not traded.
    survivors={k:v for k,v in vals.items() if v>=0.10-1e-12}
    if not survivors:
        return {}
    # Renormalize survivors first, then place them on the deterministic 5% grid.
    stotal=sum(survivors.values())
    survivors={k:v/stotal for k,v in survivors.items()}
    raw_units={k:v/0.05 for k,v in survivors.items()}
    units={k:int(np.floor(u+1e-12)) for k,u in raw_units.items()}
    remain=20-sum(units.values())
    order=sorted(survivors, key=lambda k: (-(raw_units[k]-units[k]), k))
    if order:
        for i in range(max(0,remain)):
            units[order[i % len(order)]]+=1
    out={k:u*0.05 for k,u in units.items() if u>0}
    if out and abs(sum(out.values())-1.0)>1e-10:
        return {}
    return out


# Historical helper retained for research-lineage compatibility only.
def _kirin_quantize_5pct(allocation):
    """Historical R287 control: prune exact sleeves <5%, then 5% grid."""
    if not isinstance(allocation, dict) or not allocation:
        return {}
    vals={str(k):max(0.0,float(v)) for k,v in allocation.items() if pd.notna(v) and float(v)>1e-12}
    total=sum(vals.values())
    if total<=0:
        return {}
    vals={k:v/total for k,v in vals.items()}
    survivors={k:v for k,v in vals.items() if v>=0.05-1e-12}
    if not survivors:
        return {}
    raw_units={k:v/0.05 for k,v in survivors.items()}
    units={k:int(np.floor(u+1e-12)) for k,u in raw_units.items()}
    remain=20-sum(units.values())
    order=sorted(survivors, key=lambda k: (-(raw_units[k]-units[k]), k))
    if order:
        for i in range(max(0,remain)):
            units[order[i % len(order)]]+=1
    return {k:u*0.05 for k,u in units.items() if u>0}


