def _kirin_hanko_live_target(asof, px_signal, rf_signal):
    """Frozen KRO/R314 live decision -> exact override -> R289. Fail-closed."""
    z,_ = _erc6_attack75_forward_monitor(asof, px_signal, rf_signal)
    base_exact = z.get("asset_allocation") or {}
    base_live = _kirin_quantize_10pct(base_exact)
    opm = pd.Period(z["operational_month"], freq="M")
    names=["QQQ","TLT","TQQQ","TECL","^VIX","XLK"]
    start="2009-01-01"; end=(pd.Timestamp(asof)+pd.Timedelta(days=2)).strftime("%Y-%m-%d")
    px=get_close(names,start,end).sort_index().ffill()
    me=px.groupby(px.index.to_period("M")).last()
    rows=[]
    for m in sorted(me.index):
        if m>=opm: break
        p=m-1
        if any(x not in me.index for x in [p,p-1,p-3,p-6]): continue
        tlt3=float(me.loc[p,"TLT"]/me.loc[p-3,"TLT"]-1); vix=float(me.loc[p,"^VIX"])
        inf=float(me.loc[p,"XLK"]/me.loc[p-1,"XLK"]-1)-float(me.loc[p,"XLK"]/me.loc[p-3,"XLK"]-1)
        pp=p-1
        if pp-1 not in me.index or pp-3 not in me.index: continue
        pinf=float(me.loc[pp,"XLK"]/me.loc[pp-1,"XLK"]-1)-float(me.loc[pp,"XLK"]/me.loc[pp-3,"XLK"]-1)
        if not ((tlt3<=0) and (vix<=30) and (inf>pinf)): continue
        q6=float(me.loc[p,"QQQ"]/me.loc[p-6,"QQQ"]-1); x6=float(me.loc[p,"XLK"]/me.loc[p-6,"XLK"]-1)
        asset="TECL" if x6>q6 else "TQQQ"
        rows.append((m,float(me.loc[p,asset]/me.loc[p-6,asset]-1),inf,asset))
    p=opm-1
    if any(x not in me.index for x in [p,p-1,p-3,p-6]):
        return {"status":"FAIL-CLOSED","fire":None,"asset":None,"exact":{},"execution":{}}
    tlt3=float(me.loc[p,"TLT"]/me.loc[p-3,"TLT"]-1); vix=float(me.loc[p,"^VIX"])
    inf=float(me.loc[p,"XLK"]/me.loc[p-1,"XLK"]-1)-float(me.loc[p,"XLK"]/me.loc[p-3,"XLK"]-1)
    pp=p-1
    pinf=float(me.loc[pp,"XLK"]/me.loc[pp-1,"XLK"]-1)-float(me.loc[pp,"XLK"]/me.loc[pp-3,"XLK"]-1)
    blocked=bool((tlt3<=0) and (vix<=30) and (inf>pinf))
    asset=None; rank="N/A"; cut_high=None; selected6=None; fire=False
    if blocked:
        q6=float(me.loc[p,"QQQ"]/me.loc[p-6,"QQQ"]-1); x6=float(me.loc[p,"XLK"]/me.loc[p-6,"XLK"]-1)
        asset="TECL" if x6>q6 else "TQQQ"
        selected6=float(me.loc[p,asset]/me.loc[p-6,asset]-1)
        hist=[r[1] for r in rows]
        if len(hist)<9:
            return {"status":"FAIL-CLOSED","fire":None,"asset":asset,"exact":{},"execution":{}}
        cut_low=float(pd.Series(hist).quantile(1/3)); cut_high=float(pd.Series(hist).quantile(2/3))
        rank="LOW" if selected6<=cut_low else ("MID" if selected6<=cut_high else "HIGH")
        fire=bool(rank=="HIGH" and inf>=0)
    exact=dict(base_exact)
    if fire:
        exact={k:.25*float(v) for k,v in base_exact.items()}
        exact[asset]=exact.get(asset,0.0)+.75
    execution=_kirin_quantize_10pct(exact)
    return {"status":"PASS","fire":fire,"asset":asset,"rank":rank,"selected6m":selected6,
            "cut_high":cut_high,"inflection":inf,"blocked":blocked,
            "exact":exact,"execution":execution,"base_execution":base_live,
            "operator_order":"Tenkai -> HANKO(KRO/R314) -> R289"}


