            _prev_month = month - 1
            _dates = pd.DatetimeIndex(px_signal.index)
            _prev_dates = _dates[_dates.to_period("M") <= _prev_month]
            if len(_prev_dates):
                _prev_asof = pd.Timestamp(_prev_dates.max())
