        monthly=pd.concat([hybrid.rename("麒麟「天界」"),gense.rename("麒麟「現世」"),spy_m.rename("SPY"),tqqq_m.rename("TQQQ")],axis=1); monthly.index=pd.PeriodIndex(monthly.index,freq="M")
        opm=pd.Period(month,freq="M"); prevm=opm-1
