        ytd_t=_ytd("麒麟「天界」"); ytd_g=_ytd("麒麟「現世」"); ytd_s=_ytd("SPY"); ytd_q=_ytd("TQQQ")
        st.markdown('<div style="font-size:1.65rem;font-weight:760;margin:1.15rem 0 .15rem">月次リターン</div>',unsafe_allow_html=True)
