        st.markdown('<div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:.55rem 0 .55rem">'+_metric_card2(f"最新 {opm} MTD*",mtd_t,mtd_g)+_metric_card2(f"前月 {prevm}",prev_t,prev_g)+_metric_card2(f"{opm.year} YTD*",ytd_t,ytd_g)+'</div>',unsafe_allow_html=True)
