        # v132 — canonical Python analytics payload consumed by Fast Drawdowns / Annual Returns.
        # These values are derived once here from the canonical Python monthly series;
        # Fast remains display-only for these pages.
        def _v132_analytics_from_history(_history):
            _out = {}
            for _name, _rows in (_history or {}).items():
                try:
                    _idx = pd.PeriodIndex([str(x[0])[:7] for x in _rows], freq="M")
                    _ret = pd.Series([float(x[1]) / 100.0 for x in _rows], index=_idx, dtype=float)
                    _ret = _ret.replace([np.inf, -np.inf], np.nan).dropna().sort_index()
                    if _ret.empty:
                        continue
                    _wealth = (1.0 + _ret).cumprod()
                    _dd = (_wealth / _wealth.cummax() - 1.0) * 100.0
                    _annual = ((1.0 + _ret).groupby(_ret.index.year).prod() - 1.0) * 100.0
                    _out[_name] = {
                        "drawdown": [[str(_m), round(float(_v), 8)] for _m, _v in _dd.items()],
                        "annual": [[str(int(_y)), round(float(_v), 8)] for _y, _v in _annual.items()],
                    }
                except Exception as _e:
                    raise RuntimeError(f"v132 analytics build failed for {_name}: {_e}") from _e
            return _out

        _fast_performance["analytics"] = _v132_analytics_from_history(_perf_history)
        _v132_required = [n for n in _perf_history if n in _fast_performance["analytics"]]
        if len(_v132_required) != len(_perf_history):
            raise RuntimeError("v132 FAIL-CLOSED: analytics coverage mismatch")

