            try:
                pb, _ = _pbar_consistency(r, 5)
                pb = float(pb)
                label = _pbar_label(pb)
                color = "GREEN" if pb <= .03 else ("YELLOW" if pb <= .10 else "ORANGE")
                return {"value": pb, "label": label, "color": color}
            except Exception:
                return {"value": None, "label": "INSUFFICIENT", "color": "NEUTRAL"}

