        _base_rows_map={str(r.get("month",""))[:7]:dict(r.get("position") or {}) for r in _v74_trade.get("麒麟（現世）",[])}
        for _fm in pd.period_range(pd.Period("2026-08","M"),pd.Period(opm,freq="M"),freq="M"):
            _mk=str(_fm)
