    # v3.93 — Strategy E: Sequential Absolute→Relative Dual Momentum
    # Fixed hypothesis; no sweep / no rescue tuning.
    # All screens use 12M-1M, chosen ex ante as the conventional DM horizon.
    # Layer 1: LQD absolute momentum vs matched RF.
    #   weak -> GLD
    #   strong -> Layer 2: SPY vs XLU relative momentum.
    #       XLU stronger -> XLU
    #       SPY stronger -> Layer 3: TQQQ vs TECL relative momentum.
    #           winner -> TQQQ / TECL
    # Month-end signal -> next first tradable OPEN, Open-to-Open.
    # ================================================================
    def _v393_seq_dm(px_close, rf_bt, start, end):
        need=['LQD','GLD','SPY','XLU','TQQQ','TECL']
        c=px_close.reindex(columns=[x for x in need if x in px_close.columns]).copy()
        miss=[x for x in need if x not in c.columns]
        if miss:
            c=c.join(get_close(tuple(miss),start,end),how='outer')
        c=c.sort_index().ffill()
        o=get_open(tuple(need),start,end).sort_index().ffill()
        me=c[need].resample('ME').last()
        mom=me.shift(1)/me.shift(12)-1.0  # 12M-1M

        # matched RF over exactly the same t-12 month-end -> t-1 month-end interval.
        # IMPORTANT: rf_bt is an ANNUALIZED T-bill YIELD (%) series, not daily returns.
        # Therefore it must go through the app's canonical rf_return() converter.
        rf_src=pd.Series(rf_bt).copy() if not isinstance(rf_bt,pd.Series) else rf_bt.copy()
        rf_src.index=pd.DatetimeIndex(pd.to_datetime(rf_src.index))
        rf_src=rf_src.sort_index().astype(float)
        rf_12m1m=pd.Series(np.nan,index=me.index,dtype=float,name='RF_12M1M')
        for i in range(12,len(me.index)):
            s0=me.index[i-12]
            s1=me.index[i-1]
            rf_12m1m.iloc[i]=rf_return(rf_src,s0,s1)

        valid=mom.notna().all(axis=1) & rf_12m1m.notna()
        sig=pd.Series(pd.NA,index=me.index,dtype='object',name='StrategyE_Signal')
        l1=valid & (mom['LQD'] < rf_12m1m)
        sig.loc[l1]='GLD'
        risk=valid & ~l1
        l2=risk & (mom['XLU'] > mom['SPY'])
        sig.loc[l2]='XLU'
        eq=risk & ~l2
        sig.loc[eq & (mom['TQQQ'] >= mom['TECL'])]='TQQQ'
        sig.loc[eq & (mom['TQQQ'] < mom['TECL'])]='TECL'

        idx=pd.DatetimeIndex(o.index).sort_values()
        pos=pd.Series(pd.NA,index=idx,dtype='object',name='PositionAtOpen')
        aud=[]
        for dt,s in sig.dropna().items():
            cand=idx[idx>pd.Timestamp(dt)]
            if len(cand)==0: continue
            ent=cand[0]; pos.loc[ent]=s
            aud.append({'SignalMonthEnd':dt,'EntryOpen':ent,'Signal':s,
                        'LQD_12M1M':mom.loc[dt,'LQD'],'RF_12M1M':rf_12m1m.loc[dt],
                        'SPY_12M1M':mom.loc[dt,'SPY'],'XLU_12M1M':mom.loc[dt,'XLU'],
                        'TQQQ_12M1M':mom.loc[dt,'TQQQ'],'TECL_12M1M':mom.loc[dt,'TECL']})
        pos=pos.ffill(); ar=o.pct_change(fill_method=None); hold=pos.shift(1)
        r=pd.Series(np.nan,index=idx,dtype=float,name='Strategy E SeqDM')
        for a in need:
            m=hold.eq(a); r.loc[m]=ar.loc[m,a]
        return r.dropna(),pd.DataFrame(aud),sig,pos


    def _v393_alpha_beta(r, spy):
        d=pd.concat([pd.Series(r).rename("r"),pd.Series(spy).rename("spy")],axis=1).dropna()
        if len(d)<60:
            return {"N":len(d),"Beta":np.nan,"Alpha":np.nan,"CorrSPY":np.nan}
        x=d["spy"]; y=d["r"]; vx=float(x.var(ddof=1))
        beta=float(y.cov(x)/vx) if vx>0 else np.nan
        alpha=float((y-beta*x).mean()*252.0) if np.isfinite(beta) else np.nan
        return {"N":len(d),"Beta":beta,"Alpha":alpha,"CorrSPY":float(y.corr(x))}


