    # ================================================================
    # v3.94 — TEL-DM Layer Attribution Audit LIGHT
    # Fixed attribution, NO parameter sweep:
    #   Treasury-only = TMV when TMV 3M > TMF 3M, otherwise CASH.
    #   Equity-only   = always choose TQQQ vs TECL by 3M relative momentum.
    #   Complete TEL  = Treasury gate first; if not TMV, Equity layer winner.
    # Signal at month-end -> next first tradable OPEN, Open->Open.
    # Goal: identify which layer supplies alpha, diversification and stress payoff.
    # Development cutoff remains 2026-07-31.
    # ================================================================
    def _v394_tel_layer_variants(px_close,start,end):
        need=['TMF','TMV','TQQQ','TECL']
        closes=px_close.reindex(columns=[c for c in need if c in px_close.columns]).copy()
        missing=[c for c in need if c not in closes.columns]
        if missing:
            closes=closes.join(get_close(tuple(missing),start,end),how='outer').sort_index().ffill()
        opens=get_open(tuple(need),start,end).sort_index().ffill()
        idx=pd.DatetimeIndex(opens.index).sort_values()
        me=closes[need].sort_index().ffill().resample('ME').last()
        mom3=me/me.shift(3)-1.0
        valid=mom3[need].notna().all(axis=1)
        treasury_tmv=valid & (mom3['TMV']>mom3['TMF'])
        eq_tqqq=valid & (mom3['TQQQ']>mom3['TECL'])

        sig_treas=pd.Series(pd.NA,index=me.index,dtype='object',name='TreasuryOnlySignal')
        sig_treas.loc[valid & treasury_tmv]='TMV'
        sig_treas.loc[valid & ~treasury_tmv]='CASH'
        sig_eq=pd.Series(pd.NA,index=me.index,dtype='object',name='EquityOnlySignal')
        sig_eq.loc[valid & eq_tqqq]='TQQQ'
        sig_eq.loc[valid & ~eq_tqqq]='TECL'
        sig_tel=pd.Series(pd.NA,index=me.index,dtype='object',name='TELSignal')
        sig_tel.loc[valid & treasury_tmv]='TMV'
        sig_tel.loc[valid & ~treasury_tmv & eq_tqqq]='TQQQ'
        sig_tel.loc[valid & ~treasury_tmv & ~eq_tqqq]='TECL'

        def build(sig,name):
            pos=pd.Series(pd.NA,index=idx,dtype='object',name=name+' PositionAtOpen')
            audit=[]
            for dt,val in sig.dropna().items():
                cand=idx[idx>pd.Timestamp(dt)]
                if len(cand)==0: continue
                e=cand[0]; pos.loc[e]=val
                audit.append({'SignalMonthEnd':dt,'EntryOpen':e,'Signal':val})
            pos=pos.ffill()
            ar=opens.pct_change(fill_method=None)
            hold=pos.shift(1)
            ret=pd.Series(np.nan,index=idx,dtype=float,name=name)
            active=hold.notna()
            ret.loc[active]=0.0
            for a in ['TMV','TQQQ','TECL']:
                m=hold.eq(a)
                ret.loc[m]=ar.loc[m,a]
            ret.loc[hold.eq('CASH')]=0.0
            return ret.dropna(),pos,pd.DataFrame(audit)

        tr,tr_pos,tr_aud=build(sig_treas,'Treasury-only')
        eq,eq_pos,eq_aud=build(sig_eq,'Equity-only')
        tel,tel_pos,tel_aud=build(sig_tel,'TEL-DM 3M')
        common=pd.concat([tr,eq,tel],axis=1).dropna()

        # Exact daily attribution of complete TEL return by active branch.
        tel_hold=tel_pos.shift(1).reindex(common.index)
        treas_contrib=common['TEL-DM 3M'].where(tel_hold.eq('TMV'),0.0).rename('TEL Treasury branch contribution')
        eq_contrib=common['TEL-DM 3M'].where(tel_hold.isin(['TQQQ','TECL']),0.0).rename('TEL Equity branch contribution')
        check=(common['TEL-DM 3M']-(treas_contrib+eq_contrib)).abs()

        audit=pd.DataFrame({
            'TMF_3M':mom3['TMF'],'TMV_3M':mom3['TMV'],
            'TQQQ_3M':mom3['TQQQ'],'TECL_3M':mom3['TECL'],
            'Treasury_TMV':treasury_tmv,
            'Equity_TQQQ':eq_tqqq,
            'TreasuryOnlySignal':sig_treas,
            'EquityOnlySignal':sig_eq,
            'TELSignal':sig_tel,
        }).dropna(subset=['TELSignal'])
        return common, treas_contrib, eq_contrib, audit, tel_hold, check


    def render_v394_tel_dm_layer_attribution(px_close,rf_bt,start,end):
        import io,zipfile
        st.markdown('### 🧬 v3.94 — TEL-DM Layer Attribution Audit LIGHT')
        st.caption('TEL-DMの強さがTreasury layerとEquity layerのどちらから来るかを、ルール変更なしで分解します。')
        st.info('固定仕様: Treasury-only = TMV 3M > TMF 3MならTMV、それ以外はCASH。Equity-only = 常時TQQQ vs TECL 3M winner。Complete TEL-DM = Treasury gateを先に通し、TMVでなければEquity winner。すべて月末signal→翌営業日Open、Open→Open。')
        st.warning('これは新しいパラメータ探索ではありません。3Mは既存TEL-DMの固定proxyをそのまま使い、lookback・threshold・順序・weightは変更しません。Development cutoff = 2026-07-31。')
        if not st.button('TEL-DM Layer Attributionを検証',type='primary',use_container_width=True,key='run_v394'):
            return
        with st.spinner('TEL-DMをTreasury / Equity layerへ分解し、FoF寄与まで監査中…'):
            cutoff=pd.Timestamp('2026-07-31')
            layers,tc,ec,audit,tel_hold,check=_v394_tel_layer_variants(px_close,start,end)
            layers=layers.loc[:cutoff]; tc=tc.reindex(layers.index); ec=ec.reindex(layers.index); tel_hold=tel_hold.reindex(layers.index)

            # Standalone layer metrics.
            stand=pd.DataFrame([_v381_metrics(c,layers[c])|{'Strategy':c} for c in layers.columns]).set_index('Strategy')
            stand_roll=_v326_rolling_p10_table(layers,list(layers.columns))

            # Existing architecture; compare each candidate as the fourth equal-weight family.
            d390,fam=_v390_build(px_close,rf_bt,start,end)
            fam=fam.loc[:cutoff]
            idx=fam.index.intersection(layers.index)
            base=fam.loc[idx,['MOM','MR','VIX']].copy()
            variants={}
            for c in ['Treasury-only','Equity-only','TEL-DM 3M']:
                ff=base.copy(); ff[c]=layers[c].reindex(idx); ff=ff.dropna()
                variants['4F + '+c]=_v390_monthly_rebalanced_ew(ff).rename('4F + '+c)
            ctrl=_v390_monthly_rebalanced_ew(base.dropna()).rename('3F EW')
            fof=pd.concat([ctrl]+list(variants.values()),axis=1).dropna()
            fof_metrics=pd.DataFrame([_v381_metrics(c,fof[c])|{'Strategy':c} for c in fof.columns]).set_index('Strategy')
            fof_roll=_v326_rolling_p10_table(fof,list(fof.columns))
            monthly=(1+fof).resample('ME').prod(min_count=1)-1
            cpcv,_=_v326_cpcv_summary(monthly.to_period('M'),'3F EW',['4F + Treasury-only','4F + Equity-only','4F + TEL-DM 3M'])
            wf_t=_v355_wf_blocks(monthly.to_period('M'),'3F EW','4F + Treasury-only',13)
            wf_e=_v355_wf_blocks(monthly.to_period('M'),'3F EW','4F + Equity-only',13)
            wf_tel=_v355_wf_blocks(monthly.to_period('M'),'3F EW','4F + TEL-DM 3M',13)

            # Alpha/beta and correlation using the same daily basis used in the FoF audit.
            spy=px_close['SPY'].pct_change(fill_method=None).reindex(layers.index)
            ab=pd.DataFrame([_v393_alpha_beta(layers[c],spy)|{'Strategy':c} for c in layers.columns]).set_index('Strategy')
            fam_layers=base.copy()
            for c in layers.columns: fam_layers[c]=layers[c].reindex(fam_layers.index)
            fm=(1+fam_layers.dropna()).resample('ME').prod(min_count=1)-1
            raw=fm.corr()
            corr_rows=[]
            for c in layers.columns:
                for b in ['MOM','MR','VIX']:
                    corr_rows.append({'Layer':c,'Family':b,'RawCorr':raw.loc[c,b]})
            corr_long=pd.DataFrame(corr_rows)
            eff_rows=[]
            base_cols=['MOM','MR','VIX']
            eff_rows.append({'Architecture':'3 families','Effective Bets':_v384_effective_bets(raw.loc[base_cols,base_cols])})
            for c in layers.columns:
                cols=base_cols+[c]
