    # ================================================================
    # v3.95 — Frozen v3.45 × TEL-DM Integration Audit LIGHT
    # Fixed challengers, NO sweep/rescue tuning:
    #   Control      = 100% Frozen v3.45
    #   Router25     = Treasury router OFF: 100% v3.45
    #                  Treasury router ON (TMV 3M > TMF 3M): 75% v3.45 + 25% TMV
    #   FullTEL25    = 75% v3.45 + 25% complete TEL-DM
    # 25% and 3M are inherited from prior frozen research; no 10/20/30/50% sweep.
    # Month-end signal -> next first tradable OPEN; Open->Open.
    # Development cutoff remains 2026-07-31.
    # ================================================================
    def _v395_monthly_target_mix(ret_a, ret_b, w_b, name):
        """Monthly reset to target weights, then buy-and-hold drift within month."""
        x=pd.concat([ret_a.rename('A'),ret_b.rename('B')],axis=1).dropna().sort_index()
        out=[]
        for _,g in x.groupby(x.index.to_period('M')):
            wealth=pd.Series({'A':1.0-float(w_b),'B':float(w_b)},dtype=float)
            for dt,row in g.iterrows():
                total=float(wealth.sum())
                w=wealth/total if total else pd.Series({'A':1.0-float(w_b),'B':float(w_b)})
                rr=float((w*row).sum())
                out.append((dt,rr))
                wealth=wealth*(1.0+row)
        return pd.Series(dict(out),name=name).sort_index()

    def _v395_router_mix(v345, tmv_ret, router_on, name='TEL Router25'):
        """Reset 75/25 when router is ON; 100/0 when OFF; drift until next month/regime reset."""
        x=pd.concat([v345.rename('V345'),tmv_ret.rename('TMV'),router_on.rename('RouterON')],axis=1).dropna().sort_index()
        out=[]; wealth=None; prev_month=None; prev_gate=None
        for dt,row in x.iterrows():
            gate=bool(row['RouterON']); month=dt.to_period('M')
            if wealth is None or month!=prev_month or gate!=prev_gate:
                wealth=pd.Series({'V345':0.75 if gate else 1.0,'TMV':0.25 if gate else 0.0},dtype=float)
            total=float(wealth.sum()); w=wealth/total
            rr=float(w['V345']*row['V345']+w['TMV']*row['TMV'])
            out.append((dt,rr))
            wealth['V345']*=1.0+float(row['V345']); wealth['TMV']*=1.0+float(row['TMV'])
            prev_month=month; prev_gate=gate
        return pd.Series(dict(out),name=name).sort_index()

    def render_v395_v345_tel_overlay(px_close,rf_bt,start,end):
        import io,zipfile
