# =============================================================================
# Research v198 / R330 — Frozen Promotion Cross-Architecture Portability Audit
# LIGHTWEIGHT: same hypothesis / same 144 controls / same Evidence contract.
# Optimizations:
# - R320 and R328 frozen outputs reused once.
# - monthly 144-control matrix aligned once.
# - Promotion overlay applied vectorially to all 144 columns.
# - full-period metrics calculated once per series (no duplicate control rebuild).
# - block metrics use sliced prebuilt matrices.
# =============================================================================
R330_BUILD="R330-FROZEN-PROMOTION-144-PORTABILITY-v1.2-LIGHT-PRECISION-FIX"

@st.cache_data(show_spinner=False)
def _r330_run():
    import io,zipfile,json,hashlib
    EX329,*_=_r329_run()
    if not bool(EX329.Pass.all()): raise RuntimeError("parent R329 exactness failed")
    EX320,ATLAS,CANON,FAM,C,_Z320=_r320_run()
    if not bool(EX320.Pass.all()): raise RuntimeError("parent R320 exactness failed")
    if C.shape[1]!=144: raise RuntimeError(f"expected 144 frozen controls, got {C.shape[1]}")
    EX328,FULL328,ACT328,FIRE328,BLOCK328,RS328,LOO328,CR328,D328,_Z328=_r328_run()
    if not bool(EX328.Pass.all()): raise RuntimeError("parent R328 exactness failed")

    def pidx(i):
        try: return pd.PeriodIndex(i,freq="M")
        except Exception: return pd.PeriodIndex(pd.to_datetime(i),freq="M")

    # Align once. R320 C is already monthly; avoid 144 groupby/reindex loops.
    CTRL=C.copy()
    CTRL.index=pidx(CTRL.index)
    CTRL=CTRL.groupby(level=0).last().astype("float64")
    d8=D328.copy(); d8.index=pidx(d8.index); d8=d8.groupby(level=0).last()
    common=CTRL.index.intersection(d8.index)
    common=common[common<=pd.Period("2026-07","M")]
    CTRL=CTRL.reindex(common)
    promo=d8["Promote"].reindex(common).fillna(False).astype(bool)
    tecl=d8["TECL"].reindex(common).astype("float64")
    valid=CTRL.notna().all(axis=1) & tecl.notna()
    CTRL=CTRL.loc[valid]; promo=promo.loc[valid]; tecl=tecl.loc[valid]

    # Vectorized overlay: one matrix assignment for all 144 architectures.
    OVR=CTRL.copy()
    OVR.loc[promo,:]=tecl.loc[promo].to_numpy()[:,None]

    def perf(x): return _r320_perf(pd.Series(x).dropna())
    # One full-period pass per control and overlay; cache results in dictionaries.
    pc={c:perf(CTRL[c]) for c in CTRL.columns}
    po={c:perf(OVR[c]) for c in OVR.columns}
    keys=["CAGR","Sharpe0","Sortino0","MaxDD","Calmar","Rolling36M_CAGR_P10"]
    rows=[]
    for c in CTRL.columns:
        a,b=pc[c],po[c]
        rows.append([c,len(CTRL),int(promo.sum()),
                     a["CAGR"],b["CAGR"],b["CAGR"]-a["CAGR"],
                     a["Sharpe0"],b["Sharpe0"],b["Sharpe0"]-a["Sharpe0"],
                     a["Sortino0"],b["Sortino0"],b["Sortino0"]-a["Sortino0"],
                     a["MaxDD"],b["MaxDD"],b["MaxDD"]-a["MaxDD"],
                     a["Calmar"],b["Calmar"],b["Calmar"]-a["Calmar"],
                     a["Rolling36M_CAGR_P10"],b["Rolling36M_CAGR_P10"],b["Rolling36M_CAGR_P10"]-a["Rolling36M_CAGR_P10"],
                     float((OVR[c]-CTRL[c]).mean()),
                     float(((OVR.loc[promo,c]-CTRL.loc[promo,c])>0).mean()) if promo.any() else np.nan])
    RES=pd.DataFrame(rows,columns=["Combination","N","PromotionMonths",
      "Control_CAGR","Overlay_CAGR","Delta_CAGR","Control_Sharpe0","Overlay_Sharpe0","Delta_Sharpe0",
      "Control_Sortino0","Overlay_Sortino0","Delta_Sortino0","Control_MaxDD","Overlay_MaxDD","Delta_MaxDD",
      "Control_Calmar","Overlay_Calmar","Delta_Calmar","Control_Rolling36M_CAGR_P10",
      "Overlay_Rolling36M_CAGR_P10","Delta_Rolling36M_CAGR_P10","MeanActiveReturn_AllMonths","PositiveFireShare"])

    parts=RES.Combination.str.split(r"\s*\|\s*",expand=True)
    if parts.shape[1]!=4: raise RuntimeError("R320 combination naming schema is not four-family parsable")
    RES[["Seiryu","Byakko","Suzaku","Genbu"]]=parts.to_numpy()

    SUMMARY=pd.DataFrame([{
      "Combinations":len(RES),"PromotionMonths_min":int(RES.PromotionMonths.min()),"PromotionMonths_max":int(RES.PromotionMonths.max()),
      "CAGR_ImproveShare":(RES.Delta_CAGR>0).mean(),"Sharpe_ImproveShare":(RES.Delta_Sharpe0>0).mean(),
      "Sortino_ImproveShare":(RES.Delta_Sortino0>0).mean(),"MaxDD_ImproveShare":(RES.Delta_MaxDD>0).mean(),
      "Calmar_ImproveShare":(RES.Delta_Calmar>0).mean(),"RollingP10_ImproveShare":(RES.Delta_Rolling36M_CAGR_P10>0).mean(),
      "Median_Delta_CAGR":RES.Delta_CAGR.median(),"P10_Delta_CAGR":RES.Delta_CAGR.quantile(.10),
      "Median_Delta_Sortino":RES.Delta_Sortino0.median(),"Median_Delta_MaxDD":RES.Delta_MaxDD.median(),
      "Median_Delta_Calmar":RES.Delta_Calmar.median(),"Median_Delta_RollingP10":RES.Delta_Rolling36M_CAGR_P10.median()}])

    famrows=[]
    for fam in ["Seiryu","Byakko","Suzaku","Genbu"]:
        for member,g in RES.groupby(fam,sort=False):
            famrows.append([fam,member,len(g),(g.Delta_CAGR>0).mean(),g.Delta_CAGR.mean(),g.Delta_CAGR.median(),
              (g.Delta_Sharpe0>0).mean(),g.Delta_Sharpe0.median(),(g.Delta_Sortino0>0).mean(),g.Delta_Sortino0.median(),
              (g.Delta_MaxDD>0).mean(),g.Delta_MaxDD.median(),(g.Delta_Calmar>0).mean(),g.Delta_Calmar.median(),
              (g.Delta_Rolling36M_CAGR_P10>0).mean(),g.Delta_Rolling36M_CAGR_P10.median()])
    FAMILY=pd.DataFrame(famrows,columns=["Family","Member","N","CAGR_ImproveShare","Mean_Delta_CAGR","Median_Delta_CAGR",
      "Sharpe_ImproveShare","Median_Delta_Sharpe0","Sortino_ImproveShare","Median_Delta_Sortino0",
      "MaxDD_ImproveShare","Median_Delta_MaxDD","Calmar_ImproveShare","Median_Delta_Calmar",
      "RollingP10_ImproveShare","Median_Delta_RollingP10"])

    # Three fixed blocks. Matrices are sliced once; no architecture reconstruction.
    brow=[]
    splits=np.array_split(np.arange(len(CTRL)),3)
    for bi,loc in enumerate(splits,1):
        cb=CTRL.iloc[loc]; ob=OVR.iloc[loc]; pb=promo.iloc[loc]
        pcb={c:perf(cb[c]) for c in cb.columns}
        pob={c:perf(ob[c]) for c in ob.columns}
        for c in cb.columns:
            a,b=pcb[c],pob[c]
            brow.append([c,bi,str(cb.index.min()),str(cb.index.max()),len(cb),int(pb.sum()),
                         b["CAGR"]-a["CAGR"],b["Sortino0"]-a["Sortino0"],b["MaxDD"]-a["MaxDD"],b["Calmar"]-a["Calmar"]])
    BLOCK=pd.DataFrame(brow,columns=["Combination","Block","Start","End","N","PromotionMonths",
                                    "Delta_CAGR","Delta_Sortino0","Delta_MaxDD","Delta_Calmar"])
    BLOCKSUM=BLOCK.groupby("Block",sort=False).agg(
      Combinations=("Combination","size"),CAGR_ImproveShare=("Delta_CAGR",lambda x:(x>0).mean()),
      Median_Delta_CAGR=("Delta_CAGR","median"),Sortino_ImproveShare=("Delta_Sortino0",lambda x:(x>0).mean()),
      MaxDD_ImproveShare=("Delta_MaxDD",lambda x:(x>0).mean()),Calmar_ImproveShare=("Delta_Calmar",lambda x:(x>0).mean()),
      Median_Delta_Calmar=("Delta_Calmar","median")).reset_index()

    canonical_name=f"{R323_S} | {R323_B} | {R323_Z} | {R323_G}"
    cr=RES.loc[RES.Combination.eq(canonical_name)]
    if len(cr)!=1: raise RuntimeError("canonical KIRIN row missing/duplicated")
    r=cr.iloc[0]; official=FULL328.set_index("Strategy")
    CHECK=pd.DataFrame([
      ["Control CAGR",r.Control_CAGR,float(official.loc["KIRIN","CAGR"])],
      ["Overlay CAGR",r.Overlay_CAGR,float(official.loc["Challenger","CAGR"])],
      ["Control Sortino",r.Control_Sortino0,float(official.loc["KIRIN","Sortino0"])],
      ["Overlay Sortino",r.Overlay_Sortino0,float(official.loc["Challenger","Sortino0"])],
      ["Control MaxDD",r.Control_MaxDD,float(official.loc["KIRIN","MaxDD"])],
      ["Overlay MaxDD",r.Overlay_MaxDD,float(official.loc["Challenger","MaxDD"])],
      ["Control Calmar",r.Control_Calmar,float(official.loc["KIRIN","Calmar"])],
      ["Overlay Calmar",r.Overlay_Calmar,float(official.loc["Challenger","Calmar"])]],
      columns=["Metric","R330","Official_R328"])
    CHECK["AbsDiff"]=(CHECK.R330-CHECK.Official_R328).abs()
    CHECK["Pass"]=CHECK.AbsDiff<1e-8

    EX=pd.DataFrame([
      ["Parent R329 exactness","ALL PASS","ALL PASS",True],["Parent R320 exactness","ALL PASS","ALL PASS",True],
      ["Parent R328 exactness","ALL PASS","ALL PASS",True],["Frozen architectures",str(len(RES)),"144",len(RES)==144],
      ["Promotion source","exact R328 frozen months","exact R328 frozen months",True],
      ["Promotion action","TECL 100%","TECL 100%",True],
      ["Canonical R328 identity",f"{int(CHECK.Pass.sum())}/{len(CHECK)}",f"{len(CHECK)}/{len(CHECK)}",bool(CHECK.Pass.all())],
      ["New signal/threshold/lookback/weight search","NONE","NONE",True],["Winner selection","NONE","NONE",True],
      ["DEV end",str(CTRL.index.max()),"2026-07",str(CTRL.index.max())=="2026-07"],
      ["Forward OOS","NONE","NONE",True],["Production change","NONE","NONE",True]],
      columns=["Check","Observed","Expected","Pass"])
    if not bool(EX.Pass.all()): raise RuntimeError("R330 exactness failed")

    contract={"build":R330_BUILD,"mode":"lightweight; mathematical experiment unchanged from R330 v196",
      "control_set":"R320 frozen 144 combinations","overlay":"exact R328 Promotion months; ON => TECL 100%",
      "optimizations":["single monthly alignment","vectorized 144-column overlay","reuse full-period metrics","block matrix slicing"],
      "selection":"none","dev_end":"2026-07","forward_oos":"excluded","production":"unchanged"}
    files={"00_exactness.csv":EX.to_csv(index=False),"01_portability_summary.csv":SUMMARY.to_csv(index=False),
      "02_all_144_overlay_results.csv":RES.to_csv(index=False),"03_family_marginal_portability.csv":FAMILY.to_csv(index=False),
      "04_three_block_all_combinations.csv":BLOCK.to_csv(index=False),"05_three_block_summary.csv":BLOCKSUM.to_csv(index=False),
      "06_canonical_r328_identity.csv":CHECK.to_csv(index=False),"07_research_contract.json":json.dumps(contract,ensure_ascii=False,indent=2),
      "README.txt":"R330 v198 lightweight implementation with canonical float64 precision. Same frozen 144-control portability experiment as v196; calculation duplication reduced. No new search. DEV <= 2026-07; Forward excluded; Production unchanged.\n"}
    man={k:hashlib.sha256(v.encode("utf-8-sig") if k.endswith(".csv") else v.encode()).hexdigest() for k,v in files.items()}
    files["08_manifest.json"]=json.dumps({"run":"R330","sha256":man},ensure_ascii=False,indent=2)
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
        for k,v in files.items(): z.writestr(k,v.encode("utf-8-sig") if k.endswith(".csv") else v.encode())
    return EX,SUMMARY,RES,FAMILY,BLOCKSUM,CHECK,bio.getvalue()


# =============================================================================
# Research v203 / R334 — Attack75-G25 Shield Allocation Falsification
# One frozen architecture test only:
# Turbo ON + A-state OFF => selected asset 75% + canonical Genbu 25%.
# No weight / Genbu / threshold / signal search. DEV <= 2026-07.
# =============================================================================
R334_BUILD="R334-ATTACK75-G25-SHIELD-FALSIFICATION-v1.1-LIGHT"

@st.cache_data(show_spinner=False)
def _r334_run():
    import io,zipfile,json,hashlib
    EX328,FULL328,ACT328,FIRE328,BLOCK328,RS328,LOO328,CR328,D328,_Z328=_r328_run()
    EX320,AC320,CAN320,FAM320,C320,_Z320=_r320_run()
    if not bool(EX328.Pass.all()): raise RuntimeError("parent R328 exactness failed")
    if not bool(EX320.Pass.all()): raise RuntimeError("parent R320 exactness failed")

    # Resolve the already-frozen canonical Genbu sleeve; no Genbu selection/search.
    cand, historical_registry, r193_sha, r194_sha = _r15d_r235_r195_candidates()
    ge_name=R320_CANONICAL["Genbu"]
    ge_col=f"Genbu {ge_name}"
    if ge_col not in cand.columns:
        raise RuntimeError(f"canonical Genbu missing: {ge_col}")
    ge=pd.Series(cand[ge_col]).dropna().astype("float64")
    if isinstance(ge.index,pd.DatetimeIndex):
        ge=(1.0+ge).groupby(ge.index.to_period("M")).prod(min_count=1)-1.0
    else:
        ge.index=pd.PeriodIndex(ge.index,freq="M")
    ge=ge.sort_index()

    # Reconstruct only the frozen Attack75 market state and selected-asset returns.
    start="2009-01-01"; end="2026-08-10"
    needed=["QQQ","QLD","TQQQ","LQD","GLD","TLT","SPXL","TECL","XLU","^VIX","SPY","XLK"]
    closes=get_close(tuple(needed),start,end).copy(); opens=get_open(tuple(needed),start,end).copy()
    if closes is None or opens is None or len(closes)==0 or len(opens)==0:
        raise RuntimeError("canonical close/open data unavailable")
    missing=[x for x in needed if x not in closes.columns or x not in opens.columns]
    if missing: raise RuntimeError(f"canonical market data missing: {missing}")
    idx=pd.DatetimeIndex(closes.index.intersection(opens.index)).sort_values()
    closes=closes.reindex(idx).ffill(); opens=opens.reindex(idx).ffill()
    asset_ret=opens.pct_change(fill_method=None)
    gates,_=_v326_bond_regime_signals(closes,idx)
    gate_a=gates["A TLT3M>0"].reindex(idx).ffill().fillna(False)
    brakes,_=_v329_brake_signals(closes,idx)
    vix_brake=brakes["V VIX30"].reindex(idx).fillna(False)
    inflect_eff,_=_v332_xlk_inflection_signal(closes,idx)
    choose_tecl,_=_v335_attack_selector_signal(closes,idx)
    turbo=(gate_a & ~vix_brake & inflect_eff.reindex(idx).fillna(False).astype(bool)).astype(bool)
    choose_tecl=choose_tecl.reindex(idx).fillna(False).astype(bool)
    m_turbo=turbo.groupby(turbo.index.to_period("M")).max().astype(bool)
    m_tecl=choose_tecl.groupby(choose_tecl.index.to_period("M")).max().astype(bool)
    tq=(1+asset_ret["TQQQ"]).groupby(asset_ret.index.to_period("M")).prod(min_count=1)-1
    te=(1+asset_ret["TECL"]).groupby(asset_ret.index.to_period("M")).prod(min_count=1)-1

    D=D328[["KIRIN","Challenger"]].copy()
    D.index=pd.PeriodIndex(D.index,freq="M")
    D=D.rename(columns={"KIRIN":"Attack75","Challenger":"R328_Promotion100"})
    D["Turbo"]=m_turbo.reindex(D.index).fillna(False).astype(bool)
    D["ChooseTECL"]=m_tecl.reindex(D.index).fillna(False).astype(bool)
    D["TQQQ"]=tq.reindex(D.index).astype("float64")
    D["TECL"]=te.reindex(D.index).astype("float64")
    D["Genbu"]=ge.reindex(D.index).astype("float64")
    D=D[D.index<=pd.Period("2026-07","M")].dropna()

    # Attack100 frozen R332 definition.
    D["Attack100"]=D["Attack75"].astype("float64")
    D.loc[D.Turbo & D.ChooseTECL,"Attack100"]=D.loc[D.Turbo & D.ChooseTECL,"TECL"]
    D.loc[D.Turbo & ~D.ChooseTECL,"Attack100"]=D.loc[D.Turbo & ~D.ChooseTECL,"TQQQ"]

    # R334 single pre-declared challenger: selected 75% + canonical Genbu 25%.
    # A-state has priority in canonical KIRIN. R320/R332 lineage has 33 effective Turbo fires;
    # this experiment changes ONLY the residual 25% on those same fires.
    D["Attack75_G25"]=D["Attack75"].astype("float64")
    sel=np.where(D.ChooseTECL,D.TECL,D.TQQQ).astype("float64")
    D.loc[D.Turbo,"Attack75_G25"]=.75*sel[D.Turbo.to_numpy()]+.25*D.loc[D.Turbo,"Genbu"].to_numpy()
    D["G25_Active"]=D.Attack75_G25-D.Attack75

    def perf(x): return _r320_perf(pd.Series(x).dropna())
    rows=[]
    for name in ["Attack75","Attack75_G25","R328_Promotion100","Attack100"]:
        q=perf(D[name])
        rows.append([name]+[q[k] for k in ["N","CAGR","Vol","Sharpe0","Sortino0","MaxDD","Calmar","Rolling36M_CAGR_P10"]])
    FULL=pd.DataFrame(rows,columns=["Strategy","N","CAGR","Vol","Sharpe0","Sortino0","MaxDD","Calmar","Rolling36M_CAGR_P10"])

    # Fixed chronological thirds.
    bl=[]
    for bi,loc in enumerate(np.array_split(np.arange(len(D)),3),1):
        g=D.iloc[loc]
        vals=[bi,str(g.index.min()),str(g.index.max()),len(g),int(g.Turbo.sum())]
        for name in ["Attack75_G25","R328_Promotion100","Attack100"]:
            b=perf(g.Attack75); a=perf(g[name])
            vals += [a["CAGR"]-b["CAGR"],a["Sortino0"]-b["Sortino0"],a["MaxDD"]-b["MaxDD"],a["Calmar"]-b["Calmar"],a["Rolling36M_CAGR_P10"]-b["Rolling36M_CAGR_P10"]]
        bl.append(vals)
    suffix=["Delta_CAGR","Delta_Sortino0","Delta_MaxDD","Delta_Calmar","Delta_Rolling36M_CAGR_P10"]
    cols=["Block","Start","End","N","TurboFires"]+[f"{n}_{x}" for n in ["G25","Promotion100","Attack100"] for x in suffix]
    BLOCK=pd.DataFrame(bl,columns=cols)

    # Turbo-event anatomy: only residual allocation changes.
    E=D[D.Turbo].copy()
    E["SelectedAsset"]=np.where(E.ChooseTECL,"TECL","TQQQ")
    E["G25_Win"]=E.G25_Active>0
    EVENTS=E.reset_index(names="Month")[["Month","SelectedAsset","Attack75","Attack75_G25","Genbu","G25_Active","G25_Win"]]

    # Fixed crisis windows.
    windows=[("COVID","2020-02","2020-05"),("2022_Bear","2022-01","2022-10"),("2025_Shock","2025-03","2025-05")]
    cr=[]
    for name,a,b in windows:
        g=D.loc[pd.Period(a,"M"):pd.Period(b,"M")]
        if len(g):
            cr.append([name,a,b,len(g),int(g.Turbo.sum())]+[(1+g[x]).prod()-1 for x in ["Attack75","Attack75_G25","R328_Promotion100","Attack100"]])
    CRISIS=pd.DataFrame(cr,columns=["Window","Start","End","N","TurboFires","Attack75_TotalReturn","G25_TotalReturn","Promotion100_TotalReturn","Attack100_TotalReturn"])

    # Exactness / fail-closed.
    off=np.nanmax(np.abs(D.loc[~D.Turbo,"Attack75_G25"]-D.loc[~D.Turbo,"Attack75"]))<1e-12 if (~D.Turbo).any() else True
    formula=np.nanmax(np.abs(D.loc[D.Turbo,"Attack75_G25"]-(.75*np.where(D.loc[D.Turbo,"ChooseTECL"],D.loc[D.Turbo,"TECL"],D.loc[D.Turbo,"TQQQ"])+.25*D.loc[D.Turbo,"Genbu"])))<1e-12
    EX=pd.DataFrame([
      ["Parent R328 exactness","ALL PASS","ALL PASS",bool(EX328.Pass.all())],
      ["Parent R320 exactness","ALL PASS","ALL PASS",bool(EX320.Pass.all())],
      ["Canonical Genbu",ge_name,R320_CANONICAL["Genbu"],ge_name==R320_CANONICAL["Genbu"]],
      ["Turbo fire count",str(int(D.Turbo.sum())),"33",int(D.Turbo.sum())==33],
      ["TECL/TQQQ fire split",f"{int((D.Turbo&D.ChooseTECL).sum())}/{int((D.Turbo&~D.ChooseTECL).sum())}","15/18",int((D.Turbo&D.ChooseTECL).sum())==15 and int((D.Turbo&~D.ChooseTECL).sum())==18],
      ["G25 Turbo OFF identity",str(bool(off)),"True",bool(off)],
      ["G25 exact 75/25 formula",str(bool(formula)),"True",bool(formula)],
      ["G25 weight search","NONE","NONE",True],
      ["Genbu selection/search","NONE","NONE",True],
      ["DEV end",str(D.index.max()),"2026-07",str(D.index.max())=="2026-07"],
      ["Forward OOS","NONE","NONE",True],
      ["Production change","NONE","NONE",True],
    ],columns=["Check","Observed","Expected","Pass"])
    if not bool(EX.Pass.all()): raise RuntimeError("R334 exactness failed")

    contract={"build":R334_BUILD,"challenger":"Turbo selected asset 75% + canonical Genbu 25%","control":"canonical Attack75","comparators":["R328 Promotion100","Attack100"],"weight_search":"none","genbu_search":"none","dev_end":"2026-07","forward_oos":"excluded","production":"unchanged"}
    files={
      "00_exactness.csv":EX.to_csv(index=False),
      "01_full_metrics.csv":FULL.to_csv(index=False),
      "02_turbo_event_anatomy.csv":EVENTS.to_csv(index=False),
      "03_three_block.csv":BLOCK.to_csv(index=False),
      "04_fixed_crisis_windows.csv":CRISIS.to_csv(index=False),
      "05_monthly_returns_state.csv":D.reset_index(names="Month").to_csv(index=False),
      "06_research_contract.json":json.dumps(contract,ensure_ascii=False,indent=2),
      "README.txt":"R334 Attack75-G25 shield-allocation falsification. One fixed challenger only: same frozen Turbo/selector, selected asset 75% + canonical Genbu 25%. No weight, Genbu, signal, threshold, or lookback search. DEV <= 2026-07; Forward excluded; Production unchanged.\n"
    }
    man={k:hashlib.sha256(v.encode("utf-8-sig") if k.endswith(".csv") else v.encode()).hexdigest() for k,v in files.items()}
    files["07_manifest.json"]=json.dumps({"run":"R334","sha256":man},ensure_ascii=False,indent=2)
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
        for k,v in files.items(): z.writestr(k,v.encode("utf-8-sig") if k.endswith(".csv") else v.encode())
        z.writestr("DUMMY.txt",b"R334 Evidence package")
    return EX,FULL,EVENTS,BLOCK,CRISIS,bio.getvalue()



# =============================================================================
