# =============================================================================
# Research v219 / R339 — 麒麟・玄武の盾 × 反攻 (Frozen KRO transfer test)
# Frozen G25 practical series from R338 + frozen R314/R319 KRO action.
# No search / no retuning. DEV <= 2026-07. Forward excluded.
# =============================================================================
R339_BUILD="R339-G25-KRO-TRANSFER-v1.0"

@st.cache_data(show_spinner=False)
def _r339_run():
    import io,zipfile,json,hashlib
    EX338,FULL338,ALLOC338,Z338=_r338_run()
    EX319,PERF319,DELTA319,DET319,Z319=_r319_hanko_operator_order()
    if not bool(EX338.Pass.all()) or not bool(EX319.Pass.all()):
        raise RuntimeError("R339 parent exactness failed")

    # Reuse frozen official evidence; do not reconstruct or retune.
    with zipfile.ZipFile(io.BytesIO(Z338),"r") as z:
        g=pd.read_csv(io.BytesIO(z.read("03_monthly_returns.csv")),index_col=0)
    with zipfile.ZipFile(io.BytesIO(Z319),"r") as z:
        h=pd.read_csv(io.BytesIO(z.read("05_monthly_returns.csv")),index_col=0)
    g.index=pd.PeriodIndex(g.index.astype(str),freq="M")
    h.index=pd.PeriodIndex(h.index.astype(str),freq="M")
    if "玄武の盾_現世" not in g.columns or "HANKO Practical" not in h.columns:
        raise RuntimeError("frozen parent series unavailable")

    base=pd.to_numeric(g["玄武の盾_現世"],errors="coerce").dropna().astype("float64")
    canonical=pd.to_numeric(g["天界_現世"],errors="coerce").reindex(base.index).astype("float64")
    hanko=pd.to_numeric(h["HANKO Practical"],errors="coerce").reindex(base.index).astype("float64")
    fires=[pd.Period("2020-12","M"),pd.Period("2021-11","M"),pd.Period("2024-06","M")]
    if any(m not in base.index or pd.isna(hanko.get(m,np.nan)) for m in fires):
        raise RuntimeError("frozen KRO fire month missing")

    # Frozen transfer: G25 changes ONLY on the three already-frozen R314 fires.
    # The action itself is the R319 audited KRO action after R289 practicalization.
    combo=base.copy().rename("麒麟・玄武の盾・反攻（現世）")
    canonical_kro=canonical.copy().rename("麒麟・反攻（現世）")
    for m in fires:
        combo.loc[m]=float(hanko.loc[m])
        canonical_kro.loc[m]=float(hanko.loc[m])

    common=base.index.intersection(combo.index).intersection(canonical_kro.index).sort_values()
    base=base.reindex(common); combo=combo.reindex(common); canonical_kro=canonical_kro.reindex(common)

    def met(x): return _r320_perf(pd.Series(x).dropna().astype("float64"))
    rows=[]
    for nm,x in [("麒麟・玄武の盾（現世）",base),
                 ("麒麟・玄武の盾・反攻（現世）",combo),
                 ("麒麟・反攻（現世）",canonical_kro)]:
        p=met(x)
        rows.append([nm,len(x),p["CAGR"],p["Vol"],p["Sharpe0"],p["Sortino0"],
                     p["MaxDD"],p["Calmar"],p["Rolling36M_CAGR_P10"]])
    PERF=pd.DataFrame(rows,columns=["Strategy","N","CAGR","Vol","Sharpe0","Sortino0",
                                    "MaxDD","Calmar","Rolling36M_CAGR_P10"])

    EVENTS=pd.DataFrame([[str(m),float(base.loc[m]),float(combo.loc[m]),
                          float(combo.loc[m]-base.loc[m])] for m in fires],
                        columns=["Month","G25_Return","G25_KRO_Return","ActiveDelta"])

    pbase=met(base)
    loo=[]
    for m in fires:
        x=combo.copy(); x.loc[m]=base.loc[m]; p=met(x)
        loo.append([str(m),p["CAGR"],p["Sharpe0"],p["Sortino0"],p["MaxDD"],p["Calmar"],
                    p["Rolling36M_CAGR_P10"],p["CAGR"]-pbase["CAGR"],
                    p["Sortino0"]-pbase["Sortino0"],p["MaxDD"]-pbase["MaxDD"],
                    p["Calmar"]-pbase["Calmar"],p["Rolling36M_CAGR_P10"]-pbase["Rolling36M_CAGR_P10"]])
    LOO=pd.DataFrame(loo,columns=["NeutralizedFire","CAGR","Sharpe0","Sortino0","MaxDD","Calmar",
                                  "Rolling36M_CAGR_P10","Delta_CAGR_vs_G25","Delta_Sortino_vs_G25",
                                  "Delta_MaxDD_vs_G25","Delta_Calmar_vs_G25","Delta_P10_vs_G25"])

    neutral=combo.copy()
    for m in fires: neutral.loc[m]=base.loc[m]
    maxdiff=float((neutral-base).abs().max())

    EX=pd.DataFrame([
      ["Parent R338 exactness","ALL PASS","ALL PASS",bool(EX338.Pass.all())],
      ["Parent R319 exactness","ALL PASS","ALL PASS",bool(EX319.Pass.all())],
      ["Frozen KRO fires",";".join(str(m) for m in fires),"2020-12;2021-11;2024-06",
       ";".join(str(m) for m in fires)=="2020-12;2021-11;2024-06"],
      ["KRO action","R319 frozen action unchanged","UNCHANGED",True],
      ["G25-specific threshold/weight search","NONE","NONE",True],
      ["All-fire neutralization -> G25 maxdiff",f"{maxdiff:.3e}","<1e-12",maxdiff<1e-12],
      ["DEV end",str(common.max()),"2026-07",str(common.max())=="2026-07"],
      ["Forward OOS","EXCLUDED","EXCLUDED",True],
      ["Frozen G25 change","NONE","NONE",True],
      ["Production change","NONE","NONE",True],
    ],columns=["Check","Observed","Expected","Pass"])
    if not bool(EX.Pass.all()):
        raise RuntimeError("R339 exactness failed: "+repr(EX.loc[~EX.Pass].to_dict("records")))

    contract={"build":R339_BUILD,
      "question":"Frozen KRO/R314 transfer onto frozen G25",
      "operator_order":"G25 -> frozen KRO/R314 on same 3 fires -> R289 practicalization",
      "fires":[str(m) for m in fires],"search":"none","retuning":"none",
      "dev_end":"2026-07","forward_oos":"excluded","frozen_g25":"unchanged","production":"unchanged"}
    files={
      "00_exactness.csv":EX.to_csv(index=False),
      "01_performance.csv":PERF.to_csv(index=False),
      "02_fire_month_contribution.csv":EVENTS.to_csv(index=False),
      "03_leave_one_event_out.csv":LOO.to_csv(index=False),
      "04_monthly_returns.csv":pd.concat({"G25":base,"G25_KRO":combo,"Canonical_KRO":canonical_kro},axis=1).to_csv(),
      "05_contract.json":json.dumps(contract,ensure_ascii=False,indent=2),
      "README.txt":"R339 transfers frozen KRO/R314 onto frozen G25 without any new threshold, weight, or fire search. Only 2020-12, 2021-11, 2024-06 change. Leave-one-event-out included. DEV <= 2026-07; Forward excluded; G25 and Production unchanged.\n"}
    man={k:hashlib.sha256(v.encode("utf-8-sig") if k.endswith(".csv") else v.encode()).hexdigest() for k,v in files.items()}
    files["06_manifest.json"]=json.dumps({"run":"R339","sha256":man},ensure_ascii=False,indent=2)
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
        for k,v in files.items():
            z.writestr(k,v.encode("utf-8-sig") if k.endswith(".csv") else v.encode())
        z.writestr("DUMMY.txt",b"R339 Evidence package")
    return EX,PERF,EVENTS,LOO,bio.getvalue()



# =============================================================================
# Research v220 / R340 — 麒麟・玄武の盾・反攻 Historical Falsification
# Parent: frozen R339 G25+KRO. No rule/threshold/weight search.
# Tests: time blocks, crisis windows, event concentration, cumulative event removal.
# DEV <= 2026-07. Forward excluded. Production / G25 / KRO unchanged.
# =============================================================================
R340_BUILD="R340-G25-KRO-HISTORICAL-FALSIFICATION-v1.0"

@st.cache_data(show_spinner=False)
def _r340_run():
    import io,zipfile,json,hashlib
    EX339,PERF339,EVENTS339,LOO339,Z339=_r339_run()
    if not bool(EX339.Pass.all()):
        raise RuntimeError("R340 parent R339 exactness failed")
    with zipfile.ZipFile(io.BytesIO(Z339),"r") as z:
        m=pd.read_csv(io.BytesIO(z.read("04_monthly_returns.csv")),index_col=0)
    m.index=pd.PeriodIndex(m.index.astype(str),freq="M")
    need=["G25","G25_KRO","Canonical_KRO"]
    if any(c not in m.columns for c in need):
        raise RuntimeError("R340 frozen R339 monthly series unavailable")
    for c in need: m[c]=pd.to_numeric(m[c],errors="coerce").astype("float64")
    m=m.dropna(subset=["G25","G25_KRO"])
    if str(m.index.max())!="2026-07":
        raise RuntimeError("R340 DEV seam mismatch")

    fires=[pd.Period("2020-12","M"),pd.Period("2021-11","M"),pd.Period("2024-06","M")]
    delta=m["G25_KRO"]-m["G25"]
    changed=list(delta.index[delta.abs()>1e-12])
    if changed!=fires:
        raise RuntimeError("R340 frozen fire identity mismatch: "+repr(changed))

    def met(x):
        return _r320_perf(pd.Series(x).dropna().astype("float64"))
    def row(label,x0,x1):
        p0,p1=met(x0),met(x1)
        return [label,len(x0),p0["CAGR"],p1["CAGR"],p1["CAGR"]-p0["CAGR"],
                p0["Sharpe0"],p1["Sharpe0"],p1["Sharpe0"]-p0["Sharpe0"],
                p0["Sortino0"],p1["Sortino0"],p1["Sortino0"]-p0["Sortino0"],
                p0["MaxDD"],p1["MaxDD"],p1["MaxDD"]-p0["MaxDD"],
                p0["Calmar"],p1["Calmar"],p1["Calmar"]-p0["Calmar"],
                p0["Rolling36M_CAGR_P10"],p1["Rolling36M_CAGR_P10"],
                p1["Rolling36M_CAGR_P10"]-p0["Rolling36M_CAGR_P10"]]

    cols=["Window","N","G25_CAGR","KRO_CAGR","dCAGR","G25_Sharpe","KRO_Sharpe","dSharpe",
          "G25_Sortino","KRO_Sortino","dSortino","G25_MaxDD","KRO_MaxDD","dMaxDD",
          "G25_Calmar","KRO_Calmar","dCalmar","G25_P10","KRO_P10","dP10"]

    # Time falsification: contiguous calendar blocks. P10 may be NaN on short blocks; retained transparently.
    bounds=[("2015-02–2018-12","2015-02","2018-12"),
            ("2019-01–2022-12","2019-01","2022-12"),
            ("2023-01–2026-07","2023-01","2026-07")]
    BLOCK=[]
    for label,a,b in bounds:
        q=m.loc[pd.Period(a,"M"):pd.Period(b,"M")]
        BLOCK.append(row(label,q["G25"],q["G25_KRO"]))
    BLOCK=pd.DataFrame(BLOCK,columns=cols)

    # Crisis/regime windows fixed ex ante by historical calendar, not searched for performance.
    windows=[("COVID shock/rebound","2020-02","2020-12"),
             ("2022 tightening/bear","2022-01","2022-12"),
             ("2024 H1","2024-01","2024-06")]
    CR=[]
    for label,a,b in windows:
        q=m.loc[pd.Period(a,"M"):pd.Period(b,"M")]
        CR.append(row(label,q["G25"],q["G25_KRO"]))
    CRISIS=pd.DataFrame(CR,columns=cols)

    # Cumulative removal: 0, 1, 2, 3 frozen fires removed in chronological order.
    REM=[]
    base=m["G25"]; full=m["G25_KRO"]
    for k in range(4):
        x=full.copy()
        removed=fires[:k]
        for f in removed: x.loc[f]=base.loc[f]
        p=met(x); pb=met(base)
        REM.append([k,";".join(str(f) for f in removed) if removed else "NONE",
                    p["CAGR"],p["Sharpe0"],p["Sortino0"],p["MaxDD"],p["Calmar"],
                    p["Rolling36M_CAGR_P10"],p["CAGR"]-pb["CAGR"],
                    p["Sharpe0"]-pb["Sharpe0"],p["Sortino0"]-pb["Sortino0"],
                    p["MaxDD"]-pb["MaxDD"],p["Calmar"]-pb["Calmar"],
                    p["Rolling36M_CAGR_P10"]-pb["Rolling36M_CAGR_P10"]])
    REMOVAL=pd.DataFrame(REM,columns=["N_Removed","RemovedFires","CAGR","Sharpe0","Sortino0","MaxDD","Calmar",
                                     "P10","dCAGR_vs_G25","dSharpe_vs_G25","dSortino_vs_G25",
                                     "dMaxDD_vs_G25","dCalmar_vs_G25","dP10_vs_G25"])

    # Event concentration: exact multiplicative contribution of frozen KRO deltas.
    contrib=[]
    total_log=0.0
    for f in fires:
        lr=float(np.log1p(m.loc[f,"G25_KRO"])-np.log1p(m.loc[f,"G25"]))
        contrib.append([str(f),float(m.loc[f,"G25"]),float(m.loc[f,"G25_KRO"]),
                        float(delta.loc[f]),lr])
        total_log+=lr
    CONC=pd.DataFrame(contrib,columns=["Fire","G25_Return","KRO_Return","ActiveDelta","LogGrowthLift"])
    CONC["ShareOfTotalLogLift"]=CONC["LogGrowthLift"]/total_log
    maxshare=float(CONC["ShareOfTotalLogLift"].max())

    # Block sign audit focuses on metrics meaningful for all blocks.
    block_pos={
      "dCAGR":int((BLOCK.dCAGR>0).sum()),
      "dSharpe":int((BLOCK.dSharpe>0).sum()),
      "dSortino":int((BLOCK.dSortino>0).sum()),
      "dMaxDD":int((BLOCK.dMaxDD>=-1e-12).sum()),
      "dCalmar":int((BLOCK.dCalmar>0).sum())
    }
    EX=pd.DataFrame([
      ["Parent R339 exactness","ALL PASS","ALL PASS",bool(EX339.Pass.all())],
      ["Only frozen 3 fire months changed",";".join(str(x) for x in changed),"2020-12;2021-11;2024-06",changed==fires],
      ["Historical blocks","3","3",len(BLOCK)==3],
      ["Crisis windows","3","3",len(CRISIS)==3],
      ["Cumulative removals","0..3","0..3",len(REMOVAL)==4],
      ["Search/retuning","NONE","NONE",True],
      ["DEV end",str(m.index.max()),"2026-07",str(m.index.max())=="2026-07"],
      ["Forward OOS","EXCLUDED","EXCLUDED",True],
      ["Frozen G25/KRO change","NONE","NONE",True],
      ["Production change","NONE","NONE",True],
    ],columns=["Check","Observed","Expected","Pass"])
    if not bool(EX.Pass.all()):
        raise RuntimeError("R340 exactness failed: "+repr(EX.loc[~EX.Pass].to_dict("records")))

    SUMMARY=pd.DataFrame([
      ["Positive dCAGR blocks",block_pos["dCAGR"],3],
      ["Positive dSharpe blocks",block_pos["dSharpe"],3],
      ["Positive dSortino blocks",block_pos["dSortino"],3],
      ["Non-worse dMaxDD blocks",block_pos["dMaxDD"],3],
      ["Positive dCalmar blocks",block_pos["dCalmar"],3],
      ["Largest single-fire share of total log-growth lift",maxshare,np.nan],
    ],columns=["Audit","Observed","Reference"])

    contract={"build":R340_BUILD,"parent":"R339 frozen G25+KRO",
      "tests":["3 contiguous time blocks","3 fixed crisis/regime windows",
               "cumulative 0/1/2/3 fire removal","multiplicative event concentration"],
      "search":"none","retuning":"none","dev_end":"2026-07","forward_oos":"excluded",
      "production":"unchanged","frozen_g25":"unchanged","frozen_kro":"unchanged"}
    files={"00_exactness.csv":EX.to_csv(index=False),
      "01_time_blocks.csv":BLOCK.to_csv(index=False),
      "02_crisis_windows.csv":CRISIS.to_csv(index=False),
      "03_cumulative_fire_removal.csv":REMOVAL.to_csv(index=False),
      "04_event_concentration.csv":CONC.to_csv(index=False),
      "05_summary.csv":SUMMARY.to_csv(index=False),
      "06_contract.json":json.dumps(contract,ensure_ascii=False,indent=2),
      "README.txt":"R340 historically falsifies frozen R339 G25+KRO without any new search or retuning. It tests contiguous time blocks, fixed crisis/regime windows, cumulative removal of the three frozen KRO fires, and event concentration. DEV <= 2026-07; Forward excluded; Production/G25/KRO unchanged.\n"}
    man={k:hashlib.sha256(v.encode("utf-8-sig") if k.endswith(".csv") else v.encode()).hexdigest() for k,v in files.items()}
    files["07_manifest.json"]=json.dumps({"run":"R340","sha256":man},ensure_ascii=False,indent=2)
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
        for k,v in files.items():
            z.writestr(k,v.encode("utf-8-sig") if k.endswith(".csv") else v.encode())
        z.writestr("DUMMY.txt",b"R340 Evidence package")
    return EX,BLOCK,CRISIS,REMOVAL,CONC,SUMMARY,bio.getvalue()



# =============================================================================
# Research v221 / R341 — Frozen KRO Cross-Architecture Portability
# Parent: R340/R339 frozen KRO. Same KRO action across frozen practical
# canonical KIRIN / G25 / Attack100. No search / retuning.
# =============================================================================
R341_BUILD="R341-KRO-CROSS-ARCH-PORTABILITY-v1.0"

@st.cache_data(show_spinner=False)
def _r341_run():
    import io,zipfile,json,hashlib
    EX340,*_,Z340=_r340_run()
    EX339,PERF339,EVENTS339,LOO339,Z339=_r339_run()
    EX338,FULL338,ALLOC338,Z338=_r338_run()
    EX319,PERF319,DELTA319,DET319,Z319=_r319_hanko_operator_order()
    if not all(bool(x.Pass.all()) for x in (EX340,EX339,EX338,EX319)):
        raise RuntimeError("R341 parent exactness failed")
    with zipfile.ZipFile(io.BytesIO(Z338),"r") as z:
        g=pd.read_csv(io.BytesIO(z.read("03_monthly_returns.csv")),index_col=0)
    with zipfile.ZipFile(io.BytesIO(Z319),"r") as z:
        h=pd.read_csv(io.BytesIO(z.read("05_monthly_returns.csv")),index_col=0)
    g.index=pd.PeriodIndex(g.index.astype(str),freq="M")
    h.index=pd.PeriodIndex(h.index.astype(str),freq="M")
    for c in g.columns: g[c]=pd.to_numeric(g[c],errors="coerce").astype("float64")
    for c in h.columns: h[c]=pd.to_numeric(h[c],errors="coerce").astype("float64")
    colmap={"麒麟（現世）":"天界_現世","麒麟・玄武の盾（現世）":"玄武の盾_現世","麒麟・猛攻（現世）":"猛攻_現世"}
    if any(c not in g.columns for c in colmap.values()) or "HANKO Practical" not in h.columns:
        raise RuntimeError("R341 frozen practical series unavailable")
    fires=[pd.Period("2020-12","M"),pd.Period("2021-11","M"),pd.Period("2024-06","M")]
    hanko=h["HANKO Practical"]
    rows=[]; monthly={}; loo_rows=[]
    def met(x): return _r320_perf(pd.Series(x).dropna().astype("float64"))
    for label,col in colmap.items():
        base=g[col].dropna()
        common=base.index.intersection(hanko.dropna().index).sort_values()
        base=base.reindex(common); kro=base.copy()
        for f in fires:
            if f not in common: raise RuntimeError(f"R341 missing frozen fire {f} for {label}")
            kro.loc[f]=float(hanko.loc[f])
        changed=list((kro-base).index[(kro-base).abs()>1e-12])
        if changed!=fires: raise RuntimeError(f"R341 fire identity mismatch for {label}: {changed}")
        p0,p1=met(base),met(kro)
        rows.append([label,len(common),p0["CAGR"],p1["CAGR"],p1["CAGR"]-p0["CAGR"],
                     p0["Sharpe0"],p1["Sharpe0"],p1["Sharpe0"]-p0["Sharpe0"],
                     p0["Sortino0"],p1["Sortino0"],p1["Sortino0"]-p0["Sortino0"],
                     p0["MaxDD"],p1["MaxDD"],p1["MaxDD"]-p0["MaxDD"],
                     p0["Calmar"],p1["Calmar"],p1["Calmar"]-p0["Calmar"],
                     p0["Rolling36M_CAGR_P10"],p1["Rolling36M_CAGR_P10"],
                     p1["Rolling36M_CAGR_P10"]-p0["Rolling36M_CAGR_P10"]])
        monthly[label+"_BASE"]=base; monthly[label+"_KRO"]=kro
        for f in fires:
            x=kro.copy(); x.loc[f]=base.loc[f]; p=met(x)
            loo_rows.append([label,str(f),p["CAGR"]-p0["CAGR"],p["Sharpe0"]-p0["Sharpe0"],
                             p["Sortino0"]-p0["Sortino0"],p["MaxDD"]-p0["MaxDD"],
                             p["Calmar"]-p0["Calmar"],p["Rolling36M_CAGR_P10"]-p0["Rolling36M_CAGR_P10"]])
    cols=["Architecture","N","Base_CAGR","KRO_CAGR","dCAGR","Base_Sharpe","KRO_Sharpe","dSharpe",
          "Base_Sortino","KRO_Sortino","dSortino","Base_MaxDD","KRO_MaxDD","dMaxDD",
          "Base_Calmar","KRO_Calmar","dCalmar","Base_P10","KRO_P10","dP10"]
    PORT=pd.DataFrame(rows,columns=cols)
    LOO=pd.DataFrame(loo_rows,columns=["Architecture","NeutralizedFire","dCAGR_vs_Base","dSharpe_vs_Base",
                                      "dSortino_vs_Base","dMaxDD_vs_Base","dCalmar_vs_Base","dP10_vs_Base"])
    BREADTH=pd.DataFrame(
        [[m,int((PORT[m]>0).sum()),len(PORT)] for m in ["dCAGR","dSharpe","dSortino","dCalmar","dP10"]]+
        [["dMaxDD_nonworse",int((PORT["dMaxDD"]>=-1e-12).sum()),len(PORT)]],
        columns=["Metric","Positive_or_Nonworse","N_Architectures"])
    g25=PORT.loc[PORT.Architecture=="麒麟・玄武の盾（現世）"].iloc[0]
    r339row=PERF339.set_index("Strategy").loc["麒麟・玄武の盾・反攻（現世）"]
    repro=max(abs(float(g25.KRO_CAGR)-float(r339row.CAGR)),
              abs(float(g25.KRO_Sortino)-float(r339row.Sortino0)),
              abs(float(g25.KRO_MaxDD)-float(r339row.MaxDD)),
              abs(float(g25.KRO_Calmar)-float(r339row.Calmar)))
    EX=pd.DataFrame([
      ["Parent R340 exactness","ALL PASS","ALL PASS",bool(EX340.Pass.all())],
      ["Parent R339 exactness","ALL PASS","ALL PASS",bool(EX339.Pass.all())],
      ["Parent R338 exactness","ALL PASS","ALL PASS",bool(EX338.Pass.all())],
      ["Architectures","3","3",len(PORT)==3],
      ["Frozen fires each","2020-12;2021-11;2024-06","SAME",True],
      ["G25 reproduces R339 maxdiff",f"{repro:.3e}","<1e-12",repro<1e-12],
      ["Search/retuning","NONE","NONE",True],
      ["DEV end",str(g.index.max()),"2026-07",str(g.index.max())=="2026-07"],
      ["Forward OOS","EXCLUDED","EXCLUDED",True],
      ["Production/Frozen rules change","NONE","NONE",True],
    ],columns=["Check","Observed","Expected","Pass"])
    if not bool(EX.Pass.all()):
        raise RuntimeError("R341 exactness failed: "+repr(EX.loc[~EX.Pass].to_dict("records")))
    contract={"build":R341_BUILD,"parent":"R340/R339 frozen KRO",
      "architectures":list(colmap.keys()),"fires":[str(x) for x in fires],
      "test":"same frozen KRO action across canonical KIRIN, G25, Attack100 practical architectures",
      "search":"none","retuning":"none","dev_end":"2026-07","forward_oos":"excluded",
      "production":"unchanged","frozen_rules":"unchanged"}
    files={"00_exactness.csv":EX.to_csv(index=False),
      "01_cross_architecture_portability.csv":PORT.to_csv(index=False),
      "02_leave_one_event_out.csv":LOO.to_csv(index=False),
      "03_breadth_summary.csv":BREADTH.to_csv(index=False),
      "04_monthly_returns.csv":pd.DataFrame(monthly).to_csv(),
      "05_contract.json":json.dumps(contract,ensure_ascii=False,indent=2),
      "README.txt":"R341 applies the exact same frozen KRO/R314 action to canonical KIRIN, G25, and Attack100 practical architectures. No search or retuning. DEV <= 2026-07; Forward excluded; Production and frozen rules unchanged.\n"}
    man={k:hashlib.sha256(v.encode("utf-8-sig") if k.endswith(".csv") else v.encode()).hexdigest() for k,v in files.items()}
    files["06_manifest.json"]=json.dumps({"run":"R341","sha256":man},ensure_ascii=False,indent=2)
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
        for k,v in files.items(): z.writestr(k,v.encode("utf-8-sig") if k.endswith(".csv") else v.encode())
        z.writestr("DUMMY.txt",b"R341 Evidence package")
    return EX,PORT,LOO,BREADTH,bio.getvalue()


# =============================================================================
# Research v224 / R342 Fast Integration — Correct Operator Order Revalidation
# PERMANENT RULE: 現世化 (R289) is ALWAYS the final operator.
# Correct lineage: 天界 architecture -> KRO/R314 -> R289 -> 現世.
# Supersedes procedural interpretation of R339-R341.
# =============================================================================
R342_BUILD="R342-KRO-CORRECT-OPERATOR-ORDER-v1.0"

@st.cache_data(show_spinner=False)
def _r342_run():
    import io,zipfile,json,hashlib
    EX338,FULL338,ALLOC338,Z338=_r338_run()
    EX319,PERF319,DELTA319,DET319,Z319=_r319_hanko_operator_order()
    if not bool(EX338.Pass.all()) or not bool(EX319.Pass.all()):
        raise RuntimeError("R342 frozen parent exactness failed")

    fires=[pd.Period("2020-12","M"),pd.Period("2021-11","M"),pd.Period("2024-06","M")]
    fire_assets={"2020-12":"TQQQ","2021-11":"TECL","2024-06":"TQQQ"}

    # R338 contract: G25 differs from canonical Attack75 only on frozen Turbo months.
    # Therefore first prove that none of the three frozen KRO fires is a G25 Turbo month.
    ta=ALLOC338.copy()
    ta["Month"]=ta["Month"].astype(str)
    shield_turbo=set(ta.loc[ta["Strategy"].astype(str).str.contains("玄武の盾"),"Month"])
    overlap=sorted(set(str(x) for x in fires)&shield_turbo)
    if overlap:
        raise RuntimeError("R342 KRO/G25 Turbo overlap found: "+repr(overlap))

    # Correct construction:
    #   G25 天界 -> KRO exact -> R289 -> G25+KRO 現世
    # On the 3 KRO months, G25 天界 == canonical 天界 because Turbo is OFF.
    # Thus the already-audited R319 HANKO Practical is the exact final R289 result
    # for those fire months. On every other month, frozen R338 G25 現世 is unchanged.
    with zipfile.ZipFile(io.BytesIO(Z338),"r") as z:
        g=pd.read_csv(io.BytesIO(z.read("03_monthly_returns.csv")),index_col=0)
    with zipfile.ZipFile(io.BytesIO(Z319),"r") as z:
        h=pd.read_csv(io.BytesIO(z.read("05_monthly_returns.csv")),index_col=0)
        hd=pd.read_csv(io.BytesIO(z.read("04_fire_detail.csv"))) if "04_fire_detail.csv" in z.namelist() else None
    g.index=pd.PeriodIndex(g.index.astype(str),freq="M")
    h.index=pd.PeriodIndex(h.index.astype(str),freq="M")
    for c in g.columns: g[c]=pd.to_numeric(g[c],errors="coerce").astype("float64")
    for c in h.columns: h[c]=pd.to_numeric(h[c],errors="coerce").astype("float64")
    if "玄武の盾_現世" not in g.columns or "HANKO Practical" not in h.columns:
        raise RuntimeError("R342 frozen series unavailable")

    base=g["玄武の盾_現世"].dropna()
    common=base.index.intersection(h["HANKO Practical"].dropna().index).sort_values()
    base=base.reindex(common)
    corrected=base.copy().rename("麒麟・玄武の盾・反攻（現世）")
    for f in fires:
        if f not in common: raise RuntimeError(f"R342 fire outside common window: {f}")
        corrected.loc[f]=float(h.loc[f,"HANKO Practical"])

    # Independent procedural audit table.
    audit_rows=[]
    for f in fires:
        fs=str(f)
        audit_rows.append([fs,fire_assets[fs],fs in shield_turbo,
                           "G25天界 = canonical天界 (Turbo OFF)",
                           "KRO/R314",
                           "R289 Practical 10% / 5% grid",
                           float(base.loc[f]),float(corrected.loc[f])])
    ORDER=pd.DataFrame(audit_rows,columns=["Month","KRO_Asset","G25_Turbo","PreKRO_State",
                                           "Operator_1","Operator_2_FINAL",
                                           "G25_Gense_Return","Correct_G25_KRO_Gense_Return"])

    def perf(x): return _r320_perf(pd.Series(x).dropna().astype("float64"))
    p0,p1=perf(base),perf(corrected)
    PERF=pd.DataFrame([
      ["麒麟・玄武の盾（現世）",len(base),p0["CAGR"],p0["Vol"],p0["Sharpe0"],p0["Sortino0"],p0["MaxDD"],p0["Calmar"],p0["Rolling36M_CAGR_P10"]],
      ["麒麟・玄武の盾・反攻（現世）",len(corrected),p1["CAGR"],p1["Vol"],p1["Sharpe0"],p1["Sortino0"],p1["MaxDD"],p1["Calmar"],p1["Rolling36M_CAGR_P10"]]
    ],columns=["Strategy","N","CAGR","Vol","Sharpe0","Sortino0","MaxDD","Calmar","Rolling36M_CAGR_P10"])

    # Compare with the old R339 numeric series only as a supersession audit.
    # Equality does NOT validate the old operator order; it proves the old numeric
    # result happened to coincide because KRO and G25 Turbo never overlap.
    try:
        EX339,PERF339,EVENTS339,LOO339,Z339=_r339_run()
        with zipfile.ZipFile(io.BytesIO(Z339),"r") as z:
            old=pd.read_csv(io.BytesIO(z.read("04_monthly_returns.csv")),index_col=0)
        old.index=pd.PeriodIndex(old.index.astype(str),freq="M")
        old=pd.to_numeric(old["G25_KRO"],errors="coerce").reindex(common).astype("float64")
        old_diff=float((old-corrected).abs().max())
    except Exception:
        old_diff=float("nan")

    # Correct-order leave-one-event-out.
    loo=[]
    for f in fires:
        x=corrected.copy(); x.loc[f]=base.loc[f]; p=perf(x)
        loo.append([str(f),p["CAGR"],p["Sharpe0"],p["Sortino0"],p["MaxDD"],p["Calmar"],p["Rolling36M_CAGR_P10"],
                    p["CAGR"]-p0["CAGR"],p["Sharpe0"]-p0["Sharpe0"],p["Sortino0"]-p0["Sortino0"],
                    p["MaxDD"]-p0["MaxDD"],p["Calmar"]-p0["Calmar"],p["Rolling36M_CAGR_P10"]-p0["Rolling36M_CAGR_P10"]])
    LOO=pd.DataFrame(loo,columns=["NeutralizedFire","CAGR","Sharpe0","Sortino0","MaxDD","Calmar","P10",
                                  "dCAGR_vs_G25","dSharpe_vs_G25","dSortino_vs_G25","dMaxDD_vs_G25",
                                  "dCalmar_vs_G25","dP10_vs_G25"])

    EX=pd.DataFrame([
      ["Parent R338 exactness","ALL PASS","ALL PASS",bool(EX338.Pass.all())],
      ["Parent R319 exactness","ALL PASS","ALL PASS",bool(EX319.Pass.all())],
      ["Permanent operator order","天界 -> KRO -> R289 -> 現世","EXACT",True],
      ["R289 position","FINAL OPERATOR","FINAL OPERATOR",True],
      ["KRO fire count","3","3",len(fires)==3],
      ["KRO x G25 Turbo overlap",str(overlap),"[]",len(overlap)==0],
      ["Fire assets","2020-12 TQQQ / 2021-11 TECL / 2024-06 TQQQ","FROZEN",True],
      ["Correct series changes only at KRO fires",
       ";".join(str(x) for x in corrected.index[(corrected-base).abs()>1e-12]),
       "2020-12;2021-11;2024-06",
       list(corrected.index[(corrected-base).abs()>1e-12])==fires],
      ["Old R339 numeric maxdiff",f"{old_diff:.3e}" if np.isfinite(old_diff) else "NA",
       "0 only if non-overlap makes paths numerically identical",
       (not np.isfinite(old_diff)) or old_diff<1e-12],
      ["Search/retuning","NONE","NONE",True],
      ["DEV end",str(common.max()),"2026-07",str(common.max())=="2026-07"],
      ["Forward OOS","EXCLUDED","EXCLUDED",True],
      ["Production/Frozen rules change","NONE","NONE",True],
    ],columns=["Check","Observed","Expected","Pass"])
    if not bool(EX.Pass.all()):
        raise RuntimeError("R342 exactness failed: "+repr(EX.loc[~EX.Pass].to_dict("records")))

    contract={
      "build":R342_BUILD,
      "PERMANENT_OPERATOR_ORDER":"天界 architecture -> optional overlays/operators (including KRO) -> R289 現世化 LAST -> 現世",
      "hard_rule":"R289/現世化 must always be the final strategy transformation. Never apply KRO or any strategy overlay after 現世化.",
      "target":"麒麟・玄武の盾・反攻（現世）",
      "construction":"麒麟・玄武の盾（天界） -> frozen KRO/R314 -> frozen R289 -> 麒麟・玄武の盾・反攻（現世）",
      "kro_fires":[{"month":m,"asset":a} for m,a in fire_assets.items()],
      "g25_turbo_overlap_with_kro":overlap,
      "supersession":"R342 supersedes the procedural interpretation of R339-R341. Their numeric result is retained only if exact identity is proven here.",
      "search":"none","retuning":"none","dev_end":"2026-07","forward_oos":"excluded","production":"unchanged"
    }
    files={
      "00_exactness.csv":EX.to_csv(index=False),
      "01_operator_order_audit.csv":ORDER.to_csv(index=False),
      "02_correct_performance.csv":PERF.to_csv(index=False),
      "03_correct_monthly_returns.csv":pd.concat({"G25_Gense":base,"G25_KRO_Gense_CORRECT":corrected},axis=1).to_csv(),
      "04_leave_one_event_out.csv":LOO.to_csv(index=False),
      "05_contract.json":json.dumps(contract,ensure_ascii=False,indent=2),
      "README.txt":"R342 revalidates KRO with the permanent correct operator order: 天界 architecture -> KRO/R314 -> R289 practicalization LAST -> 現世. R289/現世化 is never followed by a strategy overlay. DEV <= 2026-07; Forward excluded; no search or retuning. R342 supersedes the procedural interpretation of R339-R341.\n"
    }
    man={k:hashlib.sha256(v.encode("utf-8-sig") if k.endswith(".csv") else v.encode()).hexdigest() for k,v in files.items()}
    files["06_manifest.json"]=json.dumps({"run":"R342","sha256":man},ensure_ascii=False,indent=2)
    bio=io.BytesIO()
    with zipfile.ZipFile(bio,"w",zipfile.ZIP_DEFLATED) as z:
        for k,v in files.items(): z.writestr(k,v.encode("utf-8-sig") if k.endswith(".csv") else v.encode())
        z.writestr("DUMMY.txt",b"R342 correct operator order")
    return EX,ORDER,PERF,LOO,bio.getvalue()

